window.QUIZ_DATA["ite"] = [{"id":1,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":1,"chooseType":"Choose 1 answer","question":"An example of a public dataset at risk of an algorithmic privacy violation is the","options":{"A":"Google Maps satellite view dataset","B":"Google search view dataset","C":"Stanford hospital dataset","D":"Fidelity Bank lending dataset"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Ví dụ nào về tập dữ liệu công khai có nguy cơ vi phạm quyền riêng tư thuật toán?","optionsVi":{"A":"Tập dữ liệu hình ảnh vệ tinh của Google Maps","B":"Tập dữ liệu chế độ xem tìm kiếm Google","C":"Tập dữ liệu bệnh viện Stanford","D":"Tập dữ liệu cho vay của ngân hàng Fidelity"},"answerDisplay":"A. Google Maps satellite view dataset","concept":"• Tập dữ liệu hình ảnh vệ tinh độ phân giải cao công khai (như Google Maps Satellite) có nguy cơ làm lộ hình ảnh tài sản cá nhân, địa chỉ nhà riêng và hành vi di chuyển.","whyCorrect":"• Ảnh vệ tinh công khai có thể bị khai thác bởi thuật toán thị giác máy tính để phân tích và theo dõi tài sản cá nhân không có sự đồng ý.","whyWrong":{"B":"• Dữ liệu tìm kiếm Google được xử lý tổng hợp, không hiển thị trực tiếp hình ảnh vị trí địa lý thực tế.","C":"• Dữ liệu y tế Stanford là dữ liệu nghiên cứu đã qua quy trình giải định danh nghiêm ngặt.","D":"• Dữ liệu tín dụng ngân hàng Fidelity là dữ liệu tài chính bảo mật nội bộ, không phải tập dữ liệu công khai."}}},{"id":2,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":2,"chooseType":"Choose 1 answer","question":"During cross-validation, which of the following dataset splits is used to tune the performance of a model?","options":{"A":"Training set","B":"Test set","C":"Validation test","D":"Unit test"},"answer":"C","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Trong quá trình kiểm thử chéo (Cross-validation), tập dữ liệu nào được sử dụng để tinh chỉnh hiệu suất của mô hình?","optionsVi":{"A":"Tập huấn luyện (Training set)","B":"Tập kiểm thử (Test set)","C":"Tập xác thực (Validation set)","D":"Tập kiểm thử đơn vị (Unit test)"},"answerDisplay":"C. Validation set","concept":"• Tập xác thực (Validation set) được sử dụng trong quá trình huấn luyện để tinh chỉnh siêu tham số (Hyperparameters) và đánh giá hiện tượng Overfitting.","whyCorrect":"• Tập xác thực giúp kỹ sư chọn mô hình có hiệu suất tối ưu trước khi đánh giá cuối cùng trên tập Test.","whyWrong":{"A":"• Tập Training được dùng để mô hình học trọng số (weights), không dùng để tinh chỉnh siêu tham số.","B":"• Tập Test chỉ dùng để đánh giá độc lập hiệu suất cuối cùng của mô hình đã chốt.","D":"• Unit test là quy trình kiểm thử phần mềm, không phải phân tập dữ liệu machine learning."}}},{"id":3,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":3,"chooseType":"Choose 2 answers","question":"Which of the following are potential ethical benefits of conducting pilot testing prior to the release of emerging technologies? (Select two.)","options":{"A":"It certifies that a product's developers are legally accountable.","B":"It minimizes the impact of any ethical issues which may emerge.","C":"It demonstrates that the system is functional as early as possible in order to satisfy senior management and investor stakeholders.","D":"It reveals any gaps in accountability or auditability."},"answer":"A, D","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Phương pháp nào sau đây giúp nâng cao tính giải thích được (Explainability) của mô hình học sâu? (Select two)","optionsVi":{"A":"Sử dụng các kỹ thuật giải thích độc lập mô hình như LIME hoặc SHAP","B":"Tăng số lượng lớp ẩn trong mạng nơ-ron","C":"Mã hóa toàn bộ tập dữ liệu đầu vào","D":"Trực quan hóa trọng số và đặc trưng lớp trung gian (Feature visualization)"},"answerDisplay":"A. Using model-agnostic explanation techniques like LIME or SHAP & D. Feature visualization","concept":"• Giải thích mô hình hộp đen (Black Box) cần các công cụ hỗ trợ như LIME/SHAP và phương pháp trực quan hóa bản đồ nhiệt/đặc trưng trung gian.","whyCorrect":"• LIME/SHAP xấp xỉ hành vi local của mô hình, còn Feature visualization giúp mở hộp đen hiển thị lớp nhận diện.","whyWrong":{"B":"• Tăng lớp ẩn làm mạng nơ-ron phức tạp hơn và khó giải thích hơn.","C":"• Mã hóa dữ liệu là bảo mật mã hóa, không làm mô hình dễ giải thích hơn."}}},{"id":4,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":4,"chooseType":"Choose 1 answer","question":"Why is it important to consider Goodhart's law?","options":{"A":"A model might optimize one metric at the expense of others.","B":"A model might be ineffective in its application domain.","C":"A model might change its task from classification to regression, or vice versa.","D":"A model very famous and can be apply to all domain."},"answer":"C","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Trách nhiệm chính của nhà quản trị dữ liệu (Data Governance Officer) là gì?","optionsVi":{"A":"Trực tiếp viết mã nguồn cho mô hình deep learning","B":"Mua sắm thiết bị phần cứng máy chủ","C":"Thiết lập quy trình, chính sách và tiêu chuẩn chất lượng/an toàn dữ liệu","D":"Quản lý doanh số bán hàng của công ty"},"answerDisplay":"C. Establishing data quality, security policies, and governance standards","concept":"• Quản trị dữ liệu (Data Governance) tập trung vào khía cạnh chính sách, tiêu chuẩn chất lượng, tuân thủ pháp lý và an toàn dữ liệu.","whyCorrect":"• Thiết lập quy chuẩn giúp dữ liệu toàn tổ chức luôn chuẩn xác, bảo mật và tuân thủ nguyên tắc đạo đức.","whyWrong":{"A":"• Viết mã mô hình thuộc vai trò của Data Scientist / ML Engineer.","B":"• Mua sắm máy chủ thuộc vai trò của IT Operations / DevOps.","D":"• Quản lý doanh số thuộc về bộ phận Kinh doanh (Sales/Marketing)."}}},{"id":5,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":5,"chooseType":"Choose 2 answers","question":"Which of the following elements should be communicated with end users when negotiating ethical access to a user's data? (Select two.)","options":{"A":"The monetary value of that data","B":"An offer of money or other incentives to relinquish user's rights","C":"The intention behind a certain activity or request","D":"A request for consent to perform an action"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Vấn đề đạo đức chính khi áp dụng chấm điểm tín dụng tự động bằng AI là gì?","optionsVi":{"A":"Làm tăng chi phí duyệt hồ sơ","B":"Nguy cơ thiên vị và phân biệt đối xử dựa trên thuộc tính nhạy cảm gián tiếp","C":"Tốc độ phê duyệt quá chậm","D":"Tăng dung lượng lưu trữ cơ sở dữ liệu"},"answerDisplay":"B. Risk of bias and indirect discrimination based on sensitive attributes","concept":"• AI tín dụng có thể sử dụng các thuộc tính thay thế (Proxy Attributes như mã zip, học vấn) dẫn tới phân biệt đối xử với nhóm yếu thế.","whyCorrect":"• Thiên vị thuật toán khiến người thuộc nhóm yếu thế bị từ chối vay bất công, vi phạm tính công bằng đạo đức.","whyWrong":{"A":"• Chấm điểm tự động làm giảm chi phí chứ không tăng.","C":"• Tốc độ phê duyệt của AI nhanh hơn con người gấp nhiều lần.","D":"• Dung lượng cơ sở dữ liệu là vấn đề kỹ thuật hạ tầng."}}},{"id":6,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":6,"chooseType":"Choose 1 answer","question":"What are the limitations of training and testing an AI model in a specific context?","options":{"A":"Models may perform poorly when applied to different contexts","B":"Models require less computational power in limited contexts","C":"Models reduce training data requirements when context is specified","D":"Models automatically improve when tested in the same context"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Khái niệm 'Data Provenance' (Nguồn gốc dữ liệu) đề cập đến điều gì?","optionsVi":{"A":"Tốc độ tải dữ liệu từ máy chủ","B":"Lịch sử ghi lại nguồn gốc, quá trình di chuyển và các thay đổi của dữ liệu theo thời gian","C":"Dung lượng tính bằng Gigabyte của tập dữ liệu","D":"Thuật toán nén dữ liệu"},"answerDisplay":"B. Documentation of data origin, movement, and transformations over time","concept":"• Data Provenance theo dõi vết chuỗi dữ liệu (Data Lineage) từ lúc thu thập nguyên bản đến khi được xử lý và đưa vào mô hình.","whyCorrect":"• Theo dõi nguồn gốc giúp kiểm toán tính trung thực, tính minh bạch và độ tin cậy của tập dữ liệu huấn luyện.","whyWrong":{"A":"• Tốc độ tải thuộc về băng thông mạng.","C":"• Dung lượng là kích thước tệp tin.","D":"• Thuật toán nén là kỹ thuật nén nạp dữ liệu."}}},{"id":7,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":7,"chooseType":"Choose 1 answer","question":"What does the acronym RACI stand for?","options":{"A":"Relatable, Agreeable, Commendable, Irascible","B":"Responsible, Accessible, Consulted, Improvised","C":"Redesignable, Accessible, Collected, Informative?","D":"Responsible, Accountable, Consulted, Informed"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Tác động nào sau đây là hệ quả của thiên vị xác nhận (Confirmation Bias) trong phân tích dữ liệu?","optionsVi":{"A":"Chỉ chọn lọc dữ liệu phù hợp với giả thuyết ban đầu và bỏ qua dữ liệu mâu thuẫn","B":"Tăng độ chính xác của mô hình học máy","C":"Tự động phát hiện các lỗi sai trong tập dữ liệu","D":"Giảm độ phức tạp tính toán của thuật toán"},"answerDisplay":"A. Selective data collection that favors existing hypotheses while ignoring contradictory evidence","concept":"• Confirmation Bias khiến nhà phân tích vô thức lựa chọn thông tin củng cố niềm tin cá nhân và lờ đi dữ liệu thực tế mâu thuẫn.","whyCorrect":"• Việc thu thập dữ liệu thiên vị dẫn tới các kết luận nghiên cứu lệch lạc và không phản ánh đúng thực tế khách quan.","whyWrong":{"B":"• Thiên vị làm giảm độ chính xác và tính khách quan của kết quả.","C":"• Confirmation bias không giúp phát hiện lỗi mà làm bỏ qua lỗi.","D":"• Độ phức tạp tính toán phụ thuộc vào số lượng phép toán của thuật toán."}}},{"id":8,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":8,"chooseType":"Choose 1 answer","question":"What are the essential steps involved in creating personas for user-centric marketing?","options":{"A":"Define target audience, conduct research, build fictional personas based on insights, validate personas","B":"Identify privacy risks, analyze data, implement policies, conduct training","C":"Conduct surveys, run focus groups, implement findings, analyze results","D":"Develop marketing strategies, execute campaigns, evaluate outcomes, adjust tactics"},"answer":"C","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Trong khung quản trị rủi ro AI của NIST (NIST AI RMF), 4 chức năng cốt lõi là gì?","optionsVi":{"A":"Plan, Do, Check, Act","B":"Input, Process, Output, Feedback","C":"Govern, Map, Measure, Manage","D":"Identify, Protect, Detect, Respond"},"answerDisplay":"C. Govern, Map, Measure, Manage","concept":"• Khung quản trị NIST AI RMF được cấu trúc xung quanh 4 chức năng chính: Quản trị (Govern), Ánh xạ rủi ro (Map), Đo lường (Measure) và Quản lý (Manage).","whyCorrect":"• Bốn chức năng này cung cấp phương pháp toàn diện để quản lý rủi ro AI trong suốt chu kỳ sống.","whyWrong":{"A":"• Plan-Do-Check-Act là chu trình chất lượng ISO 9001 (PDCA).","B":"• Input-Process-Output là mô hình xử lý hệ thống thông tin.","D":"• Identify-Protect-Detect-Respond là khung an ninh mạng NIST Cybersecurity Framework (NIST CSF)."}}},{"id":9,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":9,"chooseType":"Choose 1 answer","question":"Which of the following is a recommended security practice for machine learning datasets?","options":{"A":"Ensure your team is full of different perspectives","B":"Enact a sound data governance structure","C":"Perform threat modeling with beneficial algorithms","D":"Create a chain of command"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Mục đích của việc ẩn danh hóa dữ liệu (Data Anonymization) là gì?","optionsVi":{"A":"Tăng kích thước tệp dữ liệu để phân tích sâu hơn","B":"Loại bỏ hoặc làm mờ thông tin cá nhân để ngăn chặn việc nhận dạng danh tính người dùng","C":"Mã hóa dữ liệu để chỉ người có mật khẩu mới đọc được","D":"Tự động xóa các bản ghi cũ"},"answerDisplay":"B. Removing or obscuring personal identifiers to prevent individual identification","concept":"• Anonymization biến đổi dữ liệu cá nhân (PII) thành dữ liệu vô danh sao cho không thể khôi phục lại danh tính.","whyCorrect":"• Loại bỏ mối liên kết giữa dữ liệu và cá nhân giúp chia sẻ dữ liệu nghiên cứu an toàn mà không xâm phạm quyền riêng tư.","whyWrong":{"A":"• Ẩn danh hóa không làm tăng kích thước tệp.","C":"• Mã hóa (Encryption) là biện pháp bảo mật có thể giải mã, khác với ẩn danh hóa vĩnh viễn.","D":"• Xóa bản ghi là hủy dữ liệu (Data Retention policy)."}}},{"id":10,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":10,"chooseType":"Choose 1 answer","question":"You're training a model to classify whether or not a bridge is likely to collapse given several factors. You have a dataset of thousands of existing bridges and their attributes, where each bridge is labeled as having collapsed or not collapsed. Only a handful of bridges in the dataset are labeled as having collapsed—the rest are labeled as not collapsed. Given your goal of minimizing bridge collapse and the severe harm it can cause, which of the following metrics would be most useful for evaluating the model?","options":{"A":"Accuracy","B":"Confusion matrix","C":"Precision","D":"Recall"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Nguyên tắc 'Privacy by Design' (Riêng tư theo thiết kế) có ý nghĩa gì đối với các kỹ sư phần mềm?","optionsVi":{"A":"Tích hợp các biện pháp bảo vệ quyền riêng tư ngay từ khâu kiến trúc và thiết kế ban đầu","B":"Chỉ bổ sung tính năng riêng tư sau khi khách hàng phàn nàn","C":"Ủy quyền toàn bộ trách nhiệm bảo mật cho người dùng","D":"Khóa tất cả các tính năng của ứng dụng"},"answerDisplay":"A. Integrating privacy protections into the core system architecture from the initial design phase","concept":"• Privacy by Design coi quyền riêng tư là thành phần thiết yếu được chủ động xây dựng ngay từ đầu, thay vì vá lỗi thụ động.","whyCorrect":"• Tích hợp từ đầu giúp ngăn ngừa nguy cơ rò rỉ dữ liệu hiệu quả và tiết kiệm chi phí sửa chữa.","whyWrong":{"B":"• Bổ sung sau khi có phàn nàn là cách làm thụ động bị cấm.","C":"• Đổ trách nhiệm cho người dùng là vi phạm đạo đức thiết kế.","D":"• Khóa tính năng làm sản phẩm không thể sử dụng được."}}},{"id":11,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":11,"chooseType":"Choose 1 answer","question":"Which of the following describes extrajudicial judgment?","options":{"A":"A ruling or scoring made outside of a court.","B":"Transferring defendants from one jurisdiction to another for trial.","C":"Applying law from one jurisdiction within another.","D":"Unusual interpretation of law outside of its typical meaning."},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Khái niệm 'Data Minimization' (Giảm thiểu dữ liệu) yêu cầu điều gì?","optionsVi":{"A":"Nén dữ liệu cơ sở xuống mức dung lượng thấp nhất","B":"Chỉ thu thập đúng và đủ dữ liệu cần thiết cho mục đích xử lý cụ thể đã được xác định trước","C":"Xóa toàn bộ dữ liệu người dùng hàng tuần","D":"Chỉ lưu trữ dữ liệu dưới dạng số nguyên"},"answerDisplay":"B. Collecting only the data strictly necessary for a specified purpose","concept":"• Giảm thiểu dữ liệu đòi hỏi hạn chế thu thập dư thừa, giúp bảo vệ riêng tư người dùng và giảm nguy cơ rò rỉ.","whyCorrect":"• Giới hạn thu thập đúng mục đích là nguyên tắc cốt lõi của GDPR và PIPEDA.","whyWrong":{"A":"• Nén dữ liệu là thuật toán lưu trữ, không phải giảm thiểu quyền riêng tư.","C":"• Xóa hàng tuần gây mất mát dữ liệu phục vụ vận hành.","D":"• Định dạng kiểu dữ liệu thuộc về lập trình phần mềm."}}},{"id":12,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":12,"chooseType":"Choose 1 answer","question":"Differential privacy works by adding what to a dataset?","options":{"A":"filters","B":"fairness scoring","C":"noise","D":"k-anonymity"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Lợi ích chính của việc áp dụng khung giải thích LIME (Local Interpretable Model-agnostic Explanations) là gì?","optionsVi":{"A":"Giải thích kết quả dự đoán của bất kỳ mô hình hộp đen nào tại vùng lân cận điểm dữ liệu cụ thể","B":"Tăng tốc độ huấn luyện mô hình lên gấp 10 lần","C":"Tự động sửa các lỗi sai trong tập dữ liệu","D":"Thay thế hoàn toàn mạng nơ-ron phức tạp bằng cây quyết định đơn giản"},"answerDisplay":"A. Explaining black-box predictions locally around specific data points","concept":"• LIME xấp xỉ hành vi của mô hình phức tạp bằng một mô hình đơn giản có thể giải thích được tại khu vực lân cận của mẫu dữ liệu.","whyCorrect":"• LIME hoạt động độc lập với loại mô hình (model-agnostic), giúp giải thích quyết định cá thể một cách minh bạch.","whyWrong":{"B":"• LIME tốn thêm thời gian tính toán giải thích chứ không tăng tốc huấn luyện.","C":"• LIME không có chức năng sửa dữ liệu.","D":"• LIME không thay thế mô hình gốc mà chỉ cung cấp lời giải thích cho kết quả của nó."}}},{"id":13,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":13,"chooseType":"Choose 1 answer","question":"When it comes to protecting private data, which of the following could be the root cause of a problem?","options":{"A":"The data was stored insecurely.","B":"The data was leaked online.","C":"The data was deleted from storage.","D":"The data was broken."},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Khi nói đến bảo vệ dữ liệu riêng tư, yếu tố nào sau đây có thể là nguyên nhân gốc rễ (root cause) của vấn đề rò rỉ?","optionsVi":{"A":"Dữ liệu được lưu trữ không an toàn (stored insecurely)","B":"Dữ liệu bị rò rỉ trên mạng","C":"Dữ liệu bị xóa khỏi bộ lưu trữ","D":"Dữ liệu bị hư hỏng tệp tin"},"answerDisplay":"A. The data was stored insecurely.","concept":"• Lưu trữ không an toàn (Insecure Storage) như thiếu mã hóa hay phân quyền lỏng lẻo là nguyên nhân gốc rễ trực tiếp dẫn đến rò rỉ dữ liệu.","whyCorrect":"• Bảo mật lưu trữ yếu tạo điều kiện cho tin tặc khai thác thâm nhập dữ liệu trái phép.","whyWrong":{"B":"• Dữ liệu rò rỉ trên mạng là hậu quả thực tế, không phải nguyên nhân gốc rễ.","C":"• Xóa dữ liệu gây mất thông tin chứ không gây rò rỉ.","D":"• Hư hỏng tệp là lỗi toàn vẹn dữ liệu."}}},{"id":14,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":14,"chooseType":"Choose 1 answer","question":"What is the role of interdisciplinary collaboration in tech ethics?","options":{"A":"It's unnecessary complexity","B":"It brings diverse expertise to ethical challenges","C":"It slows down development processes","D":"It creates conflicting viewpoints only"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Vai trò của sự hợp tác liên ngành (Interdisciplinary Collaboration) trong đạo đức công nghệ là gì?","optionsVi":{"A":"Tạo ra sự phức tạp không cần thiết","B":"Mang lại chuyên môn đa dạng để giải quyết các thách thức đạo đức (brings diverse expertise)","C":"Làm chậm quy trình phát triển","D":"Chỉ tạo ra các quan điểm xung đột"},"answerDisplay":"B. It brings diverse expertise to ethical challenges","concept":"• Đạo đức công nghệ đòi hỏi góc nhìn kết hợp từ kỹ sư, luật sư, nhà xã hội học và chuyên gia tâm lý.","whyCorrect":"• Kết hợp chuyên môn đa dạng giúp nhận diện toàn diện các rủi ro xã hội mà kỹ sư công nghệ có thể bỏ sót.","whyWrong":{"A":"• Sự hợp tác mang lại giá trị thực tế chứ không phải phức tạp vô ích.","C":"• Làm chậm ngắn hạn giúp tránh sự cố khủng hoảng dài hạn.","D":"• Xung đột quan điểm giúp phản biện và tìm ra giải pháp tối ưu."}}},{"id":15,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":15,"chooseType":"Choose 1 answer","question":"Which of the following describes the technique of homomorphic encryption?","options":{"A":"A method of swapping public and private keys between hosts.","B":"A method of cryptography that hides data inside other data.","C":"A method of performing operations on encrypted data.","D":"A method of mitigating biased algorithms through enhanced secrecy."},"answer":"C","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất về kỹ thuật Mã hóa đồng hình (Homomorphic Encryption)?","optionsVi":{"A":"Phương pháp hoán đổi khóa công khai và riêng tư","B":"Phương pháp giấu dữ liệu vào trong dữ liệu khác (Steganography)","C":"Phương pháp thực hiện các phép tính toán trực tiếp trên dữ liệu đã được mã hóa mà không cần giải mã","D":"Phương pháp giảm thiểu thuật toán thiên vị bằng tính bảo mật"},"answerDisplay":"C. A method of performing operations on encrypted data.","concept":"• Homomorphic Encryption cho phép máy chủ tính toán trên ciphertext và trả về kết quả mã hóa mà không bao giờ lộ dữ liệu thô.","whyCorrect":"• Kỹ thuật này bảo vệ tuyệt đối quyền riêng tư dữ liệu trong quá trình xử lý điện toán đám mây.","whyWrong":{"A":"• Hoán đổi khóa thuộc về trao đổi khóa Asymmetric (RSA/ECC).","B":"• Giấu dữ liệu là kỹ thuật Steganography.","D":"• Mã hóa không tự động sửa được thiên vị thuật toán."}}},{"id":16,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":16,"chooseType":"Choose 1 answer","question":"What role does communication play in ethical leadership?","options":{"A":"Preventing conflict resolution","B":"Encouraging silence during ethical issues","C":"Building trust and ethical alignment","D":"Reducing transparency in strategy"},"answer":"C","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Giao tiếp đóng vai trò gì trong lãnh đạo đạo đức (Ethical Leadership)?","optionsVi":{"A":"Ngăn cản giải quyết xung đột","B":"Khuyến khích sự im lặng khi xảy ra vấn đề đạo đức","C":"Xây dựng niềm tin và sự đồng bộ về tiêu chuẩn đạo đức (Building trust and ethical alignment)","D":"Giảm tính minh bạch trong chiến lược"},"answerDisplay":"C. Building trust and ethical alignment","concept":"• Truyền thông cởi mở trong lãnh đạo giúp xây dựng niềm tin nội bộ và thống nhất định hướng hành vi đạo đức cho nhân viên.","whyCorrect":"• Truyền thông minh bạch giúp định hình văn hóa và đảm bảo mọi thành viên hiểu rõ trách nhiệm của mình.","whyWrong":{"A":"• Truyền thông giúp thúc đẩy giải quyết xung đột.","B":"• Im lặng che giấu sai phạm vi phạm đạo đức.","D":"• Lãnh đạo đạo đức yêu cầu tăng cường minh bạch."}}},{"id":17,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":17,"chooseType":"Choose 1 answer","question":"What can happen if users are excluded from AI impact discussions?","options":{"A":"They contribute less","B":"Systems may not reflect public values","C":"Faster deployment","D":"Lower training costs"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Điều gì có thể xảy ra nếu người dùng bị loại khỏi các cuộc thảo luận về tác động của AI?","optionsVi":{"A":"Họ đóng góp ít hơn","B":"Các hệ thống AI có thể không phản ánh đúng các giá trị của công chúng (Systems may not reflect public values)","C":"Triển khai nhanh hơn","D":"Chi phí huấn luyện thấp hơn"},"answerDisplay":"B. Systems may not reflect public values","concept":"• Bỏ qua tiếng nói của người dùng làm hệ thống AI thiếu tính đại diện và có nguy cơ xâm phạm các giá trị đạo đức cộng đồng.","whyCorrect":"• Tham vấn người dùng đảm bảo AI được thiết kế đáp ứng đúng nhu cầu và giá trị nhân văn của xã hội.","whyWrong":{"A":"• Đóng góp ít hơn là biểu hiện, không phải hậu quả hệ thống.","C":"• Triển khai nhanh không bù đắp được nguy cơ sản phẩm bị tẩy chay.","D":"• Chi phí huấn luyện thuộc về hạ tầng máy tính."}}},{"id":18,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":18,"chooseType":"Choose 2 answers","question":"Which approach promotes inclusive communication?","options":{"A":"Using a single communication channel","B":"Considering diverse cultural and accessibility needs","C":"Focusing only on majority perspectives","D":"Standardizing all messages"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Cách tiếp cận nào sau đây thúc đẩy giao tiếp mang tính bao hàm (Inclusive Communication)?","optionsVi":{"A":"Chỉ sử dụng một kênh truyền thông duy nhất","B":"Xem xét các nhu cầu đa dạng về văn hóa và khả năng tiếp cận (Considering diverse cultural and accessibility needs)","C":"Chỉ tập trung vào quan điểm của nhóm đa số","D":"Tiêu chuẩn hóa cứng nhắc tất cả thông điệp"},"answerDisplay":"B. Considering diverse cultural and accessibility needs","concept":"• Giao tiếp bao hàm đảm bảo thông điệp tiếp cận được tới mọi nhóm đối tượng, kể cả người khuyết tật hay đa dạng văn hóa.","whyCorrect":"• Tôn trọng nhu cầu tiếp cận đa dạng đảm bảo tính bình đẳng trong việc truyền tải thông tin.","whyWrong":{"A":"• Dùng 1 kênh làm hạn chế khả năng tiếp cận của người dùng.","C":"• Tập trung nhóm đa số tạo ra sự gạt bỏ nhóm yếu thế.","D":"• Chuẩn hóa cứng nhắc bỏ qua các nhu cầu tiếp cận đặc thù."}}},{"id":19,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":19,"chooseType":"Choose 2 answers","question":"Which of the following are important qualities of a press release? (Select two.)","options":{"A":"It's in a digital format","B":"It's non-interactive","C":"It's delivered on a single platform","D":"It's concise"},"answer":"B, D","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Những phẩm chất quan trọng nào của một thông cáo báo chí (Press Release)? (Select two)","optionsVi":{"A":"Được phát hành dưới dạng kỹ thuật số","B":"Mang tính chất một chiều / không tương tác trực tiếp (Non-interactive)","C":"Được phân phối trên một nền tảng duy nhất","D":"Ngắn gọn và súc tích (Concise)"},"answerDisplay":"B. It's non-interactive & D. It's concise","concept":"• Press Release là văn bản thông báo chính thức một chiều, ngắn gọn, súc tích dành cho các nhà báo trích dẫn.","whyCorrect":"• Tính ngắn gọn súc tích và tính chất công bố chính thức (non-interactive) là hai thuộc tính chuẩn mực của Press Release.","whyWrong":{"A":"• Dạng kỹ thuật số là kênh phân phối, không phải thuộc tính bản chất.","C":"• Press Release được phân phối đa nền tảng để phủ sóng rộng."}}},{"id":20,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":20,"chooseType":"Choose 1 answer","question":"What is a challenge of explainability in complex AI systems?","options":{"A":"It makes models faster","B":"Users don't care about explanations","C":"Black-box algorithms are hard to interpret","D":"It improves transparency instantly"},"answer":"C","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Thách thức của tính giải thích được (Explainability) trong các hệ thống AI phức tạp là gì?","optionsVi":{"A":"Làm cho mô hình chạy nhanh hơn","B":"Người dùng không quan tâm đến lời giải thích","C":"Các thuật toán hộp đen (Black-box algorithms) rất khó để diễn giải logic bên trong","D":"Nó làm tăng tính minh bạch ngay lập tức"},"answerDisplay":"C. Black-box algorithms are hard to interpret","concept":"• Các mô hình deep learning có hàng tỷ trọng số toán học khiến việc diễn giải cơ sở lập luận trở nên cực kỳ khó khăn.","whyCorrect":"• Bản chất phức tạp của thuật toán Black-box là rào cản chính cho việc đạt được tính giải thích được.","whyWrong":{"A":"• Giải thích làm tốn thêm tài nguyên tính toán.","B":"• Người dùng và nhà kiểm toán rất cần lời giải thích.","D":"• Minh bạch không đạt được ngay lập tức nếu thiếu công cụ giải thích."}}},{"id":21,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":21,"chooseType":"Choose 2 answers","question":"How can sentiment analysis be useful in social media communication?","options":{"A":"It can shape the content and delivery of the message based on users' perceptions of the organization or technology.","B":"It can classify customers as loyal or disloyal, helping you target customers differently in your communications.","C":"It can determine which users have the largest influence on your reputation, and therefore which users you should communicate with.","D":"It can determine how to construct a message that influences users to be more positive about the organization or technology."},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Phân tích cảm xúc (Sentiment Analysis) có thể hữu ích như thế nào trong truyền thông mạng xã hội?","optionsVi":{"A":"Nó có thể định hình nội dung và cách thức phân phối thông điệp dựa trên nhận thức của người dùng về tổ chức","B":"Phân loại khách hàng trung thành hay không","C":"Xác định người dùng có ảnh hưởng lớn nhất để liên lạc","D":"Tự động thao túng người dùng có cảm xúc tích cực hơn"},"answerDisplay":"A. It can shape the content and delivery of the message based on users' perceptions of the organization or technology.","concept":"• Phân tích cảm xúc giúp doanh nghiệp đo lường thái độ dư luận thời gian thực để điều chỉnh chiến lược truyền thông phù hợp.","whyCorrect":"• Hiểu được thái độ công chúng giúp tổ chức xây dựng nội dung truyền thông đúng tâm lý và tinh tế.","whyWrong":{"B":"• Phân loại khách hàng trung thành thuộc về CRM/Loyalty analytics.","C":"• Tìm người ảnh hưởng thuộc về Influencer marketing.","D":"• Thao túng người dùng là vi phạm đạo đức truyền thông."}}},{"id":22,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":22,"chooseType":"Choose 2 answers","question":"Which of the following are useful strategies for communicating ethical risks to the organization? (Select two.)","options":{"A":"Communicate information through a single voice","B":"Disseminate information in multiple formats","C":"Communicate information in real time","D":"Provide information only when solicited"},"answer":"B, C","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Những chiến lược nào sau đây là hữu ích để truyền thông các rủi ro đạo đức tới toàn tổ chức? (Select two)","optionsVi":{"A":"Truyền đạt thông tin qua một giọng nói duy nhất","B":"Phổ biến thông tin dưới nhiều định dạng đa dạng (Disseminate information in multiple formats)","C":"Truyền đạt thông tin theo thời gian thực (Communicate information in real time)","D":"Chỉ cung cấp thông tin khi được yêu cầu"},"answerDisplay":"B. Disseminate information in multiple formats & C. Communicate information in real time","concept":"• Truyền thông rủi ro hiệu quả cần sử dụng đa dạng định dạng (văn bản, video, tập huấn) và cập nhật kịp thời gian thực.","whyCorrect":"• Đa dạng định dạng giúp tăng khả năng tiếp thu và truyền thông thời gian thực giúp ngăn ngừa sự cố kịp thời.","whyWrong":{"A":"• Giọng nói duy nhất tạo ra sự đơn điệu và thiếu phủ sóng.","D":"• Chỉ cung cấp khi hỏi là thái độ thụ động nguy hiểm trong quản lý rủi ro."}}},{"id":23,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":23,"chooseType":"Choose 1 answer","question":"What is the purpose of a holding statement in crisis and media communications?","options":{"A":"To order the business to temporarily halt certain operations","B":"To retain the services of specific media outlets","C":"To pre-write communications before they are needed","D":"To prevent personnel from communicating prematurely"},"answer":"D","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Mục đích của một phát ngôn giữ chỗ (Holding Statement) trong truyền thông khủng hoảng là gì?","optionsVi":{"A":"Yêu cầu doanh nghiệp tạm dừng hoạt động","B":"Thuê dịch vụ của các cơ quan báo chí cụ thể","C":"Viết trước các văn bản truyền thông khi chưa cần đến","D":"Ngăn chặn nhân viên phát ngôn vội vàng/sớm khi chưa có đủ thông tin xác thực"},"answerDisplay":"D. To prevent personnel from communicating prematurely","concept":"• Holding Statement là thông cáo ban đầu giúp kiểm soát luồng thông tin, câu thời gian xác minh sự thật và ngăn phát ngôn vội vã.","whyCorrect":"• Tránh việc nhân viên tự ý đưa ra thông tin chưa kiểm chứng làm trầm trọng thêm khủng hoảng.","whyWrong":{"A":"• Holding statement là công cụ truyền thông, không phải lệnh dừng vận hành.","B":"• Không dùng để thuê hợp đồng báo chí.","C":"• Chuẩn bị kịch bản là crisis template, holding statement dùng để công bố tạm thời khi sự cố xảy ra."}}},{"id":24,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":24,"chooseType":"Choose 2 answers","question":"Which of the following communication tactics help uphold transparency and explainability from the customer perspective? (Select two.)","options":{"A":"Providing prompt responses to customer questions about the decisions made by data-driven systems.","B":"Providing information about data-driven systems in simple, easy-to-understand terms.","C":"Providing in-depth white papers on the algorithms that underlie data-driven systems.","D":"Providing guidelines for how customers can keep their private data secure when using data-driven systems."},"answer":"A, B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Những chiến thuật truyền thông nào sau đây giúp duy trì tính minh bạch và khả năng giải thích từ góc nhìn của khách hàng? (Select two)","optionsVi":{"A":"Cung cấp phản hồi kịp thời cho các câu hỏi của khách hàng về quyết định do hệ thống AI đưa ra","B":"Cung cấp thông tin về các hệ thống AI bằng các thuật ngữ đơn giản, dễ hiểu","C":"Cung cấp các báo cáo kỹ thuật chuyên sâu về thuật toán","D":"Cung cấp hướng dẫn bảo mật dữ liệu cá nhân"},"answerDisplay":"A. Providing prompt responses to customer questions... & B. Providing information about data-driven systems in simple, easy-to-understand terms.","concept":"• Minh bạch với người tiêu dùng đòi hỏi giải thích thuật toán bằng ngôn ngữ bình dân (Layman terms) và phản hồi thắc mắc kịp thời.","whyCorrect":"• Ngôn ngữ dễ hiểu và phản hồi nhanh giúp người dùng thực sự nắm bắt được cách hệ thống ra quyết định ảnh hưởng đến họ.","whyWrong":{"C":"• Báo cáo quá chuyên sâu gây quá tải thông tin và khó hiểu cho khách hàng đại chúng.","D":"• Hướng dẫn bảo mật là kiến thức an toàn thông tin chung."}}},{"id":25,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":25,"chooseType":"Choose 1 answer","question":"What role does social media play in promoting products and building brand reputation?","options":{"A":"Facilitates direct engagement with consumers","B":"Guarantees higher sales numbers","C":"Eliminates the need for customer feedback","D":"Focuses solely on aesthetic appeal"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Mạng xã hội đóng vai trò gì trong việc quảng bá sản phẩm và xây dựng uy tín thương hiệu?","optionsVi":{"A":"Tạo điều kiện tương tác trực tiếp với người tiêu dùng (Facilitates direct engagement with consumers)","B":"Đảm bảo con số doanh số cao hơn","C":"Loại bỏ nhu cầu về phản hồi của khách hàng","D":"Chỉ tập trung vào sức hút thẩm mỹ"},"answerDisplay":"A. Facilitates direct engagement with consumers","concept":"• Mạng xã hội rút ngắn khoảng cách giữa doanh nghiệp và người dùng, cho phép đối thoại và lắng nghe hai chiều.","whyCorrect":"• Tương tác trực tiếp giúp thương hiệu thấu hiểu khách hàng và giải quyết các mối băn khoăn kịp thời.","whyWrong":{"B":"• Mạng xã hội không đảm bảo chắc chắn doanh số.","C":"• Mạng xã hội tăng cường thu thập phản hồi chứ không loại bỏ.","D":"• Thẩm mỹ chỉ là bề ngoài, cốt lõi là sự tương tác nội dung."}}},{"id":26,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":26,"chooseType":"Choose 2 answers","question":"Why are deep learning and machine learning called narrow? Select two options.","options":{"A":"Narrow can only perform the specific tasks it was designed to do.","B":"Narrow AI can't handle situations that its training data didn't prepare it for.","C":"Narrow AI is dependent on hand-coding of its algorithms."},"answer":"A, B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Tại sao Học sâu (Deep Learning) và Học máy (Machine Learning) lại được gọi là AI hẹp (Narrow AI)? (Select two)","optionsVi":{"A":"Narrow AI chỉ có thể thực hiện các tác vụ cụ thể mà nó được thiết kế để làm","B":"Narrow AI không thể xử lý các tình huống mà dữ liệu huấn luyện không chuẩn bị trước cho nó","C":"Narrow AI phụ thuộc hoàn toàn vào việc lập trình mã hóa thủ công thuật toán"},"answerDisplay":"A. Narrow can only perform the specific tasks it was designed to do & B. Narrow AI can't handle situations that its training data didn't prepare it for.","concept":"• Narrow AI chỉ tối ưu hóa cho bài toán chuyên biệt trong phạm vi dữ liệu huấn luyện, không có trí tuệ suy luận đa năng.","whyCorrect":"• Tính giới hạn tác vụ và sự phụ thuộc hoàn toàn vào phân phối dữ liệu huấn luyện là 2 lý do khiến ML/DL là Narrow AI.","whyWrong":{"C":"• Học máy tự động học đặc trưng từ dữ liệu chứ không lập trình thủ công từng quy tắc."}}},{"id":27,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":27,"chooseType":"Choose 1 answer","question":"The optimistic view of general AI could be accurately summarized as AI as a ____","options":{"A":"utility","B":"peace-keeping tool","C":"human right","D":"weapon"},"answer":"C","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Góc nhìn lạc quan về AI tổng quát (AGI) có thể được tóm tắt chính xác là xem AI như một ____","optionsVi":{"A":"Tiện ích hạ tầng","B":"Công cụ giữ gìn hòa bình","C":"Quyền con người (Human right)","D":"Vũ khí"},"answerDisplay":"C. human right","concept":"• Quan điểm bình đẳng nhân văn coi việc tiếp cận AGI và các lợi ích của nó như một quyền cơ bản của con người (Human Right).","whyCorrect":"• Xem AGI là quyền con người thể hiện triết lý phân phối công bằng thành quả công nghệ cho toàn bộ nhân loại.","whyWrong":{"A":"• Xem như tiện ích hạ tầng là quan điểm thương mại kỹ thuật.","B":"• Công cụ giữ hòa bình là quan điểm an ninh quân sự.","D":"• Xem như vũ khí là quan điểm bi quan và đe dọa."}}},{"id":28,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":28,"chooseType":"Choose 2 answers","question":"Which of the following are examples of how AI can limit human autonomy? (Select two.)","options":{"A":"Weapon systems can limit human autonomy as humans may not have decision-making capability or understand the decision making.","B":"AI systems might impact certain vulnerable groups such as the elderly and children differently than the rest of the population, which could limit those groups' autonomy.","C":"AI systems can assist individuals with automated, repetitive, or dangerous tasks.","D":"AI systems can perform tasks that humans cannot, such as processing millions of data records in a matter of seconds."},"answer":"A, B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Những ví dụ nào sau đây thể hiện cách AI có thể làm giới hạn quyền tự quyết (Autonomy) của con người? (Select two)","optionsVi":{"A":"Các hệ thống vũ khí tự động làm giảm quyền tự quyết vì con người có thể không có khả năng ra quyết định hoặc hiểu quyết định đó","B":"Các hệ thống AI có thể tác động đến các nhóm yếu thế như người già và trẻ em theo cách khác biệt, làm giới hạn quyền tự quyết của họ","C":"Hệ thống AI hỗ trợ cá nhân với các công việc tự động lặp đi lặp lại","D":"Hệ thống AI thực hiện các tác vụ vượt quá khả năng con người như xử lý hàng triệu bản ghi"},"answerDisplay":"A. Weapon systems can limit human autonomy... & B. AI systems might impact certain vulnerable groups...","concept":"• AI làm suy giảm Autonomy khi tước bỏ quyền kiểm soát quyết định của con người (trong vũ khí) hoặc thao túng các nhóm dễ bị tổn thương.","whyCorrect":"• Vũ khí tự động tước đi quyền ra quyết định sinh tử của con người và tác động lệch tới nhóm yếu thế làm thu hẹp quyền tự quyết xã hội.","whyWrong":{"C":"• Tự động hóa công việc lặp lại giúp tăng thời gian sáng tạo cho con người.","D":"• Xử lý dữ liệu quy mô lớn là năng lực hạ tầng tính toán."}}},{"id":29,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":29,"chooseType":"Choose 1 answer","question":"For a model to clean, parse, and self-train it's own dataset while remaining impartial, the model needs","options":{"A":"more powerful computing algorithms to auto-scrub data","B":"a list of bias and domain tests to run and adjust for","C":"10x the amount of data","D":"a test for recency bias"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Để một mô hình tự làm sạch, phân tích và huấn luyện trên tập dữ liệu của chính nó mà vẫn duy trì tính vô tư, mô hình cần điều gì?","optionsVi":{"A":"Các thuật toán tính toán mạnh hơn","B":"Một danh sách các bài kiểm thử thiên vị và kiểm thử miền (domain tests) để chạy và điều chỉnh","C":"Gấp 10 lần lượng dữ liệu","D":"Một bài kiểm thử cho thiên vị tính mới"},"answerDisplay":"B. a list of bias and domain tests to run and adjust for","concept":"• Tự động làm sạch dữ liệu có đạo đức đòi hỏi quy trình kiểm thử thiên vị (Bias Testing) và quy chuẩn miền kiến thức để hiệu chỉnh độ lệch.","whyCorrect":"• Danh sách kiểm thử giúp mô hình chủ động phát hiện và loại bỏ các sai lệch trong quá trình tự huấn luyện.","whyWrong":{"A":"• Thuật toán mạnh hơn không đảm bảo tính khách quan nếu không có tiêu chí kiểm thử thiên vị.","C":"• Tăng lượng dữ liệu có thể làm tăng quy mô thiên vị nếu dữ liệu gốc bị lệch.","D":"• Kiểm thử Recency bias chỉ giải quyết một khía cạnh thời gian."}}},{"id":30,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":30,"chooseType":"Choose 1 answer","question":"Which of the following best distinguishes between responsibility, accountability, and liability?","options":{"A":"Responsibility is the duty to complete a task, accountability is ownership of outcomes, and liability is legal obligation for any potential damages","B":"Responsibility is managing outcomes, accountability involves delegating tasks, and liability is financial responsibility","C":"Responsibility and accountability are synonymous, while liability is the duty to perform tasks","D":"Liability and accountability are the same, whereas responsibility is irrelevant in business"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Khái niệm nào sau đây phân biệt rõ nhất giữa Trách nhiệm nghĩa vụ (Responsibility), Trách nhiệm giải trình (Accountability) và Trách nhiệm pháp lý (Liability)?","optionsVi":{"A":"Responsibility là nghĩa vụ hoàn thành công việc, Accountability là quyền sở hữu kết quả cuối cùng, và Liability là nghĩa vụ pháp lý bồi thường thiệt hại","B":"Responsibility là quản lý kết quả, Accountability là ủy quyền, Liability là tài chính","C":"Responsibility và Accountability đồng nghĩa với nhau","D":"Liability và Accountability là một"},"answerDisplay":"A. Responsibility is the duty to complete a task, accountability is ownership of outcomes, and liability is legal obligation for any potential damages","concept":"• Ba khái niệm quản trị: Responsibility (nhiệm vụ thực thi), Accountability (chịu trách nhiệm kết quả) và Liability (bồi thường pháp lý).","whyCorrect":"• Định nghĩa chính xác phân biệt nhiệm vụ công việc, sở hữu kết quả và nghĩa vụ tài chính/pháp lý trước tòa.","whyWrong":{"B":"• Accountability không phải là việc ủy quyền tác vụ.","C":"• Responsibility và Accountability có ranh giới rõ ràng trong quản trị.","D":"• Liability mang tính chế tài pháp lý, khác với Accountability nội bộ."}}},{"id":31,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":31,"chooseType":"Choose 3 answers","question":"Which of the following, by itself, qualifies as personally identifiable information (PII)?","options":{"A":"System events added to a log","B":"A user's home address","C":"Temperature readings for an office building","D":"A user's customer ID in an online ordering system"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Thông tin nào sau đây độc lập đủ điều kiện cấu thành Thông tin định danh cá nhân (PII)?","optionsVi":{"A":"Sự kiện hệ thống được ghi vào nhật ký log","B":"Địa chỉ nhà riêng của người dùng (User's home address)","C":"Chỉ số nhiệt độ của một tòa nhà văn phòng","D":"Mã ID khách hàng trong hệ thống đặt hàng trực tuyến"},"answerDisplay":"B. A user's home address","concept":"• PII độc lập (Direct PII) là thông tin tự nó có thể chỉ đích danh địa điểm cư trú hoặc danh tính của một cá nhân cụ thể.","whyCorrect":"• Địa chỉ nhà riêng là thông tin địa lý duy nhất liên kết trực tiếp tới danh tính cá nhân.","whyWrong":{"A":"• Log sự kiện hệ thống là dữ liệu hạ tầng phần mềm.","C":"• Nhiệt độ tòa nhà là dữ liệu môi trường IoT.","D":"• Mã Customer ID cần bảng ánh xạ trong CSDL mới định danh được."}}},{"id":32,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":32,"chooseType":"Choose 3 answers","question":"Which of the following are actions that can help combat implicit bias? (Select three.)","options":{"A":"Obtaining your information from the same one or two media sources that your family and friends access.","B":"Cultivating awareness of your own biases.","C":"Interacting with diverse groups of people.","D":"Exposing yourself to “counter-stereotypical” examples."},"answer":"B, C, D","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Những hành động nào sau đây giúp chống lại thiên vị ẩn (Implicit Bias)? (Select three)","optionsVi":{"A":"Chỉ nhận thông tin từ 1-2 nguồn truyền thông quen thuộc của gia đình","B":"Nuôi dưỡng nhận thức về các thiên vị của chính bản thân (Cultivating awareness)","C":"Tương tác và giao lưu với các nhóm người đa dạng (Interacting with diverse groups)","D":"Tiếp xúc với các ví dụ đi ngược lại định kiến thông thường (Counter-stereotypical examples)"},"answerDisplay":"B. Cultivating awareness... & C. Interacting with diverse groups... & D. Exposing yourself to counter-stereotypical examples.","concept":"• Giảm Implicit Bias đòi hỏi tự nhận thức, đa dạng hóa trải nghiệm xã hội và liên tục tiếp nhận thông tin phản chứng định kiến.","whyCorrect":"• Ba hành động này giúp bộ não tái cấu trúc các liên tưởng định kiến vô thức sẵn có.","whyWrong":{"A":"• Tiêu thụ thông tin từ 1-2 nguồn quen thuộc làm gia tăng phòng bùn thông tin (Echo Chamber) và củng cố thiên vị sẵn có."}}},{"id":33,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":33,"chooseType":"Choose 1 answer","question":"Model inputs of address with \"City + State\" as separate inputs from a dataset would violate which accuracy guideline?","options":{"A":"Domain expertise","B":"No correlating data","C":"First principles","D":"Objective summarization"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Đầu vào mô hình chứa 'Thành phố + Bang' như các biến tách biệt từ tập dữ liệu sẽ vi phạm hướng dẫn độ chính xác nào?","optionsVi":{"A":"Chuyên môn miền","B":"Không dùng dữ liệu có tương quan cao / trùng lặp (No correlating data)","C":"Nguyên lý đầu tiên","D":"Tóm tắt khách quan"},"answerDisplay":"B. No correlating data","concept":"• Thành phố và Bang có mối tương quan phụ thuộc địa lý hoàn toàn (Multicollinearity). Sử dụng cả hai gây vi phạm nguyên tắc No Correlating Data.","whyCorrect":"• Dữ liệu tương quan hoàn toàn tạo ra nhiễu đa cộng tuyến trong các mô hình thống kê học máy.","whyWrong":{"A":"• Chuyên môn miền là tri thức ngành.","C":"• First principles là lập luận nguyên lý gốc.","D":"• Tóm tắt khách quan là phương pháp tổng hợp."}}},{"id":34,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":34,"chooseType":"Choose 1 answer","question":"Which type of bias causes people to trust an automated decision-making system (ADS) over a human's decision?","options":{"A":"Implicit bias","B":"Automation bias","C":"Complacency bias","D":"Confirmation bias"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Loại thiên vị nào khiến con người có xu hướng tin tưởng một hệ thống ra quyết định tự động (ADS) hơn quyết định của con người?","optionsVi":{"A":"Thiên vị ẩn (Implicit bias)","B":"Thiên vị tự động hóa (Automation bias)","C":"Thiên vị tự mãn (Complacency bias)","D":"Thiên vị xác nhận (Confirmation bias)"},"answerDisplay":"B. Automation bias","concept":"• Automation Bias là tâm lý ưu tiên và tin tưởng mù quáng vào kết quả của thuật toán tự động hơn đánh giá chuyên môn của con người.","whyCorrect":"• Sự tin tưởng sai lệch vào máy tính dẫn tới việc bỏ qua các lỗi sai rành rành của thuật toán.","whyWrong":{"A":"• Implicit bias là định kiến vô thức về con người/nhóm xã hội.","C":"• Complacency bias là sự chủ quan do hệ thống vận hành trơn tru lâu ngày.","D":"• Confirmation bias là thiên vị củng cố niềm tin cá nhân."}}},{"id":35,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":35,"chooseType":"Choose 1 answer","question":"A predictive model's false negative result can be defined as","options":{"A":"the predicted result was positive, and the actual result was positive","B":"the predicted result was negative, and the actual result was negative","C":"the predicted result was positive, and the actual result was negative","D":"the predicted result was negative, and the actual result was positive"},"answer":"D","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Kết quả Âm tính giả (False Negative) của một mô hình dự đoán được định nghĩa là gì?","optionsVi":{"A":"Kết quả dự đoán là Dương tính, và kết quả thực tế là Dương tính","B":"Kết quả dự đoán là Âm tính, và kết quả thực tế là Âm tính","C":"Kết quả dự đoán là Dương tính, và kết quả thực tế là Âm tính","D":"Kết quả dự đoán là Âm tính, nhưng kết quả thực tế là Dương tính (Predicted negative, actual positive)"},"answerDisplay":"D. the predicted result was negative, and the actual result was positive","concept":"• False Negative (Bỏ sót) xảy ra khi mô hình báo Không (Negative) nhưng thực tế đối tượng lại Có (Positive) - ví dụ bỏ sót bệnh nhân mắc ung thư.","whyCorrect":"• Định nghĩa chính xác của False Negative trong ma trận nhầm lẫn (Confusion Matrix).","whyWrong":{"A":"• Đây là True Positive (Dương tính thật).","B":"• Đây là True Negative (Âm tính thật).","C":"• Đây là False Positive (Báo động giả / Dương tính giả)."}}},{"id":36,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":36,"chooseType":"Choose 2 answers","question":"How can confirmation bias impact us socially? (Select two.)","options":{"A":"It can lead to a diverse set of friends.","B":"It can prevent us from being social with other people.","C":"It can impede socio-political cooperation.","D":"It can lead to groupthink, which can in turn halt forward progress."},"answer":"C, D","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Thiên vị xác nhận (Confirmation Bias) có thể tác động đến chúng ta về mặt xã hội như thế nào? (Select two)","optionsVi":{"A":"Dẫn tới việc có nhóm bạn bè đa dạng","B":"Ngăn cản chúng ta hòa nhập xã hội với người khác","C":"Cản trở sự hợp tác kinh tế - xã hội và chính trị (Impede socio-political cooperation)","D":"Dẫn đến tư duy nhóm (Groupthink), kìm hãm sự tiến bộ xã hội"},"answerDisplay":"C. It can impede socio-political cooperation & D. It can lead to groupthink...","concept":"• Confirmation Bias khiến các nhóm xã hội củng cố cực đoan quan điểm cá nhân, tạo ra tư duy nhóm (Groupthink) và chia rẽ chính trị.","whyCorrect":"• Việc từ chối tiếp nhận thông tin trái chiều làm gia tăng sự phân hóa chính trị và kìm hãm đối thoại xã hội.","whyWrong":{"A":"• Confirmation bias khiến con người co cụm với người giống mình chứ không tạo ra bạn bè đa dạng.","B":"• Nó không ngăn cản giao tiếp nói chung mà làm lệch lạc quan điểm giao tiếp."}}},{"id":37,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":37,"chooseType":"Choose 1 answer","question":"Which emerging technology area requires the most immediate ethical attention?","options":{"A":"All emerging technologies require ethical consideration","B":"Only artificial intelligence","C":"Only biotechnology","D":"Only robotics"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Trong các hệ thống trí tuệ môi trường (Ambient Intelligence), rủi ro riêng tư nào phổ biến nhất do việc giám sát dữ liệu liên tục?","optionsVi":{"A":"Truy cập và thu thập dữ liệu trái phép (Unauthorized data access)","B":"Cải thiện khả năng phân tích dữ liệu","C":"Nâng cao trải nghiệm người dùng","D":"Tối ưu hóa tài nguyên phần cứng"},"answerDisplay":"A. Unauthorized data access","concept":"• Ambient Intelligence theo dõi hành vi người dùng 24/7 qua cảm biến, tạo ra rủi ro lộ rò và rình mò truy cập trái phép.","whyCorrect":"• Thu thập dữ liệu liên tục tích tụ kho thông tin nhạy cảm rất dễ bị bên thứ ba xâm nhập bất hợp pháp.","whyWrong":{"B":"• Phân tích nâng cao là lợi ích kỹ thuật.","C":"• Nâng cao trải nghiệm là mục tiêu sản phẩm.","D":"• Tối ưu tài nguyên thuộc về hiệu năng hệ thống."}}},{"id":38,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":38,"chooseType":"Choose 1 answer","question":"In a complex learning function, we will understand the ____ but not the ____","options":{"A":"causal link, correlation","B":"algorithm, cause and effect","C":"inputs/outputs, algorithm","D":"input data, output data"},"answer":"C","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Trong một hàm học máy phức tạp (Complex Learning Function), chúng ta sẽ hiểu khía cạnh nào nhưng không hiểu khía cạnh nào?","optionsVi":{"A":"Mối quan hệ nguyên nhân, tương quan","B":"Thuật toán, mối quan hệ nguyên nhân và kết quả","C":"Đầu vào và đầu ra (inputs/outputs), nhưng không hiểu cơ chế bên trong của thuật toán (algorithm)","D":"Dữ liệu đầu vào, dữ liệu đầu ra"},"answerDisplay":"C. inputs/outputs, algorithm","concept":"• Bản chất của mô hình học sâu hộp đen (Black Box) là chúng ta thấy và kiểm soát được Input/Output nhưng không hiểu rõ cơ chế biến đổi trung gian của thuật toán.","whyCorrect":"• Hiểu rõ dữ liệu đầu vào và kết quả đầu ra nhưng không giải thích được cơ chế tính toán bên trong là đặc trưng của Black Box.","whyWrong":{"A":"• Mô hình AI thường bắt được mối tương quan (correlation) chứ không bắt được mối quan hệ nguyên nhân (causal link).","B":"• Thuật toán bên trong không thể giải thích rõ ràng.","D":"• Cả Input và Output đều là phần nhìn thấy được."}}},{"id":39,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":39,"chooseType":"Choose 1 answer","question":"What is the ultimate goal of ethics in emerging technology?","options":{"A":"Slow down technological progress","B":"Ensure technology serves humanity's best interests","C":"Increase regulatory compliance costs","D":"Make development more complex"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Mục tiêu tối thượng của đạo đức trong công nghệ mới nổi (Emerging Technology) là gì?","optionsVi":{"A":"Làm chậm sự phát triển của công nghệ","B":"Đảm bảo công nghệ phục vụ cho lợi ích tốt nhất của nhân loại (Ensure technology serves humanity's best interests)","C":"Tăng chi phí tuân thủ quy định","D":"Làm cho quy trình phát triển trở nên phức tạp hơn"},"answerDisplay":"B. Ensure technology serves humanity's best interests","concept":"• Đạo đức công nghệ hướng tới việc định hình sự phát triển của công nghệ sao cho mang lại giá trị nhân văn và không gây hại.","whyCorrect":"• Mục tiêu cốt lõi là hướng công nghệ tới phục vụ hạnh phúc, sự an toàn và lợi ích chung của con người.","whyWrong":{"A":"• Đạo đức không nhằm kìm hãm sự tiến bộ công nghệ mà là định hướng sự tiến bộ đó.","C":"• Tăng chi phí tuân thủ chỉ là hệ quả quản lý, không phải mục tiêu tối thượng.","D":"• Mục tiêu không phải làm phức tạp hóa quy trình."}}},{"id":40,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":40,"chooseType":"Choose 1 answer","question":"\"Companies have an obligation to their shareholders\" is part of a view that sees artificial intelligence as","options":{"A":"an overall good for humanity, no matter the consequences","B":"just another tool that accelerates research, like online advertising","C":"a gimmick for enterprises, unless general intelligence is achieved","D":"a harmful tool that will bring about the end of capitalism"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Quan điểm 'Các công ty có nghĩa vụ đối với cổ đông của họ' là một phần của góc nhìn xem trí tuệ nhân tạo như thế nào?","optionsVi":{"A":"Một điều tốt đẹp tổng thể cho nhân loại bất kể hậu quả","B":"Chỉ là một công cụ giúp tăng tốc nghiên cứu và kinh doanh, giống như quảng cáo trực tuyến (just another tool that accelerates research)","C":"Một chiêu trò quảng cáo cho doanh nghiệp","D":"Một công cụ có hại sẽ chấm dứt chủ nghĩa tư bản"},"answerDisplay":"B. just another tool that accelerates research, like online advertising","concept":"• Góc nhìn tối đa hóa giá trị cổ đông (Shareholder Primacy) coi AI thuần túy là công cụ công nghệ kinh doanh giúp tăng năng suất và doanh thu.","whyCorrect":"• Quan điểm thương mại xem AI là công cụ đẩy nhanh tiến độ và lợi nhuận doanh nghiệp như các công nghệ số trước đây.","whyWrong":{"A":"• Quan điểm vị cổ đông không tập trung vào lợi ích nhân loại tổng thể.","C":"• AI không chỉ là chiêu trò bề ngoài mà mang lại hiệu quả thực tế.","D":"• Doanh nghiệp coi AI là công cụ gia tăng lợi nhuận tư bản chứ không phải chấm dứt nó."}}},{"id":41,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":41,"chooseType":"Choose 1 answer","question":"What is the impact of biased algorithms on decision-making?","options":{"A":"They can lead to unfair and discriminatory outcomes","B":"They enhance the precision and accuracy of decisions","C":"They ensure all stakeholders are considered equally","D":"They guarantee privacy and security in all data processes"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Tác động của các thuật toán bị thiên vị (Biased Algorithms) đối với quá trình ra quyết định là gì?","optionsVi":{"A":"Chúng có thể dẫn đến các kết quả bất công và phân biệt đối xử (unfair and discriminatory outcomes)","B":"Chúng nâng cao độ chính xác của các quyết định","C":"Chúng đảm bảo tất cả các bên liên quan được xem xét bình đẳng","D":"Chúng đảm bảo quyền riêng tư và bảo mật trong mọi quy trình"},"answerDisplay":"A. They can lead to unfair and discriminatory outcomes","concept":"• Algorithmic Bias tái lập định kiến xã hội, tạo ra các quyết định lệch lạc gây bất công cho nhóm đối tượng bị thiên vị.","whyCorrect":"• Tác động tiêu cực trực tiếp của thuật toán thiên vị là tạo ra các quyết định phân biệt đối xử và vi phạm tính công bằng.","whyWrong":{"B":"• Thiên vị làm giảm tính khách quan và chính xác của quyết định thực tế.","C":"• Thuật toán thiên vị không xem xét bình đẳng các nhóm.","D":"• Thiên vị thuật toán không liên quan đến đảm bảo an ninh bảo mật."}}},{"id":42,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":42,"chooseType":"Choose 2 answers","question":"What is one of the recommendations for governments?","options":{"A":"Promote human values.","B":"Promote transparency in AI.","C":"Promote international cooperation.","D":"Promote collaboration."},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Khuyến nghị quan trọng nào sau đây được dành cho các chính phủ trong quản trị AI?","optionsVi":{"A":"Thúc đẩy các giá trị con người","B":"Thúc đẩy tính minh bạch trong AI (Promote transparency in AI)","C":"Thúc đẩy hợp tác quốc tế","D":"Thúc đẩy sự cộng tác"},"answerDisplay":"B. Promote transparency in AI.","concept":"• Khuyến nghị chính sách cho chính phủ tập trung vào việc bắt buộc tính minh bạch (Transparency) để công chúng kiểm toán và giám sát hệ thống AI.","whyCorrect":"• Thúc đẩy minh bạch giúp xây dựng khung pháp lý giải trình trách nhiệm và sự tin tưởng xã hội.","whyWrong":{"A":"• Thúc đẩy giá trị con người là mục tiêu chung nhưng khuyến nghị pháp lý ưu tiên tính minh bạch kiểm toán.","C":"• Hợp tác quốc tế là phương tiện ngoại giao.","D":"• Sự cộng tác là phương thức triển khai chung."}}},{"id":43,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":43,"chooseType":"Choose 2 answers","question":"Which of the following ethical domains does the IEEE 7000 series explore? (Select two.)","options":{"A":"Emulated empathy","B":"Machine-readable privacy terms","C":"Fair competition","D":"Personnel safety"},"answer":"A, B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Lĩnh vực đạo đức nào sau đây được chuỗi tiêu chuẩn IEEE 7000 nghiên cứu? (Select two)","optionsVi":{"A":"Thấu cảm giả lập (Emulated empathy)","B":"Điều khoản quyền riêng tư máy có thể đọc được (Machine-readable privacy terms)","C":"Cạnh tranh công bằng","D":"An toàn nhân sự"},"answerDisplay":"A. Emulated empathy & B. Machine-readable privacy terms","concept":"• Chuỗi tiêu chuẩn IEEE 7000 tập trung vào thiết kế đạo đức cho hệ thống tự động, bao gồm thấu cảm mô phỏng và điều khoản máy đọc.","whyCorrect":"• Hai khía cạnh này nằm trong phạm vi kỹ thuật hóa đạo đức của chuẩn IEEE 7000.","whyWrong":{"C":"• Cạnh tranh công bằng thuộc về luật chống độc quyền thương mại.","D":"• An toàn nhân sự thuộc về an toàn lao động OSHA."}}},{"id":44,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":44,"chooseType":"Choose 1 answer","question":"A model that equalizes the number of mistakes it makes for each subgroup to reduce harm is deciding on","options":{"A":"equality of true outcomes","B":"equality of false negatives","C":"equality of training data","D":"equality of prediction bias"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Một mô hình bằng cân bằng số lượng sai sót mà nó mắc phải cho mỗi nhóm nhỏ để giảm thiểu tổn hại là đang quyết định về tiêu chuẩn nào?","optionsVi":{"A":"Bình đẳng kết quả thực tế","B":"Bình đẳng âm tính giả (Equality of false negatives)","C":"Bình đẳng dữ liệu huấn luyện","D":"Bình đẳng thiên vị dự đoán"},"answerDisplay":"B. equality of false negatives","concept":"• Equality of False Negatives đảm bảo tỷ lệ bỏ sót sai sót gây hại đạt mức ngang nhau giữa tất cả các phân nhóm xã hội.","whyCorrect":"• Cân bằng tỷ lệ Âm tính giả giữa các nhóm đảm bảo rủi ro bỏ sót tổn hại không bị dồn lên một nhóm yếu thế cụ thể.","whyWrong":{"A":"• Bình đẳng kết quả là Equalized Odds tổng thể.","C":"• Dữ liệu huấn luyện là phân phối mẫu đầu vào.","D":"• Thiên vị dự đoán là chỉ số đo lường độ lệch chung."}}},{"id":45,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":45,"chooseType":"Choose 1 answer","question":"Your business handles the personal data of California residents. Which of the following regulations would enable a resident to request that their data be deleted from your company's files?","options":{"A":"PCI DSS","B":"OECD Privacy Guidelines","C":"COPPA","D":"CCPA"},"answer":"D","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Doanh nghiệp của bạn xử lý dữ liệu cá nhân của cư dân California. Quy định nào sau đây cho phép cư dân yêu cầu xóa dữ liệu của họ khỏi tệp của công ty?","optionsVi":{"A":"PCI DSS","B":"Hướng dẫn quyền riêng tư OECD","C":"COPPA","D":"CCPA (Đạo luật quyền riêng tư người tiêu dùng California)"},"answerDisplay":"D. CCPA","concept":"• CCPA (California Consumer Privacy Act) trao cho cư dân California quyền yêu cầu doanh nghiệp xóa dữ liệu cá nhân (Right to Delete).","whyCorrect":"• CCPA là đạo luật riêng tư của bang California quy định rõ quyền xóa dữ liệu cá nhân của người tiêu dùng.","whyWrong":{"A":"• PCI DSS là tiêu chuẩn an toàn dữ liệu thẻ thanh toán ngân hàng.","B":"• OECD Privacy Guidelines là khuyến nghị quốc tế, không phải luật bắt buộc thi hành tại California.","C":"• COPPA là luật bảo vệ quyền riêng tư trẻ em trên mạng của Mỹ."}}},{"id":46,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":46,"chooseType":"Choose 1 answer","question":"Which international standard provides guidelines for AI governance?","options":{"A":"ISO 27001","B":"IEEE Standards","C":"ISO/IEC 42001","D":"HIPAA"},"answer":"C","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Tiêu chuẩn quốc tế nào cung cấp các hướng dẫn cho hệ thống quản trị AI trong tổ chức?","optionsVi":{"A":"ISO 27001","B":"Tiêu chuẩn IEEE","C":"ISO/IEC 42001","D":"HIPAA"},"answerDisplay":"C. ISO/IEC 42001","concept":"• ISO/IEC 42001 là tiêu chuẩn quốc tế đầu tiên chứng nhận Hệ thống quản trị trí tuệ nhân tạo (AIMS - Artificial Intelligence Management System).","whyCorrect":"• ISO/IEC 42001 thiết lập các yêu cầu quản trị AI có trách nhiệm và an toàn cho tổ chức.","whyWrong":{"A":"• ISO 27001 là tiêu chuẩn an toàn thông tin chung (ISMS).","B":"• IEEE Standards bao gồm nhiều tiêu chuẩn kỹ thuật chuyên ngành.","D":"• HIPAA là luật bảo mật thông tin y tế của Mỹ."}}},{"id":47,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":47,"chooseType":"Choose 1 answer","question":"If you are attempting to build a new framework for the research and development (R&D) of AI, which of the following frameworks might you look at first for its emphasis in this area?","options":{"A":"The Beijing AI Principles","B":"The American Medical Association's definition of artificial intelligence","C":"The G20 AI Principles","D":"The Montreal Declaration for a Responsible Development of Artificial Intelligence"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Nếu bạn đang cố gắng xây dựng một khung làm việc mới cho nghiên cứu và phát triển (R&D) AI, khung làm việc nào nhấn mạnh nhất vào lĩnh vực này?","optionsVi":{"A":"Nguyên tắc AI Bắc Kinh (The Beijing AI Principles)","B":"Định nghĩa AI của Hiệp hội Y khoa Hoa Kỳ","C":"Nguyên tắc AI của G20","D":"Tuyên ngôn Montreal về phát triển AI có trách nhiệm"},"answerDisplay":"A. The Beijing AI Principles","concept":"• Nguyên tắc AI Bắc Kinh (Beijing AI Principles) nổi tiếng với việc phân chia rõ ràng các nguyên tắc dành riêng cho khâu Nghiên cứu & Phát triển (R&D).","whyCorrect":"• Khung Bắc Kinh chú trọng hàng đầu vào các chỉ dẫn đạo đức trong giai đoạn R&D AI.","whyWrong":{"B":"• Định nghĩa AMA tập trung vào ứng dụng y khoa.","C":"• G20 AI Principles tập trung vào chính sách kinh tế và tăng trưởng bền vững.","D":"• Tuyên ngôn Montreal tập trung vào quyền con người và bình đẳng xã hội."}}},{"id":48,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":48,"chooseType":"Choose 1 answer","question":"Why is the question of robot rights and emancipation one that isn't as important as addressing issues of bias, privacy, transparency, and other principles discussed in the various ethical frameworks?","options":{"A":"These rights necessitate that robots become sentient entities, which is currently not feasible.","B":"Humans are anthropocentric and don’t want to extend rights to other sentient entities.","C":"There is no legal precedent for granting rights to entities that are not humans.","D":"Robots are mechanical instruments and therefore don’t deserve to have rights."},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Tại sao câu hỏi về quyền và sự giải phóng của robot lại không quan trọng bằng việc giải quyết các vấn đề về thiên vị, quyền riêng tư, tính minh bạch trong các khung đạo đức AI hiện nay?","optionsVi":{"A":"Các quyền này đòi hỏi robot phải trở thành các thực thể có tri giác, điều mà hiện tại hoàn toàn không khả thi","B":"Con người coi mình là trung tâm và không muốn trao quyền","C":"Không có tiền lệ pháp lý","D":"Robot là công cụ cơ khí nên không xứng đáng có quyền"},"answerDisplay":"A. These rights necessitate that robots become sentient entities, which is currently not feasible.","concept":"• Quyền của Robot đòi hỏi trí tuệ nhân tạo phải đạt mức Tri giác (Sentience) và Ý thức, trong khi công nghệ AI hiện tại chỉ là các thuật toán xử lý dữ liệu toán học.","whyCorrect":"• Tính không khả thi về mặt kỹ thuật khiến việc bàn luận quyền cho robot trở nên viển vông so với các rủi ro thiên vị/riêng tư thực tế đang hiện hữu.","whyWrong":{"B":"• Quan điểm vị nhân sinh không phải lý do kỹ thuật cốt lõi.","C":"• Tiền lệ pháp lý có thể tạo mới nếu công nghệ thực sự đạt tri giác.","D":"• Định kiến vật lý không phản ánh lý do công nghệ."}}},{"id":49,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":49,"chooseType":"Choose 1 answer","question":"Which of the following software development principles is essential in the real-world deployment of AI-enabled software applications in critical scenarios like self-driving cars?","options":{"A":"Robustness to adversarial examples","B":"Architectural design analysis","C":"Continuous integration and deployment of patch updates","D":"Version control of the AI models deployed"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Nguyên tắc phát triển phần mềm nào sau đây là thiết yếu trong việc triển khai thực tế các ứng dụng AI trong các kịch bản quan trọng như xe tự lái?","optionsVi":{"A":"Tính chống chịu trước các cuộc tấn công dữ liệu nhiễu/đối kháng (Robustness to adversarial examples)","B":"Phân tích thiết kế kiến trúc","C":"Tích hợp và triển khai liên tục bản vá","D":"Quản lý phiên bản của mô hình AI"},"answerDisplay":"A. Robustness to adversarial examples","concept":"• Tấn công đối kháng (Adversarial Attacks) có thể đánh lừa xe tự lái (như dán băng dính lên biển báo dừng). Mô hình bắt buộc phải có tính chống chịu (Robustness) an toàn.","whyCorrect":"• Độ vững chắc trước dữ liệu đối kháng đảm bảo hệ thống AI không bị thao túng gây tai nạn nguy hiểm đến tính mạng.","whyWrong":{"B":"• Phân tích kiến trúc là bước thiết kế chung.","C":"• CI/CD là quy trình phát triển phần mềm chuẩn.","D":"• Quản lý phiên bản là quản trị mã nguồn (Git)."}}},{"id":50,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":50,"chooseType":"Choose 1 answer","question":"What does the GDPR primarily regulate?","options":{"A":"Artificial intelligence development","B":"Data protection and privacy","C":"Software quality assurance","D":"Network security protocols"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Đạo luật GDPR của Liên minh Châu Âu chủ yếu điều chỉnh lĩnh vực nào?","optionsVi":{"A":"Phát triển trí tuệ nhân tạo","B":"Bảo vệ dữ liệu và quyền riêng tư cá nhân (Data protection and privacy)","C":"Đảm bảo chất lượng phần mềm","D":"Giao thức an ninh mạng"},"answerDisplay":"B. Data protection and privacy","concept":"• GDPR (General Data Protection Regulation) là quy định chung về bảo vệ dữ liệu và riêng tư cá nhân nghiêm ngặt nhất thế giới.","whyCorrect":"• GDPR quy định nghĩa vụ thu thập, xử lý và bảo vệ dữ liệu cá nhân của mọi cư dân EU.","whyWrong":{"A":"• GDPR điều chỉnh dữ liệu cá nhân chung chứ không chuyên biệt cho quy trình lập trình AI.","C":"• Chất lượng phần mềm thuộc về kiểm thử QA.","D":"• Giao thức mạng thuộc về tiêu chuẩn viễn thông."}}},{"id":51,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":51,"chooseType":"Choose 1 answer","question":"How can a leader promote ethical behavior across an organization?","options":{"A":"By making decisions in isolation","B":"By enforcing silence on ethical issues","C":"By modeling ethical behavior and encouraging open dialogue","D":"By limiting diversity in teams"},"answer":"C","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Làm thế nào một nhà lãnh đạo có thể thúc đẩy hành vi đạo đức trong toàn bộ tổ chức?","optionsVi":{"A":"Bằng cách đưa ra quyết định độc đoán một mình","B":"Bằng cách bắt buộc giữ im lặng về các vấn đề đạo đức","C":"Bằng cách làm tấm gương hành vi đạo đức và khuyến khích đối thoại cởi mở (modeling ethical behavior and encouraging open dialogue)","D":"Bằng cách hạn chế sự đa dạng trong các đội ngũ"},"answerDisplay":"C. By modeling ethical behavior and encouraging open dialogue","concept":"• Lãnh đạo đạo đức (Ethical Leadership) đòi hỏi nêu gương thực tế (Lead by Example) và tạo môi trường an toàn tâm lý để nhân viên thảo luận rủi ro.","whyCorrect":"• Nêu gương và đối thoại cởi mở giúp lan tỏa văn hóa đạo đức tới mọi cấp bậc trong công ty.","whyWrong":{"A":"• Quyết định độc đoán cô lập góc nhìn và làm gia tăng rủi ro sai phạm.","B":"• Bắt buộc im lặng sẽ che giấu các vi phạm đạo đức nghiêm trọng.","D":"• Hạn chế đa dạng làm suy giảm tính phản biện."}}},{"id":52,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":52,"chooseType":"Choose 1 answer","question":"Which of the following might be a risk of not having an ethical organizational culture?","options":{"A":"Employees might be less interested in their careers.","B":"Employees might face cognitive dissonance.","C":"Employees will experience a faster approval process to get a product launched.","D":"Employees are more likely to express their opinions about the company."},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Điều nào sau đây có thể là một rủi ro khi không có một văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Nhân viên ít quan tâm hơn đến sự nghiệp","B":"Nhân viên phải đối mặt với sự bất hòa nhận thức (Cognitive dissonance)","C":"Nhân viên trải qua quy trình phê duyệt nhanh hơn","D":"Nhân viên dễ bày tỏ ý kiến hơn"},"answerDisplay":"B. Employees might face cognitive dissonance.","concept":"• Thiếu văn hóa đạo đức khiến nhân viên rơi vào trạng thái bất hòa nhận thức (Cognitive Dissonance) khi mâu thuẫn giữa đạo đức cá nhân và yêu cầu gian dối của công ty.","whyCorrect":"• Sự mâu thuẫn giữa giá trị cá nhân và văn hóa sai trái của công ty gây ra áp lực tâm lý và hoảng loạn nhận thức.","whyWrong":{"A":"• Quan tâm sự nghiệp không phải tác động tâm lý trực tiếp của văn hóa phi đạo đức.","C":"• Phê duyệt nhanh cắt giảm quy trình là hành vi rủi ro vận hành.","D":"• Văn hóa phi đạo đức cấm đoán nhân viên bày tỏ ý kiến phản biện."}}},{"id":53,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":53,"chooseType":"Choose 1 answer","question":"How can an organization promote an ethical culture from the top down?","options":{"A":"Leadership actively models ethical behavior","B":"Emphasizing profit margins over ethical considerations","C":"Ignoring unethical behavior if it increases efficiency","D":"Relying solely on external audit reports"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Tổ chức có thể thúc đẩy văn hóa đạo đức từ trên xuống (top-down) như thế nào?","optionsVi":{"A":"Ban lãnh đạo tích cực làm tấm gương cho hành vi đạo đức (Leadership actively models ethical behavior)","B":"Nhấn mạnh biên lợi nhuận hơn các xem xét đạo đức","C":"Bỏ qua hành vi không đạo đức nếu nó giúp tăng hiệu suất","D":"Chỉ dựa vào các báo cáo kiểm toán bên ngoài"},"answerDisplay":"A. Leadership actively models ethical behavior","concept":"• Thúc đẩy văn hóa top-down đòi hỏi cấp lãnh đạo cao nhất phải thể hiện cam kết đạo đức qua từng quyết định thực tế.","whyCorrect":"• Hành vi nêu gương của lãnh đạo là tín hiệu mạnh mẽ nhất định hình chuẩn mực hành xử cho toàn bộ nhân viên.","whyWrong":{"B":"• Ưu tiên lợi nhuận trên đạo đức sẽ phá hủy văn hóa doanh nghiệp.","C":"• Bỏ qua sai phạm vì hiệu suất tạo ra tiền lệ xấu cực kỳ nguy hiểm.","D":"• Kiểm toán bên ngoài chỉ mang tính kiểm tra thụ động."}}},{"id":54,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":54,"chooseType":"Choose 1 answer","question":"Which of the following is a problematic reason to pilot a code of ethics prior to widespread deployment?","options":{"A":"The pilot phase helps to identify gaps in the current code of ethics.","B":"The pilot phase helps to develop awareness and buy-in from the relevant stakeholders in the organization.","C":"The pilot phase demonstrates the seriousness of the organization with respect to its ethical responsibilities.","D":"The pilot phase helps to stress test a code of ethics in a real-world situation."},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Lý do nào sau đây là một lý do có vấn đề khi thử nghiệm một bộ quy tắc đạo đức trước khi triển khai rộng rãi?","optionsVi":{"A":"Giai đoạn thử nghiệm giúp xác định các lỗ hổng trong bộ quy tắc đạo đức hiện tại","B":"Giai đoạn thử nghiệm giúp phát triển sự nhận thức và đồng thuận từ các bên liên quan","C":"Giai đoạn thử nghiệm thể hiện sự nghiêm túc của tổ chức đối với trách nhiệm đạo đức","D":"Giai đoạn thử nghiệm giúp kiểm thử sức chịu đựng của bộ quy tắc trong thực tế"},"answerDisplay":"A. The pilot phase helps to identify gaps in the current code of ethics.","concept":"• Mục tiêu của Pilot là stress-test và xây dựng sự đồng thuận; nếu coi pilot chỉ để che đậy lỗ hổng hoặc trì hoãn triển khai sẽ gây ra rủi ro cho tổ chức.","whyCorrect":"• Tìm lỗ hổng mà không có cơ chế sửa đổi thực tế biến thử nghiệm thành cái cớ trì hoãn tuân thủ.","whyWrong":{"B":"• Xây dựng đồng thuận là lợi ích tích cực chuẩn mực của Pilot.","C":"• Thể hiện cam kết nghiêm túc là giá trị tích cực của Pilot.","D":"• Stress-test trong thực tế là mục tiêu kỹ thuật chính đáng của Pilot."}}},{"id":55,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":55,"chooseType":"Choose 1 answer","question":"Why is fair competition an important ethical consideration for data-driven technology businesses?","options":{"A":"Fair competition prevents predatory pricing.","B":"Fair competition builds user trust in technology as a whole.","C":"Fair competition provides products choice to users.","D":"Fair competition provides service choice to users."},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Tại sao cạnh tranh công bằng lại là một xem xét đạo đức quan trọng đối với các doanh nghiệp công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Cạnh tranh công bằng ngăn chặn việc định giá độc quyền","B":"Cạnh tranh công bằng xây dựng niềm tin của người dùng vào toàn bộ hệ sinh thái công nghệ (builds user trust in technology as a whole)","C":"Cạnh tranh công bằng cung cấp sự lựa chọn sản phẩm cho người dùng","D":"Cạnh tranh công bằng cung cấp sự lựa chọn dịch vụ cho người dùng"},"answerDisplay":"B. Fair competition builds user trust in technology as a whole.","concept":"• Cạnh tranh công bằng ngăn chặn sự độc quyền dữ liệu (Data Monopoly), bảo vệ lòng tin tổng thể của xã hội vào hạ tầng số.","whyCorrect":"• Xây dựng niềm tin công chúng vào công nghệ là giá trị đạo đức cao nhất của môi trường cạnh tranh lành mạnh.","whyWrong":{"A":"• Định giá chỉ là khía cạnh tài chính thương mại.","C":"• Lựa chọn sản phẩm là lợi ích tiêu dùng thương mại.","D":"• Lựa chọn dịch vụ thuộc về thị trường."}}},{"id":56,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":56,"chooseType":"Choose 1 answer","question":"What is one outcome of building an ethical culture within an organization?","options":{"A":"Reduced compliance with regulation","B":"Higher trust among stakeholders","C":"Slower development processes","D":"More hierarchical power structure"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Một kết quả của việc xây dựng văn hóa đạo đức trong một tổ chức là gì?","optionsVi":{"A":"Giảm sự tuân thủ quy định","B":"Mức độ tin tưởng cao hơn giữa các bên liên quan (Higher trust among stakeholders)","C":"Quy trình phát triển chậm hơn","D":"Cấu trúc quyền lực phân cấp hơn"},"answerDisplay":"B. Higher trust among stakeholders","concept":"• Văn hóa đạo đức củng cố lòng tin của khách hàng, đối tác, nhân viên và cơ quan quản lý đối với tổ chức.","whyCorrect":"• Niềm tin cao hơn từ các bên liên quan là tài sản chiến lược bền vững nhất do văn hóa đạo đức tạo ra.","whyWrong":{"A":"• Văn hóa đạo đức làm tăng tuân thủ quy định.","C":"• Quy trình chuẩn hóa đạo đức làm tăng hiệu quả chứ không gây trì trệ.","D":"• Đạo đức thúc đẩy minh bạch chứ không tạo thêm quyền lực phân cấp độc đoán."}}},{"id":57,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":57,"chooseType":"Choose 1 answer","question":"What makes ethical leadership crucial in the data-driven age?","options":{"A":"It focuses solely on profit","B":"It empowers ethical culture and trust","C":"It allows ignoring stakeholders","D":"It prevents communication"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Điều gì làm cho lãnh đạo đạo đức trở nên quan trọng trong kỷ nguyên dựa trên dữ liệu?","optionsVi":{"A":"Nó chỉ tập trung vào lợi nhuận","B":"Nó thúc đẩy văn hóa đạo đức và niềm tin (It empowers ethical culture and trust)","C":"Nó cho phép bỏ qua các bên liên quan","D":"Nó ngăn cản sự giao tiếp"},"answerDisplay":"B. It empowers ethical culture and trust","concept":"• Trong thời đại AI & Big Data, lãnh đạo đạo đức giữ vai trò la bàn định hướng cho việc sử dụng dữ liệu có trách nhiệm.","whyCorrect":"• Thúc đẩy văn hóa đạo đức và xây dựng lòng tin giúp tổ chức phát triển bền vững trong kỷ nguyên số.","whyWrong":{"A":"• Chỉ tập trung lợi nhuận là lãnh đạo thuần thương mại.","C":"• Bỏ qua stakeholders là thất bại quản trị.","D":"• Ngăn cản giao tiếp gây chia rẽ tổ chức."}}},{"id":58,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":58,"chooseType":"Choose 1 answer","question":"Which expression best characterizes what a company or organizational culture is?","options":{"A":"\"This is how we want this done.\"","B":"\"This is how things are done around here.\"","C":"\"It is what it is.\"","D":"\"This is what we're told to do.\""},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Câu nói nào sau đây thể hiện rõ nhất bản chất văn hóa của một công ty hoặc tổ chức?","optionsVi":{"A":"\"Đây là cách chúng tôi muốn điều này được thực hiện.\"","B":"\"Đây là cách mọi việc được thực hiện ở đây.\" (\"This is how things are done around here.\")","C":"\"Nó là như vậy rồi.\"","D":"\"Đây là những gì chúng tôi được bảo phải làm.\""},"answerDisplay":"B. \"This is how things are done around here.\"","concept":"• Văn hóa doanh nghiệp là tập hợp các thói quen, hành vi và chuẩn mực ngầm được mọi người thực hành hàng ngày ('How things are done around here').","whyCorrect":"• Cụm từ phản ánh chính xác bản chất thực tế vận hành của văn hóa tổ chức vượt trên cả khẩu hiệu lý thuyết.","whyWrong":{"A":"• Đây chỉ là mong muốn chủ quan của quản lý.","C":"• Đây là thái độ buông xuôi.","D":"• Đây là sự tuân thủ thụ động."}}},{"id":59,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":59,"chooseType":"Choose 1 answer","question":"What is the most effective way to measure ethical implementation success?","options":{"A":"Financial metrics only","B":"Combination of stakeholder feedback, incident tracking, and outcome assessment","C":"Legal compliance scores only","D":"Technical performance metrics only"},"answer":"B","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Cách hiệu quả nhất để đo lường thành công của việc triển khai đạo đức trong tổ chức là gì?","optionsVi":{"A":"Chỉ dựa vào các chỉ số tài chính","B":"Kết hợp phản hồi của các bên liên quan, theo dõi sự cố và đánh giá kết quả (Combination of stakeholder feedback, incident tracking, and outcome assessment)","C":"Chỉ dựa vào điểm tuân thủ pháp lý","D":"Chỉ dựa vào các chỉ số hiệu năng kỹ thuật"},"answerDisplay":"B. Combination of stakeholder feedback, incident tracking, and outcome assessment","concept":"• Đo lường thực thi đạo đức đòi hỏi cách tiếp cận toàn diện đa chiều (Triangulation) kết hợp phản hồi, dữ liệu sự cố và tác động thực tế.","whyCorrect":"• Kết hợp cả 3 nguồn dữ liệu cung cấp bức tranh toàn cảnh chính xác về hiệu quả triển khai văn hóa đạo đức.","whyWrong":{"A":"• Tài chính không phản ánh mức độ tuân thủ đạo đức.","C":"• Điểm tuân thủ chỉ phản ánh điều kiện tối thiểu hình thức.","D":"• Kỹ thuật thuần túy bỏ qua khía cạnh con người và xã hội."}}},{"id":60,"task":"sp26_fe_re","taskLabel":"SP26 FE RE","num":60,"chooseType":"Choose 1 answer","question":"How can fair competition in data-driven technologies foster innovation and trust?","options":{"A":"By encouraging diverse ideas and approaches","B":"By limiting access to new technologies","C":"By enforcing uniformity in data processing methods","D":"By prioritizing profit over ethical standards"},"answer":"A","source":"ITE302c_SP26_FE_RE","explanation":{"questionVi":"Cạnh tranh công bằng trong các công nghệ dựa trên dữ liệu có thể thúc đẩy sự đổi mới và lòng tin như thế nào?","optionsVi":{"A":"Bằng cách khuyến khích các ý tưởng và cách tiếp cận đa dạng (By encouraging diverse ideas and approaches)","B":"Bằng cách giới hạn quyền truy cập vào các công nghệ mới","C":"Bằng cách bắt buộc áp dụng đồng nhất các phương pháp xử lý dữ liệu","D":"Bằng cách ưu tiên lợi nhuận hơn các tiêu chuẩn đạo đức"},"answerDisplay":"A. By encouraging diverse ideas and approaches","concept":"• Cạnh tranh công bằng ngăn chặn độc quyền, tạo môi trường cho các ý tưởng và giải pháp công nghệ đa dạng phát triển.","whyCorrect":"• Đa dạng giải pháp và ý tưởng kích thích sáng tạo đổi mới và mang lại nhiều lựa chọn tốt hơn cho người dùng.","whyWrong":{"B":"• Giới hạn truy cập kìm hãm sự đổi mới.","C":"• Bắt buộc đồng nhất làm triệt tiêu tính sáng tạo đột phá.","D":"• Ưu tiên lợi nhuận bất chấp đạo đức phá hủy lòng tin công chúng."}}},{"id":1,"task":"sp26_fe","taskLabel":"SP26 FE","num":1,"chooseType":"Choose 1 answer","question":"Which type of bias occurs when training data is not representative of the population?","options":{"A":"Confirmation bias","B":"Selection bias","C":"Anchoring bias","D":"Availability bias"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Loại thiên vị nào xảy ra khi dữ liệu huấn luyện không đại diện cho tổng thể quần thể?","optionsVi":{"A":"Confirmation bias (Thiên vị xác nhận)","B":"Selection bias (Thiên vị lựa chọn)","C":"Anchoring bias (Thiên vị neo)","D":"Availability bias (Thiên vị sẵn có)"},"answerDisplay":"B. Selection bias","concept":"• Selection bias (Thiên vị lựa chọn) xảy ra khi quy trình chọn mẫu dữ liệu không đại diện đúng cho quần thể thực tế.","whyCorrect":"• Khi tập dữ liệu huấn luyện thiếu tính đại diện, mô hình AI/ML sẽ đưa ra dự đoán lệch lạc so với thực tế.","whyWrong":{"A":"• Confirmation bias là thiên vị khi chỉ tìm kiếm thông tin củng cố niềm tin cá nhân sẵn có.","C":"• Anchoring bias là xu hướng phụ thuộc quá nhiều vào thông tin đầu tiên nhận được.","D":"• Availability bias là đánh giá dựa trên thông tin dễ nhớ ra nhất trong trí nhớ."}}},{"id":2,"task":"sp26_fe","taskLabel":"SP26 FE","num":2,"chooseType":"Choose 1 answer","question":"Why is stakeholder communication vital in managing ethical risk?","options":{"A":"To improve company branding only","B":"To ensure stakeholder expectations and values are understood","C":"To avoid legal responsibilities","D":"To control product pricing strategies"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Tại sao việc giao tiếp với các bên liên quan (stakeholders) lại thiết yếu trong quản lý rủi ro đạo đức?","optionsVi":{"A":"Chỉ để cải thiện hình ảnh thương hiệu công ty","B":"Để đảm bảo kỳ vọng và giá trị của các bên liên quan được thấu hiểu","C":"Để né tránh các trách nhiệm pháp lý","D":"Để kiểm soát chiến lược định giá sản phẩm"},"answerDisplay":"B. To ensure stakeholder expectations and values are understood","concept":"• Giao tiếp với các bên liên quan giúp xác định đúng rủi ro đạo đức và kỳ vọng của cộng đồng đối với hệ thống AI.","whyCorrect":"• Thấu hiểu kỳ vọng và giá trị đạo đức của các bên liên quan là chìa khóa để thiết kế hệ thống có trách nhiệm.","whyWrong":{"A":"• Quản lý rủi ro đạo đức hướng tới giá trị cốt lõi chứ không chỉ cải thiện thương hiệu bề ngoài.","C":"• Né tránh trách nhiệm pháp lý là hành vi vi phạm đạo đức doanh nghiệp.","D":"• Kiểm soát chiến lược định giá sản phẩm thuộc lĩnh vực kinh doanh thương mại."}}},{"id":3,"task":"sp26_fe","taskLabel":"SP26 FE","num":3,"chooseType":"Choose 1 answer","question":"Which of the following best describes capability caution as referenced in the Asilomar Al Principles?","options":{"A":"If there is no understanding of the internal mechanisms of Al, then Al development should be halted","B":"Given a lack of consensus, we should avoid strong assumptionis regarding upper limits on future Al capabilities.","C":"Should there be a greater reliance on Al, measures should be taken to ensure that humans are still capable of finding work.","D":"We should keep limits on on what artificial general intelligence (AGI) is capable of"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất về 'Cẩn trọng khả năng' (Capability Caution) trong Nguyên tắc AI Asilomar?","optionsVi":{"A":"Nếu không hiểu cơ chế bên trong của AI thì phải dừng phát triển AI","B":"Khi chưa có sự đồng thuận, chúng ta nên tránh đưa ra giả định mạnh mẽ về giới hạn trên của năng lực AI tương lai","C":"Nếu phụ thuộc nhiều vào AI, phải có biện pháp đảm bảo con người vẫn tìm được việc làm","D":"Chúng ta nên đặt giới hạn cho những gì AI tổng quát (AGI) có thể làm"},"answerDisplay":"B. Given a lack of consensus, we should avoid strong assumptionis regarding upper limits on future Al capabilities.","concept":"• Capability Caution (Asilomar Principle 22) khuyên tránh chủ quan đưa ra trần giới hạn năng lực AI trong tương lai.","whyCorrect":"• Việc không đặt giả định chủ quan giúp cộng đồng chuẩn bị tốt hơn trước các rủi ro tiềm ẩn của AGI.","whyWrong":{"A":"• Đây là nội dung của nguyên tắc về tính giải thích và minh bạch (Explainability).","C":"• Đây thuộc nguyên tắc về giá trị con người và thị trường lao động.","D":"• Đặt giới hạn cứng là chính sách quản chế, không phải tinh thần Capability Caution."}}},{"id":4,"task":"sp26_fe","taskLabel":"SP26 FE","num":4,"chooseType":"Choose 1 answer","question":"Which of the following is a notable aspect of the Personal Information Protection and Electronic Documents Act (PIPEDA) when compared to similar laws and regulations?","options":{"A":"Its exclusive focus on a single domain rather than a breadth of domains","B":"The early date of its inauguration","C":"Its nationwide scope and specific national focus","D":"A stipulation to continue providing service even if data usage is denied"},"answer":"C","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Đặc điểm nổi bật của Đạo luật PIPEDA (Canada) khi so sánh với các luật tương tự là gì?","optionsVi":{"A":"Chỉ tập trung vào một lĩnh vực duy nhất thay vì mở rộng nhiều lĩnh vực","B":"Thời điểm ban hành rất sớm","C":"Phạm vi toàn quốc và tập trung vào mục tiêu quốc gia cụ thể (Canada)","D":"Quy định tiếp tục cung cấp dịch vụ ngay cả khi người dùng từ chối chia sẻ dữ liệu"},"answerDisplay":"C. Its nationwide scope and specific national focus","concept":"• PIPEDA là đạo luật quyền riêng tư dữ liệu thương mại áp dụng trên toàn bộ lãnh thổ Canada.","whyCorrect":"• PIPEDA thiết lập khung pháp lý bảo vệ dữ liệu tư nhân đồng bộ áp dụng cho mọi tổ chức trên toàn quốc Canada.","whyWrong":{"A":"• PIPEDA áp dụng rộng rãi cho hầu hết các hoạt động thương mại tư nhân.","B":"• Thời gian ban hành năm 2000 không phải đặc điểm phân biệt cốt lõi.","D":"• Tổ chức được quyền từ chối dịch vụ nếu dữ liệu đó là thiết yếu cho hợp đồng."}}},{"id":5,"task":"sp26_fe","taskLabel":"SP26 FE","num":5,"chooseType":"Choose 1 answer","question":"What does informed consent require in the context of Al?","options":{"A":"Legal approval of Al patents","B":"Clear communication of data use and user permission","C":"Selling user data to partners","D":"Disabling all tracking features"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Sự chấp thuận có can thiệp (Informed Consent) yêu cầu điều gì trong bối cảnh AI?","optionsVi":{"A":"Sự phê duyệt pháp lý cho các bằng sáng chế AI","B":"Giao tiếp rõ ràng về việc sử dụng dữ liệu và được sự cho phép của người dùng","C":"Bán dữ liệu người dùng cho các đối tác","D":"Tắt tất cả các tính năng theo dõi"},"answerDisplay":"B. Clear communication of data use and user permission","concept":"• Informed Consent đòi hỏi người dùng được giải thích minh bạch dữ liệu dùng làm gì trước khi tự nguyện cho phép.","whyCorrect":"• Thông tin minh bạch và sự đồng ý tự nguyện của người dùng là nền tảng đạo đức thu thập dữ liệu.","whyWrong":{"A":"• Bằng sáng chế thuộc về sở hữu trí tuệ công nghệ.","C":"• Bán dữ liệu khi chưa được cho phép là vi phạm quyền riêng tư nghiêm trọng.","D":"• Tắt tính năng theo dõi không phải là quá trình thông tin và xin phép chấp thuận."}}},{"id":6,"task":"sp26_fe","taskLabel":"SP26 FE","num":6,"chooseType":"Choose 1 answer","question":"If you were faced with an Al system that identifies exactly what individuals will be infected in a pandemic of a novel disease before the first case occurs, what kind of Al is this?","options":{"A":"Narrow Al","B":"General AI","C":"Superintelligence","D":"Basic Al"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Nếu bạn đối mặt với một hệ thống AI có khả năng xác định chính xác những cá nhân nào sẽ bị nhiễm bệnh trong một đại dịch trước khi ca bệnh đầu tiên xuất hiện, đây là loại AI nào?","optionsVi":{"A":"AI hẹp (Narrow AI)","B":"AI tổng quát (General AI)","C":"Siêu trí tuệ (Superintelligence)","D":"AI cơ bản (Basic AI)"},"answerDisplay":"A. Narrow Al","concept":"• Narrow AI (AI chuyên biệt) là hệ thống AI được tối ưu cho duy nhất một tác vụ cụ thể.","whyCorrect":"• Dù kết quả dự đoán đại dịch cực kỳ siêu việt, hệ thống vẫn chỉ giải quyết 1 bài toán chuyên biệt nên vẫn thuộc Narrow AI.","whyWrong":{"B":"• General AI (AGI) có khả năng học và làm mọi nhiệm vụ trí tuệ đa dạng như con người.","C":"• Superintelligence vượt xa trí tuệ con người trên toàn bộ các lĩnh vực.","D":"• Basic AI không phải thuật ngữ phân loại tiêu chuẩn."}}},{"id":7,"task":"sp26_fe","taskLabel":"SP26 FE","num":7,"chooseType":"Choose 1 answer","question":"Which of the following resources does the National Institute of Standards and Technology (NIST) provide to organizations?","options":{"A":"Measurement technologies","B":"Reference materials","C":"Security tools","D":"Industrial configurations"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Tài nguyên nào sau đây do Viện Tiêu chuẩn và Công nghệ Quốc gia (NIST) cung cấp cho các tổ chức?","optionsVi":{"A":"Các công nghệ đo lường","B":"Tài liệu tham khảo và khung tiêu chuẩn (Reference materials)","C":"Các công cụ bảo mật phần mềm","D":"Cấu hình công nghiệp"},"answerDisplay":"B. Reference materials","concept":"• NIST cung cấp các tài liệu tham khảo, khung quản trị rủi ro AI (AI Risk Management Framework) và chuẩn mực kỹ thuật cho tổ chức.","whyCorrect":"• Các tài liệu tham khảo và khung tiêu chuẩn của NIST giúp tổ chức áp dụng quy trình an toàn và đạo đức.","whyWrong":{"A":"• NIST phát triển tiêu chuẩn đo lường nhưng sản phẩm cung cấp cho quản trị tổ chức là các tài liệu hướng dẫn.","C":"• NIST không bán hay cung cấp công cụ phần mềm thương mại.","D":"• Cấu hình công nghiệp cụ thể thuộc trách nhiệm của nhà sản xuất thiết bị."}}},{"id":8,"task":"sp26_fe","taskLabel":"SP26 FE","num":8,"chooseType":"Choose 1 answer","question":"Which method can be implemented to effectively communicate with the media during an ethical crisis?","options":{"A":"Provide regular updates to keep the media informed","B":"Ignore media inquiries until the crisis resolves","C":"Offer incentives for positive coverage","D":"Release information only to major news networks"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Phương pháp nào có thể được triển khai để truyền thông hiệu quả với truyền thông/báo chí trong khủng hoảng đạo đức?","optionsVi":{"A":"Cung cấp cập nhật thường xuyên để giữ thông tin minh bạch cho truyền thông","B":"Bỏ qua các yêu cầu của truyền thông cho đến khi khủng hoảng tự giải quyết","C":"Cung cấp lợi ích tài chính để báo chí đưa tin tích cực","D":"Chỉ phát hành thông tin cho các mạng tin tức lớn"},"answerDisplay":"A. Provide regular updates to keep the media informed","concept":"• Truyền thông khủng hoảng đạo đức đòi hỏi sự chủ động, minh bạch và cung cấp thông tin cập nhật liên tục.","whyCorrect":"• Cập nhật thông tin thường xuyên giúp duy trì niềm tin và ngăn chặn tin đồn thất thiệt trong khủng hoảng.","whyWrong":{"B":"• Bỏ qua báo chí khiến tin đồn lan rộng và làm suy giảm nghiêm trọng niềm tin công chúng.","C":"• Mua chuộc báo chí là vi phạm đạo đức truyền thông nghiêm trọng.","D":"• Giới hạn kênh thông tin làm mất đi tính minh bạch với các bên liên quan."}}},{"id":9,"task":"sp26_fe","taskLabel":"SP26 FE","num":9,"chooseType":"Choose 1 answer","question":"What percentage of frameworks include privacy as core tenet?","options":{"A":"50%","B":"85%","C":"25%","D":"99%"},"answer":"C","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Tỷ lệ phần trăm các khung làm việc (frameworks) bao gồm quyền riêng tư như một nguyên tắc cốt lõi là bao nhiêu?","optionsVi":{"A":"50%","B":"85%","C":"25%","D":"99%"},"answerDisplay":"C. 25%","concept":"• Báo cáo khảo sát các khung quản trị AI/IT chỉ ra rằng khoảng 25% các khung đạo đức xem quyền riêng tư là nguyên tắc cốt lõi ban đầu.","whyCorrect":"• 25% là con số thống kê chính xác trong nghiên cứu tổng hợp về các tiêu chuẩn đạo đức dữ liệu.","whyWrong":{"A":"• 50% không phải con số ghi nhận trong nghiên cứu khảo sát khung quản trị.","B":"• 85% là con số quá cao so với thực tế triển khai khung bảo mật riêng tư.","D":"• 99% không phản ánh đúng thực trạng đa dạng của các khung làm việc đạo đức."}}},{"id":10,"task":"sp26_fe","taskLabel":"SP26 FE","num":10,"chooseType":"Choose 1 answer","question":"An example of automation bias is","options":{"A":"using biased survey data instead of parsed survey data","B":"using parsed twitter data over parsed Facebook data","C":"using new data over existing data","D":"using scraped twitter data over survey data"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Một ví dụ về thiên vị tự động hóa (Automation Bias) là gì?","optionsVi":{"A":"Sử dụng dữ liệu khảo sát bị thiên vị thay vì dữ liệu khảo sát được phân tích","B":"Tin tưởng sử dụng dữ liệu Twitter đã phân tích thay vì dữ liệu Facebook dựa trên sự tin tưởng quá mức vào thuật toán","C":"Sử dụng dữ liệu mới thay vì dữ liệu hiện có","D":"Sử dụng dữ liệu Twitter cào được thay vì dữ liệu khảo sát"},"answerDisplay":"B. using parsed twitter data over parsed Facebook data","concept":"• Automation Bias là xu hướng con người tin tưởng và ưu tiên kết quả đầu ra của hệ thống tự động/máy tính hơn nhận thức và các nguồn dữ liệu khác.","whyCorrect":"• Việc ưu tiên dữ liệu từ công cụ tự động hóa mà không kiểm chứng thiên vị phản ánh đúng bản chất Automation Bias.","whyWrong":{"A":"• Việc chọn sai dữ liệu khảo sát liên quan đến Sampling Bias.","C":"• Ưu tiên dữ liệu mới liên quan đến Recency Bias.","D":"• Cào dữ liệu Twitter thuộc về phương pháp thu thập dữ liệu."}}},{"id":11,"task":"sp26_fe","taskLabel":"SP26 FE","num":11,"chooseType":"Choose 1 answer","question":"What is one outcome of not considering ethics in algorithm design?","options":{"A":"Lower electricity bilis","B":"Enhanced system performance","C":"Discriminatory or unsafe results","D":"Better customer loyalty"},"answer":"C","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Hậu quả nào xảy ra khi không xem xét các yếu tố đạo đức trong thiết kế thuật toán?","optionsVi":{"A":"Hóa đơn tiền điện thấp hơn","B":"Hiệu suất hệ thống được nâng cao","C":"Kết quả phân biệt đối xử hoặc không an toàn","D":"Lòng trung thành của khách hàng tốt hơn"},"answerDisplay":"C. Discriminatory or unsafe results","concept":"• Bỏ qua đạo đức trong thiết kế thuật toán sẽ tạo ra các quyết định thiên vị, phân biệt đối xử xã hội và nguy cơ gây hại cho người dùng.","whyCorrect":"• Thiếu xem xét đạo đức trực tiếp dẫn tới kết quả đầu ra bị phân biệt đối xử bất công hoặc nguy hiểm.","whyWrong":{"A":"• Tiền điện thuộc về tiêu thụ điện năng hạ tầng máy chủ.","B":"• Bỏ qua đạo đức không giúp tăng hiệu suất thuật toán mà làm giảm độ tin cậy.","D":"• Kết quả thiên vị sẽ làm sụt giảm nghiêm trọng lòng tin của khách hàng."}}},{"id":12,"task":"sp26_fe","taskLabel":"SP26 FE","num":12,"chooseType":"Choose 1 answer","question":"How do Al and other data-driven technologies use probability?","options":{"A":"By determining the objective likelihood of some event happening","B":"By estimating the likelihood of some event happening without input data","C":"By providing a model of belief about the likelihood of some event happening","D":"By guaranteeing that some event will occur with 100% likelihood"},"answer":"C","source":"ITE302c_SP26_FE","explanation":{"questionVi":"AI và các công nghệ dựa trên dữ liệu sử dụng xác suất như thế nào?","optionsVi":{"A":"Bằng cách xác định khả năng khách quan tuyệt đối của một sự kiện xảy ra","B":"Bằng cách ước tính khả năng xảy ra sự kiện mà không cần dữ liệu đầu vào","C":"Bằng cách cung cấp một mô hình niềm tin (model of belief) về khả năng xảy ra của một sự kiện dựa trên dữ liệu","D":"Bằng cách đảm bảo rằng sự kiện chắc chắn xảy ra với khả năng 100%"},"answerDisplay":"C. By providing a model of belief about the likelihood of some event happening","concept":"• AI sử dụng xác suất Bayesian và thống kê để mô hình hóa niềm tin/đánh giá khả năng xảy ra của sự kiện dựa trên bằng chứng dữ liệu có sẵn.","whyCorrect":"• AI không khẳng định tuyệt đối mà đưa ra xác suất dự đoán (model of belief) dựa trên phân phối dữ liệu.","whyWrong":{"A":"• AI không xác định được xác suất khách quan tuyệt đối khi dữ liệu luôn có độ nhiễu.","B":"• Mô hình xác suất bắt buộc phải dựa vào dữ liệu đầu vào để tính toán.","D":"• Rất ít dự đoán AI đạt mức đảm bảo chắc chắn 100%."}}},{"id":13,"task":"sp26_fe","taskLabel":"SP26 FE","num":13,"chooseType":"Choose 1 answer","question":"Which of the following is a key element of communications with internal and external stakeholders regarding an organization's ethics policies?","options":{"A":"Simple to follow examples","B":"Daily communications","C":"Dense procedural descriptions","D":"Flexible verbiage"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Yếu tố đạo đức nào cần xem xét khi thiết kế các thuật toán AI?","optionsVi":{"A":"Tối đa hóa việc thu thập dữ liệu mà không cho người dùng biết","B":"Đảm bảo tính công bằng và minh bạch trong quá trình ra quyết định","C":"Ưu tiên tốc độ hơn độ chính xác","D":"Hạn chế công chúng tiếp cận các hướng dẫn đạo đức"},"answerDisplay":"B. Ensuring fairness and transparency in decision-making","concept":"• Thiết kế thuật toán AI có đạo đức đòi hỏi hai trụ cột cốt lõi là Tính công bằng (Fairness) và Tính minh bạch (Transparency).","whyCorrect":"• Đảm bảo công bằng và minh bạch giúp hệ thống đưa ra quyết định không thiên vị và có thể kiểm toán được.","whyWrong":{"A":"• Thu thập lén lút là vi phạm nghiêm trọng nguyên tắc Informed Consent.","C":"• Ưu tiên tốc độ mà bỏ qua chính xác làm tăng nguy cơ sai sót gây hại.","D":"• Hạn chế công khai hướng dẫn đi ngược lại nguyên tắc minh bạch."}}},{"id":14,"task":"sp26_fe","taskLabel":"SP26 FE","num":14,"chooseType":"Choose 1 answer","question":"In which of the following could STRIDE or VAST classifications be applied?","options":{"A":"Black box mitigation methods","B":"Network optimization tools","C":"Bias mitigation techniques","D":"Threat modeling or analysis tools"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Thuật ngữ 'AI có thể giải thích được' (XAI - Explainable AI) đề cập đến điều gì?","optionsVi":{"A":"Các hệ thống AI có thể mô tả logic bên trong và các quyết định của chúng theo cách con người hiểu được","B":"Các hệ thống AI chỉ vận hành bằng thư viện mã nguồn mở rõ ràng","C":"Các hệ thống AI thay thế toàn bộ vai trò giải thích của con người","D":"Các hệ thống AI tự động dịch thuật văn bản"},"answerDisplay":"A. AI systems that can describe their internal logic and decisions in human-understandable terms","concept":"• Explainable AI (XAI) giải quyết vấn đề hộp đen (Black Box) bằng cách giải trình lý do đưa ra kết quả dự đoán.","whyCorrect":"• XAI giúp chuyên gia và người dùng hiểu rõ căn cứ để đưa ra quyết định của mô hình AI.","whyWrong":{"B":"• Mã nguồn mở không đồng nghĩa với việc mô hình học máy đó giải thích được kết quả.","C":"• XAI không thay thế con người mà hỗ trợ con người kiểm soát quyết định.","D":"• Dịch thuật văn bản là tác động của NLP, không phải định nghĩa XAI."}}},{"id":15,"task":"sp26_fe","taskLabel":"SP26 FE","num":15,"chooseType":"Choose 3 answers","question":"Which of the following statements are promoted by the categorical imperative? (Select three)","options":{"A":"You have a moral duty to choose your actions based on their potential outcomes","B":"Act in such a way that your actions may become a universal law","C":"Don't treat people as a means to an end; treat them always as an end.","D":"Each person must use reason to will moral laws"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Mục tiêu chính của quản trị dữ liệu (Data Governance) là gì?","optionsVi":{"A":"Đảm bảo tính sẵn có, tính khả dụng, tính toàn vẹn và tính bảo mật của dữ liệu trong toàn tổ chức","B":"Xóa toàn bộ dữ liệu lưu trữ hàng năm","C":"Thay thế chuyên viên phân tích dữ liệu bằng bot tự động","D":"Thương mại hóa toàn bộ dữ liệu khách hàng không giới hạn"},"answerDisplay":"A. Ensuring data availability, usability, integrity, and security across an organization","concept":"• Quản trị dữ liệu (Data Governance) thiết lập quyền hạn, trách nhiệm và chính sách duy trì chất lượng và an toàn dữ liệu.","whyCorrect":"• Bốn trụ cột cốt lõi của Data Governance bao gồm Availability, Usability, Integrity và Security.","whyWrong":{"B":"• Xóa dữ liệu hàng năm gây mất mát tài sản thông tin của doanh nghiệp.","C":"• Bot tự động hỗ trợ chứ không thay thế hoàn toàn vai trò quản trị của con người.","D":"• Bán dữ liệu vô danh sách vi phạm quyền riêng tư nghiêm trọng."}}},{"id":16,"task":"sp26_fe","taskLabel":"SP26 FE","num":16,"chooseType":"Choose 1 answer","question":"Which technique helps improve algorithmic faimess?","options":{"A":"Using larger datasets only","B":"Bias testing and diverse training data","C":"Increasing processing speed","D":"Reducing system complexity"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Kỹ thuật nào giúp cải thiện tính công bằng của thuật toán (Algorithmic Fairness)?","optionsVi":{"A":"Chỉ sử dụng các tập dữ liệu lớn hơn","B":"Kiểm thử thiên vị và đa dạng hóa dữ liệu huấn luyện (Bias testing and diverse training data)","C":"Tăng tốc độ xử lý của máy chủ","D":"Giảm độ phức tạp của hệ thống"},"answerDisplay":"B. Bias testing and diverse training data","concept":"• Tính công bằng thuật toán đòi hỏi phát hiện rủi ro thiên vị qua kiểm thử (Bias Testing) và sử dụng tập dữ liệu đại diện đa dạng.","whyCorrect":"• Kiểm thử thiên vị phát hiện độ lệch kết quả và dữ liệu đa dạng giúp mô hình hoạt động công bằng cho mọi nhóm đối tượng.","whyWrong":{"A":"• Dữ liệu lớn hơn nhưng nếu vẫn bị thiên vị thì mô hình chỉ học sâu thêm sự thiên vị đó.","C":"• Tốc độ xử lý thuộc về hiệu năng phần cứng, không thay đổi độ công bằng của thuật toán.","D":"• Giảm độ phức tạp không đảm bảo loại bỏ được thiên vị trong dữ liệu."}}},{"id":17,"task":"sp26_fe","taskLabel":"SP26 FE","num":17,"chooseType":"Choose 1 answer","question":"What is non-maleficence?","options":{"A":"The principle of doing no harm","B":"The principle of having no bias","C":"The principle of having no security risk.","D":"The principle of having security risk"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Yếu tố nào phân biệt rõ nhất giữa AI tổng quát (AGI) và AI hẹp (Narrow AI)?","optionsVi":{"A":"Khả năng tự học và giải quyết mọi tác vụ trí tuệ của con người trên nhiều lĩnh vực","B":"Tốc độ xử lý tính toán trong 1 giây","C":"Dung lượng bộ nhớ lưu trữ mô hình","D":"Số lượng ngôn ngữ lập trình được sử dụng"},"answerDisplay":"A. Ability to learn and solve any intellectual task across multiple domains","concept":"• General AI (AGI) có trí tuệ linh hoạt đa năng như con người, khác biệt với Narrow AI chỉ xử lý 1 tác vụ chuyên biệt.","whyCorrect":"• Khả năng tự học và giải quyết bài toán đa lĩnh vực là đặc trưng cốt lõi của AGI.","whyWrong":{"B":"• Tốc độ xử lý là chỉ số hiệu năng máy tính, không định nghĩa AGI.","C":"• Dung lượng bộ nhớ phụ thuộc vào hạ tầng lưu trữ.","D":"• Ngôn ngữ lập trình là công cụ phát triển phần mềm."}}},{"id":18,"task":"sp26_fe","taskLabel":"SP26 FE","num":18,"chooseType":"Choose 1 answer","question":"Which principle emphasizes treating people as ends in themselves, not merely as means?","options":{"A":"Utilitarianism","B":"Virtue ethics","C":"Kantian deontology","D":"Social contract theory"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Nguyên tắc 'Non-maleficence' trong đạo đức công nghệ có nghĩa là gì?","optionsVi":{"A":"Nguyên tắc tối đa hóa lợi nhuận tài chính","B":"Nguyên tắc không gây hại (Do no harm)","C":"Nguyên tắc tự động hóa mọi quy trình","D":"Nguyên tắc công khai toàn bộ mã nguồn"},"answerDisplay":"B. Principle of doing no harm","concept":"• Non-maleficence (Không gây hại) đòi hỏi hệ thống công nghệ không được gây ra tổn hại vật lý, tinh thần hay xã hội cho con người.","whyCorrect":"• Yêu cầu cốt lõi của Non-maleficence là phòng ngừa và tránh gây tổn hại cho người dùng và cộng đồng.","whyWrong":{"A":"• Tối đa hóa lợi nhuận thuộc về mục tiêu thương mại doanh nghiệp.","C":"• Tự động hóa là mục tiêu kỹ thuật, không phải nguyên tắc đạo đức.","D":"• Công khai mã nguồn thuộc về Open Source."}}},{"id":19,"task":"sp26_fe","taskLabel":"SP26 FE","num":19,"chooseType":"Choose 1 answer","question":"Which element is essential for system accountability?","options":{"A":"Complete automation","B":"Clear responsibility assignment","C":"Maximum data collection","D":"Fastest processing speed"},"answer":"C","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Thuật ngữ 'Algorithmic Bias' (Thiên vị thuật toán) phát sinh từ nguyên nhân chính nào?","optionsVi":{"A":"Lỗi phần cứng của bộ vi xử lý CPU","B":"Đường truyền internet bị ngắt kết nối","C":"Dữ liệu huấn luyện bị lệch hoặc định kiến trong thiết kế thuật toán","D":"Do máy tính bị nhiễm virus"},"answerDisplay":"C. Biased training data or prejudiced algorithmic design","concept":"• Thiên vị thuật toán phản ánh sự lệch lạc sẵn có trong tập dữ liệu quá khứ hoặc định kiến vô thức của nhà thiết kế.","whyCorrect":"• Dữ liệu huấn luyện không công bằng sẽ làm thuật toán tái lập và trầm trọng hóa sự thiên vị đó.","whyWrong":{"A":"• Lỗi CPU là sự cố phần cứng.","B":"• Gián đoạn internet thuộc về đường truyền mạng.","D":"• Virus là phần mềm độc hại an ninh mạng."}}},{"id":20,"task":"sp26_fe","taskLabel":"SP26 FE","num":20,"chooseType":"Choose 1 answer","question":"What is the benefit of hosting a virtual reality press conference over a traditional in-person press conference?","options":{"A":"It will be easier to communicate your overall message to your audience.","B":"The conference will be easily accessible to all willing participants","C":"The conference can be interactive without the participants needing to be co-located","D":"The participants will be impressed by your leveraging of new and exciting technologies"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Vai trò của đánh giá tác động riêng tư (PIA - Privacy Impact Assessment) là gì?","optionsVi":{"A":"Phân tích và xác định các rủi ro xâm phạm quyền riêng tư trước khi triển khai hệ thống dữ liệu","B":"Định giá tiền tệ cho dữ liệu cá nhân","C":"Tăng dung lượng nén của cơ sở dữ liệu","D":"Tự động gửi email quảng cáo tới khách hàng"},"answerDisplay":"A. Analyzing and identifying privacy risks prior to system deployment","concept":"• Privacy Impact Assessment (PIA) là quy trình chủ động kiểm toán rủi ro riêng tư trong chu kỳ phát triển dự án.","whyCorrect":"• Đánh giá chủ quan rủi ro riêng tư trước khi triển khai giúp phòng ngừa vi phạm pháp luật và bảo vệ người dùng.","whyWrong":{"B":"• PIA không dùng để định giá bán dữ liệu.","C":"• Nén cơ sở dữ liệu là tối ưu lưu trữ.","D":"• Gửi email quảng cáo là hoạt động marketing."}}},{"id":21,"task":"sp26_fe","taskLabel":"SP26 FE","num":21,"chooseType":"Choose 1 answer","question":"Why is deciding how to act using moral reasoning not always a feasible goal for human beings?","options":{"A":"Most people are not educated on normative ethical theories and therefore cannot perform true moral reasoning","B":"Moral reasoning is too complicated to apply to a real-world situation","C":"Moral reasoning has few tangible benefits for most people.","D":"Human decision making is often influenced by emotion and not logic."},"answer":"D","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Tại sao việc quyết định hành động bằng suy luận đạo đức không phải lúc nào cũng là mục tiêu khả thi đối với con người?","optionsVi":{"A":"Hầu hết mọi người không được học về các thuyết đạo đức chuẩn mực","B":"Suy luận đạo đức quá phức tạp để áp dụng vào thực tế","C":"Suy luận đạo đức mang lại ít lợi ích thiết thực","D":"Quyết định của con người thường chịu ảnh hưởng mạnh mẽ bởi cảm xúc thay vì logic thuần túy"},"answerDisplay":"D. Human decision making is often influenced by emotion and not logic.","concept":"• Tâm lý học nhận thức chỉ ra rằng quyết định thực tế của con người bị chi phối mạnh mẽ bởi cảm xúc và thiên vị nhận thức, thay vì các mô hình suy luận đạo đức lý tưởng.","whyCorrect":"• Ảnh hưởng của cảm xúc khiến con người khó duy trì sự hợp lý và logic thuần túy khi ra quyết định đạo đức.","whyWrong":{"A":"• Thiếu học vấn không ngăn cản suy luận đạo đức tự nhiên của con người.","B":"• Suy luận đạo đức hoàn toàn có thể áp dụng vào thực tế.","C":"• Đạo đức mang lại giá trị gắn kết và sự tin tưởng rất lớn cho xã hội."}}},{"id":22,"task":"sp26_fe","taskLabel":"SP26 FE","num":22,"chooseType":"Choose 1 answer","question":"Our goals for building an ethical predictive model include making sure the results are","options":{"A":"precise, explainable, predictable","B":"accurate, precise, fair","C":"precise, methodical, ethical","D":"accurate, fair and explainable"},"answer":"D","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Mục tiêu xây dựng một mô hình dự đoán có đạo đức bao gồm việc đảm bảo kết quả đạt được các tiêu chuẩn nào?","optionsVi":{"A":"Chính xác, giải thích được, dự đoán được","B":"Chính xác, chuẩn xác, công bằng","C":"Chuẩn xác, có phương pháp, có đạo đức","D":"Chính xác, công bằng và có thể giải thích được (Accurate, fair and explainable)"},"answerDisplay":"D. accurate, fair and explainable","concept":"• Ba trụ cột cốt lõi của một mô hình học máy dự đoán có đạo đức bao gồm: Độ chính xác (Accuracy), Tính công bằng (Fairness) và Khả năng giải thích (Explainability).","whyCorrect":"• Đảm bảo chính xác, công bằng và giải thích được giúp mô hình tin cậy và không gây hại bất công.","whyWrong":{"A":"• Dự đoán được (predictable) là đặc tính tính toán, không phản ánh tiêu chí đạo đức cốt lõi.","B":"• Thiếu tiêu chí Khả năng giải thích (Explainability) quan trọng.","C":"• 'Có phương pháp' là kỹ thuật xử lý, chưa đủ bộ ba chuẩn mực đạo đức."}}},{"id":23,"task":"sp26_fe","taskLabel":"SP26 FE","num":23,"chooseType":"Choose 1 answer","question":"Which of the following is a misuse of intellectual property (IP) when it comes to ethical accountability for an organization?","options":{"A":"Collecting retums on investments made in research and development","B":"Filing a patent for the IP that makes non-obvious information known to the public","C":"Enhancing the security posture of a product or service.","D":"Using IP as a defensive mechariism to eschew transparency requirements"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Hành vi nào sau đây là sự lạm dụng sở hữu trí tuệ (IP) liên quan đến trách nhiệm đạo đức của tổ chức?","optionsVi":{"A":"Thu lợi nhuận từ các khoản đầu tư nghiên cứu và phát triển (R&D)","B":"Đầu cơ bằng sáng chế để kiện tụng trục lợi (Patent trolling)","C":"Cấp phép sử dụng sở hữu trí tuệ cho đối tác","D":"Bảo vệ bí mật thương mại theo quy định pháp luật"},"answerDisplay":"B. Patent trolling","concept":"• Patent Trolling (đầu cơ bằng sáng chế) là việc đăng ký/mua bằng sáng chế không để sản xuất mà chỉ để đi kiện tụng đòi tiền bồi thường, kìm hãm đổi mới sáng tạo.","whyCorrect":"• Patent Trolling là hành vi lạm dụng luật sở hữu trí tuệ vi phạm nghiêm trọng đạo đức kinh doanh.","whyWrong":{"A":"• Thu hồi vốn R&D là hoạt động kinh doanh hợp pháp chính đáng.","C":"• Cấp phép IP giúp thương mại hóa công nghệ tích cực.","D":"• Bảo vệ bí mật thương mại là quyền lợi hợp pháp của doanh nghiệp."}}},{"id":24,"task":"sp26_fe","taskLabel":"SP26 FE","num":24,"chooseType":"Choose 1 answer","question":"How can organizations ensure continuous ethical improvement?","options":{"A":"By implementing systems once and forgetting them","B":"Through regular assessment, feedback, and adaptation","C":"By following competitors only","D":"By focusing solely on compliance"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Vấn đề hộp đen (Black Box Problem) là gì?","optionsVi":{"A":"Khi mô hình được triển khai, nhưng các nhà nghiên cứu không thể giải thích lý do tại sao nó đưa ra quyết định đó","B":"Vấn đề tạo ra khi nhà nghiên cứu không thiết lập đúng thuộc tính","C":"Vấn đề khi các tập dữ liệu bị tối màu","D":"Vấn đề lưu trữ dữ liệu an toàn trong thiết bị"},"answerDisplay":"A. When a model is deployed, but researchers are unable to figure out why its making decisions","concept":"• Black Box Problem xảy ra ở các mô hình học sâu phức tạp nơi con người không thể truy xuất hay giải thích các bước lập luận bên trong.","whyCorrect":"• Sự thiếu minh bạch trong cơ chế ra quyết định tạo ra rủi ro không thể kiểm toán và khắc phục sai lệch.","whyWrong":{"B":"• Đây là vấn đề kỹ thuật gán thuộc tính (Feature Engineering).","C":"• Dữ liệu tối (Dark data) là dữ liệu chưa khai thác, không phải Black Box.","D":"• Lưu trữ dữ liệu thuộc về hạ tầng phần cứng."}}},{"id":25,"task":"sp26_fe","taskLabel":"SP26 FE","num":25,"chooseType":"Choose 1 answer","question":"What can be learned from a predictive model should not change if the ________ is either included or excluded in the training set","options":{"A":"dataset filter","B":"biased dataset","C":"model fairness score","D":"Individual's data"},"answer":"C","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Đối tượng nào sau đây là một ví dụ về Bên liên quan thứ cấp (Secondary Stakeholder)?","optionsVi":{"A":"Nhân viên công ty (Employees)","B":"Khách hàng (Customers)","C":"Báo chí / Cơ quan truyền thông (Media)","D":"Nhà đầu tư (Investors)"},"answerDisplay":"C. Media","concept":"• Bên liên quan sơ cấp (Primary Stakeholders) giao dịch trực tiếp với công ty (nhân viên, khách hàng, nhà đầu tư). Bên liên quan thứ cấp (Secondary Stakeholders) chịu ảnh hưởng hoặc tác động gián tiếp (truyền thông, cộng đồng).","whyCorrect":"• Báo chí truyền thông gián tiếp tác động đến dư luận nên thuộc nhóm Secondary Stakeholder.","whyWrong":{"A":"• Nhân viên là bên liên quan sơ cấp (Primary).","B":"• Khách hàng là bên liên quan sơ cấp (Primary).","D":"• Nhà đầu tư là bên liên quan sơ cấp (Primary)."}}},{"id":26,"task":"sp26_fe","taskLabel":"SP26 FE","num":26,"chooseType":"Choose 1 answer","question":"Why is equity an important principle in emerging tech ethics?","options":{"A":"It increases brand value","B":"It ensures faimess in access and outcomes","C":"It simplifies design","D":"It boosts marketing campaigns"},"answer":"D","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Nguyên tắc giảm thiểu dữ liệu (Data Minimization) yêu cầu bạn giới hạn thu thập dữ liệu ở mức nào?","optionsVi":{"A":"Chỉ những gì cần thiết cho tính riêng tư vi sai","B":"Tùy chọn cho chuỗi mệnh lệnh quản lý","C":"Cần thiết để đạt tính ẩn danh k-anonymity","D":"Chỉ những gì bắt buộc để thực hiện một mục đích đã xác định cụ thể (Required to fulfill a specific purpose)"},"answerDisplay":"D. required to fulfill a specific purpose","concept":"• Data Minimization quy định tổ chức chỉ được thu thập đúng và đủ dữ liệu phục vụ mục đích đã được thông báo trước.","whyCorrect":"• Thu thập giới hạn đúng mục đích ngăn ngừa việc tích trữ dữ liệu dư thừa gây rủi ro xâm phạm riêng tư.","whyWrong":{"A":"• Differential privacy là kỹ thuật toán học, không phải tiêu chuẩn phạm vi thu thập.","B":"• Chuỗi mệnh lệnh quản lý không phải căn cứ pháp lý thu thập dữ liệu.","C":"• K-anonymity là kỹ thuật nhóm dữ liệu."}}},{"id":27,"task":"sp26_fe","taskLabel":"SP26 FE","num":27,"chooseType":"Choose 1 answer","question":"Why is it important to engage stakeholders at the beginning of the ethical nsk management process?","options":{"A":"It proves that you are completely equipped to address any ethical risks in your data-driven systems","B":"It lets stakeholders know that the organization cannot address ethical risks in data-driven systems without input from stakeholders first.","C":"It helps the organization avoid legal trouble during the development and deployment of data-driven systems","D":"It demonstrates that the organization is committed to accountability and transparency in their data-driven systems"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Hạn chế lớn của việc sử dụng các thuật toán có thể giải thích và điều chỉnh được là người dùng có xu hướng đưa ra quyết định như thế nào?","optionsVi":{"A":"Đưa ra các quyết định vị kỷ / có lợi nhất cho cá nhân (Selfish decisions)","B":"Đưa ra các quyết định có ý thức xã hội","C":"Đưa ra các quyết định ngẫu nhiên","D":"Đưa ra các quyết định thiên vị"},"answerDisplay":"A. selfish","concept":"• Khi hiểu rõ và điều chỉnh được thuật toán, con người có xu hướng thao túng đầu vào để tối đa hóa lợi ích cá nhân (Selfish behavior).","whyCorrect":"• Tính minh bạch quá mức có thể bị lợi dụng để 'gaming the system' (lách luật thuật toán).","whyWrong":{"B":"• Thực tế người dùng ít khi hy sinh lợi ích cá nhân vì ý thức xã hội chung.","C":"• Quyết định có tính toán tối đa lợi ích chứ không ngẫu nhiên.","D":"• Quyết định vị kỷ tập trung vào lợi ích bản thân."}}},{"id":28,"task":"sp26_fe","taskLabel":"SP26 FE","num":28,"chooseType":"Choose 2 answers","question":"Why is it important to categorize ethical risks into different types? (Select two)","options":{"A":"It makes it easier for us to identify and manage different types of risks","B":"It ensures that customers and other external stakeholders know that we take ethical risks senously.","C":"It helps us understand the many complexities involved in different types of ethical risks","D":"It helps us consider risk mitigation in terms of universal tactics that apply to all potential kinds of ethical risk."},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Mục tiêu chính của Đánh giá tác động đạo đức (Ethical Impact Assessment) là gì?","optionsVi":{"A":"Đánh giá tính khả thi về mặt tài chính","B":"Xác định và giảm thiểu các tổn hại đạo đức tiềm ẩn của dự án trước khi triển khai","C":"Tối ưu hóa mã nguồn lập trình","D":"Đưa sản phẩm ra thị trường nhanh hơn"},"answerDisplay":"B. To identify and mitigate potential ethical harms of a project before deployment","concept":"• Ethical Impact Assessment là công cụ quản trị giúp nhận diện trước các tác động tiêu cực về mặt xã hội và đạo đức.","whyCorrect":"• Đánh giá trước giúp chủ động thiết kế các biện pháp giảm thiểu tổn hại cho cộng đồng.","whyWrong":{"A":"• Tài chính thuộc về thẩm định kinh doanh (Financial Assessment).","C":"• Tối ưu mã nguồn thuộc về kỹ thuật phần mềm.","D":"• Tốc độ ra thị trường thuộc về chiến lược kinh doanh."}}},{"id":29,"task":"sp26_fe","taskLabel":"SP26 FE","num":29,"chooseType":"Choose 1 answer","question":"Which of the following constitute external stakeholders in the context of a code of ethics?","options":{"A":"Business managers","B":"Developers","C":"Regulators","D":"Designers"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Trong đánh giá rủi ro, khái niệm 'Khả năng xảy ra' (Likelihood) đề cập đến điều gì?","optionsVi":{"A":"Chi phí tài chính của rủi ro","B":"Xác suất một sự cố rủi ro sẽ xảy ra (Probability that a risk event will occur)","C":"Mức độ nghiêm trọng của tác động","D":"Thời gian kéo dài của rủi ro"},"answerDisplay":"B. The probability that a risk event will occur","concept":"• Ma trận rủi ro được tính dựa trên hai trục: Khả năng xảy ra (Likelihood/Probability) và Mức độ tác động (Impact/Severity).","whyCorrect":"• Likelihood đo lường xác suất thống kê một nguy cơ chuyển hóa thành sự cố thực tế.","whyWrong":{"A":"• Chi phí tài chính thuộc về đo lường tác động (Impact).","C":"• Mức độ nghiêm trọng là trục Impact.","D":"• Thời gian kéo dài là thuộc tính thời lượng (Duration)."}}},{"id":30,"task":"sp26_fe","taskLabel":"SP26 FE","num":30,"chooseType":"Choose 1 answer","question":"Which ethical framework emphasizes the importance of moral duties and rules when addressing ethical dilemmas?","options":{"A":"Deontological Ethics","B":"Ethical Relativism","C":"Utilitarianism","D":"Virtue Ethics"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Cách tiếp cận nào mô tả đúng nhất về Đạo đức Nghĩa vụ (Deontological Ethics)?","optionsVi":{"A":"Hành động là đúng nếu nó mang lại kết quả tổng thể tốt nhất","B":"Hành động là đúng nếu nó tuân thủ các nghĩa vụ và quy tắc đạo đức bất kể hậu quả ra sao","C":"Hành động là đúng nếu nó được thực hiện bởi một người có đức hạnh","D":"Hành động là đúng nếu được pháp luật phê chuẩn"},"answerDisplay":"B. Action is right if it adheres to moral duties and rules regardless of consequences","concept":"• Deontology (Đạo đức Kant) khẳng định tính đúng sai nằm ở bản chất hành vi và sự tuân thủ nghĩa vụ/quy tắc, không phụ thuộc vào kết quả.","whyCorrect":"• Nghĩa vụ đạo đức là bắt buộc và tuyệt đối, không được vi phạm ngay cả khi kết quả có vẻ tốt.","whyWrong":{"A":"• Đây là định nghĩa của Utilitarianism / Consequentialism (Đạo đức Hậu quả).","C":"• Đây là định nghĩa của Virtue Ethics (Đạo đức Đức hạnh).","D":"• Pháp luật không đồng nhất tuyệt đối với chuẩn mực đạo đức."}}},{"id":31,"task":"sp26_fe","taskLabel":"SP26 FE","num":31,"chooseType":"Choose 1 answer","question":"How can small organizations implement ethical practices with limited resources?","options":{"A":"Wait until they grow larger","B":"Focus on core ethical principles and gradual implementation","C":"Copy larger organizations exactly","D":"Ignore ethics until legally required"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Mục tiêu chính của ẩn danh k-anonymity là gì?","optionsVi":{"A":"Mã hóa toàn bộ cơ sở dữ liệu","B":"Ngăn chặn việc định danh lại cá nhân trong tập dữ liệu bằng cách nhóm các bản ghi tương tự","C":"Tăng tốc độ truy vấn cơ sở dữ liệu","D":"Xóa các bản ghi cá nhân"},"answerDisplay":"B. Preventing re-identification of individuals in a dataset by grouping records","concept":"• K-anonymity đảm bảo thông tin của một người ẩn trong ít nhất K-1 cá nhân khác có cùng thuộc tính gián tiếp.","whyCorrect":"• K-anonymity bảo vệ quyền riêng tư bằng cách triệt tiêu khả năng định danh duy nhất (re-identification).","whyWrong":{"A":"• Mã hóa dữ liệu là mã hóa lưu trữ (Encryption).","C":"• Tăng tốc truy vấn thuộc về index cơ sở dữ liệu.","D":"• K-anonymity giữ lại dữ liệu nhưng làm mờ thuộc tính."}}},{"id":32,"task":"sp26_fe","taskLabel":"SP26 FE","num":32,"chooseType":"Choose 1 answer","question":"Which of the following types of malware monitors a user's behavior without their knowledge or permission?","options":{"A":"Virus","B":"Spyware","C":"Ransomware","D":"Trojan horse"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Mã độc tống tiền (Ransomware) được định nghĩa tốt nhất là gì?","optionsVi":{"A":"Một loại virus làm chậm máy tính","B":"Phần mềm độc hại mã hóa dữ liệu của nạn nhân và yêu cầu thanh toán tiền chuộc để giải mã","C":"Lỗi hư hỏng phần cứng","D":"Một email lừa đảo thông thường"},"answerDisplay":"B. Malware that encrypts files and demands payment for decryption","concept":"• Ransomware là mối đe dọa an ninh mạng nghiêm trọng chiếm đoạt dữ liệu bằng mã hóa để tống tiền.","whyCorrect":"• Hành vi mã hóa khóa file và đòi tiền chuộc là đặc trưng phân loại của Ransomware.","whyWrong":{"A":"• Virus thông thường không nhất thiết mã hóa tống tiền.","C":"• Ransomware là phần mềm độc hại, không phải lỗi phần cứng.","D":"• Email lừa đảo (Phishing) chỉ là kịch bản phát tán."}}},{"id":33,"task":"sp26_fe","taskLabel":"SP26 FE","num":33,"chooseType":"Choose 1 answer","question":"How can artificial intelligence facilitate feedback and monitoring processes in crisis communication strategies?","options":{"A":"By automating sentiment analysis to gauge public opinion","B":"By creating holding statements for immediate use","C":"By replacing human oversight in communication strategies","D":"By predicting future crises through historical data analysis"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Trí tuệ nhân tạo có thể hỗ trợ các quy trình phản hồi và giám sát trong chiến lược truyền thông khủng hoảng như thế nào?","optionsVi":{"A":"Bằng cách tự động hóa phân tích cảm xúc (Sentiment Analysis) để đo lường ý kiến công chúng","B":"Bằng cách tạo các phát ngôn tạm thời để sử dụng ngay","C":"Bằng cách thay thế hoàn toàn sự giám sát của con người trong chiến lược truyền thông","D":"Bằng cách dự đoán các khủng hoảng tương lai thông qua phân tích dữ liệu lịch sử"},"answerDisplay":"A. By automating sentiment analysis to gauge public opinion","concept":"• Phân tích cảm xúc (Sentiment Analysis) qua AI giúp doanh nghiệp nắm bắt thời gian thực phản ứng và luồng dư luận của công chúng trong khủng hoảng.","whyCorrect":"• Tự động hóa phân tích cảm xúc giúp đội ngũ truyền thông kịp thời điều chỉnh thông điệp ứng phó phù hợp.","whyWrong":{"B":"• Phát ngôn cần sự phê duyệt kỹ lưỡng của lãnh đạo chứ không tự động phát hành.","C":"• AI không thể thay thế hoàn toàn sự giám sát và ra quyết định chiến lược của con người.","D":"• Dự đoán tương lai chỉ là một khía cạnh hỗ trợ, không phải cơ chế phản hồi giám sát trực tiếp dư luận."}}},{"id":34,"task":"sp26_fe","taskLabel":"SP26 FE","num":34,"chooseType":"Choose 2 answers","question":"Which of the following are potential training data inadequacies that you should communicate to your users in support of transparency? (Select two)","options":{"A":"The amount of time it took to collect the data","B":"Any known bias in the sample data","C":"The relatively large size of a dataset used in training","D":"Any missing values in the dataset and how they were handled"},"answer":"B, D","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Những thiếu sót nào của dữ liệu huấn luyện mà bạn nên thông báo cho người dùng nhằm hỗ trợ tính minh bạch? (Select two)","optionsVi":{"A":"Khoảng thời gian cần thiết để thu thập dữ liệu","B":"Bất kỳ thiên vị đã biết nào trong dữ liệu mẫu","C":"Kích thước tương đối lớn của tập dữ liệu huấn luyện","D":"Bất kỳ giá trị nào bị thiếu trong tập dữ liệu và cách chúng được xử lý"},"answerDisplay":"B. Any known bias in the sample data & D. Any missing values in the dataset and how they were handled","concept":"• Tính minh bạch trong AI đòi hỏi công khai các hạn chế của dữ liệu như thiên vị mẫu (Sampling Bias) và phương pháp xử lý dữ liệu khuyết thiếu.","whyCorrect":"• Công khai rủi ro thiên vị và cách xử lý dữ liệu thiếu giúp người dùng và nhà kiểm toán đánh giá đúng độ tin cậy của mô hình.","whyWrong":{"A":"• Thời gian thu thập là thông tin quản lý dự án, không ảnh hưởng trực tiếp đến rủi ro mô hình.","C":"• Kích thước tập dữ liệu lớn là đặc tính quy mô, không phải thiếu sót (inadequacy) cần cảnh báo."}}},{"id":35,"task":"sp26_fe","taskLabel":"SP26 FE","num":35,"chooseType":"Choose 1 answer","question":"Unknown Unknowns refer to","options":{"A":"being unsure about the morals of the research team","B":"lack of explainability and what a model is actually looking at to make it's prediction","C":"facing unknown empirical data with an incomplete dataset","D":"an uncertainty of how the data is gathered"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"'Unknown Unknowns' (Những điều không biết là mình không biết) đề cập đến yếu tố nào?","optionsVi":{"A":"Không chắc chắn về đạo đức của nhóm nghiên cứu","B":"Sự thiếu tính giải thích (Lack of Explainability) và việc mô hình thực sự dựa vào đâu để đưa ra dự đoán","C":"Đối mặt với dữ liệu thực nghiệm chưa biết với tập dữ liệu chưa hoàn chỉnh","D":"Sự không chắc chắn về cách thu thập dữ liệu"},"answerDisplay":"B. lack of explainability and what a model is actually looking at to make it's prediction","concept":"• 'Unknown Unknowns' trong AI chỉ các điểm mù tiềm ẩn của mô hình hộp đen mà các nhà nghiên cứu thậm chí không nhận ra để đo lường hay dự đoán trước.","whyCorrect":"• Thiếu khả năng giải thích (Explainability) làm cho nhà phát triển không thể biết mô hình đang sử dụng các mối tương quan sai lệch nào để đưa ra kết quả.","whyWrong":{"A":"• Đạo đức nhóm nghiên cứu là vấn đề quản trị nhân sự.","C":"• Dữ liệu chưa biết là Unknown Knowns hoặc hạn chế mẫu.","D":"• Quy trình thu thập dữ liệu có thể kiểm toán được qua log."}}},{"id":36,"task":"sp26_fe","taskLabel":"SP26 FE","num":36,"chooseType":"Choose 1 answer","question":"A type of artificial intelligence that outperforms humans in all tasks is known as","options":{"A":"General Al","B":"Outwit Al","C":"Specific Al","D":"Encompassing Al"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Loại trí tuệ nhân tạo vượt trội hơn con người trong mọi tác vụ được gọi là gì?","optionsVi":{"A":"AI tổng quát / Siêu AI (General AI / Superintelligence)","B":"Outwit AI","C":"Specific AI","D":"Encompassing AI"},"answerDisplay":"A. General Al","concept":"• General AI (AGI) hoặc Superintelligence được định nghĩa là AI có năng lực trí tuệ ngang bằng hoặc vượt xa con người trên mọi lĩnh vực.","whyCorrect":"• General AI đại diện cho cấp độ AI đa năng vượt qua giới hạn của các AI chuyên biệt (Narrow AI).","whyWrong":{"B":"• Outwit AI không phải thuật ngữ phân loại học thuật.","C":"• Specific AI chính là Narrow AI (AI hẹp), chỉ làm được 1 việc.","D":"• Encompassing AI không nằm trong hệ thống phân loại AI chính thức."}}},{"id":37,"task":"sp26_fe","taskLabel":"SP26 FE","num":37,"chooseType":"Choose 1 answer","question":"Identify the privacy risks associated with data collection, transmission, storage, and access in ambient intelligence systems. Which risk is most prevalent due to constant data monitoring?","options":{"A":"Unauthorized data access","B":"Enhanced data analytics","C":"Improved user experience","D":"Optimized resource allocation"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Xác định các rủi ro về quyền riêng tư liên quan đến việc thu thập, truyền tải, lưu trữ và truy cập dữ liệu trong các hệ thống trí tuệ môi trường (Ambient Intelligence). Rủi ro nào phổ biến nhất do việc giám sát dữ liệu liên tục?","optionsVi":{"A":"Truy cập dữ liệu trái phép (Unauthorized data access)","B":"Phân tích dữ liệu được nâng cao","C":"Trải nghiệm người dùng được cải thiện","D":"Tối ưu hóa phân bổ tài nguyên"},"answerDisplay":"A. Unauthorized data access","concept":"• Môi trường thông minh (Ambient Intelligence) thu thập dữ liệu sinh hoạt liên tục, tạo ra nguy cơ bị thâm nhập và truy cập dữ liệu trái phép rất cao.","whyCorrect":"• Việc giám sát liên tục tạo ra kho dữ liệu nhạy cảm dễ trở thành mục tiêu của các cuộc truy cập và rò rỉ trái phép.","whyWrong":{"B":"• Phân tích dữ liệu nâng cao là lợi ích kỹ thuật, không phải rủi ro riêng tư.","C":"• Trải nghiệm người dùng là mục tiêu thiết kế sản phẩm.","D":"• Phân bổ tài nguyên thuộc về quản lý hạ tầng."}}},{"id":38,"task":"sp26_fe","taskLabel":"SP26 FE","num":38,"chooseType":"Choose 1 answer","question":"Which psychological reason contributes to automation bias?","options":{"A":"Over-reliance on technology","B":"Fear of technology","C":"Lack of technical skills","D":"Distrust in human judgment"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Yếu tố tâm lý nào đóng góp vào thiên vị tự động hóa (Automation Bias)?","optionsVi":{"A":"Sự phụ thuộc quá mức vào công nghệ (Over-reliance on technology)","B":"Nỗi sợ hãi công nghệ","C":"Thiếu kỹ năng kỹ thuật","D":"Không tin tưởng vào quyết định của con người"},"answerDisplay":"A. Over-reliance on technology","concept":"• Automation Bias xuất phát từ thói quen tâm lý ỷ 赖 và tin tưởng mù quáng vào độ chính xác của máy tính/thuật toán.","whyCorrect":"• Tâm lý phụ thuộc quá mức khiến con người giảm bớt sự cảnh giác và bỏ qua việc kiểm tra phản biện kết quả máy tính.","whyWrong":{"B":"• Nỗi sợ công nghệ (Technophobia) dẫn tới từ chối sử dụng chứ không gây ra thiên vị tin tưởng.","C":"• Kỹ năng kỹ thuật không phải nguyên nhân tâm lý cốt lõi.","D":"• Mất tin tưởng vào con người là hệ quả gián tiếp, không phải nguyên nhân tâm lý kích hoạt Automation Bias."}}},{"id":39,"task":"sp26_fe","taskLabel":"SP26 FE","num":39,"chooseType":"Choose 1 answer","question":"The nature of a predictive model may reveal","options":{"A":"the researchers behind it","B":"the algorithm's bias","C":"the data it is trained on","D":"the ethics of the individual inputs"},"answer":"C","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Bản chất của một mô hình dự đoán có thể tiết lộ điều gì?","optionsVi":{"A":"Các nhà nghiên cứu đứng sau nó","B":"Thiên vị của thuật toán","C":"Dữ liệu mà nó đã được huấn luyện (The data it is trained on)","D":"Đạo đức của các đầu vào riêng lẻ"},"answerDisplay":"C. the data it is trained on","concept":"• Kết quả dự đoán và trọng số của mô hình học máy phản ánh trực tiếp phân phối và đặc trưng của tập dữ liệu huấn luyện.","whyCorrect":"• Phân tích mô hình có thể suy ngược ra các đặc điểm của tập dữ liệu được dùng để huấn luyện.","whyWrong":{"A":"• Tên nhà nghiên cứu được lưu trong tài liệu dự án chứ không nằm trong trọng số mô hình.","B":"• Thiên vị thuật toán là hệ quả, không phải tập nguồn bản chất.","D":"• Đầu vào riêng lẻ không mang tính đạo đức độc lập."}}},{"id":40,"task":"sp26_fe","taskLabel":"SP26 FE","num":40,"chooseType":"Choose 1 answer","question":"What is the purpose of change management in terms of creating an ethical organizational culture?","options":{"A":"To create a fast transition through training","B":"To create a management transition","C":"To create a smooth transition","D":"To create a slow transition through training"},"answer":"C","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Mục đích của quản lý sự thay đổi (Change Management) trong việc tạo ra một văn hóa tổ chức có đạo đức là gì?","optionsVi":{"A":"Tạo ra sự chuyển giao nhanh chóng thông qua đào tạo","B":"Tạo ra sự chuyển giao quản lý","C":"Tạo ra một sự chuyển giao suôn sẻ và bền vững (Smooth transition)","D":"Tạo ra sự chuyển giao chậm thông qua đào tạo"},"answerDisplay":"C. To create a smooth transition","concept":"• Quản lý sự thay đổi (Change Management) giúp tổ chức tiếp nhận các chuẩn mực đạo đức mới một cách êm đẹp và đồng bộ.","whyCorrect":"• Chuyển giao suôn sẻ giúp giảm bớt sự kháng cự nội bộ và đưa các giá trị đạo đức vào vận hành thực tế.","whyWrong":{"A":"• Tốc độ quá nhanh có thể tạo ra sự chống đối và thiếu chiều sâu.","B":"• Quản lý sự thay đổi không chỉ thay đổi nhân sự quản lý.","D":"• Mục tiêu không phải làm chậm quy trình mà là đạt hiệu quả suôn sẻ."}}},{"id":41,"task":"sp26_fe","taskLabel":"SP26 FE","num":41,"chooseType":"Choose 1 answer","question":"In the following scatter plot, the GrossIncome variable is plotted against the Revenue variable. What type of correlation does this plot suggest?","options":{"A":"There is a weak negative correlation between both variables.","B":"There is a strong negative correlation between both variables.","C":"There is a weak positive correlation between both variables.","D":"There is a strong positive correlation between both variables."},"answer":"D","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Trong biểu đồ phân tán giữa biến Lợi nhuận gộp (GrossIncome) và Doanh thu (Revenue), loại tương quan nào được gợi ý?","optionsVi":{"A":"Tương quan âm yếu giữa cả hai biến","B":"Tương quan âm mạnh giữa cả hai biến","C":"Tương quan dương yếu giữa cả hai biến","D":"Tương quan dương mạnh giữa cả hai biến (Strong positive correlation)"},"answerDisplay":"D. There is a strong positive correlation between both variables.","concept":"• Doanh thu tăng kéo theo Lợi nhuận gộp tăng biểu thị mối tương quan thuận mạnh (Strong Positive Correlation).","whyCorrect":"• Xu hướng đồng biến tuyến tính giữa Doanh thu và Lợi nhuận gộp phản ánh tương quan dương mạnh.","whyWrong":{"A":"• Tương quan âm nghĩa là một biến tăng thì biến kia giảm.","B":"• Tương quan âm mạnh đi ngược lại quy luật doanh thu - lợi nhuận.","C":"• Mối quan hệ giữa doanh thu và lợi nhuận gộp thường rất chặt chẽ chứ không yếu."}}},{"id":42,"task":"sp26_fe","taskLabel":"SP26 FE","num":42,"chooseType":"Choose 1 answer","question":"Which of the following is the most important idea that a crisis communication program should manage?","options":{"A":"The public's perception of a crisis","B":"The real-world effects of a crisis","C":"The individual details of a crisis","D":"Internal stakeholder consensus about how to approach a crisis"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Ý tưởng nào sau đây là quan trọng nhất mà một chương trình truyền thông khủng hoảng nên quản lý?","optionsVi":{"A":"Nhận thức của công chúng về khủng hoảng (The public's perception of a crisis)","B":"Các tác động thực tế của khủng hoảng","C":"Các chi tiết riêng lẻ của khủng hoảng","D":"Sự đồng thuận của các bên liên quan nội bộ về cách tiếp cận"},"answerDisplay":"A. The public's perception of a crisis","concept":"• Truyền thông khủng hoảng tập trung vào việc quản lý nhận thức (Perception Management) của công chúng để duy trì niềm tin.","whyCorrect":"• Nhận thức của công chúng định hình uy tín và sự tồn tại dài hạn của tổ chức sau khủng hoảng.","whyWrong":{"B":"• Tác động thực tế thuộc về khắc phục hậu quả vận hành/kỹ thuật.","C":"• Chi tiết riêng lẻ có thể gây xao nhãng khỏi thông điệp cốt lõi.","D":"• Đồng thuận nội bộ là bước chuẩn bị, không phải đối tượng truyền thông chính."}}},{"id":43,"task":"sp26_fe","taskLabel":"SP26 FE","num":43,"chooseType":"Choose 1 answer","question":"What is one risk of ignoring ethical concerns in Al design?","options":{"A":"Reduced testing time","B":"Improved speed of deployment","C":"Public backlash and regulatory consequences","D":"Higher profit margins"},"answer":"C","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Một rủi ro của việc bỏ qua các lo ngại về đạo đức trong thiết kế AI là gì?","optionsVi":{"A":"Giảm thời gian kiểm thử","B":"Cải thiện tốc độ triển khai","C":"Sự phản đối của công chúng và các hậu quả pháp lý/quản lý","D":"Biên lợi nhuận cao hơn"},"answerDisplay":"C. Public backlash and regulatory consequences","concept":"• Xem nhẹ đạo đức AI dẫn tới việc phát hành các sản phẩm thiên vị, gây hại xã hội, dẫn đến khủng hoảng truyền thông và án phạt pháp lý.","whyCorrect":"• Phản ứng dữ dội từ công chúng và án phạt từ cơ quan quản lý là hậu quả trực tiếp của việc phát triển công nghệ thiếu trách nhiệm.","whyWrong":{"A":"• Giảm thời gian kiểm thử là hành vi cắt giảm quy trình, không phải hệ quả tiêu cực cho tổ chức.","B":"• Tốc độ triển khai không bù đắp được rủi ro tẩy chay sản phẩm.","D":"• Lợi nhuận ngắn hạn sẽ bị đè bẹp bởi chi phí bồi thường và phạt pháp lý."}}},{"id":44,"task":"sp26_fe","taskLabel":"SP26 FE","num":44,"chooseType":"Choose 1 answer","question":"As a cognitive bias, humans see lack of context/meaning around a piece of information and tend to","options":{"A":"fill in gaps with existing knowledge","B":"use biased sources of research","C":"seek authority figures","D":"disagree with their previous beliefs"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Là một thiên vị nhận thức, khi thấy sự thiếu bối cảnh/ý nghĩa xung quanh một mẩu thông tin, con người có xu hướng làm gì?","optionsVi":{"A":"Tự điền vào khoảng trống bằng kiến thức sẵn có của mình (Fill in gaps with existing knowledge)","B":"Sử dụng các nguồn nghiên cứu bị thiên vị","C":"Tìm kiếm các nhân vật có thẩm quyền","D":"Không đồng ý với niềm tin trước đây của họ"},"answerDisplay":"A. fill in gaps with existing knowledge","concept":"• Khi thiếu bối cảnh, não bộ tự động bù đắp thông tin thiếu bằng các giả định và kiến thức có sẵn trong trí nhớ.","whyCorrect":"• Xu hướng tự lấp khoảng trống thông tin là cơ chế thiên vị nhận thức tự nhiên của con người.","whyWrong":{"B":"• Tìm nguồn nghiên cứu là hành vi chủ động kiểm chứng.","C":"• Tìm thẩm quyền không phải cơ chế tự phát của não bộ.","D":"• Con người ít khi tự bác bỏ niềm tin có sẵn của mình."}}},{"id":45,"task":"sp26_fe","taskLabel":"SP26 FE","num":45,"chooseType":"Choose 1 answer","question":"What is the long-term impact of ignoring ethical considerations in technology development?","options":{"A":"Faster time to market","B":"Loss of public trust and potential regulatory backlash","C":"Higher profits","D":"Simplified development processes"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Tác động dài hạn của việc bỏ qua các xem xét đạo đức trong phát triển công nghệ là gì?","optionsVi":{"A":"Thời gian ra thị trường nhanh hơn","B":"Mất niềm tin của công chúng và phản ứng pháp lý tiềm ẩn (Loss of public trust and potential regulatory backlash)","C":"Lợi nhuận cao hơn","D":"Quy trình phát triển được đơn giản hóa"},"answerDisplay":"B. Loss of public trust and potential regulatory backlash","concept":"• Bỏ qua đạo đức công nghệ gây mất niềm tin xã hội bền vững và đối mặt với các quy định pháp luật thắt chặt.","whyCorrect":"• Xây dựng lại lòng tin bị mất tiêu tốn chi phí khổng lồ và kéo theo các án phạt pháp lý nghiêm trọng.","whyWrong":{"A":"• Thời gian nhanh ngắn hạn không bền vững trong dài hạn.","C":"• Lợi nhuận bị ảnh hưởng tiêu cực khi công chúng tẩy chay.","D":"• Quy trình đơn giản hóa không bù đắp được thiệt hại uy tín."}}},{"id":46,"task":"sp26_fe","taskLabel":"SP26 FE","num":46,"chooseType":"Choose 1 answer","question":"Which of the following risk categories deals with stakeholder responsibility in creating and using data-driven technologies?","options":{"A":"Explainability","B":"Accountability","C":"Transparency","D":"Understandability"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Danh mục rủi ro nào sau đây giải quyết trách nhiệm của các bên liên quan trong việc tạo ra và sử dụng các công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Khả năng giải thích (Explainability)","B":"Trách nhiệm giải trình (Accountability)","C":"Tính minh bạch (Transparency)","D":"Khả năng thấu hiểu (Understandability)"},"answerDisplay":"B. Accountability","concept":"• Trách nhiệm giải trình (Accountability) xác định ai là người chịu trách nhiệm pháp lý và đạo đức đối với hậu quả của hệ thống AI.","whyCorrect":"• Accountability quy định nghĩa vụ của tổ chức/cá nhân phát triển đối với hành vi và tác động của công nghệ.","whyWrong":{"A":"• Explainability giải thích cơ chế mô hình hoạt động.","C":"• Transparency liên quan đến việc công khai thông tin dữ liệu.","D":"• Understandability liên quan đến khả năng tiếp thu của người dùng."}}},{"id":47,"task":"sp26_fe","taskLabel":"SP26 FE","num":47,"chooseType":"Choose 1 answer","question":"Which of the following is one explanation for why cognitive biases exist?","options":{"A":"We receive too much information and are overloaded.","B":"We use then to help remember things.","C":"They help us think logically instead of emotionally.","D":"They are taught to us in school"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Một giải thích cho lý do tại sao các thiên vị nhận thức (Cognitive Biases) tồn tại là gì?","optionsVi":{"A":"Chúng ta nhận quá nhiều thông tin và bị quá tải (We receive too much information and are overloaded)","B":"Chúng ta sử dụng chúng để giúp ghi nhớ mọi thứ","C":"Chúng giúp chúng ta suy nghĩ logic thay vì cảm xúc","D":"Chúng được dạy cho chúng ta ở trường học"},"answerDisplay":"A. We receive too much information and are overloaded.","concept":"• Thiên vị nhận thức là các đường tắt tư duy (Lối tắt nhận thức / Heuristics) giúp não bộ xử lý nhanh trong tình trạng quá tải thông tin.","whyCorrect":"• Quá tải thông tin buộc não bộ phải đơn giản hóa quy trình ra quyết định để tiết kiệm năng lượng.","whyWrong":{"B":"• Thiên vị nhận thức không phải là công cụ ghi nhớ.","C":"• Thiên vị nhận thức gây ra lệch lạc logic chứ không làm tăng tính logic.","D":"• Đây là cơ chế tiến hóa sinh học tâm lý, không phải kiến thức trường học."}}},{"id":48,"task":"sp26_fe","taskLabel":"SP26 FE","num":48,"chooseType":"Choose 1 answer","question":"Pseudocode can best be defined as","options":{"A":"an explainable description of code that is meant for humans, not computers","B":"a Python library for machine learning","C":"a middle ground between code and plain writing that can be fed into a computer","D":"a type of Javascript that is both human and machine-readable"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Mã giả (Pseudocode) có thể được định nghĩa tốt nhất là gì?","optionsVi":{"A":"Một mô tả có thể giải thích được của mã nguồn dành cho con người hiểu, không phải cho máy tính chạy","B":"Một thư viện Python cho học máy","C":"Dạng trung gian giữa mã lệnh và văn bản thuần có thể nạp vào máy tính","D":"Một loại Javascript mà cả con người và máy tính đều đọc được"},"answerDisplay":"A. an explainable description of code that is meant for humans, not computers","concept":"• Pseudocode là công cụ truyền thông giúp minh bạch hóa thuật toán cho các bên liên quan phi kỹ thuật hiểu mà không cần biết cú pháp lập trình.","whyCorrect":"• Pseudocode dùng ngôn ngữ tự nhiên kết hợp cấu trúc lệnh để con người dễ dàng đọc, giải thích và kiểm toán logic.","whyWrong":{"B":"• Pseudocode không phải là thư viện lập trình Python.","C":"• Máy tính không thể trực tiếp thực thi Pseudocode.","D":"• Pseudocode độc lập với bất kỳ ngôn ngữ lập trình cụ thể nào như Javascript."}}},{"id":49,"task":"sp26_fe","taskLabel":"SP26 FE","num":49,"chooseType":"Choose 1 answer","question":"How can effective communication mitigate ethical risks in Al and Data Science?","options":{"A":"By ensuring transparency and understanding of ethical guidelines","B":"By limiting access to Al technologies","C":"By prioritizing speed over accuracy in data processing","D":"By encouraging the concealment of ethical concerns"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Giao tiếp hiệu quả có thể giảm thiểu rủi ro đạo đức trong AI và Khoa học dữ liệu như thế nào?","optionsVi":{"A":"Bằng cách đảm bảo tính minh bạch và thấu hiểu các hướng dẫn đạo đức","B":"Bằng cách giới hạn quyền truy cập vào các công nghệ AI","C":"Bằng cách ưu tiên tốc độ hơn độ chính xác trong xử lý dữ liệu","D":"Bằng cách khuyến khích che giấu các mối quan tâm đạo đức"},"answerDisplay":"A. By ensuring transparency and understanding of ethical guidelines","concept":"• Giao tiếp hiệu quả đảm bảo mọi thành viên và bên liên quan nắm rõ và tuân thủ khung đạo đức của dự án.","whyCorrect":"• Minh bạch thông tin và thấu hiểu hướng dẫn giúp ngăn ngừa các vi phạm đạo đức từ sớm.","whyWrong":{"B":"• Cấm đoán quyền truy cập không giải quyết rủi ro thiết kế AI.","C":"• Ưu tiên tốc độ bỏ qua chính xác làm tăng rủi ro sai sót.","D":"• Che giấu mối quan tâm là hành vi vi phạm đạo đức nghiêm trọng."}}},{"id":50,"task":"sp26_fe","taskLabel":"SP26 FE","num":50,"chooseType":"Choose 1 answer","question":"What is a key step in monitoring ethical organizational policies?","options":{"A":"Establishing a policy committee","B":"Regular compliance checks","C":"Creating a rewards system","D":"Hosting annual policy workshops"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Bước then chốt trong việc giám sát các chính sách đạo đức của tổ chức là gì?","optionsVi":{"A":"Thành lập một ủy ban chính sách","B":"Kiểm tra việc tuân thủ định kỳ (Regular compliance checks)","C":"Tạo ra một hệ thống thưởng","D":"Tổ chức các hội thảo chính sách hàng năm"},"answerDisplay":"B. Regular compliance checks","concept":"• Giám sát chính sách đòi hỏi các hoạt động kiểm tra và kiểm toán tuân thủ (Compliance Checks) thường xuyên.","whyCorrect":"• Kiểm tra định kỳ giúp phát hiện kịp thời các hành vi chệch hướng khỏi chuẩn mực đạo đức.","whyWrong":{"A":"• Thành lập ủy ban là bước khởi tạo ban đầu, không phải quy trình giám sát liên tục.","C":"• Khen thưởng hỗ trợ động lực nhưng không thay thế kiểm toán tuân thủ.","D":"• Hội thảo có tính giáo dục chứ không có chức năng kiểm tra tuân thủ."}}},{"id":51,"task":"sp26_fe","taskLabel":"SP26 FE","num":51,"chooseType":"Choose 1 answer","question":"Which approach to corporate governance is more likely to create an ethical organizational culture?","options":{"A":"A systemic approach with incentive systems","B":"An oversight committee focus on rules.","C":"A board focused on legal and regulatory compliance","D":"An oversight committee focus on frameworks"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Cách tiếp cận nào đối với quản trị doanh nghiệp có nhiều khả năng tạo ra một văn hóa tổ chức có đạo đức hơn?","optionsVi":{"A":"Một tiếp cận hệ thống kết hợp các cơ chế khuyến khích (A systemic approach with incentive systems)","B":"Một ủy ban giám sát chỉ tập trung vào các quy tắc","C":"Một ban giám đốc chỉ tập trung vào tuân thủ pháp lý","D":"Một ủy ban giám sát chỉ tập trung vào các khung làm việc"},"answerDisplay":"A. A systemic approach with incentive systems","concept":"• Tiếp cận hệ thống kết hợp cơ chế thưởng/khuyến khích thúc đẩy nhân viên chủ động thực hành hành vi đạo đức thay vì đối phó.","whyCorrect":"• Cơ chế khuyến khích tích cực gắn liền với hệ thống vận hành giúp biến đạo đức thành thói quen văn hóa tổ chức.","whyWrong":{"B":"• Chỉ tập trung vào quy tắc cứng nhắc dễ tạo tâm lý chống đối hoặc đối phó hình thức.","C":"• Tuân thủ pháp lý chỉ là mức tối thiểu, chưa đủ để xây dựng văn hóa đạo đức nâng cao.","D":"• Chỉ tập trung vào khung làm việc lý thuyết thiếu tính thực thi."}}},{"id":52,"task":"sp26_fe","taskLabel":"SP26 FE","num":52,"chooseType":"Choose 1 answer","question":"What is the primary motivating factor behind hacktivism?","options":{"A":"The desire to make money","B":"The desire to serve an authority figure","C":"The desire to spread fear.","D":"The desire for social change."},"answer":"D","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Động cơ chính đằng sau hoạt động tấn công mạng vì mục đích xã hội (Hacktivism) là gì?","optionsVi":{"A":"Mong muốn kiếm tiền","B":"Mong muốn phục vụ một nhân vật có thẩm quyền","C":"Mong muốn gieo rắc sự sợ hãi","D":"Mong muốn thúc đẩy sự thay đổi xã hội (Desire for social change)"},"answerDisplay":"D. The desire for social change.","concept":"• Hacktivism (Hacking + Activism) là việc sử dụng kỹ thuật tấn công mạng để phản đối chính trị hoặc thúc đẩy các chiến dịch xã hội.","whyCorrect":"• Động cơ cốt lõi của tin tặc Hacktivism là tạo ra sự thay đổi chính trị hoặc xã hội theo quan điểm của họ.","whyWrong":{"A":"• Kiếm tiền là động cơ của tội phạm mạng tài chính (Financial Cybercrime).","B":"• Hacktivism thường mang tính tự phát hoặc phi chính phủ.","C":"• Gieo rắc sợ hãi là động cơ của khủng bố mạng (Cyberterrorism)."}}},{"id":53,"task":"sp26_fe","taskLabel":"SP26 FE","num":53,"chooseType":"Choose 1 answer","question":"If one group comprises the majority of the training data, they will skew the dataset and give the model","options":{"A":"less fairness for that group","B":"more confidence about that group","C":"less confidence about that group","D":"more faimess for that group"},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Nếu một nhóm chiếm đa số trong dữ liệu huấn luyện, họ sẽ làm lệch tập dữ liệu và mang lại cho mô hình yếu tố nào?","optionsVi":{"A":"Ít tính công bằng hơn cho nhóm đó","B":"Độ tự tin cao hơn về nhóm đó (more confidence about that group)","C":"Ít độ tự tin hơn về nhóm đó","D":"Nhiều tính công bằng hơn cho nhóm đó"},"answerDisplay":"B. more confidence about that group","concept":"• Chiếm đa số mẫu giúp mô hình học sâu các đặc trưng của nhóm đó dẫn tới độ tự tin (confidence) dự đoán cao hơn cho nhóm này.","whyCorrect":"• Dữ liệu dồi dào tăng độ tin cậy toán học của mô hình đối với nhóm đa số nhưng gây ra thiên vị bất công cho nhóm thiểu số.","whyWrong":{"A":"• Nhóm đa số nhận được kết quả tối ưu hơn, không phải ít công bằng hơn cho chính họ.","C":"• Dữ liệu nhiều làm tăng độ tự tin chứ không giảm.","D":"• Tính công bằng tổng thể bị suy giảm chứ không tăng."}}},{"id":54,"task":"sp26_fe","taskLabel":"SP26 FE","num":54,"chooseType":"Choose 1 answer","question":"Which strategy is key to building and maintaining an ethical organizational culture?","options":{"A":"Implementing ethics training and effective sessions","B":"Focusing solely on financial performance","C":"Ignoring regional and diversity differences","D":"Minimizing leadership roles"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Chiến lược nào là chìa khóa để xây dựng và duy trì một văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Triển khai đào tạo đạo đức và các buổi học hiệu quả (Implementing ethics training and effective sessions)","B":"Chỉ tập trung vào hiệu suất tài chính","C":"Bỏ qua các khác biệt về vùng miền và sự đa dạng","D":"Giảm thiểu vai trò của lãnh đạo"},"answerDisplay":"A. Implementing ethics training and effective sessions","concept":"• Đào tạo đạo đức thường xuyên nâng cao nhận thức và trang bị kỹ năng xử lý tình huống thực tế cho nhân viên.","whyCorrect":"• Đào tạo hiệu quả biến chính sách đạo đức trên giấy tờ thành hành động thực tế của mọi thành viên.","whyWrong":{"B":"• Chỉ tập trung tài chính dễ dẫn tới vi phạm đạo đức để đạt chỉ tiêu.","C":"• Bỏ qua đa dạng làm gia tăng mâu thuẫn và thiên vị văn hóa.","D":"• Giảm vai trò lãnh đạo làm mất đi định hướng và tấm gương đạo đức."}}},{"id":55,"task":"sp26_fe","taskLabel":"SP26 FE","num":55,"chooseType":"Choose 1 answer","question":"Which of the following describes an ethical framework?","options":{"A":"Ethical frameworks raise timeless ethical questions that are not easily put into action","B":"Ethical frameworks apply meta-ethical theories to everyday business operations.","C":"Ethical frameworks consolidate regulatory requirements for an industry.","D":"Ethical frameworks seek to mitigate ethical concerns by creating actionable steps"},"answer":"D","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng về một Khung làm việc đạo đức (Ethical Framework)?","optionsVi":{"A":"Khung đạo đức đưa ra các câu hỏi vượt thời gian nhưng khó đưa vào hành động","B":"Khung đạo đức áp dụng các thuyết siêu đạo đức vào vận hành kinh doanh hàng ngày","C":"Khung đạo đức hợp nhất các yêu cầu pháp lý cho một ngành","D":"Khung đạo đức tìm cách giảm thiểu các mối quan tâm đạo đức bằng cách tạo ra các bước hành động cụ thể"},"answerDisplay":"D. Ethical frameworks seek to mitigate ethical concerns by creating actionable steps","concept":"• Ethical Framework cung cấp quy trình và các bước hành động cụ thể (Actionable Steps) để tổ chức áp dụng giảm thiểu rủi ro đạo đức.","whyCorrect":"• Tính ứng dụng cao và đưa ra hướng dẫn hành động thực tế là đặc trưng phân biệt của khung làm việc đạo đức.","whyWrong":{"A":"• Khung đạo đức hướng tới hành động thực tế chứ không chỉ lý thuyết suông.","B":"• Khung đạo đức tập trung vào đạo đức ứng dụng (Applied Ethics).","C":"• Pháp lý là Legal Framework, không phải Ethical Framework."}}},{"id":56,"task":"sp26_fe","taskLabel":"SP26 FE","num":56,"chooseType":"Choose 1 answer","question":"Why is it important to take a proactive approach to addressing liability issues?","options":{"A":"The law often lags behind innovation","B":"The law is not always applied consistently","C":"The law is not always clear","D":"The law often difficult to understand"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Tại sao việc chủ động giải quyết các vấn đề trách nhiệm pháp lý lại quan trọng?","optionsVi":{"A":"Luật pháp thường tụt hậu so với sự đổi mới công nghệ (The law often lags behind innovation)","B":"Luật pháp không phải lúc nào cũng được áp dụng nhất quán","C":"Luật pháp không phải lúc nào cũng rõ ràng","D":"Luật pháp thường khó hiểu"},"answerDisplay":"A. The law often lags behind innovation","concept":"• Sự phát triển vũ bão của công nghệ luôn vượt trước khả năng lập pháp của cơ quan quản lý (Pacing Problem).","whyCorrect":"• Do luật chưa kịp quy định các công nghệ mới, tổ chức phải chủ động quản trị rủi ro đạo đức để tránh thảm họa pháp lý sau này.","whyWrong":{"B":"• Áp dụng nhất quán không phải lý do chính của khoảng trống pháp lý đổi mới.","C":"• Sự rõ ràng của luật là vấn đề diễn giải văn bản.","D":"• Khó hiểu là vấn đề kỹ thuật pháp lý."}}},{"id":57,"task":"sp26_fe","taskLabel":"SP26 FE","num":57,"chooseType":"Choose 1 answer","question":"What distinguishes consequentialist ethics from deontological ethics?","options":{"A":"Consequentialism focuses on outcomes, deontology on duties","B":"Consequentialism ignores results, deontology focuses on happiness","C":"They are essentially the same approach","D":"Consequentialism is newer than deontology"},"answer":"A","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Điều gì phân biệt Đạo đức Hậu quả (Consequentialist Ethics) với Đạo đức Nghĩa vụ (Deontological Ethics)?","optionsVi":{"A":"Đạo đức Hậu quả tập trung vào kết quả đầu ra, Đạo đức Nghĩa vụ tập trung vào nghĩa vụ và quy tắc","B":"Đạo đức Hậu quả bỏ qua kết quả, Đạo đức Nghĩa vụ tập trung vào hạnh phúc","C":"Về bản chất hai cách tiếp cận này giống hệt nhau","D":"Đạo đức Hậu quả mới hơn Đạo đức Nghĩa vụ"},"answerDisplay":"A. Consequentialism focuses on outcomes, deontology on duties","concept":"• Consequentialism đánh giá tính đúng sai dựa trên kết quả thực tế (Outcomes), trong khi Deontology đánh giá dựa trên việc tuân thủ các quy tắc nghĩa vụ bất biến (Duties).","whyCorrect":"• Sự khác biệt triết học cơ bản là một bên lấy Hậu quả làm thước đo, một bên lấy Quy tắc nghĩa vụ làm thước đo.","whyWrong":{"B":"• Consequentialism rất coi trọng kết quả và hạnh phúc tổng thể (như Utilitarianism).","C":"• Đây là hai trường phái đối lập nhau trong triết học đạo đức.","D":"• Lịch sử ra đời không phải là tiêu chí phân biệt bản chất triết học của hai trường phái."}}},{"id":58,"task":"sp26_fe","taskLabel":"SP26 FE","num":58,"chooseType":"Choose 1 answer","question":"What does a code of ethics provide for a data-driven organization?","options":{"A":"Specific employee salaries","B":"Legal immunity from lawsuits","C":"Guiding values and expectations for ethical behavior","D":"Product development timelines"},"answer":"C","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Bộ Quy tắc Đạo đức (Code of Ethics) cung cấp điều gì cho một tổ chức dựa trên dữ liệu?","optionsVi":{"A":"Mức lương cụ thể của nhân viên","B":"Quyền miễn trừ pháp lý khỏi các vụ kiện tụng","C":"Các giá trị hướng dẫn và kỳ vọng đối với hành vi đạo đức của nhân viên","D":"Tài liệu mốc thời gian phát triển sản phẩm"},"answerDisplay":"C. Guiding values and expectations for ethical behavior","concept":"• Bộ quy tắc đạo đức thiết lập kim chỉ nam và tiêu chuẩn hành vi bắt buộc cho nhân viên trong các hoạt động thu thập và xử lý dữ liệu.","whyCorrect":"• Bộ quy tắc giúp định hình văn hóa tổ chức và đưa ra định hướng xử lý cho các quyết định đạo đức hàng ngày.","whyWrong":{"A":"• Mức lương thuộc về chính sách nhân sự và hợp đồng lao động.","B":"• Quy tắc nội bộ không có giá trị tạo quyền miễn trừ pháp lý trước tòa án.","D":"• Tiến độ phát triển sản phẩm thuộc về quản lý dự án."}}},{"id":59,"task":"sp26_fe","taskLabel":"SP26 FE","num":59,"chooseType":"Choose 1 answer","question":"Which of the following best describes beneficence?","options":{"A":"Beneficence is a term coined by IBM that relates to their Green Horizons initiative in 2014","B":"Beneficence is the promotion of well-being, not just for moral agents like humans, but of animals, the environment, and societies.","C":"Beneficence is the promotion of well-being for moral agents like humans","D":"Beneficence is the promotion of efficient systems that perform rapidly and benefit companies."},"answer":"B","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất về Lòng nhân ái / Sự làm điều thiện (Beneficence)?","optionsVi":{"A":"Beneficence là thuật ngữ do IBM tạo ra liên quan đến sáng kiến Green Horizons của họ vào năm 2014","B":"Beneficence là sự thúc đẩy an lạc và thịnh vượng, không chỉ cho con người mà còn cho động vật, môi trường và toàn xã hội","C":"Beneficence là sự thúc đẩy an lạc chỉ riêng cho con người","D":"Beneficence là việc thúc đẩy các hệ thống hiệu quả vận hành nhanh mang lại lợi ích cho công ty"},"answerDisplay":"B. Beneficence is the promotion of well-being, not just for moral agents like humans, but of animals, the environment, and societies.","concept":"• Beneficence trong đạo đức công nghệ đòi hỏi phát triển sản phẩm vì sự thịnh vượng và an lạc chung của con người, hệ sinh thái và xã hội.","whyCorrect":"• Ý nghĩa rộng của Beneficence bao phủ cả tác động đến môi trường, động vật và toàn thể cộng đồng.","whyWrong":{"A":"• Beneficence là thuật ngữ triết học đạo đức cổ điển, không phải thương hiệu của IBM.","C":"• Chỉ giới hạn ở con người là chưa đủ phạm vi rộng của đạo đức sinh thái.","D":"• Lợi ích hiệu năng công ty là hiệu quả thương mại, không phải nguyên tắc Beneficence."}}},{"id":60,"task":"sp26_fe","taskLabel":"SP26 FE","num":60,"chooseType":"Choose 2 answers","question":"Which of the following are tools of an effective media communication plan? (Select two.)","options":{"A":"Mission statement","B":"Press release","C":"Public education campaign","D":"Video briefing"},"answer":"B, C","source":"ITE302c_SP26_FE","explanation":{"questionVi":"Những công cụ nào sau đây thuộc về một kế hoạch truyền thông hiệu quả với báo chí/truyền thông? (Select two.)","optionsVi":{"A":"Tuyên bố sứ mệnh (Mission statement)","B":"Thông cáo báo chí (Press release)","C":"Chiến dịch giáo dục công chúng (Public education campaign)","D":"Tóm tắt video nội bộ"},"answerDisplay":"B. Press release & C. Public education campaign","concept":"• Kế hoạch truyền thông đối ngoại sử dụng Thông cáo báo chí (Press Release) và Chiến dịch giáo dục công chúng để truyền tải thông điệp.","whyCorrect":"• Thông cáo báo chí cung cấp thông tin chính thống cho nhà báo và chiến dịch giáo dục giúp công chúng hiểu đúng vấn đề.","whyWrong":{"A":"• Mission statement là định hướng chiến lược doanh nghiệp nội bộ.","D":"• Video briefing nội bộ không phải công cụ truyền thông báo chí đại chúng."}}},{"id":1,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":1,"chooseType":"Choose 1 answer","question":"The Data minimization principle requires that you limit data collection to only what is:","options":{"A":"Necessary for differential privacy","B":"Optional for a chain of command","C":"Needed to have k-anonymity","D":"Required to fulfill a specific purpose"},"answer":"D","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Nguyên tắc Giảm thiểu dữ liệu (Data minimization) yêu cầu bạn giới hạn việc thu thập dữ liệu ở mức chỉ bao gồm những gì:","optionsVi":{"A":"Cần thiết cho tính riêng tư vi sai","B":"Tùy chọn cho chuỗi chỉ huy","C":"Cần thiết để đạt tính ẩn danh k-anonymity","D":"Cần thiết để thực hiện một mục đích cụ thể đã xác định (Required to fulfill a specific purpose)"},"answerDisplay":"D. Required to fulfill a specific purpose","concept":"• Nguyên tắc Giảm thiểu dữ liệu (Data Minimization) yêu cầu doanh nghiệp chỉ thu thập đúng và đủ dữ liệu cần thiết phục vụ cho một mục đích xử lý cụ thể đã được xác định trước.","whyCorrect":"• Chỉ thu thập dữ liệu thực sự cần thiết cho mục đích cụ thể giúp hạn chế rủi ro lộ rò dữ liệu cá nhân.","whyWrong":{"A":"• Differential privacy là kỹ thuật toán học thêm nhiễu, không phải điều kiện thu thập.","B":"• Thu thập dữ liệu không nhằm phục vụ chuỗi chỉ huy nội bộ.","C":"• k-anonymity là phương pháp ẩn danh hóa tập dữ liệu."}}},{"id":2,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":2,"chooseType":"Choose 1 answer","question":"What does the acronym RACI stand for in organizational governance?","options":{"A":"Relatable, Agreeable, Commendable, Irascible","B":"Responsible, Accessible, Consulted, Improvised","C":"Redesignable, Accessible, Collected, Informative","D":"Responsible, Accountable, Consulted, Informed"},"answer":"D","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Từ viết tắt RACI trong quản trị tổ chức và dự án đại diện cho điều gì?","optionsVi":{"A":"Relatable, Agreeable, Commendable, Irascible","B":"Responsible, Accessible, Consulted, Improvised","C":"Redesignable, Accessible, Collected, Informative","D":"Người thực thi (Responsible), Người chịu trách nhiệm (Accountable), Người tham vấn (Consulted), Người nhận thông tin (Informed)"},"answerDisplay":"D. Responsible, Accountable, Consulted, Informed","concept":"• Ma trận RACI: Responsible (thực hiện nhiệm vụ), Accountable (chịu trách nhiệm cuối cùng), Consulted (được tham vấn trước quyết định), Informed (được thông báo kết quả).","whyCorrect":"• Định nghĩa chính xác của mô hình phân công trách nhiệm RACI trong quản trị.","whyWrong":{"A":"• Đây là các tính từ tiếng Anh ngẫu nhiên.","B":"• Accessible và Improvised không phải thành tố RACI.","C":"• Redesignable và Collected không thuộc ma trận RACI."}}},{"id":3,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":3,"chooseType":"Choose 2 answers","question":"Which of the following are likely benefits of having defined organizational policies? (Select two.)","options":{"A":"It supports profitable research innovations","B":"It supports accountability and makes it more explicit","C":"It supports consistency of behavior and unification of culture","D":"It supports improved sales and marketing results"},"answer":"B, C","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Những lợi ích nào sau đây là hệ quả của việc sở hữu các chính sách tổ chức được xác định rõ ràng? (Select two)","optionsVi":{"A":"Hỗ trợ đổi mới nghiên cứu có lợi nhuận","B":"Hỗ trợ trách nhiệm giải trình và làm cho trách nhiệm đó trở nên rõ ràng (supports accountability)","C":"Hỗ trợ tính nhất quán trong hành vi và thống nhất văn hóa tổ chức (consistency of behavior and unification of culture)","D":"Cải thiện kết quả bán hàng"},"answerDisplay":"B. It supports accountability and makes it more explicit & C. It supports consistency of behavior and unification of culture.","concept":"• Chính sách tổ chức (Organizational Policies) quy định rõ trách nhiệm giải trình và chuẩn hóa hành vi ứng xử thống nhất cho toàn bộ nhân sự.","whyCorrect":"• Minh bạch hóa trách nhiệm giải trình và tạo sự thống nhất hành vi văn hóa là hai mục tiêu cốt lõi của chính sách tổ chức.","whyWrong":{"A":"• Đổi mới nghiên cứu là mục tiêu R&D.","D":"• Kết quả bán hàng thuộc về chiến lược tiếp thị."}}},{"id":4,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":4,"chooseType":"Choose 1 answer","question":"Which of the following describes the purpose of a STEEPV analysis?","options":{"A":"To perform a strategic analysis of user needs and behaviors","B":"To perform a strategic analysis of how external environments impact business operations","C":"To perform a strategic analysis of how internal office politics impact business operations","D":"To perform a strategic analysis of how bias can manifest in AI products"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng mục đích của mô hình phân tích STEEPV?","optionsVi":{"A":"Phân tích chiến lược nhu cầu người dùng","B":"Thực hiện phân tích chiến lược về cách các môi trường bên ngoài tác động đến hoạt động kinh doanh (how external environments impact business operations)","C":"Phân tích chính trị nội bộ","D":"Phân tích thiên vị AI"},"answerDisplay":"B. To perform a strategic analysis of how external environments impact business operations.","concept":"• Khung STEEPV phân tích 6 yếu tố vĩ mô môi trường bên ngoài: Social, Technological, Economic, Environmental, Political, Values.","whyCorrect":"• Phân tích tác động của các yếu tố vĩ mô môi trường bên ngoài đến doanh nghiệp là bản chất của STEEPV.","whyWrong":{"A":"• Nhu cầu người dùng là phân tích thị trường.","C":"• Chính trị nội bộ là phân tích văn hóa doanh nghiệp.","D":"• Thiên vị AI thuộc về Algorithmic Audit."}}},{"id":5,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":5,"chooseType":"Choose 1 answer","question":"What is the function of a red team in a penetration testing exercise?","options":{"A":"To conduct the simulated attacks","B":"To defend against the simulated attacks","C":"To officiate the simulated attacks","D":"To disable the attacks"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Chức năng của Đội Đỏ (Red Team) trong bài kiểm thử xâm nhập (Penetration testing) là gì?","optionsVi":{"A":"Thực hiện các cuộc tấn công giả lập (To conduct the simulated attacks)","B":"Phòng thủ trước các cuộc tấn công giả lập (Blue Team)","C":"Điều hành và giám sát bài kiểm thử (Purple Team)","D":"Vô hiệu hóa các cuộc tấn công"},"answerDisplay":"A. To conduct the simulated attacks","concept":"• Trong diễn tập an ninh mạng: Red Team đóng vai kẻ tấn công giả lập, Blue Team đóng vai bên phòng thủ, Purple Team điều phối.","whyCorrect":"• Vai trò cốt lõi của Red Team là đóng vai đối thủ tấn công để tìm ra các lỗ hổng của hệ thống.","whyWrong":{"B":"• Phòng thủ là vai trò của Đội Xanh (Blue Team).","C":"• Điều hành là vai trò của Đội Tím (Purple Team / White Team).","D":"• Vô hiệu hóa là mục tiêu của hệ thống phòng thủ."}}},{"id":6,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":6,"chooseType":"Choose 1 answer","question":"The Netflix Prize privacy scandal is an example of what privacy vulnerability?","options":{"A":"Re-identification through auxiliary datasets (Linkage attack)","B":"Data corruption during transfer","C":"Insecure database storage password","D":"Adversarial network attack"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Bê bối riêng tư Giải thưởng Netflix (Netflix Prize scandal) là một ví dụ về lỗ hổng quyền riêng tư nào?","optionsVi":{"A":"Tái định danh cá nhân thông qua liên kết tập dữ liệu bổ sung (Linkage attack / Re-identification)","B":"Hư hỏng dữ liệu trong khi truyền","C":"Mật khẩu CSDL không an toàn","D":"Tấn công đối kháng mạng"},"answerDisplay":"A. Re-identification through auxiliary datasets","concept":"• Tái định danh (Re-identification) xảy ra khi tập dữ liệu được ẩn danh hóa sơ sài bị liên kết chéo với tập dữ liệu công khai bên ngoài (như IMDb) để lộ tên người dùng.","whyCorrect":"• Các nhà nghiên cứu đã khôi phục danh tính cá nhân từ tập dữ liệu rating vô danh của Netflix bằng cách liên kết với dữ liệu IMDb công khai.","whyWrong":{"B":"• Sự cố không liên quan đến rò rỉ đường truyền mạng.","C":"• Mật khẩu cơ sở dữ liệu không phải nguyên nhân rò rỉ thuật toán.","D":"• Không phải là cuộc tấn công mạng đối kháng vào mô hình."}}},{"id":7,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":7,"chooseType":"Choose 1 answer","question":"In a scatter plot plotting GrossIncome against Revenue where points move upward from left to right, what type of correlation is suggested?","options":{"A":"Weak negative correlation","B":"Strong positive correlation","C":"Strong negative correlation","D":"No correlation"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Trong biểu đồ phân tán giữa Thu nhập gộp (GrossIncome) và Doanh thu (Revenue) khi các điểm dữ liệu hướng lên từ trái sang phải, loại tương quan nào được thể hiện?","optionsVi":{"A":"Tương quan âm yếu","B":"Tương quan dương mạnh (Strong positive correlation)","C":"Tương quan âm mạnh","D":"Không có tương quan"},"answerDisplay":"B. Strong positive correlation","concept":"• Biểu đồ phân tán (Scatter plot) hướng lên từ trái sang phải thể hiện tương quan thuận (Positive Correlation) giữa hai biến số.","whyCorrect":"• Doanh thu tăng kéo theo Thu nhập gộp tăng nhất quán là biểu hiện của Strong Positive Correlation.","whyWrong":{"A":"• Tương quan âm yếu biểu thị xu hướng đi xuống rải rác.","C":"• Tương quan âm mạnh biểu thị xu hướng đi xuống dốc.","D":"• Không tương quan biểu thị các điểm dữ liệu rải rác hỗn loạn."}}},{"id":8,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":8,"chooseType":"Choose 1 answer","question":"In a classification model that determines whether or not a customer qualifies for a coupon, a significantly lower percentage of males qualified than females. Which of the following types of discrimination does this outcome potentially represent?","options":{"A":"Disparate treatment","B":"Disparate non-impact","C":"Disparate impact (Unintentional adverse outcome on protected group)","D":"Disparate mistreatment"},"answer":"C","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Trong mô hình phân loại xác định khách hàng có đủ điều kiện nhận phiếu giảm giá hay không, tỷ lệ nam giới đủ điều kiện thấp hơn đáng kể so với nữ giới. Kết quả này đại diện cho loại phân biệt đối xử nào?","optionsVi":{"A":"Phân biệt đối xử cố ý (Disparate treatment)","B":"Tác động không chênh lệch","C":"Tác động không bình đẳng gián tiếp (Disparate impact)","D":"Ngược đãi không bình đẳng"},"answerDisplay":"C. Disparate impact","concept":"• Disparate Impact (Tác động bất bình đẳng gián tiếp) xảy ra khi quy trình trung lập tạo ra kết quả bất lợi không mong muốn cho một nhóm đối tượng cụ thể.","whyCorrect":"• Tỷ lệ đạt điều kiện chênh lệch đáng kể giữa nam và nữ là biểu hiện chuẩn của Disparate Impact.","whyWrong":{"A":"• Disparate treatment đòi hỏi hành vi cố ý phân biệt xử lý trực tiếp dựa trên giới tính.","B":"• Thuật ngữ Disparate non-impact không tồn tại trong luật đạo đức.","D":"• Disparate mistreatment không phải khái niệm tiêu chuẩn."}}},{"id":9,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":9,"chooseType":"Choose 2 answers","question":"Which of the following are cost functions used to evaluate linear regression models? (Select two.)","options":{"A":"Accuracy","B":"Mean squared error (MSE)","C":"Root mean squared error (RMSE)","D":"Recall"},"answer":"B, C","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Những hàm mất mát (Cost functions) nào sau đây được sử dụng để đánh giá các mô hình hồi quy tuyến tính (Linear Regression)? (Select two)","optionsVi":{"A":"Độ chính xác (Accuracy)","B":"Sai số bình phương trung bình (Mean squared error - MSE)","C":"Căn sai số bình phương trung bình (Root mean squared error - RMSE)","D":"Độ gợi nhớ (Recall)"},"answerDisplay":"B. Mean squared error (MSE) & C. Root mean squared error (RMSE)","concept":"• Mô hình hồi quy tuyến tính (dự đoán biến liên tục) sử dụng hằng số sai số khoảng cách như MSE và RMSE làm hàm tổn thất.","whyCorrect":"• MSE và RMSE đo lường khoảng cách sai lệch giữa giá trị dự đoán liên tục và giá trị thực tế.","whyWrong":{"A":"• Accuracy dùng cho mô hình Phân loại (Classification).","D":"• Recall dùng cho mô hình Phân loại nhị phân."}}},{"id":10,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":10,"chooseType":"Choose 1 answer","question":"A dataset attribute that is not identifiable by itself but constitutes sensitive information about the individual that needs to be protected is known as a:","options":{"A":"Explicitly private column","B":"Quasi-identifier","C":"Non-sensitive column","D":"Sensitive attribute"},"answer":"D","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Thuộc tính tập dữ liệu không tự định danh cá nhân nhưng chứa thông tin nhạy cảm cần được bảo vệ được gọi là gì?","optionsVi":{"A":"Cột riêng tư rõ ràng","B":"Bán định danh (Quasi-identifier)","C":"Cột không nhạy cảm","D":"Thuộc tính nhạy cảm (Sensitive attribute)"},"answerDisplay":"D. sensitive column","concept":"• Sensitive Attribute (Thuộc tính nhạy cảm) là thông tin như tình trạng bệnh lý, thu nhập, tôn giáo cần bảo vệ riêng tư.","whyCorrect":"• Bản thân thuộc tính nhạy cảm (như chẩn đoán y tế) không trực tiếp chỉ danh tính nhưng là thông tin cần bảo mật cao nhất.","whyWrong":{"A":"• Cột riêng tư không phải thuật ngữ dữ liệu tiêu chuẩn.","B":"• Quasi-identifier là thông tin bán định danh (như mã zip, ngày sinh, giới tính).","C":"• Non-sensitive column là dữ liệu thông thường không cần bảo mật."}}},{"id":11,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":11,"chooseType":"Choose 1 answer","question":"Which of the following describes extrajudicial judgment?","options":{"A":"A ruling or scoring made outside of a formal court system","B":"Transferring defendants between jurisdictions","C":"Applying international laws locally","D":"Revising courtroom procedures"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả Phán quyết ngoài tư pháp (Extrajudicial judgment)?","optionsVi":{"A":"Một phán quyết hoặc chấm điểm rủi ro được thực hiện bên ngoài hệ thống tòa án chính thức (made outside of a court)","B":"Chuyển giao bị cáo giữa các thẩm quyền","C":"Áp dụng luật quốc tế","D":"Sửa đổi quy trình tòa án"},"answerDisplay":"A. A ruling or scoring made outside of a court","concept":"• Extrajudicial Judgment là việc các thuật toán hay thực thể tư nhân tự động đưa ra quyết định đánh giá/chấm điểm trừng phạt cá nhân mà không qua quy trình xét xử của tòa án.","whyCorrect":"• Quyết định hay chấm điểm đưa ra bên ngoài tòa án chính thức là bản chất của Extrajudicial judgment.","whyWrong":{"B":"• Chuyển bị cáo là Extradition.","C":"• Áp dụng luật quốc tế là International law application.","D":"• Sửa đổi quy trình là Judicial reform."}}},{"id":12,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":12,"chooseType":"Choose 2 answers","question":"Which of the following elements should be communicated with end users when negotiating ethical access to a user's data? (Select two.)","options":{"A":"The monetary value of that data","B":"An offer of money to relinquish rights","C":"The intention behind a certain activity or request","D":"A request for consent to perform an action"},"answer":"C, D","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Những yếu tố nào sau đây nên được truyền thông rõ ràng với người dùng khi thỏa thuận quyền truy cập dữ liệu một cách có đạo đức? (Select two)","optionsVi":{"A":"Giá trị tiền tệ của dữ liệu","B":"Đề nghị tiền để từ bỏ quyền","C":"Mục đích và ý định đằng sau yêu cầu thu thập dữ liệu (The intention behind request)","D":"Yêu cầu sự đồng ý (Consent) để thực hiện hành động"},"answerDisplay":"C. The intention behind a certain activity or request & D. A request for consent to perform an action","concept":"• Informed Consent (Sự đồng ý dựa trên thông tin đầy đủ) yêu cầu giải thích rõ Mục đích sử dụng (Intention) và xin phép đồng ý tự nguyện (Consent).","whyCorrect":"• Nêu rõ mục đích thu thập và thu thập sự đồng ý rõ ràng là hai yêu cầu minh bạch đạo đức bắt buộc.","whyWrong":{"A":"• Định giá tiền tệ không phải trọng tâm quyền riêng tư.","B":"• Dùng tiền ép người dùng từ bỏ quyền là hành vi thao túng vi phạm đạo đức."}}},{"id":13,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":13,"chooseType":"Choose 1 answer","question":"Which of the following describes the goal of integrity when it comes to cybersecurity?","options":{"A":"Ensuring that data is kept private.","B":"Ensuring that data hasn't been modified without authorization.","C":"Ensuring that data is accessible to those who need it","D":"Ensuring that data is deleted permanently"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả mục tiêu Tính toàn vẹn (Integrity) trong an ninh mạng?","optionsVi":{"A":"Đảm bảo dữ liệu được giữ riêng tư (Confidentiality)","B":"Đảm bảo dữ liệu không bị thay đổi/sửa đổi trái phép (Ensuring data hasn't been modified without authorization)","C":"Đảm bảo dữ liệu luôn sẵn sàng truy cập (Availability)","D":"Đảm bảo dữ liệu bị xóa vĩnh viễn"},"answerDisplay":"B. Ensuring that data hasn't been modified without authorization.","concept":"• Bộ ba CIA Triad: Confidentiality (Bảo mật riêng tư), Integrity (Toàn vẹn không bị sửa đổi trái phép), Availability (Sẵn sàng truy cập).","whyCorrect":"• Integrity đảm bảo dữ liệu nguyên vẹn, chuẩn xác và không bị can thiệp trái phép.","whyWrong":{"A":"• Đây là mục tiêu Bảo mật (Confidentiality).","C":"• Đây là mục tiêu Sẵn sàng (Availability).","D":"• Xóa dữ liệu là Data destruction."}}},{"id":14,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":14,"chooseType":"Choose 1 answer","question":"Which of the following risk categories deals with stakeholder responsibility in creating and using data-driven technologies?","options":{"A":"Explainability","B":"Accountability","C":"Transparency","D":"Understandability"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Danh mục rủi ro nào sau đây xử lý trách nhiệm của các bên liên quan trong việc tạo ra và sử dụng các công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Tính giải thích được (Explainability)","B":"Trách nhiệm giải trình (Accountability)","C":"Tính minh bạch (Transparency)","D":"Tính dễ hiểu (Understandability)"},"answerDisplay":"B. Accountability","concept":"• Trách nhiệm giải trình (Accountability) quy định nghĩa vụ của tổ chức/cá nhân trong việc gánh chịu trách nhiệm đối với các tác động của hệ thống AI.","whyCorrect":"• Định rõ ai chịu trách nhiệm cho các hậu quả của công nghệ là bản chất của Accountability.","whyWrong":{"A":"• Explainability là thuộc tính giải thích mô hình toán.","C":"• Transparency là công khai thông tin.","D":"• Understandability là khả năng tiếp thu thông điệp."}}},{"id":15,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":15,"chooseType":"Choose 1 answer","question":"Which of the following tools is designed by Google for model inspection and bias analysis?","options":{"A":"What-If Tool","B":"SHAP","C":"ELI5","D":"LIME"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Công cụ nào sau đây do Google thiết kế để kiểm tra mô hình và phân tích thiên vị tích hợp trên nền tảng AI?","optionsVi":{"A":"What-If Tool (WIT)","B":"SHAP","C":"ELI5","D":"LIME"},"answerDisplay":"A. What-If Tool","concept":"• Google What-If Tool (WIT) là công cụ giao diện trực quan mở do Google phát triển giúp nhà phân tích kiểm thử các kịch bản giả định và phân tích tính công bằng của mô hình.","whyCorrect":"• What-If Tool là sản phẩm phân tích minh bạch AI chính thức của Google.","whyWrong":{"B":"• SHAP là thư viện mã nguồn mở độc lập dựa trên lý thuyết trò chơi Shapley values.","C":"• ELI5 là thư viện Python giải thích mô hình chung.","D":"• LIME là công cụ giải thích local độc lập."}}},{"id":16,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":16,"chooseType":"Choose 1 answer","question":"What is the purpose of a holding statement in crisis and media communications?","options":{"A":"To order the business to temporarily halt operations","B":"To retain the services of specific media outlets","C":"To pre-write communications before they are needed","D":"To prevent personnel from communicating prematurely"},"answer":"D","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Mục đích của một phát ngôn giữ chỗ (Holding Statement) trong truyền thông khủng hoảng là gì?","optionsVi":{"A":"Yêu cầu doanh nghiệp tạm dừng hoạt động","B":"Thuê dịch vụ của các cơ quan báo chí cụ thể","C":"Viết trước các văn bản truyền thông khi chưa cần đến","D":"Ngăn chặn nhân viên phát ngôn vội vàng/sớm khi chưa có đủ thông tin xác thực (prevent personnel from communicating prematurely)"},"answerDisplay":"D. To prevent personnel from communicating prematurely","concept":"• Holding Statement là thông cáo ban đầu giúp kiểm soát luồng thông tin, câu thời gian xác minh sự thật và ngăn phát ngôn vội vã.","whyCorrect":"• Tránh việc nhân viên tự ý đưa ra thông tin chưa kiểm chứng làm trầm trọng thêm khủng hoảng.","whyWrong":{"A":"• Holding statement là công cụ truyền thông, không phải lệnh dừng vận hành.","B":"• Không dùng để thuê hợp đồng báo chí.","C":"• Chuẩn bị kịch bản là crisis template, holding statement dùng để công bố tạm thời khi sự cố xảy ra."}}},{"id":17,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":17,"chooseType":"Choose 2 answers","question":"Which of the following are challenges that can arise if you fail to communicate about the social impact of ethical risks? (Select two.)","options":{"A":"Disenfranchisement of vulnerable groups","B":"Erosion of fundamental human rights","C":"Decreased corporate revenue","D":"Reduced brand loyalty"},"answer":"A, B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Những thách thức xã hội nào sau đây có thể phát sinh nếu bạn không truyền thông về tác động xã hội của các rủi ro đạo đức? (Select two)","optionsVi":{"A":"Sự tước đoạt quyền lợi của các nhóm yếu thế (Disenfranchisement)","B":"Sự xói mòn các quyền con người cơ bản (Erosion of rights)","C":"Giảm doanh thu công ty","D":"Giảm lòng trung thành thương hiệu"},"answerDisplay":"A. Disenfranchisement of vulnerable groups & B. Erosion of fundamental human rights","concept":"• Không truyền thông rủi ro tác động xã hội gây ra các thảm họa nhân văn nghiêm trọng như tước đoạt quyền xã hội và xói mòn nhân quyền.","whyCorrect":"• Tước đoạt quyền lợi nhóm yếu thế và xói mòn nhân quyền là hai tác động xã hội lớn nhất.","whyWrong":{"C":"• Doanh thu là chỉ số tài chính.","D":"• Lòng trung thành thương hiệu là chỉ số tiếp thị."}}},{"id":18,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":18,"chooseType":"Choose 1 answer","question":"Which of the following negative consequences is the direct result of failing to be truthful in communicating about a crisis?","options":{"A":"Discrimination","B":"Security risk","C":"Reputational damage","D":"Financial loss"},"answer":"C","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Hậu quả tiêu cực nào sau đây là kết quả trực tiếp của việc thiếu trung thực khi truyền thông về một cuộc khủng hoảng?","optionsVi":{"A":"Phân biệt đối xử","B":"Rủi ro an ninh","C":"Tổn hại uy tín nghiêm trọng (Reputational damage)","D":"Tổn thất tài chính"},"answerDisplay":"C. Reputational damage","concept":"• Thiếu trung thực hay dối trá trong khủng hoảng phá hủy hoàn toàn lòng tin của công chúng, gây ra tổn hại uy tín (Reputational Damage) không thể cứu vãn.","whyCorrect":"• Mất lòng tin do gian dối truyền thông dẫn trực tiếp tới sự sụp đổ uy tín thương hiệu.","whyWrong":{"A":"• Phân biệt đối xử do thiên vị thuật toán.","B":"• Rủi ro an ninh do lỗ hổng kỹ thuật.","D":"• Phạt tài chính là hệ quả gián tiếp."}}},{"id":19,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":19,"chooseType":"Choose 1 answer","question":"Why is it important to maintain public trust?","options":{"A":"Trust, once lost, is extremely difficult to regain.","B":"Trust is required to avoid legal pitfalls.","C":"Trust can be used against the organization.","D":"Trust is a temporary trend."},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Tại sao việc duy trì lòng tin của công chúng lại cực kỳ quan trọng?","optionsVi":{"A":"Lòng tin một khi đã mất đi thì cực kỳ khó khôi phục lại (Trust, once lost, is difficult to regain)","B":"Lòng tin bắt buộc để tránh rắc rối pháp lý","C":"Lòng tin bị dùng chống lại công ty","D":"Lòng tin là trào lưu tạm thời"},"answerDisplay":"A. Trust, once lost, is difficult to regain.","concept":"• Lòng tin công chúng (Public Trust) là tài sản vô hình quý giá nhất; một khi bị phá hủy bởi scandal đạo đức sẽ mất nhiều năm để gầy dựng lại.","whyCorrect":"• Tính chất khó khôi phục của lòng tin khẳng định tầm quan trọng cốt lõi của việc duy trì uy tín.","whyWrong":{"B":"• Pháp lý tuân thủ bằng luật chứ không dựa vào lòng tin.","C":"• Lòng tin là tài sản bảo vệ công ty.","D":"• Lòng tin là nền tảng bền vững dài hạn."}}},{"id":20,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":20,"chooseType":"Choose 1 answer","question":"In the context of open data, what does FAIR stand for?","options":{"A":"Findable, Accessible, Interoperable, and Reusable","B":"Fundamental Artificial Intelligence Research","C":"Fair Competition Principles","D":"Finance Accountability Intelligence Research"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Trong bối cảnh dữ liệu mở (Open Data), từ viết tắt FAIR đại diện cho điều gì?","optionsVi":{"A":"Dễ tìm kiếm, Dễ truy cập, Khả năng tương tác, và Dễ tái sử dụng (Findable, Accessible, Interoperable, Reusable)","B":"Nghiên cứu AI cơ bản","C":"Nguyên tắc cạnh tranh công bằng","D":"Nghiên cứu tài chính"},"answerDisplay":"A. An acronym for findable, accessible, interoperable, and reusable.","concept":"• Nguyên tắc dữ liệu FAIR: Findable (Tìm kiếm được), Accessible (Truy cập được), Interoperable (Tương tác hệ thống được), Reusable (Tái sử dụng được).","whyCorrect":"• Định nghĩa chuẩn mực của tiêu chuẩn dữ liệu mở FAIR trong quản trị dữ liệu khoa học.","whyWrong":{"B":"• Không phải viết tắt của nghiên cứu AI.","C":"• Không phải quy tắc cạnh tranh thương mại.","D":"• Không phải thuật ngữ tài chính."}}},{"id":21,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":21,"chooseType":"Choose 1 answer","question":"Which of the following is an adequate definition of a stakeholder?","options":{"A":"All internal employees only","B":"All people who have an impact on or are impacted by the organization","C":"All external customers only","D":"Shareholders and investors only"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây là định nghĩa đầy đủ về Bên liên quan (Stakeholder)?","optionsVi":{"A":"Toàn bộ nhân viên nội bộ","B":"Tất cả những người có tác động hoặc chịu tác động bởi hoạt động của tổ chức (impact on or impacted by the organization)","C":"Toàn bộ khách hàng bên ngoài","D":"Chỉ các cổ đông và nhà đầu tư"},"answerDisplay":"B. All people who have an impact or are impacted by the organization.","concept":"• Stakeholder (Bên liên quan) bao gồm bất kỳ cá nhân hay nhóm nào có thể gây ảnh hưởng hoặc chịu ảnh hưởng bởi các quyết định và sản phẩm của doanh nghiệp.","whyCorrect":"• Bao quát cả chiều tác động hai hướng (tác động đến tổ chức và chịu tác động từ tổ chức).","whyWrong":{"A":"• Chỉ nhân viên là định nghĩa hẹp Internal.","C":"• Chỉ khách hàng bỏ qua nhân viên và cơ quan quản lý.","D":"• Chỉ cổ đông là định nghĩa Shareholder hẹp."}}},{"id":22,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":22,"chooseType":"Choose 1 answer","question":"The endorsement of which of the following types of stakeholder is most critical when developing mission and vision statements?","options":{"A":"Department heads","B":"C-suite executives","C":"Employees","D":"Customers"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Sự phê chuẩn của nhóm bên liên quan nào là quan trọng nhất khi xây dựng các tuyên bố Sứ mệnh và Tầm nhìn (Mission & Vision) của công ty?","optionsVi":{"A":"Trưởng các bộ phận","B":"Ban điều hành cấp cao (C-suite executives)","C":"Nhân viên cấp dưới","D":"Khách hàng"},"answerDisplay":"B. C-suite executives","concept":"• Sứ mệnh và Tầm nhìn là định hướng chiến lược tối cao của tổ chức, bắt buộc phải được cam kết và duyệt phê chuẩn bởi C-Suite Executives (CEO, CTO, CIO).","whyCorrect":"• Cam kết từ ban điều hành C-suite quyết định việc thực thi chiến lược toàn công ty.","whyWrong":{"A":"• Trưởng phòng thực thi chiến lược cấp trung.","C":"• Nhân viên thực hiện tác vụ.","D":"• Khách hàng là đối tượng phục vụ."}}},{"id":23,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":23,"chooseType":"Choose 2 answers","question":"Which of the following are tools of an effective media communication plan? (Select two.)","options":{"A":"Mission statement","B":"Press release","C":"Public education campaign","D":"Video briefing"},"answer":"B, C","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Những công cụ nào sau đây thuộc về một kế hoạch truyền thông báo chí/truyền thông hiệu quả? (Select two)","optionsVi":{"A":"Tuyên bố sứ mệnh","B":"Thông cáo báo chí (Press release)","C":"Chiến dịch giáo dục công chúng (Public education campaign)","D":"Tóm tắt video nội bộ"},"answerDisplay":"B. Press release & C. Public education campaign","concept":"• Kế hoạch truyền thông báo chí sử dụng các công cụ công bố chính thức như Press Release và các chiến dịch nâng cao nhận thức cộng đồng (Public Education Campaign).","whyCorrect":"• Thông cáo báo chí và chiến dịch giáo dục là hai công cụ truyền thông đối ngoại chính yếu.","whyWrong":{"A":"• Tuyên bố sứ mệnh là định hướng chiến lược nội bộ.","D":"• Video briefing là công cụ giao tiếp nội bộ."}}},{"id":24,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":24,"chooseType":"Choose 2 answers","question":"Which of the following are useful strategies for communicating ethical risks to the organization? (Select two.)","options":{"A":"Communicate information through a single voice","B":"Disseminate information in multiple formats","C":"Communicate information in real time","D":"Provide information only when solicited"},"answer":"B, C","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Những chiến lược nào sau đây là hữu ích để truyền thông các rủi ro đạo đức tới toàn tổ chức? (Select two)","optionsVi":{"A":"Truyền đạt thông tin qua một giọng nói duy nhất","B":"Phổ biến thông tin dưới nhiều định dạng đa dạng (Disseminate information in multiple formats)","C":"Truyền đạt thông tin theo thời gian thực (Communicate information in real time)","D":"Chỉ cung cấp thông tin khi được yêu cầu"},"answerDisplay":"B. Disseminate information in multiple formats & C. Communicate information in real time","concept":"• Truyền thông rủi ro hiệu quả cần sử dụng đa dạng định dạng (văn bản, video, tập huấn) và cập nhật kịp thời gian thực.","whyCorrect":"• Đa dạng định dạng giúp tăng khả năng tiếp thu và truyền thông thời gian thực giúp ngăn ngừa sự cố kịp thời.","whyWrong":{"A":"• Giọng nói duy nhất tạo ra sự đơn điệu và thiếu phủ sóng.","D":"• Chỉ cung cấp khi hỏi là thái độ thụ động nguy hiểm trong quản lý rủi ro."}}},{"id":25,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":25,"chooseType":"Choose 1 answer","question":"To uphold transparency and explainability, communication about data-driven technologies should be:","options":{"A":"Clear, concise, and coherent","B":"Complex, convincing, and contained","C":"Caring, consistent, and creative","D":"Long, complex and iterative"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Để duy trì tính minh bạch và khả năng giải thích, truyền thông về các công nghệ dựa trên dữ liệu phải tuân theo tiêu chí nào?","optionsVi":{"A":"Rõ ràng, ngắn gọn súc tích và mạch lạc (Clear, concise, and coherent)","B":"Phức tạp, thuyết phục","C":"Quan tâm, nhất quán, sáng tạo","D":"Dài dòng, phức tạp"},"answerDisplay":"A. Clear, concise, and coherent","concept":"• Nguyên tắc 3C trong truyền thông giải thích AI: Clear (Rõ ràng), Concise (Ngắn gọn súc tích) và Coherent (Mạch lạc).","whyCorrect":"• Rõ ràng, ngắn gọn và mạch lạc giúp người dùng đại chúng dễ dàng thấu hiểu và tin tưởng.","whyWrong":{"B":"• Truyền thông phức tạp gây rào cản nhận thức.","C":"• Quan tâm và sáng tạo không thay thế được tính rõ ràng.","D":"• Dài dòng làm mất trọng tâm thông điệp."}}},{"id":26,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":26,"chooseType":"Choose 1 answer","question":"An example of algorithmic bias resulting from historical representation in data is when:","options":{"A":"An image recognition model selects one face over another based on sample data","B":"A model selects for one demographic less often because of their historical representation","C":"A model fails to recognize cultural differences due to incorrect attributes","D":"A predictive model incorporates training data from a variety of sources"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Ví dụ nào thể hiện thiên vị thuật toán phát sinh từ tỷ lệ đại diện lịch sử bị lệch trong dữ liệu?","optionsVi":{"A":"Mô hình nhận diện khuôn mặt chọn mặt này hơn mặt khác","B":"Mô hình lựa chọn một nhóm nhân khẩu học ít hơn đáng kể do tỷ lệ xuất hiện thấp trong dữ liệu lịch sử (selects less often because of historical representation)","C":"Mô hình không nhận diện được khác biệt văn hóa","D":"Mô hình tổng hợp dữ liệu đa nguồn"},"answerDisplay":"B. a model selects for one demographic less often because of their historical representation","concept":"• Historical Bias (Thiên vị lịch sử) xảy ra khi dữ liệu quá khứ chứa tỷ lệ đại diện thấp cho một nhóm xã hội, khiến thuật toán phân biệt lựa chọn nhóm đó ít hơn.","whyCorrect":"• Phản ánh chính xác cơ chế học thiên vị từ sự thiếu hụt đại diện trong dữ liệu quá khứ.","whyWrong":{"A":"• Chọn mặt dựa trên mẫu ngẫu nhiên là lỗi nhận diện.","C":"• Lỗi thuộc tính văn hóa là thiếu chuyên môn miền.","D":"• Tích hợp đa nguồn giúp giảm thiên vị."}}},{"id":27,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":27,"chooseType":"Choose 1 answer","question":"Which of the following describes dual-use or multipurpose data?","options":{"A":"Data used in multiple devices like TV and phone","B":"Data collected for one application that could also be applied to another application in a different domain","C":"Data transformed into multiple audio/video formats","D":"Data shared with family members"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả Dữ liệu sử dụng kép hoặc đa mục đích (Dual-use / Multipurpose data)?","optionsVi":{"A":"Dữ liệu dùng trên nhiều thiết bị TV/Điện thoại","B":"Dữ liệu được thu thập cho một ứng dụng ban đầu nhưng cũng có thể được áp dụng cho ứng dụng khác ở lĩnh vực khác (collected for one app, applied to another domain)","C":"Dữ liệu chuyển đổi định dạng âm thanh/video","D":"Dữ liệu chia sẻ với người thân"},"answerDisplay":"B. Data collected for one application that could also be applied to another application in a different domain.","concept":"• Dual-use / Multipurpose Data là dữ liệu được thu thập cho mục đích dân sự/lành tính nhưng có thể bị tái sử dụng cho mục đích theo dõi hoặc quân sự nhạy cảm.","whyCorrect":"• Tái sử dụng dữ liệu sang miền ứng dụng khác ngoài mục đích ban đầu là bản chất của Dual-use data.","whyWrong":{"A":"• Sử dụng trên nhiều thiết bị là Cross-device compatibility.","C":"• Chuyển đổi định dạng là Media encoding.","D":"• Chia sẻ gia đình là Personal data sharing."}}},{"id":28,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":28,"chooseType":"Choose 1 answer","question":"To measure a predictive model's accuracy, you:","options":{"A":"Divide the number of predictions by the total dataset","B":"Measure the ratio of the model's error curve","C":"Multiply total predictions by correct percentage","D":"Divide the number of correct predictions by the total number of predictions"},"answer":"D","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Để đo lường độ chính xác (Accuracy) của một mô hình dự đoán, bạn thực hiện phép tính nào?","optionsVi":{"A":"Chia số dự đoán cho tổng tập dữ liệu","B":"Đo tỷ lệ đường cong lỗi","C":"Nhân tổng dự đoán với phần trăm đúng","D":"Chia số lượng dự đoán đúng cho tổng số lượng dự đoán (Divide correct predictions by total predictions)"},"answerDisplay":"D. divide the number of correct predictions by the total number of predictions","concept":"• Công thức tính Accuracy: Accuracy = (Số lượng dự đoán đúng) / (Tổng số lượng dự đoán).","whyCorrect":"• Phép chia số dự đoán đúng cho tổng số lần dự đoán ra tỷ lệ độ chính xác chuẩn mực.","whyWrong":{"A":"• Phép chia này không tính đến số dự đoán đúng.","B":"• Tỷ lệ đường cong lỗi đo Lực mất mát (Loss curve).","C":"• Phép nhân không ra công thức tính chỉ số Accuracy."}}},{"id":29,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":29,"chooseType":"Choose 3 answers","question":"Which of the following statements are promoted by the categorical imperative? (Select three.)","options":{"A":"Act in such a way that your actions may become a universal law.","B":"Don't treat people as a means to an end; treat them always as an end.","C":"Each person must use reason to will moral laws.","D":"You have a moral duty to choose your actions based on their potential outcomes."},"answer":"A, B, C","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Những tuyên bố nào sau đây được cổ vũ bởi Thuyết mệnh lệnh tuyệt đối (Categorical Imperative) của Kant? (Select three)","optionsVi":{"A":"Hành động sao cho nguyên tắc hành động của bạn có thể trở thành luật phổ quát cho toàn nhân loại (Universal law)","B":"Không coi con người là phương tiện để đạt mục đích; luôn coi con người là mục đích tối hậu (End in itself)","C":"Mỗi người phải sử dụng lý trí để thiết lập các quy luật đạo đức","D":"Chọn hành động dựa trên kết quả đầu ra"},"answerDisplay":"A. Act in such a way that your actions may become a universal law. & B. Don't treat people as a means to an end; treat them always as an end. & C. Each person must use reason to will moral laws.","concept":"• Categorical Imperative (Kant): 1. Công lý phổ quát (Universalability), 2. Tôn trọng phẩm giá con người là mục đích tối hậu (Humanity Formulation), 3. Tự trị lý trí (Autonomy).","whyCorrect":"• Ba tuyên bố A, B, C là 3 nguyên lý cốt lõi cấu thành nên Categorical Imperative của Immanuel Kant.","whyWrong":{"D":"• Lựa chọn dựa trên kết quả đầu ra (Outcomes) là triết lý Thuyết vị lợi (Utilitarianism), trái ngược với Kantian Deontology."}}},{"id":30,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":30,"chooseType":"Choose 1 answer","question":"Which of these steps follows the most logical order for a low-to-high sorting algorithm?","options":{"A":"1. Scan to find largest number...","B":"1. Scan to find the smallest number, 2. Set to 0 in index of output array, 3. Remove that number from input array, 4. Repeat steps 1-3 adding 1 to index","C":"1. Scan array length...","D":"1. Scan random numbers..."},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Trình tự nào sau đây tuân theo thứ tự logic nhất cho một thuật toán sắp xếp từ thấp đến cao (Selection Sort)?","optionsVi":{"A":"Quét tìm số lớn nhất","B":"1. Quét tìm số nhỏ nhất, 2. Đặt vào chỉ số 0 của mảng đầu ra, 3. Xóa số đó khỏi mảng đầu vào, 4. Lặp lại bước 1-3 và tăng chỉ số thêm 1 (Scan smallest -> Output array -> Remove -> Repeat)","C":"Quét độ dài mảng","D":"Quét số ngẫu nhiên"},"answerDisplay":"B. 1. Scan to find the smallest number 2. Set to 0 in the index in the output array 3 Remove that number from the input array 4. Repeat steps 1-3, but add 1 to the index number for each loop","concept":"• Thuật toán sắp xếp tăng dần đơn giản (Selection Sort): Tìm phần tử nhỏ nhất -> Đưa vào vị trí mảng mới -> Xóa phần tử cũ -> Lặp lại.","whyCorrect":"• Các bước mô tả chính xác logic lặp tìm phần tử nhỏ nhất và xếp vào mảng kết quả.","whyWrong":{"A":"• Quét số lớn nhất sẽ tạo ra mảng sắp xếp giảm dần.","C":"• Quét độ dài mảng không giúp tìm giá trị phần tử.","D":"• Quét số ngẫu nhiên không tạo ra mảng sắp xếp."}}},{"id":31,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":31,"chooseType":"Choose 1 answer","question":"How are predictive models used in hedge funds?","options":{"A":"They predict whether people will be able to pay off loans","B":"They predict future movement of stocks and find points to exploit the market moving in either direction","C":"They aid researchers by forecasting financial collapse","D":"They provide predictions to shareholders to estimate returns"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Các mô hình dự đoán được sử dụng như thế nào trong các quỹ đầu tư cơ hội (Hedge funds)?","optionsVi":{"A":"Dự đoán khả năng trả nợ vay cá nhân","B":"Dự đoán sự chuyển động tương lai của giá cổ phiếu và tìm kiếm các điểm khai thác lợi nhuận theo cả hai chiều thị trường (predict stock movement and exploit market in either direction)","C":"Dự báo sụp đổ tài chính cho nhà nghiên cứu","D":"Cung cấp dự đoán cho cổ đông"},"answerDisplay":"B. they predict future movement of stocks and find points to exploit the market moving in either direction","concept":"• Algorithmic Trading trong Hedge Funds sử dụng AI để dự báo biến động giá ngắn hạn và tự động giao dịch mua/bán khống để sinh lời.","whyCorrect":"• Khai thác biến động thị trường hai chiều (Long/Short) là đặc trưng giao dịch của Hedge Funds.","whyWrong":{"A":"• Đánh giá nợ vay là công việc của Ngân hàng bán lẻ (Retail Banks).","C":"• Dự báo sụp đổ kinh tế vĩ mô là công việc của Ngân hàng trung ương (FED/IMF).","D":"• Báo cáo lợi nhuận cổ đông thuộc về quản trị tài chính doanh nghiệp."}}},{"id":32,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":32,"chooseType":"Choose 1 answer","question":"In artificial intelligence risk management, 'Unknown Unknowns' refers to:","options":{"A":"Being unsure about the morals of the research team","B":"Lack of explainability and what a model is actually looking at to make its prediction","C":"Facing unknown empirical data with an incomplete dataset","D":"An uncertainty of how the data is gathered"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Trong quản lý rủi ro AI, thuật ngữ 'Điều không biết về những điều không biết' (Unknown Unknowns) đề cập đến điều gì?","optionsVi":{"A":"Không chắc chắn về đạo đức của đội ngũ","B":"Sự thiếu tính giải thích được và việc không thể biết mô hình thực sự dựa vào yếu tố nào để đưa ra dự đoán (Lack of explainability and what a model is actually looking at)","C":"Dữ liệu thực nghiệm chưa biết","D":"Không chắc chắn về quy trình thu thập dữ liệu"},"answerDisplay":"B. lack of explainability and what a model is actually looking at to make it's prediction","concept":"• Unknown Unknowns trong AI Hộp đen là các rủi ro mà chúng ta thậm chí không biết là chúng tồn tại do không thể giải thích cơ chế ra quyết định của mô hình.","whyCorrect":"• Việc không thể biết mô hình đang dựa vào quy luật nào bên trong là rủi ro Unknown Unknowns nguy hại nhất.","whyWrong":{"A":"• Đạo đức nhóm nghiên cứu là rủi ro quản trị con người.","C":"• Thiếu dữ liệu thực nghiệm là Known Unknowns.","D":"• Không chắc quy trình thu thập là rủi ro Data Provenance."}}},{"id":33,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":33,"chooseType":"Choose 1 answer","question":"Once a dataset has been cleaned, which accuracy guideline ensures your model is looking at the problem correctly?","options":{"A":"Domain expertise","B":"Objective summarization","C":"Dataset verification","D":"First principles"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Sau khi tập dữ liệu đã được làm sạch, hướng dẫn độ chính xác nào đảm bảo mô hình đang tiếp cận bài toán đúng đắn theo góc nhìn chuyên môn?","optionsVi":{"A":"Tri thức / Chuyên môn miền (Domain expertise)","B":"Tóm tắt khách quan","C":"Xác minh tập dữ liệu","D":"Nguyên lý đầu tiên"},"answerDisplay":"A. Domain expertise","concept":"• Domain Expertise (Tri thức chuyên ngành) đảm bảo các biến số và giả định toán học của mô hình phù hợp với thực tế vận hành chuyên môn.","whyCorrect":"• Chuyên môn miền giúp đánh giá tính hợp lý và đúng đắn của logic dự đoán trong bối cảnh thực tế.","whyWrong":{"B":"• Objective summarization là phương pháp tóm tắt dữ liệu.","C":"• Dataset verification là bước kiểm tra định dạng dữ liệu.","D":"• First principles là lập luận nguyên lý cơ bản."}}},{"id":34,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":34,"chooseType":"Choose 1 answer","question":"What is the primary purpose of differential privacy?","options":{"A":"To enable parties to share private data without revealing individual identity in the dataset","B":"To remove direct identifiers that can be used to identify individuals","C":"To only allow certain parties to access certain portions of the data","D":"To ensure the data is completely confidential"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Mục đích chính của Tính riêng tư vi sai (Differential Privacy) là gì?","optionsVi":{"A":"Cho phép các bên chia sẻ và phân tích dữ liệu riêng tư mà không làm lộ danh tính của bất kỳ cá nhân nào có trong tập dữ liệu (share private data without revealing individuals)","B":"Loại bỏ định danh trực tiếp","C":"Phân quyền truy cập từng phần dữ liệu","D":"Bảo mật tuyệt đối dữ liệu"},"answerDisplay":"A. To enable parties to share private data without revealing individuals represented in the data.","concept":"• Differential Privacy thêm nhiễu toán học ngẫu nhiên vào dữ liệu để cho phép phân tích thống kê tổng thể mà triệt tiêu khả năng suy luận danh tính cá nhân.","whyCorrect":"• Giúp chia sẻ dữ liệu nghiên cứu an toàn mà không làm lộ dữ liệu cá thể.","whyWrong":{"B":"• Loại bỏ định danh trực tiếp là Anonymization đơn thuần.","C":"• Phân quyền truy cập là Access Control (RBAC).","D":"• Bảo mật tuyệt đối là Encryption."}}},{"id":35,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":35,"chooseType":"Choose 1 answer","question":"If your company needs to do the same automated analysis as new data comes in every month, what is the best term to describe that process?","options":{"A":"Pipeline (Data Pipeline)","B":"Workflow","C":"Swimlane","D":"Use case"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Nếu công ty bạn cần thực hiện cùng một quy trình phân tích tự động khi dữ liệu mới đổ về hàng tháng, thuật ngữ nào mô tả đúng nhất quy trình đó?","optionsVi":{"A":"Đường ống xử lý dữ liệu (Data Pipeline)","B":"Luồng công việc (Workflow)","C":"Làn bơi (Swimlane)","D":"Tình huống sử dụng (Use case)"},"answerDisplay":"A. pipeline","concept":"• Data Pipeline là chuỗi tự động hóa thu thập, biến đổi, làm sạch và phân tích dữ liệu lặp đi lặp lại theo định kỳ.","whyCorrect":"• Tự động hóa quy trình phân tích dữ liệu đầu vào định kỳ là bản chất của Data Pipeline.","whyWrong":{"B":"• Workflow là quy trình làm việc chung của con người.","C":"• Swimlane là sơ đồ phân công trách nhiệm.","D":"• Use case là kịch bản ứng dụng phần mềm."}}},{"id":36,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":36,"chooseType":"Choose 2 answers","question":"Which of the following are important ethical elements to safeguard within ethical AI systems? (Select two.)","options":{"A":"Accountability and management of bias","B":"Transparency and explainability, balanced with privacy","C":"The number of layers, tensors, or parameters used","D":"Performance and optimization speed"},"answer":"A, B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Những yếu tố đạo đức quan trọng nào sau đây cần được bảo vệ trong các hệ thống AI có đạo đức? (Select two)","optionsVi":{"A":"Trách nhiệm giải trình và quản lý thiên vị (Accountability and management of bias)","B":"Tính minh bạch và tính giải thích được, cân bằng với quyền riêng tư (Transparency and explainability, balanced with privacy)","C":"Số lượng lớp nơ-ron và tham số","D":"Hiệu suất và tốc độ tối ưu hóa"},"answerDisplay":"A. Accountability and management of bias. & B. Transparency and explainability, balanced with privacy.","concept":"• Các trụ cột của AI có trách nhiệm (Trustworthy AI): 1. Accountability & Bias control, 2. Transparency & Explainability & Privacy protection.","whyCorrect":"• Hai nhóm trụ cột này là cốt lõi của mọi khung làm việc đạo đức AI chuẩn mực.","whyWrong":{"C":"• Số lớp nơ-ron là thông số kỹ thuật.","D":"• Hiệu suất và tốc độ là chỉ số tối ưu hóa phần mềm."}}},{"id":37,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":37,"chooseType":"Choose 1 answer","question":"Which of the following describes the black box problem in AI?","options":{"A":"It is difficult to understand how or why an AI system made a particular decision.","B":"It is difficult to understand the nature of data being used.","C":"It is difficult to understand the results coming from an AI system.","D":"It is difficult to generate reports."},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả bài toán Hộp đen (Black box problem) trong AI?","optionsVi":{"A":"Rất khó để hiểu cách thức hoặc lý do tại sao hệ thống AI lại đưa ra một quyết định cụ thể (difficult to understand how or why AI made a decision)","B":"Khó hiểu bản chất dữ liệu huấn luyện","C":"Khó hiểu kết quả đầu ra","D":"Khó tạo báo cáo"},"answerDisplay":"A. It is difficult to understand how or why an Al system made a particular decision.","concept":"• Black Box Problem xảy ra khi logic tính toán toán học bên trong của mô hình AI quá phức tạp khiến con người không thể giải thích lý do dẫn đến kết quả.","whyCorrect":"• Không thể giải thích lập luận ra quyết định bên trong của AI là bản chất của vấn đề Black Box.","whyWrong":{"B":"• Bản chất dữ liệu có thể kiểm tra qua Data Profiling.","C":"• Kết quả đầu ra hiển thị rõ ràng.","D":"• Báo cáo là công cụ xuất dữ liệu."}}},{"id":38,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":38,"chooseType":"Choose 1 answer","question":"What is one possible reason a predictive model may predict a higher crime rate based on historical datasets used?","options":{"A":"If drug arrests are historically high in that area, the model may correlate crime with areas of high drug enforcement based on datasets","B":"If crime is down, the model predicts a parabolic curve","C":"The model's training curve had insufficient data","D":"Formatting error in dataset"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Lý do khả thi nào khiến một mô hình dự đoán dự báo tỷ lệ tội phạm cao hơn tại một khu vực dựa trên dữ liệu lịch sử?","optionsVi":{"A":"Nếu số vụ bắt giữ ma túy trong lịch sử cao tại khu vực đó, mô hình sẽ đánh đồng tương quan tỷ lệ tội phạm với tần suất tuần tra bắt giữ (historically high drug arrests correlated with crime)","B":"Mô hình dự báo đường cong hình parabol","C":"Đường cong huấn luyện thiếu dữ liệu","D":"Lỗi định dạng dữ liệu"},"answerDisplay":"A. If drug arrests are historically high in that area, the model may correlate crime with areas of high drug use based on the datasets","concept":"• Feedback Loop in Predictive Policing: Mô hình nhận dữ liệu bắt giữ lịch sử (phản ánh tần suất cảnh sát tuần tra) và nhầm lẫn đó là tỷ lệ tội phạm thực tế.","whyCorrect":"• Phản ánh hiện tượng mô hình AI nhầm lẫn giữa tần suất thực thi pháp luật lịch sử với tỷ lệ tội phạm khách quan.","whyWrong":{"B":"• Mô hình không tự động tạo ra đường cong parabol phi lý.","C":"• Thiếu dữ liệu gây lỗi variance chứ không tạo định kiến khu vực cụ thể.","D":"• Lỗi định dạng gây ra crash mã nguồn."}}},{"id":39,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":39,"chooseType":"Choose 1 answer","question":"At what point should ethical consideration ideally be applied to emerging technologies?","options":{"A":"From its inception, through maintenance, to applying foresight regarding its decommissioning","B":"Once an ethical issue has received negative feedback in public media","C":"Upon delivery, with appropriate warranties where necessary","D":"During periodic reviews after deployment"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Thời điểm nào là lý tưởng nhất để áp dụng các xem xét đạo đức vào các công nghệ mới nổi?","optionsVi":{"A":"Từ khi khởi tạo ý tưởng, xuyên suốt quá trình bảo trì, cho đến khi ngừng hoạt động (From inception, through maintenance, to decommissioning)","B":"Khi sự cố nhận phản hồi tiêu cực trên truyền thông","C":"Khi bàn giao sản phẩm","D":"Trong các đợt đánh giá định kỳ sau triển khai"},"answerDisplay":"A. From its inception, through maintenance, to applying foresight regarding its decommissioning.","concept":"• Vòng đời Đạo đức Toàn diện (End-to-End Ethical Lifecycle): Đạo đức phải được tích hợp xuyên suốt từ khởi tạo (Inception), phát triển, vận hành cho đến khi hủy bỏ (Decommissioning).","whyCorrect":"• Tích hợp đạo đức xuyên suốt toàn bộ vòng đời sản phẩm đảm bảo sự an toàn và có trách nhiệm tối đa.","whyWrong":{"B":"• Đợi phàn nàn truyền thông là thái độ thụ động nguy hiểm.","C":"• Áp dụng khi bàn giao là quá muộn.","D":"• Đánh giá định kỳ chỉ là một phần nhỏ của quản trị."}}},{"id":40,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":40,"chooseType":"Choose 1 answer","question":"What is the difference between beneficence and non-maleficence?","options":{"A":"Beneficence refers to 'do only good' and non-maleficence refers to 'do no harm'","B":"Beneficence is a less important goal than non-maleficence","C":"Beneficence and non-maleficence are identical","D":"Non-maleficence refers only to malevolent AGI"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Sự khác biệt giữa Thuyết làm điều thiện (Beneficence) và Thuyết không gây hại (Non-maleficence) là gì?","optionsVi":{"A":"Beneficence đề cập đến việc 'chỉ làm điều tốt/mang lại lợi ích', còn Non-maleficence đề cập đến việc 'không gây ra tổn hại' ('do good' vs 'do no harm')","B":"Beneficence kém quan trọng hơn","C":"Cả hai hoàn toàn giống nhau","D":"Non-maleficence chỉ áp dụng cho AGI ác ý"},"answerDisplay":"A. Beneficence refers to \"do only good\" and non-maleficence refers to \"do no harm\"","concept":"• Hai nguyên tắc đạo đức sinh học/AI cốt lõi: Beneficence (Chủ động làm điều có lợi cho con người) và Non-maleficence (Tránh tuyệt đối việc gây ra tổn hại).","whyCorrect":"• Phân biệt chính xác giữa hành vi chủ động tạo lợi ích (Beneficence) và nguyên tắc ngắm chừng không gây hại (Non-maleficence).","whyWrong":{"B":"• Cả hai nguyên tắc đều có tầm quan trọng ngang nhau.","C":"• Chúng có ranh giới triết học rõ ràng.","D":"• Không giới hạn trong phạm vi AGI."}}},{"id":41,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":41,"chooseType":"Choose 1 answer","question":"What is non-maleficence?","options":{"A":"The principle of doing no harm","B":"The principle of having no bias","C":"The principle of having no security risk","D":"The principle of maximizing profits"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Khái niệm Không gây hại (Non-maleficence) được định nghĩa là gì?","optionsVi":{"A":"Nguyên tắc không gây ra tổn hại cho con người và xã hội (The principle of doing no harm)","B":"Nguyên tắc không có thiên vị","C":"Nguyên tắc không có rủi ro an ninh","D":"Nguyên tắc tối đa hóa lợi nhuận"},"answerDisplay":"A. The principle of doing no harm.","concept":"• Non-maleficence (Primum non nocere - Trước tiên là không gây hại) là quy tắc đạo đức cơ bản yêu cầu hệ thống công nghệ không được gây ra thiệt hại cho người dùng.","whyCorrect":"• Định nghĩa kinh điển của nguyên tắc Non-maleficence là 'Do no harm'.","whyWrong":{"B":"• Không thiên vị là Fairness.","C":"• Không có rủi ro an ninh là Security/Robustness.","D":"• Tối đa lợi nhuận là Commercial goal."}}},{"id":42,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":42,"chooseType":"Choose 1 answer","question":"Why is the question of robot rights and emancipation one that isn't as important as addressing issues of bias, privacy, transparency, and other principles discussed in the various ethical frameworks?","options":{"A":"These rights necessitate that robots become sentient entities, which is currently not feasible.","B":"Humans are anthropocentric and don't want to extend rights.","C":"There is no legal precedent.","D":"Robots are mechanical instruments."},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Tại sao câu hỏi về quyền và sự giải phóng của robot lại không quan trọng bằng việc giải quyết các vấn đề về thiên vị, quyền riêng tư, tính minh bạch trong các khung đạo đức AI hiện nay?","optionsVi":{"A":"Các quyền này đòi hỏi robot phải trở thành các thực thể có tri giác, điều mà hiện tại hoàn toàn không khả thi (necessitate robots become sentient entities)","B":"Con người coi mình là trung tâm","C":"Không có tiền lệ pháp lý","D":"Robot là công cụ cơ khí"},"answerDisplay":"A. These rights necessitate that robots become sentient entities, which is currently not feasible.","concept":"• Quyền của Robot đòi hỏi trí tuệ nhân tạo phải đạt mức Tri giác (Sentience) và Ý thức, trong khi công nghệ AI hiện tại chỉ là các thuật toán xử lý dữ liệu toán học.","whyCorrect":"• Tính không khả thi về mặt kỹ thuật khiến việc bàn luận quyền cho robot trở nên viển vông so với các rủi ro thiên vị/riêng tư thực tế đang hiện hữu.","whyWrong":{"B":"• Quan điểm vị nhân sinh không phải lý do kỹ thuật cốt lõi.","C":"• Tiền lệ pháp lý có thể tạo mới nếu công nghệ thực sự đạt tri giác.","D":"• Định kiến vật lý không phản ánh lý do công nghệ."}}},{"id":43,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":43,"chooseType":"Choose 1 answer","question":"An example of prioritizing new data over existing historical data to improve model relevance is:","options":{"A":"Using biased survey data instead of parsed survey data","B":"Using parsed Twitter data over parsed Facebook data","C":"Using new data over existing data (Recency bias / Data freshness)","D":"Using scraped Twitter data over survey data"},"answer":"C","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Một ví dụ về việc ưu tiên dữ liệu mới hơn dữ liệu lịch sử có sẵn để nâng cao tính cập nhật cho mô hình là gì?","optionsVi":{"A":"Dùng dữ liệu khảo sát bị thiên vị","B":"Dùng dữ liệu Twitter hơn dữ liệu Facebook","C":"Sử dụng dữ liệu mới hơn dữ liệu lịch sử hiện có (Using new data over existing data)","D":"Dùng dữ liệu Twitter thay vì khảo sát"},"answerDisplay":"C. using new data over existing data","concept":"• Data Freshness (Tính tươi mới của dữ liệu): Sử dụng dữ liệu mới cập nhật phản ánh đúng thực tế hành vi hiện tại hơn các dữ liệu lịch sử đã lỗi thời.","whyCorrect":"• Ưu tiên dữ liệu mới giúp mô hình cập nhật xu hướng tiêu dùng và hành vi xã hội hiện hành.","whyWrong":{"A":"• Dữ liệu thiên vị làm suy giảm chất lượng mô hình.","B":"• Lựa chọn nền tảng mạng xã hội phụ thuộc mục đích nghiên cứu.","D":"• Dữ liệu cào web Twitter có thể chứa nhiều nhiễu hơn khảo sát chuẩn."}}},{"id":44,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":44,"chooseType":"Choose 1 answer","question":"When your collected data doesn't accurately reflect the full environment, you're experiencing:","options":{"A":"Prejudice bias","B":"Observer bias","C":"Exclusion bias","D":"Sample bias"},"answer":"D","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Khi dữ liệu bạn thu thập được không phản ánh chính xác và toàn diện môi trường thực tế, bạn đang gặp phải loại thiên vị nào?","optionsVi":{"A":"Thiên vị định kiến (Prejudice bias)","B":"Thiên vị người quan sát (Observer bias)","C":"Thiên vị loại trừ (Exclusion bias)","D":"Thiên vị mẫu (Sample bias)"},"answerDisplay":"D. sample bias","concept":"• Sample Bias (Thiên vị mẫu) xảy ra khi mẫu thu thập không đại diện đúng cho phân bố của tổng thể thực tế.","whyCorrect":"• Thu thập mẫu không bao quát đầy đủ môi trường thực tế gây ra hiện tượng lệch mẫu.","whyWrong":{"A":"• Prejudice bias là định kiến văn hóa xã hội có sẵn.","B":"• Observer bias xảy ra khi người nghiên cứu ghi nhận dữ liệu bị chủ quan.","C":"• Exclusion bias là loại bỏ một nhóm cụ thể trong quá trình xử lý."}}},{"id":45,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":45,"chooseType":"Choose 2 answers","question":"Which of the following are ways that regulations differ from ethical frameworks? (Select two.)","options":{"A":"Regulations are often industry led","B":"Regulations are flexible in their implementation.","C":"Regulations have legal enforcement behind them.","D":"Regulations provide a clear basis for potential litigation."},"answer":"C, D","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Những điểm nào sau đây phân biệt Quy định pháp lý (Regulations) với Khung làm việc đạo đức (Ethical Frameworks)? (Select two)","optionsVi":{"A":"Quy định thường do ngành dẫn dắt","B":"Quy định linh hoạt khi triển khai","C":"Quy định có sự cưỡng chế thi hành bằng pháp luật (Regulations have legal enforcement behind them)","D":"Quy định cung cấp cơ sở rõ ràng cho các tranh tụng pháp lý (Clear basis for potential litigation)"},"answerDisplay":"C. Regulations have legal enforcement behind them. & D. Regulations provide a clear basis for potential litigation.","concept":"• Sự khác biệt chính giữa Pháp lý và Đạo đức: Pháp lý có tính cưỡng chế (Legal Enforcement) và phạt chế tài trước tòa, còn Khung đạo đức mang tính tự nguyện và tự quản.","whyCorrect":"• Tính cưỡng chế pháp luật và làm cơ sở xử lý tranh tụng tòa án là đặc trưng riêng của văn bản pháp lý.","whyWrong":{"A":"• Khung đạo đức thường do ngành dẫn dắt nhiều hơn quy định nhà nước.","B":"• Quy định pháp lý cứng nhắc hơn khung đạo đức linh hoạt."}}},{"id":46,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":46,"chooseType":"Choose 1 answer","question":"Which of the following is the most important ethical consideration regarding technical developments like deepfakes?","options":{"A":"They take away monetization opportunities, leaving individuals unfairly compensated for their data","B":"They usurp a person's likeness and can then be weaponized against them.","C":"They violate data sharing agreements in many jurisdictions.","D":"They are built on technological progress made by a third-party organization."},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Mối quan ngại đạo đức quan trọng nhất đối với các phát triển kỹ thuật như Deepfakes là gì?","optionsVi":{"A":"Chúng làm mất cơ hội kiếm tiền của cá nhân","B":"Chúng tước đoạt và mạo danh hình ảnh/giọng nói của một người, sau đó có thể bị biến thành vũ khí chống lại chính họ (usurp likeness and weaponized against them)","C":"Chúng vi phạm thỏa thuận chia sẻ dữ liệu","D":"Chúng xây dựng trên tiến bộ của bên thứ ba"},"answerDisplay":"B. They usurp a person's likeness and can then be weaponized against them.","concept":"• Rủi ro Deepfake tước đoạt danh tính số, hình ảnh, giọng nói của cá nhân để bôi nhọ, tống tiền hoặc lừa đảo xã hội.","whyCorrect":"• Việc mạo danh hình ảnh cá nhân để vũ khí hóa gây tổn hại danh dự và an toàn cá nhân là nguy cơ nghiêm trọng nhất.","whyWrong":{"A":"• Mất cơ hội kiếm tiền chỉ là thương mại.","C":"• Vi phạm thỏa thuận chia sẻ là vấn đề hợp đồng.","D":"• Xây dựng trên công nghệ bên thứ ba là sở hữu trí tuệ."}}},{"id":47,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":47,"chooseType":"Choose 1 answer","question":"Which school of philosophical thought primarily advocates for a global moral code?","options":{"A":"Utilitarianism","B":"Deontology","C":"Virtue ethics","D":"Relativism"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Trường phái tư tưởng triết học nào chủ yếu cổ vũ cho một bộ quy tắc đạo đức toàn cầu có tính nghĩa vụ tuyệt đối?","optionsVi":{"A":"Thuyết vị lợi (Utilitarianism)","B":"Thuyết nghĩa vụ luận (Deontology)","C":"Thuyết đạo đức đức hạnh (Virtue ethics)","D":"Thuyết tương đối đạo đức"},"answerDisplay":"B. Deontology","concept":"• Deontology (Thuyết nghĩa vụ luận của Immanuel Kant) cho rằng các quy tắc đạo đức là những mệnh lệnh tuyệt đối (Categorical Imperatives) áp dụng phổ quát cho toàn nhân loại.","whyCorrect":"• Nghĩa vụ luận đòi hỏi tuân thủ các quy tắc đạo đức tuyệt đối không thay đổi theo hoàn cảnh.","whyWrong":{"A":"• Utilitarianism đánh giá đạo đức dựa trên kết quả/hậu quả.","C":"• Virtue ethics tập trung vào phẩm chất và đức hạnh cá nhân.","D":"• Relativism cho rằng đạo đức thay đổi theo văn hóa."}}},{"id":48,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":48,"chooseType":"Choose 1 answer","question":"How does the 'virtuous cycle' that benefits Big Tech operate?","options":{"A":"Organizations write algorithms with fewer biases, which leads to fairer outcomes.","B":"By acting virtuous, the public respects Big Tech more and more.","C":"Better classes of customers lead to richer and more refined data for algorithmic systems.","D":"Data-driven algorithms improve solutions, leading to new customers, and better data."},"answer":"D","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Chu trình tăng trưởng độc quyền ('Virtuous Cycle') mang lại lợi ích cho các tập đoàn Big Tech vận hành như thế nào?","optionsVi":{"A":"Tổ chức viết thuật toán ít thiên vị dẫn tới kết quả công bằng hơn","B":"Hành động đạo đức giúp công chúng tôn trọng Big Tech hơn","C":"Khách hàng tốt mang lại dữ liệu phong phú hơn","D":"Thuật toán dựa trên dữ liệu cải thiện giải pháp -> Thu hút khách hàng mới -> Thu thập thêm dữ liệu tốt hơn (Data -> Product -> Users -> More Data)"},"answerDisplay":"D. Data-driven algorithms improve solutions, leading to new customers, and better data.","concept":"• Vòng lặp phản hồi dữ liệu (Data Flywheel Effect): Càng nhiều dữ liệu -> Thuật toán càng thông minh -> Sản phẩm càng tốt -> Thu hút thêm người dùng -> Lại có thêm dữ liệu độc quyền.","whyCorrect":"• Chu trình tự củng cố giữa dữ liệu, chất lượng sản phẩm và lượng người dùng tạo nên lợi thế độc quyền cho Big Tech.","whyWrong":{"A":"• Viết thuật toán ít thiên vị là mục tiêu đạo đức.","B":"• Công chúng tôn trọng là hiệu ứng thương hiệu.","C":"• Khách hàng giàu không phải nguyên nhân cốt lõi của chu trình."}}},{"id":49,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":49,"chooseType":"Choose 1 answer","question":"A model that equalizes the number of mistakes it makes for each subgroup to reduce harm is deciding on:","options":{"A":"Equality of false negatives","B":"Equality of true outcomes","C":"Equality of training data","D":"Equality of prediction bias"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Một mô hình bằng cân bằng số lượng sai sót mà nó mắc phải cho mỗi nhóm nhỏ để giảm thiểu tổn hại là đang quyết định về tiêu chuẩn nào?","optionsVi":{"A":"Bình đẳng âm tính giả (Equality of false negatives)","B":"Bình đẳng kết quả thực tế","C":"Bình đẳng dữ liệu huấn luyện","D":"Bình đẳng thiên vị dự đoán"},"answerDisplay":"A. equality of false negatives","concept":"• Equality of False Negatives đảm bảo tỷ lệ bỏ sót sai sót gây hại đạt mức ngang nhau giữa tất cả các phân nhóm xã hội.","whyCorrect":"• Cân bằng tỷ lệ Âm tính giả giữa các nhóm đảm bảo rủi ro bỏ sót tổn hại không bị dồn lên một nhóm yếu thế cụ thể.","whyWrong":{"B":"• Bình đẳng kết quả là Equalized Odds tổng thể.","C":"• Dữ liệu huấn luyện là phân phối mẫu đầu vào.","D":"• Thiên vị dự đoán là chỉ số đo lường độ lệch chung."}}},{"id":50,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":50,"chooseType":"Choose 1 answer","question":"Which type of fairness fails to address merit while maintaining accuracy?","options":{"A":"Error rate parity","B":"Statistical parity (Demographic parity)","C":"Equality of false positives","D":"Equality of prediction rate"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Loại tiêu chuẩn công bằng nào thất bại trong việc đánh giá năng lực/xứng đáng cá nhân (merit) trong khi cố duy trì tỷ lệ ngang bằng giữa các nhóm?","optionsVi":{"A":"Cân bằng tỷ lệ lỗi (Error rate parity)","B":"Cân bằng thống kê / nhân khẩu học (Statistical parity)","C":"Bình đẳng dương tính giả","D":"Bình đẳng tỷ lệ dự đoán"},"answerDisplay":"B. statistical parity","concept":"• Statistical Parity (Demographic Parity) ép buộc tỷ lệ lựa chọn bằng nhau giữa các nhóm mà không xét đến độ xứng đáng (merit) thực tế của từng cá nhân trong nhóm.","whyCorrect":"• Cân bằng chỉ số nhóm cố định có thể bỏ qua sự chênh lệch năng lực cá nhân thực tế giữa các nhóm.","whyWrong":{"A":"• Error rate parity xét tỷ lệ lỗi sai dự đoán.","C":"• False positive parity xét tỷ lệ báo động giả.","D":"• Prediction rate parity là chỉ số đầu ra."}}},{"id":51,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":51,"chooseType":"Choose 1 answer","question":"What is the purpose of what-if scenario planning sessions?","options":{"A":"To think critically about the tradeoffs between company values and business needs so you can decide how to proceed","B":"To think critically about mistakes so you can identify what should do after a violation","C":"To think critically about potential worst-case scenarios so you can decide whether or not to proceed with a project","D":"To think critically about best-case scenarios"},"answer":"C","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Mục đích của các buổi diễn tập lập kế hoạch kịch bản giả định 'What-if' là gì?","optionsVi":{"A":"Suy nghĩ về sự đánh đổi giá trị","B":"Suy nghĩ về các sai lầm sau khi sự cố xảy ra","C":"Tư duy phản biện về các kịch bản tồi tệ nhất có thể xảy ra (worst-case scenarios) để quyết định có nên tiếp tục dự án hay không","D":"Suy nghĩ về kịch bản tốt nhất"},"answerDisplay":"C. The purpose of what-if scenario planning sessions is to think critically about potential worst-case scenarios so you can decide whether or not to proceed with a project","concept":"• Diễn tập kịch bản 'What-if' đóng vai trò quản lý rủi ro dự phòng, giúp nhận diện các thảm họa tồi tệ nhất (Worst-case) để phòng ngừa hoặc dừng dự án kịp thời.","whyCorrect":"• Đánh giá kịch bản xấu nhất giúp tổ chức quyết định tính khả thi và an toàn đạo đức của dự án trước khi triển khai.","whyWrong":{"A":"• Đánh đổi giá trị là phân tích đạo đức chung.","B":"• Xử lý sự cố là Post-mortem report.","D":"• Kịch bản tốt nhất (Best-case) không phản ánh tư duy quản lý rủi ro."}}},{"id":52,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":52,"chooseType":"Choose 1 answer","question":"Which of the following describes the purpose of having an Ethics Board for a data-driven organization?","options":{"A":"An Ethics Board can help maintain an organization's values-based intentions and increase transparency into how they use data-driven technologies","B":"An Ethics Board can help maintain values-based intentions and decrease inherent dangers","C":"An Ethics Board can help maintain profit margins","D":"An Ethics Board can increase transparency into how the organization uses AI"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng mục đích của việc thành lập Hội đồng Đạo đức (Ethics Board) cho một tổ chức dựa trên dữ liệu?","optionsVi":{"A":"Hội đồng Đạo đức giúp duy trì các định hướng dựa trên giá trị của tổ chức và tăng cường tính minh bạch trong việc sử dụng công nghệ dựa trên dữ liệu (maintain values-based intentions and increase transparency)","B":"Duy trì định hướng và giảm nguy cơ tự động","C":"Duy trì biên lợi nhuận công ty","D":"Tăng tính minh bạch sử dụng AI"},"answerDisplay":"A. An Ethics Board can help maintain an organization's values-based intentions and increase transparency into how they use data-driven technologies _","concept":"• Hội đồng Đạo đức (Ethics Board) giữ vai trò định hướng giá trị đạo đức và giám sát minh bạch quy trình sử dụng AI trong tổ chức.","whyCorrect":"• Định hướng giá trị cốt lõi và đảm bảo minh bạch là hai nhiệm vụ quan trọng nhất của Ethics Board.","whyWrong":{"B":"• Giảm nguy cơ tự động là công việc kỹ thuật.","C":"• Biên lợi nhuận thuộc về Hội đồng quản trị kinh doanh.","D":"• Tăng minh bạch chỉ là một nửa nhiệm vụ, thiếu khía cạnh định hướng giá trị."}}},{"id":53,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":53,"chooseType":"Choose 1 answer","question":"Which of the following constitute external stakeholders in the context of a code of ethics?","options":{"A":"Business managers","B":"Regulators and Customers","C":"Developers","D":"Designers"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Những đối tượng nào sau đây cấu thành các bên liên quan bên ngoài (External Stakeholders) trong bối cảnh bộ quy tắc đạo đức?","optionsVi":{"A":"Các nhà quản lý kinh doanh","B":"Cơ quan quản lý nhà nước và Khách hàng (Regulators and Customers)","C":"Các nhà phát triển phần mềm","D":"Các nhà thiết kế"},"answerDisplay":"B. Regulators and Customers","concept":"• External Stakeholders bao gồm các cá nhân/tổ chức nằm ngoài doanh nghiệp như Khách hàng, Cơ quan quản lý (Regulators), Cộng đồng và Đối tác.","whyCorrect":"• Cơ quan quản lý và Khách hàng là hai nhóm bên ngoài chịu ảnh hưởng và điều chỉnh chính sách của doanh nghiệp.","whyWrong":{"A":"• Quản lý kinh doanh là Internal Stakeholders.","C":"• Lập trình viên là Internal Stakeholders.","D":"• Nhà thiết kế là Internal Stakeholders."}}},{"id":54,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":54,"chooseType":"Choose 1 answer","question":"Which of the following is a valid reason for tracking the number and severity of an organization's ethical violations?","options":{"A":"It can replace the need for refreshing policies.","B":"It can help provide qualitative and quantitative information that can be used to improve policies.","C":"It can dissuade end users from scrutinizing policies.","D":"It can help provide transparency around efforts to improve policies."},"answer":"D","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Lý do hợp lệ nào cho việc theo dõi số lượng và mức độ nghiêm trọng của các vi phạm đạo đức trong một tổ chức?","optionsVi":{"A":"Thay thế nhu cầu cập nhật chính sách","B":"Cung cấp thông tin định tính và định lượng","C":"Can ngăn người dùng soi xét chính sách","D":"Giúp cung cấp sự minh bạch xung quanh các nỗ lực cải thiện chính sách (provide transparency around efforts to improve policies)"},"answerDisplay":"D. It can help provide transparency around the efforts to improve the policies.","concept":"• Ghi nhận và công khai chỉ số vi phạm đạo đức giúp tổ chức minh bạch hóa kết quả xử lý và chứng minh nỗ lực cải tiến liên tục.","whyCorrect":"• Minh bạch hóa nỗ lực cải tiến chính sách củng cố niềm tin của các bên liên quan vào tổ chức.","whyWrong":{"A":"• Theo dõi vi phạm càng làm tăng nhu cầu cập nhật chính sách.","B":"• Định tính định lượng là dạng dữ liệu, không phải lý do minh bạch.","C":"• Ngăn cản người dùng soi xét là thái độ che giấu phi đạo đức."}}},{"id":55,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":55,"chooseType":"Choose 1 answer","question":"Which of the following might be a risk of not having an ethical organizational culture?","options":{"A":"Employees might be less interested in their careers.","B":"Employees might face cognitive dissonance.","C":"Employees will experience a faster approval process to get a product launched.","D":"Employees are more likely to express their opinions about the company."},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Điều nào sau đây có thể là một rủi ro khi không có một văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Nhân viên ít quan tâm hơn đến sự nghiệp","B":"Nhân viên phải đối mặt với sự bất hòa nhận thức (Cognitive dissonance)","C":"Nhân viên trải qua quy trình phê duyệt nhanh hơn","D":"Nhân viên dễ bày tỏ ý kiến hơn"},"answerDisplay":"B. Employees might face cognitive dissonance.","concept":"• Thiếu văn hóa đạo đức khiến nhân viên rơi vào trạng thái bất hòa nhận thức (Cognitive Dissonance) khi mâu thuẫn giữa đạo đức cá nhân và yêu cầu gian dối của công ty.","whyCorrect":"• Sự mâu thuẫn giữa giá trị cá nhân và văn hóa sai trái của công ty gây ra áp lực tâm lý và hoảng loạn nhận thức.","whyWrong":{"A":"• Quan tâm sự nghiệp không phải tác động tâm lý trực tiếp của văn hóa phi đạo đức.","C":"• Phê duyệt nhanh cắt giảm quy trình là hành vi rủi ro vận hành.","D":"• Văn hóa phi đạo đức cấm đoán nhân viên bày tỏ ý kiến phản biện."}}},{"id":56,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":56,"chooseType":"Choose 1 answer","question":"Which of the following is an important reason for continually refreshing an organization's internal and external ethics policies?","options":{"A":"It helps internal stakeholders justify the release of new product features.","B":"It helps maintain alignment with emergent risks and changing ethical posture of products and services.","C":"It helps maintain alignment with cultural values of employees.","D":"It helps demonstrate to senior management that work is being done."},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Lý do quan trọng cho việc liên tục cập nhật làm mới các chính sách đạo đức nội bộ và bên ngoài của tổ chức là gì?","optionsVi":{"A":"Biện minh cho việc phát hành tính năng mới","B":"Giúp duy trì sự đồng bộ với các rủi ro mới nổi và vị thế đạo đức thay đổi của các sản phẩm/dịch vụ (maintain alignment with emergent risks)","C":"Duy trì sự đồng bộ với giá trị văn hóa","D":"Báo cáo tiến độ làm việc cho lãnh đạo"},"answerDisplay":"B. It helps maintain alignment with the emergent risks and changing ethical posture of the products and services of the organization.","concept":"• Công nghệ và rủi ro mới (Emergent Risks) xuất hiện liên tục, đòi hỏi chính sách đạo đức phải được cập nhật thường xuyên để tương thích.","whyCorrect":"• Đảm bảo chính sách luôn bắt kịp với các rủi ro công nghệ mới xuất hiện là lý do quan trọng nhất.","whyWrong":{"A":"• Biện minh tính năng không phải mục tiêu đạo đức.","C":"• Đồng bộ văn hóa là một phần nhỏ.","D":"• Báo cáo hình thức không mang giá trị quản trị rủi ro."}}},{"id":57,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":57,"chooseType":"Choose 1 answer","question":"Which of the following is an important action needed for the finalization of internal and external ethics policies before approval?","options":{"A":"Discarding open issues to provide a clean slate","B":"Documenting the assumptions and choices made in the drafting of the policies","C":"Testing the policy in an already deployed project setting","D":"Ensuring the policies are the same as those from peer organizations"},"answer":"B","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Hành động quan trọng nào cần thiết cho việc hoàn thiện các chính sách đạo đức trước khi phê duyệt chính thức?","optionsVi":{"A":"Bỏ qua các vấn đề còn mở","B":"Ghi chép và lưu trữ tài liệu về các giả định và lựa chọn được đưa ra trong quá trình dự thảo (Documenting assumptions and choices made)","C":"Thử nghiệm chính sách trên dự án đã triển khai","D":"Đảm bảo chính sách giống hệt các công ty đối thủ"},"answerDisplay":"B. Documenting the assumptions and choices made in the drafting of the policies","concept":"• Ghi chép tài liệu về giả định và lý do đưa ra các quyết định trong dự thảo chính sách tạo ra tính giải trình và cơ sở kiểm toán sau này.","whyCorrect":"• Ghi chép các giả định giúp các bên phê duyệt hiểu rõ căn cứ lập luận của bộ chính sách.","whyWrong":{"A":"• Bỏ qua vấn đề chưa giải quyết là che giấu rủi ro.","C":"• Thử nghiệm trên dự án thực tế nên làm ở giai đoạn Pilot.","D":"• Sao chép đối thủ bỏ qua tính đặc thù của tổ chức."}}},{"id":58,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":58,"chooseType":"Choose 1 answer","question":"Which of the following is a key element of communications with internal and external stakeholders regarding an organization's ethics policies?","options":{"A":"Simple to follow and easy to understand","B":"Daily communications","C":"Dense procedural descriptions","D":"Flexible verbiage"},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Yếu tố cốt lõi trong truyền thông với các bên liên quan về chính sách đạo đức của tổ chức là gì?","optionsVi":{"A":"Đơn giản, dễ theo dõi và dễ hiểu (Simple to follow and easy to understand)","B":"Truyền thông hàng ngày","C":"Mô tả quy trình dày đặc phức tạp","D":"Ngôn từ mập mờ linh hoạt"},"answerDisplay":"A. Simple to follow","concept":"• Truyền thông chính sách đạo đức cần ưu tiên tính Đơn giản (Simplicity) và Dễ hiểu để mọi đối tượng đều có thể tiếp thu và tuân thủ.","whyCorrect":"• Tính đơn giản dễ hiểu đảm bảo chính sách thực sự được phổ cập và áp dụng hiệu quả.","whyWrong":{"B":"• Truyền thông hàng ngày gây quá tải thông tin.","C":"• Mô tả quá dày đặc gây cản trở việc đọc và hiểu.","D":"• Ngôn từ mập mờ tạo ra các khe hở vi phạm."}}},{"id":59,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":59,"chooseType":"Choose 1 answer","question":"Why are environmental concerns important to consider in the ethical development of data-driven technologies?","options":{"A":"Data-driven technologies can cause secondary, indirect, or cumulative effects on the environment that might impact people in the long term.","B":"Data-driven technologies directly impact the environment through invasive mining.","C":"Data-driven technologies directly impact environment through pollution.","D":"Data-driven technologies directly impact living things via displacement."},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Tại sao các mối quan ngại về môi trường lại quan trọng cần xem xét trong việc phát triển đạo đức các công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Các công nghệ dựa trên dữ liệu có thể gây ra các tác động thứ cấp, gián tiếp hoặc tích tụ lên môi trường, ảnh hưởng dài hạn tới con người (secondary, indirect, or cumulative effects)","B":"Tác động trực tiếp qua khai thác khoáng sản","C":"Tác động trực tiếp qua ô nhiễm","D":"Tác động trực tiếp gây di dời sinh vật"},"answerDisplay":"A. Data-driven technologies can cause secondary, indirect, or cumulative effects on the environment that might impact people in the long term.","concept":"• Các trung tâm dữ liệu AI tiêu thụ năng lượng khổng lồ và thải lượng khí thải carbon tích tụ (Cumulative Impact), đe dọa môi trường sống dài hạn.","whyCorrect":"• Tác động tích tụ và gián tiếp đến môi trường ảnh hưởng trực tiếp đến sự phát triển bền vững của nhân loại.","whyWrong":{"B":"• Khai thác khoáng sản là chuỗi cung ứng phần cứng.","C":"• Ô nhiễm trực tiếp là rác thải điện tử.","D":"• Di dời sinh vật là tác động sinh thái xây dựng."}}},{"id":60,"task":"su25_fe_re","taskLabel":"SU25 FE RE","num":60,"chooseType":"Choose 1 answer","question":"Which of the following is a reason to periodically update a code of ethics document?","options":{"A":"It allows you to capture the evolving nature of the ethical risks of the product or service that you are developing.","B":"It signals that you care about ethics to internal and external stakeholders.","C":"It reinforces the presence of the code of ethics in the minds of the employees.","D":"It is a fiduciary and regulatory responsibility for the organization to do so."},"answer":"A","source":"ITE302c_SU25_FE_RE","explanation":{"questionVi":"Lý do nào sau đây giải thích tại sao cần định kỳ cập nhật tài liệu bộ quy tắc đạo đức?","optionsVi":{"A":"Cho phép nắm bắt bản chất đang tiến hóa của các rủi ro đạo đức đối với sản phẩm hoặc dịch vụ đang phát triển (capture the evolving nature of ethical risks)","B":"Phát tín hiệu rằng công ty quan tâm đến đạo đức","C":"Củng cố sự hiện diện trong tâm trí nhân viên","D":"Là trách nhiệm pháp lý và ủy thác"},"answerDisplay":"A. It allows you to capture the evolving nature of the ethical risks of the product or service that you are developing.","concept":"• Bản chất rủi ro AI liên tục tiến hóa (Evolving Risks), do đó Bộ quy tắc đạo đức phải là một văn bản sống (Living Document) được định kỳ cập nhật.","whyCorrect":"• Nắm bắt sự thay đổi của rủi ro công nghệ theo thời gian là mục đích thực chất nhất của việc cập nhật quy tắc đạo đức.","whyWrong":{"B":"• Phát tín hiệu chỉ là giá trị truyền thông bề nổi.","C":"• Củng cố nhận thức nhân viên là mục tiêu tập huấn.","D":"• Trách nhiệm pháp lý là điều kiện bắt buộc tối thiểu."}}},{"id":1,"task":"su25_fe","taskLabel":"SU25 FE","num":1,"chooseType":"Choose 2 answers","question":"You want to solicit feedback from users who are seeking explanations about your AI products and services. So, you decide to place a form on your marketing website that users can fill out. Which of the following is the best way to structure that form for the purpose of collecting useful feedback?","options":{"A":"Provide a drop-down menu of feedback categories that users can select from, with a promise that you'll follow up via email.","B":"Provide a series of open questions with a single-line entry field where users can provide short answers.","C":"Provide a series of yes or no questions with radio buttons where users select their respective answers.","D":"Provide a large, unrestricted text box where users can enter their thoughts at length."},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Bạn muốn thu thập phản hồi từ người dùng đang tìm kiếm lời giải thích về các sản phẩm và dịch vụ AI của mình. Bạn quyết định đặt một biểu mẫu trên trang web tiếp thị. Cách nào sau đây là tốt nhất để cấu trúc biểu mẫu đó nhằm thu thập phản hồi hữu ích?","optionsVi":{"A":"Cung cấp menu thả xuống gồm các danh mục phản hồi để người dùng chọn, kèm lời hứa sẽ phản hồi qua email","B":"Cung cấp một loạt câu hỏi mở với ô nhập 1 dòng cho câu trả lời ngắn","C":"Cung cấp các câu hỏi Có/Không với nút chọn radio","D":"Cung cấp một ô văn bản lớn không giới hạn để người dùng nhập ý kiến dài"},"answerDisplay":"A. Provide a drop-down menu of feedback categories that users can select from, with a promise that you'll follow up via email.","concept":"• Phản hồi minh bạch AI cần được phân loại theo danh mục (Categories) để phân luồng xử lý và có cam kết phản hồi cá nhân hóa.","whyCorrect":"• Phân loại danh mục giúp tổ chức chuyển đúng thắc mắc đến đội ngũ chuyên môn và email follow-up đảm bảo tính giải trình.","whyWrong":{"B":"• Ô nhập 1 dòng giới hạn thông tin phản hồi của người dùng.","C":"• Câu hỏi Có/Không quá cứng nhắc, không thể hiện được các thắc mắc phức tạp về AI.","D":"• Ô văn bản không cấu trúc gây khó khăn cho việc phân loại và tự động xử lý phản hồi."}}},{"id":2,"task":"su25_fe","taskLabel":"SU25 FE","num":2,"chooseType":"Choose 1 answer","question":"Which type of risk analysis method uses words like 'unlikely', 'rare' to describe likelihood, and 'low', 'medium', 'high' for impact?","options":{"A":"Semi-qualitative analysis","B":"Quantitative analysis","C":"Semi-quantitative analysis","D":"Qualitative analysis"},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Phương pháp phân tích rủi ro nào sau đây sử dụng các từ như 'ít khả năng', 'hiếm khi' để mô tả khả năng xảy ra, và các từ như 'thấp', 'trung bình', 'cao' để mô tả tác động?","optionsVi":{"A":"Phân tích bán định tính (Semi-qualitative analysis)","B":"Phân tích định lượng (Quantitative analysis)","C":"Phân tích bán định lượng (Semi-quantitative analysis)","D":"Phân tích định tính (Qualitative analysis)"},"answerDisplay":"D. Qualitative analysis","concept":"• Phân tích định tính (Qualitative Analysis) xếp hạng rủi ro dựa trên các thang đo từ ngữ mô tả (High/Medium/Low, Unlikely/Rare) thay vì chỉ số số học.","whyCorrect":"• Sử dụng từ ngữ mô tả định tính là đặc trưng cốt lõi của phương pháp Qualitative Risk Analysis.","whyWrong":{"A":"• Bán định tính kết hợp từ ngữ với thứ tự xếp hạng số.","B":"• Định lượng (Quantitative) sử dụng con số tài chính và xác suất phần trăm cụ thể.","C":"• Bán định lượng gán điểm số (1-5) cho các mức mô hình."}}},{"id":3,"task":"su25_fe","taskLabel":"SU25 FE","num":3,"chooseType":"Choose 1 answer","question":"In reverse-engineering a double coin flip differential model, what would be the probability of getting two heads in a row?","options":{"A":"0.50","B":"0.25","C":"0.75","D":"0.125"},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Khi giải mã ngược một mô hình vi sai tung đồng xu hai lần, xác suất để nhận được hai mặt ngửa (heads) liên tiếp là bao nhiêu?","optionsVi":{"A":"0.50 (50%)","B":"0.25 (25%)","C":"0.75 (75%)","D":"0.125 (12.5%)"},"answerDisplay":"B. 0.25","concept":"• Xác suất của hai sự kiện độc lập đồng thời là tích xác suất từng sự kiện: P(Head và Head) = 0.5 * 0.5 = 0.25.","whyCorrect":"• Mỗi lần tung đồng xu ngửa có xác suất 0.5, tung 2 lần liên tiếp là 0.5 × 0.5 = 0.25.","whyWrong":{"A":"• 0.50 là xác suất của một lần tung duy nhất.","C":"• 0.75 là xác suất nhận được ít nhất một mặt ngửa trong 2 lần tung.","D":"• 0.125 là xác suất nhận được 3 mặt ngửa liên tiếp (0.5^3)."}}},{"id":4,"task":"su25_fe","taskLabel":"SU25 FE","num":4,"chooseType":"Choose 1 answer","question":"During cross-validation, which of the following dataset splits is used to tune the performance of a model?","options":{"A":"Training set","B":"Test set","C":"Validation set","D":"Unit test"},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Trong quá trình kiểm thử chéo (Cross-validation), tập dữ liệu nào được sử dụng để tinh chỉnh hiệu suất của mô hình?","optionsVi":{"A":"Tập huấn luyện (Training set)","B":"Tập kiểm thử (Test set)","C":"Tập xác thực (Validation set)","D":"Tập kiểm thử đơn vị (Unit test)"},"answerDisplay":"C. Validation set","concept":"• Tập xác thực (Validation set) được sử dụng trong quá trình huấn luyện để tinh chỉnh siêu tham số (Hyperparameters) và đánh giá hiện tượng Overfitting.","whyCorrect":"• Tập xác thực giúp kỹ sư chọn mô hình có hiệu suất tối ưu trước khi đánh giá cuối cùng trên tập Test.","whyWrong":{"A":"• Tập Training được dùng để mô hình học trọng số (weights), không dùng để tinh chỉnh siêu tham số.","B":"• Tập Test chỉ dùng để đánh giá độc lập hiệu suất cuối cùng của mô hình đã chốt.","D":"• Unit test là quy trình kiểm thử phần mềm, không phải phân tập dữ liệu machine learning."}}},{"id":5,"task":"su25_fe","taskLabel":"SU25 FE","num":5,"chooseType":"Choose 1 answer","question":"When used in recommendation engines, explainable algorithms can help a company build what with users?","options":{"A":"Efficiency","B":"Accuracy","C":"Profitability","D":"Trust"},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Khi được sử dụng trong các hệ thống gợi ý (Recommendation engines), các thuật toán có thể giải thích được giúp công ty xây dựng yếu tố nào với người dùng?","optionsVi":{"A":"Hiệu suất (Efficiency)","B":"Độ chính xác (Accuracy)","C":"Khả năng sinh lời (Profitability)","D":"Lòng tin (Trust)"},"answerDisplay":"D. Trust","concept":"• Tính giải thích được trong hệ thống gợi ý giúp người dùng hiểu rõ căn cứ gợi ý sản phẩm/nội dung, từ đó củng cố lòng tin (Trust) đối với nền tảng.","whyCorrect":"• Lòng tin của người dùng được củng cố khi hệ thống minh bạch lý do đưa ra đề xuất.","whyWrong":{"A":"• Hiệu suất là đặc tính kỹ thuật tính toán.","B":"• Độ chính xác thuộc về mô hình dự đoán.","C":"• Khả năng sinh lời là chỉ số thương mại doanh nghiệp."}}},{"id":6,"task":"su25_fe","taskLabel":"SU25 FE","num":6,"chooseType":"Choose 1 answer","question":"Which of the following is a recommended security practice for machine learning models?","options":{"A":"Adversarial robustness testing and data sanitization","B":"Storing all plain data in public repositories","C":"Disabling user authentication","D":"Using outdated code libraries"},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Thực hành bảo mật nào sau đây được khuyến nghị cho các mô hình học máy?","optionsVi":{"A":"Kiểm thử tính chống chịu đối kháng và làm sạch dữ liệu (Adversarial robustness testing and data sanitization)","B":"Lưu trữ toàn bộ dữ liệu thô trên kho lưu trữ công khai","C":"Tắt xác thực người dùng","D":"Sử dụng các thư viện mã nguồn đã lỗi thời"},"answerDisplay":"A. Adversarial robustness testing and data sanitization","concept":"• Bảo mật học máy yêu cầu chống chịu trước các cuộc tấn công đối kháng (Adversarial Attacks) và làm sạch dữ liệu đầu vào (Data Sanitization).","whyCorrect":"• Kiểm thử chống chịu đối kháng và làm sạch dữ liệu bảo vệ mô hình khỏi bị thao túng kết quả dự đoán.","whyWrong":{"B":"• Lưu trữ công khai gây rò rỉ nghiêm trọng.","C":"• Tắt xác thực phá hủy hàng rào an ninh.","D":"• Thư viện cũ chứa nhiều lỗ hổng bảo mật."}}},{"id":7,"task":"su25_fe","taskLabel":"SU25 FE","num":7,"chooseType":"Choose 2 answers","question":"Which of the following are potential ethical benefits of conducting pilot tests?","options":{"A":"Guaranteed 100% legal protection","B":"Identifying unknown biases and ethical gaps in real-world scenarios before mass deployment","C":"Eliminating the need for user consent","D":"Bypassing regulatory compliance checks"},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Lợi ích đạo đức tiềm năng nào của việc tiến hành các bài kiểm thử thử nghiệm (Pilot tests)?","optionsVi":{"A":"Đảm bảo bảo vệ pháp lý 100%","B":"Nhận diện các thiên vị không ngờ tới và lỗ hổng đạo đức trong kịch bản thực tế trước khi triển khai hàng loạt","C":"Loại bỏ nhu cầu thu thập sự đồng ý người dùng","D":"Bỏ qua các kiểm tra tuân thủ pháp lý"},"answerDisplay":"B. Identifying unknown biases and ethical gaps in real-world scenarios before mass deployment","concept":"• Thử nghiệm Pilot giúp stress-test mô hình trong môi trường kiểm soát để kịp thời phát hiện các thiên vị ẩn trước khi phát hành đại chúng.","whyCorrect":"• Nhận diện sớm lỗi đạo đức và thiên vị giúp đội ngũ phát triển khắc phục tổn hại trước khi ảnh hưởng quy mô lớn.","whyWrong":{"A":"• Pilot không mang lại sự miễn trừ pháp lý tuyệt đối.","C":"• Pilot vẫn cần tuân thủ Informed Consent.","D":"• Pilot không dùng để lách kiểm tra tuân thủ."}}},{"id":8,"task":"su25_fe","taskLabel":"SU25 FE","num":8,"chooseType":"Choose 1 answer","question":"Differential privacy works by adding what to a dataset?","options":{"A":"Encryption keys","B":"Filters","C":"Random noise","D":"Synthetic labels"},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Tính riêng tư vi sai (Differential Privacy) hoạt động bằng cách thêm yếu tố nào vào tập dữ liệu?","optionsVi":{"A":"Khóa mã hóa","B":"Bộ lọc dữ liệu","C":"Nhiễu ngẫu nhiên (Random noise)","D":"Nhãn tổng hợp"},"answerDisplay":"C. Random noise","concept":"• Differential Privacy thêm nhiễu toán học ngẫu nhiên (Laplace/Gaussian noise) vào kết quả truy vấn để triệt tiêu khả năng truy ngược cá nhân.","whyCorrect":"• Nhiễu ngẫu nhiên làm mờ dữ liệu cá thể nhưng vẫn giữ nguyên xu hướng thống kê của toàn bộ tập dữ liệu.","whyWrong":{"A":"• Khóa mã hóa thuộc về Cryptography.","B":"• Bộ lọc dữ liệu dùng để làm sạch dữ liệu.","D":"• Nhãn tổng hợp dùng cho Data Augmentation."}}},{"id":9,"task":"su25_fe","taskLabel":"SU25 FE","num":9,"chooseType":"Choose 1 answer","question":"Which of the following describes the technique of homomorphic encryption?","options":{"A":"A method of swapping public and private keys between hosts.","B":"A method of cryptography that hides data inside other data.","C":"A method of performing operations on encrypted data.","D":"A method of mitigating biased algorithms through enhanced secrecy."},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả kỹ thuật mã hóa đồng hình (Homomorphic encryption)?","optionsVi":{"A":"Phương pháp hoán đổi khóa công khai và riêng tư","B":"Phương pháp giấu dữ liệu vào trong dữ liệu khác (Steganography)","C":"Phương pháp thực hiện các phép tính toán trực tiếp trên dữ liệu đã mã hóa","D":"Phương pháp giảm thiên vị thuật toán qua tính bảo mật"},"answerDisplay":"C. A method of performing operations on encrypted data.","concept":"• Homomorphic Encryption cho phép tính toán trực tiếp trên ciphertext mà không cần giải mã, giữ an toàn tuyệt đối cho dữ liệu thô.","whyCorrect":"• Cho phép máy chủ điện toán đám mây xử lý dữ liệu mà không bao giờ xem được nội dung chưa mã hóa.","whyWrong":{"A":"• Hoán đổi khóa là Asymmetric key exchange.","B":"• Giấu dữ liệu là Steganography.","D":"• Mã hóa không tự động sửa được thiên vị thuật toán."}}},{"id":10,"task":"su25_fe","taskLabel":"SU25 FE","num":10,"chooseType":"Choose 1 answer","question":"Which team typically oversees penetration test operations and adherence to the rules of engagement (ROE)?","options":{"A":"Blue team","B":"Red team","C":"Purple team","D":"White team"},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Đội ngũ nào thường giám sát hoạt động kiểm thử xâm nhập và tuân thủ các quy tắc tham chiến (Rules of Engagement - ROE)?","optionsVi":{"A":"Đội Xanh (Blue team)","B":"Đội Đỏ (Red team)","C":"Đội Tím (Purple team)","D":"Đội Trắng (White team)"},"answerDisplay":"D. White team","concept":"• Trong diễn tập an ninh mạng: Red Team tấn công, Blue Team phòng thủ, Purple Team phối hợp, và White Team đóng vai trò trọng tài/giám sát tuân thủ quy tắc ROE.","whyCorrect":"• White Team là hội đồng giám sát trọng tài đảm bảo cuộc diễn tập tuân thủ đúng phạm vi an toàn.","whyWrong":{"A":"• Blue Team là bên phòng thủ.","B":"• Red Team là bên tấn công giả lập.","C":"• Purple Team tối ưu hóa chia sẻ tri thức giữa Red và Blue."}}},{"id":11,"task":"su25_fe","taskLabel":"SU25 FE","num":11,"chooseType":"Choose 1 answer","question":"Which of the following is a platform that includes hundreds of security exploit tools?","options":{"A":"Zenmap","B":"Nmap","C":"Kali Linux","D":"Wireshark"},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Nền tảng nào sau đây tích hợp hàng trăm công cụ khai thác bảo mật và kiểm thử xâm nhập?","optionsVi":{"A":"Zenmap","B":"Nmap","C":"Kali Linux","D":"Wireshark"},"answerDisplay":"C. Kali Linux","concept":"• Kali Linux là hệ điều hành Linux chuyên biệt cài đặt sẵn hàng trăm công cụ an ninh mạng, kiểm thử xâm nhập và điều tra số.","whyCorrect":"• Kali Linux là nền tảng chuẩn mực tích hợp sẵn bộ công cụ bảo mật phong phú.","whyWrong":{"A":"• Zenmap là giao diện GUI cho Nmap.","B":"• Nmap là công cụ quét cổng mạng.","D":"• Wireshark là công cụ phân tích gói tin mạng (Packet Sniffer)."}}},{"id":12,"task":"su25_fe","taskLabel":"SU25 FE","num":12,"chooseType":"Choose 2 answers","question":"Which of the following are fundamental risk management tasks? (Select two.)","options":{"A":"Mitigation","B":"Authentication","C":"Compliance","D":"Identification"},"answer":"A, D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Những nhiệm vụ nào sau đây là các nhiệm vụ quản lý rủi ro cơ bản? (Select two)","optionsVi":{"A":"Giảm thiểu rủi ro (Mitigation)","B":"Xác thực người dùng","C":"Tuân thủ pháp lý","D":"Nhận diện rủi ro (Identification)"},"answerDisplay":"A. Mitigation & D. Identification","concept":"• Chu trình quản lý rủi ro bao gồm các bước cốt lõi: Nhận diện (Identification), Đánh giá (Assessment), Giảm thiểu (Mitigation) và Giám sát (Monitoring).","whyCorrect":"• Nhận diện rủi ro là bước đầu tiên và Giảm thiểu rủi ro là bước xử lý cốt lõi.","whyWrong":{"B":"• Xác thực (Authentication) là tính năng an ninh mạng.","C":"• Tuân thủ (Compliance) là mục tiêu quản trị."}}},{"id":13,"task":"su25_fe","taskLabel":"SU25 FE","num":13,"chooseType":"Choose 2 answers","question":"Which of the following are important steps to document during an auditing process? (Select two.)","options":{"A":"Specify and document what precisely is being audited","B":"Document the audit procedures to be followed","C":"Provide significant advance notice before an audit","D":"Specify a purpose for the audit or an agenda to be covered"},"answer":"A, B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Những bước nào sau đây là quan trọng cần lập hồ sơ tài liệu trong quá trình kiểm toán? (Select two)","optionsVi":{"A":"Xác định và ghi chép rõ ràng chính xác đối tượng được kiểm toán (Specify and document what precisely is being audited)","B":"Ghi chép quy trình kiểm toán cần tuân thủ (Document the audit procedures to be followed)","C":"Gửi thông báo trước quá lâu","D":"Tạo chương trình họp chung"},"answerDisplay":"A. Specify and document what precisely is being audited & B. Document the audit procedures to be followed","concept":"• Hồ sơ kiểm toán đòi hỏi tính chính xác về phạm vi kiểm toán (Audit Scope) và quy trình thực hiện (Audit Procedures).","whyCorrect":"• Xác định rõ đối tượng và quy trình giúp đảm bảo tính minh bạch và khả năng tái lập kiểm toán.","whyWrong":{"C":"• Thông báo trước là thủ tục hành chính.","D":"• Lên lịch họp là quản lý thời gian."}}},{"id":14,"task":"su25_fe","taskLabel":"SU25 FE","num":14,"chooseType":"Choose 1 answer","question":"Which of the following measures is best suited for reporting results to an audience?","options":{"A":"Standard deviation","B":"Variance","C":"Mode","D":"Median"},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Chỉ số thống kê nào sau đây phù hợp nhất để báo cáo kết quả cho khán giả đại chúng?","optionsVi":{"A":"Độ lệch chuẩn (Standard deviation)","B":"Phương sai (Variance)","C":"Yếu vị / Mốt (Mode)","D":"Trung vị (Median)"},"answerDisplay":"D. Median","concept":"• Trung vị (Median) dễ hiểu đối với đại chúng vì nó chia tập dữ liệu thành 2 nửa bằng nhau và không bị ảnh hưởng bởi giá trị ngoại lệ (Outliers).","whyCorrect":"• Median mang lại cái nhìn trung thực và dễ tiếp thu cho người nghe không chuyên.","whyWrong":{"A":"• Độ lệch chuẩn là khái niệm thống kê phức tạp cho đại chúng.","B":"• Phương sai khó hình dung trực quan.","C":"• Mode chỉ phản ánh giá trị xuất hiện nhiều nhất."}}},{"id":15,"task":"su25_fe","taskLabel":"SU25 FE","num":15,"chooseType":"Choose 1 answer","question":"A hospital dataset protects whether an individual has had either a stroke, heart attack, or staph infection. The individual may still be harmed via dataset:","options":{"A":"Group inclusion","B":"Privacy columns","C":"k-anonymity leakage","D":"Security issues"},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Tập dữ liệu bệnh viện bảo vệ thông tin cá nhân bị đột quỵ, đau tim hay nhiễm trùng. Cá nhân vẫn có thể bị tổn hại thông qua yếu tố nào?","optionsVi":{"A":"Sự bao hàm nhóm / suy luận nhóm (Group inclusion)","B":"Cột riêng tư","C":"Rò rỉ k-anonymity","D":"Vấn đề an ninh"},"answerDisplay":"A. group inclusion","concept":"• Group Inclusion (Suy luận nhóm) xảy ra khi dữ liệu tiết lộ thuộc tính chung của cả nhóm (ví dụ: 100% người trong nhóm mắc bệnh X), gây xâm phạm riêng tư dù cá nhân đã ẩn danh.","whyCorrect":"• Sự thuộc về nhóm tiết lộ thuộc tính nhạy cảm ngay cả khi danh tính cá nhân chưa bị rò rỉ trực tiếp.","whyWrong":{"B":"• Cột riêng tư là giải pháp thiết kế.","C":"• k-anonymity bị tấn công Homogeneity attack khi toàn bộ nhóm có chung nhạy cảm.","D":"• Vấn đề an ninh là khái niệm chung."}}},{"id":16,"task":"su25_fe","taskLabel":"SU25 FE","num":16,"chooseType":"Choose 1 answer","question":"The organization needs to ask itself about any quality control issues it may be having. Which of the following processes is most suitable for asking and answering that question?","options":{"A":"Business impact assessment","B":"Lessons learned report","C":"Vulnerability audit","D":"Business continuity plan"},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Tổ chức cần tự vấn về các vấn đề kiểm soát chất lượng. Quy trình nào sau đây phù hợp nhất để đặt ra và giải đáp câu hỏi đó?","optionsVi":{"A":"Đánh giá tác động kinh doanh (BIA)","B":"Báo cáo bài học kinh nghiệm rút ra (Lessons learned report)","C":"Kiểm toán lỗ hổng","D":"Kế hoạch duy trì hoạt động kinh doanh"},"answerDisplay":"B. Lessons learned report","concept":"• Báo cáo Bài học kinh nghiệm (Lessons Learned Report) được thực hiện sau dự án/sự cố để đánh giá chất lượng và cải tiến quy trình.","whyCorrect":"• Tổng kết bài học giúp tổ chức nhìn nhận rõ sai sót chất lượng và đưa ra biện pháp khắc phục cho tương lai.","whyWrong":{"A":"• BIA tập trung vào gián đoạn kinh doanh.","C":"• Vulnerability audit tập trung vào lỗ hổng kỹ thuật.","D":"• Business continuity plan phục vụ ứng phó thảm họa."}}},{"id":17,"task":"su25_fe","taskLabel":"SU25 FE","num":17,"chooseType":"Choose 1 answer","question":"Why is it important to take a proactive approach to addressing liability issues?","options":{"A":"The law often lags behind innovation.","B":"The law is not always applied consistently.","C":"The law is not always clear.","D":"The law often difficult to understand"},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Tại sao việc chủ động tiếp cận xử lý các vấn đề trách nhiệm pháp lý lại quan trọng?","optionsVi":{"A":"Luật pháp thường đi sau sự đổi mới công nghệ (The law often lags behind innovation)","B":"Luật pháp không phải lúc nào cũng áp dụng nhất quán","C":"Luật pháp không phải lúc nào cũng rõ ràng","D":"Luật pháp thường khó hiểu"},"answerDisplay":"A. The law often lags behind innovation.","concept":"• Công nghệ AI phát triển nhanh hơn tốc độ ban hành văn bản luật (Pacing Problem). Do đó doanh nghiệp phải chủ động hành động trước khi có luật.","whyCorrect":"• Tốc độ đổi mới công nghệ nhanh khiến pháp luật luôn đi sau, đòi hỏi sự chủ động đạo đức từ doanh nghiệp.","whyWrong":{"B":"• Tính nhất quán là vấn đề thực thi tòa án.","C":"• Tính rõ ràng là kỹ thuật lập pháp.","D":"• Độ khó hiểu thuộc về đào tạo pháp lý."}}},{"id":18,"task":"su25_fe","taskLabel":"SU25 FE","num":18,"chooseType":"Choose 1 answer","question":"When you deliver periodic statements about a crisis to the media, what should the first statement do?","options":{"A":"Provide in-depth details about the situation","B":"Set the tone of what is to follow","C":"Survey public opinion of the organization","D":"Accept responsibility for perceived problems"},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Khi bạn đưa ra các phát biểu định kỳ về một cuộc khủng hoảng cho truyền thông, phát biểu đầu tiên nên làm gì?","optionsVi":{"A":"Cung cấp chi tiết chuyên sâu","B":"Thiết lập định hướng và thái độ cho các thông điệp tiếp theo (Set the tone of what is to follow)","C":"Khảo sát ý kiến công chúng","D":"Nhận trách nhiệm cho mọi sự cố"},"answerDisplay":"B. Set the tone of what is to follow","concept":"• Phát biểu đầu tiên trong khủng hoảng đóng vai trò 'Set the tone' - thể hiện sự bình tĩnh, minh bạch và cam kết giải quyết sự cố.","whyCorrect":"• Định hình thái độ ban đầu giúp ổn định tâm lý dư luận và làm nền tảng cho thông tin cập nhật sau.","whyWrong":{"A":"• Chi tiết chuyên sâu chưa thể có ngay ở thời điểm đầu khủng hoảng.","C":"• Khảo sát ý kiến là bước nghiên cứu thị trường.","D":"• Nhận trách nhiệm vội vã khi chưa xác minh nguyên nhân là rủi ro pháp lý."}}},{"id":19,"task":"su25_fe","taskLabel":"SU25 FE","num":19,"chooseType":"Choose 1 answer","question":"What is the benefit of hosting a virtual reality press conference over a traditional in-person press conference?","options":{"A":"It will be easier to communicate your overall message to your audience.","B":"The conference will be easily accessible to all willing participants.","C":"The conference can be interactive without the participants needing to be co-located.","D":"The participants will be impressed by your leveraging of new and exciting technologies."},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Lợi ích của việc tổ chức họp báo thực tế ảo (VR) so với họp báo trực tiếp truyền thống là gì?","optionsVi":{"A":"Dễ dàng truyền tải thông điệp hơn","B":"Dễ tiếp cận cho mọi người","C":"Buổi họp báo có tính tương tác cao mà các bên không cần phải có mặt tại cùng một địa điểm (interactive without co-location)","D":"Gây ấn tượng bằng công nghệ mới"},"answerDisplay":"C. The conference can be interactive without the participants needing to be co-located.","concept":"• Họp báo VR cho phép tương tác không gian 3D chân thực mà loại bỏ hoàn toàn rào cản khoảng cách địa lý.","whyCorrect":"• Khả năng tương tác từ xa mà không cần tập trung tại một vị trí vật lý là ưu điểm vượt trội của VR.","whyWrong":{"A":"• VR không tự động làm thông điệp dễ hiểu hơn.","B":"• VR yêu cầu thiết bị phần cứng nên chưa thể dễ tiếp cận cho tất cả.","D":"• Gây ấn tượng công nghệ chỉ là yếu tố hình thức."}}},{"id":20,"task":"su25_fe","taskLabel":"SU25 FE","num":20,"chooseType":"Choose 2 answers","question":"Which of the following are important factors to consider when developing a media campaign? (Select two.)","options":{"A":"The environment in which the campaign will be launched","B":"The time-sensitive nature of communication in the campaign","C":"The effect the campaign has on the organization's bottom line","D":"The risks that will be talked about in the campaign"},"answer":"A, B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Những yếu tố nào sau đây là quan trọng cần xem xét khi xây dựng một chiến dịch truyền thông? (Select two)","optionsVi":{"A":"Môi trường và bối cảnh chiến dịch được phát động (The environment in which the campaign will be launched)","B":"Yếu tố thời gian nhạy cảm của thông điệp (The time-sensitive nature of communication)","C":"Tác động tới lợi nhuận công ty","D":"Các rủi ro thảo luận"},"answerDisplay":"A. The environment in which the campaign will be launched & B. The time-sensitive nature of communication in the campaign","concept":"• Truyền thông hiệu quả yêu cầu thấu hiểu bối cảnh môi trường xã hội (Environment) và đảm bảo tính thời điểm (Timing).","whyCorrect":"• Bối cảnh môi trường và tính kịp thời quyết định sự thành bại và độ tiếp nhận của công chúng đối với chiến dịch.","whyWrong":{"C":"• Lợi nhuận là chỉ số tài chính nội bộ.","D":"• Rủi ro thảo luận là một phần của kịch bản."}}},{"id":21,"task":"su25_fe","taskLabel":"SU25 FE","num":21,"chooseType":"Choose 2 answers","question":"Which of the following are pitfalls in communicating risks to the organization? (Select two.)","options":{"A":"Having a disjointed message","B":"Not paying attention to the flow of messaging","C":"Following up messaging with an audience","D":"Coordinating a message between departments"},"answer":"A, B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Những cạm bẫy nào sau đây trong việc truyền thông rủi ro tới tổ chức? (Select two)","optionsVi":{"A":"Thông điệp rời rạc, mâu thuẫn (Having a disjointed message)","B":"Không chú ý tới luồng truyền tải thông điệp (Not paying attention to the flow of messaging)","C":"Theo dõi phản hồi người nghe","D":"Phối hợp thông điệp giữa các phòng ban"},"answerDisplay":"A. Having a disjointed message & B. Not paying attention to the flow of messaging","concept":"• Cạm bẫy truyền thông rủi ro bao gồm sự thiếu thống nhất thông điệp (Disjointed) và thiếu kiểm soát luồng thông tin (Flow).","whyCorrect":"• Thông điệp rời rạc gây hoang mang và lờ đi luồng truyền tin khiến thông điệp bị bóp méo.","whyWrong":{"C":"• Theo dõi phản hồi là thực hành tốt.","D":"• Phối hợp liên phòng ban là thực hành chuẩn."}}},{"id":22,"task":"su25_fe","taskLabel":"SU25 FE","num":22,"chooseType":"Choose 1 answer","question":"Which of the following should be conducted as part of a risk communication strategy in order to ensure the organization is upholding its regulatory obligations?","options":{"A":"Business impact assessment (BIA)","B":"Compliance audit","C":"Ethical risk review","D":"Public relations campaign"},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Hoạt động nào sau đây nên được thực hiện như một phần của chiến lược truyền thông rủi ro để đảm bảo tổ chức tuân thủ các nghĩa vụ pháp lý?","optionsVi":{"A":"Đánh giá tác động kinh doanh (BIA)","B":"Kiểm toán tuân thủ (Compliance audit)","C":"Đánh giá rủi ro đạo đức","D":"Chiến dịch quan hệ công chúng (PR)"},"answerDisplay":"B. Compliance audit","concept":"• Compliance Audit (Kiểm toán tuân thủ) kiểm tra và xác nhận tổ chức thực hiện đúng các quy định pháp luật hiện hành.","whyCorrect":"• Kiểm toán tuân thủ cung cấp bằng chứng minh bạch về việc đáp ứng đầy đủ các nghĩa vụ pháp lý.","whyWrong":{"A":"• BIA tập trung vào khôi phục gián đoạn vận hành.","C":"• Ethical review tập trung vào các giá trị đạo đức.","D":"• PR campaign phục vụ quảng bá hình ảnh."}}},{"id":23,"task":"su25_fe","taskLabel":"SU25 FE","num":23,"chooseType":"Choose 1 answer","question":"Which of the following describes the purpose of a business impact assessment (BIA)?","options":{"A":"It helps you predict business interruptions and develop recovery strategies.","B":"It helps you identify what risks you can accept or transfer to third party.","C":"It helps you evaluate how a product could fail to apply ethical values.","D":"It helps you identify what risks you can accept or transfer to customers."},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng mục đích của Đánh giá tác động kinh doanh (BIA)?","optionsVi":{"A":"Giúp dự đoán sự gián đoạn kinh doanh và xây dựng chiến lược khôi phục (predict business interruptions and develop recovery strategies)","B":"Xác định rủi ro chấp nhận hoặc chuyển giao cho bên thứ ba","C":"Đánh giá thất bại áp dụng giá trị đạo đức","D":"Chuyển giao rủi ro cho khách hàng"},"answerDisplay":"A. It helps you predict business interruptions and develop recovery strategies.","concept":"• BIA (Business Impact Assessment) xác định ảnh hưởng của sự gián đoạn vận hành và lập kế hoạch khôi phục thảm họa.","whyCorrect":"• Mục đích chuẩn mực của BIA là dự báo gián đoạn và thiết lập chiến lược ứng phó khôi phục.","whyWrong":{"B":"• Quản lý rủi ro rỡ ràng thuộc về Risk Treatment.","C":"• Đánh giá đạo đức thuộc về Ethical Impact Assessment.","D":"• Chuyển rủi ro cho khách hàng là vi phạm đạo đức."}}},{"id":24,"task":"su25_fe","taskLabel":"SU25 FE","num":24,"chooseType":"Choose 1 answer","question":"Why is it important to engage stakeholders at the beginning of the ethical risk management process?","options":{"A":"It proves that you are completely equipped to address any ethical risks.","B":"It demonstrates that the organization is committed to accountability and transparency in their data-driven systems.","C":"It helps the organization avoid legal trouble during development.","D":"It lets stakeholders know that the organization cannot address risks without input."},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Tại sao việc tham vấn các bên liên quan (Stakeholders) ngay từ đầu quy trình quản lý rủi ro đạo đức lại quan trọng?","optionsVi":{"A":"Chứng minh công ty xử lý được mọi rủi ro","B":"Thể hiện cam kết của tổ chức đối với trách nhiệm giải trình và tính minh bạch trong các hệ thống dựa trên dữ liệu (committed to accountability and transparency)","C":"Giúp tránh rắc rối pháp lý","D":"Thể hiện sự bất lực nếu không có tham vấn"},"answerDisplay":"B. It demonstrates that the organization is committed to accountability and transparency in their data-driven systems.","concept":"• Tham vấn Stakeholders từ sớm thể hiện thái độ cầu thị, minh bạch và trách nhiệm giải trình của doanh nghiệp trước xã hội.","whyCorrect":"• Cam kết minh bạch và trách nhiệm giải trình được khẳng định qua việc tham vấn chủ động các bên liên quan.","whyWrong":{"A":"• Không tổ chức nào có thể cam kết 100% không có rủi ro.","C":"• Tránh rắc rối pháp lý chỉ là tác dụng phụ.","D":"• Không phải sự bất lực mà là hợp tác có trách nhiệm."}}},{"id":25,"task":"su25_fe","taskLabel":"SU25 FE","num":25,"chooseType":"Choose 2 answers","question":"Why is it important to categorize ethical risks into different types? (Select two.)","options":{"A":"It makes it easier for us to identify and manage different types of risks","B":"It helps us understand the many complexities involved in different types of ethical risks","C":"It ensures that customers know we take risks seriously","D":"It helps us consider risk mitigation in terms of universal tactics"},"answer":"A, B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Tại sao việc phân loại các rủi ro đạo đức thành các dạng khác nhau lại quan trọng? (Select two)","optionsVi":{"A":"Dễ dàng hơn trong việc nhận diện và quản lý từng loại rủi ro (easier to identify and manage)","B":"Giúp hiểu rõ các độ phức tạp đa dạng liên quan đến từng dạng rủi ro đạo đức (understand the complexities)","C":"Đảm bảo khách hàng biết công ty nghiêm túc","D":"Áp dụng chiến thuật chung cho mọi loại"},"answerDisplay":"A. It makes it easier for us to identify and manage different types of risks & B. It helps us understand the many complexities involved in different types of ethical risks","concept":"• Phân loại rủi ro giúp cấu trúc hóa quy trình quản lý rủi ro phức tạp thành các phân nhóm có thể kiểm soát và áp dụng giải pháp chuyên biệt.","whyCorrect":"• Phân loại giúp dễ nhận diện, quản lý và nắm bắt bản chất phức tạp của từng loại rủi ro.","whyWrong":{"C":"• Hiển thị cho khách hàng là hình thức truyền thông.","D":"• Phân loại để áp dụng biện pháp riêng biệt chứ không dùng chiến thuật cào bằng universal."}}},{"id":26,"task":"su25_fe","taskLabel":"SU25 FE","num":26,"chooseType":"Choose 1 answer","question":"What is a likely outcome for a weather app using a learning algorithm to figure out where to put their future weather stations?","options":{"A":"Accessing weather forecasts from local broadcasts","B":"Storing data in an AWS instance with all weather stations in the country","C":"Collecting weather data every time the app is opened","D":"Collecting location data every time the app is opened, potentially learning where a user lives, works, etc."},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Hệ quả tiềm tàng đối với quyền riêng tư khi một ứng dụng thời tiết sử dụng thuật toán học máy để xác định vị trí đặt trạm thời tiết tương lai là gì?","optionsVi":{"A":"Truy cập dự báo địa phương","B":"Lưu dữ liệu trên AWS","C":"Thu thập dữ liệu thời tiết mỗi khi mở app","D":"Thu thập dữ liệu vị trí mỗi khi ứng dụng được mở, có khả năng học được nơi người dùng sống và làm việc (potentially learning where a user lives, works)"},"answerDisplay":"D. Collecting location data every time the app is opened, potentially learning where a user lives, works, etc.","concept":"• Thu thập dữ liệu vị trí GPS liên tục tạo ra rủi ro suy luận thông tin định danh cá nhân nhạy cảm (nhà riêng, cơ quan).","whyCorrect":"• Việc theo dõi vị trí mở app vô tình thu thập thông tin di chuyển cá nhân riêng tư của người dùng.","whyWrong":{"A":"• Xem dự báo là tính năng cơ bản.","B":"• Lưu trữ AWS là hạ tầng điện toán.","C":"• Thu thập thông số thời tiết là dữ liệu khí tượng chung."}}},{"id":27,"task":"su25_fe","taskLabel":"SU25 FE","num":27,"chooseType":"Choose 1 answer","question":"A type of artificial intelligence that outperforms humans in all tasks is known as:","options":{"A":"General AI","B":"Superintelligence (ASI)","C":"Specific AI","D":"Narrow AI"},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Loại trí tuệ nhân tạo vượt trội hơn con người trong mọi tác vụ nhận thức được gọi là gì?","optionsVi":{"A":"AI tổng quát (General AI)","B":"Siêu trí tuệ (Superintelligence / ASI)","C":"AI đặc thù","D":"AI hẹp (Narrow AI)"},"answerDisplay":"B. Superintelligence","concept":"• Artificial Superintelligence (ASI - Siêu trí tuệ) là cấp độ AI lý thuyết vượt xa trí tuệ toàn diện của con người ở mọi lĩnh vực.","whyCorrect":"• Vượt trội hơn con người trong tất cả các lĩnh vực là định nghĩa chuẩn của Superintelligence.","whyWrong":{"A":"• General AI (AGI) ngang bằng với trí tuệ con người.","C":"• Specific AI chỉ làm 1 việc cụ thể.","D":"• Narrow AI chỉ tối ưu bài toán hẹp."}}},{"id":28,"task":"su25_fe","taskLabel":"SU25 FE","num":28,"chooseType":"Choose 1 answer","question":"Which of the following best describes what an algorithm is?","options":{"A":"A recipe that a computer uses to solve problems","B":"A type of process a human uses to write down steps","C":"A type of computer that calculates problem-solving methods","D":"A list of ingredients a computer uses to generate problems"},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất về khái niệm Thuật toán (Algorithm)?","optionsVi":{"A":"Một công thức / tập các chỉ dẫn từng bước mà máy tính sử dụng để giải quyết vấn đề (A recipe that a computer uses to solve problems)","B":"Quy trình con người dùng để ghi chép","C":"Một loại máy tính tính toán","D":"Danh sách nguyên liệu tạo ra bài toán"},"answerDisplay":"A. a recipe that a computer uses to solve problems","concept":"• Thuật toán (Algorithm) là tập hợp hữu hạn các chỉ dẫn rõ ràng từng bước để máy tính thực hiện giải quyết một bài toán toán học hay logic.","whyCorrect":"• Ẩn dụ 'công thức' (recipe) thể hiện chính xác bản chất tập hợp chỉ dẫn tính toán từng bước của thuật toán.","whyWrong":{"B":"• Thuật toán dành cho máy tính thi hành.","C":"• Thuật toán là logic chứ không phải thiết bị máy tính phần cứng.","D":"• Thuật toán dùng để giải quyết bài toán chứ không tạo thêm bài toán."}}},{"id":29,"task":"su25_fe","taskLabel":"SU25 FE","num":29,"chooseType":"Choose 1 answer","question":"A predictive model's true positive result can be defined as:","options":{"A":"The predicted result was negative, and the actual result was negative","B":"The predicted result was negative, and the actual result was positive","C":"The predicted result was positive, and the actual result was positive","D":"The predicted result was positive, and the actual result was negative"},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Kết quả Dương tính thật (True Positive) của một mô hình dự đoán được định nghĩa là gì?","optionsVi":{"A":"Dự đoán Âm tính và Thực tế Âm tính","B":"Dự đoán Âm tính và Thực tế Dương tính","C":"Dự đoán Dương tính và Thực tế Dương tính (Predicted positive, actual positive)","D":"Dự đoán Dương tính và Thực tế Âm tính"},"answerDisplay":"C. the predicted result was positive, and the actual result was positive","concept":"• True Positive (Dương tính thật) xảy ra khi mô hình dự đoán có (Positive) và thực tế đối tượng thực sự có (Positive).","whyCorrect":"• Định nghĩa chính xác của True Positive trong ma trận nhầm lẫn (Confusion Matrix).","whyWrong":{"A":"• Đây là True Negative (Âm tính thật).","B":"• Đây là False Negative (Âm tính giả).","D":"• Đây là False Positive (Dương tính giả)."}}},{"id":30,"task":"su25_fe","taskLabel":"SU25 FE","num":30,"chooseType":"Choose 1 answer","question":"An algorithm that takes an input, tries 10 different sorting techniques, and uses the best fit on the next 100 inputs is best described as a:","options":{"A":"Implicit algorithm","B":"Data algorithm","C":"Learning algorithm","D":"Explicit algorithm"},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Một thuật toán nhận đầu vào, thử 10 kỹ thuật sắp xếp khác nhau, và sử dụng phương pháp tối ưu nhất cho 100 đầu vào tiếp theo được mô tả đúng nhất là:","optionsVi":{"A":"Thuật toán ngầm định","B":"Thuật toán dữ liệu","C":"Thuật toán học tập / học máy (Learning algorithm)","D":"Thuật toán rõ ràng tường minh"},"answerDisplay":"C. learning algorithm","concept":"• Thuật toán học tập (Learning Algorithm) tự thử nghiệm, đánh giá hiệu năng và tự thích ứng cải thiện kết quả cho các dữ liệu tương lai.","whyCorrect":"• Khả năng tự thử nghiệm và chọn phương án tối ưu dựa trên dữ liệu quá khứ là đặc trưng của Learning Algorithm.","whyWrong":{"A":"• Thuật toán ngầm định không tự thích ứng.","B":"• Data algorithm không phải thuật ngữ phân loại ML.","D":"• Explicit algorithm tuân theo các quy tắc cố định được lập trình cứng."}}},{"id":31,"task":"su25_fe","taskLabel":"SU25 FE","num":31,"chooseType":"Choose 1 answer","question":"Are criminal justice risk assessments race-neutral?","options":{"A":"No, it is designed with intention to be unfair.","B":"Yes, technology in itself is not racist.","C":"No, the data is biased as it reflects historical bias.","D":"Yes, algorithms replace human judgement and they are unbiased"},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Các đánh giá rủi ro trong hệ thống tư pháp hình sự có trung lập về mặt chủng tộc hay không?","optionsVi":{"A":"Không, nó cố tình được thiết kế bất công","B":"Có, bản thân công nghệ không phân biệt chủng tộc","C":"Không, dữ liệu bị thiên vị vì nó phản ánh định kiến trong lịch sử (data is biased as it reflects historical bias)","D":"Có, thuật toán thay thế con người nên không thiên vị"},"answerDisplay":"C. No, the data is biased as it reflects historical bias.","concept":"• Thuật toán đánh giá rủi ro tư pháp học từ dữ liệu bắt giữ quá khứ chứa định kiến lịch sử, khiến kết quả dự đoán tái lập sự phân biệt chủng tộc.","whyCorrect":"• Dữ liệu huấn luyện lịch sử bị lệch phản ánh các định kiến xã hội quá khứ.","whyWrong":{"A":"• Không phải do cố tình thiết kế ác ý mà do dữ liệu đầu vào bị thiên vị.","B":"• Thuật toán không trung lập nếu dữ liệu huấn luyện bị lệch.","D":"• Thuật toán không tự động trung lập nếu không được kiểm soát thiên vị."}}},{"id":32,"task":"su25_fe","taskLabel":"SU25 FE","num":32,"chooseType":"Choose 2 answers","question":"Which of the following are key principles of privacy by design? (Select two.)","options":{"A":"Organizations must incorporate privacy protections throughout the project lifecycle.","B":"Organizations must be proactive in protecting against privacy risks, not reactive.","C":"Organizations must keep the focus of privacy protections on the business rather than the user.","D":"Organizations must not expose operational practices."},"answer":"A, B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Những nguyên tắc cốt lõi nào sau đây thuộc về Riêng tư theo thiết kế (Privacy by Design)? (Select two)","optionsVi":{"A":"Tổ chức phải tích hợp các biện pháp bảo vệ riêng tư trong suốt chu kỳ sống dự án (throughout the project lifecycle)","B":"Tổ chức phải chủ động phòng ngừa rủi ro riêng tư chứ không thụ động đối phó (Proactive not reactive)","C":"Tập trung bảo vệ kinh doanh thay vì người dùng","D":"Không công khai thực hành vận hành"},"answerDisplay":"A. Organizations must incorporate privacy protections throughout the project lifecycle. & B. Organizations must be proactive in protecting against privacy risks, not reactive.","concept":"• Privacy by Design quy định 7 nguyên tắc cốt lõi, nổi bật là Chủ động phòng ngừa (Proactive) và Bảo vệ xuyên suốt toàn bộ chu kỳ sống phần mềm.","whyCorrect":"• Chủ động phòng ngừa từ sớm và tích hợp xuyên suốt vòng đời phát triển là hai trụ cột chính của Privacy by Design.","whyWrong":{"C":"• Privacy by Design lấy người dùng làm trung tâm (User-centric).","D":"• Privacy by Design yêu cầu sự minh bạch mở (Visibility and Transparency)."}}},{"id":33,"task":"su25_fe","taskLabel":"SU25 FE","num":33,"chooseType":"Choose 2 answers","question":"Which of the following elements are important aspects of ethical integrity with regards to data? (Select two.)","options":{"A":"If the holders of data are trustworthy entities.","B":"Whether the data was gathered in an ethical manner.","C":"If the data is commercially viable or monetarily valuable.","D":"What type of data is being collected."},"answer":"A, B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Những khía cạnh nào sau đây là yếu tố quan trọng của sự liêm chính đạo đức đối với dữ liệu? (Select two)","optionsVi":{"A":"Bên nắm giữ dữ liệu có phải là thực thể đáng tin cậy hay không (trustworthy entities)","B":"Dữ liệu có được thu thập theo phương thức có đạo đức hay không (gathered in an ethical manner)","C":"Dữ liệu có giá trị thương mại hay không","D":"Loại dữ liệu được thu thập"},"answerDisplay":"A. If the holders of data are trustworthy entities. & B. Whether the data was gathered in an ethical manner.","concept":"• Đạo đức dữ liệu (Data Ethics) yêu cầu tính minh bạch trong phương thức thu thập (Consent) và độ tin cậy của đơn vị lưu trữ dữ liệu.","whyCorrect":"• Phương thức thu thập có đạo đức và tính đáng tin cậy của bên nắm giữ bảo đảm sự liêm chính cho toàn bộ vòng đời dữ liệu.","whyWrong":{"C":"• Giá trị thương mại là chỉ số kinh doanh.","D":"• Loại dữ liệu là định dạng kỹ thuật."}}},{"id":34,"task":"su25_fe","taskLabel":"SU25 FE","num":34,"chooseType":"Choose 1 answer","question":"When building a predictive model, what is the goal of the deployment phase?","options":{"A":"To plug in 40% of your dataset for accuracy testing","B":"To use the model in real-life predictions, monitoring the error rate and accuracy","C":"To train and repeat training until finding a better curve","D":"To specify the type of algorithm and clean the data"},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Khi xây dựng một mô hình dự đoán, mục tiêu của giai đoạn triển khai (Deployment phase) là gì?","optionsVi":{"A":"Nạp 40% dữ liệu để thử nghiệm độ chính xác","B":"Sử dụng mô hình trong các dự đoán thực tế đời sống, đồng thời theo dõi tỷ lệ lỗi và độ chính xác (use the model in real-life predictions, monitoring error rate)","C":"Huấn luyện liên tục cho đến khi tìm được đường cong tốt hơn","D":"Xác định loại thuật toán và làm sạch dữ liệu"},"answerDisplay":"B. To use the model in real-life predictions, monitoring the error rate and accuracy","concept":"• Giai đoạn Triển khai (Deployment) đưa mô hình vào môi trường sản xuất (Production) để phục vụ người dùng thực và liên tục giám sát hiệu năng.","whyCorrect":"• Đưa mô hình vào thực tế và giám sát sai số liên tục là mục đích chính của giai đoạn triển khai.","whyWrong":{"A":"• Nạp dữ liệu thử nghiệm thuộc về giai đoạn Validation/Testing.","C":"• Huấn luyện lại thuộc về giai đoạn Training.","D":"• Chọn thuật toán và làm sạch thuộc giai đoạn Data Preparation & Design."}}},{"id":35,"task":"su25_fe","taskLabel":"SU25 FE","num":35,"chooseType":"Choose 2 answers","question":"Which of the following are examples of how AI can limit human autonomy? (Select two.)","options":{"A":"Weapon systems can limit human autonomy as humans may not have decision-making capability or understand the decision making.","B":"AI systems might impact certain vulnerable groups such as the elderly and children differently than the rest of the population, which could limit those groups' autonomy.","C":"AI systems can assist individuals with automated, repetitive, or dangerous tasks.","D":"AI systems can perform tasks that humans cannot, such as processing millions of data records in a matter of seconds."},"answer":"A, B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Những ví dụ nào sau đây thể hiện cách AI có thể làm giới hạn quyền tự quyết (Autonomy) của con người? (Select two)","optionsVi":{"A":"Các hệ thống vũ khí tự động làm giảm quyền tự quyết vì con người có thể không có khả năng ra quyết định hoặc hiểu quyết định đó","B":"Các hệ thống AI có thể tác động đến các nhóm yếu thế như người già và trẻ em theo cách khác biệt, làm giới hạn quyền tự quyết của họ","C":"Hệ thống AI hỗ trợ cá nhân với các công việc tự động lặp đi lặp lại","D":"Hệ thống AI thực hiện các tác vụ vượt quá khả năng con người như xử lý hàng triệu bản ghi"},"answerDisplay":"A. Weapon systems can limit human autonomy... & B. AI systems might impact certain vulnerable groups...","concept":"• AI làm suy giảm Autonomy khi tước bỏ quyền kiểm soát quyết định của con người (trong vũ khí) hoặc thao túng các nhóm dễ bị tổn thương.","whyCorrect":"• Vũ khí tự động tước đi quyền ra quyết định sinh tử của con người và tác động lệch tới nhóm yếu thế làm thu hẹp quyền tự quyết xã hội.","whyWrong":{"C":"• Tự động hóa công việc lặp lại giúp tăng thời gian sáng tạo cho con người.","D":"• Xử lý dữ liệu quy mô lớn là năng lực hạ tầng tính toán."}}},{"id":36,"task":"su25_fe","taskLabel":"SU25 FE","num":36,"chooseType":"Choose 1 answer","question":"Which type of bias causes people to trust an automated decision-making system (ADS) over a human's decision?","options":{"A":"Implicit bias","B":"Automation bias","C":"Complacency bias","D":"Confirmation bias"},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Loại thiên vị nào khiến con người có xu hướng tin tưởng một hệ thống ra quyết định tự động (ADS) hơn quyết định của con người?","optionsVi":{"A":"Thiên vị ẩn (Implicit bias)","B":"Thiên vị tự động hóa (Automation bias)","C":"Thiên vị tự mãn (Complacency bias)","D":"Thiên vị xác nhận (Confirmation bias)"},"answerDisplay":"B. Automation bias","concept":"• Automation Bias là tâm lý ưu tiên và tin tưởng mù quáng vào kết quả của thuật toán tự động hơn đánh giá chuyên môn của con người.","whyCorrect":"• Sự tin tưởng sai lệch vào máy tính dẫn tới việc bỏ qua các lỗi sai rành rành của thuật toán.","whyWrong":{"A":"• Implicit bias là định kiến vô thức về con người/nhóm xã hội.","C":"• Complacency bias là sự chủ quan do hệ thống vận hành trơn tru lâu ngày.","D":"• Confirmation bias là thiên vị củng cố niềm tin cá nhân."}}},{"id":37,"task":"su25_fe","taskLabel":"SU25 FE","num":37,"chooseType":"Choose 1 answer","question":"An unintended negative outcome of programming a broad goal into general intelligence is known as:","options":{"A":"Perverse instantiation","B":"Enduring output","C":"Artificial sanctification","D":"An ethical dilemma"},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Một hệ quả tiêu cực không mong muốn của việc lập trình mục tiêu quá rộng cho AI tổng quát được gọi là gì?","optionsVi":{"A":"Sự hiện thực hóa lệch lạc (Perverse instantiation)","B":"Đầu ra bền vững","C":"Thánh hóa nhân tạo","D":"Tình huống tiến thoái lưỡng nan về đạo đức"},"answerDisplay":"A. Perverse instantiation","concept":"• Perverse Instantiation xảy ra khi AI thực hiện mục tiêu được giao theo cách quá triệt để hoặc sai lệch ý định ban đầu của con người (ví dụ: muốn xóa sổ bệnh tật thì AI diệt trừ con người).","whyCorrect":"• Khái niệm triết học AI chỉ việc AI hoàn thành mục tiêu bằng phương cách không mong muốn gây thảm họa.","whyWrong":{"B":"• Enduring output là thuộc tính đầu ra.","C":"• Artificial sanctification không phải thuật ngữ triết học AI.","D":"• Ethical dilemma là xung đột giá trị đạo đức."}}},{"id":38,"task":"su25_fe","taskLabel":"SU25 FE","num":38,"chooseType":"Choose 1 answer","question":"If you are doing an analysis of data to determine which of several small businesses you should purchase to gain the maximum benefit to your overall company finances, what type of analysis are you doing?","options":{"A":"Descriptive","B":"Prescriptive","C":"Predictive","D":"Cumulative"},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Nếu bạn phân tích dữ liệu để xác định doanh nghiệp nhỏ nào nên mua nhằm đạt lợi ích tối đa cho tài chính công ty, bạn đang làm loại phân tích nào?","optionsVi":{"A":"Phân tích mô tả (Descriptive)","B":"Phân tích kê đơn / đề xuất (Prescriptive analysis)","C":"Phân tích dự đoán (Predictive)","D":"Phân tích tích lũy"},"answerDisplay":"B. Prescriptive","concept":"• Phân tích kê đơn (Prescriptive Analytics) không chỉ dự báo tương lai mà đưa ra khuyến nghị hành động tối ưu nhất (hành động nên thực hiện).","whyCorrect":"• Đưa ra quyết định kinh doanh cụ thể để đạt lợi ích tối đa chính là mục tiêu của Prescriptive Analytics.","whyWrong":{"A":"• Descriptive chỉ tóm tắt chuyện gì đã xảy ra trong quá khứ.","C":"• Predictive dự báo điều gì có thể xảy ra trong tương lai.","D":"• Cumulative không phải loại hình phân tích dữ liệu tiêu chuẩn."}}},{"id":39,"task":"su25_fe","taskLabel":"SU25 FE","num":39,"chooseType":"Choose 1 answer","question":"How does increasing AI performance often conflict with the desire for explainability?","options":{"A":"Increasing AI performance sometimes reduces the transparency of input data.","B":"Increasing AI performance sometimes leads to greater model complexity, making it more difficult to explain decision-making processes.","C":"Increasing AI performance leads to evaluation metrics no longer being useful.","D":"Increasing AI performance removes human-in-the-loop methods."},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Việc tăng hiệu suất AI thường xung đột với mong muốn giải thích được (Explainability) như thế nào?","optionsVi":{"A":"Tăng hiệu suất AI làm giảm tính minh bạch dữ liệu đầu vào","B":"Tăng hiệu suất AI thường dẫn tới độ phức tạp mô hình cao hơn, làm cho quy trình ra quyết định khó giải thích hơn (leads to greater model complexity)","C":"Tăng hiệu suất làm các chỉ số đánh giá mất tác dụng","D":"Tăng hiệu suất loại bỏ con người khỏi quy trình"},"answerDisplay":"B. Increasing AI performance sometimes leads to greater model complexity, making it more difficult to explain decision-making processes.","concept":"• Mâu thuẫn cốt lõi (Trade-off): Các mô hình có hiệu suất cao nhất (như Deep Neural Networks) cực kỳ phức tạp về mặt toán học, dẫn tới mất tính giải thích.","whyCorrect":"• Độ phức tạp kiến trúc làm tăng hiệu suất dự đoán nhưng tạo ra bài toán hộp đen khó giải thích.","whyWrong":{"A":"• Minh bạch dữ liệu đầu vào phụ thuộc quy trình thu thập.","C":"• Chỉ số đánh giá vẫn cực kỳ hữu ích.","D":"• HITL là quy trình vận hành giám sát độc lập."}}},{"id":40,"task":"su25_fe","taskLabel":"SU25 FE","num":40,"chooseType":"Choose 1 answer","question":"A model that makes more mistakes by moving its decision threshold down 40% of its worthiness metric will be potentially:","options":{"A":"More accurate and fairer","B":"Less accurate and less fair","C":"Fairer but less accurate","D":"Less fair but more accurate"},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Một mô hình mắc nhiều lỗi hơn bằng cách hạ ngưỡng quyết định (decision threshold) xuống 40% chỉ số giá trị sẽ có khả năng trở thành:","optionsVi":{"A":"Chính xác hơn và công bằng hơn","B":"Kém chính xác hơn và kém công bằng hơn","C":"Công bằng hơn nhưng kém chính xác hơn (Fairer but less accurate)","D":"Kém công bằng hơn nhưng chính xác hơn"},"answerDisplay":"C. Fairer but less accurate","concept":"• Sự đánh đổi trong ML (Trade-off between Accuracy and Fairness): Hạ ngưỡng quyết định có thể làm giảm sai lệch bất công giữa các nhóm (tăng Fairness) nhưng làm tăng tỷ lệ báo động giả (giảm Accuracy).","whyCorrect":"• Hạ ngưỡng mở rộng cơ hội cho nhóm bị phân biệt đối xử (tăng tính công bằng) nhưng chấp nhận nhiều sai sót dự đoán hơn (giảm độ chính xác).","whyWrong":{"A":"• Hạ ngưỡng làm tăng lỗi nên không thể vừa tăng chính xác vừa tăng công bằng.","B":"• Hạ ngưỡng mở rộng cơ hội tiếp cận cho nhóm yếu thế nên giúp tăng Fairness.","D":"• Ngược lại với bản chất của trade-off hạ ngưỡng."}}},{"id":41,"task":"su25_fe","taskLabel":"SU25 FE","num":41,"chooseType":"Choose 1 answer","question":"Which subset of transparency involves describing the system to a non-expert?","options":{"A":"Explainability","B":"Interpretability","C":"Auditability","D":"Useability"},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Khía cạnh nào của tính minh bạch liên quan đến việc mô tả hệ thống cho một người không phải là chuyên gia hiểu được?","optionsVi":{"A":"Tính giải thích được (Explainability)","B":"Tính diễn giải được (Interpretability)","C":"Tính kiểm toán được (Auditability)","D":"Tính khả dụng (Useability)"},"answerDisplay":"A. Explainability","concept":"• Explainability (Tính giải thích được) là việc chuyển đổi các logic toán học phức tạp thành thuật ngữ phổ thông cho người dùng đại chúng (non-experts) hiểu.","whyCorrect":"• Mô tả mô hình AI cho người không có chuyên môn kỹ thuật chính là mục tiêu cốt lõi của Explainability.","whyWrong":{"B":"• Interpretability là khả năng chuyên gia tự diễn giải cơ chế bên trong của mô hình.","C":"• Auditability là khả năng lưu log phục vụ kiểm toán độc lập.","D":"• Useability là tính dễ sử dụng của giao diện người dùng."}}},{"id":42,"task":"su25_fe","taskLabel":"SU25 FE","num":42,"chooseType":"Choose 2 answers","question":"Which of the following ethical considerations should have priority in an emergency situation like the use of contact-tracing solutions during a pandemic?","options":{"A":"Privacy","B":"Accountability","C":"Explainability","D":"Bias"},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Mối quan tâm đạo đức nào sau đây cần được ưu tiên kiểm soát trong tình huống khẩn cấp như sử dụng ứng dụng truy vết tiếp xúc dịch bệnh?","optionsVi":{"A":"Quyền riêng tư dữ liệu (Privacy)","B":"Trách nhiệm giải trình (Accountability)","C":"Tính giải thích (Explainability)","D":"Thiên vị (Bias)"},"answerDisplay":"A. Privacy","concept":"• Ứng dụng truy vết tiếp xúc (Contact Tracing) thu thập dữ liệu vị trí và sức khỏe liên tục, do đó rủi ro xâm phạm Quyền riêng tư (Privacy) là yếu tố nhạy cảm nhất cần bảo vệ.","whyCorrect":"• Bảo vệ dữ liệu định vị cá nhân khỏi lạm dụng giám sát trong đại dịch là ưu tiên đạo đức hàng đầu.","whyWrong":{"B":"• Trách nhiệm giải trình là điều kiện khung quản trị.","C":"• Tính giải thích là thuộc tính thuật toán.","D":"• Thiên vị là rủi ro dữ liệu mẫu."}}},{"id":43,"task":"su25_fe","taskLabel":"SU25 FE","num":43,"chooseType":"Choose 1 answer","question":"A model can still be unfair even though it won't explicitly know which groups are being inputted into the system due to:","options":{"A":"Biased training datasets","B":"Blind attributes","C":"Proxy attributes (Biased features correlated with protected groups)","D":"Optimized parameters"},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Một mô hình vẫn có thể bất công ngay cả khi nó không biết rõ nhóm đối tượng nào đang được nạp vào hệ thống là do yếu tố nào?","optionsVi":{"A":"Tập dữ liệu huấn luyện bị thiên vị","B":"Thuộc tính ẩn mù","C":"Các thuộc tính thay thế / tương quan (Proxy attributes)","D":"Các tham số được tối ưu hóa"},"answerDisplay":"C. Proxy attributes (Biased features correlated with protected groups)","concept":"• Proxy Attributes (Thuộc tính thay thế) như mã bưu chính, trường đại học hay thu nhập có tương quan mạnh với chủng tộc/giới tính, khiến mô hình thiên vị dù đã ẩn thuộc tính nhạy cảm.","whyCorrect":"• Việc ẩn thuộc tính nhạy cảm không thể ngăn mô hình học thiên vị gián tiếp qua các thuộc tính proxy.","whyWrong":{"A":"• Dữ liệu thiên vị là nguyên nhân gốc nhưng cơ chế gây ra thiên vị ẩn là qua Proxy Attributes.","B":"• Thuộc tính ẩn mù (Fairness through unawareness) bị vô hiệu hóa bởi proxy attributes.","D":"• Tối ưu tham số là thuật toán huấn luyện."}}},{"id":44,"task":"su25_fe","taskLabel":"SU25 FE","num":44,"chooseType":"Choose 1 answer","question":"Fairness in machine learning can protect groups from bias, but can still harm:","options":{"A":"Training datasets","B":"Researchers","C":"Future models","D":"Individuals within those groups"},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Tính công bằng trong học máy có thể bảo vệ các nhóm khỏi thiên vị, nhưng vẫn có thể gây hại cho đối tượng nào?","optionsVi":{"A":"Các tập dữ liệu huấn luyện","B":"Các nhà nghiên cứu","C":"Các mô hình tương lai","D":"Các cá nhân trong chính những nhóm đó (Individuals within those groups)"},"answerDisplay":"D. Individuals within those groups","concept":"• Group Fairness (Công bằng nhóm) đảm bảo tỷ lệ duyệt ngang nhau giữa các nhóm nhưng có thể bỏ qua yếu tố cá thể, gây bất công cho cá nhân cụ thể (Individual Fairness).","whyCorrect":"• Ép buộc chỉ số bình đẳng nhóm có thể làm từ chối một cá nhân xuất sắc cụ thể trong nhóm đó.","whyWrong":{"A":"• Tập dữ liệu là dữ liệu thô.","B":"• Nhà nghiên cứu là người thiết kế.","C":"• Mô hình tương lai là phiên bản phần mềm."}}},{"id":45,"task":"su25_fe","taskLabel":"SU25 FE","num":45,"chooseType":"Choose 1 answer","question":"Why do smart toys raise additional ethical concerns over those that are raised in the course of other products and services that use AI?","options":{"A":"They are used in the privacy of homes rather than in public settings, like other products or services.","B":"The smart toys store personal data on the device, which can be stolen.","C":"It is difficult to obtain informed consent for the use of the smart toy.","D":"Children are more susceptible to manipulation and therefore need extra protective measures."},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Tại sao đồ chơi thông minh (Smart Toys) lại gây ra các lo ngại về đạo đức bổ sung so với các sản phẩm/dịch vụ AI khác?","optionsVi":{"A":"Chúng được sử dụng trong sự riêng tư tại nhà","B":"Đồ chơi lưu dữ liệu cá nhân trên thiết bị","C":"Khó thu thập sự chấp thuận từ phụ huynh","D":"Trẻ em dễ bị thao túng hơn và do đó cần các biện pháp bảo vệ đặc biệt (Children are more susceptible to manipulation)"},"answerDisplay":"D. Children are more susceptible to manipulation and therefore need extra protective measures.","concept":"• Trẻ em là nhóm đối tượng yếu thế (Vulnerable Population) chưa phát triển đầy đủ nhận thức, dễ bị thao túng tâm lý và thu thập dữ liệu trái phép bởi Smart Toys.","whyCorrect":"• Trẻ em dễ bị ảnh hưởng bởi AI tương tác nên đòi hỏi tiêu chuẩn bảo vệ đạo đức nghiêm ngặt hơn sản phẩm người lớn.","whyWrong":{"A":"• Sử dụng tại nhà không phải lý do duy nhất tạo rủi ro đặc thù đồ chơi.","B":"• Lưu dữ liệu thiết bị là rủi ro IoT chung.","C":"• Sự chấp thuận phụ huynh là quy trình pháp lý COPPA."}}},{"id":46,"task":"su25_fe","taskLabel":"SU25 FE","num":46,"chooseType":"Choose 2 answers","question":"Which of the following are important elements of the data minimization principle? (Select two.)","options":{"A":"Only collect data that is strictly necessary","B":"Only keep data for as long as it is needed","C":"Only delete data that can be easily replaced","D":"Only compress data that needs to be kept as small as possible"},"answer":"A, B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Những yếu tố nào sau đây là thành phần quan trọng của nguyên tắc giảm thiểu dữ liệu (Data Minimization)? (Select two)","optionsVi":{"A":"Chỉ thu thập dữ liệu thực sự cần thiết (Only collect data that is strictly necessary)","B":"Chỉ giữ dữ liệu trong khoảng thời gian còn cần đến (Only keep data for as long as it is needed)","C":"Chỉ xóa dữ liệu có thể thay thế","D":"Chỉ nén dữ liệu cần lưu trữ nhỏ"},"answerDisplay":"A. Only collect data that is strictly necessary & B. Only keep data for as long as it is needed","concept":"• Data Minimization bao gồm hai khía cạnh: Giới hạn phạm vi thu thập (Need-to-know) và Giới hạn thời gian lưu trữ (Data Retention).","whyCorrect":"• Chỉ thu thập dữ liệu thiết yếu và xóa dữ liệu khi hết thời hạn sử dụng giúp phòng ngừa tối đa rủi ro lộ rò.","whyWrong":{"C":"• Xóa dữ liệu phụ thuộc vào quy định lưu trữ chứ không phải tính dễ thay thế.","D":"• Nén dữ liệu là giải pháp tối ưu lưu trữ phần mềm."}}},{"id":47,"task":"su25_fe","taskLabel":"SU25 FE","num":47,"chooseType":"Choose 1 answer","question":"Which type of entity are the OECD Principles on Artificial Intelligence mostly geared towards?","options":{"A":"Individuals","B":"Municipal governments","C":"National governments","D":"Private corporations"},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Các nguyên tắc AI của OECD chủ yếu hướng tới đối tượng nào?","optionsVi":{"A":"Cá nhân người dùng","B":"Chính quyền thành phố / địa phương","C":"Chính phủ các quốc gia (National governments)","D":"Các tập đoàn tư nhân"},"answerDisplay":"C. National governments","concept":"• Khung khuyến nghị OECD AI Principles được thiết kế chủ yếu làm kim chỉ nam chính sách cho Chính phủ các nước thành viên xây dựng luật pháp.","whyCorrect":"• OECD là tổ chức hợp tác kinh tế liên chính phủ, các khuyến nghị hướng tới cấp độ hoạch định chính sách quốc gia.","whyWrong":{"A":"• Cá nhân là đối tượng được bảo vệ.","B":"• Chính quyền địa phương thực thi chính sách từ quốc gia.","D":"• Các tập đoàn áp dụng tuân thủ luật do chính phủ ban hành."}}},{"id":48,"task":"su25_fe","taskLabel":"SU25 FE","num":48,"chooseType":"Choose 1 answer","question":"Which of the following describes an ethical framework?","options":{"A":"Ethical frameworks raise timeless ethical questions that are not easily put into action.","B":"Ethical frameworks apply meta-ethical theories to everyday business operations.","C":"Ethical frameworks consolidate regulatory requirements for an industry.","D":"Ethical frameworks seek to mitigate ethical concerns by creating actionable steps."},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng về một Khung làm việc đạo đức (Ethical Framework)?","optionsVi":{"A":"Khung đạo đức đưa ra các câu hỏi vượt thời gian nhưng khó thực thi","B":"Khung đạo đức áp dụng lý thuyết siêu đạo đức vào kinh doanh","C":"Khung đạo đức hợp nhất các quy định pháp luật","D":"Khung đạo đức tìm cách giảm thiểu các mối quan tâm đạo đức bằng cách tạo ra các bước hành động cụ thể (creating actionable steps)"},"answerDisplay":"D. Ethical frameworks seek to mitigate ethical concerns by creating actionable steps.","concept":"• Ethical Framework cung cấp quy trình và các bước hành động cụ thể (Actionable Steps) để tổ chức áp dụng giảm thiểu rủi ro đạo đức.","whyCorrect":"• Tính ứng dụng cao và đưa ra hướng dẫn hành động thực tế là đặc trưng phân biệt của khung làm việc đạo đức.","whyWrong":{"A":"• Khung đạo đức hướng tới hành động thực tế chứ không chỉ lý thuyết suông.","B":"• Khung đạo đức tập trung vào đạo đức ứng dụng (Applied Ethics).","C":"• Pháp lý là Legal Framework, không phải Ethical Framework."}}},{"id":49,"task":"su25_fe","taskLabel":"SU25 FE","num":49,"chooseType":"Choose 1 answer","question":"Which organizational resource is most commonly used in terms of fostering an ethical organizational culture?","options":{"A":"Human resources","B":"Informational resources","C":"Financial resources","D":"Physical resources"},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Nguồn lực tổ chức nào được sử dụng phổ biến nhất để thúc đẩy văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Nguồn nhân lực (Human resources)","B":"Nguồn lực thông tin","C":"Nguồn lực tài chính","D":"Nguồn lực cơ sở vật chất"},"answerDisplay":"A. Human resources","concept":"• Văn hóa đạo đức được xây dựng bởi con người qua đào tạo, nêu gương lãnh đạo và tuyển dụng (Human Resources).","whyCorrect":"• Nguồn nhân lực là yếu tố cốt lõi trực tiếp thực hành và lan tỏa các giá trị đạo đức trong công ty.","whyWrong":{"B":"• Thông tin là công cụ hỗ trợ.","C":"• Tài chính tài trợ các chương trình nhưng con người mới là đối tượng thực thi.","D":"• Cơ sở vật chất là hạ tầng làm việc."}}},{"id":50,"task":"su25_fe","taskLabel":"SU25 FE","num":50,"chooseType":"Choose 1 answer","question":"Which of the following would be the most beneficial stage to hold ethical risk reviews for a new project that your team is undertaking?","options":{"A":"Development","B":"Deployment","C":"Design","D":"Conception"},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Giai đoạn nào là có lợi nhất để tổ chức đánh giá rủi ro đạo đức cho một dự án mới mà đội ngũ của bạn đang thực hiện?","optionsVi":{"A":"Giai đoạn Phát triển (Development)","B":"Giai đoạn Triển khai (Deployment)","C":"Giai đoạn Thiết kế (Design)","D":"Giai đoạn Hình thành ý tưởng / Khởi tạo (Conception)"},"answerDisplay":"D. Conception","concept":"• Đánh giá rủi ro sớm từ giai đoạn Khởi tạo (Conception) giúp phát hiện rủi ro từ gốc, tránh lãng phí chi phí sửa chữa ở các giai đoạn sau.","whyCorrect":"• Đánh giá ngay từ ý tưởng ban đầu giúp định hình kiến trúc có đạo đức trước khi bắt đầu viết code.","whyWrong":{"A":"• Đợi đến Phát triển thì kiến trúc đã định hình, khó sửa đổi.","B":"• Đợi đến Triển khai là quá muộn, gây rủi ro thảm họa phát hành.","C":"• Thiết kế sau giai đoạn khởi tạo ý tưởng."}}},{"id":51,"task":"su25_fe","taskLabel":"SU25 FE","num":51,"chooseType":"Choose 1 answer","question":"How can the human resources department help build an ethical organizational culture?","options":{"A":"Hiring candidates based on their technical skills","B":"Hiring candidates based on their culture fit and ethical values","C":"Hiring candidates based on their leadership skills","D":"Hiring candidates based solely on soft skills"},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Bộ phận nhân sự (HR) có thể giúp xây dựng văn hóa tổ chức có đạo đức như thế nào?","optionsVi":{"A":"Tuyển dụng ứng viên thuần túy dựa trên kỹ năng kỹ thuật","B":"Tuyển dụng ứng viên dựa trên sự phù hợp văn hóa và giá trị đạo đức (culture fit and ethical values)","C":"Tuyển dụng dựa trên kỹ năng lãnh đạo","D":"Tuyển dụng thuần túy dựa trên kỹ năng mềm"},"answerDisplay":"B. Hiring candidates based on their culture fit and ethical values","concept":"• HR đóng vai trò gác cổng văn hóa bằng cách tuyển dụng những ứng viên chia sẻ cùng giá trị đạo đức cốt lõi với tổ chức.","whyCorrect":"• Tuyển dụng người có cùng chuẩn mực đạo đức giúp củng cố văn hóa công ty một cách tự nhiên và bền vững.","whyWrong":{"A":"• Chỉ chú trọng kỹ thuật bỏ qua thái độ đạo đức tạo ra rủi ro vi phạm cao.","C":"• Kỹ năng lãnh đạo chưa đủ đảm bảo phẩm chất đạo đức.","D":"• Kỹ năng mềm không thay thế cho la bàn đạo đức cá nhân."}}},{"id":52,"task":"su25_fe","taskLabel":"SU25 FE","num":52,"chooseType":"Choose 1 answer","question":"Is an open door policy equivalent to ensuring employee voice?","options":{"A":"No, because an open door policy is the opposite of employee voice.","B":"Yes, because both allow employees to speak up.","C":"Yes, because an open door policy is essential for employee voice.","D":"No, because an open door policy does not ensure employees feel heard."},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Chính sách mở cửa (Open door policy) có tương đương với việc đảm bảo tiếng nói của nhân viên (Employee voice) hay không?","optionsVi":{"A":"Không, vì chính sách mở cửa trái ngược với tiếng nói nhân viên","B":"Có, vì cả hai đều cho phép nhân viên phát biểu","C":"Có, vì chính sách mở cửa là thiết yếu","D":"Không, vì chính sách mở cửa không đảm bảo nhân viên thực sự cảm thấy mình được lắng nghe (does not ensure employees feel heard)"},"answerDisplay":"D. No, because an open door policy does not ensure employees feel heard.","concept":"• Chính sách mở cửa hình thức không tự động tạo ra sự an toàn tâm lý (Psychological Safety) để nhân viên tin rằng ý kiến đóng góp của họ thực sự được lắng nghe và phản hồi.","whyCorrect":"• Mở cửa phòng quản lý không có nghĩa là nhân viên cảm thấy an toàn và được lắng nghe thực sự.","whyWrong":{"A":"• Chính sách mở cửa không trái ngược mà là một công cụ hỗ trợ hình thức.","B":"• Cho phép nói không đồng nghĩa với lắng nghe và hành động.","C":"• Mở cửa không đủ để tạo nên Employee Voice toàn diện."}}},{"id":53,"task":"su25_fe","taskLabel":"SU25 FE","num":53,"chooseType":"Choose 1 answer","question":"Which of the following presents the most important argument for why we need to consider the impact of AI on labor in the design, development, and deployment of data-driven technology?","options":{"A":"There might be potential labor rights and human rights violations.","B":"The organization would like to avoid having to deal with union concerns.","C":"There may be an impact on worker productivity if they are not included in all phases.","D":"There is still a need for human workers in human-in-the-loop mechanisms."},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Nội dung nào sau đây đưa ra lập luận quan trọng nhất giải thích tại sao cần xem xét tác động của AI đối với lao động trong quá trình thiết kế, phát triển và triển khai công nghệ?","optionsVi":{"A":"Có thể có các vi phạm tiềm ẩn về quyền lao động và quyền con người (potential labor rights and human rights violations)","B":"Tổ chức muốn né tránh việc xử lý các quan ngại của công đoàn","C":"Có thể ảnh hưởng đến năng suất của công nhân","D":"Vẫn cần công nhân cho cơ chế Human-in-the-loop"},"answerDisplay":"A. There might be potential labor rights and human rights violations.","concept":"• Tự động hóa AI có rủi ro xâm phạm quyền lao động (sa thải vô căn cứ, giảm chất lượng công việc) và quyền con người.","whyCorrect":"• Ngăn ngừa vi phạm quyền lao động và quyền con người là luận điểm đạo đức tối thượng vượt trên năng suất hay né tránh công đoàn.","whyWrong":{"B":"• Né tránh công đoàn là mục tiêu quản lý nội bộ, không phải luận điểm đạo đức tối thượng.","C":"• Năng suất là yếu tố kinh tế.","D":"• Cơ chế HITL là phương pháp vận hành kỹ thuật."}}},{"id":54,"task":"su25_fe","taskLabel":"SU25 FE","num":54,"chooseType":"Choose 1 answer","question":"Why is fair competition an important ethical consideration for data-driven technology businesses?","options":{"A":"Fair competition prevents predatory pricing.","B":"Fair competition builds user trust in technology as a whole.","C":"Fair competition provides products choice to users.","D":"Fair competition provides service choice to users."},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Tại sao cạnh tranh công bằng lại là một xem xét đạo đức quan trọng đối với các doanh nghiệp công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Cạnh tranh công bằng ngăn chặn việc định giá độc quyền","B":"Cạnh tranh công bằng xây dựng niềm tin của người dùng vào toàn bộ hệ sinh thái công nghệ (builds user trust in technology as a whole)","C":"Cạnh tranh công bằng cung cấp sự lựa chọn sản phẩm cho người dùng","D":"Cạnh tranh công bằng cung cấp sự lựa chọn dịch vụ cho người dùng"},"answerDisplay":"B. Fair competition builds user trust in technology as a whole.","concept":"• Cạnh tranh công bằng ngăn chặn sự độc quyền dữ liệu (Data Monopoly), bảo vệ lòng tin tổng thể của xã hội vào hạ tầng số.","whyCorrect":"• Xây dựng niềm tin công chúng vào công nghệ là giá trị đạo đức cao nhất của môi trường cạnh tranh lành mạnh.","whyWrong":{"A":"• Định giá chỉ là khía cạnh tài chính thương mại.","C":"• Lựa chọn sản phẩm là lợi ích tiêu dùng thương mại.","D":"• Lựa chọn dịch vụ thuộc về thị trường."}}},{"id":55,"task":"su25_fe","taskLabel":"SU25 FE","num":55,"chooseType":"Choose 1 answer","question":"Which of the following is a potential benefit of having an ethical organizational culture?","options":{"A":"More employees are likely to switch careers.","B":"Employees will feel a sense of responsibility and loyalty.","C":"Employees are more likely to listen to their superiors.","D":"The company will get an increase in stock value."},"answer":"B","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Lợi ích tiềm năng nào của việc sở hữu một văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Nhiều nhân viên có khả năng chuyển nghề hơn","B":"Nhân viên sẽ cảm nhận được tinh thần trách nhiệm và lòng trung thành (responsibility and loyalty)","C":"Nhân viên dễ nghe lời cấp trên hơn","D":"Công ty chắc chắn tăng giá trị cổ phiếu"},"answerDisplay":"B. Employees will feel a sense of responsibility and loyalty.","concept":"• Văn hóa đạo đức nuôi dưỡng tinh thần tự giác, tinh thần trách nhiệm và cam kết gắn bó dài lâu của nhân viên.","whyCorrect":"• Nhận thức rõ giá trị đạo đức của công ty tạo động lực thúc đẩy tinh thần trách nhiệm và sự trung thành.","whyWrong":{"A":"• Văn hóa tốt làm giảm tỷ lệ nhảy việc.","C":"• Nghe lời mù quáng không phải là mục tiêu đạo đức.","D":"• Cổ phiếu phụ thuộc nhiều biến số thị trường tài chính."}}},{"id":56,"task":"su25_fe","taskLabel":"SU25 FE","num":56,"chooseType":"Choose 1 answer","question":"To which of the following groups would a code of ethics not be applicable?","options":{"A":"Developers of the data-driven technology system","B":"Designers of the data-driven technology system","C":"Business managers of the data-driven technology system","D":"Data subjects of the data-driven technology system"},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Nhóm đối tượng nào sau đây không phải là đối tượng áp dụng của bộ quy tắc đạo đức nội bộ công ty?","optionsVi":{"A":"Các nhà phát triển hệ thống công nghệ","B":"Các nhà thiết kế hệ thống công nghệ","C":"Các nhà quản lý kinh doanh của hệ thống","D":"Chủ thể dữ liệu / người dùng bị thu thập dữ liệu (Data subjects)"},"answerDisplay":"D. Data subjects of the data-driven technology system","concept":"• Bộ quy tắc đạo đức tổ chức (Code of Ethics) quy định tiêu chuẩn hành vi cho nhân viên trong công ty, không ràng buộc vai trò của chủ thể dữ liệu (Data Subjects).","whyCorrect":"• Data subjects là đối tượng được bảo vệ bởi bộ quy tắc chứ không phải nhân sự chịu sự điều chỉnh hành vi của bộ quy tắc nội bộ.","whyWrong":{"A":"• Lập trình viên bắt buộc tuân thủ code of ethics.","B":"• Nhà thiết kế bắt buộc tuân thủ code of ethics.","C":"• Quản lý kinh doanh bắt buộc tuân thủ code of ethics."}}},{"id":57,"task":"su25_fe","taskLabel":"SU25 FE","num":57,"chooseType":"Choose 1 answer","question":"Which of the following is a misuse of intellectual property (IP) when it comes to ethical accountability for an organization?","options":{"A":"Collecting returns on investments made in research and development","B":"Filing a patent for the IP that makes non-obvious information known to the public.","C":"Enhancing the security posture of a product or service.","D":"Using IP as a defensive mechanism to eschew transparency requirements."},"answer":"D","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Hành vi nào sau đây là sự lạm dụng sở hữu trí tuệ (IP) liên quan đến trách nhiệm giải trình đạo đức của tổ chức?","optionsVi":{"A":"Thu lợi nhuận từ các khoản đầu tư R&D","B":"Nộp bằng sáng chế cho IP công khai thông tin","C":"Nâng cao tư thế bảo mật cho sản phẩm","D":"Sử dụng sở hữu trí tuệ như cơ chế phòng thủ để trốn tránh các yêu cầu minh bạch (Using IP to eschew transparency requirements)"},"answerDisplay":"D. using IP as a defensive mechanism to eschew transparency requirements.","concept":"• Lạm dụng lấy lý do bảo vệ sở hữu trí tuệ (IP protection) để từ chối giải thích hay kiểm toán thuật toán là hành vi trốn tránh trách nhiệm minh bạch.","whyCorrect":"• Viện cớ bảo mật IP để che đậy thuật toán hộp đen thiên vị vi phạm nghiêm trọng nguyên tắc minh bạch đạo đức.","whyWrong":{"A":"• Thu hồi vốn R&D là hoạt động thương mại hợp pháp.","B":"• Đăng ký bằng sáng chế công khai là thủ tục IP chuẩn.","C":"• Tăng cường bảo mật là thực hành an toàn thông tin tốt."}}},{"id":58,"task":"su25_fe","taskLabel":"SU25 FE","num":58,"chooseType":"Choose 1 answer","question":"Which of the following is a notable aspect of the Personal Information Protection and Electronic Documents Act (PIPEDA) when compared to similar laws and regulations?","options":{"A":"Its exclusive focus on a single domain rather than a breadth of domains","B":"The early date of its inauguration","C":"Its nationwide scope and specific national focus","D":"A stipulation to continue providing service even if data usage is denied"},"answer":"C","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Đặc điểm nổi bật của Đạo luật PIPEDA (Canada) khi so sánh với các luật tương tự là gì?","optionsVi":{"A":"Chỉ tập trung vào một lĩnh vực duy nhất","B":"Thời điểm ban hành rất sớm","C":"Phạm vi toàn quốc và tập trung vào mục tiêu quốc gia cụ thể (Canada)","D":"Quy định tiếp tục cung cấp dịch vụ ngay cả khi từ chối dữ liệu"},"answerDisplay":"C. Its nationwide scope and specific national focus","concept":"• PIPEDA là đạo luật bảo vệ quyền riêng tư thương mại áp dụng thống nhất trên toàn bộ lãnh thổ Canada.","whyCorrect":"• Phạm vi áp dụng toàn quốc Canada cho khu vực tư nhân là đặc trưng phân biệt chính của PIPEDA.","whyWrong":{"A":"• PIPEDA áp dụng rộng rãi đa ngành.","B":"• Thời điểm năm 2000 không phải điểm khác biệt duy nhất.","D":"• Doanh nghiệp được quyền từ chối dịch vụ nếu dữ liệu là thiết yếu."}}},{"id":59,"task":"su25_fe","taskLabel":"SU25 FE","num":59,"chooseType":"Choose 1 answer","question":"Why is the question of robot rights and emancipation one that isn't as important as addressing issues of bias, privacy, transparency, and other principles discussed in the various ethical frameworks?","options":{"A":"These rights necessitate that robots become sentient entities, which is currently not feasible.","B":"Humans are anthropocentric and don't want to extend rights to other sentient entities.","C":"There is no legal precedent for granting rights to entities that are not humans.","D":"Robots are mechanical instruments and therefore don't deserve to have rights."},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Tại sao câu hỏi về quyền và sự giải phóng của robot lại không quan trọng bằng việc giải quyết các vấn đề về thiên vị, quyền riêng tư, tính minh bạch trong các khung đạo đức AI hiện nay?","optionsVi":{"A":"Các quyền này đòi hỏi robot phải trở thành các thực thể có tri giác, điều mà hiện tại hoàn toàn không khả thi","B":"Con người coi mình là trung tâm và không muốn trao quyền","C":"Không có tiền lệ pháp lý","D":"Robot là công cụ cơ khí nên không xứng đáng có quyền"},"answerDisplay":"A. These rights necessitate that robots become sentient entities, which is currently not feasible.","concept":"• Quyền của Robot đòi hỏi trí tuệ nhân tạo phải đạt mức Tri giác (Sentience) và Ý thức, trong khi công nghệ AI hiện tại chỉ là các thuật toán xử lý dữ liệu toán học.","whyCorrect":"• Tính không khả thi về mặt kỹ thuật khiến việc bàn luận quyền cho robot trở nên viển vông so với các rủi ro thiên vị/riêng tư thực tế đang hiện hữu.","whyWrong":{"B":"• Quan điểm vị nhân sinh không phải lý do kỹ thuật cốt lõi.","C":"• Tiền lệ pháp lý có thể tạo mới nếu công nghệ thực sự đạt tri giác.","D":"• Định kiến vật lý không phản ánh lý do công nghệ."}}},{"id":60,"task":"su25_fe","taskLabel":"SU25 FE","num":60,"chooseType":"Choose 1 answer","question":"What is the function of a red team in a penetration testing exercise?","options":{"A":"To conduct the simulated attacks","B":"To defend against the simulated attacks","C":"To officiate the simulated attacks","D":"To disable the attacks"},"answer":"A","source":"ITE302c_SU25_FE","explanation":{"questionVi":"Chức năng của Đội Đỏ (Red Team) trong bài kiểm thử xâm nhập (Penetration testing) là gì?","optionsVi":{"A":"Thực hiện các cuộc tấn công giả lập (To conduct the simulated attacks)","B":"Phòng thủ trước các cuộc tấn công giả lập (Blue Team)","C":"Điều hành và giám sát bài kiểm thử (Purple Team)","D":"Vô hiệu hóa các cuộc tấn công"},"answerDisplay":"A. To conduct the simulated attacks","concept":"• Trong diễn tập an ninh mạng: Red Team đóng vai kẻ tấn công giả lập, Blue Team đóng vai bên phòng thủ, Purple Team điều phối.","whyCorrect":"• Vai trò cốt lõi của Red Team là đóng vai đối thủ tấn công để tìm ra các lỗ hổng của hệ thống.","whyWrong":{"B":"• Phòng thủ là vai trò của Đội Xanh (Blue Team).","C":"• Điều hành là vai trò của Đội Tím (Purple Team / White Team).","D":"• Vô hiệu hóa là mục tiêu của hệ thống phòng thủ."}}},{"id":1,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":1,"chooseType":"Choose 1 answer","question":"What is the primary advantage of radioactive data tracing over past techniques used to trace data in machine learning models?","options":{"A":"Radioactive data tracing can be used to modify the label","B":"Radioactive data tracing doesn't impact a model's overall performance","C":"Radioactive data tracing targets language-based input","D":"Radioactive data tracing makes modification perceptible to humans"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Ưu điểm chính của kỹ thuật truy vết dữ liệu phóng xạ (Radioactive data tracing) so với các kỹ thuật truy vết trước đây trong mô hình học máy là gì?","optionsVi":{"A":"Truy vết dữ liệu phóng xạ có thể sửa đổi nhãn","B":"Truy vết dữ liệu phóng xạ không làm ảnh hưởng hay suy giảm hiệu suất tổng thể của mô hình (doesn't impact model's performance)","C":"Truy vết dữ liệu phóng xạ nhắm vào đầu vào ngôn ngữ","D":"Truy vết dữ liệu phóng xạ làm cho sự sửa đổi hiển thị rõ với con người"},"answerDisplay":"B. Radioactive data tracing doesn't impact a model's performance.","concept":"• Radioactive Data Tracing: Đánh dấu dữ liệu huấn luyện bằng vết nước tinh vi (watermarking) để xác minh bản quyền dữ liệu bị cào trái phép mà hoàn toàn không ảnh hưởng đến độ chính xác và hiệu suất của mô hình.","whyCorrect":"• Khả năng bảo vệ bản quyền dữ liệu mà duy trì nguyên vẹn hiệu suất mô hình là ưu thế kỹ thuật cốt lõi.","whyWrong":{"A":"• Mục tiêu không phải sửa nhãn mà là theo dõi nguồn gốc.","C":"• Áp dụng cho nhiều dạng dữ liệu (hình ảnh, văn bản, âm thanh).","D":"• Vết nước phóng xạ tinh vi không thể nhận biết bằng mắt thường của con người."}}},{"id":2,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":2,"chooseType":"Choose 1 answer","question":"In which of the following applications could STRIDE or VAST classifications be applied?","options":{"A":"Black box mitigation methods","B":"Network optimization tools","C":"Bias mitigation techniques","D":"Threat modeling or analysis tools"},"answer":"D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Phân loại STRIDE hoặc VAST có thể được áp dụng trong ứng dụng nào sau đây?","optionsVi":{"A":"Các phương pháp giảm thiểu hộp đen","B":"Công cụ tối ưu hóa mạng","C":"Kỹ thuật giảm thiểu thiên vị","D":"Các công cụ mô hình hóa hoặc phân tích mối đe dọa an ninh (Threat modeling or analysis tools)"},"answerDisplay":"D. Threat modeling or analysis tools","concept":"• Mô hình hóa mối đe dọa (Threat Modeling): STRIDE (Spoofing, Tampering, Repudiation, Information Disclosure, Denial of Service, Elevation of Privilege) và VAST là hai khung tiêu chuẩn đánh giá rủi ro an ninh mạng.","whyCorrect":"• STRIDE và VAST là các khung mô hình hóa mối đe dọa kinh điển trong an toàn thông tin.","whyWrong":{"A":"• Giảm thiểu hộp đen dùng thuật toán XAI.","B":"• Tối ưu hóa mạng thuộc về hạ tầng phần mạng.","C":"• Giảm thiên vị thuộc về công bằng ML."}}},{"id":3,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":3,"chooseType":"Choose 1 answer","question":"The explainable AI movement states that cooperation between agents, in this case algorithms and humans, depends on which of the following?","options":{"A":"Trust","B":"Human rights","C":"Competition","D":"Privacy"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Phong trào AI giải thích được (Explainable AI - XAI) khẳng định sự hợp tác hiệu quả giữa các tác thể, ở đây là thuật toán và con người, phụ thuộc vào yếu tố nào?","optionsVi":{"A":"Lòng tin (Trust)","B":"Nhân quyền","C":"Cạnh tranh","D":"Quyền riêng tư"},"answerDisplay":"A. trust","concept":"• Lòng tin trong tương tác Người - AI (Human-AI Trust): Khả năng giải thích giúp con người hiểu cơ chế ra quyết định của máy, từ đó tạo dựng niềm tin hợp tác.","whyCorrect":"• Lòng tin là yếu tố quyết định sự chấp nhận và hợp tác giữa con người và thuật toán.","whyWrong":{"B":"• Nhân quyền là giá trị bảo vệ rộng lớn.","C":"• Cạnh tranh là yếu tố thị trường.","D":"• Quyền riêng tư là khía cạnh bảo mật dữ liệu."}}},{"id":4,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":4,"chooseType":"Choose 1 answer","question":"Which of the following is an explainability risk of self-learning models?","options":{"A":"Self-learning models can corrupt data","B":"Self-learning models may introduce new data you're unaware of","C":"Self-learning models are complex black boxes whose evolving decisions cannot be easily understood or predicted","D":"Self-learning models are unable to generate decisions"},"answer":"C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả rủi ro về khả năng giải thích của các mô hình tự học (Self-learning models)?","optionsVi":{"A":"Mô hình tự học làm hỏng dữ liệu","B":"Mô hình tự học đưa dữ liệu mới vào","C":"Mô hình tự học là các hộp đen phức tạp mà các quyết định tiến hóa của chúng rất khó để hiểu hoặc dự đoán (black boxes whose decisions cannot be understood)","D":"Mô hình tự học không thể ra quyết định"},"answerDisplay":"C. Self-learning models are black boxes whose decisions cannot be understood","concept":"• Rủi ro Hộp đen của Mô hình Tự học: Khi thuật toán liên tục tự điều chỉnh trọng số mà không có sự can thiệp của con người, logic ra quyết định trở nên hoàn toàn không thể giải thích.","whyCorrect":"• Sự biến đổi trọng số tự động khiến mô hình trở thành Hộp đen không thể thấu hiểu.","whyWrong":{"A":"• Mô hình không làm hỏng cấu trúc tệp.","B":"• Nhập dữ liệu mới do đường ống dữ liệu quy định.","D":"• Mô hình tự học liên tục đưa ra đầu ra quyết định."}}},{"id":5,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":5,"chooseType":"Choose 1 answer","question":"One benefit of an explainable model is:","options":{"A":"Privacy is preserved","B":"Recruiting leverage","C":"Less competition","D":"The model is more trustworthy and audit-friendly"},"answer":"D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Một lợi ích quan trọng của một mô hình giải thích được (Explainable model) là gì?","optionsVi":{"A":"Quyền riêng tư được bảo vệ tuyệt đối","B":"Lợi thế tuyển dụng","C":"Ít cạnh tranh hơn","D":"Mô hình đáng tin cậy hơn và dễ dàng kiểm toán (more trustworthy and audit-friendly)"},"answerDisplay":"D. the model is more accurate / trustworthy","concept":"• Lợi ích của XAI: Tăng cường tính đáng tin cậy, giúp các kỹ sư và kiểm toán viên dễ dàng phát hiện lỗi sai và xác minh tính công bằng.","whyCorrect":"• Tính giải thích giúp củng cố niềm tin và tạo điều kiện cho việc kiểm toán mô hình.","whyWrong":{"A":"• Giải thích mô hình đôi khi có sự đánh đổi với bảo vệ riêng tư (Privacy leak risks).","B":"• Lợi thế tuyển dụng là tác động nhân sự phụ.","C":"• Cạnh tranh phụ thuộc vào thị trường."}}},{"id":6,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":6,"chooseType":"Choose 1 answer","question":"SSL, TLS, and SSH are all forms of:","options":{"A":"Computer forensics tools","B":"Media codecs","C":"Encryption protocols","D":"Version control systems"},"answer":"C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"SSL, TLS và SSH đều là các hình thức của:","optionsVi":{"A":"Công cụ điều tra số","B":"Bộ mã hóa đa phương tiện","C":"Các giao thức mã hóa bảo mật truyền thông (Encryption protocols)","D":"Hệ thống quản lý phiên bản mã nguồn"},"answerDisplay":"C. Encryption protocols","concept":"• Giao thức mã hóa an ninh mạng: SSL, TLS (mã hóa đường truyền web HTTPS) và SSH (mã hóa kết nối máy chủ từ xa).","whyCorrect":"• SSL, TLS và SSH là các giao thức mã hóa an toàn mạng tiêu chuẩn.","whyWrong":{"A":"• Công cụ điều tra số là EnCase, Autopsy.","B":"• Media codecs là H.264, MP3.","D":"• Version control là Git, SVN."}}},{"id":7,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":7,"chooseType":"Choose 1 answer","question":"What shared principle from ethical frameworks in intellectual property often at odds with?","options":{"A":"Privacy","B":"Safety","C":"Security","D":"Transparency / Explainability"},"answer":"D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Quyền sở hữu trí tuệ (Intellectual Property - bí mật thương mại) thường mâu thuẫn trực tiếp với nguyên tắc đạo đức chung nào?","optionsVi":{"A":"Quyền riêng tư (Privacy)","B":"An toàn (Safety)","C":"An ninh (Security)","D":"Tính minh bạch và tính giải thích được (Transparency / Explainability)"},"answerDisplay":"D. Transparency/explainability","concept":"• Sự xung đột giữa Minh bạch AI và Sở hữu trí tuệ: Các công ty từ chối công khai mã nguồn/mô hình vì lý do bảo hộ bí mật kinh doanh.","whyCorrect":"• Bảo hộ bí mật thuật toán độc quyền trực tiếp ngăn cản yêu cầu công khai giải thích mô hình.","whyWrong":{"A":"• Sở hữu trí tuệ không trực tiếp xung đột với quyền riêng tư cá nhân.","B":"• An toàn là mục tiêu chung.","C":"• An ninh công nghệ được tăng cường nhờ bảo vệ bí mật."}}},{"id":8,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":8,"chooseType":"Choose 1 answer","question":"What is the primary purpose of obtaining feedback about an ethical crisis?","options":{"A":"To demonstrate compliance","B":"To make operational improvements and prevent future incidents","C":"To appease concerned stakeholders","D":"To motivate internal personnel"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Mục đích chính của việc thu thập phản hồi (Feedback) về một cuộc khủng hoảng đạo đức là gì?","optionsVi":{"A":"Để chứng minh sự tuân thủ hình thức","B":"Để thực hiện các cải tiến vận hành và đạo đức nhằm ngăn chặn sự cố tái diễn (To make operational improvements)","C":"Để xoa dịu các bên liên quan","D":"Để động viên nhân viên"},"answerDisplay":"B. To make operational improvements","concept":"• Post-Incident Feedback Loops: Sử dụng bài học sau sự cố (Lessons Learned) để cải tiến quy trình vận hành và ngăn chặn lỗi lặp lại.","whyCorrect":"• Rút kinh nghiệm để cải tiến vận hành thực chất là giá trị cao nhất của phản hồi khủng hoảng.","whyWrong":{"A":"• Tuân thủ hình thức không khắc phục được nguyên nhân gốc.","C":"• Xoa dịu suông mà không sửa đổi là thái độ dối trá.","D":"• Động viên nhân viên là tác vụ nhân sự."}}},{"id":9,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":9,"chooseType":"Choose 1 answer","question":"How can sentiment analysis be useful in social media communication?","options":{"A":"It can shape the content and delivery of the message based on users' perceptions of the organization or technology","B":"It can classify customers as loyal or disloyal","C":"It can determine users with largest influence","D":"It can influence users to be positive"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Phân tích cảm xúc (Sentiment Analysis) có thể hữu ích như thế nào trong truyền thông mạng xã hội?","optionsVi":{"A":"Nó giúp định hình nội dung và cách thức phân phối thông điệp dựa trên nhận thức/cảm xúc hiện tại của người dùng đối với tổ chức hoặc công nghệ (shape content and delivery based on perception)","B":"Phân loại khách hàng trung thành hay không","C":"Xác định người có tầm ảnh hưởng lớn nhất","D":"Thao túng người dùng tích cực hơn"},"answerDisplay":"A. It can shape the content and delivery of the message based on users' perceptions of the organization or technology _","concept":"• Sentiment Analysis phân tích thái độ dư luận (Tích cực, Tiêu cực, Trung tính) để điều chỉnh chiến lược truyền thông phù hợp.","whyCorrect":"• Hiểu thái độ công chúng giúp tổ chức tinh chỉnh thông điệp và thời điểm phát ngôn tối ưu.","whyWrong":{"B":"• Trung thành là chỉ số Customer Retention.","C":"• Người ảnh hưởng được đo bằng Influencer Metrics.","D":"• Phân tích cảm xúc đo lường thái độ chứ không thao túng tâm lý trực tiếp."}}},{"id":10,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":10,"chooseType":"Choose 1 answer","question":"Which of the following is a best practice when participating in media inquiries?","options":{"A":"Only agree to speak to favorable outlets","B":"Get your message out as quickly as possible without verification","C":"Divulge only legal information","D":"Ensure your message is clear, truthful, and consistent across channels"},"answer":"D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Thực hành tốt nhất khi tham gia phản hồi các yêu cầu phỏng vấn của báo chí/truyền thông là gì?","optionsVi":{"A":"Chỉ đồng ý nói chuyện với báo giới thân quen","B":"Phát ngôn càng nhanh càng tốt mà không cần xác minh","C":"Chỉ tiết lộ thông tin bắt buộc","D":"Đảm bảo thông điệp của bạn rõ ràng, trung thực và nhất quán trên mọi kênh truyền thông (Ensure your message is consistent)","E":"Từ chối trả lời"},"answerDisplay":"D. Ensure your message is consistent","concept":"• Nhất quán trong Truyền thông Báo chí (Message Consistency): Giúp duy trì uy tín và tránh mâu thuẫn thông tin gây ra bất ổn dư luận.","whyCorrect":"• Đảm bảo tính thống nhất nhất quán của thông điệp tránh phát ngôn sai lệch.","whyWrong":{"A":"• Né tránh báo chí đối lập tạo ra nghi vấn che giấu.","B":"• Phát ngôn vội vàng chưa xác minh dễ gây ra tin giả.","C":"• Tiết lộ quá ít tạo cảm giác thiếu hợp tác."}}},{"id":11,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":11,"chooseType":"Choose 1 answer","question":"Which of the following can help mitigate unwillingness to accept feedback in an organization?","options":{"A":"Engage in cultural awareness","B":"Create and participate in a risk culture of open feedback","C":"Communicate the importance of feedback","D":"Communicate regularly about values"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây có thể giúp giảm thiểu thái độ e ngại/miễn cưỡng khi tiếp nhận phản hồi trong một tổ chức?","optionsVi":{"A":"Tham gia nhận thức văn hóa","B":"Xây dựng và tham gia vào một văn hóa rủi ro mở lắng nghe phản hồi (risk culture of open feedback)","C":"Truyền thông tầm quan trọng của phản hồi","D":"Truyền thông định kỳ về giá trị"},"answerDisplay":"B. Create and participate in a risk culture.","concept":"• Risk Culture (Văn hóa Rủi ro minh bạch): Cho phép nhân viên thoải mái báo cáo sai sót và tiếp nhận phản hồi mà không sợ bị trừng phạt.","whyCorrect":"• Xây dựng văn hóa mở thúc đẩy việc tự giác lắng nghe và sửa đổi.","whyWrong":{"A":"• Nhận thức văn hóa là phạm vi DEI.","C":"• Truyền thông lý thuyết suông không thay đổi được tâm lý lo sợ trừng phạt.","D":"• Nói về giá trị không tự động xóa bỏ tâm lý e ngại."}}},{"id":12,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":12,"chooseType":"Choose 1 answer","question":"If you were faced with an AI system that predicts specific human actions across broad general domains better than humans, this system is classified as:","options":{"A":"Narrow AI","B":"General AI","C":"Superintelligence (Artificial Superintelligence - ASI)","D":"Basic AI"},"answer":"C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nếu bạn đối mặt với một hệ thống AI có khả năng dự đoán và thực hiện các tác vụ vượt trội hơn con người trên nhiều lĩnh vực tổng quát rộng lớn, hệ thống này được phân loại là:","optionsVi":{"A":"AI hẹp (Narrow AI)","B":"AI tổng quát (General AI)","C":"Siêu trí tuệ nhân tạo (Superintelligence / ASI)","D":"AI cơ bản"},"answerDisplay":"C. Superintelligence","concept":"• Phân loại AI: Narrow AI (Trí tuệ chuyên biệt một việc), AGI (Trí tuệ ngang tầm con người), Superintelligence (Trí tuệ vượt trội hoàn toàn con người trên mọi lĩnh vực).","whyCorrect":"• Vượt trội hoàn toàn trí tuệ con người trên đa lĩnh vực là định nghĩa của Superintelligence.","whyWrong":{"A":"• Narrow AI chỉ giỏi một tác vụ hẹp (như đánh cờ).","B":"• General AI mới chỉ đạt mức ngang bằng nhận thức con người.","D":"• Basic AI là các thuật toán quy tắc đơn giản."}}},{"id":13,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":13,"chooseType":"Choose 1 answer","question":"What is ambient intelligence?","options":{"A":"Linked IoT technology collecting home data","B":"Linked IoT conducting surveillance","C":"Linked IoT technology that is always on and acting to personalize the experience for people within its environment","D":"Linked IoT technology collecting campus data"},"answer":"C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Trí tuệ môi trường (Ambient Intelligence) được định nghĩa là gì?","optionsVi":{"A":"Công nghệ IoT thu thập dữ liệu nhà ở","B":"Công nghệ IoT giám sát lén lút","C":"Mạng lưới công nghệ IoT kết nối luôn bật và chủ động tương tác để cá nhân hóa trải nghiệm cho con người trong môi trường sống (always on and acting to personalize experience)","D":"Công nghệ IoT thu thập dữ liệu khuôn viên"},"answerDisplay":"C. Linked IOT technology that always on and acting to personalize the experience for the people within its environment","concept":"• Ambient Intelligence (AmI): Môi trường thông minh tích hợp cảm biến IoT luôn hiện diện nhạy bén để tự động phục vụ nhu cầu con người.","whyCorrect":"• Tính chất luôn bật và tự động cá nhân hóa môi trường sống cho con người là bản chất của Ambient Intelligence.","whyWrong":{"A":"• Thu thập dữ liệu nhà ở chỉ là Smart Home cơ bản.","B":"• Giám sát lén lút là Mass Surveillance.","D":"• Dữ liệu khuôn viên là Campus IoT."}}},{"id":14,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":14,"chooseType":"Choose 1 answer","question":"Your organization has developed an AI system that recommends treatments for hospital patients. What applied ethics domain do these concerns fall under?","options":{"A":"Bioethics (or Medical Ethics)","B":"Engineering ethics","C":"Business ethics","D":"Environmental ethics"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Tổ chức của bạn đã phát triển một hệ thống AI gợi ý phác đồ điều trị cho bệnh nhân nhập viện. Các lo ngại đạo đức liên quan thuộc về lĩnh vực đạo đức ứng dụng nào?","optionsVi":{"A":"Đạo đức sinh học / Đạo đức y khoa (Bioethics)","B":"Đạo đức kỹ thuật (Engineering ethics)","C":"Đạo đức kinh doanh (Business ethics)","D":"Đạo đức môi trường (Environmental ethics)"},"answerDisplay":"A. Bioethics","concept":"• Bioethics (Đạo đức sinh học/y khoa) điều chỉnh các vấn đề đạo đức phát sinh trong chăm sóc sức khỏe, y tế và ứng dụng công nghệ sinh học trên con người.","whyCorrect":"• Ứng dụng điều trị y tế cho bệnh nhân thuộc phạm vi trực tiếp của Bioethics.","whyWrong":{"B":"• Engineering ethics điều chỉnh quy chuẩn xây dựng và thiết kế phần cứng.","C":"• Business ethics điều chỉnh quan hệ thương mại và thị trường.","D":"• Environmental ethics điều chỉnh tác động môi trường tự nhiên."}}},{"id":15,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":15,"chooseType":"Choose 1 answer","question":"How does a smart contract differ from a traditional legal contract?","options":{"A":"Smart contracts serve a completely different purpose","B":"Smart contracts automatically execute terms via code and eliminate the need for a central trusted authority","C":"Smart contracts are always more effective","D":"Smart contracts guarantee all parties remain anonymous"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Hợp đồng thông minh (Smart contract) khác biệt như thế nào so với hợp đồng pháp lý truyền thống?","optionsVi":{"A":"Hợp đồng thông minh phục vụ mục đích khác","B":"Hợp đồng thông minh tự động thực thi các điều khoản bằng mã code phần mềm và loại bỏ nhu cầu về một cơ quan trung gian phân xử (eliminate need for central authority)","C":"Hợp đồng thông minh luôn hiệu quả hơn","D":"Hợp đồng thông minh đảm bảo ẩn danh tuyệt đối"},"answerDisplay":"B. Smart contracts eliminate the need for a central authority.","concept":"• Smart Contracts (Blockchain): Mã lập trình tự động thực thi (Self-executing code) khi thỏa điều kiện, loại bỏ các bên trung gian (Central Authority).","whyCorrect":"• Tự động thực thi mã nguồn trên Blockchain loại bỏ vai trò của các thực thể trung gian phân xử.","whyWrong":{"A":"• Cả hai đều giao kết cam kết giữa các bên.","C":"• Hiệu quả phụ thuộc vào tính chuẩn xác của mã nguồn.","D":"• Tính ẩn danh không bắt buộc trong smart contract."}}},{"id":16,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":16,"chooseType":"Choose 1 answer","question":"Which of the following statements accurately describes the philosophical concept of Determinism?","options":{"A":"All future events are determined by preceding events, as in a chain","B":"All events, past, present, and future, are determined in advance by causal laws","C":"Human beings are able to make choices whose outcomes are not determined","D":"All events are predestined by supernatural force"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Phát biểu nào sau đây mô tả chính xác triết lý Thuyết quyết định luận (Determinism)?","optionsVi":{"A":"Tương lai bị quyết định theo chuỗi","B":"Mọi sự kiện quá khứ, hiện tại và tương lai đều được quyết định trước bởi các quy luật nguyên nhân - kết quả tiền đề (All events determined in advance by preceding causes)","C":"Con người tự do đưa ra lựa chọn độc lập","D":"Mọi sự kiện do định mệnh siêu nhiên an bài"},"answerDisplay":"B. All events, past, present, and future, are determined in advance.","concept":"• Determinism (Thuyết quyết định luận): Mọi hành vi và sự kiện vũ trụ đều bị quy định chặt chẽ bởi chuỗi nguyên nhân - kết quả vật lý xảy ra trước đó.","whyCorrect":"• Quan điểm triết học cho rằng mọi sự kiện đều được an bài trước bởi chuỗi nguyên nhân nhân quả tiền đề.","whyWrong":{"A":"• Quyết định luận không cho phép sự can thiệp ngẫu nhiên ngoài quy luật.","C":"• Lựa chọn độc lập là Thuyết ý chí tự do (Free Will).","D":"• An bài siêu nhiên là Thuyết định mệnh (Fatalism)."}}},{"id":17,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":17,"chooseType":"Choose 1 answer","question":"Which of the following, by itself, qualifies as personally identifiable information (PII)?","options":{"A":"System events added to a log","B":"A user's home address","C":"Temperature readings for an office building","D":"A user's customer ID in an online ordering system"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây, bản thân nó đủ điều kiện cấu thành Thông tin định danh cá nhân (PII)?","optionsVi":{"A":"Sự kiện hệ thống trong tệp log","B":"Địa chỉ nhà riêng của người dùng (User's home address)","C":"Nhiệt độ tòa nhà","D":"Mã ID khách hàng"},"answerDisplay":"B. A user's home address","concept":"• Personally Identifiable Information (PII): Dữ liệu trực tiếp xác định danh tính cá nhân cụ thể như Địa chỉ nhà (Home Address), Số CMND/CCCD, Email cá nhân.","whyCorrect":"• Địa chỉ nhà riêng là thông tin định danh trực tiếp xác định vị trí cư trú cá nhân.","whyWrong":{"A":"• Log hệ thống là dữ liệu an ninh kỹ thuật.","C":"• Nhiệt độ tòa nhà là dữ liệu môi trường.","D":"• Mã Customer ID cần bảng ánh xạ nội bộ mới xác định được tên cá nhân."}}},{"id":18,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":18,"chooseType":"Choose 1 answer","question":"You have collected social media posts with a specific hashtag. What is the first step in cleaning this text dataset?","options":{"A":"Tokenization and removing special characters/punctuation","B":"Building a neural network","C":"Encrypting the dataset","D":"Running sentiment analysis"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Bạn đã thu thập các bài đăng trên mạng xã hội chứa một hashtag cụ thể. Bước đầu tiên trong việc làm sạch tập dữ liệu văn bản này là gì?","optionsVi":{"A":"Tách từ (Tokenization) và loại bỏ các ký tự đặc biệt / dấu câu (removing special characters and noise)","B":"Xây dựng mạng nơ-ron","C":"Mã hóa tập dữ liệu","D":"Chạy phân tích cảm xúc"},"answerDisplay":"A. Tokenization and removing special characters","concept":"• NLP Data Cleaning: Tách từ (Tokenization), hạ chữ thường (Lowercasing) và lọc bỏ nhiễu ký tự đặc biệt trước khi đưa vào mô hình học máy.","whyCorrect":"• Tiền xử lý văn bản bằng cách tách từ và lọc nhiễu là bước móng bắt buộc.","whyWrong":{"B":"• Xây dựng mô hình thực hiện ở khâu sau.","C":"• Mã hóa dữ liệu là khâu bảo mật lưu trữ.","D":"• Phân tích cảm xúc là mục tiêu xử lý sau khi dữ liệu đã sạch."}}},{"id":19,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":19,"chooseType":"Choose 1 answer","question":"Which of the following defines the AI black box problem?","options":{"A":"The challenge of understanding how complex machine learning algorithms make specific decisions","B":"Not knowing how something crashed","C":"Machine intelligence making illusory predictions","D":"A dangerous machine put in digital prison"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây định nghĩa bài toán Hộp đen (Black box problem) trong AI?","optionsVi":{"A":"Thách thức trong việc thấu hiểu cách các thuật toán học máy phức tạp đưa ra các quyết định cụ thể (challenge of understanding how algorithms make decisions)","B":"Không biết tại sao phần mềm sụp đổ","C":"Trí tuệ máy tạo ra dự đoán ảo","D":"Máy tính bị giam trong tù số"},"answerDisplay":"A. The challenge of understanding how complex ML algorithms make decisions.","concept":"• Black Box Problem: Không thể truy ngược logic toán học bên trong mạng nơ-ron để giải thích lý do đầu ra.","whyCorrect":"• Không thể giải thích cơ chế đưa ra quyết định bên trong là định nghĩa chuẩn của Black Box.","whyWrong":{"B":"• Phần mềm crash là lỗi lập trình (Bug/Exception).","C":"• Dự đoán ảo là Ảo giác AI (Hallucination).","D":"• Digital prison là khái niệm viễn tưởng AI Containment."}}},{"id":20,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":20,"chooseType":"Choose 1 answer","question":"A type of artificial intelligence that outperforms humans in specific defined tasks is known as:","options":{"A":"General AI","B":"Narrow AI (Weak AI)","C":"AEI","D":"Special AI"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Loại trí tuệ nhân tạo vượt trội hơn con người trong một số nhiệm vụ cụ thể được xác định rõ được gọi là gì?","optionsVi":{"A":"AI tổng quát (General AI)","B":"AI hẹp / AI chuyên biệt (Narrow AI)","C":"AEI","D":"AI đặc biệt"},"answerDisplay":"B. Narrow Al","concept":"• Narrow AI (AI hẹp): Được thiết kế và huấn luyện chuyên sâu cho một tác vụ duy nhất (nhận diện khuôn mặt, chơi cờ AlphaGo) và vượt trội hơn con người ở tác vụ đó.","whyCorrect":"• Trí tuệ chuyên biệt một lĩnh vực cụ thể là định nghĩa của Narrow AI.","whyWrong":{"A":"• General AI có năng lực trí tuệ đa nhiệm toàn diện như con người.","C":"• AEI không phải thuật ngữ AI tiêu chuẩn.","D":"• Special AI không phải khái niệm học thuật."}}},{"id":21,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":21,"chooseType":"Choose 1 answer","question":"What is the fundamental attribution error in cognitive psychology?","options":{"A":"Assuming cause-effect for correlated variables","B":"Believing your negative risks are lower than others","C":"Believing your ideas are normal","D":"Attributing one's own bad behavior to situational factors, but attributing others' bad behavior to internal personality traits"},"answer":"D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Lỗi quy kết cơ bản (Fundamental attribution error) trong tâm lý học nhận thức là gì?","optionsVi":{"A":"Giả định nguyên nhân kết quả cho hai biến tương quan","B":"Tin rằng rủi ro tiêu cực của mình thấp hơn người khác","C":"Tin rằng ý kiến mình là số đông","D":"Quy kết hành vi xấu của bản thân là do hoàn cảnh khách quan, nhưng quy kết hành vi xấu tương tự của người khác là do tính cách tiêu cực nội tại của họ (own bad behavior to situation, others to personality)"},"answerDisplay":"D. When you say your bad behavior is caused by the situation, but when other people display the same bad behavior, it is caused by a personality trait","concept":"• Fundamental Attribution Error: Định kiến tâm lý luôn đổ lỗi cho hoàn cảnh khi bản thân mắc sai lầm, nhưng lại quy kết cho phẩm chất đạo đức/tính cách khi người khác mắc sai lầm tương tự.","whyCorrect":"• Phản ánh chính xác xu hướng tâm lý quy kết hoàn cảnh cho mình và quy kết tính cách cho người khác.","whyWrong":{"A":"• Đây là nhầm lẫn Tương quan và Nhân quả (Correlation vs Causation).","B":"• Đây là Định kiến lạc quan (Optimism bias).","C":"• Đây là Hiệu ứng đồng thuận giả (False consensus effect)."}}},{"id":22,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":22,"chooseType":"Choose 1 answer","question":"When building a predictive model, what is the goal of the training phase?","options":{"A":"To specify algorithm and clean data","B":"To adjust the model based on a subset of data, optimizing for a lower error rate","C":"To use the model in real-world scenarios","D":"To adjust training methods from backpropagation to supervised learning"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Khi xây dựng một mô hình dự đoán, mục tiêu của giai đoạn huấn luyện (Training phase) là gì?","optionsVi":{"A":"Chỉ định thuật toán và làm sạch dữ liệu","B":"Điều chỉnh các trọng số của mô hình dựa trên tập dữ liệu huấn luyện, tối ưu hóa để đạt tỷ lệ lỗi sai thấp nhất (adjust model, optimize for lower error rate)","C":"Sử dụng mô hình trong kịch bản thực tế","D":"Chuyển đổi phương pháp huấn luyện"},"answerDisplay":"B. To adjust the model based on a subset of data, optimizing for a lower error rate","concept":"• Mục tiêu Huấn luyện (Training Goal): Cập nhật trọng số (Weights) nhằm giảm thiểu hàm tổn thất (Loss Function).","whyCorrect":"• Tối ưu hóa trọng số mô hình để hạ thấp tỷ lệ sai số là bản chất của giai đoạn huấn luyện.","whyWrong":{"A":"• Khâu chọn thuật toán thuộc pha chuẩn bị.","C":"• Sử dụng thực tế thuộc pha triển khai (Deployment).","D":"• Backpropagation là kỹ thuật nằm trong Supervised Learning."}}},{"id":23,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":23,"chooseType":"Choose 1 answer","question":"Which of the following best describes beneficence?","options":{"A":"Beneficence is a term coined by IBM for Green Horizons","B":"Beneficence is the active promotion of well-being, not just for moral agents like humans, but of animals, environment, and societies","C":"Beneficence is promotion of well-being for humans only","D":"Beneficence is promotion of efficient system performance"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất khái niệm Thuyết làm điều thiện (Beneficence)?","optionsVi":{"A":"Thuật ngữ do IBM đặt ra năm 2014","B":"Beneficence là việc chủ động thúc đẩy sự thịnh vượng/tốt đẹp, không chỉ cho con người mà còn cho động vật, môi trường và toàn xã hội (promotion of well-being for humans, animals, environment, societies)","C":"Beneficence chỉ thúc đẩy lợi ích cho con người","D":"Beneficence là thúc đẩy hiệu suất hệ thống"},"answerDisplay":"B. Beneficence is the promotion of well-being, not just for moral agents like humans, but of animals, the environment, and societies _","concept":"• Beneficence (Thuyết làm điều thiện) bao quát việc chủ động tạo ra tác động tích cực rộng lớn cho con người, hệ sinh thái và toàn xã hội.","whyCorrect":"• Định nghĩa toàn diện về việc tạo dựng lợi ích cho con người, sinh giới và môi trường.","whyWrong":{"A":"• Beneficence là triết lý đạo đức cổ điển có từ thời Hy Lạp.","C":"• Định nghĩa hẹp bỏ qua tác động môi trường sinh thái.","D":"• Hiệu suất hệ thống là chỉ số phần mềm."}}},{"id":24,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":24,"chooseType":"Choose 1 answer","question":"How can a visual contract be easier to understand than a written contract?","options":{"A":"The use of pictures is more accessible to all people","B":"The use of pictures explains the contract in greater detail","C":"The use of pictures with simple text makes it easier for the layperson to understand the details of a contract","D":"The use of pictures without text makes it easier"},"answer":"C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Làm thế nào một hợp đồng hình ảnh (Visual contract) có thể dễ hiểu hơn một hợp đồng văn bản truyền thống?","optionsVi":{"A":"Hình ảnh tiếp cận tốt hơn với mọi người","B":"Hình ảnh giải thích chi tiết hơn","C":"Việc sử dụng hình ảnh kết hợp với văn bản đơn giản giúp người không chuyên dễ hiểu các chi tiết của hợp đồng hơn (pictures with simple text makes it easier for layperson)","D":"Sử dụng hình ảnh không cần văn bản"},"answerDisplay":"C. The use of pictures with simple text makes it easier for the layperson to understand the details of a contract","concept":"• Legal Design & Visual Contracts: Kết hợp minh họa trực quan với ngôn ngữ phổ thông giúp giảm rào cản nhận thức pháp lý cho người tiêu dùng đại chúng.","whyCorrect":"• Hình ảnh trực quan đi kèm văn bản giản dị giúp người dùng bình thường thấu hiểu các điều khoản pháp lý phức tạp.","whyWrong":{"A":"• Chỉ hình ảnh không thay thế hoàn toàn được thuật ngữ pháp lý.","B":"• Văn bản chi tiết hơn hình ảnh nhưng hình ảnh giúp minh họa tinh gọn.","D":"• Hợp đồng hoàn toàn không văn bản gây mập mờ tính pháp lý."}}},{"id":25,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":25,"chooseType":"Choose 1 answer","question":"Why is deciding how to act using moral reasoning not always a feasible goal for human beings?","options":{"A":"Most people are not educated on normative ethical theories","B":"Moral reasoning is too complicated for real-world situations","C":"Moral reasoning has few tangible benefits","D":"Human decision making is often influenced by emotion, bias, and context rather than logic"},"answer":"D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Tại sao việc đưa ra quyết định hành động bằng lý trí đạo đức không phải lúc nào cũng là mục tiêu khả thi đối với con người?","optionsVi":{"A":"Hầu hết mọi người không được học lý thuyết đạo đức","B":"Lý trí đạo đức quá phức tạp","C":"Lý trí đạo đức có ít lợi ích hữu hình","D":"Quyết định của con người thường bị chi phối mạnh mẽ bởi cảm xúc, định kiến và nhận thức hơn là logic thuần túy (influenced by emotion and not logic)"},"answerDisplay":"D. Human decision making is often influenced by emotion and not logic.","concept":"• Tâm lý học hành vi (Bounded Rationality): Quyết định thực tế của con người bị chi phối bởi cảm xúc, áp lực thời gian và định kiến nhận thức.","whyCorrect":"• Cảm xúc và định kiến tâm lý thường lấn áp khả năng lập luận logic đạo đức thuần túy.","whyWrong":{"A":"• Con người có nhận thức đạo đức tự nhiên mà không cần học lý thuyết chính quy.","B":"• Lý trí đạo đức áp dụng tốt trong nhiều tình huống thực tế.","C":"• Quyết định đạo đức mang lại giá trị uy tín và xã hội rất lớn."}}},{"id":26,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":26,"chooseType":"Choose 1 answer","question":"Your business handles the personal data of California residents. Which of the following regulations would enable a resident to request that their data be deleted from your company's files?","options":{"A":"PCI DSS","B":"OECD Privacy Guidelines","C":"COPPA","D":"CCPA"},"answer":"D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Doanh nghiệp của bạn xử lý dữ liệu cá nhân của cư dân California. Quy định nào sau đây cho phép cư dân yêu cầu xóa dữ liệu của họ khỏi tệp của công ty?","optionsVi":{"A":"PCI DSS","B":"Hướng dẫn quyền riêng tư OECD","C":"COPPA","D":"CCPA (Đạo luật quyền riêng tư người tiêu dùng California)"},"answerDisplay":"D. CCPA","concept":"• CCPA (California Consumer Privacy Act) trao cho cư dân California quyền yêu cầu doanh nghiệp xóa dữ liệu cá nhân (Right to Delete).","whyCorrect":"• CCPA là đạo luật riêng tư của bang California quy định rõ quyền xóa dữ liệu cá nhân của người tiêu dùng.","whyWrong":{"A":"• PCI DSS là tiêu chuẩn an toàn dữ liệu thẻ thanh toán ngân hàng.","B":"• OECD Privacy Guidelines là khuyến nghị quốc tế, không phải luật bắt buộc thi hành tại California.","C":"• COPPA là luật bảo vệ quyền riêng tư trẻ em trên mạng của Mỹ."}}},{"id":27,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":27,"chooseType":"Choose 1 answer","question":"Which type of fairness would make sense when dividing concert/event tickets evenly between different demographic groups?","options":{"A":"Equality of false positives","B":"Error rate parity","C":"Statistical parity (Demographic parity)","D":"Equality of prediction rate"},"answer":"C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Loại tiêu chuẩn công bằng nào sẽ có ý nghĩa nhất khi phân chia vé tham dự sự kiện chia đều theo tỷ lệ đại diện của các nhóm nhân khẩu học khác nhau?","optionsVi":{"A":"Bình đẳng dương tính giả","B":"Cân bằng tỷ lệ lỗi","C":"Cân bằng thống kê / nhân khẩu học (Statistical parity / Demographic parity)","D":"Bình đẳng tỷ lệ dự đoán"},"answerDisplay":"C. statistical parity","concept":"• Statistical Parity (Demographic Parity): Đảm bảo tỷ lệ lựa chọn / phân bổ tài nguyên đạt mức ngang nhau giữa các nhóm xã hội.","whyCorrect":"• Phân chia tài nguyên vé tham dự bằng nhau giữa các nhóm là biểu hiện chuẩn của Statistical Parity.","whyWrong":{"A":"• False positive parity xét tỷ lệ lỗi báo nhầm.","B":"• Error rate parity xét tỷ lệ lỗi sai.","D":"• Prediction rate parity đo lường tỷ lệ đầu ra tổng thể."}}},{"id":28,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":28,"chooseType":"Choose 1 answer","question":"An unfair model will by nature:","options":{"A":"Optimize for making the fewest decisions","B":"Try to balance groups automatically","C":"Optimize for overall accuracy while concentrating errors on a specific subgroup","D":"Optimize for making the fewest mistakes"},"answer":"C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Một mô hình không công bằng (Unfair model) về mặt bản chất sẽ thực hiện thao tác tối ưu hóa nào?","optionsVi":{"A":"Tối ưu hóa để ra ít quyết định nhất","B":"Tự động cân bằng các nhóm","C":"Tối ưu hóa độ chính xác chung trong khi dồn sai số/lỗi sai lên một nhóm yếu thế cụ thể (concentrating errors on a specific subgroup)","D":"Tối ưu hóa để mắc ít lỗi nhất"},"answerDisplay":"C. optimize for overall accuracy while concentrating errors on a specific subgroup","concept":"• Bản chất của Unfair Model: Đạt chỉ số Accuracy tổng thể cao bằng cách hy sinh nhóm yếu thế (dồn tỷ lệ lỗi False Positive / False Negative lên nhóm đó).","whyCorrect":"• Mô hình thiên vị giữ độ chính xác tổng thể bằng cách dồn sai sót thiệt hại lên phân nhóm thiểu số.","whyWrong":{"A":"• Số lượng quyết định không phản ánh tính công bằng.","B":"• Mô hình thiên vị không tự động cân bằng nhóm.","D":"• Mắc ít lỗi nhất không đảm bảo lỗi được phân bố đều."}}},{"id":29,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":29,"chooseType":"Choose 1 answer","question":"Which of the following best describes capability caution as referenced in the Asilomar AI Principles?","options":{"A":"Halt AI development if internal mechanisms are unknown","B":"Avoid strong assumptions regarding upper limits on future AI capabilities","C":"Ensure humans are capable of finding work","D":"Keep limits on AGI capabilities"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất nguyên tắc Thận trọng về Năng lực (Capability Caution) trong Nguyên tắc Asilomar AI?","optionsVi":{"A":"Dừng phát triển AI nếu không hiểu cơ chế nội tại","B":"Tránh đưa ra các giả định cứng nhắc cho rằng có những giới hạn trên đối với năng lực AI trong tương lai (avoid strong assumptions regarding upper limits on future AI capabilities)","C":"Đảm bảo con người có việc làm","D":"Đặt giới hạn cho AGI"},"answerDisplay":"B. Given a lack of consensus, we should avoid strong assumptions regarding upper limits on future Al capabilities","concept":"• Capability Caution (Asilomar Principles): Không được chủ quan cho rằng AI có ngưỡng giới hạn trên, mà phải luôn cảnh giác trước sự bùng nổ trí tuệ công nghệ.","whyCorrect":"• Không đưa ra giả định chủ quan về giới hạn năng lực AI trong tương lai để luôn sẵn sàng quản lý rủi ro.","whyWrong":{"A":"• Dừng phát triển không phải khuyến nghị Asilomar.","C":"• Việc làm thuộc về nguyên tắc Human Alignment.","D":"• Giới hạn AGI thuộc về AI Safety Control."}}},{"id":30,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":30,"chooseType":"Choose 1 answer","question":"What does the American Medical Association (AMA) say the 'A' in AI should stand for in healthcare?","options":{"A":"Automated","B":"Augmented (Augmented Intelligence)","C":"Artificial","D":"Auditability"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Hiệp hội Y khoa Hoa Kỳ (AMA) đề xuất chữ 'A' trong thuật ngữ AI trong y tế nên đại diện cho điều gì?","optionsVi":{"A":"Tự động (Automated)","B":"Gia tăng / Hỗ trợ (Augmented Intelligence)","C":"Nhân tạo (Artificial)","D":"Khả năng kiểm toán (Auditability)"},"answerDisplay":"B. Augmented","concept":"• Augmented Intelligence (Trí tuệ Gia tăng): AMA nhấn mạnh AI trong y tế chỉ đóng vai trò hỗ trợ gia tăng năng lực chẩn đoán của bác sĩ con người (Human-in-the-loop) chứ không thay thế bác sĩ.","whyCorrect":"• Augmented Intelligence thể hiện vai trò công cụ hỗ trợ nâng cao năng lực y bác sĩ.","whyWrong":{"A":"• Tự động hóa hoàn toàn nguy hiểm trong y tế.","C":"• Artificial là định nghĩa truyền thống mà AMA muốn thay đổi góc nhìn.","D":"• Auditability là thuộc tính kỹ thuật."}}},{"id":31,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":31,"chooseType":"Choose 1 answer","question":"Which of the following resources does the National Institute of Standards and Technology (NIST) provide for AI risk management?","options":{"A":"Measurement technologies and standards frameworks (NIST AI RMF)","B":"Reference materials","C":"Security tools","D":"Industrial configurations"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nguồn lực nào sau đây được Viện Tiêu chuẩn và Công nghệ Quốc gia Mỹ (NIST) cung cấp cho quản lý rủi ro AI?","optionsVi":{"A":"Các công nghệ đo lường và Khung làm việc quản lý rủi ro AI (NIST AI Risk Management Framework - AI RMF)","B":"Tài liệu tham khảo","C":"Công cụ an ninh","D":"Cấu hình công nghiệp"},"answerDisplay":"A. Measurement technologies","concept":"• NIST AI RMF (Risk Management Framework): Cung cấp các phương pháp đo lường, đánh giá và quản trị rủi ro AI cho các tổ chức.","whyCorrect":"• Các công nghệ đo lường và chuẩn hóa quản lý rủi ro là sản phẩm cốt lõi của NIST.","whyWrong":{"B":"• Tài liệu tham khảo chỉ là thành phần phụ.","C":"• NIST không bán/cung cấp phần mềm công cụ an ninh trực tiếp.","D":"• Cấu hình công nghiệp thuộc về nhà sản xuất."}}},{"id":32,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":32,"chooseType":"Choose 1 answer","question":"A 'purposefully biased' algorithm used to identify unfair attributes in system decisions is an example of:","options":{"A":"Bias testing and algorithmic auditing","B":"Data corruption","C":"Malicious hacking","D":"System failure"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Một thuật toán được 'cố ý thiết kế thiên vị' bởi các kiểm toán viên nhằm phát hiện các thuộc tính bất công trong quyết định hệ thống là ví dụ về:","optionsVi":{"A":"Kiểm thử thiên vị và kiểm toán thuật toán (Bias testing and algorithmic auditing)","B":"Hư hỏng dữ liệu","C":"Hacking độc hại","D":"Lỗi hệ thống"},"answerDisplay":"A. Bias testing and algorithmic auditing","concept":"• Stress-testing AI via Synthetic Bias: Cố ý đưa mẫu thiên vị vào kiểm thử để đánh giá mức độ chống chịu và phản ứng của mô hình kiểm toán.","whyCorrect":"• Sử dụng dữ liệu lệch cố ý để đo lường tính nhạy cảm thiên vị của hệ thống.","whyWrong":{"B":"• Không làm hỏng cấu trúc dữ liệu.","C":"• Đây là hoạt động kiểm toán an toàn hợp pháp.","D":"• Đây là phương pháp kiểm thử chủ động."}}},{"id":33,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":33,"chooseType":"Choose 1 answer","question":"Why is it impractical to protect all possible subgroups in predictive models?","options":{"A":"Subgroup math splits data so finely that there won't be enough data to accurately reflect each subgroup (Combinatorial explosion of attributes)","B":"Fairness scores won't be high enough","C":"Individuals do not need protection","D":"Regulations forbid it"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Tại sao việc bảo vệ tuyệt đối tất cả các phân nhóm nhỏ có thể xảy ra lại không thực tế trong các mô hình dự đoán?","optionsVi":{"A":"Việc chia nhỏ nhóm dẫn tới hiện tượng bùng nổ tổ hợp, khiến tập dữ liệu mẫu cho từng nhóm quá nhỏ không đủ để huấn luyện mô hình chính xác (won't be enough data to reflect each subgroup)","B":"Điểm công bằng không đủ cao","C":"Cá nhân không cần bảo vệ","D":"Quy định pháp lý cấm"},"answerDisplay":"A. There won't be enough data to reflect each subgroup","concept":"• Combinatorial Explosion in Subgroup Fairness: Khi kết hợp quá nhiều thuộc tính (tuổi x giới tính x chủng tộc x thu nhập), số lượng nhóm tăng theo cấp số nhân khiến dữ liệu bị phân mảnh quá nhỏ.","whyCorrect":"• Sự bùng nổ tổ hợp chia nhỏ tập dữ liệu khiến dữ liệu không đủ đại diện cho từng nhóm nhỏ.","whyWrong":{"B":"• Điểm công bằng phụ thuộc vào mô hình.","C":"• Cá nhân luôn cần được bảo vệ.","D":"• Luật khuyến khích bảo vệ nhóm."}}},{"id":34,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":34,"chooseType":"Choose 1 answer","question":"What makes ethics training effective in an organization?","options":{"A":"Keep sessions short and focused","B":"Keep sessions interactive and engaging","C":"Keep content simple and direct","D":"All of the above (Short, interactive, simple and actionable)"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Điều gì giúp cho các chương trình tập huấn đạo đức trong tổ chức đạt hiệu quả cao?","optionsVi":{"A":"Giữ các buổi ngắn gọn và tập trung","B":"Tạo tính tương tác cao và cuốn hút người tham gia (Keep sessions interactive)","C":"Nội dung đơn giản trực tiếp","D":"Tất cả các yếu tố trên"},"answerDisplay":"B. Keep sessions interactive.","concept":"• Đào tạo đạo đức hiệu quả đòi hỏi phương pháp Tương tác (Interactive Case Studies) giúp nhân viên tự nhập vai giải quyết tình huống thay vì nghe giảng thụ động.","whyCorrect":"• Tính tương tác giúp nhân viên chủ động rèn luyện tư duy phản biện đạo đức trong thực tế.","whyWrong":{"A":"• Thời lượng ngắn không quyết định được chất lượng tiếp thu nếu thiếu tương tác.","C":"• Nội dung đơn giản chỉ là điều kiện cần.","D":"• Đáp án B thể hiện phương pháp giảng dạy tích cực hàng đầu."}}},{"id":35,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":35,"chooseType":"Choose 1 answer","question":"Which approach to corporate governance is more likely to create an ethical organizational culture?","options":{"A":"A systemic approach with incentive systems align with values","B":"An oversight committee focus solely on rules","C":"A board focused only on legal compliance","D":"An oversight committee focus on static frameworks"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Cách tiếp cận quản trị doanh nghiệp nào có khả năng cao hơn trong việc tạo ra một văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Cách tiếp cận hệ thống kết hợp với hệ thống khuyến khích / đãi ngộ gắn liền với giá trị đạo đức (systemic approach with incentive systems)","B":"Ủy ban chỉ tập trung vào quy tắc cứng","C":"Hội đồng chỉ tập trung vào tuân thủ pháp lý","D":"Ủy ban tập trung vào khung lý thuyết tĩnh"},"answerDisplay":"A. A systemic approach with incentive systems.","concept":"• Quản trị hệ thống (Systemic Governance) thưởng/phạt và khuyến khích nhân viên theo chuẩn mực giá trị giúp củng cố văn hóa đạo đức tự giác.","whyCorrect":"• Gắn cơ chế đãi ngộ khuyến khích với các giá trị đạo đức giúp thúc đẩy hành vi tích cực toàn tổ chức.","whyWrong":{"B":"• Chỉ tập trung quy tắc tạo ra tâm lý đối phó cứng nhắc.","C":"• Tuân thủ pháp lý chỉ là điều kiện sàn tối thiểu.","D":"• Khung lý thuyết tĩnh thiếu tính thực tiễn hành động."}}},{"id":36,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":36,"chooseType":"Choose 1 answer","question":"Which of the following are objectives of a forensic analysis? (Select two.)","options":{"A":"To inform stakeholders that an incident has occurred","B":"To determine what occurred in an incident","C":"To identify who or what is responsible for an incident","D":"To mitigate the effects of an incident"},"answer":"B, C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Những mục tiêu nào sau đây thuộc về Phân tích điều tra số (Forensic analysis)? (Select two)","optionsVi":{"A":"Thông báo cho các bên liên quan","B":"Xác định những gì đã xảy ra trong sự cố (To determine what occurred in an incident)","C":"Xác định ai hoặc yếu tố nào chịu trách nhiệm cho sự cố (To identify who or what is responsible)","D":"Giảm thiểu tác hại sự cố"},"answerDisplay":"B. To determine what occurred in an incident & C. To identify who or what is responsible for an incident","concept":"• Forensic Analysis (Điều tra pháp y kỹ thuật số) tập trung vào khôi phục bằng chứng để trả lời 2 câu hỏi: Chuyện gì đã xảy ra (What) và Ai chịu trách nhiệm (Who/Cause).","whyCorrect":"• Khôi phục diễn biến sự cố và tìm ra nguyên nhân/thủ phạm là mục đích chính của Forensic analysis.","whyWrong":{"A":"• Thông báo sự cố là công việc của Incident Response PR.","D":"• Giảm thiểu tác hại là công việc của Containment & Remediation team."}}},{"id":37,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":37,"chooseType":"Choose 1 answer","question":"Which of the following benefits can be gained from establishing baseline system behaviors? (Select two.)","options":{"A":"Tracking deviance from norms","B":"Optimizing costs of operation","C":"Restoring compromised functionality through a system rollback","D":"Holding employees more accountable"},"answer":"A, C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Những lợi ích nào sau đây có thể đạt được từ việc thiết lập các hành vi hệ thống cơ sở (Baseline system behaviors)? (Select two)","optionsVi":{"A":"Theo dõi và phát hiện sự sai lệch so với chuẩn mực vận hành (Tracking deviance from norms)","B":"Tối ưu hóa chi phí vận hành","C":"Khôi phục lại chức năng bị xâm nhập thông qua khôi phục hệ thống về trạng thái cơ sở (Restoring functionality through system rollback)","D":"Buộc nhân viên chịu trách nhiệm nhiều hơn"},"answerDisplay":"A. Tracking deviance from norms & C. Restoring compromised functionality through a system rollback","concept":"• Baseline Behavior: Giúp phát hiện nhanh các dấu hiệu bất thường (Deviance) và cung cấp điểm mốc an toàn để khôi phục (Rollback) khi bị tấn công.","whyCorrect":"• Phát hiện sai lệch bất thường và làm điểm mốc rollback khôi phục hệ thống là 2 lợi ích an ninh cốt lõi.","whyWrong":{"B":"• Tối ưu chi phí thuộc về FinOps.","D":"• Quản lý trách nhiệm nhân viên thuộc về quy trình nhân sự."}}},{"id":38,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":38,"chooseType":"Choose 1 answer","question":"Which of the following are typically true when comparing open source software to closed source software? (Select two.)","options":{"A":"Open source code is accessible for independent security auditing","B":"Closed source code is always free of bugs","C":"Open source software relies on community contribution for bug fixes and audit","D":"Closed source code guarantees 100% security"},"answer":"A, C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Những nhận định nào sau đây là đúng khi so sánh phần mềm mã nguồn mở (Open source) so với mã nguồn đóng (Closed source)? (Select two)","optionsVi":{"A":"Mã nguồn mở cho phép các kiểm toán viên an toàn thông tin độc lập truy cập đánh giá (Open source code is accessible for auditing)","B":"Mã nguồn đóng hoàn toàn không có lỗi","C":"Phần mềm mã nguồn mở dựa vào sự đóng góp của cộng đồng để sửa lỗi và kiểm toán (relies on community contribution)","D":"Mã nguồn đóng đảm bảo an toàn 100%"},"answerDisplay":"A. Open source code is accessible for independent security auditing & C. Open source software relies on community contribution","concept":"• So sánh Mã nguồn mở và Mã nguồn đóng: Mã nguồn mở minh bạch công khai cho phép cộng đồng kiểm toán lỗ hổng và đóng góp bản vá.","whyCorrect":"• Tính minh bạch cho kiểm toán độc lập và sự hỗ trợ sửa lỗi từ cộng đồng là 2 đặc trưng của Open Source.","whyWrong":{"B":"• Mọi phần mềm đều có rủi ro chứa bug.","D":"• Mã nguồn đóng không đảm bảo an toàn tuyệt đối."}}},{"id":39,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":39,"chooseType":"Choose 1 answer","question":"Which of the following elements might be considered moderately affected in an Impact Assessment?","options":{"A":"Loss of human life","B":"A brief delay in the conveyance of a commercial transaction","C":"Minor disruption to non-critical operations","D":"Severe health impairment"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Yếu tố nào sau đây có thể được coi là chịu tác động ở mức độ Vừa phải (Moderately affected) trong Đánh giá tác động?","optionsVi":{"A":"Mất mát sinh mạng con người (Tác động thảm họa - High/Critical)","B":"Một sự gián đoạn trì hoãn ngắn trong việc chuyển giao giao dịch thương mại (brief delay in commercial transaction)","C":"Tước đoạt nhân quyền (Tác động nghiêm trọng)","D":"Tổn hại sức khỏe nghiêm trọng (High impact)"},"answerDisplay":"B. A brief delay in the conveyance of a commercial transaction.","concept":"• Phân cấp Mức độ Tác động Rủi ro: High/Critical (Thiệt hại tính mạng/nhân quyền), Moderate (Trì hoãn ngắn giao dịch/ảnh hưởng nhỏ vận hành).","whyCorrect":"• Trì hoãn ngắn giao dịch thương mại thuộc phân cấp tác động vừa phải Moderate.","whyWrong":{"A":"• Thiệt hại sinh mạng là tác động Thảm họa (Critical/Severe).","C":"• Tước đoạt nhân quyền thuộc High Impact.","D":"• Tổn hại sức khỏe nghiêm trọng thuộc High Impact."}}},{"id":40,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":40,"chooseType":"Choose I answer","question":"Which of the following describes the AI Fairness 360 (AIF360) project?","options":{"A":"An open source Python toolkit developed by IBM that evaluates models for bias and provides mitigation algorithms","B":"A static checklist for ML practitioners","C":"A global conference initiative","D":"A benchmark dataset product"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả dự án AI Fairness 360 (AIF360)?","optionsVi":{"A":"Một thư viện mã nguồn mở do IBM phát triển giúp đánh giá thiên vị trong mô hình và cung cấp các thuật toán giảm thiểu thiên vị (open source library evaluating models and providing mitigation tactics)","B":"Bảng kiểm tra định dạng tĩnh","C":"Chiến dịch hội thảo toàn cầu","D":"Sản phẩm bộ dữ liệu chuẩn"},"answerDisplay":"A. An open source library that evaluates models for bias and provides mitigation tactics to reduce that bias.","concept":"• AI Fairness 360 (IBM AIF360): Bộ công cụ mã nguồn mở kiểm thử và giảm thiểu thiên vị cho các mô hình học máy.","whyCorrect":"• Định nghĩa chuẩn của bộ thư viện mở IBM AIF360 trong kiểm toán thiên vị.","whyWrong":{"B":"• AIF360 là bộ thư viện mã nguồn chứ không chỉ là danh sách kiểm tra.","C":"• Không phải sự kiện hội thảo.","D":"• Không phải là một sản phẩm mô hình cố định."}}},{"id":41,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":41,"chooseType":"Choose 1 answer","question":"Which of the following are desired qualities when choosing a spokesperson for your organization during a crisis? (Select two.)","options":{"A":"Articulate when communicating important details","B":"Patient and empathetic when addressing tough questions or concerns","C":"Lighthearted when dealing with serious topics","D":"Defensive when challenged"},"answer":"A, B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Những phẩm chất mong muốn nào sau đây khi lựa chọn một người phát ngôn (Spokesperson) cho tổ chức trong khủng hoảng? (Select two)","optionsVi":{"A":"Ăn nói rõ ràng mạch lạc khi truyền thông các chi tiết quan trọng (Articulate when communicating important details)","B":"Kiên nhẫn và thấu hiểu khi giải quyết các câu hỏi hoặc lo ngại hóc húa (Patient when addressing tough questions)","C":"Cợt nhả khi bàn về chủ đề nghiêm trọng","D":"Phản ứng phòng thủ gay gắt"},"answerDisplay":"A. Articulate when communicating important details & B. Patient when addressing tough questions or concerns","concept":"• Phẩm chất Người phát ngôn Truyền thông: Khả năng diễn đạt mạch lạc (Articulate) và Sự kiên nhẫn thấu hiểu (Patient & Empathetic).","whyCorrect":"• Diễn đạt mạch lạc và kiên nhẫn lắng nghe giúp xây dựng uy tín và xoa dịu căng thẳng khủng hoảng.","whyWrong":{"C":"• Thái độ cợt nhả gây phẫn nộ dư luận.","D":"• Thái độ phòng thủ gay gắt phá hủy lòng tin."}}},{"id":42,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":42,"chooseType":"Choose 1 answer","question":"Which of the following are effective strategies when making statements on social media? (Select two.)","options":{"A":"Being honest and up front","B":"Communicating only as needed","C":"Presenting a human face of the organization","D":"Focusing on positive feedback only"},"answer":"A, C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Những chiến lược nào sau đây là hiệu quả khi đưa ra các phát biểu trên mạng xã hội? (Select two)","optionsVi":{"A":"Trung thực và thẳng thắn ngay từ đầu (Being honest and up front)","B":"Chỉ truyền thông khi thật cần thiết","C":"Thể hiện diện mạo nhân văn/gần gũi của tổ chức (Presenting a face of the organization)","D":"Chỉ tập trung vào phản hồi tích cực"},"answerDisplay":"A. Being honest and up front & C. Presenting a face of the organization","concept":"• Truyền thông mạng xã hội thành công yêu cầu tính Trung thực (Authenticity) và sự Cầu thị nhân văn (Human Face) thay vì ngôn từ doanh nghiệp cứng nhắc.","whyCorrect":"• Bày tỏ thái độ trung thực và giao tiếp với diện mạo nhân văn xây dựng niềm tin với cộng đồng mạng.","whyWrong":{"B":"• Chỉ truyền thông khi cần khiến tổ chức bị coi là thiếu minh bạch.","D":"• Lờ đi phản hồi tiêu cực gây ra làn sóng tẩy chay dư luận."}}},{"id":43,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":43,"chooseType":"Choose 1 answer","question":"Which of the following describe important aspects in the role of an ethical AI engineer? (Select two.)","options":{"A":"Cleaning data and auditing models for bias","B":"Building and maintaining computational hardware","C":"Writing new equations for intelligence","D":"Keeping up with the latest developments, ethical frameworks, and vulnerabilities"},"answer":"A, D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Những khía cạnh nào sau đây mô tả đúng nhất vai trò của một Kỹ sư AI có trách nhiệm/đạo đức (Ethical AI Engineer)? (Select two)","optionsVi":{"A":"Làm sạch dữ liệu và kiểm toán mô hình để phát hiện thiên vị (Cleaning data and auditing for bias)","B":"Lắp ráp phần cứng máy tính","C":"Viết phương trình toán học mới","D":"Cập nhật liên tục các phát triển mới nhất, khung đạo đức và lỗ hổng an ninh (Keeping up with developments and vulnerabilities)"},"answerDisplay":"A. Cleaning and sorting data, and auditing for bias. & D. Keeping up with the latest developments and vulnerabilities.","concept":"• Vai trò Kỹ sư AI Đạo đức: Kiểm toán thiên vị dữ liệu (Auditing bias) và Liên tục cập nhật các rủi ro lỗ hổng mới (Vulnerabilities & Ethics frameworks).","whyCorrect":"• Kiểm toán thiên vị và cập nhật rủi ro lỗ hổng là hai nhiệm vụ kỹ thuật cốt lõi.","whyWrong":{"B":"• Lắp phần cứng là công việc kỹ thuật viên hạ tầng Data Center.","C":"• Viết phương trình toán là công việc nhà nghiên cứu lý thuyết."}}},{"id":44,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":44,"chooseType":"Choose 1 answer","question":"Which of the following describe corporate hegemony in tech markets? (Select two.)","options":{"A":"Consolidating market power through aggressive mergers and acquisitions","B":"Spending large sums on branding","C":"Making multiple investments","D":"Locking out smaller players and startups, leading to monopolies or cartels"},"answer":"A, D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Những nội dung nào sau đây mô tả sự Bá quyền Doanh nghiệp (Corporate hegemony) trong thị trường công nghệ? (Select two)","optionsVi":{"A":"Củng cố quyền lực thị trường thông qua thâu tóm và sáp nhập (Consolidating interests through M&A)","B":"Chi tiền tiếp thị thương hiệu","C":"Đầu tư đa dạng","D":"Khóa chặt rào cản ngăn các đối thủ nhỏ hơn tham gia, dẫn tới độc quyền hoặc nhóm tập đoàn thao túng (Locking out smaller players, leading to monopolies)"},"answerDisplay":"A. Consolidating interests through mergers and acquisitions & D. Locking out smaller players, leading to monopolies or cartels","concept":"• Corporate Hegemony (Thao túng bá quyền): Big Tech thâu tóm M&A các đối thủ tiềm năng và dựng rào cản ngăn doanh nghiệp nhỏ gia nhập thị trường.","whyCorrect":"• Thâu tóm M&A và triệt hạ đối thủ nhỏ là hai biểu hiện của Corporate Hegemony.","whyWrong":{"B":"• Chi tiền quảng cáo là hoạt động tiếp thị bình thường.","C":"• Đầu tư đa dạng là chiến lược rủi ro tài chính."}}},{"id":45,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":45,"chooseType":"Choose 1 answer","question":"Which of the following are requirements set forth by the Biometric Information Privacy Act (BIPA)? (Select two.)","options":{"A":"Organizations must not transmit biometric data over unsecured networks","B":"Organizations must obtain written consent from individuals prior to collecting biometric data","C":"Organizations must destroy biometric data in a timely fashion according to retention policy","D":"Organizations must store biometric data locally"},"answer":"B, C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Những yêu cầu nào sau đây do Đạo luật bảo vệ quyền riêng tư thông tin sinh trắc học (BIPA - Illinois) quy định? (Select two)","optionsVi":{"A":"Không truyền dữ liệu qua mạng","B":"Tổ chức phải nhận được sự đồng ý bằng văn bản từ cá nhân trước khi thu thập và sử dụng dữ liệu sinh trắc học (obtain consent regarding collection)","C":"Tổ chức phải hủy bỏ dữ liệu sinh trắc học đúng hạn định theo chính sách lưu trữ (destroy biometric data in a timely fashion)","D":"Bắt buộc lưu dữ liệu tại chỗ"},"answerDisplay":"B. Organizations must obtain consent from individuals regarding the collection and use of biometric data & C. Organizations must destroy biometric data in a timely fashion.","concept":"• BIPA (Biometric Information Privacy Act): Bắt buộc Xin phép đồng ý (Written Consent) và Xóa dữ liệu sinh trắc học đúng hạn (Timely Destruction).","whyCorrect":"• Xin sự đồng ý trước khi thu thập và hủy bỏ dữ liệu đúng hạn là 2 trụ cột bắt buộc của luật BIPA.","whyWrong":{"A":"• Mạng truyền tải được phép nếu có mã hóa TLS.","D":"• BIPA không cấm lưu trữ trên đám mây an toàn."}}},{"id":46,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":46,"chooseType":"Choose 1 answer","question":"An ethical impact assessment is:","options":{"A":"Focused on past ethical risks","B":"Focused on identifying and preventing future potential ethical problems (Forward-looking)","C":"Focused on identifying causes of past errors","D":"Focused on audit compliance"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Một Đánh giá Tác động Đạo đức (Ethical Impact Assessment - EIA) có đặc điểm trọng tâm là gì?","optionsVi":{"A":"Tập trung vào các rủi ro đạo đức trong quá khứ","B":"Tập trung vào việc nhận diện và phòng ngừa các vấn đề đạo đức tiềm tàng trong tương lai (Focused on preventing future problems)","C":"Tập trung tìm nguyên nhân lỗi quá khứ","D":"Tập trung vào tuân thủ kiểm toán"},"answerDisplay":"B. Focused on preventing future problems _","concept":"• Ethical Impact Assessment (EIA) là công cụ chủ động hướng về tương lai (Proactive / Forward-looking) giúp đánh giá tác động trước khi triển khai công nghệ.","whyCorrect":"• Chủ động nhận diện và triệt tiêu các nguy cơ sự cố đạo đức trước khi sản phẩm ra mắt.","whyWrong":{"A":"• Đánh giá sự cố quá khứ là Post-mortem audit.","C":"• Tìm nguyên nhân cũ là Root cause analysis.","D":"• Tuân thủ kiểm toán chỉ là một phần thủ tục."}}},{"id":47,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":47,"chooseType":"Choose 1 answer","question":"Which of the following describes the primary purpose of a SIEM system?","options":{"A":"To launch simulated attacks on networks","B":"To assign severity scores to software flaws","C":"To aggregate, correlate, and analyze alerts/logs from disparate security sources into a single analysis platform","D":"To protect confidentiality over a network"},"answer":"C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất mục đích chính của hệ thống SIEM?","optionsVi":{"A":"Tấn công giả lập hệ thống","B":"Chấm điểm lỗ hổng phần mềm","C":"Tổng hợp, tương quan và phân tích các cảnh báo/nhật ký từ nhiều nguồn an ninh khác nhau về một nền tảng quản lý tập trung (aggregate alerts from disparate sources into single platform)","D":"Mã hóa đường truyền mạng"},"answerDisplay":"C. To aggregate alerts from disparate sources into a single analysis platform.","concept":"• SIEM (Security Information and Event Management): Tập trung hóa logs và cảnh báo an ninh từ phòng tuyến mạng, máy chủ, ứng dụng để giám sát tổng thể.","whyCorrect":"• Gom và phân tích cảnh báo từ đa nguồn về một giao diện tập trung là nhiệm vụ chính của SIEM.","whyWrong":{"A":"• Tấn công giả lập là công cụ của Red Team.","B":"• Chấm điểm lỗ hổng là công cụ Vulnerability Scanner (CVSS).","D":"• Bảo vệ truyền tải là giao thức VPN/TLS."}}},{"id":48,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":48,"chooseType":"Choose 1 answer","question":"Which of the following constitute internal stakeholders in the context of a code of ethics?","options":{"A":"Regulators","B":"Designers and Developers","C":"Data subjects","D":"Policymakers"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nhóm đối tượng nào sau đây cấu thành các bên liên quan nội bộ (Internal Stakeholders) trong bối cảnh bộ quy tắc đạo đức?","optionsVi":{"A":"Cơ quan quản lý nhà nước (Regulators)","B":"Các nhà thiết kế và lập trình viên (Designers and Developers)","C":"Chủ thể dữ liệu (Data subjects)","D":"Các nhà hoạch định chính sách"},"answerDisplay":"B. Designers","concept":"• Internal Stakeholders bao gồm nhân viên, nhà thiết kế, lập trình viên, ban quản lý làm việc trực tiếp bên trong tổ chức.","whyCorrect":"• Lập trình viên và nhà thiết kế là nhân sự nội bộ trực tiếp tham gia xây dựng sản phẩm.","whyWrong":{"A":"• Regulators là bên liên quan bên ngoài.","C":"• Data subjects là bên ngoài bị tác động.","D":"• Policymakers là cơ quan chính phủ bên ngoài."}}},{"id":49,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":49,"chooseType":"Choose 1 answer","question":"If a coin is flipped as a randomized response mechanism in differential privacy, which setup ensures 'yes/no' survey data remains private while retaining statistical utility?","options":{"A":"Heads for yes, tails for no","B":"Heads for fake answer, tails for true answer","C":"Heads for true answer, tails for random answer (Randomized Response technique)","D":"Heads for random answer, tails for yes"},"answer":"C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nếu tung đồng xu làm cơ chế phản hồi ngẫu nhiên trong riêng tư vi sai, thiết lập nào đảm bảo câu trả lời khảo sát 'có/không' vừa riêng tư vừa giữ được giá trị thống kê?","optionsVi":{"A":"Ngửa là Có, Sấp là Không","B":"Ngửa trả lời giả, Sấp trả lời thật","C":"Nếu Ngửa thì trả lời thật, nếu Sấp thì trả lời ngẫu nhiên theo lần tung thứ hai (heads for true answer, tails for random answer)","D":"Ngửa trả lời ngẫu nhiên, Sấp là Có"},"answerDisplay":"C. heads for true answer, tails for random answer","concept":"• Kỹ thuật Phản hồi Ngẫu nhiên (Randomized Response in Differential Privacy): Thêm nhiễu ngẫu nhiên bằng cách tung đồng xu để che giấu câu trả lời thực tế của cá nhân nhưng giữ nguyên xác suất thống kê đám đông.","whyCorrect":"• Ngửa trả lời thật, sấp trả lời ngẫu nhiên là cơ chế chuẩn của Randomized Response.","whyWrong":{"A":"• Ngửa Có sấp Không lộ hoàn toàn câu trả lời.","B":"• Ngửa giả sấp thật không tạo ra nhiễu ngẫu nhiên toán học.","D":"• Thiết lập làm sai lệch xác suất thống kê."}}},{"id":50,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":50,"chooseType":"Choose 1 answer","question":"Which of the following is a benefit of using focus groups over surveys?","options":{"A":"They provide structured data","B":"They are more scalable","C":"They are an easier way to collect information","D":"They allow for deeper engagement and qualitative insights with the target demographic community"},"answer":"D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Lợi ích của việc sử dụng nhóm thảo luận tập trung (Focus groups) so với khảo sát đại chúng (Surveys) là gì?","optionsVi":{"A":"Cung cấp dữ liệu cấu trúc tốt hơn","B":"Mở rộng quy mô dễ hơn","C":"Dễ thu thập thông tin hơn","D":"Cho phép tương tác sâu sắc hơn và thu thập góc nhìn định tính từ cộng đồng dân cư mục tiêu (deeper engagement with target demographic)"},"answerDisplay":"D. They allow for deeper engagement with the target demographic community.","concept":"• Focus Groups tạo môi trường đối thoại mở định tính, giúp tìm hiểu sâu sắc động cơ và góc nhìn tâm lý của người tham gia.","whyCorrect":"• Thảo luận trực tiếp cho phép tương tác chiều sâu và làm rõ các chi tiết định tính mà khảo sát tích chọn bỏ sót.","whyWrong":{"A":"• Survey mới là công cụ cung cấp dữ liệu cấu trúc định lượng.","B":"• Survey mở rộng quy mô (scalable) tốt hơn focus group.","C":"• Survey dễ gửi hơn focus group."}}},{"id":51,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":51,"chooseType":"Choose 1 answer","question":"Which of the following cost functions or loss metrics is used to evaluate a linear regression machine learning model?","options":{"A":"Goodhart's Law","B":"Accuracy","C":"Cost function (Mean Squared Error - MSE)","D":"Receiver operating characteristic (ROC)"},"answer":"C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Chỉ số hoặc hàm tổn thất nào sau đây được sử dụng để đánh giá một mô hình học máy hồi quy tuyến tính (Linear Regression)?","optionsVi":{"A":"Định luật Goodhart","B":"Độ chính xác (Accuracy)","C":"Hàm chi phí / Hàm sai số (Cost function - MSE/RMSE)","D":"Đường cong đặc tính hoạt động của bộ thu (ROC)"},"answerDisplay":"C. Cost function","concept":"• Hàm Chi phí Hồi quy (Cost Function in Linear Regression): Sử dụng Sai số bình phương trung bình (MSE) làm hàm mất mát để đánh giá mức độ sai lệch khoảng cách.","whyCorrect":"• Hàm chi phí (Cost Function) đo lường sai số khoảng cách liên tục cho mô hình Hồi quy.","whyWrong":{"A":"• Định luật Goodhart là quy luật kinh tế xã hội.","B":"• Accuracy dùng cho bài toán Phân loại (Classification).","D":"• Đường cong ROC dùng đánh giá mô hình Phân loại nhị phân."}}},{"id":52,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":52,"chooseType":"Choose 1 answer","question":"Which of the following is a reason to engage in a comprehensive information gathering phase before drafting your internal and external ethics policies?","options":{"A":"It helps to unearth best practices and peer benchmarks in industry","B":"It provides examples of ethical pitfalls to avoid","C":"It helps to collect reaffirming evidence for beliefs","D":"It saves effort to copy policies"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Lý do nào sau đây giải thích việc cần tiến hành giai đoạn thu thập thông tin toàn diện trước khi dự thảo các chính sách đạo đức nội bộ và bên ngoài?","optionsVi":{"A":"Giúp phát hiện và khai quật các thực hành tốt nhất (best practices) và tiêu chuẩn từ các doanh nghiệp cùng ngành (unearth best practices from peers)","B":"Cung cấp cạm bẫy đạo đức","C":"Thu thập bằng chứng ủng hộ ý kiến cá nhân","D":"Tiết kiệm công sức bằng cách sao chép chính sách"},"answerDisplay":"A. It helps to unearth best practices from peers in the industry.","concept":"• Giai đoạn Thu thập Thông tin Tiền dự thảo (Information Gathering & Benchmarking): Tiếp thu các thông lệ đạo đức tốt nhất từ ngành để xây dựng bộ quy tắc khả thi.","whyCorrect":"• Khai quật các thực hành tốt nhất giúp bộ chính sách bắt kịp tiêu chuẩn tiên tiến của ngành.","whyWrong":{"B":"• Tránh cạm bẫy là lợi ích phụ.","C":"• Thu thập dữ liệu ủng hộ ý kiến cá nhân là Confirmation bias.","D":"• Sao chép là hành vi vô trách nhiệm bỏ qua tính đặc thù tổ chức."}}},{"id":53,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":53,"chooseType":"Choose 1 answer","question":"Why is suspicion a pitfall in communicating ethical risks to society?","options":{"A":"Suspicion involves fear of an emerging technology that is not completely understood, creating resistance","B":"Suspicion leads to aggressive rejection","C":"Suspicion makes it impossible to convince people of benefits","D":"Suspicion leads to ineffective tech use"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Tại sao sự nghi ngờ (Suspicion) lại là một bẫy rủi ro trong việc truyền thông các rủi ro đạo đức ra xã hội?","optionsVi":{"A":"Sự nghi ngờ bao hàm nỗi sợ hãi đối với công nghệ mới chưa được hiểu rõ hoàn toàn, tạo ra sự kháng cự tâm lý (fear of technology not completely known)","B":"Nghi ngờ dẫn tới từ chối hung hăng","C":"Nghi ngờ làm cho không thể thuyết phục","D":"Nghi ngờ làm dùng công nghệ kém hiệu quả"},"answerDisplay":"A. Suspicion involves fear of some technology that is not completely known.","concept":"• Tâm lý Nghi ngờ Công nghệ (Technological Suspicion): Nảy sinh từ sự thiếu thông tin minh bạch, dẫn tới tâm lý sợ hãi vô cớ và bài trừ công nghệ mới.","whyCorrect":"• Nỗi sợ từ sự thiếu thấu hiểu công nghệ tạo rào cản truyền thông rủi ro.","whyWrong":{"B":"• Không phải trường hợp nào nghi ngờ cũng dẫn tới hành vi hung hăng.","C":"• Minh bạch thông tin có thể hóa giải nghi ngờ.","D":"• Hiệu quả sử dụng là yếu tố kỹ thuật."}}},{"id":54,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":54,"chooseType":"Choose 1 answer","question":"Which of the following is NOT a common consideration when looking at the major AI ethical frameworks?","options":{"A":"Humanity and Beneficence","B":"Privacy","C":"Security and Robustness","D":"Monetization and Profit Maximization"},"answer":"D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Yếu tố nào sau đây KHÔNG PHẢI là một xem xét phổ biến trong các khung làm việc đạo đức AI chính yếu?","optionsVi":{"A":"Nhân tính (Humanity)","B":"Quyền riêng tư (Privacy)","C":"An ninh (Security)","D":"Tối đa hóa lợi nhuận và kiếm tiền (Monetization / Profit maximization)"},"answerDisplay":"D. Transparency Exam (hoặc Profit Maximization trong bản chuẩn)","concept":"• Các trụ cột Khung Đạo đức AI: Privacy, Transparency, Accountability, Fairness, Security, Humanity. Tối đa lợi nhuận thương mại không nằm trong trụ cột đạo đức.","whyCorrect":"• Kiếm tiền lợi nhuận thương mại là mục tiêu kinh doanh chứ không phải nguyên tắc đạo đức.","whyWrong":{"A":"• Humanity là trụ cột đạo đức tối cao.","B":"• Privacy là trụ cột cốt lõi.","C":"• Security là trụ cột kỹ thuật an toàn."}}},{"id":55,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":55,"chooseType":"Choose 2 answers","question":"Which of the following are important qualities of an effective press release? (Select two.)","options":{"A":"It's in a digital format","B":"It's non-interactive","C":"It's delivered on a single platform","D":"It's concise, clear, and newsworthy"},"answer":"A, D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Những đặc tính quan trọng nào sau đây thuộc về một Thông cáo báo chí (Press Release) hiệu quả? (Select two)","optionsVi":{"A":"Được phát hành dưới định dạng kỹ thuật số (digital format)","B":"Không có tính tương tác","C":"Phát hành trên một nền tảng duy nhất","D":"Ngắn gọn súc tích và có giá trị tin tức (concise and newsworthy)"},"answerDisplay":"A. It's in a digital format & D. It's concise","concept":"• Press Release Best Practices: Ngắn gọn súc tích (Concise), giàu giá trị tin tức (Newsworthy) và phát hành dưới dạng Kỹ thuật số (Digital Format) dễ lan tỏa.","whyCorrect":"• Định dạng kỹ thuật số và tính ngắn gọn súc tích là 2 tiêu chuẩn của thông cáo báo chí hiện đại.","whyWrong":{"B":"• Thông cáo hiện đại tích hợp đa phương tiện tương tác.","C":"• Nên phát hành trên đa nền tảng truyền thông."}}},{"id":56,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":56,"chooseType":"Choose 1 answer","question":"What are the core duties of an Ethics Board for data-driven technology organizations?","options":{"A":"Respond to rapid technological changes and investigate ethical implications","B":"Develop resources for ethical decision-making processes","C":"Build a repository of institutional knowledge around ethical practices","D":"All of the above"},"answer":"D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Nhiệm vụ cốt lõi của một Hội đồng Đạo đức đối với các tổ chức công nghệ dựa trên dữ liệu là gì?","optionsVi":{"A":"Phản ứng với các thay đổi công nghệ nhanh chóng và điều tra các hệ lụy đạo đức","B":"Phát triển các nguồn lực phục vụ quy trình ra quyết định đạo đức","C":"Xây dựng kho tri thức tổ chức về các thực hành đạo đức","D":"Tất cả các đáp án trên (All of the others)"},"answerDisplay":"D. All of the others","concept":"• Toàn diện vai trò Ethics Board: Giám sát rủi ro công nghệ mới, hỗ trợ ra quyết định đạo đức và lưu giữ kho tri thức quy trình cho doanh nghiệp.","whyCorrect":"• Cả 3 nhiệm vụ A, B, C hợp thành chức năng toàn diện của Hội đồng đạo đức.","whyWrong":{"A":"• Chỉ là một phần nhiệm vụ giám sát.","B":"• Chỉ là một phần nhiệm vụ hỗ trợ.","C":"• Chỉ là một phần nhiệm vụ quản trị tri thức."}}},{"id":57,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":57,"chooseType":"Choose 2 answers","question":"Which of the following are important to provide to a crisis communication team? (Select two.)","options":{"A":"Clear direction on the roles and responsibilities of team members","B":"Permission to tell public what they want to hear","C":"Ability to work independently","D":"Access to adequate resources and verified information"},"answer":"A, D","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Những yếu tố nào sau đây là quan trọng cần cung cấp cho đội ngũ truyền thông khủng hoảng? (Select two)","optionsVi":{"A":"Hướng dẫn rõ ràng về vai trò và trách nhiệm của từng thành viên (Clear direction on roles and responsibilities)","B":"Cho phép nói những gì công chúng muốn nghe","C":"Khả năng làm việc độc lập","D":"Quyền truy cập vào nguồn lực đầy đủ và thông tin xác thực (Access to adequate resources)"},"answerDisplay":"A. Clear direction on the roles and responsibilities of team members & D. Access to adequate resources","concept":"• Đội truyền thông khủng hoảng cần sự rõ ràng về phân công nhiệm vụ (Roles & Responsibilities) và được cung cấp đầy đủ hạ tầng/thông tin (Resources).","whyCorrect":"• Phân công vai trò chuẩn xác và cấp đủ tài nguyên giúp đội phản ứng nhanh chóng và nhất quán.","whyWrong":{"B":"• Nói những gì công chúng thích nghe mà thiếu sự thật là dối trá truyền thông.","C":"• Đội truyền thông phải phối hợp chặt chẽ với ban chỉ đạo khủng hoảng chứ không làm việc cô lập."}}},{"id":58,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":58,"chooseType":"Choose 1 answer","question":"Which of the following is an important reason to have a dedicated Policy Owner for internal and external ethics policies?","options":{"A":"They prevent changes from taking place over time","B":"The policy owner writes policy relying solely on personal knowledge","C":"They help bring the right internal and external stakeholders together to draft and update these ethics policies","D":"It helps to have a single scapegoat"},"answer":"C","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Lý do quan trọng của việc chỉ định một Chủ sở hữu Chính sách (Policy Owner) cho các chính sách đạo đức nội bộ và bên ngoài là gì?","optionsVi":{"A":"Họ ngăn cản sự thay đổi chính sách","B":"Chủ sở hữu tự viết chính sách dựa trên kiến thức cá nhân","C":"Họ giúp kết nối và quy tụ đúng các bên liên quan nội bộ và bên ngoài để cùng dự thảo và cập nhật chính sách (bring right stakeholders together)","D":"Để có người đổ lỗi"},"answerDisplay":"C. They can help to bring the right internal and external stakeholders together to help draft these ethics policies _","concept":"• Vai trò Policy Owner: Chủ trì kết nối hội họp các bên liên quan (Stakeholder Alignment) và duy trì sự cập nhật liên tục cho bộ chính sách.","whyCorrect":"• Quy tụ các bên liên quan để lấy ý kiến và cập nhật chính sách là trách nhiệm điều phối chính.","whyWrong":{"A":"• Chính sách cần liên tục được cập nhật.","B":"• Tự viết cá nhân gây ra góc nhìn chủ quan thiếu bao hàm.","D":"• Đổ lỗi không phải mục tiêu quản trị đạo đức."}}},{"id":59,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":59,"chooseType":"Choose 1 answer","question":"Which type of kurtosis in data distribution is most likely to indicate the strong presence of extreme outliers?","options":{"A":"Mesokurtic","B":"Leptokurtic (High peak and heavy tails)","C":"Platykurtic","D":"Repokurtic"},"answer":"B","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Loại độ nhọn (Kurtosis) nào trong phân bố dữ liệu có khả năng cao nhất chỉ ra sự xuất hiện mạnh mẽ của các điểm ngoại biệt cực đoan (outliers)?","optionsVi":{"A":"Mesokurtic (Độ nhọn chuẩn - Phân bố chuẩn)","B":"Leptokurtic (Độ nhọn cao, đuôi dày - Leptokurtic)","C":"Platykurtic (Độ nhọn dẹp)","D":"Repokurtic"},"answerDisplay":"B. Leptokurtic","concept":"• Leptokurtic Distribution (Kurtosis > 3): Đỉnh nhọn cao và hai đuôi dày (heavy tails), thể hiện xác suất xuất hiện các điểm cực đoan (outliers) rất lớn.","whyCorrect":"• Phân bố Leptokurtic có đuôi dày phản ánh sự hiện diện của các điểm dữ liệu ngoại biệt cực đoan.","whyWrong":{"A":"• Mesokurtic có độ nhọn bằng 3 của phân bố chuẩn.","C":"• Platykurtic có đỉnh phẳng và đuôi mỏng (ít outliers).","D":"• Repokurtic không phải thuật ngữ thống kê."}}},{"id":60,"task":"sp25_fe_re","taskLabel":"SP25 FE RE","num":60,"chooseType":"Choose 1 answer","question":"How is a culture-building workshop different from traditional ethics training?","options":{"A":"Culture-building workshops teach people how to integrate company values into daily practice, while ethics training teaches the company values","B":"Culture-building workshops teach company values, while ethics training teaches daily practice","C":"They are identical","D":"Workshops are strictly theoretical"},"answer":"A","source":"ITE302c_SP25_FE_RE","explanation":{"questionVi":"Hội thảo xây dựng văn hóa (Culture-building workshop) khác biệt như thế nào so với lớp tập huấn đạo đức (Ethics training) truyền thống?","optionsVi":{"A":"Hội thảo xây dựng văn hóa hướng dẫn mọi người cách tích hợp các giá trị của công ty vào thực hành hàng ngày, trong khi tập huấn đạo đức giảng dạy các giá trị của công ty (workshops teach integrating values into practice vs training teaches values)","B":"Hội thảo dạy giá trị, tập huấn dạy thực hành","C":"Cả hai giống hệt nhau","D":"Hội thảo mang tính lý thuyết thuần túy"},"answerDisplay":"A. Culture-building workshops teaches people how to integrate company values into daily practice, while ethics training teaches the company values.","concept":"• Culture Workshop vs Ethics Training: Training truyền tải quy tắc/giá trị (What), còn Workshop thực hành cách áp dụng quy tắc đó vào công việc hàng ngày (How to apply).","whyCorrect":"• Hướng dẫn ứng dụng thực tế giá trị vào hành vi hàng ngày là điểm khác biệt cốt lõi của Workshop.","whyWrong":{"B":"• Bị ngược vai trò giữa hai hình thức.","C":"• Hai hình thức có mục tiêu và phương pháp khác nhau.","D":"• Workshop có tính tương tác thực hành cao."}}},{"id":1,"task":"sp25_fe","taskLabel":"SP25 FE","num":1,"chooseType":"Choose 1 answer","question":"Which type of edge case is caused by data outside the normal distribution of a model's training set?","options":{"A":"Outlier edge case","B":"Systemic bias case","C":"Formatting error case","D":"Validation leak case"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Loại trường hợp ngoại lệ (edge case) nào được gây ra bởi dữ liệu nằm ngoài phân bố bình thường (normal distribution) của tập dữ liệu huấn luyện?","optionsVi":{"A":"Trường hợp ngoại lệ điểm ngoại biệt (Outlier edge case)","B":"Trường hợp thiên vị hệ thống","C":"Trường hợp lỗi định dạng","D":"Trường hợp rò rỉ kiểm chứng"},"answerDisplay":"A. Outlier edge case","concept":"• Outlier (Điểm ngoại biệt): Dữ liệu cực đoan xuất hiện ngoài dải phân bố thống kê tiêu chuẩn của mô hình.","whyCorrect":"• Dữ liệu nằm ngoài dải phân phối chuẩn tạo nên các tình huống ngoại lệ điểm ngoại biệt (Outliers).","whyWrong":{"B":"• Thiên vị hệ thống là lỗi lệch mẫu theo hướng cố định.","C":"• Lỗi định dạng do sai cú pháp dữ liệu.","D":"• Rò rỉ kiểm chứng là lỗi rò rỉ thông tin tập test sang tập train."}}},{"id":2,"task":"sp25_fe","taskLabel":"SP25 FE","num":2,"chooseType":"Choose 1 answer","question":"Which of the following types of malware monitors a user's behavior without their knowledge or consent?","options":{"A":"Adware","B":"Spyware","C":"Ransomware","D":"Trojan horse"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Loại phần mềm độc hại (Malware) nào lén lút theo dõi hành vi của người dùng mà không có sự biết đến hoặc đồng ý của họ?","optionsVi":{"A":"Phần mềm quảng cáo (Adware)","B":"Phần mềm gián điệp (Spyware)","C":"Mã độc tống tiền (Ransomware)","D":"Ngựa Trojan (Trojan horse)"},"answerDisplay":"B. Spyware","concept":"• Spyware (Phần mềm gián điệp): Ngầm thu thập bàn phím, mật khẩu, vị trí và hành vi duyệt web của người dùng để gửi về máy chủ kẻ tấn công.","whyCorrect":"• Định nghĩa kinh điển của Spyware là lén lút theo dõi hành vi người dùng.","whyWrong":{"A":"• Adware đẩy quảng cáo tự động.","C":"• Ransomware mã hóa tệp đòi tiền chuộc.","D":"• Trojan ẩn náu dưới dạng phần mềm hợp pháp để mở cổng hậu."}}},{"id":3,"task":"sp25_fe","taskLabel":"SP25 FE","num":3,"chooseType":"Choose 1 answer","question":"What kind of shape does a normal distribution take on when plotted in a histogram?","options":{"A":"Tail shape","B":"Square shape","C":"Bell shape","D":"Tree shape"},"answer":"C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Phân bố chuẩn (Normal distribution) có hình dạng như thế nào khi được biểu diễn trên biểu đồ cột (histogram)?","optionsVi":{"A":"Hình cái đuôi","B":"Hình vuông","C":"Hình quả chuông (Bell shape / Bell curve)","D":"Hình cây"},"answerDisplay":"C. Bell shape","concept":"• Phân bố Gaussian (Normal Distribution) có dạng hình quả chuông đối xứng qua giá trị trung bình (Mean).","whyCorrect":"• Hình quả chuông (Bell curve) là đặc trưng đồ thị đối xứng của phân bố chuẩn.","whyWrong":{"A":"• Hình cái đuôi là đặc trưng của phân bố lệch (Skewed distribution).","B":"• Hình vuông là phân bố đều (Uniform distribution).","D":"• Hình cây là sơ đồ cây quyết định (Decision tree)."}}},{"id":4,"task":"sp25_fe","taskLabel":"SP25 FE","num":4,"chooseType":"Choose 1 answer","question":"The principle of deleting unused or unnecessary data early and often during machine learning data pipeline is known as:","options":{"A":"Data minimization and data sanitization","B":"Data augmentation","C":"Data profiling","D":"Data duplication"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Nguyên tắc xóa dữ liệu không sử dụng hoặc không cần thiết sớm và thường xuyên trong đường ống dữ liệu học máy được gọi là gì?","optionsVi":{"A":"Giảm thiểu dữ liệu và làm sạch dữ liệu (Data minimization and data sanitization)","B":"Tăng cường dữ liệu (Data augmentation)","C":"Lập hồ sơ dữ liệu (Data profiling)","D":"Nhân bản dữ liệu (Data duplication)"},"answerDisplay":"A. Data minimization and data sanitization","concept":"• Data Minimization & Sanitization: Chủ động xóa bỏ thông tin thừa để hạ thấp nguy cơ lộ rò quyền riêng tư.","whyCorrect":"• Xóa dữ liệu thừa là cốt lõi của nguyên tắc Giảm thiểu dữ liệu.","whyWrong":{"B":"• Data augmentation là tạo thêm dữ liệu nhân tạo.","C":"• Data profiling là phân tích cấu trúc dữ liệu.","D":"• Data duplication làm tăng dung lượng rủi ro."}}},{"id":5,"task":"sp25_fe","taskLabel":"SP25 FE","num":5,"chooseType":"Choose 1 answer","question":"k-Anonymity in a dataset is achieved when each individual cannot be:","options":{"A":"Distinguished from at least k-1 other individuals in the dataset based on quasi-identifiers","B":"Reidentified in k datasets","C":"Hidden from quasi-identifier column as long as k individuals belong","D":"Harmed from datasets with k individuals"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Tính ẩn danh k-anonymity trong một tập dữ liệu đạt được khi mỗi cá nhân không thể bị:","optionsVi":{"A":"Phân biệt với ít nhất k-1 cá nhân khác trong cùng tập dữ liệu dựa trên các thuộc tính bán định danh (Distinguished from at least K individuals)","B":"Tái định danh trong k tập dữ liệu","C":"Che giấu khỏi cột bán định danh","D":"Tổn hại từ các tập dữ liệu chứa k cá nhân"},"answerDisplay":"A. distinguished from at least K individuals who are also in the dataset","concept":"• k-Anonymity Requirement: Mỗi nhóm thuộc tính bán định danh (Quasi-identifiers) phải xuất hiện ít nhất k lần.","whyCorrect":"• Định nghĩa chuẩn mực của k-anonymity là ẩn mình trong nhóm k cá nhân giống hệt thuộc tính.","whyWrong":{"B":"• k không phải số lượng tập dữ liệu.","C":"• Thuộc tính bán định danh bị làm mờ/tổng quát hóa.","D":"• Tổn hại không liên quan đến định nghĩa k-anonymity."}}},{"id":6,"task":"sp25_fe","taskLabel":"SP25 FE","num":6,"chooseType":"Choose 1 answer","question":"What does the acronym RACI stand for?","options":{"A":"Relatable, Agreeable, Commendable, Irascible","B":"Responsible, Accessible, Consulted, Improvised","C":"Redesignable, Accessible, Collected, Informative","D":"Responsible, Accountable, Consulted, Informed"},"answer":"D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Từ viết tắt RACI trong quản trị tổ chức và dự án đại diện cho điều gì?","optionsVi":{"A":"Relatable, Agreeable, Commendable, Irascible","B":"Responsible, Accessible, Consulted, Improvised","C":"Redesignable, Accessible, Collected, Informative","D":"Người thực thi (Responsible), Người chịu trách nhiệm (Accountable), Người tham vấn (Consulted), Người nhận thông tin (Informed)"},"answerDisplay":"D. Responsible, Accountable, Consulted, Informed","concept":"• Ma trận RACI: Responsible (thực hiện nhiệm vụ), Accountable (chịu trách nhiệm cuối cùng), Consulted (được tham vấn trước quyết định), Informed (được thông báo kết quả).","whyCorrect":"• Định nghĩa chính xác của mô hình phân công trách nhiệm RACI trong quản trị.","whyWrong":{"A":"• Đây là các tính từ tiếng Anh ngẫu nhiên.","B":"• Accessible và Improvised không phải thành tố RACI.","C":"• Redesignable và Collected không thuộc ma trận RACI."}}},{"id":7,"task":"sp25_fe","taskLabel":"SP25 FE","num":7,"chooseType":"Choose 1 answer","question":"Which of the following describes extrajudicial judgment?","options":{"A":"A ruling or scoring made outside of a court","B":"Transferring defendants from one jurisdiction to another","C":"Applying law from one jurisdiction within another","D":"Unusual interpretation of law"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả Phán quyết ngoài tư pháp (Extrajudicial judgment)?","optionsVi":{"A":"Một phán quyết hoặc chấm điểm rủi ro được thực hiện bên ngoài hệ thống tòa án chính thức (made outside of a court)","B":"Chuyển giao bị cáo giữa các thẩm quyền","C":"Áp dụng luật quốc tế","D":"Sửa đổi quy trình tòa án"},"answerDisplay":"A. A ruling or scoring made outside of a court","concept":"• Extrajudicial Judgment là việc các thuật toán hay thực thể tư nhân tự động đưa ra quyết định đánh giá/chấm điểm trừng phạt cá nhân mà không qua quy trình xét xử của tòa án.","whyCorrect":"• Quyết định hay chấm điểm đưa ra bên ngoài tòa án chính thức là bản chất của Extrajudicial judgment.","whyWrong":{"B":"• Chuyển bị cáo là Extradition.","C":"• Áp dụng luật quốc tế là International law application.","D":"• Sửa đổi quy trình là Judicial reform."}}},{"id":8,"task":"sp25_fe","taskLabel":"SP25 FE","num":8,"chooseType":"Choose 1 answer","question":"Which of the following risk categories deals with stakeholder responsibility in creating and using data-driven technologies?","options":{"A":"Explainability","B":"Accountability","C":"Transparency","D":"Understandability"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Danh mục rủi ro nào sau đây xử lý trách nhiệm của các bên liên quan trong việc tạo ra và sử dụng các công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Tính giải thích được (Explainability)","B":"Trách nhiệm giải trình (Accountability)","C":"Tính minh bạch (Transparency)","D":"Tính dễ hiểu (Understandability)"},"answerDisplay":"B. Accountability","concept":"• Trách nhiệm giải trình (Accountability) quy định nghĩa vụ của tổ chức/cá nhân trong việc gánh chịu trách nhiệm đối với các tác động của hệ thống AI.","whyCorrect":"• Định rõ ai chịu trách nhiệm cho các hậu quả của công nghệ là bản chất của Accountability.","whyWrong":{"A":"• Explainability là thuộc tính giải thích mô hình toán.","C":"• Transparency là công khai thông tin.","D":"• Understandability là khả năng tiếp thu thông điệp."}}},{"id":9,"task":"sp25_fe","taskLabel":"SP25 FE","num":9,"chooseType":"Choose 1 answer","question":"Which of the following best describes the use case for zero-knowledge protocols in cryptography?","options":{"A":"Choosing what to do when you have zero knowledge","B":"Notifying when battery is low","C":"Proving that a statement/data is true without revealing the underlying specific information itself","D":"Handling divide-by-zero errors"},"answer":"C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất trường hợp sử dụng của Giao thức không kiến thức (Zero-knowledge proof / protocol) trong mật mã học?","optionsVi":{"A":"Chọn việc cần làm khi không có kiến thức","B":"Cảnh báo khi hết pin","C":"Chứng minh rằng một khẳng định/dữ liệu là đúng mà không làm lộ bất kỳ thông tin chi tiết nào bên trong (Proving that something exists, but not the specifics)","D":"Xử lý lỗi chia cho số 0"},"answerDisplay":"C. Proving that something exists, but not the specifics","concept":"• Zero-Knowledge Proof (ZKP): Chứng minh sự thật (ví dụ: tôi biết mật khẩu, tôi đủ 18 tuổi) mà hoàn toàn không tiết lộ bản thân mật khẩu hay ngày sinh thực tế.","whyCorrect":"• Khả năng xác minh tính đúng đắn mà không lộ thông tin gốc là định nghĩa của Zero-Knowledge Proof.","whyWrong":{"A":"• Không phải là sự thiếu hiểu biết của con người.","B":"• Không liên quan đến quản lý năng lượng thiết bị.","D":"• Không liên quan đến phép chia số học."}}},{"id":10,"task":"sp25_fe","taskLabel":"SP25 FE","num":10,"chooseType":"Choose 1 answer","question":"When it comes to protecting private data, which of the following could be the root cause of a data breach?","options":{"A":"The data was stored insecurely without encryption","B":"The data was leaked online","C":"The data was deleted from storage","D":"The data was broken"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Khi nói về việc bảo vệ dữ liệu riêng tư, nội dung nào sau đây có thể là nguyên nhân gốc rễ (root cause) dẫn đến sự cố rò rỉ dữ liệu?","optionsVi":{"A":"Dữ liệu được lưu trữ không an toàn và thiếu mã hóa (stored insecurely)","B":"Dữ liệu bị rò rỉ trên mạng","C":"Dữ liệu bị xóa khỏi kho lưu trữ","D":"Dữ liệu bị hỏng"},"answerDisplay":"A. The data was stored insecurely.","concept":"• Root Cause vs Symptom: Lưu trữ dữ liệu không an toàn (Stored Insecurely) là nguyên nhân gốc rễ dẫn tới hậu quả rò rỉ (Leaked Online).","whyCorrect":"• Hạ tầng lưu trữ không an toàn là nguyên nhân gốc gây ra thảm họa lộ rò.","whyWrong":{"B":"• Rò rỉ ra mạng là triệu chứng/hậu quả chứ không phải nguyên nhân gốc rễ.","C":"• Xóa dữ liệu gây mất dữ liệu chứ không rò rỉ.","D":"• Dữ liệu bị hỏng là hư hỏng tệp."}}},{"id":11,"task":"sp25_fe","taskLabel":"SP25 FE","num":11,"chooseType":"Choose 1 answer","question":"Why is a model that has been overfitted to its training data a source of fairness risk?","options":{"A":"Because the model includes too much noise","B":"Because the model is too complex","C":"Because the model won't generalize fairly to the entire population","D":"Because the model has temporal bias"},"answer":"C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Tại sao một mô hình bị khớp quá mức (Overfitted) với dữ liệu huấn luyện lại là một nguồn rủi ro về tính công bằng?","optionsVi":{"A":"Vì mô hình chứa quá nhiều nhiễu","B":"Vì mô hình quá phức tạp","C":"Vì mô hình sẽ không thể tổng quát hóa một cách công bằng cho toàn bộ dân số thực tế (won't generalize to the entire population)","D":"Vì mô hình bị thiên vị thời gian"},"answerDisplay":"C. Because the model wont generalize to the entire population.","concept":"• Overfitting & Fairness: Mô hình học quá kỹ các nhiễu và định kiến của tập huấn luyện nhỏ nên sẽ đưa ra các dự đoán sai lệch bất công khi gặp dữ liệu thực tế mới.","whyCorrect":"• Mất khả năng tổng quát hóa chính xác cho đại chúng gây ra dự đoán thiên vị trên môi trường thực.","whyWrong":{"A":"• Học cả nhiễu là biểu hiện của overfitting.","B":"• Phức tạp là nguyên nhân kỹ thuật.","D":"• Temporal bias do dữ liệu lỗi thời."}}},{"id":12,"task":"sp25_fe","taskLabel":"SP25 FE","num":12,"chooseType":"Choose 1 answer","question":"How does the low likelihood of a crisis relate to its potential impact?","options":{"A":"A crisis with low likelihood tends to have moderate impact","B":"A crisis with low likelihood tends to have high impact (Black Swan events)","C":"A crisis with low likelihood has little to no effect on impact","D":"A crisis with low likelihood tends to have low impact"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Mối quan hệ giữa xác suất xảy ra thấp của một cuộc khủng hoảng và tác động tiềm tàng của nó là gì?","optionsVi":{"A":"Khủng hoảng có xác suất thấp thường có tác động vừa phải","B":"Một cuộc khủng hoảng có xác suất xảy ra thấp thường có tác động cực kỳ nghiêm trọng khi nó thực sự xảy ra (low likelihood tends to have high impact)","C":"Xác suất không ảnh hưởng tác động","D":"Khủng hoảng xác suất thấp có tác động thấp"},"answerDisplay":"B. A crisis with low likelihood tends to have high impact","concept":"• Sự kiện Thiên nga đen (Black Swan / High-Impact Low-Probability risks): Các sự cố cực hiếm gặp nhưng một khi xảy ra sẽ gây thảm họa tàn phá khủng khiếp.","whyCorrect":"• Các rủi ro hiếm gặp thường bị chủ quan bỏ qua nên khi bùng phát sẽ tạo ra tổn hại quy mô tối đa.","whyWrong":{"A":"• Không dừng ở mức vừa phải.","C":"• Hai chỉ số này liên kết chặt chẽ trong ma trận rủi ro.","D":"• Đánh giá tác động thấp cho sự cố hiếm gặp là sai lầm quản lý rủi ro."}}},{"id":13,"task":"sp25_fe","taskLabel":"SP25 FE","num":13,"chooseType":"Choose 1 answer","question":"How can you leverage emerging technologies like AI in disaster recovery plans (DRP)?","options":{"A":"By using data-driven techniques to inform and optimize strategies behind DRP","B":"By using NLP to correct typo errors","C":"By using deep learning to bolster defense against disasters","D":"By using AI to decide if DRP is necessary"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Làm thế nào bạn có thể tận dụng các công nghệ mới nổi như AI trong các kế hoạch khôi phục sau thảm họa (Disaster Recovery Plans - DRP)?","optionsVi":{"A":"Bằng cách sử dụng các kỹ thuật dựa trên dữ liệu để cung cấp thông tin và tối ưu hóa các chiến lược đằng sau DRP (using data-driven techniques to inform DRP strategies)","B":"Dùng NLP sửa lỗi chính tả","C":"Dùng học sâu ngăn thảm họa tự nhiên","D":"Dùng AI quyết định có cần DRP không"},"answerDisplay":"A. By using data-ciriven techniques to inform the strategies behind the DRP_","concept":"• AI-augmented Disaster Recovery: Sử dụng phân tích dự báo dữ liệu để mô phỏng kịch bản thảm họa và tối ưu hóa chiến lược khôi phục hạ tầng.","whyCorrect":"• Phân tích dữ liệu giúp hoạch định chiến lược khôi phục hạ tầng thông minh và hiệu quả hơn.","whyWrong":{"B":"• Sửa lỗi chính tả không có giá trị khôi phục thảm họa.","C":"• Học sâu không thể ngăn chặn trực tiếp thảm họa thiên nhiên.","D":"• DRP là yêu cầu bắt buộc tối thiểu đối với mọi doanh nghiệp."}}},{"id":14,"task":"sp25_fe","taskLabel":"SP25 FE","num":14,"chooseType":"Choose 1 answer","question":"Which of the following is the most important idea that a crisis communication strategy should focus on?","options":{"A":"The public's perception of a crisis","B":"The real-world impacts and physical safety effects of a crisis","C":"The individual details of a crisis","D":"Internal stakeholder consensus"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Nội dung quan trọng nhất mà một chiến lược truyền thông khủng hoảng cần tập trung giải quyết là gì?","optionsVi":{"A":"Nhận thức của công chúng về khủng hoảng","B":"Các tác động thực tế trong đời sống thực và sự an toàn của con người (real-world effects of a crisis)","C":"Các chi tiết đơn lẻ của khủng hoảng","D":"Sự đồng thuận của các bên nội bộ"},"answerDisplay":"B. The real-world effects ofa crisis","concept":"• Trọng tâm Truyền thông Khủng hoảng: Ưu tiên giải quyết tác hại thực tế (Real-world effects) và an toàn con người thay vì xử lý khủng hoảng truyền thông suông.","whyCorrect":"• Giải quyết các hậu quả đời thực và bảo vệ an toàn là nhiệm vụ hàng đầu trong khủng hoảng.","whyWrong":{"A":"• Nhận thức công chúng là hệ quả phụ.","C":"• Chi tiết đơn lẻ làm mất bức tranh toàn cảnh.","D":"• Đồng thuận nội bộ không thay thế được việc xử lý thiệt hại bên ngoài."}}},{"id":15,"task":"sp25_fe","taskLabel":"SP25 FE","num":15,"chooseType":"Choose 1 answer","question":"Which of the following is an adequate definition of a stakeholder?","options":{"A":"All internal employees only","B":"All internal employees and external customers","C":"All people who have an impact on or are impacted by the organization","D":"All people in the company"},"answer":"C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Nội dung nào sau đây là định nghĩa đầy đủ về Bên liên quan (Stakeholder)?","optionsVi":{"A":"Toàn bộ nhân viên nội bộ","B":"Toàn bộ nhân viên và khách hàng","C":"Tất cả những người có tác động hoặc chịu tác động bởi hoạt động của tổ chức (impact on or impacted by the organization)","D":"Toàn bộ người trong công ty"},"answerDisplay":"C. All people who have an impact or are impacted by the organization.","concept":"• Stakeholder (Bên liên quan) bao gồm bất kỳ cá nhân hay nhóm nào có thể gây ảnh hưởng hoặc chịu ảnh hưởng bởi các quyết định và sản phẩm của doanh nghiệp.","whyCorrect":"• Bao quát cả chiều tác động hai hướng (tác động đến tổ chức và chịu tác động từ tổ chức).","whyWrong":{"A":"• Chỉ nhân viên là định nghĩa hẹp Internal.","B":"• Bỏ qua cơ quan quản lý và cộng đồng.","D":"• Chỉ người trong công ty bỏ qua các thực thể bên ngoài."}}},{"id":16,"task":"sp25_fe","taskLabel":"SP25 FE","num":16,"chooseType":"Choose 1 answer","question":"When conducting a Business Impact Assessment (BIA), why is it important to interview operational staff?","options":{"A":"They are candid","B":"They may have more hands-on institutional knowledge about practical subject workflows than managers","C":"They find more time for surveys","D":"They have greater obligation to answer"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Khi tiến hành Đánh giá Tác động Kinh doanh (BIA), tại sao việc phỏng vấn trực tiếp nhân viên vận hành thực tế lại quan trọng?","optionsVi":{"A":"Họ thành thật","B":"Họ nắm giữ nhiều tri thức thực tế quy trình (institutional knowledge) về vận hành hơn các cấp quản lý (hands-on institutional knowledge)","C":"Họ rảnh rỗi hơn","D":"Họ bắt buộc trả lời"},"answerDisplay":"B. They may have more institutional knowledge about a subject than managers.","concept":"• Operational Staff (Nhân viên vận hành trực tiếp) thấu hiểu mọi rủi ro và nút thắt quy trình hàng ngày mà cấp quản lý chỉ nhìn thấy trên báo cáo.","whyCorrect":"• Tri thức vận hành thực tế giúp BIA đánh giá chính xác các lỗ hổng hệ thống.","whyWrong":{"A":"• Sự thành thật phụ thuộc cá nhân.","C":"• Nhân viên vận hành rất bận rộn.","D":"• Nghĩa vụ trả lời áp dụng chung."}}},{"id":17,"task":"sp25_fe","taskLabel":"SP25 FE","num":17,"chooseType":"Choose 1 answer","question":"What is the purpose of a holding statement in crisis and media communications?","options":{"A":"To order the business to temporarily halt operations","B":"To retain the services of specific media outlets","C":"To pre-write communications before they are needed","D":"To prevent personnel from communicating prematurely"},"answer":"D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Mục đích của một phát ngôn giữ chỗ (Holding Statement) trong truyền thông khủng hoảng là gì?","optionsVi":{"A":"Yêu cầu doanh nghiệp tạm dừng hoạt động","B":"Thuê dịch vụ của các cơ quan báo chí cụ thể","C":"Viết trước các văn bản truyền thông khi chưa cần đến","D":"Ngăn chặn nhân viên phát ngôn vội vàng/sớm khi chưa có đủ thông tin xác thực (prevent personnel from communicating prematurely)"},"answerDisplay":"D. To prevent personnel from communicating prematurely","concept":"• Holding Statement là thông cáo ban đầu giúp kiểm soát luồng thông tin, câu thời gian xác minh sự thật và ngăn phát ngôn vội vã.","whyCorrect":"• Tránh việc nhân viên tự ý đưa ra thông tin chưa kiểm chứng làm trầm trọng thêm khủng hoảng.","whyWrong":{"A":"• Holding statement là công cụ truyền thông, không phải lệnh dừng vận hành.","B":"• Không dùng để thuê hợp đồng báo chí.","C":"• Chuẩn bị kịch bản là crisis template, holding statement dùng để công bố tạm thời khi sự cố xảy ra."}}},{"id":18,"task":"sp25_fe","taskLabel":"SP25 FE","num":18,"chooseType":"Choose 1 answer","question":"In modern financial markets, what percentage of equity-futures and cash-equity trades are executed by automated algorithms?","options":{"A":"1-5%","B":"80-90%","C":"20-30%","D":"11-17%"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Trong thị trường tài chính hiện đại, tỷ lệ phần trăm các giao dịch hợp đồng tương lai cổ phiếu và cổ phiếu tiền mặt được thực hiện tự động bởi thuật toán là bao nhiêu?","optionsVi":{"A":"1-5%","B":"80-90% (Áp đảo thị trường)","C":"20-30%","D":"11-17%"},"answerDisplay":"B. 80-90%","concept":"• Algorithmic Trading Dominance: Khoảng 80-90% lượng giao dịch tài chính hiện đại được thực hiện tự động bởi các thuật toán High-Frequency Trading (HFT).","whyCorrect":"• Con số 80-90% phản ánh tỷ lệ giao dịch tự động hóa thuật toán áp đảo trong tài chính.","whyWrong":{"A":"• 1-5% quá nhỏ so với thực tế.","C":"• 20-30% phản ánh thời kỳ thập niên 2000.","D":"• 11-17% không chính xác."}}},{"id":19,"task":"sp25_fe","taskLabel":"SP25 FE","num":19,"chooseType":"Choose 1 answer","question":"How do anonymized datasets fall short of their goal of being anonymous?","options":{"A":"Anonymized datasets are deleted","B":"Anonymized datasets aren't actually anonymous because fields can identify users","C":"Anonymized datasets can be traced back by browsing history","D":"Anonymized datasets can be combined with other auxiliary datasets, which re-identifies individuals (Linkage attack)"},"answer":"D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Tại sao các tập dữ liệu được cho là đã ẩn danh vẫn thất bại trong việc đạt mục tiêu riêng tư của chúng?","optionsVi":{"A":"Dữ liệu bị xóa","B":"Trường dữ liệu có thể định danh","C":"Truy ngược qua lịch sử duyệt web","D":"Dữ liệu ẩn danh có thể bị liên kết kết hợp với các tập dữ liệu bên ngoài khác, từ đó tái định danh cá nhân (combined with other datasets, re-identify individuals)"},"answerDisplay":"D. Anonymized datasets can be combined with other datasets, which can re-identifry individuals","concept":"• Tấn công Liên kết (Linkage Attack): Kết hợp tập dữ liệu ẩn danh với tập dữ liệu công khai ngoài làm vô hiệu hóa giải pháp ẩn danh hóa sơ sài.","whyCorrect":"• Tái định danh danh tính qua liên kết tập dữ liệu phụ trợ bên ngoài là hạn chế cốt lõi.","whyWrong":{"A":"• Xóa dữ liệu không gây lộ rò.","B":"• Ẩn danh hóa đã xóa các trường định danh trực tiếp.","C":"• Lịch sử ứng dụng là một dạng dữ liệu riêng biệt."}}},{"id":20,"task":"sp25_fe","taskLabel":"SP25 FE","num":20,"chooseType":"Choose 1 answer","question":"Which of the following describes the black box problem in AI?","options":{"A":"It is difficult to understand data nature","B":"It is difficult to understand how or why an AI system made a particular decision","C":"It is difficult to understand results","D":"It is difficult to generate reports"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả bài toán Hộp đen (Black box problem) trong AI?","optionsVi":{"A":"Khó hiểu bản chất dữ liệu huấn luyện","B":"Rất khó để hiểu cách thức hoặc lý do tại sao hệ thống AI lại đưa ra một quyết định cụ thể (difficult to understand how or why AI made a decision)","C":"Khó hiểu kết quả đầu ra","D":"Khó tạo báo cáo"},"answerDisplay":"B. It is difficult to understand how or why an Al system made a particular decision.","concept":"• Black Box Problem xảy ra khi logic tính toán toán học bên trong của mô hình AI quá phức tạp khiến con người không thể giải thích lý do dẫn đến kết quả.","whyCorrect":"• Không thể giải thích lập luận ra quyết định bên trong của AI là bản chất của vấn đề Black Box.","whyWrong":{"A":"• Bản chất dữ liệu có thể kiểm tra qua Data Profiling.","C":"• Kết quả đầu ra hiển thị rõ ràng.","D":"• Báo cáo là công cụ xuất dữ liệu."}}},{"id":21,"task":"sp25_fe","taskLabel":"SP25 FE","num":21,"chooseType":"Choose 1 answer","question":"What is the black box problem?","options":{"A":"When a model is deployed, but researchers are unable to figure out why it's making specific decisions","B":"The problem created when researchers don't create accurate attributes","C":"The issue of not having enough data","D":"When a model cannot judge shape or color"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Bài toán Hộp đen (Black box problem) được phát biểu chính xác là gì?","optionsVi":{"A":"Khi một mô hình đã triển khai nhưng các nhà nghiên cứu không thể tìm ra lý do tại sao nó đưa ra các quyết định đó (unable to figure out why making decisions)","B":"Vấn đề khi không tạo đúng thuộc tính","C":"Vấn đề thiếu dữ liệu","D":"Khi mô hình không đoán được hình dạng màu sắc"},"answerDisplay":"A. When a model is deployed, but researchers are unable to figure out why it's making decisions","concept":"• Sự thiếu khả năng quan sát lập luận bên trong của thuật toán AI phức tạp.","whyCorrect":"• Không thể suy luận cách mô hình xử lý biến số dẫn đến đầu ra.","whyWrong":{"B":"• Thuộc tính sai gây thiên vị.","C":"• Thiếu dữ liệu gây underfitting.","D":"• Không đoán màu sắc là lỗi thị giác máy tính."}}},{"id":22,"task":"sp25_fe","taskLabel":"SP25 FE","num":22,"chooseType":"Choose 1 answer","question":"When building a predictive model, what is the goal of the development phase?","options":{"A":"To plug in 40% dataset","B":"To get the model's error function below an acceptable percentage threshold","C":"To specify algorithm and clean data","D":"To train continuously without stopping"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Khi xây dựng một mô hình dự đoán, mục tiêu của giai đoạn phát triển (Development phase) là gì?","optionsVi":{"A":"Nạp 40% dữ liệu","B":"Đưa hàm sai số (Error function) của mô hình xuống dưới mức ngưỡng chấp nhận được (get error function below acceptable percentage)","C":"Chỉ định thuật toán và làm sạch","D":"Huấn luyện liên tục không dừng"},"answerDisplay":"B. To get the model's error function below an acceptable percentage","concept":"• Tối ưu hóa trong phát triển ML: Điều chỉnh tham số để sai số tổn thất (Loss) giảm xuống mức tối thiểu chấp nhận được.","whyCorrect":"• Hạ hàm sai số xuống mức tối ưu chấp nhận được là tiêu chuẩn hoàn thành pha phát triển.","whyWrong":{"A":"• 40% là chỉ số chia dữ liệu.","C":"• Làm sạch là khâu tiền xử lý.","D":"• Huấn luyện không dừng gây overfitting."}}},{"id":23,"task":"sp25_fe","taskLabel":"SP25 FE","num":23,"chooseType":"Choose 1 answer","question":"What is the primary purpose of differential privacy?","options":{"A":"To enable parties to share private data without revealing individual identity in dataset","B":"To remove direct identifiers","C":"To only allow certain parties to access data","D":"To ensure data is completely confidential"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Mục đích chính của Tính riêng tư vi sai (Differential Privacy) là gì?","optionsVi":{"A":"Cho phép các bên chia sẻ và phân tích dữ liệu riêng tư mà không làm lộ danh tính của bất kỳ cá nhân nào có trong tập dữ liệu (share private data without revealing individuals)","B":"Loại bỏ định danh trực tiếp","C":"Phân quyền truy cập","D":"Bảo mật tuyệt đối"},"answerDisplay":"A. To enable parties to share private data without revealing individuals represented in the data.","concept":"• Differential Privacy thêm nhiễu toán học ngẫu nhiên vào dữ liệu để cho phép phân tích thống kê tổng thể mà triệt tiêu khả năng suy luận danh tính cá nhân.","whyCorrect":"• Giúp chia sẻ dữ liệu nghiên cứu an toàn mà không làm lộ dữ liệu cá thể.","whyWrong":{"B":"• Loại bỏ định danh trực tiếp là Anonymization đơn thuần.","C":"• Phân quyền truy cập là Access Control.","D":"• Bảo mật tuyệt đối là Encryption."}}},{"id":24,"task":"sp25_fe","taskLabel":"SP25 FE","num":24,"chooseType":"Choose 1 answer","question":"How is a Machine Learning (ML) system different from a Deep Learning (DL) system?","options":{"A":"A ML system learns from its mistakes","B":"A ML system does feature extraction automatically","C":"A ML system needs a human expert to perform manual feature extraction","D":"A ML system does not need input data"},"answer":"C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Hệ thống Học máy truyền thống (ML) khác biệt như thế nào so với hệ thống Học sâu (DL)?","optionsVi":{"A":"ML học từ sai lầm","B":"ML tự động trích xuất đặc trưng","C":"Mô hình ML truyền thống yêu cầu chuyên gia con người thực hiện trích xuất thuộc tính thủ công (requires human feature extraction)","D":"ML không cần dữ liệu đầu vào"},"answerDisplay":"C. A ML system needs a human to provide the feature extraction.","concept":"• Phân biệt ML và DL: ML truyền thống yêu cầu Feature Engineering thủ công từ con người; DL (Mạng nơ-ron sâu) tự động học Feature Extraction trực tiếp từ dữ liệu thô.","whyCorrect":"• Trích xuất thuộc tính thủ công bởi con người là hạn chế của ML truyền thống so với DL.","whyWrong":{"A":"• Cả ML và DL đều điều chỉnh trọng số dựa trên hàm lỗi.","B":"• Trích xuất thuộc tính tự động là ưu thế của DL.","D":"• Cả hai đều bắt buộc phải có dữ liệu đầu vào."}}},{"id":25,"task":"sp25_fe","taskLabel":"SP25 FE","num":25,"chooseType":"Choose 1 answer","question":"If your company needs to do the same automated analysis as new data comes in every month, what is the best term to describe that process?","options":{"A":"Pipeline (Data Pipeline)","B":"Workflow","C":"Swimlane","D":"Use case"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Nếu công ty bạn cần thực hiện cùng một quy trình phân tích tự động khi dữ liệu mới đổ về hàng tháng, thuật ngữ nào mô tả đúng nhất quy trình đó?","optionsVi":{"A":"Đường ống xử lý dữ liệu (Data Pipeline)","B":"Luồng công việc (Workflow)","C":"Làn bơi (Swimlane)","D":"Tình huống sử dụng (Use case)"},"answerDisplay":"A. pipeline","concept":"• Data Pipeline là chuỗi tự động hóa thu thập, biến đổi, làm sạch và phân tích dữ liệu lặp đi lặp lại theo định kỳ.","whyCorrect":"• Tự động hóa quy trình phân tích dữ liệu đầu vào định kỳ là bản chất của Data Pipeline.","whyWrong":{"B":"• Workflow là quy trình làm việc chung của con người.","C":"• Swimlane là sơ đồ phân công trách nhiệm.","D":"• Use case là kịch bản ứng dụng phần mềm."}}},{"id":26,"task":"sp25_fe","taskLabel":"SP25 FE","num":26,"chooseType":"Choose 1 answer","question":"Pseudocode can best be defined as:","options":{"A":"An explainable description of code that is meant for humans, not computers","B":"A Python library for machine learning","C":"A middle ground between code and plain writing that can be fed into a computer","D":"A type of Javascript"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Mã giả (Pseudocode) được định nghĩa đúng nhất là gì?","optionsVi":{"A":"Mô tả thuật toán có thể giải thích được dành cho con người đọc hiểu, không dùng để máy tính thực thi trực tiếp (meant for humans, not computers)","B":"Một thư viện Python cho học máy","C":"Ngôn ngữ máy tính","D":"Một loại Javascript"},"answerDisplay":"A. an explainable description of code that is meant for humans, not computers","concept":"• Pseudocode (Mã giả) mô tả logic thuật toán bằng ngôn ngữ tự nhiên kết hợp cấu trúc lập trình để con người dễ hiểu và thảo luận.","whyCorrect":"• Mã giả dành cho con người thấu hiểu logic mà không bị phụ thuộc vào cú pháp máy tính cụ thể.","whyWrong":{"B":"• Mã giả không phải thư viện mã nguồn.","C":"• Máy tính không thể biên dịch trực tiếp mã giả.","D":"• Mã giả không phải ngôn ngữ lập trình Javascript."}}},{"id":27,"task":"sp25_fe","taskLabel":"SP25 FE","num":27,"chooseType":"Choose 1 answer","question":"To measure a predictive model's accuracy, you:","options":{"A":"Divide the number of predictions by total dataset","B":"Measure ratio of error curve","C":"Multiply predictions by percentage","D":"Divide the number of correct predictions by the total number of predictions"},"answer":"D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Để đo lường độ chính xác (Accuracy) của một mô hình dự đoán, bạn thực hiện phép tính nào?","optionsVi":{"A":"Chia số dự đoán cho tổng tập dữ liệu","B":"Đo tỷ lệ đường cong lỗi","C":"Nhân tổng dự đoán với phần trăm đúng","D":"Chia số lượng dự đoán đúng cho tổng số lượng dự đoán (Divide correct predictions by total predictions)"},"answerDisplay":"D. divide the number of correct predictions by the total number of predictions","concept":"• Công thức tính Accuracy: Accuracy = (Số lượng dự đoán đúng) / (Tổng số lượng dự đoán).","whyCorrect":"• Phép chia số dự đoán đúng cho tổng số lần dự đoán ra tỷ lệ độ chính xác chuẩn mực.","whyWrong":{"A":"• Phép chia này không tính đến số dự đoán đúng.","B":"• Tỷ lệ đường cong lỗi đo Lực mất mát (Loss curve).","C":"• Phép nhân không ra công thức tính chỉ số Accuracy."}}},{"id":28,"task":"sp25_fe","taskLabel":"SP25 FE","num":28,"chooseType":"Choose 1 answer","question":"Which of the following is a good example of a feedback loop in machine learning?","options":{"A":"A shopping app surfaces items based on profiles; buying puts you into that dataset reinforcing future recommendations","B":"A shopping app tracks purchases","C":"A social media site surfaces posts you engage with, which goes back into the algorithm to show more similar posts","D":"A site surfaces controversial posts"},"answer":"C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Ví dụ nào sau đây là một minh họa rõ ràng về Vòng lặp phản hồi (Feedback loop) trong học máy?","optionsVi":{"A":"App mua sắm gợi ý món đồ","B":"App mua sắm theo dõi đơn hàng","C":"Trang mạng xã hội theo dõi tương tác, dùng thuật toán đẩy các bài viết bạn dễ tương tác, thông tin tương tác đó lại tiếp tục nạp ngược vào thuật toán (goes back into algorithm)","D":"Trang web gợi ý bài viết gây tranh cãi"},"answerDisplay":"C. A social media site tracks engagement, uses an algorithm to surface posts you're likely to engage with, which then goes back into the algorithm","concept":"• Machine Learning Feedback Loop: Dữ liệu hành vi đầu ra của mô hình trở thành dữ liệu huấn luyện đầu vào cho vòng lặp tiếp theo.","whyCorrect":"• Tương tác người dùng nạp ngược lại vào thuật toán để tiếp tục huấn luyện là bản chất của feedback loop.","whyWrong":{"A":"• Gợi ý cơ bản không có tính khuếch đại tự củng cố mạnh.","B":"• Theo dõi đơn thuần là ghi nhận dữ liệu tĩnh.","D":"• Bài viết tranh cãi là chiến lược nội dung."}}},{"id":29,"task":"sp25_fe","taskLabel":"SP25 FE","num":29,"chooseType":"Choose 1 answer","question":"Which of the following is one explanation for why cognitive biases exist in human reasoning?","options":{"A":"We use mental shortcuts (heuristics) to make decisions efficiently under information overload and limited time","B":"We use them to help remember things","C":"They help us think logically instead of emotionally","D":"They are taught to us in school"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Giải thích nào sau đây mô tả lý do tại sao Định kiến nhận thức (Cognitive biases) tồn tại trong lập luận của con người?","optionsVi":{"A":"Con người sử dụng các lối tắt tư duy (heuristics) để đưa ra quyết định nhanh chóng trong điều kiện quá tải thông tin và giới hạn thời gian (mental shortcuts for efficiency)","B":"Dùng để nhớ đồ vật","C":"Giúp tư duy logic thay vì cảm xúc","D":"Được dạy ở trường học"},"answerDisplay":"A. We use mental shortcuts to make decisions efficiently.","concept":"• Heuristics & Cognitive Biases: Não bộ dùng các lối tắt nhận thức để xử lý nhanh lượng thông tin khổng lồ, vô tình gây ra các sai lệch định kiến.","whyCorrect":"• Sử dụng lối tắt tư duy để ra quyết định nhanh là nguyên nhân gốc rễ sinh ra định kiến nhận thức.","whyWrong":{"B":"• Không phải công cụ lưu trữ trí nhớ.","C":"• Định kiến nhận thức đi ngược lại với logic thuần túy.","D":"• Đây là cơ chế tâm lý tự nhiên chứ không do trường học dạy."}}},{"id":30,"task":"sp25_fe","taskLabel":"SP25 FE","num":30,"chooseType":"Choose 1 answer","question":"Dating algorithms become biased mostly through offering users:","options":{"A":"Collaborative filtering that reinforces existing attraction stereotypes","B":"Access to separate data models","C":"Different ways to match with users","D":"Unlimited matches per day"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Các thuật toán hẹn hò trở nên bị thiên vị chủ yếu thông qua việc cung cấp cho người dùng tính năng gì?","optionsVi":{"A":"Lọc cộng tác (Collaborative filtering) củng cố các định kiến hấp dẫn sẵn có","B":"Truy cập các mô hình dữ liệu riêng","C":"Các cách ghép đôi khác nhau","D":"Không giới hạn lượt ghép đôi"},"answerDisplay":"A. collaborative filtering","concept":"• Lọc cộng tác (Collaborative Filtering) trong app hẹn hò gợi ý người dùng dựa trên hành vi của người dùng tương tự, vô tình tạo ra vòng lặp củng cố định kiến chủng tộc/ngoại hình.","whyCorrect":"• Lọc cộng tác nhân rộng và củng cố các định kiến xã hội vốn có trong dữ liệu quẹt thẻ.","whyWrong":{"B":"• Truy cập mô hình riêng là kiến trúc hệ thống.","C":"• Cách thức match là giao diện người dùng.","D":"• Lượt match không gây ra định kiến thiên vị nhóm."}}},{"id":31,"task":"sp25_fe","taskLabel":"SP25 FE","num":31,"chooseType":"Choose 1 answer","question":"How does the 'virtuous cycle' that benefits Big Tech operate?","options":{"A":"Organizations write algorithms with fewer biases","B":"By acting virtuous, the public respects Big Tech","C":"Better classes of customers lead to richer data","D":"Data-driven algorithms improve solutions, leading to new customers, and better data"},"answer":"D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Chu trình tăng trưởng độc quyền ('Virtuous Cycle') mang lại lợi ích cho các tập đoàn Big Tech vận hành như thế nào?","optionsVi":{"A":"Tổ chức viết thuật toán ít thiên vị dẫn tới kết quả công bằng hơn","B":"Hành động đạo đức giúp công chúng tôn trọng Big Tech hơn","C":"Khách hàng tốt mang lại dữ liệu phong phú hơn","D":"Thuật toán dựa trên dữ liệu cải thiện giải pháp -> Thu hút khách hàng mới -> Thu thập thêm dữ liệu tốt hơn (Data -> Product -> Users -> More Data)"},"answerDisplay":"D. Data-driven algorithms improve solutions, leading to new customers, and better data.","concept":"• Vòng lặp phản hồi dữ liệu (Data Flywheel Effect): Càng nhiều dữ liệu -> Thuật toán càng thông minh -> Sản phẩm càng tốt -> Thu hút thêm người dùng -> Lại có thêm dữ liệu độc quyền.","whyCorrect":"• Chu trình tự củng cố giữa dữ liệu, chất lượng sản phẩm và lượng người dùng tạo nên lợi thế độc quyền cho Big Tech.","whyWrong":{"A":"• Viết thuật toán ít thiên vị là mục tiêu đạo đức.","B":"• Công chúng tôn trọng là hiệu ứng thương hiệu.","C":"• Khách hàng giàu không phải nguyên nhân cốt lõi của chu trình."}}},{"id":32,"task":"sp25_fe","taskLabel":"SP25 FE","num":32,"chooseType":"Choose 1 answer","question":"A model that equalizes the number of mistakes it makes for each subgroup to reduce harm is deciding on:","options":{"A":"Equality of true outcomes","B":"Equality of false negatives","C":"Equality of training data","D":"Equality of prediction bias"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Một mô hình cân bằng số lượng sai sót mà nó mắc phải cho mỗi nhóm nhỏ để giảm thiểu tổn hại là đang quyết định về tiêu chuẩn nào?","optionsVi":{"A":"Bình đẳng kết quả thực tế","B":"Bình đẳng âm tính giả (Equality of false negatives)","C":"Bình đẳng dữ liệu huấn luyện","D":"Bình đẳng thiên vị dự đoán"},"answerDisplay":"B. equality of false negatives","concept":"• Equality of False Negatives đảm bảo tỷ lệ bỏ sót sai sót gây hại đạt mức ngang nhau giữa tất cả các phân nhóm xã hội.","whyCorrect":"• Cân bằng tỷ lệ Âm tính giả giữa các nhóm đảm bảo rủi ro bỏ sót tổn hại không bị dồn lên một nhóm yếu thế cụ thể.","whyWrong":{"A":"• Bình đẳng kết quả là Equalized Odds tổng thể.","C":"• Dữ liệu huấn luyện là phân phối mẫu đầu vào.","D":"• Thiên vị dự đoán là chỉ số đo lường độ lệch chung."}}},{"id":33,"task":"sp25_fe","taskLabel":"SP25 FE","num":33,"chooseType":"Choose 1 answer","question":"Which school of philosophical thought primarily advocates for a global moral code based on duty?","options":{"A":"Utilitarianism","B":"Deontology","C":"Virtue ethics","D":"Relativism"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Trường phái tư tưởng triết học nào chủ yếu cổ vũ cho một bộ quy tắc đạo đức toàn cầu có tính nghĩa vụ tuyệt đối?","optionsVi":{"A":"Thuyết vị lợi (Utilitarianism)","B":"Thuyết nghĩa vụ luận (Deontology)","C":"Thuyết đạo đức đức hạnh (Virtue ethics)","D":"Thuyết tương đối đạo đức"},"answerDisplay":"B. Deontology","concept":"• Deontology (Thuyết nghĩa vụ luận của Immanuel Kant) cho rằng các quy tắc đạo đức là những mệnh lệnh tuyệt đối (Categorical Imperatives) áp dụng phổ quát cho toàn nhân loại.","whyCorrect":"• Nghĩa vụ luận đòi hỏi tuân thủ các quy tắc đạo đức tuyệt đối không thay đổi theo hoàn cảnh.","whyWrong":{"A":"• Utilitarianism đánh giá đạo đức dựa trên kết quả/hậu quả.","C":"• Virtue ethics tập trung vào phẩm chất và đức hạnh cá nhân.","D":"• Relativism cho rằng đạo đức thay đổi theo văn hóa."}}},{"id":34,"task":"sp25_fe","taskLabel":"SP25 FE","num":34,"chooseType":"Choose 1 answer","question":"As a cognitive bias, when humans see a lack of context or meaning around a piece of information, they tend to:","options":{"A":"Fill in details using existing stereotypes or prior assumptions","B":"Use biased sources of research","C":"Seek authority figures","D":"Disagree with previous beliefs"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Dưới góc độ định kiến nhận thức, khi con người thấy sự thiếu hụt bối cảnh hoặc ý nghĩa xung quanh một mảnh thông tin, họ có xu hướng:","optionsVi":{"A":"Tự lấp đầy các chi tiết còn thiếu bằng cách dựa vào các định kiến có sẵn hoặc giả định trước đó (fill in details using stereotypes)","B":"Dùng nguồn nghiên cứu thiên vị","C":"Tìm kiếm nhân vật có thẩm quyền","D":"Bác bỏ niềm tin cũ"},"answerDisplay":"A. fill in details using existing stereotypes or prior assumptions","concept":"• Biến dạng nhận thức do thiếu bối cảnh (Filling in gaps): Trí não tự động suy đoán bổ sung phần thông tin thiếu bằng các định kiến xã hội vốn có.","whyCorrect":"• Tự điền chi tiết trống bằng định kiến có sẵn là phản ứng tâm lý nhận thức phổ biến.","whyWrong":{"B":"• Tìm nguồn thiên vị là hậu quả của Confirmation bias.","C":"• Tìm người thẩm quyền là Authority bias.","D":"• Bác bỏ niềm tin cũ đi ngược lại phản ứng nhận thức tự nhiên."}}},{"id":35,"task":"sp25_fe","taskLabel":"SP25 FE","num":35,"chooseType":"Choose 1 answer","question":"What is non-maleficence?","options":{"A":"The principle of doing no harm","B":"The principle of having no bias","C":"The principle of having no security risk","D":"The principle of maximizing profits"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Khái niệm Không gây hại (Non-maleficence) được định nghĩa là gì?","optionsVi":{"A":"Nguyên tắc không gây ra tổn hại cho con người và xã hội (The principle of doing no harm)","B":"Nguyên tắc không có thiên vị","C":"Nguyên tắc không có rủi ro an ninh","D":"Nguyên tắc tối đa hóa lợi nhuận"},"answerDisplay":"A. The principle of doing no harm.","concept":"• Non-maleficence (Primum non nocere - Trước tiên là không gây hại) là quy tắc đạo đức cơ bản yêu cầu hệ thống công nghệ không được gây ra thiệt hại cho người dùng.","whyCorrect":"• Định nghĩa kinh điển của nguyên tắc Non-maleficence là 'Do no harm'.","whyWrong":{"B":"• Không thiên vị là Fairness.","C":"• Không có rủi ro an ninh là Security/Robustness.","D":"• Tối đa lợi nhuận là Commercial goal."}}},{"id":36,"task":"sp25_fe","taskLabel":"SP25 FE","num":36,"chooseType":"Choose 1 answer","question":"In AI ethics frameworks, the principle of privacy is most commonly paired or referred to alongside:","options":{"A":"Data protection and confidentiality","B":"Security and speed","C":"Accuracy and performance","D":"Profitability and scale"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Trong các khung đạo đức AI, nguyên tắc quyền riêng tư (Privacy) thường đi kèm hoặc được đề cập song hành cùng với:","optionsVi":{"A":"Bảo vệ dữ liệu và tính bảo mật (Data protection and confidentiality)","B":"An ninh và tốc độ","C":"Độ chính xác và hiệu suất","D":"Lợi nhuận và quy mô"},"answerDisplay":"A. Data protection and confidentiality","concept":"• Privacy & Data Protection: Quyền riêng tư luôn được đảm bảo thông qua các cơ chế Bảo vệ dữ liệu (Data Protection) và Giữ bảo mật (Confidentiality).","whyCorrect":"• Bảo vệ dữ liệu và tính bảo mật là bộ đôi đi kèm tự nhiên với quyền riêng tư.","whyWrong":{"B":"• Tốc độ là tiêu chuẩn kỹ thuật.","C":"• Hiệu suất là tiêu chuẩn tối ưu hóa toán.","D":"• Lợi nhuận là tiêu chí tài chính."}}},{"id":37,"task":"sp25_fe","taskLabel":"SP25 FE","num":37,"chooseType":"Choose 1 answer","question":"A goal of a fair model's accuracy standards is to:","options":{"A":"Minimize the error rate as long as parity is obtained","B":"Minimize fairness score","C":"Minimize quality metrics","D":"Minimize training data size"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Mục tiêu về tiêu chuẩn độ chính xác của một mô hình công bằng là gì?","optionsVi":{"A":"Tối thiểu hóa tỷ lệ lỗi (Error rate) chừng nào tính bình đẳng/ngang bằng (Parity) giữa các nhóm vẫn được đảm bảo (minimize error rate as long as parity is obtained)","B":"Tối thiểu hóa điểm công bằng","C":"Tối thiểu hóa chỉ số chất lượng","D":"Tối thiểu hóa kích thước tập dữ liệu"},"answerDisplay":"A. minimize the error rate as long as parity is obtained","concept":"• Fairness-Constrained Accuracy Optimization: Đạt được độ chính xác tối đa (lỗi thấp nhất) trong phạm vi ràng buộc công bằng giữa các nhóm.","whyCorrect":"• Giảm thiểu sai số nhưng bắt buộc duy trì sự bình đẳng chỉ số giữa các nhóm.","whyWrong":{"B":"• Mục tiêu là tối đa hóa tính công bằng.","C":"• Chất lượng mô hình cần được tối ưu nâng cao.","D":"• Kích thước tập dữ liệu phụ thuộc vào bài toán."}}},{"id":38,"task":"sp25_fe","taskLabel":"SP25 FE","num":38,"chooseType":"Choose 1 answer","question":"Why are environmental concerns important to consider in the ethical development of data-driven technologies?","options":{"A":"Data-driven technologies can cause secondary, indirect, or cumulative effects on the environment that might impact people in the long term.","B":"Data-driven technologies directly impact the environment through invasive mining.","C":"Data-driven technologies directly impact environment through pollution.","D":"Data-driven technologies directly impact living things via displacement."},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Tại sao các mối quan ngại về môi trường lại quan trọng cần xem xét trong việc phát triển đạo đức các công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Các công nghệ dựa trên dữ liệu có thể gây ra các tác động thứ cấp, gián tiếp hoặc tích tụ lên môi trường, ảnh hưởng dài hạn tới con người (secondary, indirect, or cumulative effects)","B":"Tác động trực tiếp qua khai thác khoáng sản","C":"Tác động trực tiếp qua ô nhiễm","D":"Tác động trực tiếp gây di dời sinh vật"},"answerDisplay":"A. Data-driven technologies can cause secondary, indirect, or cumulative effects on the environment that might impact people in the long term.","concept":"• Các trung tâm dữ liệu AI tiêu thụ năng lượng khổng lồ và thải lượng khí thải carbon tích tụ (Cumulative Impact), đe dọa môi trường sống dài hạn.","whyCorrect":"• Tác động tích tụ và gián tiếp đến môi trường ảnh hưởng trực tiếp đến sự phát triển bền vững của nhân loại.","whyWrong":{"B":"• Khai thác khoáng sản là chuỗi cung ứng phần cứng.","C":"• Ô nhiễm trực tiếp là rác thải điện tử.","D":"• Di dời sinh vật là tác động sinh thái xây dựng."}}},{"id":39,"task":"sp25_fe","taskLabel":"SP25 FE","num":39,"chooseType":"Choose 1 answer","question":"How could a board of ethics be an example of ethics washing?","options":{"A":"If it has a wide variety of stakeholders","B":"If it has a narrow list of values to guide decisions","C":"If it has no power to institute change or enforce compliance","D":"If it has a large number of stakeholders"},"answer":"C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Làm thế nào một Hội đồng Đạo đức có thể trở thành một ví dụ về 'Ethics Washing' (Tẩy trắng đạo đức)?","optionsVi":{"A":"Nếu hội đồng có nhiều bên liên quan","B":"Nếu hội đồng có danh sách giá trị hẹp","C":"Nếu hội đồng không có thực quyền để thực thi thay đổi hoặc cưỡng chế tuân thủ (has no power to institute change)","D":"Nếu hội đồng có đông thành viên"},"answerDisplay":"C. If it has no power to institute change.","concept":"• Ethics Washing là việc lập ra các hội đồng hình thức để quảng bá hình ảnh nhưng tước bỏ quyền hạn thực thi quyết định của hội đồng đó.","whyCorrect":"• Thành lập hội đồng bề nổi nhưng không cho thực quyền thay đổi là hình thức Ethics Washing điển hình.","whyWrong":{"A":"• Đa dạng bên liên quan là tính chất tích cực.","B":"• Danh sách giá trị hẹp là vấn đề phạm vi.","D":"• Đông thành viên không quyết định việc tẩy trắng."}}},{"id":40,"task":"sp25_fe","taskLabel":"SP25 FE","num":40,"chooseType":"Choose 1 answer","question":"What does a leadership champion do in terms of organizational ethics?","options":{"A":"Makes decisions based on company values even in the face of adversity","B":"Makes decisions based on personal opinions","C":"Makes decisions based on popularity","D":"Makes decisions based on brand name"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Một thủ lĩnh tiên phong (Leadership champion) đóng vai trò gì trong đạo đức tổ chức?","optionsVi":{"A":"Đưa ra các quyết định dựa trên các giá trị của công ty ngay cả khi phải đối mặt với nghịch cảnh (Make decisions based on company values even in adversity)","B":"Ra quyết định dựa trên ý kiến cá nhân","C":"Ra quyết định dựa trên sự nổi tiếng","D":"Ra quyết định dựa trên tên thương hiệu"},"answerDisplay":"A. Make decisions based on company values even in the face of adversity.","concept":"• Leadership Champion: Người lãnh đạo kiên định bảo vệ và thực thi các giá trị đạo đức cốt lõi của công ty ngay cả khi chịu áp lực lợi nhuận hay nghịch cảnh.","whyCorrect":"• Kiên định bảo vệ giá trị tổ chức trong hoàn cảnh khó khăn là phẩm chất của Leadership Champion.","whyWrong":{"B":"• Ý kiến cá nhân mang tính chủ quan.","C":"• Sự nổi tiếng là chỉ số bề nổi.","D":"• Tên thương hiệu là tài sản tiếp thị."}}},{"id":41,"task":"sp25_fe","taskLabel":"SP25 FE","num":41,"chooseType":"Choose 1 answer","question":"Which of the following describes the purpose of having an Ethics Board for a data-driven organization?","options":{"A":"An Ethics Board can help maintain an organization's values-based intentions and increase transparency into how they use data-driven technologies","B":"An Ethics Board can help maintain profit margins","C":"An Ethics Board decreases inherent dangers of autonomous technologies","D":"An Ethics Board focuses only on internal employee disputes"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng mục đích của việc thành lập Hội đồng Đạo đức (Ethics Board) cho một tổ chức dựa trên dữ liệu?","optionsVi":{"A":"Hội đồng Đạo đức giúp duy trì các định hướng dựa trên giá trị của tổ chức và tăng cường tính minh bạch trong việc sử dụng công nghệ dựa trên dữ liệu (maintain values-based intentions and increase transparency)","B":"Duy trì biên lợi nhuận","C":"Giảm nguy cơ tự động","D":"Chỉ giải quyết tranh chấp nội bộ"},"answerDisplay":"A. An Ethics Board can help maintain an organization's values-based intentions and increase transparency into how they use data-driven technologies _","concept":"• Hội đồng Đạo đức (Ethics Board) giữ vai trò định hướng giá trị đạo đức và giám sát minh bạch quy trình sử dụng AI trong tổ chức.","whyCorrect":"• Định hướng giá trị cốt lõi và đảm bảo minh bạch là hai nhiệm vụ quan trọng nhất của Ethics Board.","whyWrong":{"B":"• Biên lợi nhuận thuộc về Hội đồng quản trị kinh doanh.","C":"• Giảm nguy cơ tự động là công việc kỹ thuật.","D":"• Tranh chấp nội bộ thuộc về phòng Nhân sự HR."}}},{"id":42,"task":"sp25_fe","taskLabel":"SP25 FE","num":42,"chooseType":"Choose 1 answer","question":"Which of the following is a key element of communications with internal and external stakeholders regarding an organization's ethics policies?","options":{"A":"Simple to follow examples and clear guidelines","B":"Daily communications","C":"Dense procedural descriptions","D":"Flexible verbiage"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Yếu tố cốt lõi trong truyền thông với các bên liên quan về chính sách đạo đức của tổ chức là gì?","optionsVi":{"A":"Ví dụ đơn giản dễ làm theo và hướng dẫn rõ ràng (Simple to follow examples)","B":"Truyền thông hàng ngày","C":"Mô tả quy trình dày đặc phức tạp","D":"Ngôn từ mập mờ linh hoạt"},"answerDisplay":"A. Simple to follow examples","concept":"• Truyền thông chính sách đạo đức cần ưu tiên tính Đơn giản (Simplicity) và Dễ hiểu để mọi đối tượng đều có thể tiếp thu và tuân thủ.","whyCorrect":"• Tính đơn giản dễ hiểu đảm bảo chính sách thực sự được phổ cập và áp dụng hiệu quả.","whyWrong":{"B":"• Truyền thông hàng ngày gây quá tải thông tin.","C":"• Mô tả quá dày đặc gây cản trở việc đọc và hiểu.","D":"• Ngôn từ mập mờ tạo ra các khe hở vi phạm."}}},{"id":43,"task":"sp25_fe","taskLabel":"SP25 FE","num":43,"chooseType":"Choose 1 answer","question":"Which of the following describes change management in the context of organizational ethics?","options":{"A":"A collective term used to describe how employees voice concerns","B":"A collective term for all approaches to prepare, support, and help individuals, teams, and organizations in fostering an ethical organizational culture","C":"A collective term for product modifications after negative feedback","D":"A process to replace executive board members"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả Quản lý sự thay đổi (Change management) trong bối cảnh đạo đức tổ chức?","optionsVi":{"A":"Thuật ngữ mô tả cách nhân viên lên tiếng","B":"Thuật ngữ chung cho tất cả các phương pháp nhằm chuẩn bị, hỗ trợ và giúp đỡ cá nhân, đội ngũ và tổ chức thực hiện sự chuyển đổi sang văn hóa đạo đức (approaches to prepare, support, help in making organizational change)","C":"Sửa đổi sản phẩm sau phản hồi tiêu cực","D":"Quy trình thay thế ban điều hành"},"answerDisplay":"B. A collective term for all approaches to prepare, support, and help individuals, teams, and organizations in fostering an ethical organizational culture.","concept":"• Change Management: Quy trình quản trị chuyển đổi hành vi, tư duy và cấu trúc tổ chức hướng tới các chuẩn mực văn hóa đạo đức mới.","whyCorrect":"• Hỗ trợ toàn diện cá nhân và tập thể thích nghi với sự thay đổi văn hóa tổ chức.","whyWrong":{"A":"• Lên tiếng là Employee Voice.","C":"• Sửa sản phẩm là Product Iteration.","D":"• Thay ban điều hành là Executive succession planning."}}},{"id":44,"task":"sp25_fe","taskLabel":"SP25 FE","num":44,"chooseType":"Choose 1 answer","question":"How is employee voice different than open door policy?","options":{"A":"Open door policy follows up with people to show how changes were implemented","B":"Employee voice follows up with people to show how changes were implemented based on their communication","C":"They are identical in implementation","D":"Open door policy is strictly formal"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Tiếng nói của nhân viên (Employee voice) khác biệt với Chính sách mở cửa (Open door policy) như thế nào?","optionsVi":{"A":"Chính sách mở cửa theo dõi và minh chứng sự thay đổi","B":"Employee voice chủ động phản hồi và chứng minh các thay đổi thực tế đã được thực thi dựa trên ý kiến đóng góp của nhân viên (follows up to show how changes were implemented)","C":"Cả hai giống hệt nhau","D":"Chính sách mở cửa là hình thức cứng nhắc"},"answerDisplay":"B. Employee voice follows up with the people to show how changes were implemented based on their communication.","concept":"• Employee Voice thực chất bao gồm hai chiều: Lắng nghe đóng góp và Thực thi hành động phản hồi (Follow-up & Implementation) để nhân viên thấy ý kiến của họ có giá trị.","whyCorrect":"• Phản hồi kết quả hành động thực tế là điểm khác biệt cốt lõi của Employee Voice so với sự mở cửa lắng nghe thụ động.","whyWrong":{"A":"• Open door policy chỉ dừng ở mở cửa lắng nghe thụ động.","C":"• Hai khái niệm có sự khác biệt lớn về tính hiệu quả hành động.","D":"• Mở cửa mang tính hình thức lỏng lẻo."}}},{"id":45,"task":"sp25_fe","taskLabel":"SP25 FE","num":45,"chooseType":"Choose 1 answer","question":"Which of the following is an important action needed for the finalization of internal and external ethics policies before approval?","options":{"A":"Discarding open issues to provide a clean slate","B":"Documenting the assumptions and choices made in the drafting of the policies","C":"Testing the policy in an already deployed project setting","D":"Ensuring the policies are the same as those from peer organizations"},"answer":"B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Hành động quan trọng nào cần thiết cho việc hoàn thiện các chính sách đạo đức trước khi phê duyệt chính thức?","optionsVi":{"A":"Bỏ qua các vấn đề còn mở","B":"Ghi chép và lưu trữ tài liệu về các giả định và lựa chọn được đưa ra trong quá trình dự thảo (Documenting assumptions and choices made)","C":"Thử nghiệm chính sách trên dự án đã triển khai","D":"Đảm bảo chính sách giống hệt các công ty đối thủ"},"answerDisplay":"B. Documenting the assumptions and choices made in the drafting of the policies","concept":"• Ghi chép tài liệu về giả định và lý do đưa ra các quyết định trong dự thảo chính sách tạo ra tính giải trình và cơ sở kiểm toán sau này.","whyCorrect":"• Ghi chép các giả định giúp các bên phê duyệt hiểu rõ căn cứ lập luận của bộ chính sách.","whyWrong":{"A":"• Bỏ qua vấn đề chưa giải quyết là che giấu rủi ro.","C":"• Thử nghiệm trên dự án thực tế nên làm ở giai đoạn Pilot.","D":"• Sao chép đối thủ bỏ qua tính đặc thù của tổ chức."}}},{"id":46,"task":"sp25_fe","taskLabel":"SP25 FE","num":46,"chooseType":"Choose 1 answer","question":"Which of the following describe a process of cross-correlation of data? (Select two.)","options":{"A":"Discovering new information via inference","B":"Analysing emotional stimulus","C":"Comparing multiple data points or datasets to identify hidden patterns","D":"Comparing people of different demographic groups"},"answer":"A, C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Những nội dung nào sau đây mô tả quy trình tương quan chéo dữ liệu (Cross-correlation of data)? (Select two)","optionsVi":{"A":"Khám phá ra các thông tin mới thông qua suy luận dữ liệu (Discovering new information via inference)","B":"Phân tích phản ứng cảm xúc","C":"So sánh nhiều điểm dữ liệu hoặc tập dữ liệu với nhau để tìm mẫu ẩn (Comparing multiple data points or sets)","D":"So sánh các nhóm nhân khẩu học"},"answerDisplay":"A. Discovering new information via inference & C. Comparing multiple data points or sets","concept":"• Cross-correlation: So sánh đối chiếu chéo nhiều nguồn dữ liệu để phát hiện ra các quy luật và tri thức suy luận mới.","whyCorrect":"• Suy luận ra thông tin mới và so sánh chéo các điểm dữ liệu là hai đặc trưng của Cross-correlation.","whyWrong":{"B":"• Phân tích cảm xúc thuộc về Sentiment analysis.","D":"• So sánh nhân khẩu học là Demographic analysis."}}},{"id":47,"task":"sp25_fe","taskLabel":"SP25 FE","num":47,"chooseType":"Choose 1 answer","question":"Which of the following elements should be communicated with end users when negotiating ethical access to a user's data? (Select two.)","options":{"A":"The monetary value of that data","B":"An offer of money to relinquish rights","C":"The intention behind a certain activity or request","D":"A request for consent to perform an action"},"answer":"C, D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Những yếu tố nào sau đây nên được truyền thông rõ ràng với người dùng khi thỏa thuận quyền truy cập dữ liệu một cách có đạo đức? (Select two)","optionsVi":{"A":"Giá trị tiền tệ của dữ liệu","B":"Đề nghị tiền để từ bỏ quyền","C":"Mục đích và ý định đằng sau yêu cầu thu thập dữ liệu (The intention behind request)","D":"Yêu cầu sự đồng ý (Consent) để thực hiện hành động"},"answerDisplay":"C. The intention behind a certain activity or request & D. A request for consent to perform an action","concept":"• Informed Consent (Sự đồng ý dựa trên thông tin đầy đủ) yêu cầu giải thích rõ Mục đích sử dụng (Intention) và xin phép đồng ý tự nguyện (Consent).","whyCorrect":"• Nêu rõ mục đích thu thập và thu thập sự đồng ý rõ ràng là hai yêu cầu minh bạch đạo đức bắt buộc.","whyWrong":{"A":"• Định giá tiền tệ không phải trọng tâm quyền riêng tư.","B":"• Dùng tiền ép người dùng từ bỏ quyền là hành vi thao túng vi phạm đạo đức."}}},{"id":48,"task":"sp25_fe","taskLabel":"SP25 FE","num":48,"chooseType":"Choose 1 answer","question":"Which of the following are common key performance indicators (KPIs) within dashboards of data-driven systems? (Select two.)","options":{"A":"Model training time","B":"EBITDA financial metrics","C":"Cashflow forecast","D":"Performance metrics, such as accuracy and cost functions"},"answer":"A, D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Những chỉ số hiệu suất cốt lõi (KPI) phổ biến nào hiển thị trên bảng điều khiển của các hệ thống dựa trên dữ liệu? (Select two)","optionsVi":{"A":"Thời gian huấn luyện mô hình (Model training time)","B":"Chỉ số tài chính EBITDA","C":"Dự báo dòng tiền","D":"Các số liệu đo lường hiệu suất như độ chính xác và hàm sai số (accuracy and cost functions)"},"answerDisplay":"A. Model training time & D. Performance metrics, such as accuracy and cost functions","concept":"• ML System Dashboard KPIs: Đo lường Thời gian huấn luyện (Training time), Accuracy, Precision/Recall và Hàm mất mát (Loss/Cost function).","whyCorrect":"• Thời gian huấn luyện và các chỉ số đo lường hiệu suất mô hình là KPI trực quan hóa kỹ thuật chính.","whyWrong":{"B":"• EBITDA là KPI tài chính kế toán.","C":"• Dòng tiền thuộc về quản trị tài chính."}}},{"id":49,"task":"sp25_fe","taskLabel":"SP25 FE","num":49,"chooseType":"Choose 1 answer","question":"Which of the following sources does a SIEM (Security Information and Event Management) system typically pull data from? (Select two.)","options":{"A":"System event logs","B":"Encrypted personal data","C":"Personnel emails","D":"Network intrusion detection alerts"},"answer":"A, D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Hệ thống SIEM (Quản lý Sự kiện và Thông tin An ninh) thường thu thập dữ liệu từ những nguồn nào sau đây? (Select two)","optionsVi":{"A":"Nhật ký sự kiện hệ thống (System event logs)","B":"Dữ liệu cá nhân mã hóa","C":"Email nhân viên","D":"Các cảnh báo từ hệ thống phát hiện xâm nhập mạng (Network intrusion detection alerts)"},"answerDisplay":"A. System event logs & D. Network intrusion detection alerts","concept":"• Nguồn dữ liệu của SIEM: Thu thập Logs sự kiện hệ thống và Cảnh báo an ninh mạng (IDS/IPS Alerts) để tổng hợp phân tích đe dọa.","whyCorrect":"• Logs hệ thống và cảnh báo phát hiện xâm nhập là hai nguồn dữ liệu an ninh cốt lõi của SIEM.","whyWrong":{"B":"• SIEM không thu thập nội dung dữ liệu cá nhân mã hóa.","C":"• Email nhân viên chứa thông tin riêng tư không phải nguồn log an ninh mạng."}}},{"id":50,"task":"sp25_fe","taskLabel":"SP25 FE","num":50,"chooseType":"Choose 1 answer","question":"Which of the following are tools of an effective media communication plan? (Select two.)","options":{"A":"Mission statement","B":"Press release","C":"Public education campaign","D":"Video briefing"},"answer":"B, C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Những công cụ nào sau đây thuộc về một kế hoạch truyền thông báo chí/truyền thông hiệu quả? (Select two)","optionsVi":{"A":"Tuyên bố sứ mệnh","B":"Thông cáo báo chí (Press release)","C":"Chiến dịch giáo dục công chúng (Public education campaign)","D":"Tóm tắt video nội bộ"},"answerDisplay":"B. Press release & C. Public education campaign","concept":"• Kế hoạch truyền thông báo chí sử dụng các công cụ công bố chính thức như Press Release và các chiến dịch nâng cao nhận thức cộng đồng (Public Education Campaign).","whyCorrect":"• Thông cáo báo chí và chiến dịch giáo dục là hai công cụ truyền thông đối ngoại chính yếu.","whyWrong":{"A":"• Tuyên bố sứ mệnh là định hướng chiến lược nội bộ.","D":"• Video briefing là công cụ giao tiếp nội bộ."}}},{"id":51,"task":"sp25_fe","taskLabel":"SP25 FE","num":51,"chooseType":"Choose 1 answer","question":"Which of the following communication tactics help uphold transparency and explainability from the customer perspective? (Select two.)","options":{"A":"Providing prompt responses to customer questions about AI decisions","B":"Providing information about data-driven systems in simple, easy-to-understand terms","C":"Providing in-depth white papers on algorithms","D":"Providing guidelines for password security"},"answer":"A, B","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Những chiến thuật truyền thông nào sau đây giúp duy trì tính minh bạch và khả năng giải thích dưới góc nhìn của khách hàng? (Select two)","optionsVi":{"A":"Cung cấp phản hồi kịp thời cho các câu hỏi của khách hàng về các quyết định tự động của hệ thống (prompt responses to questions about decisions)","B":"Cung cấp thông tin về các hệ thống dựa trên dữ liệu bằng các thuật ngữ đơn giản, dễ hiểu (simple, easy-to-understand terms)","C":"Cung cấp tài liệu kỹ thuật hàn lâm phức tạp","D":"Cung cấp hướng dẫn bảo mật mật khẩu"},"answerDisplay":"A. Providing prompt responses to customer questions about the decisions made by data-driven systems. & B. Providing information about data-driven systems in simple, easy-to-understand terms.","concept":"• Minh bạch góc nhìn người dùng: Phản hồi nhanh chóng thắc mắc và Giải thích bằng ngôn ngữ phổ thông đơn giản.","whyCorrect":"• Phản hồi kịp thời và dùng ngôn ngữ đơn giản giúp khách hàng thực sự thấu hiểu và tin tưởng hệ thống.","whyWrong":{"C":"• Báo cáo hàn lâm quá phức tạp với người dùng đại chúng.","D":"• Hướng dẫn mật khẩu thuộc về an ninh người dùng."}}},{"id":52,"task":"sp25_fe","taskLabel":"SP25 FE","num":52,"chooseType":"Choose 1 answer","question":"Which of the following are useful strategies for communicating ethical risks to the organization? (Select two.)","options":{"A":"Communicate information through a single voice","B":"Disseminate information in multiple formats","C":"Communicate information in real time","D":"Provide information only when solicited"},"answer":"B, C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Những chiến lược nào sau đây là hữu ích để truyền thông các rủi ro đạo đức tới toàn tổ chức? (Select two)","optionsVi":{"A":"Truyền đạt thông tin qua một giọng nói duy nhất","B":"Phổ biến thông tin dưới nhiều định dạng đa dạng (Disseminate information in multiple formats)","C":"Truyền đạt thông tin theo thời gian thực (Communicate information in real time)","D":"Chỉ cung cấp thông tin khi được yêu cầu"},"answerDisplay":"B. Disseminate information in multiple formats & C. Communicate information in real time","concept":"• Truyền thông rủi ro hiệu quả cần sử dụng đa dạng định dạng (văn bản, video, tập huấn) và cập nhật kịp thời gian thực.","whyCorrect":"• Đa dạng định dạng giúp tăng khả năng tiếp thu và truyền thông thời gian thực giúp ngăn ngừa sự cố kịp thời.","whyWrong":{"A":"• Giọng nói duy nhất tạo ra sự đơn điệu và thiếu phủ sóng.","D":"• Chỉ cung cấp khi hỏi là thái độ thụ động nguy hiểm trong quản lý rủi ro."}}},{"id":53,"task":"sp25_fe","taskLabel":"SP25 FE","num":53,"chooseType":"Choose 1 answer","question":"Which of the following are useful strategies for communicating ethical risks to the individual? (Select two.)","options":{"A":"Ensure individuals understand specific details of each risk","B":"Communicate to individuals proactively rather than reactively","C":"Inform individuals of how they are obligated to mitigate risks","D":"Ensure individuals feel that they have input into the process"},"answer":"B, D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Những chiến lược nào sau đây là hữu ích để truyền thông các rủi ro đạo đức tới từng cá nhân người dùng? (Select two)","optionsVi":{"A":"Đảm bảo cá nhân hiểu từng chi tiết rủi ro","B":"Truyền thông tới cá nhân một cách chủ động thay vì bị động phản ứng (Communicate proactively rather than reactively)","C":"Yêu cầu cá nhân tự giảm thiểu rủi ro","D":"Đảm bảo cá nhân cảm thấy họ có quyền đóng góp ý kiến vào quy trình (Ensure individuals feel they have input)"},"answerDisplay":"B. Communicate to individuals proactively rather than reactively & D. Ensure individuals feel that they have input into the process","concept":"• Truyền thông rủi ro cá nhân hiệu quả: Cần thể hiện sự Chủ động (Proactive) và Trao quyền đóng góp (Empowerment) cho người dùng.","whyCorrect":"• Chủ động cảnh báo và lắng nghe đóng góp ý kiến của người dùng giúp tăng hiệu quả bảo vệ riêng tư.","whyWrong":{"A":"• Truyền thông quá chi tiết kỹ thuật gây quá tải nhận thức.","C":"• Đổ trách nhiệm giảm thiểu rủi ro lên người dùng là phi đạo đức."}}},{"id":54,"task":"sp25_fe","taskLabel":"SP25 FE","num":54,"chooseType":"Choose 1 answer","question":"Which of the following best describes why data is sometimes compared to oil? (Select two.)","options":{"A":"Data can be easily monopolized","B":"Data can damage the environment","C":"Data can be monetarily valuable","D":"Data can fuel algorithmic technologies and digital economy"},"answer":"C, D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Tại sao dữ liệu đôi khi được ví như 'dầu mỏ' của thế kỷ 21? (Select two)","optionsVi":{"A":"Dữ liệu dễ bị độc quyền","B":"Dữ liệu gây hại môi trường","C":"Dữ liệu sở hữu giá trị kinh tế/tiền tệ khổng lồ (monetarily valuable)","D":"Dữ liệu làm nhiên liệu vận hành các công nghệ thuật toán và nền kinh tế số (fuel algorithmic technologies)"},"answerDisplay":"C. Data can be monetarily valuable. & D. Data can fuel algorithmic technologies.","concept":"• Thuật ngữ 'Data is the new oil': Dữ liệu mang giá trị tài sản kinh tế cao và là nhiên liệu cốt lõi vận hành các hệ thống AI.","whyCorrect":"• Giá trị tài chính lớn và đóng vai trò nhiên liệu thúc đẩy nền kinh tế thuật toán.","whyWrong":{"A":"• Dữ liệu có thể tái sử dụng không cạn kệt như dầu mỏ vật lý.","B":"• Tác động môi trường của dữ liệu là gián tiếp do điện năng."}}},{"id":55,"task":"sp25_fe","taskLabel":"SP25 FE","num":55,"chooseType":"Choose 1 answer","question":"What does it mean to say that human rights are inalienable? (Select two.)","options":{"A":"Inalienable rights are conditional","B":"Inalienable rights are inherent in all human beings by virtue of being human","C":"Inalienable rights cannot be taken away, surrendered or transferred","D":"Inalienable rights are derived from local tradition"},"answer":"B, C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Việc nói rằng Quyền con người là Không thể tước đoạt (Inalienable) có nghĩa là gì? (Select two)","optionsVi":{"A":"Quyền không thể tước đoạt là có điều kiện","B":"Quyền không thể tước đoạt vốn sẵn có ở mọi con người (inherent in all human beings)","C":"Quyền không thể tước đoạt không thể bị lấy mất, từ bỏ hay chuyển nhượng (cannot be taken away)","D":"Quyền đến từ truyền thống địa phương"},"answerDisplay":"B. Inalienable rights are inherent in all human beings. & C. Inalienable rights cannot be taken away except in extreme circumstances.","concept":"• Khái niệm Inalienable Rights (Quyền bất khả xâm phạm / Không thể tước đoạt): Quyền tự nhiên gắn liền với phẩm giá con người và không ai có thể tước bỏ.","whyCorrect":"• Tính sẵn có tự nhiên và tính không thể bị từ bỏ/tước đoạt là định nghĩa của Inalienable.","whyWrong":{"A":"• Quyền không thể tước đoạt là tuyệt đối chứ không có điều kiện.","D":"• Quyền con người mang tính phổ quát toàn cầu chứ không phụ thuộc văn hóa địa phương."}}},{"id":56,"task":"sp25_fe","taskLabel":"SP25 FE","num":56,"chooseType":"Choose 1 answer","question":"Which of the following are advantages to adopting standards frameworks like ISO 27000? (Select two.)","options":{"A":"Technology-specific focus and precise implementation instructions","B":"Formal certification processes that provide competitive advantage","C":"Regulatory weight and legal enforcement","D":"International support, recognition, and involvement"},"answer":"B, D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Những lợi thế nào sau đây thu được khi áp dụng các khung tiêu chuẩn như ISO 27000? (Select two)","optionsVi":{"A":"Tập trung cụ thể công nghệ","B":"Các quy trình chứng nhận chính thức mang lại lợi thế cạnh tranh thương mại (Formal certification processes providing competitive advantage)","C":"Sức mạnh cưỡng chế pháp lý","D":"Sự hỗ trợ, công nhận và thừa nhận quốc tế (International support and recognition)"},"answerDisplay":"B. Formal certification processes that provide competitive advantage & D. International support, recognition, and involvement","concept":"• Lợi ích của Tiêu chuẩn ISO 27000: Có giá trị Chứng nhận Quốc tế (International Recognition) và chứng minh năng lực an ninh mạng giúp tạo lợi thế cạnh tranh.","whyCorrect":"• Chứng nhận ISO mang lại uy tín cạnh tranh quốc tế và được công nhận toàn cầu.","whyWrong":{"A":"• Khung ISO mang tính quản trị chung chứ không hướng dẫn mã nguồn công nghệ cụ thể.","C":"• ISO là tiêu chuẩn tự nguyện chứ không phải luật cưỡng chế."}}},{"id":57,"task":"sp25_fe","taskLabel":"SP25 FE","num":57,"chooseType":"Choose 1 answer","question":"Which of the following are logical arguments in favor of an organization maintaining compliance? (Select two.)","options":{"A":"Reduced time to deployment","B":"Avoidance of reputational damage and legal penalties","C":"Long-term cost savings due to avoiding severe fines and sanctions","D":"Reduced costs of development"},"answer":"B, C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Những lập luận logic nào sau đây ủng hộ việc một tổ chức duy trì sự tuân thủ (Compliance)? (Select two)","optionsVi":{"A":"Giảm thời gian triển khai","B":"Tránh tổn hại uy tín thương hiệu và hình phạt pháp lý (Avoidance of reputational damage)","C":"Tiết kiệm chi phí dài hạn nhờ tránh được các khoản tiền phạt nặng nề (Long-term cost savings due to avoiding fines)","D":"Giảm chi phí phát triển"},"answerDisplay":"B. Avoidance of reputational damage & C. Long-term cost savings due to avoiding fines","concept":"• Giá trị của Tuân thủ (Compliance Value): Ngăn chặn án phạt tài chính nặng nề và bảo vệ uy tín thương hiệu khỏi rủi ro kiện tụng.","whyCorrect":"• Tránh thảm họa tổn hại uy tín và tiết kiệm chi phí phạt pháp lý là hai lợi ích chính.","whyWrong":{"A":"• Tuân thủ đòi hỏi thời gian kiểm thử nên không làm giảm thời gian triển khai.","D":"• Chi phí tuân thủ ban đầu làm tăng chi phí phát triển."}}},{"id":58,"task":"sp25_fe","taskLabel":"SP25 FE","num":58,"chooseType":"Choose 1 answer","question":"Which of the following are possible causes of the limited adoption of a code of ethics within an organization? (Select two.)","options":{"A":"Comprehensive coverage of areas of concerns","B":"Lack of clarity and ambiguity in the code of ethics","C":"Prescriptive language used in code","D":"Lack of awareness of the code of ethics and where it is meant to be applied"},"answer":"B, D","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Những nguyên nhân nào sau đây dẫn đến việc áp dụng hạn chế bộ quy tắc đạo đức trong một tổ chức? (Select two)","optionsVi":{"A":"Bao phủ toàn diện các mối quan ngại","B":"Sự thiếu rõ ràng và mập mờ trong nội dung bộ quy tắc (Lack of clarity in the code)","C":"Ngôn ngữ chỉ định","D":"Thiếu nhận thức về bộ quy tắc và phạm vi nơi nó cần được áp dụng (Lack of awareness of the code)"},"answerDisplay":"B. Lack of clarity in the code of ethics & D. Lack of awareness of the code of ethics and where it is meant to be applied","concept":"• Rào cản áp dụng Quy tắc Đạo đức: Thiếu nhận thức tập huấn (Awareness gap) và Ngôn từ mập mờ thiếu rõ ràng (Ambiguity).","whyCorrect":"• Thiếu đào tạo nhận thức và ngôn từ mập mờ khiến nhân viên không hiểu hoặc không biết cách áp dụng.","whyWrong":{"A":"• Bao phủ toàn diện thúc đẩy áp dụng tốt hơn.","C":"• Ngôn ngữ chỉ định rõ ràng giúp dễ tuân thủ hơn."}}},{"id":59,"task":"sp25_fe","taskLabel":"SP25 FE","num":59,"chooseType":"Choose 1 answer","question":"Which of the following describe how adopting ethical practices can be a strategic differentiator? (Select three.)","options":{"A":"It will build customer trust","B":"It will support the development of strategic partnerships","C":"It will encourage top talent applicants to apply for your company","D":"It will ensure you comply with regulations"},"answer":"A, B, C","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Những yếu tố nào sau đây mô tả cách thức việc áp dụng các thực hành đạo đức có thể trở thành một yếu tố tạo sự biệt chiến lược (Strategic differentiator)? (Select three)","optionsVi":{"A":"Xây dựng niềm tin vững chắc của khách hàng (build customer trust)","B":"Hỗ trợ phát triển các mối quan hệ đối tác chiến lược (support strategic partnerships)","C":"Thu hút và khuyến khích các ứng viên tài năng ứng tuyển vào công ty (encourage applicants to apply)","D":"Đảm bảo tuân thủ quy định"},"answerDisplay":"A. It will build customer trust & B. It will support the development of strategic partnerships. & D. It will encourage applicants to apply for your company _","concept":"• Lợi thế Cạnh tranh từ Đạo đức (Ethical Competitive Advantage): Giúp tạo dựng Niềm tin Khách hàng, Thu hút Nhân tài chất lượng cao và Mở rộng Đối tác chiến lược.","whyCorrect":"• Ba yếu tố A, B, C tạo nên sự khác biệt vượt trội về thương hiệu và tài sản nhân sự so với đối thủ.","whyWrong":{"D":"• Tuân thủ quy định chỉ là tiêu chuẩn bắt buộc tối thiểu (Baseline compliance), không phải yếu tố tạo sự biệt cạnh tranh (Strategic differentiator)."}}},{"id":60,"task":"sp25_fe","taskLabel":"SP25 FE","num":60,"chooseType":"Choose 1 answer","question":"Why is accountability an important principle to include in governance structures for data-driven technologies?","options":{"A":"Accountability in governance structures encourages all employees to feel responsible for building trustworthy systems","B":"Accountability encourages employees to put business needs first","C":"Accountability encourages management to hold employees accountable for their actions","D":"Accountability encourages key employees to put business needs first"},"answer":"A","source":"ITE302c_SP25_FE","explanation":{"questionVi":"Tại sao trách nhiệm giải trình (Accountability) lại là một nguyên tắc quan trọng cần đưa vào cấu trúc quản trị công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Trách nhiệm giải trình thúc đẩy tất cả nhân viên cảm nhận được trách nhiệm cá nhân trong việc xây dựng các hệ thống đáng tin cậy (encourages all employees to feel responsible for building trustworthy systems)","B":"Khuyến khích nhân viên đặt nhu cầu kinh doanh lên hàng đầu","C":"Khuyến khích quản lý bắt bẻ nhân viên","D":"Khuyến khích nhân viên chủ chốt chạy theo lợi nhuận"},"answerDisplay":"A. Accountability in govemance structures encourages all employees to feel responsible for building trusuorthy systems _","concept":"• Accountability & Culture: Trách nhiệm giải trình lan tỏa nhận thức trách nhiệm cá nhân tới từng kỹ sư và nhân viên để đồng lòng hướng tới AI đáng tin cậy.","whyCorrect":"• Tạo dựng tinh thần trách nhiệm tập thể trong việc xây dựng sản phẩm công nghệ an toàn có trách nhiệm.","whyWrong":{"B":"• Đặt nhu cầu kinh doanh lên trên đạo đức gây ra rủi ro vi phạm.","C":"• Trách nhiệm giải trình không dùng để làm công cụ trừng phạt cá nhân.","D":"• Chạy theo nhu cầu kinh doanh làm suy yếu quản trị."}}},{"id":1,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":1,"chooseType":"Choose 1 answer","question":"You have a dataset of customers that includes each customer's gender, location, and total spending amount. You want to group similar customers together to target marketing campaigns without prior labels. What ML technique is this?","options":{"A":"Dimensionality reduction","B":"Regression","C":"Classification","D":"Clustering"},"answer":"D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Bạn có một tập dữ liệu khách hàng bao gồm giới tính, vị trí và tổng số tiền chi tiêu. Bạn muốn nhóm các khách hàng tương tự lại với nhau để phục vụ chiến dịch tiếp thị mà không có nhãn trước. Kỹ thuật học máy nào được áp dụng?","optionsVi":{"A":"Giảm chiều dữ liệu","B":"Hồi quy (Regression)","C":"Phân loại (Classification)","D":"Phân cụm (Clustering)"},"answerDisplay":"D. Clustering","concept":"• Clustering (Học không giám sát - Unsupervised Learning): Tự động gom nhóm các điểm dữ liệu có đặc trưng tương đồng mà không cần nhãn dữ liệu trước.","whyCorrect":"• Phân cụm khách hàng không có nhãn trước là bài toán Clustering điển hình.","whyWrong":{"A":"• Giảm chiều dữ liệu nén biến số.","B":"• Hồi quy dự đoán con số liên tục.","C":"• Phân loại yêu cầu nhãn lớp trước."}}},{"id":2,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":2,"chooseType":"Choose 1 answer","question":"A dataset attribute that is not directly identifiable by itself but constitutes data about the individual that needs to be protected is known as a:","options":{"A":"Explicitly private column","B":"Quasi-identifier","C":"Non-sensitive column","D":"Sensitive column"},"answer":"B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Một thuộc tính dữ liệu không tự định danh trực tiếp cá nhân nhưng cấu thành dữ liệu về cá nhân cần được bảo vệ khi kết hợp lại được gọi là:","optionsVi":{"A":"Cột riêng tư rõ ràng","B":"Thuộc tính bán định danh (Quasi-identifier)","C":"Cột không nhạy cảm","D":"Cột nhạy cảm"},"answerDisplay":"B. quasi-identifier","concept":"• Quasi-identifier: Thuộc tính kết hợp (Tuổi, Giới tính, Mã bưu điện) có thể giúp tái định danh cá nhân.","whyCorrect":"• Định nghĩa chuẩn của thuộc tính bán định danh trong riêng tư dữ liệu.","whyWrong":{"A":"• Không có thuật ngữ này.","C":"• Cột không nhạy cảm không đe dọa riêng tư.","D":"• Cột nhạy cảm chứa thông tin sức khỏe/tài chính."}}},{"id":3,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":3,"chooseType":"Choose 1 answer","question":"The Data minimization principle requires that you limit data collection to only what is:","options":{"A":"Necessary for differential privacy","B":"Optional for a chain of command","C":"Needed to have k-anonymity","D":"Required to fulfill a specific, stated purpose"},"answer":"D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Nguyên tắc Giảm thiểu dữ liệu (Data minimization) yêu cầu bạn giới hạn việc thu thập dữ liệu chỉ trong phạm vi những gì:","optionsVi":{"A":"Cần thiết cho riêng tư vi sai","B":"Tùy chọn cho chuỗi chỉ huy","C":"Cần thiết để có k-anonymity","D":"Trực tiếp cần thiết để thực hiện mục đích cụ thể đã xác định (required to fulfill a specific purpose)"},"answerDisplay":"D. required to fulfill a specific purpose","concept":"• Data Minimization: Giới hạn thu thập đúng và đủ mục đích.","whyCorrect":"• Thu thập đúng mục đích là bản chất Data Minimization.","whyWrong":{"A":"• Kỹ thuật riêng tư vi sai.","B":"• Cấu trúc chỉ huy.","C":"• Mô hình ẩn danh."}}},{"id":4,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":4,"chooseType":"Choose 1 answer","question":"How do AI and other data-driven technologies use probability in decision making?","options":{"A":"By determining objective likelihood","B":"By estimating likelihood without input data","C":"By providing a mathematical model of belief about the likelihood of an event happening based on evidence","D":"By guaranteeing 100% likelihood"},"answer":"C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"AI và các công nghệ dựa trên dữ liệu sử dụng xác suất như thế nào trong việc ra quyết định?","optionsVi":{"A":"Xác định khả năng khách quan","B":"Ước tính không cần dữ liệu","C":"Cung cấp một mô hình toán học phản ánh mức độ tin tưởng về khả năng xảy ra của một sự kiện dựa trên dữ liệu (model of belief about likelihood)","D":"Đảm bảo chắc chắn 100%"},"answerDisplay":"C. By providing a model of belief about the likelihood of some event happening","concept":"• Probabilistic Inference: Mô hình hóa mức độ tin tưởng dựa trên bằng chứng dữ liệu.","whyCorrect":"• Mô hình toán học lượng hóa độ tin tưởng khả năng xảy ra sự kiện.","whyWrong":{"A":"• Xác suất AI mang tính suy luận toán học.","B":"• Bắt buộc cần dữ liệu đầu vào.","D":"• AI không bao giờ cam kết chắc chắn 100%."}}},{"id":5,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":5,"chooseType":"Choose 1 answer","question":"If a coin is flipped as a randomized response mechanism in differential privacy, which setup ensures survey data remains private while retaining statistical utility?","options":{"A":"Heads for yes, tails for no","B":"Heads for fake answer, tails for true answer","C":"Heads for true answer, tails for random answer (Randomized Response)","D":"Heads for random answer, tails for yes"},"answer":"C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Nếu tung đồng xu làm cơ chế phản hồi ngẫu nhiên trong riêng tư vi sai, thiết lập nào đảm bảo dữ liệu khảo sát riêng tư mà vẫn có giá trị thống kê?","optionsVi":{"A":"Ngửa là Có, Sấp là Không","B":"Ngửa trả lời giả, Sấp trả lời thật","C":"Nếu Ngửa thì trả lời thật, nếu Sấp thì trả lời ngẫu nhiên (heads for true answer, tails for random answer)","D":"Ngửa trả lời ngẫu nhiên, Sấp là Có"},"answerDisplay":"C. heads for true answer, tails for random answer","concept":"• Randomized Response: Tung đồng xu tạo nhiễu ngẫu nhiên bảo vệ cá nhân nhưng giữ xác suất thống kê.","whyCorrect":"• Cơ chế chuẩn của Randomized Response.","whyWrong":{"A":"• Ngửa Có sấp Không lộ hoàn toàn câu trả lời.","B":"• Không tạo nhiễu ngẫu nhiên toán học.","D":"• Làm sai lệch xác suất."}}},{"id":6,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":6,"chooseType":"Choose 1 answer","question":"A major limitation of using explainable, adjustable algorithms is that users tend to make:","options":{"A":"Selfish, self-serving decisions (Gaming the algorithm)","B":"Socially conscious decisions","C":"Malicious hacking decisions","D":"Private decisions"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Hạn chế lớn của việc sử dụng các thuật toán giải thích được và có thể điều chỉnh là người dùng có xu hướng đưa ra các quyết định:","optionsVi":{"A":"Ích kỷ, vụ lợi cá nhân / thao túng thuật toán (Selfish decisions / Gaming the algorithm)","B":"Có ý thức xã hội","C":"Quyết định hack độc hại","D":"Quyết định riêng tư"},"answerDisplay":"A. selfish","concept":"• Goodhart's Law & Gaming the Algorithm: Khi cơ chế ra quyết định của thuật toán bị lộ giải thích rõ ràng, người dùng sẽ tự điều chỉnh hành vi một cách ích kỷ (Selfish) để thao túng kết quả theo hướng có lợi cho bản thân.","whyCorrect":"• Minh bạch giải thích khiến người dùng tự lợi điều chỉnh dữ liệu để gặt hái kết quả có lợi (Selfish decisions).","whyWrong":{"B":"• Người dùng thường ưu tiên lợi ích cá nhân hơn ý thức xã hội.","C":"• Thao túng thuật toán ích kỷ khác với tấn công mạng độc hại.","D":"• Riêng tư không phải hạn chế của khả năng điều chỉnh."}}},{"id":7,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":7,"chooseType":"Choose 1 answer","question":"A disruptive user on a social media site is subjected to a shadow ban. Which of the following indicates that a shadow ban has occurred?","options":{"A":"User is warned by admin","B":"User finds posting privileges revoked","C":"User receives a ban message","D":"A user logs in one day to find that they are able to post normally, but receive zero engagement or direct responses because their posts are hidden from everyone else"},"answer":"D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Một người dùng gây rối trên mạng xã hội bị áp dụng lệnh 'Shadow ban' (Cấm ẩn). Biểu hiện nào chỉ ra lệnh Shadow ban đang diễn ra?","optionsVi":{"A":"Người dùng bị quản trị viên cảnh báo","B":"Người dùng bị tước quyền đăng bài","C":"Người dùng nhận thông báo cấm","D":"Người dùng đăng bài bình thường nhưng không ai nhìn thấy và không nhận được bất kỳ tương tác/phản hồi nào (able to post, but receive no direct responses)"},"answerDisplay":"D. A user logs in one day to find that they are able to post, but receive no direct responses.","concept":"• Shadow Ban (Cấm ngầm / Cấm ẩn): Hệ thống chặn hiển thị nội dung của người dùng đối với cộng đồng mà hoàn toàn không thông báo cho người đó biết.","whyCorrect":"• Vẫn đăng bài được nhưng bài viết bị ngầm ẩn khỏi nguồn cấp của cộng đồng.","whyWrong":{"A":"• Cảnh báo công khai không phải Shadow ban.","B":"• Tước quyền công khai là Banning.","C":"• Thông báo cấm là Explicit ban."}}},{"id":8,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":8,"chooseType":"Choose 1 answer","question":"What does the acronym RACI stand for?","options":{"A":"Relatable, Agreeable, Commendable, Irascible","B":"Responsible, Accessible, Consulted, Improvised","C":"Redesignable, Accessible, Collected, Informative","D":"Responsible, Accountable, Consulted, Informed"},"answer":"D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Từ viết tắt RACI đại diện cho điều gì?","optionsVi":{"A":"Relatable, Agreeable, Commendable, Irascible","B":"Responsible, Accessible, Consulted, Improvised","C":"Redesignable, Accessible, Collected, Informative","D":"Người thực thi (Responsible), Người chịu trách nhiệm (Accountable), Người tham vấn (Consulted), Người nhận thông tin (Informed)"},"answerDisplay":"D. Responsible, Accountable, Consulted, Informed","concept":"• Ma trận phân công RACI.","whyCorrect":"• Định nghĩa chính xác RACI.","whyWrong":{"A":"• Các từ tiếng Anh ngẫu nhiên.","B":"• Accessible và Improvised sai.","C":"• Redesignable sai."}}},{"id":9,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":9,"chooseType":"Choose 1 answer","question":"At which level of differential privacy is the outcome secured from even the entity collecting the data?","options":{"A":"k-anonymous","B":"Global differential privacy","C":"Local differential privacy (LDP)","D":"Premium differential privacy"},"answer":"C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Ở cấp độ riêng tư vi sai nào thì kết quả dữ liệu được bảo vệ an toàn ngay cả khỏi chính thực thể đang thu thập dữ liệu?","optionsVi":{"A":"k-anonymous","B":"Riêng tư vi sai toàn cục (Global)","C":"Riêng tư vi sai cục bộ (Local differential privacy - LDP)","D":"Riêng tư vi sai cao cấp"},"answerDisplay":"C. local","concept":"• Local Differential Privacy (LDP): Nhiễu ngẫu nhiên được thêm ngay trên thiết bị người dùng (Client-side) trước khi gửi về máy chủ, khiến chính đơn vị thu thập cũng không biết dữ liệu gốc.","whyCorrect":"• Thêm nhiễu trực tiếp tại thiết bị giúp bảo mật ngay cả trước đơn vị thu thập dữ liệu.","whyWrong":{"A":"• k-anonymity là mô hình tập dữ liệu.","B":"• Global DP thêm nhiễu tại máy chủ trung tâm nên máy chủ vẫn thấy dữ liệu thô.","D":"• Premium không phải thuật ngữ."}}},{"id":10,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":10,"chooseType":"Choose 1 answer","question":"The nature of a predictive model's output primarily reveals:","options":{"A":"The researchers behind it","B":"The algorithm's bias","C":"The quality, distribution, and biases of the data it was trained on","D":"The ethics of individual inputs"},"answer":"C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Bản chất đầu ra của một mô hình dự đoán chủ yếu tiết lộ điều gì?","optionsVi":{"A":"Các nhà nghiên cứu","B":"Thiên vị thuật toán","C":"Chất lượng, sự phân bố và các thiên vị của tập dữ liệu mà nó được huấn luyện (the data it is trained on)","D":"Đạo đức đầu vào cá nhân"},"answerDisplay":"C. the data it is trained on","concept":"• GIGO Principle: Mô hình phản ánh trực tiếp dữ liệu huấn luyện.","whyCorrect":"• Tiết lộ bản chất tập dữ liệu đầu vào.","whyWrong":{"A":"• Nhà nghiên cứu chọn mô hình.","B":"• Thuật toán chỉ là khung.","D":"• Đạo đức cá nhân không đại diện."}}},{"id":11,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":11,"chooseType":"Choose 1 answer","question":"Which of the following Python explainability tools is designed to integrate seamlessly with Google's Cloud AI Platform for model analysis?","options":{"A":"What-If Tool (WIT)","B":"SHAP","C":"ELI5","D":"LIME"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Công cụ giải thích Python nào sau đây được thiết kế để tích hợp liền mạch với Google Cloud AI Platform phục vụ phân tích mô hình?","optionsVi":{"A":"What-If Tool (WIT của Google)","B":"SHAP","C":"ELI5","D":"LIME"},"answerDisplay":"A. What-If","concept":"• Google What-If Tool (WIT): Công cụ giao diện trực quan của Google AI giúp phân tích tác động khi thay đổi thuộc tính mô hình.","whyCorrect":"• What-If Tool là sản phẩm trực thuộc hệ sinh thái Google Cloud AI.","whyWrong":{"B":"• SHAP là thư viện mã nguồn mở độc lập.","C":"• ELI5 là thư viện mã mở Python.","D":"• LIME là bộ công cụ mã mở."}}},{"id":12,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":12,"chooseType":"Choose 1 answer","question":"Which of the following metrics is used to evaluate a linear regression machine learning model?","options":{"A":"Goodhart's Law","B":"Accuracy","C":"Cost function (Mean Squared Error - MSE)","D":"Receiver operating characteristic (ROC)"},"answer":"C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Chỉ số nào sau đây được sử dụng để đánh giá mô hình học máy hồi quy tuyến tính (Linear Regression)?","optionsVi":{"A":"Định luật Goodhart","B":"Độ chính xác Accuracy","C":"Hàm chi phí / Hàm sai số (Cost function - MSE)","D":"Đường cong ROC"},"answerDisplay":"C. Cost function","concept":"• Linear Regression Evaluation: Dùng Hàm chi phí Cost Function (MSE/RMSE).","whyCorrect":"• Đo lường sai số liên tục cho mô hình Hồi quy.","whyWrong":{"A":"• Quy luật kinh tế.","B":"• Accuracy dùng cho Phân loại Classification.","D":"• ROC dùng cho Phân loại nhị phân."}}},{"id":13,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":13,"chooseType":"Choose 1 answer","question":"Which of the following is a best practice for incorporating diversity, equity, and inclusion (DEI) into organizational media communications?","options":{"A":"Promote an authentic organizational culture that embraces DEI values throughout the organization","B":"Ensure multiple groups communicate differently based on race","C":"Focus on intended message without incorporating feedback","D":"Reassure customers with PR statements"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Thực hành tốt nhất để tích hợp tính đa dạng, bình đẳng và bao hàm (DEI) vào truyền thông doanh nghiệp là gì?","optionsVi":{"A":"Thúc đẩy một văn hóa tổ chức chân thực thực sự đón nhận và thực thi các giá trị DEI (Promote organizational culture embracing DEI values)","B":"Phân nhóm truyền thông theo chủng tộc","C":"Bỏ qua phản hồi","D":"Trấn an khách hàng bằng PR"},"answerDisplay":"A. Promote an organizational culture that embraces these values","concept":"• Authentic DEI Communication: Bắt nguồn từ văn hóa tổ chức thực chất.","whyCorrect":"• Thúc đẩy văn hóa doanh nghiệp đón nhận thực thi giá trị DEI.","whyWrong":{"B":"• Phân biệt truyền thông theo chủng tộc là phi đạo đức.","C":"• Bỏ qua phản hồi gây ngạo mạn.","D":"• PR bề nổi là Ethics Washing."}}},{"id":14,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":14,"chooseType":"Choose 1 answer","question":"When you deliver periodic statements about a crisis to the media, what should the first statement do?","options":{"A":"Provide in-depth details about the situation","B":"Survey public opinion","C":"Set the tone of what is to follow, acknowledge event, and state initial steps","D":"Accept full responsibility immediately"},"answer":"C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Khi bạn đưa ra các phát biểu định kỳ về một cuộc khủng hoảng cho báo chí, phát biểu đầu tiên cần phải làm gì?","optionsVi":{"A":"Cung cấp chi tiết chuyên sâu","B":"Khảo sát ý kiến công chúng","C":"Thiết lập tông giọng truyền thông, xác nhận sự cố và nêu bước xử lý ban đầu (Set the tone of what is to follow)","D":"Nhận trách nhiệm ngay lập tức"},"answerDisplay":"C. Set the tone of what is to follow","concept":"• Holding Statement: Thiết lập tông giọng truyền thông nghiêm túc.","whyCorrect":"• Thiết lập định hướng và thái độ tiếp nhận sự cố.","whyWrong":{"A":"• Chưa có đủ chi tiết chuyên sâu.","B":"• Chưa thể khảo sát dư luận ngay.","D":"• Nhận trách nhiệm vội vàng gây rủi ro pháp lý."}}},{"id":15,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":15,"chooseType":"Choose 1 answer","question":"Which of the following is the most important idea that a crisis communication strategy should focus on?","options":{"A":"The public's perception of a crisis","B":"The real-world effects and physical safety impacts of a crisis","C":"The individual details of a crisis","D":"Internal stakeholder consensus"},"answer":"B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Nội dung quan trọng nhất mà một chiến lược truyền thông khủng hoảng cần tập trung giải quyết là gì?","optionsVi":{"A":"Nhận thức của công chúng","B":"Các tác động thực tế trong đời sống thực và sự an toàn của con người (real-world effects of a crisis)","C":"Các chi tiết đơn lẻ","D":"Sự đồng thuận nội bộ"},"answerDisplay":"B. The real-world effects of a crisis","concept":"• Real-World Effects in Crisis PR: Ưu tiên tác hại thực tế và an toàn con người.","whyCorrect":"• Ưu tiên xử lý thiệt hại đời thực và bảo vệ an toàn.","whyWrong":{"A":"• Nhận thức là hệ quả phụ.","C":"• Chi tiết đơn lẻ làm mất bức tranh toàn cảnh.","D":"• Đồng thuận nội bộ không thay thế được xử lý thiệt hại bên ngoài."}}},{"id":16,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":16,"chooseType":"Choose 1 answer","question":"Which of the following describes the primary purpose of a Business Impact Assessment (BIA)?","options":{"A":"It helps you predict business interruptions and develop recovery strategies","B":"It helps you identify what risks you can accept or transfer to third party","C":"It helps evaluate ethical failure","D":"It helps transfer risks to customers"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng mục đích chính của Đánh giá Tác động Kinh doanh (BIA)?","optionsVi":{"A":"Giúp bạn dự đoán các gián đoạn kinh doanh và phát triển các chiến lược khôi phục tương ứng (predict business interruptions and develop recovery strategies)","B":"Chuyển rủi ro cho bên thứ ba","C":"Đánh giá thất bại đạo đức","D":"Chuyển rủi ro cho khách hàng"},"answerDisplay":"A. It helps you predict business interruptions and develop recovery strategies.","concept":"• BIA Purpose: Dự đoán gián đoạn vận hành và xây dựng chiến lược khôi phục.","whyCorrect":"• Dự đoán gián đoạn và lập chiến lược khôi phục.","whyWrong":{"B":"• Risk Treatment.","C":"• Ethical Impact Assessment.","D":"• Phi đạo đức."}}},{"id":17,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":17,"chooseType":"Choose 1 answer","question":"What is the primary benefit of hosting a virtual press conference over a traditional co-located conference?","options":{"A":"Easier to communicate overall message","B":"Easily accessible","C":"The conference can be interactive without participants needing to be co-located","D":"Impressed by technology"},"answer":"C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Lợi ích chính của việc tổ chức một buổi họp báo trực tuyến (Virtual press conference) so với họp báo truyền thống tập trung là gì?","optionsVi":{"A":"Dễ truyền đạt thông điệp","B":"Dễ tiếp cận","C":"Hội thảo có thể mang tính tương tác mà không yêu cầu các đại biểu phải tập trung cùng một địa điểm (interactive without being co-located)","D":"Gây ấn tượng công nghệ"},"answerDisplay":"C. The conference can be interactive without the participants needing to be co-located.","concept":"• Virtual Conference Advantage: Tương tác mà không cần chung vị trí địa lý.","whyCorrect":"• Tạo tương tác phản hồi mà không bị rào cản địa lý.","whyWrong":{"A":"• Video thu sẵn cũng truyền thông điệp được.","B":"• Tiếp cận là đặc tính chung.","D":"• Ấn tượng công nghệ là giá trị bề nổi."}}},{"id":18,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":18,"chooseType":"Choose 1 answer","question":"The endorsement of which role is most vital for securing company-wide adoption of an ethics policy?","options":{"A":"Department heads","B":"C-suite executives and senior leadership","C":"Employees","D":"Customers"},"answer":"B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Sự bảo chứng/ủng hộ của vai trò nào là quan trọng nhất để đảm bảo sự áp dụng chính sách đạo đức trên toàn công ty?","optionsVi":{"A":"Trưởng bộ phận","B":"Ban lãnh đạo cấp cao C-suite (C-suite executives)","C":"Nhân viên","D":"Khách hàng"},"answerDisplay":"B. C-suite executives","concept":"• Tone at the Top: Cam kết ủng hộ từ C-suite.","whyCorrect":"• Cam kết từ cấp C-suite tạo quyền lực thực thi toàn công ty.","whyWrong":{"A":"• Trưởng bộ phận làm theo chỉ đạo.","C":"• Nhân viên là đối tượng tuân thủ.","D":"• Khách hàng là thực thể bên ngoài."}}},{"id":19,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":19,"chooseType":"Choose 1 answer","question":"Our primary goals for building an ethical predictive model include making sure the results are:","options":{"A":"Precise, explainable, predictable","B":"Accurate, precise, fair","C":"Precise, methodical, ethical","D":"Accurate, fair, and explainable"},"answer":"D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Mục tiêu khi xây dựng một mô hình dự đoán có đạo đức bao gồm việc đảm bảo kết quả đạt 3 tiêu chí nào?","optionsVi":{"A":"Chính xác, giải thích được, dự đoán được","B":"Chính xác, chuẩn xác, công bằng","C":"Chuẩn xác, bài bản, đạo đức","D":"Chính xác (Accurate), Công bằng (Fair) và Giải thích được (Explainable)"},"answerDisplay":"D. accurate, fair and explainable","concept":"• Accurate + Fair + Explainable.","whyCorrect":"• Bộ 3 tiêu chuẩn định nghĩa mô hình dự đoán có trách nhiệm.","whyWrong":{"A":"• Thiếu Công bằng.","B":"• Thiếu Giải thích được.","C":"• Thiếu Công bằng."}}},{"id":20,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":20,"chooseType":"Choose 1 answer","question":"What is the primary purpose of differential privacy?","options":{"A":"To enable parties to share private data without revealing individuals represented in the data","B":"To remove direct identifiers","C":"To allow certain parties to access data","D":"To ensure data is completely confidential"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Mục đích chính của Tính riêng tư vi sai (Differential privacy) là gì?","optionsVi":{"A":"Cho phép các bên chia sẻ và phân tích dữ liệu riêng tư mà không làm lộ danh tính của bất kỳ cá nhân nào có trong tập dữ liệu (share private data without revealing individuals)","B":"Loại bỏ định danh trực tiếp","C":"Phân quyền truy cập","D":"Bảo mật tuyệt đối"},"answerDisplay":"A. To enable parties to share private data without revealing individuals represented in the data.","concept":"• Differential Privacy Purpose: Chia sẻ dữ liệu tổng thể mà không làm lộ dữ liệu cá thể.","whyCorrect":"• Cho phép phân tích chia sẻ dữ liệu mà bảo vệ riêng tư cá nhân.","whyWrong":{"B":"• Anonymization.","C":"• Access Control.","D":"• Encryption."}}},{"id":21,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":21,"chooseType":"Choose 1 answer","question":"What's the difference between a basic and a complex learning algorithm?","options":{"A":"A basic algorithm has a set amount of choices to optimize for, while a complex algorithm is given the freedom to discover its own features and representations","B":"Basic cannot use computer vision","C":"Basic cannot process more than 5 steps","D":"Basic handles numbers, complex handles pictures"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Sự khác biệt giữa một thuật toán cơ bản và một thuật toán học máy phức tạp là gì?","optionsVi":{"A":"Thuật toán cơ bản có một số lượng lựa chọn cố định để tối ưu hóa, trong khi thuật toán phức tạp được tự do tự phát hiện các thuộc tính đại diện (basic has set choices vs complex given freedom to find own model)","B":"Cơ bản không dùng thị giác máy tính","C":"Cơ bản không xử lý quá 5 bước","D":"Cơ bản xử lý số, phức tạp xử lý ảnh"},"answerDisplay":"A. A basic algorithm has a set amount of choices to optimize for, while a complex algorithm is given the freedom to find its own model","concept":"• Representation Learning.","whyCorrect":"• Tự do học và khám phá các biểu diễn đặc trưng.","whyWrong":{"B":"• Thuật toán cơ bản vẫn dùng trong thị giác.","C":"• Số bước không quyết định bản chất.","D":"• Thuật toán cơ bản vẫn xử lý ảnh."}}},{"id":22,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":22,"chooseType":"Choose 1 answer","question":"A training set based on feeding 60% of data for training, validating on 20%, and testing on 20% is known as a:","options":{"A":"Classic training set (Classic train/val/test split)","B":"Optimized training set","C":"False positive set","D":"Predictive training set"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Một tập dữ liệu được chia theo tỷ lệ 60% cho huấn luyện, 20% cho kiểm chứng và 20% cho kiểm thử được gọi là:","optionsVi":{"A":"Phân chia tập dữ liệu cổ điển (Classic training set / Classic split)","B":"Tập huấn luyện tối ưu hóa","C":"Tập dương tính giả","D":"Tập huấn luyện dự đoán"},"answerDisplay":"A. classic training set","concept":"• Classic Train/Val/Test Split (60/20/20 hoặc 70/15/15): Tỷ lệ phân chia dữ liệu tiêu chuẩn truyền thống.","whyCorrect":"• Phân chia tỷ lệ 60/20/20 là cấu trúc tập dữ liệu cổ điển.","whyWrong":{"B":"• Optimized training set can thiệp vào đại diện nhóm.","C":"• False positive set là danh sách lỗi.","D":"• Predictive training set không phải tên gọi tỷ lệ."}}},{"id":23,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":23,"chooseType":"Choose 1 answer","question":"What is the AI black box problem?","options":{"A":"When a model is deployed, but researchers are unable to figure out why it's making specific decisions","B":"Problem when attributes are inaccurate","C":"Issue of not having enough data","D":"Model cannot judge shape or color"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Bài toán Hộp đen (Black box problem) trong AI được phát biểu chính xác là gì?","optionsVi":{"A":"Khi mô hình đã triển khai nhưng các nhà nghiên cứu không thể tìm ra lý do tại sao nó đưa ra các quyết định đó (unable to figure out why making decisions)","B":"Vấn đề thuộc tính sai","C":"Thiếu dữ liệu huấn luyện","D":"Không đoán được hình dạng màu sắc"},"answerDisplay":"A. When a model is deployed, but researchers are unable to figure out why its making decisions","concept":"• Black Box Problem.","whyCorrect":"• Không thể giải thích cách mô hình ra kết quả.","whyWrong":{"B":"• Thuộc tính sai gây thiên vị.","C":"• Thiếu dữ liệu gây underfitting.","D":"• Lỗi thị giác."}}},{"id":24,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":24,"chooseType":"Choose 1 answer","question":"Model inputs of address with 'City + State' as separate inputs from a dataset would violate which accuracy guideline?","options":{"A":"Domain expertise","B":"No correlation guideline (No correlating data)","C":"First principles","D":"Objective summarization"},"answer":"B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Đưa các đầu vào địa chỉ như 'Thành phố + Bang' thành các biến đầu vào riêng biệt trong cùng một tập dữ liệu sẽ vi phạm hướng dẫn độ chính xác nào?","optionsVi":{"A":"Chuyên môn miền","B":"Hướng dẫn không trùng lặp tương quan (No correlating data)","C":"Nguyên lý đầu tiên","D":"Tóm tắt khách quan"},"answerDisplay":"B. No correlating data","concept":"• No Correlating Data / Multicollinearity.","whyCorrect":"• Đưa các biến phụ thuộc tương quan trực tiếp vào vi phạm nguyên tắc No correlating data.","whyWrong":{"A":"• Chuyên môn miền giúp loại bỏ biến trùng.","C":"• Nguyên lý đầu tiên là lập luận logic.","D":"• Tóm tắt khách quan là tổng hợp."}}},{"id":25,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":25,"chooseType":"Choose 1 answer","question":"The pessimist view of General AI (AGI) references a scenario in which technological advancement leads to:","options":{"A":"Winner take all market","B":"A potential human extinction event (Existential risk)","C":"Creating AI for all governments","D":"Impossible progress"},"answer":"B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Góc nhìn bi quan về Trí tuệ Nhân tạo Tổng quát (AGI) đề cập đến kịch bản trong đó sự tiến bộ công nghệ dẫn tới:","optionsVi":{"A":"Thị trường kẻ thắng ăn tất","B":"Một nguy cơ diệt vong tiềm tàng đối với nhân loại (potential extinction event / Existential risk)","C":"Tạo AI cho chính phủ","D":"Sự tiến bộ bất khả thi"},"answerDisplay":"B. a potential extinction event","concept":"• Existential Risk of AGI (Rủi ro Diệt vong): Góc nhìn bi quan cảnh báo AGI mất kiểm soát có thể gây ra thảm họa diệt vong cho loài người.","whyCorrect":"• Nguy cơ diệt vong nhân loại là mối lo ngại cực đoan nhất của góc nhìn bi quan AGI.","whyWrong":{"A":"• Winner-take-all là rủi ro kinh tế độc quyền.","C":"• Tạo AI cho chính phủ là chính sách.","D":"• Sự tiến bộ AGI là hoàn toàn khả thi."}}},{"id":26,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":26,"chooseType":"Choose 1 answer","question":"Which type of bias causes people to uncritically trust and rely on an automated decision-making system?","options":{"A":"Implicit bias","B":"Automation bias","C":"Complacency bias","D":"Confirmation bias"},"answer":"B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Loại định kiến nào khiến con người tin tưởng và phụ thuộc một cách thiếu phản biện vào một hệ thống ra quyết định tự động?","optionsVi":{"A":"Định kiến ẩn tàng","B":"Định kiến tự động hóa (Automation bias)","C":"Định kiến tự thỏa mãn","D":"Định kiến xác nhận"},"answerDisplay":"B. Automation bias","concept":"• Automation Bias: Xu hướng tâm lý con người nhắm mắt tin tưởng tuyệt đối vào đề xuất tự động của máy tính.","whyCorrect":"• Định nghĩa kinh điển của Automation bias.","whyWrong":{"A":"• Implicit bias về nhóm xã hội.","C":"• Complacency bias là sự chủ quan.","D":"• Confirmation bias tìm thông tin củng cố quan điểm."}}},{"id":27,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":27,"chooseType":"Choose 1 answer","question":"A predictive model's false negative result can be defined as:","options":{"A":"Predicted positive, actual positive","B":"Predicted negative, actual negative","C":"Predicted positive, actual negative","D":"The predicted result was negative, but the actual result was positive"},"answer":"D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Kết quả Âm tính giả (False Negative) của một mô hình dự đoán được định nghĩa là gì?","optionsVi":{"A":"Dự đoán dương tính, thực tế dương tính (True Positive)","B":"Dự đoán âm tính, thực tế âm tính (True Negative)","C":"Dự đoán dương tính, thực tế âm tính (False Positive)","D":"Kết quả dự đoán là âm tính, nhưng kết quả thực tế lại là dương tính (predicted negative, actual positive)"},"answerDisplay":"D. the predicted result was negative, and the actual result was positive","concept":"• False Negative (FN): Mô hình dự đoán Âm tính (bỏ sót) nhưng thực tế là Dương tính (có bệnh/có lỗi).","whyCorrect":"• Định nghĩa chính xác của chỉ số False Negative.","whyWrong":{"A":"• True Positive.","B":"• True Negative.","C":"• False Positive."}}},{"id":28,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":28,"chooseType":"Choose 1 answer","question":"Which of the following describes why explainability is important in AI decision systems?","options":{"A":"Necessary so internal stakeholders understand system","B":"Provides interpretations of actions","C":"It provides accountability and trust for users and regulators","D":"Enables explanation for shareholder purposes"},"answer":"C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Nội dung nào mô tả lý do tại sao tính giải thích được (Explainability) lại quan trọng?","optionsVi":{"A":"Nội bộ hiểu hệ thống","B":"Cung cấp diễn giải","C":"Nó tạo ra trách nhiệm giải trình và lòng tin (provides accountability and trust)","D":"Giải thích cho cổ đông"},"answerDisplay":"C. It provides accountability and trust","concept":"• XAI Value: Accountability + Trust.","whyCorrect":"• Củng cố trách nhiệm giải trình và lòng tin xã hội.","whyWrong":{"A":"• Hướng tới cả bên ngoài.","B":"• Phương tiện kỹ thuật.","D":"• Cổ đông chỉ là một góc."}}},{"id":29,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":29,"chooseType":"Choose 1 answer","question":"What is one possible reason a predictive model may predict a higher crime rate in a neighborhood based on dataset flaws?","options":{"A":"If drug arrests are historically high in that area, the model correlates crime with areas of heavy policing and high arrest datasets","B":"If crime is down, model predicts parabolic curve","C":"Training curve lacked data","D":"Error function output false data"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Lý do nào giải thích việc một mô hình dự đoán có thể dự báo sai tỷ lệ tội phạm cao hơn tại một khu vực dựa trên lỗi dữ liệu?","optionsVi":{"A":"Nếu số vụ bắt giữ ma túy trong lịch sử ở khu vực đó cao (do cảnh sát tập trung tuần tra đông), mô hình sẽ tương quan tội phạm với dữ liệu lịch sử bắt giữ đó (correlate crime with high arrest datasets)","B":"Mô hình dự đoán đường cong parabol","C":"Thiếu dữ liệu đường cong","D":"Hàm lỗi xuất dữ liệu giả"},"answerDisplay":"A. If drug arrests are historically high in that area, the model may correlate crime with areas of high drug use based on the datasets","concept":"• Predictive Policing Feedback Loop: Dữ liệu cảnh sát tuần tra nhiều sinh ra số lượng vụ bắt giữ cao, mô hình ngộ nhận khu vực đó có tỷ lệ tội phạm cao hơn thực tế.","whyCorrect":"• Mô hình nhầm lẫn giữa mật độ bắt giữ của cảnh sát với tỷ lệ tội phạm thực tế.","whyWrong":{"B":"• Mô hình không tự đoán đường cong parabol ngẫu nhiên.","C":"• Thiếu dữ liệu gây underfitting chứ không tự sinh thiên vị địa phương.","D":"• Hàm sai số không tự tạo ra dữ liệu giả."}}},{"id":30,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":30,"chooseType":"Choose 1 answer","question":"How does the 'virtuous cycle' that benefits Big Tech operate?","options":{"A":"Organizations write algorithms with fewer biases","B":"By acting virtuous, public respects Big Tech","C":"Better classes of customers lead to richer data","D":"Data-driven algorithms improve solutions, leading to new customers, and better data"},"answer":"D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Chu trình tăng trưởng độc quyền ('Virtuous Cycle') mang lại lợi ích cho các tập đoàn Big Tech vận hành như thế nào?","optionsVi":{"A":"Viết thuật toán ít thiên vị","B":"Công chúng tôn trọng Big Tech","C":"Khách hàng tốt mang dữ liệu phong phú","D":"Thuật toán dựa trên dữ liệu cải thiện giải pháp -> Thu hút khách hàng mới -> Thu thập thêm dữ liệu tốt hơn (Data -> Product -> Users -> More Data)"},"answerDisplay":"D. Data-driven algorithms improve solutions, leading to new customers, and better data.","concept":"• Data Flywheel Effect.","whyCorrect":"• Vòng lặp củng cố độc quyền Big Tech.","whyWrong":{"A":"• Mục tiêu đạo đức.","B":"• Thương hiệu.","C":"• Yếu tố phụ."}}},{"id":31,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":31,"chooseType":"Choose 1 answer","question":"What tools do researchers have to evaluate the fairness of existing black box models?","options":{"A":"Systematically change input perturbations and evaluate output decisions (Audit by testing inputs/outputs)","B":"Change training data, evaluate outputs","C":"Change inputs, evaluate training data","D":"Evaluate inputs, evaluate data"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Chiến lược chính nào được các nhà nghiên cứu sử dụng để đánh giá tính công bằng của một mô hình Hộp đen đã triển khai?","optionsVi":{"A":"Thay đổi có hệ thống các đầu vào thử nghiệm và đánh giá các quyết định đầu ra thu được (Change inputs, evaluate outputs)","B":"Thay đổi dữ liệu huấn luyện","C":"Thay đổi đầu vào và đánh giá dữ liệu huấn luyện","D":"Đánh giá đầu vào và dữ liệu"},"answerDisplay":"A. Change inputs, evaluate outputs","concept":"• Black-box Audit Technique.","whyCorrect":"• Thay đổi đầu vào và đo lường đầu ra là phương pháp duy nhất kiểm toán Hộp đen đóng.","whyWrong":{"B":"• Hộp đen đóng không cho sửa dữ liệu huấn luyện.","C":"• Đánh giá dữ liệu huấn luyện không đo được đầu ra.","D":"• Đánh giá đầu vào đơn thuần không đo được thiên vị."}}},{"id":32,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":32,"chooseType":"Choose 1 answer","question":"What is non-maleficence?","options":{"A":"The principle of doing no harm","B":"The principle of having no bias","C":"The principle of having no security risk","D":"The principle of having security risk"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Khái niệm Không gây hại (Non-maleficence) được định nghĩa là gì?","optionsVi":{"A":"Nguyên tắc không gây ra tổn hại cho con người và xã hội (The principle of doing no harm)","B":"Nguyên tắc không có thiên vị","C":"Nguyên tắc không có rủi ro an ninh","D":"Nguyên tắc có rủi ro an ninh"},"answerDisplay":"A. The principle of doing no harm.","concept":"• Non-maleficence: Do no harm.","whyCorrect":"• Định nghĩa kinh điển của Non-maleficence.","whyWrong":{"B":"• Fairness.","C":"• Security.","D":"• Sai định nghĩa."}}},{"id":33,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":33,"chooseType":"Choose 1 answer","question":"Why does the trolley problem pose an ethical predicament in autonomous vehicle engineering?","options":{"A":"You have to make a choice between two scenarios where choosing one inevitably leads to loss of life in the other","B":"Too many outcomes make choice difficult","C":"Moral responsibility split with trolley operator","D":"Actor lacks control"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Tại sao bài toán Xe điện (Trolley problem) lại tạo ra một tình huống tiến thoái lưỡng nan về đạo đức trong kỹ thuật xe tự lái?","optionsVi":{"A":"Bạn phải đưa ra lựa chọn giữa hai kịch bản mà việc chọn kịch bản này chắc chắn dẫn tới thiệt hại mạng sống ở kịch bản kia (choice between two scenarios leading to loss of life)","B":"Quá nhiều kết quả khiến khó chọn","C":"Trách nhiệm phân chia với người vận hành xe","D":"Tác thể thiếu quyền kiểm soát"},"answerDisplay":"A. You have to make a choice between two scenarios where choosing one leads to loss of life in the other.","concept":"• The Trolley Problem in AI: Tình huống xung đột đạo đức bắt buộc chọn phương án gây ra thiệt hại tính mạng ít hơn khi tai nạn không thể tránh khỏi.","whyCorrect":"• Sự bắt buộc phải lựa chọn giữa các kết quả đều gây ra thương vong tính mạng.","whyWrong":{"B":"• Vấn đề là bản chất thiệt hại chứ không chỉ số lượng kết quả.","C":"• Xe tự lái không có người vận hành thủ công.","D":"• Lập trình viên AI là tác thể thiết lập thuật toán ra quyết định."}}},{"id":34,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":34,"chooseType":"Choose 1 answer","question":"Which school of philosophical thought primarily advocates for a global moral code based on categorical duty?","options":{"A":"Utilitarianism","B":"Deontology","C":"Virtue ethics","D":"Virtual ethics"},"answer":"B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Trường phái tư tưởng triết học nào chủ yếu cổ vũ cho một bộ quy tắc đạo đức toàn cầu dựa trên nghĩa vụ tuyệt đối?","optionsVi":{"A":"Thuyết vị lợi","B":"Thuyết nghĩa vụ luận (Deontology)","C":"Thuyết đạo đức đức hạnh","D":"Đạo đức ảo"},"answerDisplay":"B. Deontology","concept":"• Deontology.","whyCorrect":"• Tuân thủ các quy tắc nghĩa vụ tuyệt đối.","whyWrong":{"A":"• Vị lợi đánh giá theo hậu quả.","C":"• Đức hạnh cá nhân.","D":"• Không phải trường phái."}}},{"id":35,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":35,"chooseType":"Choose 1 answer","question":"Fairness in AI is best defined as just and equal treatment without:","options":{"A":"Prejudice and favoritism","B":"Discrimination and prejudice","C":"Bias and contempt","D":"Favoritism or discrimination based on protected attributes"},"answer":"D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Tính công bằng (Fairness) trong AI được định nghĩa đúng nhất là sự đối xử công minh mà không có:","optionsVi":{"A":"Định kiến và sự thiên vị","B":"Phân biệt đối xử và định kiến","C":"Thiên vị và coi thường","D":"Sự thiên vị hoặc sự phân biệt đối xử dựa trên các thuộc tính được bảo vệ (favoritism or discrimination)"},"answerDisplay":"D. favoritism or discrimination","concept":"• AI Fairness Definition: Ngăn ngừa sự thiên vị (Favoritism) và phân biệt đối xử (Discrimination) đối với các nhóm dân số.","whyCorrect":"• Không thiên vị và không phân biệt đối xử đối với các cá nhân hay nhóm.","whyWrong":{"A":"• Prejudice mang nghĩa hẹp định kiến.","B":"• Thiếu khía cạnh thiên vị (Favoritism).","C":"• Contempt là sự coi thường không thuộc thuật ngữ."}}},{"id":36,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":36,"chooseType":"Choose 1 answer","question":"In auditing and fixing word embedding models like Word2Vec for bias, we have an advantage over traditional black box models because:","options":{"A":"We can generate a fairness score","B":"We can decide which inputs to use","C":"We have direct access to the training data and vector space representations","D":"We can see the decision-making model"},"answer":"C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Khi kiểm toán và khắc phục thiên vị trong mô hình nhúng từ như Word2Vec, chúng ta có lợi thế gì so với mô hình hộp đen truyền thống?","optionsVi":{"A":"Tạo được điểm công bằng","B":"Quyết định đầu vào","C":"Chúng ta có quyền truy cập trực tiếp vào tập dữ liệu huấn luyện và các đại diện không gian vectơ từ (access to training data and vector space)","D":"Nhìn thấy mô hình ra quyết định"},"answerDisplay":"C. we have access to the training data","concept":"• Word2Vec Auditing: Có thể đo lường trực tiếp khoảng cách đại số vectơ (Vector distance) giữa các từ (như Man - Doctor vs Woman - Nurse) trong tập dữ liệu huấn luyện mở.","whyCorrect":"• Quyền truy cập tập dữ liệu huấn luyện và không gian vectơ cho phép can thiệp trực tiếp.","whyWrong":{"A":"• Điểm công bằng có thể tính cho nhiều mô hình.","B":"• Quyết định đầu vào là thao tác kiểm thử.","D":"• Word2Vec là mô hình biểu diễn từ chứ không phải mô hình phân loại quyết định."}}},{"id":37,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":37,"chooseType":"Choose 1 answer","question":"Which of the following is the most important ethical consideration regarding deepfake technology?","options":{"A":"They take away monetization opportunities","B":"They usurp a person's likeness, identity, and voice, which can then be weaponized against them without consent","C":"They violate data sharing agreements","D":"They are built on third party tech"},"answer":"B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Xem xét đạo đức quan trọng nhất liên quan đến công nghệ Deepfake là gì?","optionsVi":{"A":"Tước đoạt cơ hội kiếm tiền","B":"Chúng chiếm đoạt hình ảnh, danh tính và giọng nói của một người để vũ khí hóa chống lại họ mà không được phép (usurp person's likeness weaponized against them)","C":"Vi phạm thỏa thuận","D":"Xây trên công nghệ bên thứ ba"},"answerDisplay":"B. They usurp a person's likeness and can then be weaponized against them.","concept":"• Deepfake Ethical Risks: Xâm phạm nghiêm trọng danh tính và hình ảnh cá nhân.","whyCorrect":"• Tước đoạt hình ảnh/giọng nói để mạo danh gây hại cá nhân.","whyWrong":{"A":"• Tài chính không phải nguy cơ đạo đức cốt lõi.","C":"• Thỏa thuận dữ liệu là vấn đề hợp đồng.","D":"• Chi tiết hạ tầng."}}},{"id":38,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":38,"chooseType":"Choose 1 answer","question":"Which of the following is a key reason to engage in a comprehensive information gathering phase before drafting ethics policies?","options":{"A":"It helps to unearth best practices and peer benchmarks in industry","B":"Provides examples of pitfalls","C":"Collect evidence for beliefs","D":"Saves effort by copying"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Lý do quan trọng để tiến hành giai đoạn thu thập thông tin toàn diện trước khi dự thảo chính sách đạo đức là gì?","optionsVi":{"A":"Giúp phát hiện và khai quật các thực hành tốt nhất (best practices) từ các doanh nghiệp cùng ngành (unearth best practices from peers in industry)","B":"Ví dụ cạm bẫy","C":"Thu thập bằng chứng ủng hộ ý kiến","D":"Tiết kiệm công sức bằng cách sao chép"},"answerDisplay":"A. It helps to unearth best practices from peers in the industry.","concept":"• Pre-draft Benchmarking: Khai quật thực hành tốt nhất của ngành.","whyCorrect":"• Giúp bộ chính sách bắt kịp thông lệ tiên tiến của ngành.","whyWrong":{"B":"• Tránh cạm bẫy là lợi ích phụ.","C":"• Confirmation bias.","D":"• Sao chép là vô trách nhiệm."}}},{"id":39,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":39,"chooseType":"Choose 1 answer","question":"Which of the following is NOT a common consideration when looking at the major AI ethical frameworks?","options":{"A":"Humanity and Beneficence","B":"Privacy","C":"Security and Robustness","D":"Monetization and Profit Maximization"},"answer":"D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Yếu tố nào sau đây KHÔNG PHẢI là một xem xét phổ biến trong các khung làm việc đạo đức AI chính yếu?","optionsVi":{"A":"Nhân tính (Humanity)","B":"Quyền riêng tư (Privacy)","C":"An ninh (Security)","D":"Tối đa hóa lợi nhuận thương mại (Monetization / Profit maximization)"},"answerDisplay":"D. Transparency (hoặc Profit Maximization trong bản chuẩn)","concept":"• AI Ethics Pillars vs Business Goals.","whyCorrect":"• Kiếm tiền lợi nhuận là mục tiêu kinh doanh thương mại chứ không phải nguyên tắc đạo đức.","whyWrong":{"A":"• Trụ cột đạo đức.","B":"• Trụ cột cốt lõi.","C":"• Trụ cột kỹ thuật."}}},{"id":40,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":40,"chooseType":"Choose 1 answer","question":"Which of the following is a potential organizational benefit of establishing an ethical organizational culture?","options":{"A":"More employees likely to switch careers","B":"Employees will feel a strong sense of responsibility, trust, and loyalty toward the organization","C":"Employees more likely to blindly listen to superiors","D":"Guaranteed stock value increase"},"answer":"B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Lợi ích tiềm năng cho tổ chức khi xây dựng một văn hóa doanh nghiệp có đạo đức là gì?","optionsVi":{"A":"Nhân viên dễ nhảy việc","B":"Nhân viên sẽ cảm thấy có tinh thần trách nhiệm, niềm tin và lòng trung thành mạnh mẽ đối với tổ chức (sense of responsibility and loyalty)","C":"Nhân viên nghe lời cấp trên mù quáng","D":"Đảm bảo tăng giá cổ phiếu"},"answerDisplay":"B. Employees will feel a sense of responsibility and loyalty.","concept":"• Benefits of Ethical Culture: Tăng cường tinh thần trách nhiệm, lòng tin và sự gắn kết trung thành của nhân sự.","whyCorrect":"• Tạo dựng tinh thần trách nhiệm và lòng trung thành gắn kết của nhân viên.","whyWrong":{"A":"• Giảm tỷ lệ nhảy việc.","C":"• Đạo đức khuyến khích phản biện xây dựng chứ không nghe lời mù quáng.","D":"• Giá cổ phiếu bị chi phối bởi nhiều yếu tố thị trường."}}},{"id":41,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":41,"chooseType":"Choose 1 answer","question":"Which approach to corporate governance is more likely to create an ethical organizational culture?","options":{"A":"A systemic approach with incentive systems aligned with ethical values","B":"An oversight committee focus on rules","C":"A board focused on legal compliance","D":"An oversight committee focus on static frameworks"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Cách tiếp cận quản trị doanh nghiệp nào có khả năng tạo ra một văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Cách tiếp cận hệ thống kết hợp với hệ thống đãi ngộ/khuyến khích gắn liền với giá trị đạo đức (systemic approach with incentive systems)","B":"Ủy ban tập trung quy tắc cứng","C":"Hội đồng tập trung tuân thủ pháp lý","D":"Ủy ban tập trung khung lý thuyết"},"answerDisplay":"A. A systemic approach with incentive systems.","concept":"• Systemic Governance: Gắn cơ chế đãi ngộ với giá trị.","whyCorrect":"• Thúc đẩy tự giác qua hệ thống khuyến khích.","whyWrong":{"B":"• Tạo tâm lý đối phó.","C":"• Tuân thủ pháp lý là mức sàn.","D":"• Khung tĩnh thiếu tính hành động."}}},{"id":42,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":42,"chooseType":"Choose 1 answer","question":"An ethical impact assessment is:","options":{"A":"Focused on past ethical risks","B":"Focused on identifying and preventing future potential ethical problems (Forward-looking)","C":"Focused on identifying causes of past errors","D":"Focused on identifying causes of future errors"},"answer":"B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Đánh giá Tác động Đạo đức (Ethical Impact Assessment) có trọng tâm là gì?","optionsVi":{"A":"Tập trung rủi ro quá khứ","B":"Tập trung vào việc nhận diện và phòng ngừa các vấn đề đạo đức tiềm tàng trong tương lai (Focused on preventing future problems)","C":"Tìm nguyên nhân lỗi cũ","D":"Tìm nguyên nhân lỗi tương lai"},"answerDisplay":"B. Focused on preventing future problems.","concept":"• Ethical Impact Assessment: Công cụ chủ động hướng về tương lai (Proactive / Forward-looking).","whyCorrect":"• Chủ động phòng ngừa rủi ro tiềm tàng trong tương lai.","whyWrong":{"A":"• Rủi ro quá khứ thuộc Post-mortem.","C":"• Root cause analysis.","D":"• Định nghĩa không chuẩn."}}},{"id":43,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":43,"chooseType":"Choose 1 answer","question":"Why is accountability an important principle to include in governance structures for data-driven technologies?","options":{"A":"Accountability in governance structures encourages all employees to feel responsible for building trustworthy systems","B":"Accountability encourages employees to put business needs first","C":"Accountability encourages management to hold employees accountable for actions","D":"Accountability encourages key employees to put business needs first"},"answer":"A","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Tại sao trách nhiệm giải trình (Accountability) lại là một nguyên tắc quan trọng cần đưa vào cấu trúc quản trị?","optionsVi":{"A":"Trách nhiệm giải trình thúc đẩy tất cả nhân viên cảm nhận được trách nhiệm cá nhân trong việc xây dựng các hệ thống đáng tin cậy (encourages all employees to feel responsible for building trustworthy systems)","B":"Đặt nhu cầu kinh doanh lên hàng đầu","C":"Bắt bẻ nhân viên","D":"Chạy theo lợi nhuận"},"answerDisplay":"A. Accountability in governance structures encourages all employees to feel responsible for building trusuorthy systems.","concept":"• Accountability Culture.","whyCorrect":"• Thúc đẩy tinh thần trách nhiệm tập thể xây dựng AI đáng tin cậy.","whyWrong":{"B":"• Đặt lợi nhuận trên đạo đức gây rủi ro.","C":"• Không dùng trừng phạt cá nhân.","D":"• Chạy theo kinh doanh làm suy yếu quản trị."}}},{"id":44,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":44,"chooseType":"Choose 1 answer","question":"Which of the following is a benefit of using focus groups over surveys?","options":{"A":"They provide structured data","B":"They are more scalable","C":"They are easier way to collect info","D":"They allow for deeper engagement and qualitative insights with the target demographic community"},"answer":"D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Lợi ích của việc sử dụng nhóm thảo luận tập trung (Focus groups) so với khảo sát (Surveys) là gì?","optionsVi":{"A":"Cung cấp dữ liệu cấu trúc","B":"Mở rộng quy mô dễ hơn","C":"Dễ thu thập thông tin","D":"Cho phép tương tác sâu sắc hơn và thu thập góc nhìn định tính từ cộng đồng dân cư mục tiêu (deeper engagement with target demographic)"},"answerDisplay":"D. They allow for deeper engagement with the target demographic community.","concept":"• Focus Groups vs Surveys: Nhóm tập trung cho phép tương tác định tính chiều sâu.","whyCorrect":"• Tương tác chiều sâu và khai quật thông tin định tính.","whyWrong":{"A":"• Surveys cung cấp dữ liệu cấu trúc.","B":"• Surveys mở rộng quy mô tốt hơn.","C":"• Surveys dễ thực hiện hơn."}}},{"id":45,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":45,"chooseType":"Choose 1 answer","question":"Which of the following is an important reason for continually refreshing an organization's internal and external ethics policies?","options":{"A":"Justify product release","B":"Maintain alignment of policies with employee values","C":"It helps maintain alignment with emergent technological risks and changing ethical posture of products and services","D":"Demonstrate work to management"},"answer":"C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Lý do quan trọng của việc liên tục cập nhật/làm mới các chính sách đạo đức nội bộ và bên ngoài của tổ chức là gì?","optionsVi":{"A":"Biện minh phát hành sản phẩm","B":"Duy trì sự phù hợp với giá trị nhân viên","C":"Giúp duy trì sự phù hợp với các rủi ro mới bùng phát và sự thay đổi trong định hướng đạo đức của các sản phẩm/dịch vụ (maintain alignment with emergent risks and changing ethical posture)","D":"Báo cáo công việc cho quản lý"},"answerDisplay":"C. It helps maintain alignment with the emergent risks and changing ethical posture of the products and services of the organization.","concept":"• Continuous Policy Refresh: Bắt kịp với sự xuất hiện của các rủi ro công nghệ mới bùng phát (Emergent risks).","whyCorrect":"• Duy trì sự phù hợp với các rủi ro công nghệ mới xuất hiện.","whyWrong":{"A":"• Không dùng để biện minh phát hành.","B":"• Phù hợp với nhân viên chỉ là một phần.","D":"• Báo cáo cấp trên là hình thức hành chính."}}},{"id":46,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":46,"chooseType":"Choose 1 answer","question":"How could a board of ethics be an example of ethics washing?","options":{"A":"If it has a wide variety of stakeholders","B":"If it has a narrow list of values to guide decisions","C":"If it has no power to institute change or enforce decisions","D":"If it has a large number of stakeholders"},"answer":"C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Làm thế nào một Hội đồng Đạo đức có thể trở thành ví dụ về 'Ethics washing'?","optionsVi":{"A":"Nếu có nhiều bên liên quan","B":"Nếu có danh sách giá trị hẹp","C":"Nếu hội đồng không có thực quyền để thực thi thay đổi hoặc cưỡng chế quyết định (has no power to institute change)","D":"Nếu quá đông thành viên"},"answerDisplay":"C. If it has no power to institute change.","concept":"• Ethics Washing: Lập hội đồng bề nổi nhưng không trao thực quyền.","whyCorrect":"• Tước bỏ thực quyền thay đổi là hình thức Ethics Washing.","whyWrong":{"A":"• Tích cực.","B":"• Phạm vi.","D":"• Số lượng không quyết định."}}},{"id":47,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":47,"chooseType":"Choose 1 answer","question":"Which of the following are likely examples of a leverageable third-party data-driven or data-related product? (Select two.)","options":{"A":"Data annotation, labeling, and augmentation tools","B":"Management oversight","C":"Product design lifecycle","D":"Pre-trained or compiled third-party AI models"},"answer":"A, D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những ví dụ nào sau đây là sản phẩm dựa trên dữ liệu của bên thứ ba có thể tận dụng sử dụng? (Select two)","optionsVi":{"A":"Các công cụ gán nhãn, chú thích và tăng cường dữ liệu của bên thứ ba (Data annotation and augmentation tools)","B":"Giám sát quản lý","C":"Vòng đời thiết kế sản phẩm","D":"Các mô hình AI được biên dịch / huấn luyện sẵn của bên thứ ba (Compiled models)"},"answerDisplay":"A. Data annotation and augmentation tools & D. Compiled models","concept":"• Third-Party AI Data Products: Bộ công cụ gán nhãn dữ liệu (Data annotation tools) và Mô hình huấn luyện sẵn (Pre-trained/Compiled models).","whyCorrect":"• Công cụ chú thích dữ liệu và các mô hình huấn luyện sẵn là sản phẩm dữ liệu bên thứ ba điển hình.","whyWrong":{"B":"• Giám sát quản lý là quy trình nội bộ.","C":"• Vòng đời thiết kế là phương pháp luận."}}},{"id":48,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":48,"chooseType":"Choose 1 answer","question":"Which of the following risk analysis methods use words like 'unlikely' and 'rare' for likelihood, and 'low', 'medium', 'high' for impact? (Select two.)","options":{"A":"Semi-qualitative analysis","B":"Quantitative analysis","C":"Semi-quantitative analysis","D":"Qualitative analysis"},"answer":"A, D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những phương pháp phân tích rủi ro nào sử dụng các từ mô tả định tính như 'hiếm gặp', 'thấp', 'trung bình', 'cao'? (Select two)","optionsVi":{"A":"Phân tích bán định tính (Semi-qualitative analysis)","B":"Phân tích định lượng","C":"Phân tích bán định lượng","D":"Phân tích định tính (Qualitative analysis)"},"answerDisplay":"A. Semi-qualitative analysis & D. Qualitative analysis","concept":"• Qualitative Risk Descriptors.","whyCorrect":"• Phân tích định tính và bán định tính dùng nhãn từ ngữ mô tả.","whyWrong":{"B":"• Định lượng dùng con số tài chính.","C":"• Bán định lượng dùng điểm số thứ tự."}}},{"id":49,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":49,"chooseType":"Choose 1 answer","question":"Which of the following elements directly constitute Personally Identifiable Information (PII)? (Select two.)","options":{"A":"Cookies and session tokens","B":"Passport numbers","C":"Device IDs","D":"Telephone numbers (or Social Security Numbers)"},"answer":"B, D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những yếu tố nào sau đây trực tiếp cấu thành Thông tin định danh cá nhân (PII)? (Select two)","optionsVi":{"A":"Cookies và session tokens","B":"Số hộ chiếu (Passport numbers)","C":"ID thiết bị","D":"Số điện thoại / Số an sinh xã hội (Telephone numbers / SSN)"},"answerDisplay":"B. Passport numbers & D. Telephone numbers","concept":"• Direct PII: Số hộ chiếu, Số điện thoại / Số an sinh xã hội trực tiếp định danh cá nhân.","whyCorrect":"• Số hộ chiếu và số điện thoại là các thuộc tính định danh cá nhân trực tiếp.","whyWrong":{"A":"• Cookies là dữ liệu phiên gián tiếp.","C":"• Device ID là mã thiết bị phần cứng."}}},{"id":50,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":50,"chooseType":"Choose 1 answer","question":"Which of the following are tools of an effective media communication plan? (Select two.)","options":{"A":"Mission statement","B":"Press release","C":"Public education campaign","D":"Video briefing"},"answer":"B, C","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những công cụ nào thuộc về một kế hoạch truyền thông báo chí hiệu quả? (Select two)","optionsVi":{"A":"Tuyên bố sứ mệnh","B":"Thông cáo báo chí (Press release)","C":"Chiến dịch giáo dục công chúng (Public education campaign)","D":"Video briefing nội bộ"},"answerDisplay":"B. Press release & C. Public education campaign","concept":"• Media Plan Tools: Press Release và Public Education Campaign.","whyCorrect":"• Thông cáo báo chí và chiến dịch giáo dục là 2 công cụ đối ngoại chính.","whyWrong":{"A":"• Tuyên bố sứ mệnh là định hướng nội bộ.","D":"• Video briefing là giao tiếp nội bộ."}}},{"id":51,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":51,"chooseType":"Choose 1 answer","question":"Which of the following are important factors to consider when developing a media campaign? (Select two.)","options":{"A":"The environment in which campaign launched","B":"Effect on bottom line","C":"The time-sensitive nature of communication in campaign","D":"The specific risks that will be talked about in campaign"},"answer":"C, D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những yếu tố quan trọng nào cần xem xét khi xây dựng một chiến dịch truyền thông? (Select two)","optionsVi":{"A":"Môi trường ra mắt","B":"Tác động lợi nhuận","C":"Tính chất nhạy cảm thời gian của truyền thông (time-sensitive nature of communication)","D":"Các rủi ro cụ thể sẽ được truyền thông trong chiến dịch (risks talked about in campaign)"},"answerDisplay":"C. The time-sensitive nature of communication in the campaign & D. The risks that will be talked about in the campaign","concept":"• Media Campaign Factors: Tính nhạy cảm thời gian (Timing) và Nội dung rủi ro cụ thể truyền thông.","whyCorrect":"• Yếu tố thời điểm nhạy cảm và nội dung rủi ro cụ thể là 2 nhân tố cốt lõi.","whyWrong":{"A":"• Môi trường là kênh truyền tải.","B":"• Lợi nhuận là mục tiêu thương mại."}}},{"id":52,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":52,"chooseType":"Choose 1 answer","question":"Which of the following are important qualities of an effective press release? (Select two.)","options":{"A":"It's in a digital format","B":"It's non-interactive","C":"It's delivered on a single platform","D":"It's concise, clear, and newsworthy"},"answer":"A, D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những đặc tính quan trọng nào thuộc về một Thông cáo báo chí (Press Release) hiệu quả? (Select two)","optionsVi":{"A":"Được phát hành dưới định dạng kỹ thuật số (digital format)","B":"Không có tính tương tác","C":"Phát hành trên một nền tảng","D":"Ngắn gọn súc tích và giàu giá trị tin tức (concise and newsworthy)"},"answerDisplay":"A. It's in a digital format & D. It's concise","concept":"• Press Release Qualities: Digital format + Concise.","whyCorrect":"• Định dạng kỹ thuật số và tính ngắn gọn súc tích.","whyWrong":{"B":"• Tích hợp đa phương tiện tương tác.","C":"• Nên phát hành đa nền tảng."}}},{"id":53,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":53,"chooseType":"Choose 1 answer","question":"Which of the following are challenges that can arise if you fail to communicate about the social impact of ethical risks? (Select two.)","options":{"A":"Decreased corporate revenue","B":"Reduced brand loyalty","C":"Disenfranchisement of vulnerable communities","D":"Erosion of basic human rights"},"answer":"C, D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những thách thức/hệ lụy nào có thể phát sinh nếu bạn không truyền thông về tác động xã hội của các rủi ro đạo đức? (Select two)","optionsVi":{"A":"Giảm doanh thu","B":"Giảm lòng trung thành","C":"Sự tước đoạt quyền lợi / đẩy cộng đồng yếu thế ra bên lề (Disenfranchisement)","D":"Sự xói mòn các quyền con người cơ bản (Erosion of rights)"},"answerDisplay":"C. Disenfranchisement & D. Erosion of rights","concept":"• Social Impact Failures: Disenfranchisement + Erosion of rights.","whyCorrect":"• Tước quyền lợi nhóm yếu thế và xói mòn nhân quyền.","whyWrong":{"A":"• Chỉ số tài chính.","B":"• Chỉ số tiếp thị."}}},{"id":54,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":54,"chooseType":"Choose 1 answer","question":"Management asks an employee to do a data-related task. Which of the following would likely be ethically problematic? (Select two.)","options":{"A":"Manipulate data or alter its interpretation","B":"Aggregate data together","C":"Change data to another format","D":"Delete inconvenient raw data while claiming it was erroneous"},"answer":"A, D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Quản lý yêu cầu nhân viên thực hiện một tác vụ dữ liệu. Những tác vụ nào sau đây có khả năng cao vi phạm đạo đức? (Select two)","optionsVi":{"A":"Thao túng dữ liệu hoặc làm sai lệch cách diễn giải (Manipulate data or alter interpretation)","B":"Gom tổng hợp dữ liệu","C":"Chuyển đổi định dạng","D":"Xóa dữ liệu thô không thuận lợi và gán nhãn giả là dữ liệu lỗi (Delete inconvenient data claimed as erroneous)"},"answerDisplay":"A. Manipulate data or alter its interpretation. & D. Delete any erroneous data (hoặc xóa dữ liệu cố ý)","concept":"• Data Manipulation & Fraud.","whyCorrect":"• Thao túng dữ liệu và xóa dữ liệu thực tế là hành vi gian lận.","whyWrong":{"B":"• Gom dữ liệu là chuẩn.","C":"• Chuyển định dạng là kỹ thuật chuẩn."}}},{"id":55,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":55,"chooseType":"Choose 1 answer","question":"Why are deep learning and traditional machine learning models called narrow AI? (Select two.)","options":{"A":"Narrow AI can only perform the specific tasks it was designed to do","B":"Narrow AI can't handle situations that its training data didn't prepare it for","C":"Narrow AI is dependent on hand-coding of algorithms","D":"Narrow AI cannot process text"},"answer":"A, B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Tại sao các mô hình học sâu và học máy truyền thống lại được gọi là AI hẹp (Narrow AI)? (Select two)","optionsVi":{"A":"AI hẹp chỉ có thể thực hiện các nhiệm vụ cụ thể mà nó được thiết kế để làm (only perform specific tasks designed to do)","B":"AI hẹp không thể xử lý các tình huống mà dữ liệu huấn luyện chưa chuẩn bị cho nó (can't handle situations training data didn't prepare for)","C":"AI hẹp phụ thuộc vào lập trình thủ công","D":"AI hẹp không xử lý được văn bản"},"answerDisplay":"A. Narrow can only perform the specific tasks it was designed to do. & B. Narrow Al cant handle situations that its training data didn't prepare it for","concept":"• Characteristics of Narrow AI: Chỉ giải quyết 1 tác vụ chuyên biệt và Thất bại khi gặp tình huống nằm ngoài phân bố huấn luyện (Out-of-distribution).","whyCorrect":"• Giới hạn trong nhiệm vụ thiết kế hẹp và thất bại khi gặp tình huống dữ liệu chưa được huấn luyện.","whyWrong":{"C":"• Học sâu tự động học thuộc tính chứ không lập trình thủ công.","D":"• AI hẹp xử lý văn bản cực tốt (như LLM)."}}},{"id":56,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":56,"chooseType":"Choose 1 answer","question":"Which of the following elements are important aspects of ethical integrity with regards to data? (Select two.)","options":{"A":"If the holders of data are trustworthy entities","B":"Whether the data was gathered in an ethical manner with informed consent","C":"If data is commercially viable","D":"What type of data is being collected"},"answer":"A, B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những yếu tố nào sau đây là khía cạnh quan trọng của sự liêm chính đạo đức (Ethical integrity) liên quan đến dữ liệu? (Select two)","optionsVi":{"A":"Liệu thực thể nắm giữ dữ liệu có phải là tổ chức đáng tin cậy hay không (holders of data are trustworthy entities)","B":"Liệu dữ liệu có được thu thập theo một cách thức có đạo đức và được sự đồng ý hay không (gathered in an ethical manner)","C":"Dữ liệu có thương mại hóa được không","D":"Loại dữ liệu thu thập là gì"},"answerDisplay":"A. If the holders of data are trusuorthy entities. & B. Whether the data was gathered in an ethical manner.","concept":"• Data Ethical Integrity: Đơn vị nắm giữ dữ liệu Đáng tin cậy (Trustworthy entity) và Phương thức thu thập Có đạo đức (Ethical collection).","whyCorrect":"• Thực thể nắm giữ uy tín và phương thức thu thập hợp đạo đức là 2 trụ cột liêm chính dữ liệu.","whyWrong":{"C":"• Thương mại hóa là chỉ số tài chính.","D":"• Định dạng dữ liệu là thuộc tính kỹ thuật."}}},{"id":57,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":57,"chooseType":"Choose 1 answer","question":"Which of the following are ways that legal regulations differ from ethical frameworks? (Select two.)","options":{"A":"Regulations are often industry led","B":"Regulations are flexible in implementation","C":"Regulations have mandatory legal enforcement behind them with penalties for violations","D":"Regulations provide a clear, formal basis for potential litigation and lawsuits"},"answer":"C, D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những điểm nào sau đây mô tả sự khác biệt giữa các quy định pháp lý (Regulations) và các khung đạo đức (Ethical frameworks)? (Select two)","optionsVi":{"A":"Quy định do ngành dẫn dắt","B":"Quy định linh hoạt trong áp dụng","C":"Các quy định có sức mạnh cưỡng chế pháp lý bắt buộc kèm theo chế tài xử phạt (legal enforcement behind them)","D":"Các quy định cung cấp một căn cứ pháp lý rõ ràng cho các vụ kiện tụng và tố tụng tòa án (clear basis for potential litigation)"},"answerDisplay":"C. Regulations have legal enforcement behind them. & D. Regulations provide a clear basis for potential litigation.","concept":"• Regulations vs Ethical Frameworks: Quy định pháp lý có Cưỡng chế trừng phạt (Legal enforcement) và Căn cứ kiện tụng (Basis for litigation), trong khi Khung đạo đức mang tính tự nguyện định hướng.","whyCorrect":"• Sức mạnh cưỡng chế xử phạt và căn cứ tố tụng tòa án là 2 điểm khác biệt bản chất của luật pháp.","whyWrong":{"A":"• Khung đạo đức thường do ngành tự phát động.","B":"• Khung đạo đức mới linh hoạt, luật pháp áp dụng cứng nhắc."}}},{"id":58,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":58,"chooseType":"Choose 1 answer","question":"Which of the following are important elements of the data minimization principle? (Select two.)","options":{"A":"Only collect data that is strictly necessary for stated purpose","B":"Only keep data for as long as it is needed to fulfill purpose","C":"Only delete data easily replaced","D":"Only compress data to keep small"},"answer":"A, B","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những yếu tố nào sau đây là thành phần quan trọng của nguyên tắc giảm thiểu dữ liệu (Data minimization)? (Select two)","optionsVi":{"A":"Chỉ thu thập dữ liệu tuyệt đối cần thiết cho mục đích công bố (Only collect data strictly necessary)","B":"Chỉ lưu trữ dữ liệu trong khoảng thời gian cần thiết để hoàn thành mục đích (Only keep data as long as needed)","C":"Chỉ xóa dữ liệu dễ thay thế","D":"Chỉ nén dữ liệu"},"answerDisplay":"A. Only collect data that is strictly necessary & B. Only keep data for as longas it is needed","concept":"• Data Minimization & Retention: Thu thập đúng mức cần thiết (Collection Minimization) và Hủy dữ liệu khi hết thời hạn mục đích (Storage Limitation).","whyCorrect":"• Thu thập tối thiểu và lưu trữ trong thời gian tối thiểu là 2 nguyên tắc giảm thiểu cốt lõi.","whyWrong":{"C":"• Tiêu chí xóa dữ liệu theo hạn lưu trữ chứ không theo độ khó thay thế.","D":"• Nén dữ liệu là kỹ thuật lưu trữ phần cứng."}}},{"id":59,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":59,"chooseType":"Choose 1 answer","question":"Which of the following are primary reasons to design, develop, and deploy a Code of Ethics within an organization? (Select two.)","options":{"A":"It compels employees to operate in an ethical manner","B":"It prevents regulatory scrutiny","C":"It lets external stakeholders know that you are an ethical company","D":"It creates consistency in ethical practices across the organization, rather than patchy implementation"},"answer":"C, D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những lý do chính nào để thiết kế, phát triển và triển khai một Bộ quy tắc đạo đức trong tổ chức? (Select two)","optionsVi":{"A":"Bắt buộc nhân viên làm việc đạo đức","B":"Ngăn thanh tra pháp lý","C":"Cho các bên liên quan bên ngoài biết rằng bạn là một công ty có đạo đức và trách nhiệm (lets external stakeholders know you are ethical company)","D":"Nó tạo ra sự nhất quán trong thực hành đạo đức trên toàn tổ chức thay vì áp dụng manh mún (creates consistency across organization)"},"answerDisplay":"C. It lets external stakeholders know that you are an ethical company. & D. It creates consistency in the ethical practices across the organization, rather than patchy implementation of the practices _","concept":"• Value of Code of Ethics: Xây dựng Uy tín với Bên ngoài (External Reputation) và Đảm bảo Tính nhất quán Nội bộ (Internal Consistency).","whyCorrect":"• Thể hiện cam kết với bên ngoài và duy trì tính nhất quán thực thi nội bộ.","whyWrong":{"A":"• Bộ quy tắc cung cấp định hướng chứ không tự cưỡng chế.","B":"• Không thể ngăn chặn thanh tra pháp lý."}}},{"id":60,"task":"fa24_fe_re","taskLabel":"FA24 FE RE","num":60,"chooseType":"Choose 1 answer","question":"Which of the following are actionable strategies that can help individuals combat their own implicit bias? (Select three.)","options":{"A":"Obtaining information from same sources","B":"Cultivating active self-awareness of your own personal biases","C":"Interacting with diverse groups of people from different backgrounds","D":"Exposing yourself to counter-stereotypical examples and stories"},"answer":"B, C, D","source":"ITE302c_FA24_FE_RE","explanation":{"questionVi":"Những hành động/chiến lược nào giúp cá nhân chủ động chống lại định kiến ẩn tàng (Implicit bias) của chính mình? (Select three)","optionsVi":{"A":"Thu thập thông tin từ một nguồn quen thuộc","B":"Rèn luyện sự tự nhận thức chủ động về các định kiến cá nhân của bản thân (Cultivating awareness of own biases)","C":"Tăng cường tương tác với các nhóm người đa dạng từ các nền tảng khác nhau (Interacting with diverse groups)","D":"Chủ động tiếp xúc với các ví dụ và câu chuyện phản-định-kiến (Exposing to counter-stereotypical examples)"},"answerDisplay":"B. Cultivating awareness of your own biases. & C. Interacting with diverse groups of people. & D. Exposing yourself to \"counter-stereotypical\" examples.","concept":"• Combating Implicit Bias: Tự nhận thức (Self-awareness), Tương tác đa dạng (Diverse interaction) và Tiếp xúc hình mẫu phản định kiến (Counter-stereotypical exposure).","whyCorrect":"• Ba chiến lược B, C, D là các phương pháp tâm lý học hành vi chứng minh hiệu quả triệt tiêu định kiến ẩn tàng.","whyWrong":{"A":"• Tiếp nhận thông tin từ một nguồn làm trầm trọng thêm định kiến (Echo chamber)."}}},{"id":1,"task":"fa24_fe","taskLabel":"FA24 FE","num":1,"chooseType":"Choose 1 answer","question":"What does the acronym SIEM stand for in a cybersecurity context?","options":{"A":"Selective information extrapolation methods","B":"Social, interpersonal, empathic, mental","C":"Security Information and Event Management","D":"Serial input to externalized modulation"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Từ viết tắt SIEM đại diện cho điều gì trong bối cảnh an ninh mạng?","optionsVi":{"A":"Phương pháp suy luận thông tin có chọn lọc","B":"Xã hội, tương tác, thấu cảm, tâm lý","C":"Quản lý Sự kiện và Thông tin An ninh (Security Information and Event Management)","D":"Đầu vào chuỗi để điều chế ngoài"},"answerDisplay":"C. Security Information and Event Management","concept":"• SIEM (Security Information and Event Management): Nền tảng an ninh mạng tổng hợp, tương quan và phân tích log sự kiện từ toàn bộ hạ tầng công nghệ.","whyCorrect":"• Định nghĩa chính xác tên gọi chuẩn của hệ thống SIEM trong an toàn thông tin.","whyWrong":{"A":"• Đây là tên gọi ngẫu nhiên.","B":"• Thuộc tính tâm lý xã hội không thuộc an ninh mạng.","D":"• Giao thức phần cứng viễn thông không liên quan."}}},{"id":2,"task":"fa24_fe","taskLabel":"FA24 FE","num":2,"chooseType":"Choose 1 answer","question":"The Data minimization principle requires that you limit data collection to only what is:","options":{"A":"Necessary for differential privacy","B":"Optional for a chain of command","C":"Needed to have k-anonymity","D":"Directly required to fulfill a specific, stated purpose"},"answer":"D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Nguyên tắc Giảm thiểu dữ liệu (Data minimization) yêu cầu bạn giới hạn việc thu thập dữ liệu chỉ trong phạm vi những gì:","optionsVi":{"A":"Cần thiết cho riêng tư vi sai","B":"Tùy chọn cho chuỗi chỉ huy","C":"Cần thiết để có k-anonymity","D":"Trực tiếp cần thiết để thực hiện mục đích cụ thể đã xác định (required to fulfill a specific purpose)"},"answerDisplay":"D. required to fulfill a specific purpose","concept":"• Data Minimization Principle: Thu thập đúng và đủ dữ liệu cần thiết cho mục đích công bố.","whyCorrect":"• Giới hạn thu thập đúng mục đích sử dụng là bản chất của Data Minimization.","whyWrong":{"A":"• Differential privacy là kỹ thuật toán học.","B":"• Chuỗi chỉ huy thuộc về cấu trúc tổ chức.","C":"• k-anonymity là mô hình ẩn danh dữ liệu."}}},{"id":3,"task":"fa24_fe","taskLabel":"FA24 FE","num":3,"chooseType":"Choose 1 answer","question":"Which of the following risk categories deals with stakeholder responsibility in creating and using data-driven technologies?","options":{"A":"Explainability","B":"Accountability","C":"Transparency","D":"Understandability"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Danh mục rủi ro nào xử lý trách nhiệm của các bên liên quan trong việc tạo ra và sử dụng công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Tính giải thích được","B":"Trách nhiệm giải trình (Accountability)","C":"Tính minh bạch","D":"Tính dễ hiểu"},"answerDisplay":"B. Accountability","concept":"• Accountability: Quy định rõ nghĩa vụ gánh chịu trách nhiệm đối với các tác động của hệ thống công nghệ.","whyCorrect":"• Định rõ ai chịu trách nhiệm cho các hậu quả của công nghệ.","whyWrong":{"A":"• Explainability là thuộc tính giải thích thuật toán.","C":"• Transparency là công khai thông tin.","D":"• Understandability là tính dễ tiếp thu."}}},{"id":4,"task":"fa24_fe","taskLabel":"FA24 FE","num":4,"chooseType":"Choose 1 answer","question":"What kind of shape does a normal distribution take on when plotted in a histogram?","options":{"A":"Tail shape","B":"Square shape","C":"Bell shape","D":"Tree shape"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Phân bố chuẩn (Normal distribution) có hình dạng như thế nào khi được biểu diễn trên biểu đồ cột (histogram)?","optionsVi":{"A":"Hình cái đuôi","B":"Hình vuông","C":"Hình quả chuông (Bell shape / Bell curve)","D":"Hình cây"},"answerDisplay":"C. Bell shape","concept":"• Gaussian Normal Distribution: Hình quả chuông đối xứng qua giá trị trung bình Mean.","whyCorrect":"• Hình quả chuông đối xứng đặc trưng của phân bố chuẩn.","whyWrong":{"A":"• Tail shape là phân bố lệch Skewed.","B":"• Square shape là phân bố đều Uniform.","D":"• Tree shape là cấu trúc cây."}}},{"id":5,"task":"fa24_fe","taskLabel":"FA24 FE","num":5,"chooseType":"Choose 1 answer","question":"Which of the following is a transparency risk of closed source software?","options":{"A":"Closed source software may not be accessible to independent auditors","B":"Closed source software cannot be shared with business partners","C":"Closed source software includes obfuscated code","D":"Closed source software cannot be reviewed by developing organization"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả rủi ro về tính minh bạch của phần mềm mã nguồn đóng (Closed source software)?","optionsVi":{"A":"Phần mềm mã nguồn đóng có thể không cho phép các kiểm toán viên độc lập bên ngoài truy cập xem xét (may not be accessible to independent auditors)","B":"Không thể chia sẻ với đối tác","C":"Chứa mã xáo trộn","D":"Không thể được xem xét bởi chính tổ chức phát triển"},"answerDisplay":"A. Closed source software may not be accessible to independent auditors.","concept":"• Closed Source Transparency Risk: Ngăn cản sự kiểm tra độc lập của bên thứ ba.","whyCorrect":"• Việc ngăn cấm kiểm toán viên độc lập kiểm tra mã nguồn tạo ra rủi ro thiếu minh bạch.","whyWrong":{"B":"• Vẫn chia sẻ qua hợp đồng thương mại.","C":"• Mã nguồn đóng lưu mã nhị phân.","D":"• Tổ chức tự phát triển hoàn toàn nắm mã nguồn."}}},{"id":6,"task":"fa24_fe","taskLabel":"FA24 FE","num":6,"chooseType":"Choose 1 answer","question":"An unfair model will by nature:","options":{"A":"Optimize for making fewest decisions","B":"Try to balance groups automatically","C":"Optimize for overall accuracy while concentrating errors on a specific subgroup","D":"Optimize for making fewest mistakes"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Một mô hình không công bằng (Unfair model) về mặt bản chất sẽ thực hiện việc tối ưu hóa nào?","optionsVi":{"A":"Tối ưu hóa ra ít quyết định","B":"Tự động cân bằng nhóm","C":"Tối ưu hóa độ chính xác chung bằng cách dồn sai số/lỗi lên một phân nhóm yếu thế cụ thể (concentrating errors on specific subgroup)","D":"Tối ưu hóa mắc ít lỗi nhất"},"answerDisplay":"C. optimize for overall accuracy while concentrating errors on a specific subgroup","concept":"• Unfair Model Behavior: Giữ chỉ số chung cao bằng cách dồn rủi ro thiệt hại lên phân nhóm thiểu số.","whyCorrect":"• Mô hình thiên vị dồn sai sót thiệt hại lên nhóm yếu thế.","whyWrong":{"A":"• Số lượng quyết định không phản ánh thiên vị.","B":"• Mô hình thiên vị không tự cân bằng.","D":"• Mắc ít lỗi nhất không đảm bảo lỗi được phân bố đều."}}},{"id":7,"task":"fa24_fe","taskLabel":"FA24 FE","num":7,"chooseType":"Choose 1 answer","question":"What can be learned from a predictive model should not change whether an individual's data is included or excluded in the training set. This concept refers to:","options":{"A":"Differential privacy","B":"Dataset filtering","C":"Biased dataset","D":"Model fairness score"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Những gì học được từ mô hình dự đoán không nên thay đổi bất kể dữ liệu của một cá nhân có xuất hiện hay bị loại khỏi tập huấn luyện hay không. Khái niệm này đề cập đến:","optionsVi":{"A":"Tính riêng tư vi sai (Differential privacy)","B":"Lọc tập dữ liệu","C":"Tập dữ liệu thiên vị","D":"Điểm công bằng mô hình"},"answerDisplay":"A. Differential privacy","concept":"• Core Differential Privacy Principle: Kết quả đầu ra mô hình không bị ảnh hưởng bởi sự có mặt hay vắng mặt của bất kỳ 1 cá nhân nào.","whyCorrect":"• Đảm bảo sự thêm hay bớt dữ liệu cá nhân không làm thay đổi kết quả dự đoán tổng thể.","whyWrong":{"B":"• Lọc dữ liệu là khâu tiền xử lý.","C":"• Tập dữ liệu thiên vị gây sai lệch mô hình.","D":"• Điểm công bằng đo lường độ bình đẳng."}}},{"id":8,"task":"fa24_fe","taskLabel":"FA24 FE","num":8,"chooseType":"Choose 1 answer","question":"Which of the following defines the AI black box problem?","options":{"A":"The challenge of understanding how complex machine learning algorithms make specific decisions","B":"Not knowing how something crashed","C":"Machine intelligence making illusory predictions","D":"A dangerous machine put in digital prison"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Nội dung nào sau đây định nghĩa bài toán Hộp đen (Black box problem) trong AI?","optionsVi":{"A":"Thách thức trong việc thấu hiểu cách các thuật toán học máy phức tạp đưa ra các quyết định cụ thể (challenge of understanding how algorithms make decisions)","B":"Không biết tại sao phần mềm sụp đổ","C":"Trí tuệ máy tạo dự đoán ảo","D":"Máy tính bị giam trong tù số"},"answerDisplay":"A. The challenge of understanding how complex ML algorithms make decisions.","concept":"• Black Box Problem: Không thể truy ngược logic toán học bên trong mạng nơ-ron phức tạp.","whyCorrect":"• Thách thức thấu hiểu cách mô hình đưa ra quyết định.","whyWrong":{"B":"• Phần mềm crash là lỗi lập trình Exception.","C":"• Dự đoán ảo là Ảo giác AI Hallucination.","D":"• Tù số là khái niệm viễn tưởng."}}},{"id":9,"task":"fa24_fe","taskLabel":"FA24 FE","num":9,"chooseType":"Choose 1 answer","question":"A type of artificial intelligence that outperforms humans in specific defined tasks is known as:","options":{"A":"General AI","B":"Narrow AI","C":"AEI","D":"Special AI"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Loại trí tuệ nhân tạo vượt trội hơn con người trong một số nhiệm vụ cụ thể được gọi là gì?","optionsVi":{"A":"AI tổng quát (General AI)","B":"AI hẹp / AI chuyên biệt (Narrow AI)","C":"AEI","D":"AI đặc biệt"},"answerDisplay":"B. Narrow Al","concept":"• Narrow AI: Trí tuệ chuyên biệt một tác vụ duy nhất.","whyCorrect":"• Định nghĩa chuẩn của Narrow AI.","whyWrong":{"A":"• General AI có năng lực đa nhiệm như con người.","C":"• AEI không phải thuật ngữ AI tiêu chuẩn.","D":"• Special AI không phải thuật ngữ học thuật."}}},{"id":10,"task":"fa24_fe","taskLabel":"FA24 FE","num":10,"chooseType":"Choose 1 answer","question":"When building a predictive model, what is the goal of the training phase?","options":{"A":"To specify algorithm and clean data","B":"To adjust the model based on a subset of data, optimizing for a lower error rate","C":"To use the model in real-world scenarios","D":"To adjust training methods from backpropagation to supervised learning"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Khi xây dựng một mô hình dự đoán, mục tiêu của giai đoạn huấn luyện (Training phase) là gì?","optionsVi":{"A":"Chỉ định thuật toán và làm sạch dữ liệu","B":"Điều chỉnh các trọng số mô hình dựa trên tập dữ liệu huấn luyện, tối ưu hóa để đạt tỷ lệ lỗi sai thấp nhất (adjust model, optimizing for lower error rate)","C":"Sử dụng mô hình trong kịch bản thực tế","D":"Chuyển đổi phương pháp huấn luyện"},"answerDisplay":"B. To adjust the model based on a subset of data, optimizing for a lower error rate","concept":"• Goal of Training: Cập nhật trọng số tham số để hạ thấp hàm sai số Loss.","whyCorrect":"• Tối ưu hóa trọng số mô hình để giảm tỷ lệ sai số.","whyWrong":{"A":"• Chọn thuật toán là khâu chuẩn bị.","C":"• Sử dụng thực tế là pha triển khai Deployment.","D":"• Backpropagation thuộc Supervised Learning."}}},{"id":11,"task":"fa24_fe","taskLabel":"FA24 FE","num":11,"chooseType":"Choose 1 answer","question":"Pseudocode can best be defined as:","options":{"A":"An explainable description of code that is meant for humans, not computers","B":"A Python library for machine learning","C":"A middle ground between code and plain writing fed into computers","D":"A type of Javascript"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Mã giả (Pseudocode) được định nghĩa đúng nhất là gì?","optionsVi":{"A":"Mô tả thuật toán có thể giải thích được dành cho con người đọc hiểu, không dùng cho máy tính (meant for humans, not computers)","B":"Thư viện Python","C":"Ngôn ngữ trung gian nạp vào máy tính","D":"Loại Javascript"},"answerDisplay":"A. an explainable description of code that is meant for humans, not computers","concept":"• Pseudocode: Mã giả mô tả thuật toán bằng ngôn ngữ tự nhiên dành cho con người thấu hiểu.","whyCorrect":"• Dành cho con người đọc hiểu chứ không thực thi trực tiếp trên máy.","whyWrong":{"B":"• Không phải thư viện lập trình.","C":"• Máy tính không thực thi trực tiếp mã giả.","D":"• Không phải ngôn ngữ Javascript."}}},{"id":12,"task":"fa24_fe","taskLabel":"FA24 FE","num":12,"chooseType":"Choose 1 answer","question":"To measure a predictive model's accuracy, you:","options":{"A":"Divide number of predictions by total dataset","B":"Measure ratio of error curve","C":"Multiply predictions by percentage","D":"Divide the number of correct predictions by the total number of predictions"},"answer":"D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Để đo lường độ chính xác (Accuracy) của một mô hình dự đoán, bạn thực hiện phép tính nào?","optionsVi":{"A":"Chia số dự đoán cho tổng tập dữ liệu","B":"Đo tỷ lệ đường cong lỗi","C":"Nhân tổng dự đoán với phần trăm đúng","D":"Chia số lượng dự đoán đúng cho tổng số lượng dự đoán (Divide correct predictions by total predictions)"},"answerDisplay":"D. divide the number of correct predictions by the total number of predictions","concept":"• Accuracy Formula: (Correct Predictions) / (Total Predictions).","whyCorrect":"• Phép chia số dự đoán đúng cho tổng số lần dự đoán ra tỷ lệ độ chính xác.","whyWrong":{"A":"• Phép chia không tính đến dự đoán đúng.","B":"• Đường cong lỗi đo Loss curve.","C":"• Phép nhân không ra công thức Accuracy."}}},{"id":13,"task":"fa24_fe","taskLabel":"FA24 FE","num":13,"chooseType":"Choose 1 answer","question":"Which of the following is a good example of a feedback loop in machine learning?","options":{"A":"A shopping app surfaces items based on profiles","B":"A shopping app tracks purchases","C":"A social media site tracks engagement, uses an algorithm to surface posts you're likely to engage with, which then goes back into the algorithm","D":"A site surfaces controversial posts"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Ví dụ nào sau đây là một minh họa rõ ràng về Vòng lặp phản hồi (Feedback loop) trong học máy?","optionsVi":{"A":"App mua sắm gợi ý món đồ","B":"App mua sắm theo dõi đơn hàng","C":"Trang mạng xã hội theo dõi tương tác, dùng thuật toán đẩy các bài viết bạn dễ tương tác, thông tin tương tác đó lại tiếp tục nạp ngược vào thuật toán (goes back into algorithm)","D":"Trang web gợi ý bài viết gây tranh cãi"},"answerDisplay":"C. A social media site tracks engagement, uses an algorithm to surface posts you're likely to engage with, which then goes back into the algorithm","concept":"• Feedback Loop: Dữ liệu hành vi đầu ra nạp ngược lại làm dữ liệu huấn luyện đầu vào cho thuật toán.","whyCorrect":"• Tương tác người dùng nạp ngược lại vào thuật toán để tiếp tục huấn luyện củng cố.","whyWrong":{"A":"• Gợi ý cơ bản không có tính củng cố vòng lặp.","B":"• Theo dõi đơn thuần là dữ liệu tĩnh.","D":"• Bài viết tranh cãi là chiến lược nội dung."}}},{"id":14,"task":"fa24_fe","taskLabel":"FA24 FE","num":14,"chooseType":"Choose 1 answer","question":"Which of the following is one explanation for why cognitive biases exist in human reasoning?","options":{"A":"We use mental shortcuts (heuristics) to make decisions efficiently under information overload and limited time","B":"We use them to help remember things","C":"They help us think logically","D":"They are taught to us in school"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Giải thích nào sau đây mô tả lý do tại sao Định kiến nhận thức (Cognitive biases) tồn tại trong lập luận của con người?","optionsVi":{"A":"Con người sử dụng các lối tắt tư duy (heuristics) để đưa ra quyết định nhanh chóng trong điều kiện quá tải thông tin và giới hạn thời gian (mental shortcuts for efficiency)","B":"Dùng để nhớ đồ vật","C":"Giúp tư duy logic","D":"Được dạy ở trường học"},"answerDisplay":"A. We use mental shortcuts to make decisions efficiently.","concept":"• Heuristics & Cognitive Biases: Lối tắt nhận thức giúp não bộ xử lý thông tin nhanh, vô tình tạo ra định kiến sai lệch.","whyCorrect":"• Sử dụng lối tắt tư duy ra quyết định nhanh là nguyên nhân gốc rễ sinh ra định kiến nhận thức.","whyWrong":{"B":"• Không phải công cụ lưu trí nhớ.","C":"• Đi ngược lại với logic thuần túy.","D":"• Đây là cơ chế tâm lý tự nhiên."}}},{"id":15,"task":"fa24_fe","taskLabel":"FA24 FE","num":15,"chooseType":"Choose 1 answer","question":"Dating algorithms become biased mostly through offering users:","options":{"A":"Collaborative filtering that reinforces existing stereotypes","B":"Access to separate data models","C":"Different ways to match","D":"Unlimited matches per day"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Các thuật toán hẹn hò trở nên bị thiên vị chủ yếu thông qua việc cung cấp cho người dùng tính năng gì?","optionsVi":{"A":"Lọc cộng tác (Collaborative filtering) củng cố các định kiến hấp dẫn sẵn có","B":"Truy cập mô hình dữ liệu riêng","C":"Các cách ghép đôi khác nhau","D":"Không giới hạn lượt ghép đôi"},"answerDisplay":"A. collaborative filtering","concept":"• Collaborative Filtering Bias: Tự động nhân rộng các thiên vị dựa trên hành vi quẹt thẻ của số đông.","whyCorrect":"• Lọc cộng tác củng cố các định kiến xã hội vốn có trong dữ liệu.","whyWrong":{"B":"• Mô hình riêng là kiến trúc hệ thống.","C":"• Cách match là giao diện người dùng.","D":"• Lượt match không sinh thiên vị nhóm."}}},{"id":16,"task":"fa24_fe","taskLabel":"FA24 FE","num":16,"chooseType":"Choose 1 answer","question":"How does the 'virtuous cycle' that benefits Big Tech operate?","options":{"A":"Organizations write algorithms with fewer biases","B":"By acting virtuous, public respects Big Tech","C":"Better classes of customers lead to richer data","D":"Data-driven algorithms improve solutions, leading to new customers, and better data"},"answer":"D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Chu trình tăng trưởng độc quyền ('Virtuous Cycle') mang lại lợi ích cho các tập đoàn Big Tech vận hành như thế nào?","optionsVi":{"A":"Tổ chức viết thuật toán ít thiên vị","B":"Công chúng tôn trọng Big Tech hơn","C":"Khách hàng tốt mang lại dữ liệu phong phú","D":"Thuật toán dựa trên dữ liệu cải thiện giải pháp -> Thu hút khách hàng mới -> Thu thập thêm dữ liệu tốt hơn (Data -> Product -> Users -> More Data)"},"answerDisplay":"D. Data-driven algorithms improve solutions, leading to new customers, and better data.","concept":"• Data Flywheel Effect: Dữ liệu -> Sản phẩm tốt -> Nhiều người dùng -> Thêm dữ liệu độc quyền.","whyCorrect":"• Chu trình tự củng cố giữa dữ liệu, chất lượng sản phẩm và người dùng tạo lợi thế độc quyền.","whyWrong":{"A":"• Viết thuật toán ít thiên vị là mục tiêu đạo đức.","B":"• Tôn trọng là hiệu ứng thương hiệu.","C":"• Khách hàng giàu không phải nguyên nhân cốt lõi."}}},{"id":17,"task":"fa24_fe","taskLabel":"FA24 FE","num":17,"chooseType":"Choose 1 answer","question":"A model that equalizes the number of mistakes it makes for each subgroup to reduce harm is deciding on:","options":{"A":"Equality of true outcomes","B":"Equality of false negatives","C":"Equality of training data","D":"Equality of prediction bias"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Một mô hình cân bằng số lượng sai sót mà nó mắc phải cho mỗi nhóm nhỏ để giảm thiểu tổn hại là đang quyết định về tiêu chuẩn nào?","optionsVi":{"A":"Bình đẳng kết quả thực tế","B":"Bình đẳng âm tính giả (Equality of false negatives)","C":"Bình đẳng dữ liệu huấn luyện","D":"Bình đẳng thiên vị dự đoán"},"answerDisplay":"B. equality of false negatives","concept":"• Equality of False Negatives: Cân bằng tỷ lệ bỏ sót sai sót gây hại ngang nhau giữa các nhóm.","whyCorrect":"• Đảm bảo rủi ro bỏ sót tổn hại không dồn lên một nhóm yếu thế cụ thể.","whyWrong":{"A":"• Bình đẳng kết quả là Equalized Odds.","C":"• Dữ liệu huấn luyện là phân phối mẫu.","D":"• Thiên vị dự đoán là chỉ số đo chung."}}},{"id":18,"task":"fa24_fe","taskLabel":"FA24 FE","num":18,"chooseType":"Choose 1 answer","question":"If your company needs to perform the exact same automated analysis as new data arrives periodically every month, what is the best term to describe that process?","options":{"A":"Data Pipeline","B":"Workflow","C":"Swimlane","D":"Use case"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Nếu công ty bạn cần thực hiện cùng một quy trình phân tích tự động khi dữ liệu mới đổ về hàng tháng, thuật ngữ nào mô tả đúng nhất quy trình đó?","optionsVi":{"A":"Đường ống xử lý dữ liệu (Data Pipeline)","B":"Luồng công việc (Workflow)","C":"Làn bơi (Swimlane)","D":"Tình huống sử dụng (Use case)"},"answerDisplay":"A. pipeline","concept":"• Data Pipeline: Chuỗi tự động hóa thu thập, làm sạch và phân tích dữ liệu lặp đi lặp lại theo định kỳ.","whyCorrect":"• Tự động hóa quy trình phân tích dữ liệu đầu vào định kỳ là bản chất của Data Pipeline.","whyWrong":{"B":"• Workflow là quy trình làm việc con người.","C":"• Swimlane là sơ đồ phân công.","D":"• Use case là kịch bản phần mềm."}}},{"id":19,"task":"fa24_fe","taskLabel":"FA24 FE","num":19,"chooseType":"Choose 1 answer","question":"A predictive model's true positive result can be defined as:","options":{"A":"Predicted negative, actual negative","B":"Predicted negative, actual positive","C":"The predicted result was positive, and the actual result was positive","D":"Predicted positive, actual negative"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Kết quả Dương tính thật (True Positive) của một mô hình dự đoán được định nghĩa là gì?","optionsVi":{"A":"Dự đoán âm tính, thực tế âm tính (True Negative)","B":"Dự đoán âm tính, thực tế dương tính (False Negative)","C":"Kết quả dự đoán là dương tính và kết quả thực tế cũng là dương tính (predicted positive, actual positive)","D":"Dự đoán dương tính, thực tế âm tính (False Positive)"},"answerDisplay":"C. the predicted result was positive, and the actual result was positive","concept":"• Confusion Matrix Metrics: True Positive (TP) = Dự đoán Dương tính VÀ Thực tế Dương tính.","whyCorrect":"• Định nghĩa chính xác của chỉ số True Positive trong Ma trận nhầm lẫn.","whyWrong":{"A":"• Đây là True Negative (TN).","B":"• Đây là False Negative (FN).","D":"• Đây là False Positive (FP)."}}},{"id":20,"task":"fa24_fe","taskLabel":"FA24 FE","num":20,"chooseType":"Choose 1 answer","question":"What is ambient intelligence?","options":{"A":"Linked IoT collecting home data","B":"Linked IoT conducting government surveillance","C":"Linked IoT technology that is always on and acting to personalize the experience for people within its environment","D":"Linked IoT collecting campus data"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Trí tuệ môi trường (Ambient Intelligence) được định nghĩa là gì?","optionsVi":{"A":"Công nghệ IoT thu thập dữ liệu nhà ở","B":"Công nghệ IoT giám sát lén lút","C":"Mạng lưới công nghệ IoT kết nối luôn bật và chủ động tương tác để cá nhân hóa trải nghiệm cho con người trong môi trường sống (always on and acting to personalize experience)","D":"Công nghệ IoT thu thập dữ liệu khuôn viên"},"answerDisplay":"C. Linked IOT technology that always on and acting to personalize the experience for the people within its environment","concept":"• Ambient Intelligence (AmI): Môi trường thông minh luôn bật để tự động cá nhân hóa trải nghiệm.","whyCorrect":"• Tính chất luôn bật và tự động cá nhân hóa môi trường sống cho con người.","whyWrong":{"A":"• Thu thập dữ liệu nhà ở là Smart Home cơ bản.","B":"• Giám sát lén lút là Mass Surveillance.","D":"• Dữ liệu khuôn viên là Campus IoT."}}},{"id":21,"task":"fa24_fe","taskLabel":"FA24 FE","num":21,"chooseType":"Choose 1 answer","question":"What does 'Ethics by Design' mean in software development?","options":{"A":"Tenet of engineering activism","B":"An approach in which ethical considerations are integrated proactively from the initial design stage of a product","C":"A creative design approach","D":"Reference to IEEE framework"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"'Đạo đức theo thiết kế' (Ethics by Design) có nghĩa là gì trong phát triển phần mềm?","optionsVi":{"A":"Nguyên lý hoạt động kỹ thuật","B":"Cách tiếp cận trong đó các xem xét đạo đức được chủ động tích hợp ngay từ giai đoạn thiết kế ban đầu của sản phẩm (ethical considerations integrated from initial design stage)","C":"Cách tiếp cận thiết kế sáng tạo","D":"Tài liệu tham khảo IEEE"},"answerDisplay":"B. An approach in which ethics is considered from the initial design stage.","concept":"• Ethics by Design: Tích hợp chủ động tiêu chuẩn đạo đức và quyền riêng tư ngay từ khâu phác thảo thiết kế hệ thống.","whyCorrect":"• Chủ động cân nhắc đạo đức ngay từ giai đoạn ý tưởng thiết kế đầu tiên.","whyWrong":{"A":"• Không phải khẩu hiệu hoạt động.","C":"• Không chỉ dừng ở mảng sáng tạo đồ họa.","D":"• IEEE cung cấp khung hỗ trợ chứ không định nghĩa hẹp thuật ngữ này."}}},{"id":22,"task":"fa24_fe","taskLabel":"FA24 FE","num":22,"chooseType":"Choose 1 answer","question":"What are the attributes of an error function when training a predictive model?","options":{"A":"Percentage of formatted data","B":"The percentage or degree to which predictions deviate from actual outcomes","C":"Ratio of algorithm to curve","D":"Ratio of training data to consumed data"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Các thuộc tính của một hàm sai số (Error function) khi huấn luyện mô hình dự đoán thể hiện điều gì?","optionsVi":{"A":"Tỷ lệ dữ liệu định dạng đúng","B":"Tỷ lệ hoặc mức độ mà các dự đoán của mô hình bị lệch so với kết quả thực tế (percentage of predictions that don't match actual outcomes)","C":"Tỷ lệ thuật toán trên đường cong","D":"Tỷ lệ dữ liệu huấn luyện"},"answerDisplay":"B. the percentage of predictions that don't match actual outcomes","concept":"• Error / Loss Function: Đo lường mức độ sai lệch giữa dự đoán (Prediction) và thực tế (Ground truth).","whyCorrect":"• Đo lường tỷ lệ/mức độ dự đoán không khớp với kết quả thực tế.","whyWrong":{"A":"• Định dạng dữ liệu thuộc tiền xử lý.","C":"• Không có tỷ lệ thuật toán trên đường cong.","D":"• Tỷ lệ dữ liệu thuộc khai thác mẫu."}}},{"id":23,"task":"fa24_fe","taskLabel":"FA24 FE","num":23,"chooseType":"Choose 1 answer","question":"At what point should ethical consideration ideally be applied to emerging technologies?","options":{"A":"Once an ethical issue receives negative feedback","B":"Upon delivery","C":"During periodic reviews","D":"From its inception and design, through maintenance, to applying foresight regarding its decommissioning"},"answer":"D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Tại thời điểm nào các xem xét đạo đức nên được áp dụng lý tưởng cho các công nghệ mới nổi?","optionsVi":{"A":"Khi gặp phản hồi tiêu cực","B":"Khi bàn giao sản phẩm","C":"Trong các đợt xem xét định kỳ","D":"Xuyên suốt từ khi hình thành ý tưởng, qua quá trình bảo trì, cho đến khi ngừng vận hành hoàn toàn (From inception through maintenance to decommissioning)"},"answerDisplay":"D. From its inception, through maintenance, to applying foresight regarding its decommissioning.","concept":"• Lifecycle Ethical Governance: Đạo đức phải được lồng ghép trong suốt toàn bộ vòng đời sản phẩm (Inception -> Maintenance -> Decommissioning).","whyCorrect":"• Bao phủ toàn bộ vòng đời từ khâu ý tưởng đến khi loại bỏ công nghệ.","whyWrong":{"A":"• Phản ứng sau khi bùng phát sự cố là bị động.","B":"• Bàn giao mới xem xét đạo đức là quá muộn.","C":"• Xem xét định kỳ là chưa đủ nếu bỏ qua khâu thiết kế ban đầu."}}},{"id":24,"task":"fa24_fe","taskLabel":"FA24 FE","num":24,"chooseType":"Choose 1 answer","question":"Our goals for building an ethical predictive model include making sure the results are:","options":{"A":"Precise, explainable, predictable","B":"Accurate, precise, fair","C":"Precise, methodical, ethical","D":"Accurate, fair, and explainable"},"answer":"D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Mục tiêu khi xây dựng một mô hình dự đoán có đạo đức bao gồm việc đảm bảo kết quả đạt 3 tiêu chí nào?","optionsVi":{"A":"Chính xác, giải thích được, dự đoán được","B":"Chính xác, chuẩn xác, công bằng","C":"Chuẩn xác, bài bản, đạo đức","D":"Chính xác (Accurate), Công bằng (Fair) và Giải thích được (Explainable)"},"answerDisplay":"D. accurate, fair and explainable","concept":"• Trụ cột AI Đạo đức: Accuracy + Fairness + Explainability.","whyCorrect":"• Ba tiêu chuẩn cốt lõi của một mô hình dự đoán có trách nhiệm.","whyWrong":{"A":"• Thiếu tiêu chuẩn công bằng.","B":"• Thiếu tiêu chuẩn giải thích được.","C":"• Thiếu tiêu chuẩn công bằng."}}},{"id":25,"task":"fa24_fe","taskLabel":"FA24 FE","num":25,"chooseType":"Choose 1 answer","question":"What side effect of learning algorithms creates an ethical dilemma regarding user privacy?","options":{"A":"Learning algorithms require high computing power","B":"Learning algorithms require large datasets, which often means storing personally identifying information about users","C":"Learning algorithms require government regulation","D":"Learning algorithms require fast internet"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Tác dụng phụ nào của các thuật toán học máy tạo ra một tình huống tiến thoái lưỡng nan về đạo đức riêng tư cho người dùng?","optionsVi":{"A":"Thuật toán yêu cầu năng lượng tính toán cao","B":"Các thuật toán học máy yêu cầu các tập dữ liệu khổng lồ, đồng nghĩa với việc thu thập và lưu trữ thông tin định danh cá nhân của người dùng (require large datasets, storing identifying information)","C":"Thuật toán yêu cầu chính phủ quản lý","D":"Thuật toán cần mạng nhanh"},"answerDisplay":"B. Learning algorithms require large datasets, which means storing identifying information about users","concept":"• Big Data Privacy Dilemma: Học máy càng thông minh càng thèm khát lượng lớn dữ liệu cá nhân, trực tiếp đe dọa quyền riêng tư.","whyCorrect":"• Nhu cầu nạp dữ liệu khổng lồ đe dọa trực tiếp quyền riêng tư cá nhân.","whyWrong":{"A":"• Năng lượng tính toán thuộc về rủi ro môi trường.","C":"• Quản lý chính phủ là giải pháp pháp lý.","D":"• Mạng nhanh là hạ tầng viễn thông."}}},{"id":26,"task":"fa24_fe","taskLabel":"FA24 FE","num":26,"chooseType":"Choose 1 answer","question":"Which of the following is a good example of a feedback loop in machine learning?","options":{"A":"Shopping app surfaces items based on profiles","B":"Shopping app tracks purchases","C":"A social media site tracks engagement, uses an algorithm to surface posts you're likely to engage with, which then goes back into the algorithm","D":"Site surfaces controversial posts"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Ví dụ nào sau đây là một minh họa rõ ràng về Vòng lặp phản hồi (Feedback loop) trong học máy?","optionsVi":{"A":"App mua sắm gợi ý món đồ","B":"App mua sắm theo dõi đơn hàng","C":"Trang mạng xã hội theo dõi tương tác, dùng thuật toán đẩy bài viết bạn dễ tương tác, thông tin tương tác đó lại tiếp tục nạp ngược vào thuật toán (goes back into algorithm)","D":"Trang web gợi ý bài viết gây tranh cãi"},"answerDisplay":"C. A social media site tracks engagement, uses an algorithm to surface posts you're likely to engage with, which then goes back into the algorithm","concept":"• Feedback Loop: Dữ liệu hành vi đầu ra nạp ngược lại làm dữ liệu đầu vào.","whyCorrect":"• Tương tác người dùng nạp ngược lại vào thuật toán để tiếp tục huấn luyện.","whyWrong":{"A":"• Gợi ý đơn thuần không có tính củng cố vòng lặp.","B":"• Ghi nhận dữ liệu tĩnh.","D":"• Chiến lược nội dung."}}},{"id":27,"task":"fa24_fe","taskLabel":"FA24 FE","num":27,"chooseType":"Choose 1 answer","question":"What's the primary functional difference between a basic algorithm and a complex learning algorithm?","options":{"A":"A basic algorithm has a set amount of choices to optimize for, while a complex algorithm is given freedom to discover its own features and representations","B":"Basic takes single input, complex takes multiple inputs","C":"Basic handles numbers, complex handles pictures","D":"Basic has 5 steps, complex has 15 steps"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Sự khác biệt chức năng chính giữa một thuật toán cơ bản và một thuật toán học máy phức tạp là gì?","optionsVi":{"A":"Thuật toán cơ bản có một số lượng lựa chọn cố định để tối ưu hóa, trong khi thuật toán học máy phức tạp được tự do tự phát hiện các thuộc tính và biểu diễn dữ liệu (basic has set choices vs complex given freedom to discover features)","B":"Cơ bản nhận 1 đầu vào, phức tạp nhận nhiều đầu vào","C":"Cơ bản xử lý số, phức tạp xử lý ảnh","D":"Cơ bản có 5 bước, phức tạp có 15 bước"},"answerDisplay":"A. A basic algorithm has a set amount of choices to optimize for, while a complex algorithm is given the freedom to find its own model","concept":"• Representation Learning: Thuật toán phức tạp (Deep Learning) tự động học các biểu diễn thuộc tính từ dữ liệu thô.","whyCorrect":"• Tự do khám phá và học các biểu diễn đặc trưng là bản chất của thuật toán học phức tạp.","whyWrong":{"B":"• Thuật toán cơ bản vẫn nhận nhiều biến đầu vào.","C":"• Thuật toán cơ bản vẫn xử lý hình ảnh.","D":"• Số bước không quyết định bản chất phức tạp."}}},{"id":28,"task":"fa24_fe","taskLabel":"FA24 FE","num":28,"chooseType":"Choose 1 answer","question":"How does a smart contract differ from a traditional contract?","options":{"A":"Smart contracts serve a different purpose","B":"Smart contracts eliminate the need for a central trusted authority by executing automatically via code","C":"Smart contracts are more effective","D":"Smart contracts guarantee anonymity"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Hợp đồng thông minh (Smart contract) khác biệt như thế nào so với hợp đồng truyền thống?","optionsVi":{"A":"Phục vụ mục đích khác","B":"Loại bỏ nhu cầu về một cơ quan thẩm quyền trung gian nhờ tự động thực thi bằng mã code (eliminate the need for a central authority)","C":"Hiệu quả hơn","D":"Đảm bảo ẩn danh"},"answerDisplay":"B. Smart contracts eliminate the need for a central authority.","concept":"• Smart Contracts: Tự động thực thi mã nguồn trên Blockchain không cần bên trung gian.","whyCorrect":"• Loại bỏ vai trò của bên trung gian phân xử.","whyWrong":{"A":"• Cả hai đều nhằm giao kết cam kết.","C":"• Hiệu quả phụ thuộc vào mã nguồn.","D":"• Tính ẩn danh không bắt buộc."}}},{"id":29,"task":"fa24_fe","taskLabel":"FA24 FE","num":29,"chooseType":"Choose 1 answer","question":"In empirical studies of AI ethical frameworks, what percentage of major frameworks include 'Transparency' as a core principle?","options":{"A":"Over 75% (Around 73-80% of frameworks)","B":"25%","C":"50%","D":"100%"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Trong các nghiên cứu thực nghiệm về các khung đạo đức AI, tỷ lệ phần trăm các khung làm việc chính đưa 'Tính minh bạch' (Transparency) vào làm nguyên tắc cốt lõi là bao nhiêu?","optionsVi":{"A":"Trên 75% (Khoảng 73-80% các khung đạo đức toàn cầu đều có Transparency)","B":"25%","C":"50%","D":"100%"},"answerDisplay":"A. 75%","concept":"• Prevalence of Transparency in AI Guidelines: Thống kê cho thấy hơn 75% tất cả các bộ nguyên tắc đạo đức AI trên thế giới đều chọn Transparency là trụ cột bắt buộc.","whyCorrect":"• Con số thống kê 75%+ phản ánh sự đồng thuận áp đảo toàn cầu về tính minh bạch.","whyWrong":{"B":"• 25% quá thấp.","C":"• 50% chưa phản ánh sự phổ biến.","D":"• 100% không chính xác vì có một số bộ quy tắc chỉ tập trung an toàn."}}},{"id":30,"task":"fa24_fe","taskLabel":"FA24 FE","num":30,"chooseType":"Choose 1 answer","question":"A model that equalizes the number of mistakes it makes for each subgroup to reduce harm is deciding on:","options":{"A":"Equality of true outcomes","B":"Equality of false negatives","C":"Equality of training data","D":"Equality of prediction bias"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Một mô hình cân bằng số lượng sai sót mà nó mắc phải cho mỗi nhóm nhỏ để giảm thiểu tổn hại là đang quyết định về tiêu chuẩn nào?","optionsVi":{"A":"Bình đẳng kết quả thực tế","B":"Bình đẳng âm tính giả (Equality of false negatives)","C":"Bình đẳng dữ liệu huấn luyện","D":"Bình đẳng thiên vị dự đoán"},"answerDisplay":"B. equality of false negatives","concept":"• Equality of False Negatives: Cân bằng tỷ lệ bỏ sót sai sót gây hại ngang nhau giữa các nhóm.","whyCorrect":"• Cân bằng tỷ lệ Âm tính giả giữa các nhóm.","whyWrong":{"A":"• Equalized Odds.","C":"• Dữ liệu huấn luyện là phân phối mẫu.","D":"• Thiên vị dự đoán là chỉ số đo chung."}}},{"id":31,"task":"fa24_fe","taskLabel":"FA24 FE","num":31,"chooseType":"Choose 1 answer","question":"In Game Theory applied to AI ethics, outcomes that are best for the collective group can be obscured by outcomes best for:","options":{"A":"The dataset","B":"The model","C":"The individual (Individual self-interest)","D":"The algorithm"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Trong Lý thuyết Trò chơi áp dụng cho đạo đức AI, các kết quả tốt nhất cho tập thể nhóm có thể bị che lấp bởi các kết quả tốt nhất cho:","optionsVi":{"A":"Tập dữ liệu","B":"Mô hình","C":"Tự lợi của cá nhân (The individual)","D":"Thuật toán"},"answerDisplay":"C. the individual","concept":"• Game Theory & Tragedy of the Commons: Khi mỗi cá nhân tối ưu hóa tự lợi cá nhân (Individual), kết quả chung của toàn nhóm (Group) bị suy giảm.","whyCorrect":"• Sự xung đột giữa tự lợi cá nhân ngắn hạn và lợi ích tập thể.","whyWrong":{"A":"• Dữ liệu là đối tượng.","B":"• Mô hình là công cụ.","D":"• Thuật toán không có tư lợi."}}},{"id":32,"task":"fa24_fe","taskLabel":"FA24 FE","num":32,"chooseType":"Choose 1 answer","question":"An auditing model used to adjust model predictions or decision thresholds after training is an example of a:","options":{"A":"Sub-processing bias mitigation method","B":"In-processing bias mitigation method","C":"Post-processing bias mitigation method","D":"Pre-processing bias mitigation method"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Một mô hình kiểm toán được sử dụng để điều chỉnh dự đoán hoặc ngưỡng ra quyết định sau khi mô hình đã huấn luyện xong là ví dụ về phương pháp giảm thiểu thiên vị nào?","optionsVi":{"A":"Phương pháp giảm thiểu phụ","B":"Phương pháp giảm thiểu trong quá trình (In-processing)","C":"Phương pháp giảm thiểu sau xử lý (Post-processing bias mitigation)","D":"Phương pháp giảm thiểu tiền xử lý (Pre-processing)"},"answerDisplay":"C. post-processing","concept":"• Bias Mitigation Stages: Pre-processing (Can thiệp dữ liệu), In-processing (Can thiệp thuật toán/hàm lỗi), Post-processing (Can thiệp kết quả đầu ra sau huấn luyện).","whyCorrect":"• Điều chỉnh dự đoán/ngưỡng sau khi mô hình đã huấn luyện xong thuộc về Post-processing.","whyWrong":{"A":"• Không có khái niệm sub-processing.","B":"• In-processing can thiệp trong lúc đang huấn luyện.","D":"• Pre-processing can thiệp vào tập dữ liệu thô trước huấn luyện."}}},{"id":33,"task":"fa24_fe","taskLabel":"FA24 FE","num":33,"chooseType":"Choose 1 answer","question":"Which school of philosophical thought primarily advocates for a global moral code based on duty?","options":{"A":"Utilitarianism","B":"Deontology","C":"Virtue ethics","D":"Virtual ethics"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Trường phái tư tưởng triết học nào chủ yếu cổ vũ cho một bộ quy tắc đạo đức toàn cầu dựa trên nghĩa vụ?","optionsVi":{"A":"Thuyết vị lợi","B":"Thuyết nghĩa vụ luận (Deontology)","C":"Thuyết đạo đức đức hạnh","D":"Đạo đức ảo"},"answerDisplay":"B. Deontology","concept":"• Deontology: Đạo đức dựa trên nghĩa vụ tuyệt đối.","whyCorrect":"• Nghĩa vụ luận đòi hỏi tuân thủ các quy tắc đạo đức tuyệt đối.","whyWrong":{"A":"• Utilitarianism đánh giá theo hậu quả.","C":"• Virtue ethics tập trung vào đức hạnh cá nhân.","D":"• Virtual ethics không phải trường phái triết học."}}},{"id":34,"task":"fa24_fe","taskLabel":"FA24 FE","num":34,"chooseType":"Choose 1 answer","question":"What is 'capability caution' in AI risk governance?","options":{"A":"Steps to ensure human capabilities not limited by AI","B":"Freeze AI capabilities at current state","C":"We need to remember that we don't know the full extent of what AI systems might become capable of so that we can better plan and manage risks","D":"We know the full extent of what AI systems can do"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"'Thận trọng về năng lực' (Capability caution) trong quản trị rủi ro AI được hiểu là gì?","optionsVi":{"A":"Đảm bảo năng lực con người không bị giới hạn bởi AI","B":"Đóng băng năng lực AI ở trạng thái hiện tại","C":"Chúng ta cần ghi nhớ rằng chúng ta chưa biết hết toàn bộ quy mô năng lực mà các hệ thống AI có thể đạt tới trong tương lai để lập kế hoạch quản lý rủi ro tốt hơn (don't know full extent of AI capability)","D":"Chúng ta đã biết toàn bộ năng lực AI"},"answerDisplay":"C. We need to remember that we don't know the full extent of what Al systems might become capable of so that we can better plan.","concept":"• Capability Caution: Thận trọng trước sự tiến hóa bất ngờ vượt tầm kiểm soát của các hệ thống AI siêu việt.","whyCorrect":"• Thừa nhận sự thiếu chắc chắn về giới hạn năng lực AI tương lai để chủ động phòng ngừa rủi ro.","whyWrong":{"A":"• Việc làm thuộc về Human Alignment.","B":"• Đóng băng công nghệ là không khả thi.","D":"• Tự mãn cho rằng đã biết hết năng lực AI là sai lầm nguy hiểm."}}},{"id":35,"task":"fa24_fe","taskLabel":"FA24 FE","num":35,"chooseType":"Choose 1 answer","question":"Which mathematical theorem states that no single machine learning model can outperform all other models across all possible problems?","options":{"A":"No Free Lunch Theorem","B":"Bayes' Theorem","C":"Central Limit Theorem","D":"Goodhart's Law"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Định lý toán học nào khẳng định rằng không có một mô hình học máy duy nhất nào có thể vượt trội hơn tất cả các mô hình khác trên mọi bài toán có thể xảy ra?","optionsVi":{"A":"Định lý Bữa trưa không miễn phí (No Free Lunch Theorem)","B":"Định lý Bayes","C":"Định lý Giới hạn Trung tâm","D":"Định luật Goodhart"},"answerDisplay":"A. No Free Lunch Theorem","concept":"• No Free Lunch (NFL) Theorem in ML: Mọi thuật toán học máy đều có hiệu suất trung bình ngang nhau khi xét trên tập hợp tất cả các bài toán có thể xảy ra (Không có thuật toán vạn năng).","whyCorrect":"• Định lý khẳng định không có thuật toán học máy vạn năng tối ưu cho mọi bài toán.","whyWrong":{"B":"• Định lý Bayes dùng cho xác suất có điều kiện.","C":"• Định lý Giới hạn Trung tâm dùng cho phân bố chuẩn mẫu.","D":"• Định luật Goodhart dùng cho chỉ số đánh giá bị thao túng."}}},{"id":36,"task":"fa24_fe","taskLabel":"FA24 FE","num":36,"chooseType":"Choose 1 answer","question":"Which of the following best describes capability caution as referenced in the Asilomar AI Principles?","options":{"A":"Halt AI development if internal mechanisms unknown","B":"Given a lack of consensus, we should avoid strong assumptions regarding upper limits on future AI capabilities","C":"Ensure humans are capable of finding work","D":"Keep limits on AGI capabilities"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất nguyên tắc Thận trọng về Năng lực (Capability Caution) trong Nguyên tắc Asilomar AI?","optionsVi":{"A":"Dừng phát triển AI nếu không hiểu cơ chế","B":"Do thiếu sự đồng thuận, chúng ta nên tránh đưa ra các giả định cứng nhắc cho rằng có những giới hạn trên đối với năng lực AI trong tương lai (avoid strong assumptions regarding upper limits)","C":"Đảm bảo con người có việc làm","D":"Đặt giới hạn cho AGI"},"answerDisplay":"B. Given a lack of consensus, we should avoid strong assumptions regarding upper limits on future Al capabilities","concept":"• Asilomar Capability Caution: Tránh giả định chủ quan về giới hạn năng lực tương lai của AI.","whyCorrect":"• Không đưa ra giả định cứng nhắc về ngưỡng giới hạn trên của năng lực AI.","whyWrong":{"A":"• Dừng phát triển không phải khuyến nghị Asilomar.","C":"• Việc làm thuộc về Human Alignment.","D":"• Giới hạn AGI thuộc về AI Safety Control."}}},{"id":37,"task":"fa24_fe","taskLabel":"FA24 FE","num":37,"chooseType":"Choose 1 answer","question":"Why is it impractical to protect all possible subgroups in predictive models?","options":{"A":"Accuracy will be lowered beyond reasonable rate","B":"Fairness scores won't be high enough","C":"Individuals do not need protection","D":"There won't be enough data to reflect each subgroup finely (Combinatorial explosion)"},"answer":"D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Tại sao việc bảo vệ tất cả các phân nhóm nhỏ có thể xảy ra lại không thực tế trong các mô hình dự đoán?","optionsVi":{"A":"Độ chính xác bị hạ quá thấp","B":"Điểm công bằng không đủ cao","C":"Cá nhân không cần bảo vệ","D":"Sẽ không có đủ dữ liệu mẫu để phản ánh chính xác từng nhóm nhỏ do sự bùng nổ tổ hợp (won't be enough data to reflect each subgroup)"},"answerDisplay":"D. There won't be enough data to reflect each subgroup","concept":"• Combinatorial Explosion: Phân nhỏ nhóm quá mức khiến mẫu dữ liệu từng nhóm bị cạn kiệt.","whyCorrect":"• Sự bùng nổ tổ hợp khiến dữ liệu không đủ đại diện cho từng nhóm nhỏ.","whyWrong":{"A":"• Độ chính xác là sự đánh đổi phụ.","B":"• Điểm công bằng phụ thuộc mô hình.","C":"• Cá nhân luôn cần được bảo vệ."}}},{"id":38,"task":"fa24_fe","taskLabel":"FA24 FE","num":38,"chooseType":"Choose 1 answer","question":"As a cognitive bias, when humans see a lack of context or meaning around a piece of information, they tend to:","options":{"A":"Fill in missing details using existing stereotypes or prior assumptions","B":"Use biased research sources","C":"Seek authority figures","D":"Disagree with previous beliefs"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Dưới góc độ định kiến nhận thức, khi con người thấy sự thiếu hụt bối cảnh hoặc ý nghĩa xung quanh một mảnh thông tin, họ có xu hướng:","optionsVi":{"A":"Tự lấp đầy các chi tiết còn thiếu bằng cách dựa vào các định kiến có sẵn hoặc giả định trước đó (fill in details using stereotypes)","B":"Dùng nguồn nghiên cứu thiên vị","C":"Tìm người có thẩm quyền","D":"Bác bỏ niềm tin cũ"},"answerDisplay":"A. fill in details using existing stereotypes or prior assumptions","concept":"• Filling in Gaps in Cognitive Bias: Tự động dùng định kiến sẵn có để điền vào khoảng trống thông tin.","whyCorrect":"• Tự điền chi tiết trống bằng định kiến có sẵn.","whyWrong":{"B":"• Confirmation bias.","C":"• Authority bias.","D":"• Phản ứng đi ngược lại nhận thức."}}},{"id":39,"task":"fa24_fe","taskLabel":"FA24 FE","num":39,"chooseType":"Choose 1 answer","question":"Which organizational resource is most commonly used to guide employee decision making regarding ethical situations?","options":{"A":"Code of Ethics / Code of Conduct document","B":"Financial budget report","C":"Marketing presentation","D":"Software architecture diagram"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Nguồn lực tổ chức nào được sử dụng phổ biến nhất để định hướng cho nhân viên ra quyết định trong các tình huống đạo đức?","optionsVi":{"A":"Bộ quy tắc Đạo đức / Bộ quy tắc Ứng xử (Code of Ethics / Code of Conduct)","B":"Báo cáo ngân sách tài chính","C":"Thuyết trình tiếp thị","D":"Sơ đồ kiến trúc phần mềm"},"answerDisplay":"A. Code of Ethics","concept":"• Organizational Code of Ethics: Tài liệu chuẩn mực hành vi chính thức định hướng mọi quyết định đạo đức của nhân viên.","whyCorrect":"• Bộ quy tắc đạo đức là tài liệu hướng dẫn ra quyết định hành vi tiêu chuẩn.","whyWrong":{"B":"• Báo cáo tài chính quản lý tiền bạc.","C":"• Thuyết trình tiếp thị nhằm bán hàng.","D":"• Sơ đồ kiến trúc dùng cho kỹ thuật."}}},{"id":40,"task":"fa24_fe","taskLabel":"FA24 FE","num":40,"chooseType":"Choose 1 answer","question":"Which approach to corporate governance is more likely to create an ethical organizational culture?","options":{"A":"A systemic approach with incentive systems aligned with ethical values","B":"An oversight committee focus on rules","C":"A board focused on legal compliance","D":"An oversight committee focus on static frameworks"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Cách tiếp cận quản trị doanh nghiệp nào có khả năng tạo ra một văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Cách tiếp cận hệ thống kết hợp với hệ thống đãi ngộ/khuyến khích gắn liền với giá trị đạo đức (systemic approach with incentive systems)","B":"Ủy ban tập trung quy tắc cứng","C":"Hội đồng tập trung tuân thủ pháp lý","D":"Ủy ban tập trung khung lý thuyết"},"answerDisplay":"A. A systemic approach with incentive systems.","concept":"• Systemic Governance: Gắn cơ chế đãi ngộ với giá trị đạo đức.","whyCorrect":"• Khuyến khích bằng cơ chế đãi ngộ gắn liền với giá trị.","whyWrong":{"B":"• Quy tắc cứng tạo tâm lý đối phó.","C":"• Tuân thủ pháp lý là mức sàn.","D":"• Khung tĩnh thiếu tính hành động."}}},{"id":41,"task":"fa24_fe","taskLabel":"FA24 FE","num":41,"chooseType":"Choose 1 answer","question":"Which of the following describes change management in organizational ethics?","options":{"A":"A collective term describing how employees voice concerns","B":"A collective term for all approaches to prepare, support, and help individuals, teams, and organizations in fostering an ethical organizational culture","C":"A collective term for product modifications after negative feedback","D":"A process to replace executive board"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả Quản lý sự thay đổi (Change management) trong bối cảnh đạo đức tổ chức?","optionsVi":{"A":"Thuật ngữ mô tả cách nhân viên lên tiếng","B":"Thuật ngữ chung cho tất cả các phương pháp nhằm chuẩn bị, hỗ trợ và giúp đỡ cá nhân, đội ngũ và tổ chức thực hiện sự chuyển đổi sang văn hóa đạo đức (approaches to prepare, support, help in fostering ethical culture)","C":"Sửa đổi sản phẩm sau phản hồi","D":"Quy trình thay thế ban điều hành"},"answerDisplay":"B. A collective term for all approaches to prepare, support, and help individuals, teams, and organizations in fostering an ethical organizational culture.","concept":"• Change Management: Hỗ trợ toàn diện tổ chức thích nghi với văn hóa đạo đức mới.","whyCorrect":"• Chuẩn bị và hỗ trợ toàn diện các cấp chuyển đổi văn hóa.","whyWrong":{"A":"• Employee Voice.","C":"• Product Iteration.","D":"• Succession planning."}}},{"id":42,"task":"fa24_fe","taskLabel":"FA24 FE","num":42,"chooseType":"Choose 1 answer","question":"Which of the following is an important reason to have a dedicated Policy Owner for internal and external ethics policies?","options":{"A":"They prevent changes from taking place over time","B":"Policy owner writes policy relying solely on personal knowledge","C":"They can help to bring the right internal and external stakeholders together to help draft and update these ethics policies","D":"Single person held accountable"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Lý do quan trọng của việc chỉ định một Chủ sở hữu Chính sách (Policy Owner) cho các chính sách đạo đức là gì?","optionsVi":{"A":"Ngăn cản sự thay đổi chính sách","B":"Tự viết chính sách dựa trên kiến thức cá nhân","C":"Họ giúp kết nối và quy tụ đúng các bên liên quan nội bộ và bên ngoài để cùng dự thảo và cập nhật chính sách (bring right stakeholders together)","D":"Có một người để đổ lỗi"},"answerDisplay":"C. They can help to bring the right internal and external stakeholders together to help draft these ethics policies _","concept":"• Policy Owner Role: Điều phối kết nối các bên liên quan (Stakeholder Alignment).","whyCorrect":"• Quy tụ các bên liên quan lấy ý kiến và cập nhật chính sách.","whyWrong":{"A":"• Chính sách cần cập nhật.","B":"• Tự viết cá nhân gây góc nhìn chủ quan.","D":"• Đổ lỗi không phải mục tiêu."}}},{"id":43,"task":"fa24_fe","taskLabel":"FA24 FE","num":43,"chooseType":"Choose 1 answer","question":"Why is corporate governance important when thinking about ethical considerations for data-driven technologies?","options":{"A":"It provides an accountability framework for stakeholders of the organization to prevent ethical violations","B":"It helps showcase ethical guidelines to customers","C":"It binds employees in a moral code limiting actions","D":"It helps have a document to point towards in case of violation"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Tại sao Quản trị doanh nghiệp (Corporate governance) lại quan trọng khi xem xét các khía cạnh đạo đức cho công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Nó cung cấp một khung giải trình trách nhiệm cho các bên liên quan nhằm ngăn ngừa các vi phạm đạo đức (provides an accountability framework to prevent ethical violations)","B":"Giúp khoe hướng dẫn đạo đức","C":"Ràng buộc nhân viên trong mã đạo đức","D":"Dùng làm tài liệu trỏ tay khi có sự cố"},"answerDisplay":"A. It provides an accountability framework for stakeholders of the organization to prevent ethical violations.","concept":"• Corporate Governance Value: Thiết lập khung trách nhiệm giải trình và chuẩn mực ứng xử toàn tổ chức.","whyCorrect":"• Tạo dựng khung giải trình định hướng hành vi chuẩn mực phòng ngừa rủi ro.","whyWrong":{"B":"• Khoe khoang là mục tiêu tiếp thị.","C":"• Ràng buộc hạn chế là góc nhìn tiêu cực.","D":"• Trỏ tay chối bỏ là Ethics Washing."}}},{"id":44,"task":"fa24_fe","taskLabel":"FA24 FE","num":44,"chooseType":"Choose 1 answer","question":"Which of the following would be the most beneficial stage to hold ethical risk reviews for a new project?","options":{"A":"Development stage","B":"Deployment stage","C":"Design stage","D":"Conception / Initial Ideation stage"},"answer":"D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Giai đoạn nào sau đây sẽ là thời điểm có lợi nhất để tổ chức các buổi đánh giá rủi ro đạo đức cho một dự án mới?","optionsVi":{"A":"Giai đoạn phát triển","B":"Giai đoạn triển khai","C":"Giai đoạn thiết kế","D":"Giai đoạn hình thành ý tưởng / Khởi tạo dự án (Conception stage)"},"answerDisplay":"D. Conception","concept":"• Left-shifting Ethics (Phòng ngừa sớm từ khâu Ý tưởng): Đánh giá rủi ro ngay từ giai đoạn Conception giúp triệt hạ nguy cơ đạo đức trước khi tốn chi phí thiết kế và lập trình.","whyCorrect":"• Đánh giá rủi ro ngay từ giai đoạn hình thành ý tưởng ban đầu giúp chủ động ngăn ngừa lỗi thiết kế.","whyWrong":{"A":"• Phát triển đã bắt đầu viết mã.","B":"• Triển khai là sản phẩm đã ra mắt (quá muộn).","C":"• Thiết kế đã cố định kiến trúc (vẫn trễ hơn Conception)."}}},{"id":45,"task":"fa24_fe","taskLabel":"FA24 FE","num":45,"chooseType":"Choose 1 answer","question":"Which of the following is a key reason to engage external stakeholders during the development of ethics policies?","options":{"A":"Opportunity to demonstrate ethical standpoints","B":"Reinforce employee values","C":"It can unearth new qualitative insights into how products and services might be used or impact the target demographic community","D":"Acts as shielding mechanism"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Lý do quan trọng để thu hút các bên liên quan bên ngoài (External stakeholders) trong quá trình phát triển các chính sách đạo đức là gì?","optionsVi":{"A":"Cơ hội thể hiện quan điểm","B":"Củng cố giá trị nhân viên","C":"Nó có thể phát hiện các góc nhìn định tính mới về cách sản phẩm và dịch vụ được sử dụng hoặc tác động đến cộng đồng mục tiêu (unearth new insights into how products used in target community)","D":"Làm lá chắn trách nhiệm"},"answerDisplay":"C. It can unearth new insights for how the products and services might be used in the target demographic community.","concept":"• External Stakeholder Engagement: Khai quật các góc nhìn thực tế định tính từ cộng đồng chịu tác động.","whyCorrect":"• Phát hiện các góc nhìn định tính mới về tác động cộng đồng.","whyWrong":{"A":"• Thể hiện quan điểm là PR.","B":"• Củng cố giá trị nhân viên là công tác nội bộ.","D":"• Lá chắn trách nhiệm là Ethics Washing."}}},{"id":46,"task":"fa24_fe","taskLabel":"FA24 FE","num":46,"chooseType":"Choose 1 answer","question":"Which expression best characterizes what an organizational or corporate culture is?","options":{"A":"\"This is how we want this done.\"","B":"\"This is how things are done around here.\"","C":"\"It is what it is.\"","D":"\"This is what we're told to do.\""},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Câu nói nào thể hiện một cách tốt nhất bản chất của Văn hóa doanh nghiệp / Văn hóa tổ chức?","optionsVi":{"A":"\"Đây là cách chúng tôi muốn công việc được làm.\"","B":"\"Đây là cách mọi việc được thực hiện ở đây.\" (\"This is how things are done around here.\")","C":"\"Nó là như vậy thôi.\"","D":"\"Đây là những gì chúng tôi được bảo phải làm.\""},"answerDisplay":"B. \"This is how things are done around here.\"","concept":"• Corporate Culture Definition: Tập quán và thói quen thực thi công việc hàng ngày.","whyCorrect":"• Khẩu hiệu kinh điển phản ánh hành vi thực tế của doanh nghiệp.","whyWrong":{"A":"• Mong muốn lý thuyết.","C":"• Sự buông xuôi.","D":"• Sự tuân thủ cưỡng chế."}}},{"id":47,"task":"fa24_fe","taskLabel":"FA24 FE","num":47,"chooseType":"Choose 1 answer","question":"What is the primary purpose of change management in terms of creating an ethical organizational culture?","options":{"A":"To create a fast transition through training","B":"To create a management transition","C":"To create a smooth, supported transition for individuals and teams fostering an ethical culture","D":"To create a slow transition"},"answer":"C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Mục đích của Quản lý sự thay đổi (Change management) trong việc tạo dựng một văn hóa tổ chức có đạo đức là gì?","optionsVi":{"A":"Tạo chuyển đổi nhanh","B":"Tạo chuyển đổi quản lý","C":"Tạo ra một sự chuyển đổi mượt mà và được hỗ trợ cho cá nhân và tập thể nuôi dưỡng văn hóa đạo đức (create a smooth transition)","D":"Tạo chuyển đổi chậm"},"answerDisplay":"C. To create a smooth transition.","concept":"• Change Management Goal: Chuyển đổi văn hóa mượt mà và được hỗ trợ toàn diện.","whyCorrect":"• Hỗ trợ sự chuyển đổi văn hóa mượt mà và bền vững.","whyWrong":{"A":"• Tốc độ nhanh không phải ưu tiên hàng đầu.","B":"• Chuyển đổi quản lý chỉ là một phần.","D":"• Chuyển đổi chậm không phải mục tiêu."}}},{"id":48,"task":"fa24_fe","taskLabel":"FA24 FE","num":48,"chooseType":"Choose 1 answer","question":"Why is accountability an important principle to include in governance structures for data-driven technologies?","options":{"A":"Accountability in governance structures encourages all employees to feel responsible for building trustworthy systems","B":"Accountability encourages employees to put business needs first","C":"Accountability encourages management to hold employees accountable for actions","D":"Accountability encourages key employees to put business needs first"},"answer":"A","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Tại sao trách nhiệm giải trình (Accountability) lại là một nguyên tắc quan trọng cần đưa vào cấu trúc quản trị công nghệ?","optionsVi":{"A":"Trách nhiệm giải trình thúc đẩy tất cả nhân viên cảm nhận được trách nhiệm cá nhân trong việc xây dựng các hệ thống đáng tin cậy (encourages all employees to feel responsible for building trustworthy systems)","B":"Đặt nhu cầu kinh doanh lên hàng đầu","C":"Bắt bẻ nhân viên","D":"Chạy theo lợi nhuận"},"answerDisplay":"A. Accountability in governance structures encourages all employees to feel responsible for building trusuorthy systems.","concept":"• Accountability Culture: Lan tỏa tinh thần trách nhiệm tới từng nhân sự.","whyCorrect":"• Thúc đẩy tinh thần trách nhiệm tập thể xây dựng AI đáng tin cậy.","whyWrong":{"B":"• Đặt lợi nhuận trên đạo đức gây rủi ro.","C":"• Không dùng để trừng phạt cá nhân.","D":"• Chạy theo kinh doanh làm suy yếu quản trị."}}},{"id":49,"task":"fa24_fe","taskLabel":"FA24 FE","num":49,"chooseType":"Choose 1 answer","question":"Which of the following risk analysis methods use qualitative descriptor words like 'unlikely' or 'rare' for likelihood, and 'low', 'medium', 'high' for impact? (Select two.)","options":{"A":"Semi-qualitative analysis","B":"Quantitative analysis","C":"Semi-quantitative analysis","D":"Qualitative analysis"},"answer":"A, D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Những phương pháp phân tích rủi ro nào sử dụng các từ mô tả định tính như 'hiếm gặp', 'thấp', 'trung bình', 'cao'? (Select two)","optionsVi":{"A":"Phân tích bán định tính (Semi-qualitative analysis)","B":"Phân tích định lượng (Quantitative analysis)","C":"Phân tích bán định lượng","D":"Phân tích định tính (Qualitative analysis)"},"answerDisplay":"A. Semi-qualitative analysis & D. Qualitative analysis","concept":"• Qualitative Risk Analysis: Sử dụng các thang đo từ ngữ định tính (Low/Medium/High, Rare/Unlikely) để xếp hạng rủi ro.","whyCorrect":"• Phân tích định tính và bán định tính sử dụng các nhãn từ ngữ mô tả thay cho con số xác suất tuyệt đối.","whyWrong":{"B":"• Quantitative analysis sử dụng con số tài chính và phần trăm xác suất chính xác.","C":"• Semi-quantitative sử dụng số thứ tự điểm số (1-5)."}}},{"id":50,"task":"fa24_fe","taskLabel":"FA24 FE","num":50,"chooseType":"Choose 1 answer","question":"Which of the following mechanisms provide a user with more meaningful choices regarding how their personal data is being used? (Select two.)","options":{"A":"Whether data is used by person of certain gender","B":"Granular or modular control over data usage categories","C":"Explicit Opt-in / Opt-out privacy choice mechanisms","D":"The format data is stored in"},"answer":"B, C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Những cơ chế nào sau đây cung cấp cho người dùng các lựa chọn có ý nghĩa hơn về cách dữ liệu cá nhân của họ được sử dụng? (Select two)","optionsVi":{"A":"Giới tính người sử dụng dữ liệu","B":"Quyền kiểm soát chi tiết / mô-đun đối với các mục đích sử dụng dữ liệu (Granular or modular control)","C":"Các cơ chế lựa chọn Đồng ý / Từ chối rõ ràng (Opt-in / Opt-out mechanisms)","D":"Định dạng lưu trữ dữ liệu"},"answerDisplay":"B. Granular or modular control over data usage & C. Opt-out/opt-in mechanisms","concept":"• Meaningful Consent Mechanisms: Quyền kiểm soát chi tiết (Granular Control) và nút bật/tắt Đồng ý/Từ chối (Opt-in/Opt-out) rõ ràng.","whyCorrect":"• Phân quyền tùy chỉnh chi tiết và cơ chế Opt-in/Opt-out trao quyền tự quyết thực chất cho người dùng.","whyWrong":{"A":"• Giới tính người xem dữ liệu không phải cơ chế quyền riêng tư.","D":"• Định dạng lưu trữ thuộc kỹ thuật cơ sở dữ liệu."}}},{"id":51,"task":"fa24_fe","taskLabel":"FA24 FE","num":51,"chooseType":"Choose 1 answer","question":"Which of the following are important to provide to a crisis communication team? (Select two.)","options":{"A":"Clear direction on the roles and responsibilities of team members","B":"Permission to tell public what they want to hear","C":"Ability to work independently","D":"Access to adequate resources and verified information"},"answer":"A, D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Những yếu tố nào sau đây là quan trọng cần cung cấp cho đội ngũ truyền thông khủng hoảng? (Select two)","optionsVi":{"A":"Hướng dẫn rõ ràng về vai trò và trách nhiệm của từng thành viên (Clear direction on roles and responsibilities)","B":"Cho phép nói những gì công chúng thích nghe","C":"Khả năng làm việc độc lập","D":"Quyền truy cập vào nguồn lực đầy đủ và thông tin xác thực (Access to adequate resources)"},"answerDisplay":"A. Clear direction on the roles and responsibilities of team members & D. Access to adequate resources","concept":"• Crisis PR Team Needs: Phân công nhiệm vụ rõ ràng và Cung cấp đủ tài nguyên hạ tầng.","whyCorrect":"• Phân công vai trò chuẩn xác và cấp đủ tài nguyên giúp đội ứng phó sự cố nhất quán.","whyWrong":{"B":"• Nói những gì công chúng thích nghe mà thiếu sự thật là dối trá truyền thông.","C":"• Phải phối hợp chặt chẽ với ban chỉ đạo khủng hoảng."}}},{"id":52,"task":"fa24_fe","taskLabel":"FA24 FE","num":52,"chooseType":"Choose 1 answer","question":"Which of the following are important qualities of an effective press release? (Select two.)","options":{"A":"It's in a digital format","B":"It's non-interactive","C":"It's delivered on a single platform","D":"It's concise, clear, and newsworthy"},"answer":"A, D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Những đặc tính quan trọng nào thuộc về một Thông cáo báo chí (Press Release) hiệu quả? (Select two)","optionsVi":{"A":"Được phát hành dưới định dạng kỹ thuật số (digital format)","B":"Không có tính tương tác","C":"Phát hành trên một nền tảng","D":"Ngắn gọn súc tích và có giá trị tin tức (concise and newsworthy)"},"answerDisplay":"A. It's in a digital format & D. It's concise","concept":"• Press Release Standards: Định dạng Kỹ thuật số (Digital Format) và Tính Ngắn gọn súc tích (Concise).","whyCorrect":"• Định dạng kỹ thuật số và tính ngắn gọn súc tích là 2 tiêu chuẩn báo chí hiện đại.","whyWrong":{"B":"• Thông cáo hiện đại tích hợp đa phương tiện tương tác.","C":"• Nên phát hành đa nền tảng."}}},{"id":53,"task":"fa24_fe","taskLabel":"FA24 FE","num":53,"chooseType":"Choose 1 answer","question":"Why is it important to categorize ethical risks into different types? (Select two.)","options":{"A":"It makes it easier for us to identify and manage different types of risks effectively","B":"It ensures customers know we take ethical risks seriously","C":"It helps us understand the many complexities involved in different types of ethical risks","D":"It helps consider risk mitigation in terms of universal tactics"},"answer":"A, C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Tại sao việc phân loại rủi ro đạo đức thành các loại khác nhau lại quan trọng? (Select two)","optionsVi":{"A":"Nó giúp chúng ta dễ dàng hơn trong việc nhận diện và quản lý hiệu quả từng loại rủi ro (makes it easier to identify and manage different risks)","B":"Đảm bảo khách hàng biết công ty nghiêm túc","C":"Nó giúp chúng ta thấu hiểu nhiều sự phức tạp liên quan đến từng loại rủi ro đạo đức (helps understand complexities)","D":"Giúp tìm chiến thuật toàn năng"},"answerDisplay":"A. It makes it easier for us to identify and manage different types of risks. & C. It helps us understand the many complexities involved in different types of ethical risks.","concept":"• Categorization Value: Dễ dàng nhận diện/quản lý rủi ro và Thấu hiểu sự phức tạp đặc thù từng loại rủi ro.","whyCorrect":"• Quản lý rủi ro có hệ thống và thấu hiểu các điểm phức tạp đặc thù.","whyWrong":{"B":"• Khách hàng là đối tượng truyền thông ngoài.","D":"• Không có chiến thuật toàn năng (universal tactics)."}}},{"id":54,"task":"fa24_fe","taskLabel":"FA24 FE","num":54,"chooseType":"Choose 1 answer","question":"Which of the following are pitfalls in communicating risks to the organization? (Select two.)","options":{"A":"Having a disjointed, inconsistent message across departments","B":"Following up messaging with an audience","C":"Not paying attention to the flow and timing of messaging","D":"Coordinating a message between departments"},"answer":"A, C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Những cạm bẫy/sai lầm nào khi truyền thông các rủi ro tới tổ chức? (Select two)","optionsVi":{"A":"Thông điệp bị rời rạc, mâu thuẫn giữa các phòng ban (Having a disjointed message)","B":"Theo dõi phản hồi thông điệp","C":"Không chú ý đến luồng và thời điểm truyền thông điệp (Not paying attention to the flow of messaging)","D":"Phối hợp thông điệp giữa các phòng ban"},"answerDisplay":"A. Having a disjoined message. & C. Not paying attention to the flow of messaging.","concept":"• Communication Pitfalls: Thông điệp rời rạc thiếu nhất quán (Disjointed message) và Bỏ qua luồng thời điểm truyền thông (Flow/Timing).","whyCorrect":"• Thông điệp rời rạc không nhất quán và không quan tâm đến luồng truyền thông là 2 bẫy thất bại.","whyWrong":{"B":"• Theo dõi phản hồi là thực hành tích cực.","D":"• Phối hợp giữa các phòng ban là thực hành tốt."}}},{"id":55,"task":"fa24_fe","taskLabel":"FA24 FE","num":55,"chooseType":"Choose 1 answer","question":"Which of the following are desired qualities when choosing a spokesperson for your organization? (Select two.)","options":{"A":"Articulate when communicating important details","B":"Patient when addressing tough questions or concerns","C":"Lighthearted when dealing with serious topics","D":"Defensive when challenged"},"answer":"A, B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Những phẩm chất mong muốn nào khi lựa chọn một người phát ngôn cho tổ chức? (Select two)","optionsVi":{"A":"Ăn nói rõ ràng mạch lạc khi truyền thông chi tiết quan trọng (Articulate when communicating important details)","B":"Kiên nhẫn khi giải quyết các câu hỏi hóc húa (Patient when addressing tough questions)","C":"Cợt nhả khi bàn chủ đề nghiêm trọng","D":"Phòng thủ khi bị thách thức"},"answerDisplay":"A. Articulate when communicating important details & B. Patient when addressing tough questions or concerns","concept":"• Spokesperson Qualities: Diễn đạt mạch lạc (Articulate) và Kiên nhẫn (Patient).","whyCorrect":"• Diễn đạt mạch lạc và kiên nhẫn lắng nghe giúp xây dựng uy tín.","whyWrong":{"C":"• Cợt nhả gây phẫn nộ.","D":"• Phòng thủ phá hủy lòng tin."}}},{"id":56,"task":"fa24_fe","taskLabel":"FA24 FE","num":56,"chooseType":"Choose 1 answer","question":"Which of the following are challenges that can arise if you fail to communicate about the social impact of ethical risks? (Select two.)","options":{"A":"Decreased corporate revenue","B":"Reduction of brand loyalty and customer trust","C":"Disenfranchisement of vulnerable communities","D":"Erosion of basic human rights"},"answer":"C, D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Những thách thức/hệ lụy nào có thể phát sinh nếu bạn không truyền thông về tác động xã hội của các rủi ro đạo đức? (Select two)","optionsVi":{"A":"Sụt giảm doanh thu","B":"Giảm lòng trung thành thương hiệu","C":"Sự tước đoạt quyền lợi / đẩy các cộng đồng yếu thế ra bên lề (Disenfranchisement)","D":"Sự xói mòn các quyền con người cơ bản (Erosion of rights)"},"answerDisplay":"C. Disenfranchisement & D. Erosion of rights","concept":"• Social Impact Failures: Bỏ qua truyền thông rủi ro xã hội sẽ dẫn tới Sự tước quyền lợi nhóm yếu thế (Disenfranchisement) và Xói mòn nhân quyền (Erosion of rights).","whyCorrect":"• Tước đoạt quyền lợi cộng đồng yếu thế và xói mòn nhân quyền là tác động xã hội nghiêm trọng nhất.","whyWrong":{"A":"• Doanh thu là chỉ số tài chính doanh nghiệp.","B":"• Lòng trung thành thương hiệu là chỉ số tiếp thị."}}},{"id":57,"task":"fa24_fe","taskLabel":"FA24 FE","num":57,"chooseType":"Choose 1 answer","question":"What does it mean to say that human rights are inalienable? (Select two.)","options":{"A":"Inalienable rights are conditional","B":"Inalienable rights are inherent in all human beings by virtue of being human","C":"Inalienable rights cannot be taken away or surrendered","D":"Inalienable rights are derived from tradition"},"answer":"B, C","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Nói rằng Quyền con người là Không thể tước đoạt (Inalienable) có nghĩa là gì? (Select two)","optionsVi":{"A":"Quyền có điều kiện","B":"Quyền vốn sẵn có ở mọi con người (inherent in all human beings)","C":"Quyền không thể bị lấy mất hay từ bỏ (cannot be taken away)","D":"Quyền đến từ truyền thống"},"answerDisplay":"B. Inalienable rights are inherent in all human beings. & C. Inalienable rights cannot be taken away except in extreme circumstances.","concept":"• Inalienable Rights: Sẵn có tự nhiên và Không thể bị tước đoạt.","whyCorrect":"• Sẵn có tự nhiên và không thể bị lấy mất.","whyWrong":{"A":"• Không phải quyền có điều kiện.","D":"• Quyền mang tính phổ quát."}}},{"id":58,"task":"fa24_fe","taskLabel":"FA24 FE","num":58,"chooseType":"Choose 1 answer","question":"Which of the following best describes beneficence?","options":{"A":"Beneficence is a term coined by IBM in 2014","B":"Beneficence is the active promotion of well-being, not just for moral agents like humans, but of animals, environment, and societies","C":"Beneficence is promotion of well-being for humans only","D":"Beneficence is promotion of efficient systems"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất khái niệm Thuyết làm điều thiện (Beneficence)?","optionsVi":{"A":"Thuật ngữ IBM đặt ra năm 2014","B":"Beneficence là việc chủ động thúc đẩy sự thịnh vượng/tốt đẹp, không chỉ cho con người mà còn cho động vật, môi trường và toàn xã hội (promotion of well-being for humans, animals, environment, societies)","C":"Chỉ thúc đẩy lợi ích cho con người","D":"Thúc đẩy hiệu suất hệ thống"},"answerDisplay":"B. Beneficence is the promotion of well-being, not just for moral agents like humans, but of animals, the environment, and societies.","concept":"• Beneficence: Thúc đẩy điều thiện và lợi ích cho con người, sinh giới và môi trường.","whyCorrect":"• Thúc đẩy lợi ích rộng lớn cho con người, động vật và môi trường.","whyWrong":{"A":"• Là khái niệm triết học cổ điển.","C":"• Định nghĩa hẹp bỏ qua môi trường.","D":"• Hiệu suất là chỉ số kỹ thuật."}}},{"id":59,"task":"fa24_fe","taskLabel":"FA24 FE","num":59,"chooseType":"Choose 1 answer","question":"When building a predictive model, what is the goal of the deployment phase?","options":{"A":"To plug in 40% dataset","B":"To use the model in real-life predictions, monitoring performance, error rate, and accuracy","C":"To get model to accept new inputs and train continuously","D":"To specify algorithm and clean data"},"answer":"B","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Khi xây dựng một mô hình dự đoán, mục tiêu của giai đoạn triển khai (Deployment phase) là gì?","optionsVi":{"A":"Nạp 40% dữ liệu","B":"Sử dụng mô hình trong các dự đoán thực tế đời sống, đồng thời liên tục giám sát tỷ lệ lỗi và độ chính xác (use model in real-life predictions, monitoring accuracy)","C":"Huấn luyện liên tục không dừng","D":"Chỉ định thuật toán và làm sạch"},"answerDisplay":"B. To use the model in real-life predictions, monitoring the error rate and accuracy","concept":"• Deployment Phase Goal: Đưa mô hình vào vận hành thực tế và liên tục giám sát hiệu suất (Monitoring accuracy and drift).","whyCorrect":"• Đưa mô hình vào thực tế và giám sát chỉ số hoạt động đời thực.","whyWrong":{"A":"• 40% là chỉ số chia dữ liệu.","C":"• Huấn luyện liên tục thuộc Re-training.","D":"• Chọn thuật toán là pha chuẩn bị."}}},{"id":60,"task":"fa24_fe","taskLabel":"FA24 FE","num":60,"chooseType":"Choose 1 answer","question":"In a scatter plot of Gross Income against Revenue, data points tightly cluster along an upward rising straight line from bottom-left to top-right. What correlation does this suggest?","options":{"A":"Weak negative correlation","B":"Weak positive correlation","C":"Strong negative correlation","D":"There is a strong positive correlation between both variables"},"answer":"D","source":"ITE302c_FA24_FE","explanation":{"questionVi":"Trong biểu đồ phân tán (Scatter plot), các điểm dữ liệu của biến Thu nhập gộp (Gross Income) và Doanh thu (Revenue) tập trung chặt chẽ dọc theo một đường thẳng đi lên từ dưới bên trái đến trên bên phải. Điều này thể hiện loại tương quan nào?","optionsVi":{"A":"Tương quan âm yếu","B":"Tương quan dương yếu","C":"Tương quan âm mạnh","D":"Có một tương quan dương mạnh giữa cả hai biến số (strong positive correlation)"},"answerDisplay":"D. There is a strong positive correlation between both variables.","concept":"• Scatter Plot Correlation: Đường thẳng đi lên chặt chẽ từ trái sang phải thể hiện Tương quan Dương Mạnh (Strong Positive Correlation r ≈ 1).","whyCorrect":"• Xu hướng đi lên chặt chẽ thể hiện tương quan dương mạnh giữa Doanh thu và Thu nhập gộp.","whyWrong":{"A":"• Tương quan âm đi xuống.","B":"• Tương quan yếu các điểm dữ liệu phân tán tản mát.","C":"• Tương quan âm mạnh đi xuống từ trên trái sang dưới phải."}}},{"id":1,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":1,"chooseType":"Choose 1 answer","question":"Which of the following is a transparency risk of closed source software?","options":{"A":"Closed source software may not be accessible to independent auditors","B":"Closed source software cannot be shared with business partners","C":"Closed source software includes obfuscated code that cannot be read by a human","D":"Closed source software cannot be reviewed by the organization that developed it"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Nội dung nào sau me mô tả rủi ro về tính minh bạch của phần mềm mã nguồn đóng (Closed source software)?","optionsVi":{"A":"Phần mềm mã nguồn đóng có thể không cho phép các kiểm toán viên độc lập bên ngoài truy cập đánh giá mã nguồn (may not be accessible to independent auditors)","B":"Không thể chia sẻ với đối tác kinh doanh","C":"Mã nguồn đóng chứa mã xáo trộn không thể đọc","D":"Không thể được xem xét bởi chính tổ chức phát triển"},"answerDisplay":"A. Closed source software may not be accessible to independent auditors.","concept":"• Mã nguồn đóng (Proprietary / Closed Source) ngăn cản sự kiểm tra của bên thứ ba độc lập, gây nên rủi ro minh bạch và thiếu khả năng kiểm toán.","whyCorrect":"• Việc ngăn cấm kiểm toán viên độc lập soi xét mã nguồn tạo ra nguy cơ che giấu lỗi đạo đức và lỗ hổng bảo mật.","whyWrong":{"B":"• Phần mềm mã nguồn đóng vẫn chia sẻ với đối tác qua hợp đồng thương mại.","C":"• Mã nguồn đóng lưu mã nhị phân chứ không nhất thiết là obfuscated code.","D":"• Tổ chức tự phát triển hoàn toàn sở hữu và xem xét được mã của họ."}}},{"id":2,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":2,"chooseType":"Choose 1 answer","question":"What can be learned from a predictive model should not change whether an individual's data is included or excluded in the training set. This concept refers to:","options":{"A":"Differential privacy","B":"Dataset filtering","C":"Biased dataset","D":"Model fairness score"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Những gì học được từ một mô hình dự đoán không nên thay đổi bất kể dữ liệu của một cá nhân có xuất hiện hay bị loại khỏi tập huấn luyện hay không. Khái niệm này đề cập đến:","optionsVi":{"A":"Tính riêng tư vi sai (Differential privacy)","B":"Lọc tập dữ liệu","C":"Tập dữ liệu thiên vị","D":"Điểm số công bằng mô hình"},"answerDisplay":"A. Differential privacy","concept":"• Nguyên lý cốt lõi của Differential Privacy: Kết quả dự đoán tổng thể gần như không thay đổi khi thêm hay bớt dữ liệu của bất kỳ 1 cá nhân nào.","whyCorrect":"• Đảm bảo sự có mặt hay vắng mặt của 1 cá nhân không làm ảnh hưởng đến đầu ra của mô hình.","whyWrong":{"B":"• Lọc dữ liệu là khâu tiền xử lý.","C":"• Tập dữ liệu thiên vị gây sai lệch mô hình.","D":"• Điểm số công bằng đo lường độ bình đẳng kết quả."}}},{"id":3,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":3,"chooseType":"Choose 1 answer","question":"Which of the following is a recommended security practice for machine learning datasets?","options":{"A":"Ensure your team is full of different perspectives","B":"Enact a sound data governance structure","C":"Perform threat modeling with beneficial algorithms","D":"Create a chain of command"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Thực hành bảo mật nào sau đây được khuyến nghị cho các tập dữ liệu học máy?","optionsVi":{"A":"Đảm bảo đội ngũ có nhiều góc nhìn","B":"Ban hành và thực thi một cấu trúc quản trị dữ liệu chặt chẽ (Enact a sound data governance structure)","C":"Mô hình hóa mối đe dọa","D":"Tạo chuỗi chỉ huy"},"answerDisplay":"B. Enact a sound data governance structure","concept":"• Quản trị dữ liệu (Data Governance) quy định quyền hạn truy cập, bảo vệ tính toàn vẹn và bảo mật dữ liệu học máy.","whyCorrect":"• Cấu trúc quản trị dữ liệu tốt đảm bảo dữ liệu huấn luyện an toàn khỏi rò rỉ và can thiệp trái phép.","whyWrong":{"A":"• Góc nhìn đội ngũ thuộc về quản lý nhân sự đa dạng.","C":"• Threat modeling dành cho phần mềm hệ thống.","D":"• Chuỗi chỉ huy dành cho quản lý tổ chức."}}},{"id":4,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":4,"chooseType":"Choose 1 answer","question":"Which of the following types of bias emerges when the same data collection process is applied across different cultural groups?","options":{"A":"Cultural bias","B":"Measurement bias","C":"Historical bias","D":"Representation bias"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Loại thiên vị nào xuất hiện khi cùng một quy trình thu thập dữ liệu được áp dụng rập khuôn cho các nhóm văn hóa khác nhau?","optionsVi":{"A":"Thiên vị văn hóa","B":"Thiên vị đo lường (Measurement bias)","C":"Thiên vị lịch sử","D":"Thiên vị đại diện"},"answerDisplay":"B. Measurement bias","concept":"• Measurement Bias xảy ra khi công cụ hay thang đo dữ liệu không tương thích hoặc bị lệch khi áp dụng cho các bối cảnh văn hóa khác nhau.","whyCorrect":"• Áp dụng cùng thước đo cho các văn hóa khác nhau làm sai lệch giá trị thu thập.","whyWrong":{"A":"• Cultural bias là định kiến có sẵn trong xã hội.","C":"• Historical bias phản ánh bất bình đẳng trong quá khứ.","D":"• Representation bias do thiếu mẫu nhóm."}}},{"id":5,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":5,"chooseType":"Choose 1 answer","question":"A major downside to k-anonymity is that re-identification is possible with:","options":{"A":"Multiple datasets (Auxiliary data linkage)","B":"Database leaks","C":"Sensitive columns","D":"Expanding k values"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Hạn chế lớn của kỹ thuật k-anonymity là việc tái định danh danh tính cá nhân vẫn có thể xảy ra khi kết hợp với:","optionsVi":{"A":"Nhiều tập dữ liệu bên ngoài khác (Multiple datasets / Linkage attacks)","B":"Rò rỉ cơ sở dữ liệu","C":"Các cột thuộc tính nhạy cảm","D":"Mở rộng giá trị k"},"answerDisplay":"A. multiple datasets","concept":"• Linkage Attack on k-Anonymity: Kẻ tấn công liên kết tập dữ liệu k-anonymity với tập dữ liệu công khai bổ sung để khôi phục danh tính cá nhân.","whyCorrect":"• Kết hợp chéo dữ liệu vô danh với các nguồn dữ liệu bên ngoài là cách bẻ gãy k-anonymity.","whyWrong":{"B":"• Database leaks là sự cố truy cập.","C":"• Cột nhạy cảm là nội dung cần bảo vệ.","D":"• Tăng k giúp tăng tính an toàn chứ không gây rò rỉ."}}},{"id":6,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":6,"chooseType":"Choose 1 answer","question":"A benefit of glass box models is that if an attribute is skewing predictions unfairly, you can:","options":{"A":"Easily identify and modify/remove that specific attribute","B":"Re-train the neural network automatically","C":"Increase hyperparameter layers","D":"Encrypt the dataset"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Lợi ích của các mô hình Hộp kính (Glass box models) là nếu một thuộc tính làm lệch kết quả dự đoán một cách bất công, bạn có thể:","optionsVi":{"A":"Dễ dàng nhận diện và điều chỉnh/loại bỏ thuộc tính cụ thể đó (Easily identify and modify attribute)","B":"Tự động huấn luyện lại mạng nơ-ron","C":"Tăng số lớp tham số","D":"Mã hóa tập dữ liệu"},"answerDisplay":"A. Easily identify and modify that attribute","concept":"• Glass Box Model (Mô hình giải thích được như Decision Tree, Linear Regression): Cho phép con người soi thấu tác động của từng thuộc tính đến đầu ra.","whyCorrect":"• Tính giải thích trực quan giúp phát hiện và can thiệp ngay thuộc tính gây thiên vị.","whyWrong":{"B":"• Mạng nơ-ron là Black box.","C":"• Tăng tham số làm giảm tính giải thích.","D":"• Mã hóa dữ liệu không giải quyết thiên vị mô hình."}}},{"id":7,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":7,"chooseType":"Choose 1 answer","question":"During cross-validation, which of the following dataset splits is standard for training, validation, and testing?","options":{"A":"60% training, 20% validation, 20% testing","B":"30% training, 30% validation, 40% testing","C":"10% training, 80% validation, 10% testing","D":"50% training, 50% testing"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Trong quá trình kiểm chứng chéo (Cross-validation), tỷ lệ phân chia tập dữ liệu chuẩn cho huấn luyện, kiểm chứng và kiểm thử là:","optionsVi":{"A":"60% huấn luyện (train), 20% kiểm chứng (val), 20% kiểm thử (test)","B":"30% train, 30% val, 40% test","C":"10% train, 80% val, 10% test","D":"50% train, 50% test"},"answerDisplay":"A. 60% training, 20% validation, 20% testing","concept":"• Quy tắc phân chia dữ liệu tiêu chuẩn: 60/20/20 hoặc 70/15/15 đảm bảo mô hình có đủ dữ liệu học và đánh giá khách quan.","whyCorrect":"• Phản ánh tỷ lệ phân chia tập dữ liệu kinh điển 60-20-20 trong Machine Learning.","whyWrong":{"B":"• Tỷ lệ train 30% quá nhỏ khiến mô hình bị underfitting.","C":"• Train 10% không đủ để mô hình học quy luật.","D":"• Thiếu tập Validation kiểm chứng siêu tham số."}}},{"id":8,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":8,"chooseType":"Choose 1 answer","question":"When it comes to protecting private data, which of the following provides the strongest privacy guarantee?","options":{"A":"Differential privacy","B":"k-anonymity","C":"Data masking","D":"Pseudonymization"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Khi đề cập đến bảo vệ dữ liệu riêng tư, giải pháp nào sau đây cung cấp sự đảm bảo tính riêng tư mạnh mẽ nhất toán học?","optionsVi":{"A":"Tính riêng tư vi sai (Differential privacy)","B":"Ẩn danh k-anonymity","C":"Mặt nạ dữ liệu (Data masking)","D":"Giả danh tính (Pseudonymization)"},"answerDisplay":"A. Differential privacy","concept":"• Differential Privacy cung cấp sự bảo vệ riêng tư toán học chứng minh được (Mathematically provable privacy guarantee) chống lại mọi cuộc tấn công liên kết.","whyCorrect":"• Chứng minh toán học vững chắc nhất ngăn chặn tái định danh.","whyWrong":{"B":"• k-anonymity dễ bị bẻ gãy bởi Linkage attack.","C":"• Data masking chỉ che mờ bề nổi.","D":"• Pseudonymization có thể bị khôi phục lại danh tính qua bảng ánh xạ."}}},{"id":9,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":9,"chooseType":"Choose 1 answer","question":"The Netflix prize privacy scandal is an example of re-identification using:","options":{"A":"Auxiliary public datasets (IMDb ratings)","B":"Stolen private encryption keys","C":"Phishing attack","D":"Ransomware infection"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Bê bối riêng tư Giải thưởng Netflix là một ví dụ về việc tái định danh cá nhân bằng cách sử dụng:","optionsVi":{"A":"Các tập dữ liệu công khai bổ sung bên ngoài (như đánh giá trên IMDb) (Auxiliary public datasets)","B":"Khóa mã hóa bị đánh cắp","C":"Tấn công giả mạo Phishing","D":"Mã độc tống tiền Ransomware"},"answerDisplay":"A. Auxiliary public datasets","concept":"• Bài học từ Netflix Scandal: Tập dữ liệu ratings vô danh bị liên kết với tập dữ liệu công khai IMDb để khôi phục danh tính cá nhân.","whyCorrect":"• Sử dụng dữ liệu phụ trợ IMDb là phương thức bẻ gãy sự ẩn danh của dữ liệu Netflix.","whyWrong":{"B":"• Không hề có sự cố mất khóa mã hóa.","C":"• Phishing không liên quan đến bài toán tái định danh dữ liệu mở.","D":"• Ransomware là mã độc mã hóa đòi tiền."}}},{"id":10,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":10,"chooseType":"Choose 1 answer","question":"A hospital dataset protects whether an individual has a specific disease using a technique that ensures groups of at least k individuals share identical attributes. This is known as:","options":{"A":"Group inclusion","B":"Privacy columns","C":"k-anonymity","D":"Security issues"},"answer":"C","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Một tập dữ liệu bệnh viện bảo vệ thông tin bệnh lý cá nhân bằng cách đảm bảo nhóm ít nhất k cá nhân có thuộc tính định danh giống hệt nhau. Đây được gọi là kỹ thuật gì?","optionsVi":{"A":"Bao hàm nhóm","B":"Cột riêng tư","C":"Tính ẩn danh k-anonymity","D":"Vấn đề an ninh"},"answerDisplay":"C. k-anonymity","concept":"• k-Anonymity quy định mỗi bản ghi trong tập dữ liệu không thể phân biệt được với ít nhất k-1 bản ghi khác đối với các thuộc tính bán định danh.","whyCorrect":"• Định nghĩa chuẩn mực của k-anonymity là nhóm k cá nhân giống hệt thuộc tính.","whyWrong":{"A":"• Group inclusion không phải thuật ngữ riêng tư.","B":"• Privacy columns không định nghĩa nhóm k.","D":"• Security issues là thuật ngữ chung."}}},{"id":11,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":11,"chooseType":"Choose 1 answer","question":"If you were to place the task 'Apply security patch to system' in a RACI matrix, who holds the ultimate approval responsibility?","options":{"A":"Responsible","B":"Accountable","C":"Consulted","D":"Informed"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Nếu bạn xếp nhiệm vụ 'Áp dụng bản vá an ninh cho hệ thống' vào ma trận RACI, ai là người gánh chịu trách nhiệm phê duyệt và giải trình cuối cùng?","optionsVi":{"A":"Người thực hiện (Responsible)","B":"Người chịu trách nhiệm giải trình cuối cùng (Accountable)","C":"Người được tư vấn (Consulted)","D":"Người được thông báo (Informed)"},"answerDisplay":"B. Accountable","concept":"• Ma trận RACI: Accountable (A) là cá nhân duy nhất sở hữu quyền quyết định phê duyệt và gánh hậu quả cuối cùng.","whyCorrect":"• Vị trí Accountable chịu trách nhiệm quyết định và giải trình tối cao.","whyWrong":{"A":"• Responsible là người trực tiếp thực thi thao tác vá.","C":"• Consulted đóng vai trò tư vấn kỹ thuật.","D":"• Informed nhận báo cáo sau khi hoàn thành."}}},{"id":12,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":12,"chooseType":"Choose 1 answer","question":"The Data minimization principle requires that you limit data collection to only what is:","options":{"A":"Necessary for differential privacy","B":"Optional for a chain of command","C":"Needed to have k-anonymity","D":"Required to fulfill a specific purpose"},"answer":"D","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Nguyên tắc Giảm thiểu dữ liệu (Data minimization) yêu cầu bạn giới hạn việc thu thập dữ liệu ở mức chỉ bao gồm những gì:","optionsVi":{"A":"Cần thiết cho tính riêng tư vi sai","B":"Tùy chọn cho chuỗi chỉ huy","C":"Cần thiết để đạt tính ẩn danh k-anonymity","D":"Cần thiết để thực hiện một mục đích cụ thể đã xác định (Required to fulfill a specific purpose)"},"answerDisplay":"D. Required to fulfill a specific purpose","concept":"• Nguyên tắc Giảm thiểu dữ liệu (Data Minimization) yêu cầu doanh nghiệp chỉ thu thập đúng và đủ dữ liệu cần thiết phục vụ cho một mục đích xử lý cụ thể đã được xác định trước.","whyCorrect":"• Chỉ thu thập dữ liệu thực sự cần thiết cho mục đích cụ thể giúp hạn chế rủi ro lộ rò dữ liệu cá nhân.","whyWrong":{"A":"• Differential privacy là kỹ thuật toán học thêm nhiễu, không phải điều kiện thu thập.","B":"• Thu thập dữ liệu không nhằm phục vụ chuỗi chỉ huy nội bộ.","C":"• k-anonymity là phương pháp ẩn danh hóa tập dữ liệu."}}},{"id":13,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":13,"chooseType":"Choose 1 answer","question":"Which of the following measures is best suited for reporting risk severity to executive management?","options":{"A":"Risk Heatmap / Risk Matrix","B":"Raw log files","C":"Code diff reports","D":"Database schematics"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Biện pháp/công cụ nào sau đây phù hợp nhất để báo cáo mức độ nghiêm trọng của rủi ro lên Ban điều hành cấp cao?","optionsVi":{"A":"Bản đồ nhiệt rủi ro / Ma trận rủi ro (Risk Heatmap)","B":"Tệp nhật ký log thô","C":"Báo cáo so sánh mã nguồn diff","D":"Sơ đồ cơ sở dữ liệu"},"answerDisplay":"A. Risk Heatmap","concept":"• Risk Heatmap trực quan hóa khả năng xảy ra (Likelihood) và mức độ tác động (Impact) giúp ban quản trị C-suite nhanh chóng nắm bắt rủi ro cốt lõi.","whyCorrect":"• Trực quan hóa ma trận rủi ro rõ ràng cho ban lãnh đạo C-suite.","whyWrong":{"B":"• Log thô chứa quá nhiều chi tiết kỹ thuật gây quá tải.","C":"• Code diff dành cho lập trình viên.","D":"• Sơ đồ CSDL dành cho kiến trúc sư dữ liệu."}}},{"id":14,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":14,"chooseType":"Choose 1 answer","question":"Which of the following is an important concept to consider as part of building an ethical AI philosophy?","options":{"A":"Adopting philosophies already created by other organizations","B":"Putting ethical principles into practice and foresight into future impacts","C":"Considering internal stakeholder needs above all else","D":"Focusing only on short-term compliance"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Khái niệm quan trọng nào cần xem xét khi xây dựng triết lý đạo đức AI cho tổ chức?","optionsVi":{"A":"Sao chép triết lý của tổ chức khác","B":"Đưa các nguyên tắc đạo đức vào thực thi thực tế và dự báo các tác động tương lai (Putting ethical principles into practice)","C":"Coi nhu cầu nội bộ là trên hết","D":"Chỉ tập trung vào tuân thủ ngắn hạn"},"answerDisplay":"B. Putting ethical principles into practice","concept":"• Triết lý đạo đức hiệu quả phải mang tính Thực thi (Operationalization) và Dự báo tương lai (Foresight) thay vì khẩu hiệu lý thuyết.","whyCorrect":"• Biến lý thuyết thành hành động thực tế và dự báo tác động tương lai là bản chất của triết lý đạo đức vững chắc.","whyWrong":{"A":"• Sao chép bỏ qua bối cảnh riêng của doanh nghiệp.","C":"• Chỉ quan tâm nội bộ gây ảnh hưởng tiêu cực tới khách hàng.","D":"• Bỏ qua tác động dài hạn."}}},{"id":15,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":15,"chooseType":"Choose 1 answer","question":"Why is it important to take a proactive approach to addressing ethical risks?","options":{"A":"It prevents harm before it occurs and reduces costly post-incident remediation","B":"It guarantees 100% immunity from lawsuits","C":"It replaces the need for technical security testing","D":"It simplifies code development"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Tại sao việc chủ động (Proactive approach) tiếp cận và xử lý các rủi ro đạo đức lại cực kỳ quan trọng?","optionsVi":{"A":"Giúp ngăn ngừa tổn hại trước khi nó xảy ra và giảm thiểu chi phí khắc phục sự cố tốn kém (prevents harm before it occurs)","B":"Đảm bảo miễn trừ 100% kiện tụng","C":"Thay thế nhu cầu kiểm thử an ninh kỹ thuật","D":"Đơn giản hóa việc viết mã nguồn"},"answerDisplay":"A. It prevents harm before it occurs and reduces costly post-incident remediation.","concept":"• Tiếp cận chủ động (Proactive Risk Management): Nhận diện và phòng ngừa rủi ro ngay từ đầu giúp bảo vệ uy tín và tiết kiệm chi phí khắc phục khủng hoảng.","whyCorrect":"• Chủ động ngăn tổn hại hiệu quả và tiết kiệm chi phí hơn rất nhiều so với khắc phục sự cố bị động.","whyWrong":{"B":"• Không có sự miễn trừ tuyệt đối trước pháp luật.","C":"• Đạo đức không thay thế được kỹ thuật an toàn thông tin.","D":"• Không liên quan trực tiếp đến cú pháp viết mã."}}},{"id":16,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":16,"chooseType":"Choose 1 answer","question":"What is the primary purpose of obtaining feedback about an ethical crisis?","options":{"A":"To demonstrate compliance","B":"To make operational and ethical improvements to prevent recurrence","C":"To appease concerned stakeholders","D":"To motivate internal personnel"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Mục đích chính của việc thu thập phản hồi (Feedback) về một cuộc khủng hoảng đạo đức là gì?","optionsVi":{"A":"Để chứng minh sự tuân thủ hình thức","B":"Để thực hiện các cải tiến vận hành và đạo đức nhằm ngăn chặn sự cố tái diễn (To make operational improvements)","C":"Để xoa dịu các bên liên quan","D":"Để động viên nhân viên"},"answerDisplay":"B. To make operational improvements","concept":"• Post-Incident Feedback Loops: Sử dụng bài học sau sự cố (Lessons Learned) để cải tiến quy trình vận hành và ngăn chặn lỗi lặp lại.","whyCorrect":"• Rút kinh nghiệm để cải tiến vận hành thực chất là giá trị cao nhất của phản hồi khủng hoảng.","whyWrong":{"A":"• Tuân thủ hình thức không khắc phục được nguyên nhân gốc.","C":"• Xoa dịu suông mà không sửa đổi là thái độ dối trá.","D":"• Động viên nhân viên là tác vụ nhân sự."}}},{"id":17,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":17,"chooseType":"Choose 1 answer","question":"Which of the following can help mitigate unwillingness to accept feedback in an organization?","options":{"A":"Engage in cultural awareness and cultural sensitivity","B":"Create and participate in a risk culture of open feedback","C":"Communicate the importance of feedback in refining products","D":"Communicate regularly about values"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây có thể giúp giảm thiểu thái độ e ngại/miễn cưỡng khi tiếp nhận phản hồi trong một tổ chức?","optionsVi":{"A":"Tham gia nhận thức văn hóa","B":"Xây dựng và tham gia vào một văn hóa rủi ro mở lắng nghe phản hồi (risk culture of open feedback)","C":"Truyền thông tầm quan trọng của phản hồi","D":"Truyền thông định kỳ về giá trị"},"answerDisplay":"B. Create and participate in a risk culture.","concept":"• Risk Culture (Văn hóa Rủi ro minh bạch): Cho phép nhân viên thoải mái báo cáo sai sót và tiếp nhận phản hồi mà không sợ bị trừng phạt.","whyCorrect":"• Xây dựng văn hóa mở thúc đẩy việc tự giác lắng nghe và sửa đổi.","whyWrong":{"A":"• Nhận thức văn hóa là phạm vi DEI.","C":"• Truyền thông lý thuyết suông không thay đổi được tâm lý lo sợ trừng phạt.","D":"• Nói về giá trị không tự động xóa bỏ tâm lý e ngại."}}},{"id":18,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":18,"chooseType":"Choose 1 answer","question":"When conducting a Business Impact Assessment (BIA), why is it important to interview operational staff?","options":{"A":"They are more likely to be candid and give forthright responses","B":"They may have more hands-on institutional knowledge about practical subject workflows than managers","C":"They are more likely to find time for surveys","D":"They have a greater obligation to answer"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Khi tiến hành Đánh giá Tác động Kinh doanh (BIA), tại sao việc phỏng vấn trực tiếp nhân viên vận hành thực tế lại quan trọng?","optionsVi":{"A":"Họ thành thật hơn","B":"Họ nắm giữ nhiều tri thức thực tế quy trình (institutional knowledge) về vận hành hơn các cấp quản lý (hands-on institutional knowledge)","C":"Họ có nhiều thời gian rảnh hơn","D":"Họ bắt buộc phải trả lời"},"answerDisplay":"B. They may have more institutional knowledge about a subject than managers.","concept":"• Operational Staff (Nhân viên vận hành trực tiếp) thấu hiểu mọi rủi ro và nút thắt quy trình hàng ngày mà cấp quản lý chỉ nhìn thấy trên báo cáo.","whyCorrect":"• Tri thức vận hành thực tế giúp BIA đánh giá chính xác các lỗ hổng hệ thống.","whyWrong":{"A":"• Sự thành thật phụ thuộc vào cá nhân.","C":"• Nhân viên vận hành thường bận rộn với tác vụ hàng ngày.","D":"• Nghĩa vụ trả lời áp dụng chung cho mọi cấp."}}},{"id":19,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":19,"chooseType":"Choose 1 answer","question":"An organization needs to audit its quality control issues after an incident. Which document format captures lessons learned?","options":{"A":"Business impact assessment","B":"Lessons learned report","C":"Vulnerability audit","D":"Business continuity plan"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Tổ chức cần kiểm toán các vấn đề kiểm soát chất lượng sau sự cố. Dạng tài liệu nào ghi chép lại các bài học kinh nghiệm?","optionsVi":{"A":"Báo cáo đánh giá tác động kinh doanh","B":"Báo cáo bài học kinh nghiệm (Lessons learned report)","C":"Kiểm toán lỗ hổng","D":"Kế hoạch duy trì hoạt động kinh doanh"},"answerDisplay":"B. Lessons learned report","concept":"• Lessons Learned Report ghi nhận nguyên nhân sự cố, những gì làm tốt và những điều cần cải thiện cho tương lai.","whyCorrect":"• Báo cáo bài học kinh nghiệm là tài liệu chuẩn mực tổng kết sau sự cố.","whyWrong":{"A":"• BIA đánh giá tác hại tiềm tàng trước sự cố.","C":"• Vulnerability audit tìm lỗ hổng kỹ thuật.","D":"• BCP quy định quy trình khôi phục khi gặp thảm họa."}}},{"id":20,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":20,"chooseType":"Choose 1 answer","question":"Why is deciding how to act using moral reasoning not always a feasible goal for human beings?","options":{"A":"Most people are not educated on normative ethical theories and cannot perform true moral reasoning","B":"Moral reasoning is too complicated for real-world situations","C":"Moral reasoning has few tangible benefits","D":"Human decision making is often influenced by emotion and bias rather than pure logic"},"answer":"D","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Tại sao việc đưa ra quyết định hành động bằng lý trí đạo đức không phải lúc nào cũng là mục tiêu khả thi đối với con người?","optionsVi":{"A":"Hầu hết mọi người không được học lý thuyết đạo đức","B":"Lý trí đạo đức quá phức tạp","C":"Lý trí đạo đức có ít lợi ích hữu hình","D":"Quyết định của con người thường bị chi phối mạnh mẽ bởi cảm xúc, định kiến và nhận thức hơn là logic thuần túy (influenced by emotion and not logic)"},"answerDisplay":"D. Human decision making is often influenced by emotion and not logic.","concept":"• Tâm lý học hành vi (Bounded Rationality): Quyết định thực tế của con người bị chi phối bởi cảm xúc, áp lực thời gian và định kiến nhận thức.","whyCorrect":"• Cảm xúc và định kiến tâm lý thường lấn át khả năng lập luận logic đạo đức thuần túy.","whyWrong":{"A":"• Con người có nhận thức đạo đức tự nhiên mà không cần học lý thuyết chính quy.","B":"• Lý trí đạo đức áp dụng tốt trong nhiều tình huống thực tế.","C":"• Quyết định đạo đức mang lại giá trị uy tín và xã hội rất lớn."}}},{"id":21,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":21,"chooseType":"Choose 1 answer","question":"What's the difference between a basic and complex learning algorithm?","options":{"A":"A basic algorithm has a set amount of choices to optimize for, while a complex algorithm is given the freedom to find its own model structure","B":"A basic algorithm cannot use computer vision","C":"A basic algorithm cannot process more than 5 steps","D":"A basic algorithm only handles numbers"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Sự khác biệt giữa thuật toán học cơ bản và thuật toán học phức tạp (Complex learning algorithm) là gì?","optionsVi":{"A":"Thuật toán cơ bản có một số lượng lựa chọn cố định để tối ưu hóa, trong khi thuật toán phức tạp được tự do tìm kiếm cấu trúc mô hình riêng (freedom to find its own model)","B":"Thuật toán cơ bản không thể dùng thị giác máy tính","C":"Thuật toán cơ bản không xử lý quá 5 bước","D":"Thuật toán cơ bản chỉ xử lý số"},"answerDisplay":"A. A basic algorithm has a set amount of choices to optimize for, while a complex algorithm is given the freedom to find its own model","concept":"• Thuật toán phức tạp (Deep Learning / Non-linear models) tự động trích xuất thuộc tính và tự tìm dạng hàm đại diện tối ưu mà không bị giới hạn bởi không gian tham số tuyến tính cố định.","whyCorrect":"• Khả năng tự do khám phá cấu trúc mô hình là đặc trưng của Complex Learning Algorithm.","whyWrong":{"B":"• Thuật toán cơ bản vẫn có thể xử lý điểm ảnh cơ bản.","C":"• Số lượng bước tính không quy định độ phức tạp toán học.","D":"• Mọi dữ liệu máy tính cuối cùng đều quy về dạng số."}}},{"id":22,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":22,"chooseType":"Choose 1 answer","question":"How is a Machine Learning (ML) system different from a Deep Learning (DL) system?","options":{"A":"A ML system learns from its mistakes","B":"A ML system does all feature extraction automatically","C":"A ML system typically requires a human expert to perform manual feature extraction","D":"A ML system does not need input data"},"answer":"C","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Hệ thống Học máy truyền thống (ML) khác biệt như thế nào so với hệ thống Học sâu (DL)?","optionsVi":{"A":"Mô hình ML học từ sai lầm","B":"Mô hình ML tự động trích xuất đặc trưng","C":"Mô hình ML truyền thống yêu cầu chuyên gia con người thực hiện trích xuất thuộc tính thủ công (requires human feature extraction)","D":"Mô hình ML không cần dữ liệu đầu vào"},"answerDisplay":"C. A ML system needs a human to provide the feature extraction.","concept":"• Phân biệt ML và DL: ML truyền thống yêu cầu Feature Engineering thủ công từ con người; DL (Mạng nơ-ron sâu) tự động học Feature Extraction trực tiếp từ dữ liệu thô.","whyCorrect":"• Trích xuất thuộc tính thủ công bởi con người là hạn chế của ML truyền thống so với DL.","whyWrong":{"A":"• Cả ML và DL đều điều chỉnh trọng số dựa trên hàm lỗi.","B":"• Trích xuất thuộc tính tự động là ưu thế của DL.","D":"• Cả hai đều bắt buộc phải có dữ liệu đầu vào."}}},{"id":23,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":23,"chooseType":"Choose 1 answer","question":"A good example of empirical reflection in training data is when:","options":{"A":"A true positive result defies training set","B":"A model fails to recognize cultural differences due to incorrect attributes","C":"An image recognition model selects one face over another based on sample data distribution","D":"An image recognition model cannot tell dog from photo"},"answer":"C","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Một ví dụ minh họa về sự phản ánh thực nghiệm (Empirical reflection) trong dữ liệu huấn luyện là khi:","optionsVi":{"A":"Kết quả dương tính thực tế thách thức tập dữ liệu","B":"Mô hình thất bại khi nhận diện văn hóa","C":"Mô hình nhận diện hình ảnh ưu tiên chọn khuôn mặt này hơn khuôn mặt khác dựa trên phân bố tần suất mẫu trong dữ liệu (selects face based on sample data)","D":"Mô hình không phân biệt được chó và ảnh"},"answerDisplay":"C. an image recognition model selects one face over another based on sample data","concept":"• Empirical Reflection: Mô hình tái phản ánh chính xác phân bố thống kê khách quan chứa trong tập dữ liệu huấn luyện mà nó được nạp.","whyCorrect":"• Phản ánh hiện tượng mô hình sao chép và thể hiện lại sự lệch phân bố mẫu thực nghiệm trong tập dữ liệu.","whyWrong":{"A":"• Kết quả thách thức dữ liệu là hiện tượng outlier.","B":"• Thất bại văn hóa là lỗi gán thuộc tính sai.","D":"• Lỗi phân biệt chó và ảnh là lỗi kỹ thuật phân loại."}}},{"id":24,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":24,"chooseType":"Choose 1 answer","question":"Model inputs of address with 'City + State' as separate inputs from a dataset would represent:","options":{"A":"Highly correlated attributes (Collinearity)","B":"No correlating data","C":"First principles","D":"Objective summarization"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Việc đưa thuộc tính địa chỉ gồm 'Thành phố + Bang' thành các đầu vào tách biệt trong mô hình sẽ đại diện cho:","optionsVi":{"A":"Các thuộc tính có sự tương quan rất cao / Đa cộng tuyến (Highly correlated attributes / Collinearity)","B":"Không có dữ liệu tương quan","C":"Nguyên lý đầu tiên","D":"Tóm tắt khách quan"},"answerDisplay":"A. Highly correlated attributes","concept":"• Đa cộng tuyến (Multicollinearity): Thành phố phụ thuộc trực tiếp vào Bang, khiến hai biến số này chứa thông tin trùng lặp tương quan mạnh.","whyCorrect":"• Tên thành phố quyết định tên bang tương ứng, tạo ra tính đa cộng tuyến dư thừa dữ liệu.","whyWrong":{"B":"• Hai biến số này có tương quan phụ thuộc tuyệt đối.","C":"• First principles là lập luận nguyên lý cơ bản.","D":"• Objective summarization là tóm tắt dữ liệu."}}},{"id":25,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":25,"chooseType":"Choose 1 answer","question":"If you are doing an analysis of data to determine which of several small business loans should be approved, what type of analytics is this?","options":{"A":"Descriptive","B":"Prescriptive","C":"Predictive","D":"Cumulative"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Nếu bạn đang phân tích dữ liệu để quyết định đề xuất khoản vay doanh nghiệp nhỏ nào nên được phê duyệt, đây là loại hình phân tích nào?","optionsVi":{"A":"Phân tích mô tả (Descriptive)","B":"Phân tích đề xuất / Kế hoạch hành động (Prescriptive)","C":"Phân tích dự báo (Predictive)","D":"Phân tích tích tụ (Cumulative)"},"answerDisplay":"B. Prescriptive","concept":"• Prescriptive Analytics (Phân tích chỉ định / đề xuất): Đưa ra các quyết định hành động tối ưu (Nên duyệt khoản vay nào) dựa trên dữ liệu.","whyCorrect":"• Đưa ra khuyến nghị hành động phê duyệt cụ thể là nhiệm vụ của Prescriptive Analytics.","whyWrong":{"A":"• Descriptive Analytics chỉ tóm tắt quá khứ.","C":"• Predictive Analytics dự báo xác suất vỡ nợ.","D":"• Cumulative Analytics tính tổng tích lẫy."}}},{"id":26,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":26,"chooseType":"Choose 1 answer","question":"'Companies have an obligation to their shareholders' is part of a view that sees corporate responsibility as focused primarily on:","options":{"A":"Fiduciary duty to maximize shareholder value","B":"Just another research tool","C":"A gimmick for enterprises","D":"A harmful tool to end capitalism"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"'Các công ty có nghĩa vụ đối với các cổ đông của họ' là một phần của quan điểm coi trách nhiệm doanh nghiệp tập trung vào:","optionsVi":{"A":"Nghĩa vụ ủy thác tối đa hóa giá trị cho cổ đông (Fiduciary duty to maximize shareholder value / Friedman doctrine)","B":"Công cụ tăng tốc nghiên cứu","C":"Chiêu trò doanh nghiệp","D":"Công cụ có hại phá hủy chủ nghĩa tư bản"},"answerDisplay":"A. an overall good for humanity, no matter the consequences","concept":"• Quan điểm Thuyết cổ đông (Shareholder Theory của Milton Friedman): Nghĩa vụ đạo đức và pháp lý hàng đầu của quản trị doanh nghiệp là tối đa hóa lợi nhuận cho cổ đông.","whyCorrect":"• Phản ánh tư tưởng coi lợi nhuận cổ đông là mục tiêu tối cao của doanh nghiệp.","whyWrong":{"B":"• Công cụ nghiên cứu là khía cạnh kỹ thuật.","C":"• Chiêu trò là góc nhìn hoài nghi tiếp thị.","D":"• Phá hủy tư bản trái ngược với lợi ích cổ đông."}}},{"id":27,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":27,"chooseType":"Choose 1 answer","question":"In a complex learning function (Black box AI), we will understand the:","options":{"A":"Causal link, correlation","B":"Algorithm, cause and effect","C":"Input data and output data, but not the internal mathematical decision-making logic","D":"Algorithm logic completely"},"answer":"C","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Trong một hàm học phức tạp (AI Hộp đen), chúng ta sẽ hiểu được:","optionsVi":{"A":"Mối quan hệ nguyên nhân, tương quan","B":"Thuật toán, nguyên nhân kết quả","C":"Dữ liệu đầu vào và dữ liệu đầu ra, nhưng không thể hiểu logic toán ra quyết định bên trong (inputs/outputs, but not the algorithm logic)","D":"Hiểu hoàn toàn logic thuật toán"},"answerDisplay":"C. inputs/outputs, algorithm","concept":"• Đặc trưng AI Hộp đen: Con người quan sát được Input và Output nhưng không giải thích được các phép biến đổi ma trận ẩn bên trong.","whyCorrect":"• Thấy được đầu vào và đầu ra nhưng không hiểu logic nội tại bên trong là bản chất của AI Hộp đen.","whyWrong":{"A":"• Mối quan hệ nguyên nhân bị ẩn trong hộp đen.","B":"• Nguyên nhân kết quả không thể diễn giải được.","D":"• Logic thuật toán không thể thấu hiểu trực quan."}}},{"id":28,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":28,"chooseType":"Choose 1 answer","question":"What are the attributes of an error function when training a predictive model?","options":{"A":"The percentage of data formatted properly","B":"The measure/percentage of predictions that don't match actual outcomes (Loss/Error)","C":"The ratio of algorithm to curve","D":"The ratio of training data to actual data"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Thuộc tính nào mô tả hàm sai số (Error function / Loss function) khi huấn luyện một mô hình dự đoán?","optionsVi":{"A":"Phần trăm dữ liệu được định dạng đúng","B":"Thước đo / Phần trăm các dự đoán không khớp với kết quả thực tế (predictions that don't match actual outcomes)","C":"Tỷ lệ thuật toán và đường cong","D":"Tỷ lệ dữ liệu huấn luyện"},"answerDisplay":"B. the percentage of predictions that don't match actual outcomes","concept":"• Hàm sai số (Loss/Error Function) đo lường mức độ sai lệch giữa đầu ra dự đoán của mô hình và nhãn thực tế.","whyCorrect":"• Đo lường tỷ lệ/khoảng cách dự đoán sai so với thực tế là bản chất của Error function.","whyWrong":{"A":"• Định dạng dữ liệu là bước làm sạch.","C":"• Tỷ lệ đường cong không phải khái niệm hàm sai số.","D":"• Tỷ lệ dữ liệu là chỉ số phân chia dataset."}}},{"id":29,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":29,"chooseType":"Choose 1 answer","question":"Which of the following best describes what an algorithm is?","options":{"A":"A step-by-step set of instructions (recipe) that a computer uses to solve a problem","B":"A process humans use to write code","C":"A type of hardware computer","D":"A list of ingredients to generate problems"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất Thuật toán (Algorithm) là gì?","optionsVi":{"A":"Tập hợp các hướng dẫn từng bước (công thức) mà máy tính sử dụng để giải quyết một bài toán (recipe to solve problems)","B":"Quy trình con người viết mã","C":"Một loại máy tính phần cứng","D":"Danh sách nguyên liệu tạo bài toán"},"answerDisplay":"A. a recipe that a computer uses to solve problems","concept":"• Định nghĩa Thuật toán (Algorithm): Dãy các quy tắc hay chỉ dẫn từng bước rõ ràng để xử lý dữ liệu và giải quyết bài toán.","whyCorrect":"• Ví như công thức từng bước cho máy tính giải quyết vấn đề.","whyWrong":{"B":"• Viết mã là hoạt động lập trình.","C":"• Thuật toán là phần mềm/logic chứ không phải phần cứng.","D":"• Thuật toán giải quyết bài toán chứ không tạo ra bài toán."}}},{"id":30,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":30,"chooseType":"Choose 1 answer","question":"Which of the following describes why explainability is important in AI?","options":{"A":"It is necessary so internal stakeholders understand code","B":"It provides interpretations of system actions","C":"It provides accountability and trust for users and auditors","D":"It enables explanation for shareholder purposes"},"answer":"C","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây giải thích tại sao tính giải thích được (Explainability) lại quan trọng trong AI?","optionsVi":{"A":"Cần thiết cho nhân viên hiểu mã","B":"Cung cấp diễn giải hành động","C":"Nó cung cấp trách nhiệm giải trình và xây dựng lòng tin cho người dùng cùng các kiểm toán viên (provides accountability and trust)","D":"Giải thích cho cổ đông"},"answerDisplay":"C. It provides accountability and trust","concept":"• Explainable AI (XAI) tạo nền tảng cho Accountability (Trách nhiệm giải trình) và Trust (Lòng tin) vào các quyết định tự động.","whyCorrect":"• Khả năng giải thích giúp đảm bảo trách nhiệm pháp lý và tạo dựng niềm tin công chúng.","whyWrong":{"A":"• Hiểu mã nguồn là công việc kỹ thuật.","B":"• Diễn giải hành động chỉ là một phần kỹ thuật nhỏ.","D":"• Báo cáo cổ đông thuộc về tài chính."}}},{"id":31,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":31,"chooseType":"Choose 1 answer","question":"What is the Turing test used for?","options":{"A":"To test whether an AI system is capable of tricking a human into thinking it is another human","B":"To test whether AI can think exactly like a human brain","C":"To test whether AI is trustworthy","D":"To test system availability"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Bài kiểm tra Turing (Turing test) được sử dụng để làm gì?","optionsVi":{"A":"Để kiểm tra xem hệ thống AI có khả năng đánh lừa con người khiến họ tin rằng đó là một con người khác hay không (tricking a person into thinking it's human)","B":"Kiểm tra xem AI có suy nghĩ như não người","C":"Kiểm tra AI có đáng tin không","D":"Kiểm tra tính sẵn sàng hệ thống"},"answerDisplay":"A. To test whether an Al system is capable of tricking a person into thinking it's another person.","concept":"• Turing Test (Alan Turing, 1950): Đánh giá khả năng bộc lộ hành vi trí tuệ của máy tính đến mức con người không thể phân biệt được với người thật qua hội thoại.","whyCorrect":"• Đánh lừa con người trong giao tiếp hội thoại là tiêu chuẩn của bài kiểm tra Turing.","whyWrong":{"B":"• Turing test đo lường hành vi giao tiếp bên ngoài chứ không mô phỏng sinh học não bộ.","C":"• Tính đáng tin thuộc về Trustworthy AI.","D":"• Sẵn sàng là chỉ số Uptime."}}},{"id":32,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":32,"chooseType":"Choose 1 answer","question":"Predictive loops in marketplace models like dating apps are especially susceptible to bias due to:","options":{"A":"Fairness quotients","B":"Marketplace forces","C":"Engagement levels","D":"Short feedback cycles that reinforce initial bias rapidly"},"answer":"D","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Các vòng lặp dự đoán trong các mô hình thị trường như ứng dụng hẹn hò đặc biệt dễ bị ảnh hưởng bởi thiên vị do:","optionsVi":{"A":"Chỉ số công bằng","B":"Lực lượng thị trường","C":"Mức độ tương tác","D":"Chu kỳ phản hồi ngắn làm củng cố và khuếch đại nhanh chóng các thiên vị ban đầu (Short feedback cycles)"},"answerDisplay":"D. short feedback cycles","concept":"• Short Feedback Loops: Dữ liệu hành vi người dùng (quẹt trái/phải) lập tức quay lại huấn luyện mô hình, tạo ra vòng lặp khuếch đại định kiến cực nhanh.","whyCorrect":"• Chu kỳ phản hồi ngắn tăng tốc độ khắc sâu các định kiến lựa chọn ban đầu.","whyWrong":{"A":"• Chỉ số công bằng giúp giảm thiên vị.","B":"• Lực lượng thị trường là cung cầu tổng thể.","C":"• Mức độ tương tác là thước đo tiếp thị."}}},{"id":33,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":33,"chooseType":"Choose 1 answer","question":"Why are anonymization and pseudonymization insufficient protection measures against data privacy leaks?","options":{"A":"They only work in particular scenarios","B":"They destroy data usefulness","C":"They don't integrate into workflows","D":"They can be broken by combining this data with other publicly available data (Linkage attack)"},"answer":"D","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Tại sao các biện pháp ẩn danh hóa (Anonymization) và giả danh tính (Pseudonymization) không còn đủ để bảo vệ quyền riêng tư dữ liệu?","optionsVi":{"A":"Chỉ hoạt động trong một số kịch bản","B":"Phá hủy tính hữu ích dữ liệu","C":"Không tích hợp được vào luồng công việc","D":"Chúng có thể bị bẻ gãy bằng cách kết hợp tập dữ liệu này với các dữ liệu công khai khác sẵn có (combining with other public data)","E":"Tải toàn bộ bộ nhớ"},"answerDisplay":"D. They can be broken by combining this data with other publicly available data","concept":"• Rủi ro Tái định danh (Re-identification via Linkage Attack): Thuật toán và dữ liệu công khai ngoài (mạng xã hội, báo chí) dễ dàng khôi phục danh tính từ tệp ẩn danh hóa sơ sài.","whyCorrect":"• Kết hợp với các nguồn dữ liệu mở bên ngoài triệt tiêu hiệu quả bảo vệ của ẩn danh truyền thống.","whyWrong":{"A":"• Chúng được áp dụng rộng rãi mọi kịch bản.","B":"• Ẩn danh bảo tồn giá trị thống kê dữ liệu.","C":"• Ẩn danh hóa dễ dàng tích hợp vào pipeline dữ liệu."}}},{"id":34,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":34,"chooseType":"Choose 1 answer","question":"The Children's Online Privacy Protection Act (COPPA) safeguards the privacy of which age group?","options":{"A":"Anyone under 18 years old","B":"Anyone under 13 years old","C":"Anyone between 5 and 13 years old","D":"Anyone between 13 and 18 years old"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Đạo luật bảo vệ quyền riêng tư của trẻ em trên mạng (COPPA) bảo vệ quyền riêng tư của nhóm tuổi nào?","optionsVi":{"A":"Bất kỳ ai dưới 18 tuổi","B":"Bất kỳ trẻ em nào dưới 13 tuổi (Anyone under 13 years old)","C":"Trẻ em từ 5 đến 13 tuổi","D":"Thanh thiếu niên từ 13 đến 18 tuổi"},"answerDisplay":"B. Anyone under 13 years old","concept":"• Đạo luật COPPA (Mỹ): Quy định nghiêm ngặt việc thu thập thông tin cá nhân trực tuyến từ trẻ em dưới 13 tuổi phải có sự đồng ý của cha mẹ.","whyCorrect":"• Độ tuổi bảo vệ pháp lý của COPPA được quy định chính xác là dưới 13 tuổi.","whyWrong":{"A":"• Dưới 18 tuổi là độ tuổi vị thành niên nói chung.","C":"• COPPA bảo vệ từ 0 đến dưới 13 tuổi.","D":"• 13 đến 18 tuổi chịu điều chỉnh của các quy định khác."}}},{"id":35,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":35,"chooseType":"Choose 1 answer","question":"Why does the trolley problem pose an ethical predicament for autonomous vehicles?","options":{"A":"It requires programming trade-off decisions between harming different human lives in unavoidable accidents","B":"It forces cars to follow traffic lights","C":"It limits battery capacity","D":"It creates sensor blind spots"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Tại sao Bài toán xe đứt thắng (Trolley problem) lại đặt ra một thế lưỡng nan về đạo đức cho xe tự hành?","optionsVi":{"A":"Nó bắt buộc lập trình viên phải đưa ra các quyết định đánh đổi về việc gây tổn hại cho ai trong các thảm họa tai nạn không thể tránh khỏi (trade-off decisions between harming human lives)","B":"Bắt xe tuân thủ đèn giao thông","C":"Giới hạn dung lượng pin","D":"Tạo ra điểm mù cảm biến"},"answerDisplay":"A. It requires programming trade-off decisions between harming different human lives in unavoidable accidents","concept":"• Trolley Problem trong AI Xe tự hành: Lập trình thuật toán phải quyết định thế nào khi va chạm là không thể tránh khỏi (hy sinh hành khách hay người đi bộ).","whyCorrect":"• Thế lưỡng nan đạo đức khi bắt thuật toán chọn lựa sự hy sinh giữa các sinh mệnh con người.","whyWrong":{"B":"• Tuân thủ đèn giao thông là quy tắc luật cơ bản.","C":"• Dung lượng pin là thông số kỹ thuật phần cứng.","D":"• Điểm mù cảm biến là lỗi an toàn vật lý."}}},{"id":36,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":36,"chooseType":"Choose 1 answer","question":"A goal of a fair model's accuracy standards is to:","options":{"A":"Minimize the error rate as long as parity is obtained","B":"Minimize fairness score","C":"Minimize quality metrics","D":"Minimize dataset size"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Mục tiêu về tiêu chuẩn độ chính xác của một mô hình công bằng là gì?","optionsVi":{"A":"Tối thiểu hóa tỷ lệ lỗi (Error rate) chừng nào tính bình đẳng/ngang bằng (Parity) giữa các nhóm vẫn được đảm bảo (minimize error rate as long as parity is obtained)","B":"Tối thiểu hóa điểm công bằng","C":"Tối thiểu hóa chỉ số chất lượng","D":"Tối thiểu hóa kích thước tập dữ liệu"},"answerDisplay":"A. minimize the error rate as long as parity is obtained","concept":"• Fairness-Constrained Accuracy Optimization: Đạt được độ chính xác tối đa (lỗi thấp nhất) trong phạm vi ràng buộc công bằng giữa các nhóm.","whyCorrect":"• Giảm thiểu sai số nhưng bắt buộc duy trì sự bình đẳng chỉ số giữa các nhóm.","whyWrong":{"B":"• Mục tiêu là tối đa hóa tính công bằng.","C":"• Chất lượng mô hình cần được tối ưu nâng cao.","D":"• Kích thước tập dữ liệu phụ thuộc vào bài toán."}}},{"id":37,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":37,"chooseType":"Choose 1 answer","question":"A 'purposefully biased' algorithm used by auditors to identify unfair attributes in system decisions is an example of:","options":{"A":"Bias testing and algorithmic auditing","B":"Data corruption","C":"Malicious hacking","D":"System failure"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Một thuật toán được 'cố ý thiết kế thiên vị' bởi các kiểm toán viên nhằm phát hiện các thuộc tính bất công trong quyết định hệ thống là ví dụ về:","optionsVi":{"A":"Kiểm thử thiên vị và kiểm toán thuật toán (Bias testing and algorithmic auditing)","B":"Hư hỏng dữ liệu","C":"Hacking độc hại","D":"Lỗi hệ thống"},"answerDisplay":"A. Bias testing and algorithmic auditing","concept":"• Stress-testing AI via Synthetic Bias: Cố ý đưa mẫu thiên vị vào kiểm thử để đánh giá mức độ chống chịu và phản ứng của mô hình kiểm toán.","whyCorrect":"• Sử dụng dữ liệu lệch cố ý để đo lường tính nhạy cảm thiên vị của hệ thống.","whyWrong":{"B":"• Không làm hỏng cấu trúc dữ liệu.","C":"• Đây là hoạt động kiểm toán an toàn hợp pháp.","D":"• Đây là phương pháp kiểm thử chủ động."}}},{"id":38,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":38,"chooseType":"Choose 1 answer","question":"Fairness in machine learning is best defined as:","options":{"A":"Just treatment without prejudice or favorism across protected groups","B":"Achieving 100% accuracy on all datasets","C":"Maximizing company profit margins","D":"Removing all human involvement"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Tính công bằng (Fairness) trong học máy được định nghĩa chuẩn xác nhất là gì?","optionsVi":{"A":"Sự đối xử công minh, không có định kiến hay thiên vị giữa các nhóm đối tượng được bảo vệ (Just treatment without prejudice)","B":"Đạt độ chính xác 100%","C":"Tối đa hóa lợi nhuận công ty","D":"Loại bỏ hoàn toàn con người"},"answerDisplay":"A. Just treatment without prejudice","concept":"• Định nghĩa Fairness: Đảm bảo mô hình AI đưa ra quyết định không bị ảnh hưởng tiêu cực bởi các thuộc tính nhạy cảm được bảo vệ (giới tính, chủng tộc, tuổi tác).","whyCorrect":"• Đối xử bình đẳng không định kiến là bản chất của Fairness.","whyWrong":{"B":"• Độ chính xác 100% không đảm bảo tính không thiên vị.","C":"• Lợi nhuận là mục tiêu thương mại.","D":"• Loại bỏ con người không quyết định tính công bằng."}}},{"id":39,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":39,"chooseType":"Choose 1 answer","question":"What is the capability caution in AI risk management?","options":{"A":"Ensuring human capabilities are not limited","B":"Freezing AI development completely","C":"Remembering we don't know the full extent of what AI systems might become capable of so we can better plan risk mitigation","D":"Assuming AI capabilities are completely known"},"answer":"C","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Thận trọng về năng lực (Capability caution) trong quản lý rủi ro AI là gì?","optionsVi":{"A":"Đảm bảo năng lực con người không bị hạn chế","B":"Đóng băng sự phát triển AI","C":"Luôn ghi nhớ rằng chúng ta chưa thể biết hết toàn bộ quy mô năng lực mà các hệ thống AI có thể đạt tới để lập kế hoạch quản lý rủi ro tốt hơn (remembering we don't know full extent of AI capabilities)","D":"Giả định đã biết hết năng lực AI"},"answerDisplay":"C. We need to remember that we don't know the full extent of what Al systems might become capable of so that we can better plam","concept":"• Capability Caution Principle: Thừa nhận sự bất định về sức mạnh tương lai của AI để xây dựng hàng rào an toàn phòng ngừa rủi ro vượt kiểm soát.","whyCorrect":"• Tự nhận thức giới hạn hiểu biết về sự tiến hóa của AI để chuẩn bị phương án quản trị rủi ro.","whyWrong":{"A":"• Giới hạn con người không phải trọng tâm quản lý rủi ro AI.","B":"• Đóng băng công nghệ là giải pháp không thực tế.","D":"• Chủ quan cho rằng đã biết hết gây nguy cơ thảm họa."}}},{"id":40,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":40,"chooseType":"Choose 1 answer","question":"Which of the following principle sets are important for the creation of open data ecosystems?","options":{"A":"FAIR (Findable, Accessible, Interoperable, Reusable)","B":"ISO 27001","C":"PCI DSS","D":"COPPA"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Bộ nguyên tắc nào sau đây là quan trọng cho việc xây dựng các hệ sinh thái dữ liệu mở (Open Data)?","optionsVi":{"A":"FAIR (Dễ tìm, Dễ truy cập, Khả năng tương tác, Dễ tái sử dụng)","B":"ISO 27001","C":"PCI DSS","D":"COPPA"},"answerDisplay":"A. FAIR","concept":"• Nguyên tắc dữ liệu FAIR (Findable, Accessible, Interoperable, Reusable) là khung tiêu chuẩn dữ liệu mở toàn cầu.","whyCorrect":"• Tiêu chuẩn FAIR quy định khả năng chia sẻ và chia sẻ lại dữ liệu mở khoa học.","whyWrong":{"B":"• ISO 27001 là tiêu chuẩn an toàn thông tin doanh nghiệp.","C":"• PCI DSS là bảo mật thẻ ngân hàng.","D":"• COPPA là bảo vệ riêng tư trẻ em."}}},{"id":41,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":41,"chooseType":"Choose 1 answer","question":"How do you create an ethical organizational culture?","options":{"A":"Transparency about company values through continuous actions and open communication","B":"Top-down strict communication about company values only","C":"Bottom-up communication without management involvement","D":"Having static documents that describe values"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Làm thế nào để bạn xây dựng một văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Minh bạch về các giá trị của công ty thông qua hành động nhất quán và truyền thông mở (Transparency about company values)","B":"Chỉ truyền thông mệnh lệnh từ trên xuống","C":"Truyền thông từ dưới lên không có quản lý","D":"Chỉ có các văn bản tài liệu tĩnh"},"answerDisplay":"A. Transparency about company values.","concept":"• Xây dựng văn hóa đạo đức yêu cầu sự Minh bạch giá trị (Transparency), nêu gương từ lãnh đạo và giao tiếp hai chiều công khai.","whyCorrect":"• Minh bạch giá trị cốt lõi đi đôi với hành động tạo dựng niềm tin cho toàn tổ chức.","whyWrong":{"B":"• Mệnh lệnh một chiều gây tâm lý đối phó.","C":"• Thiếu cam kết ban quản lý khiến văn hóa không được bảo đảm.","D":"• Tài liệu tĩnh không đi vào thực tế hành động."}}},{"id":42,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":42,"chooseType":"Choose 1 answer","question":"Which of the following describes the purpose of having an Ethics Board for a data-driven organization?","options":{"A":"An Ethics Board can help maintain an organization's values-based intentions and increase transparency into how they use data-driven technologies","B":"An Ethics Board can help maintain profit margins","C":"An Ethics Board decreases inherent dangers of autonomous technologies","D":"An Ethics Board focuses only on internal employee disputes"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng mục đích của việc thành lập Hội đồng Đạo đức (Ethics Board) cho một tổ chức dựa trên dữ liệu?","optionsVi":{"A":"Hội đồng Đạo đức giúp duy trì các định hướng dựa trên giá trị của tổ chức và tăng cường tính minh bạch trong việc sử dụng công nghệ dựa trên dữ liệu (maintain values-based intentions and increase transparency)","B":"Duy trì biên lợi nhuận","C":"Giảm nguy cơ tự động","D":"Chỉ giải quyết tranh chấp nội bộ"},"answerDisplay":"A. An Ethics Board can help maintain an organization's values-based intentions and increase transparency into how they use data-driven technologies _","concept":"• Hội đồng Đạo đức (Ethics Board) giữ vai trò định hướng giá trị đạo đức và giám sát minh bạch quy trình sử dụng AI trong tổ chức.","whyCorrect":"• Định hướng giá trị cốt lõi và đảm bảo minh bạch là hai nhiệm vụ quan trọng nhất của Ethics Board.","whyWrong":{"B":"• Biên lợi nhuận thuộc về Hội đồng quản trị kinh doanh.","C":"• Giảm nguy cơ tự động là công việc kỹ thuật.","D":"• Tranh chấp nội bộ thuộc về phòng Nhân sự HR."}}},{"id":43,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":43,"chooseType":"Choose 1 answer","question":"Which of the following is a potential benefit of having an ethical organizational culture?","options":{"A":"More employees are likely to switch careers","B":"Employees will feel a sense of responsibility, trust, and organizational loyalty","C":"Employees are more likely to blindly obey superiors","D":"The company will get an immediate stock value increase"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Lợi ích tiềm năng nào của việc sở hữu một văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Nhiều nhân viên muốn chuyển nghề hơn","B":"Nhân viên sẽ cảm thấy có tinh thần trách nhiệm, lòng tin và sự gắn kết trung thành với tổ chức (sense of responsibility and loyalty)","C":"Nhân viên tuân lệnh mù quáng","D":"Giá cổ phiếu tăng tức thì"},"answerDisplay":"B. Employees will feel a sense of responsibility and loyalty.","concept":"• Tác động tích cực của Văn hóa Đạo đức: Thúc đẩy sự gắn kết (Employee Engagement), gia tăng lòng trung thành và tinh thần trách nhiệm công việc.","whyCorrect":"• Nhân viên cảm thấy tự hào và có trách nhiệm khi làm việc trong môi trường minh bạch đạo đức.","whyWrong":{"A":"• Văn hóa tốt làm giảm tỷ lệ nghỉ việc (Turnover rate).","C":"• Văn hóa đạo đức khuyến khích phản biện tích cực chứ không tuân lệnh mù quáng.","D":"• Văn hóa tạo giá trị bền vững dài hạn chứ không tăng giá cổ phiếu tức thì."}}},{"id":44,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":44,"chooseType":"Choose 1 answer","question":"Why is fair competition an important ethical consideration for data-driven technology businesses?","options":{"A":"Fair competition prevents predatory pricing","B":"Fair competition builds user trust and prevents monopoly exploitation in data ecosystems","C":"Fair competition provides product choices","D":"Fair competition provides service choices"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Tại sao cạnh tranh công bằng (Fair competition) lại là một xem xét đạo đức quan trọng đối với các doanh nghiệp công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Ngăn chặn định giá độc hại","B":"Cạnh tranh công bằng xây dựng lòng tin người dùng và ngăn chặn sự lạm dụng vị thế độc quyền dữ liệu (builds user trust and prevents monopoly exploitation)","C":"Cung cấp lựa chọn sản phẩm","D":"Cung cấp lựa chọn dịch vụ"},"answerDisplay":"B. Fair competition builds user trust in technology as a whole.","concept":"• Anti-monopoly & Data Governance: Cạnh tranh công bằng ngăn chặn Big Tech lạm dụng vị thế độc quyền dữ liệu để bóp nghẹt đổi mới sáng tạo và thao túng người dùng.","whyCorrect":"• Xây dựng lòng tin chung cho toàn bộ hệ sinh thái công nghệ và bảo vệ người tiêu dùng.","whyWrong":{"A":"• Định giá chỉ là một chiêu thức thương mại.","C":"• Lựa chọn sản phẩm là kết quả thương mại.","D":"• Lựa chọn dịch vụ là kết quả thị trường."}}},{"id":45,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":45,"chooseType":"Choose 1 answer","question":"Which of the following describes change management in the context of organizational ethics?","options":{"A":"A collective term used to describe how employees voice concerns","B":"A collective term for all approaches to prepare, support, and help individuals, teams, and organizations in making organizational change toward an ethical culture","C":"A collective term for product modifications after negative feedback","D":"A process to replace executive board members"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả Quản lý sự thay đổi (Change management) trong bối cảnh đạo đức tổ chức?","optionsVi":{"A":"Thuật ngữ mô tả cách nhân viên lên tiếng","B":"Thuật ngữ chung cho tất cả các phương pháp nhằm chuẩn bị, hỗ trợ và giúp đỡ cá nhân, đội ngũ và tổ chức thực hiện sự chuyển đổi sang văn hóa đạo đức (approaches to prepare, support, help in making organizational change)","C":"Sửa đổi sản phẩm sau phản hồi tiêu cực","D":"Quy trình thay thế ban điều hành"},"answerDisplay":"B. A collective term for all approaches to prepare, support, and help individuals, teams, and organizations in fostering an ethical organizational culture.","concept":"• Change Management: Quy trình quản trị chuyển đổi hành vi, tư duy và cấu trúc tổ chức hướng tới các chuẩn mực văn hóa đạo đức mới.","whyCorrect":"• Hỗ trợ toàn diện cá nhân và tập thể thích nghi với sự thay đổi văn hóa tổ chức.","whyWrong":{"A":"• Lên tiếng là Employee Voice.","C":"• Sửa sản phẩm là Product Iteration.","D":"• Thay ban điều hành là Executive succession planning."}}},{"id":46,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":46,"chooseType":"Choose 1 answer","question":"Which expression best characterizes what a company or organizational culture is?","options":{"A":"'This is how we want this done.'","B":"'This is how things are done around here.'","C":"'It is what it is.'","D":"'This is what we're told to do.'"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Câu nói nào sau đây thể hiện rõ nét nhất bản chất của Văn hóa tổ chức (Organizational culture)?","optionsVi":{"A":"'Đây là cách chúng tôi muốn điều này được làm.'","B":"'Đây là cách mọi việc được thực hiện ở nơi đây.' ('This is how things are done around here.')","C":"'Nó là như vậy rồi.'","D":"'Đây là những gì chúng tôi được bảo phải làm.'"},"answerDisplay":"B. \"This is how things are done around here.\"","concept":"• Định nghĩa kinh điển của Văn hóa tổ chức: 'The way we do things around here' - Thói quen, niềm tin và hành vi ứng xử ngầm định hàng ngày của tập thể.","whyCorrect":"• Thể hiện thói quen ứng xử và chuẩn mực hành động thực tế đã ăn sâu vào tổ chức.","whyWrong":{"A":"• Đây là mong muốn lý thuyết của quản lý.","C":"• Thể hiện thái độ buông xuôi.","D":"• Thể hiện sự tuân thủ mệnh lệnh thụ động."}}},{"id":47,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":47,"chooseType":"Choose 1 answer","question":"Which of the following is an ethical benefit of incorporating fair competition considerations in a data-driven technology ecosystem?","options":{"A":"Consolidating products and services under a single organization","B":"Encouraging product or service differentiation and user empowerment","C":"Lowering product and service costs for users","D":"Accelerating investments in research"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Lợi ích đạo đức của việc đưa các xem xét cạnh tranh công bằng vào hệ sinh thái công nghệ dựa trên dữ liệu là gì?","optionsVi":{"A":"Sáp nhập các sản phẩm về một tập đoàn","B":"Khuyến khích sự đa dạng hóa/sự khác biệt của sản phẩm dịch vụ và trao quyền cho người dùng (Encouraging product differentiation and user empowerment)","C":"Hạ giá thành sản phẩm","D":"Tăng tốc đầu tư R&D"},"answerDisplay":"B. Encouraging product or service differentiation","concept":"• Lợi ích của Fair Competition: Tránh sự độc quyền cồng kềnh, thúc đẩy đổi mới sáng tạo đa dạng và trao cho người dùng quyền tự do lựa chọn giải pháp.","whyCorrect":"• Thúc đẩy sự đa dạng giải pháp công nghệ và trao quyền lựa chọn tự do cho người tiêu dùng.","whyWrong":{"A":"• Sáp nhập tập trung gây độc quyền nguy hiểm.","C":"• Hạ giá thành là lợi ích kinh tế ngắn hạn.","D":"• Tăng R&D là mục tiêu đầu tư doanh nghiệp."}}},{"id":48,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":48,"chooseType":"Choose 1 answer","question":"An ethical impact assessment is:","options":{"A":"Focused on past ethical risks","B":"Focused on identifying and preventing future potential ethical problems (Forward-looking)","C":"Focused on identifying causes of past errors","D":"Focused on audit compliance"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Một Đánh giá Tác động Đạo đức (Ethical Impact Assessment - EIA) có đặc điểm trọng tâm là gì?","optionsVi":{"A":"Tập trung vào các rủi ro đạo đức trong quá khứ","B":"Tập trung vào việc nhận diện và phòng ngừa các vấn đề đạo đức tiềm tàng trong tương lai (Focused on preventing future problems)","C":"Tập trung tìm nguyên nhân lỗi quá khứ","D":"Tập trung vào tuân thủ kiểm toán"},"answerDisplay":"B. Focused on preventing future problems.","concept":"• Ethical Impact Assessment (EIA) là công cụ chủ động hướng về tương lai (Proactive / Forward-looking) giúp đánh giá tác động trước khi triển khai công nghệ.","whyCorrect":"• Chủ động nhận diện và triệt tiêu các nguy cơ sự cố đạo đức trước khi sản phẩm ra mắt.","whyWrong":{"A":"• Đánh giá sự cố quá khứ là Post-mortem audit.","C":"• Tìm nguyên nhân cũ là Root cause analysis.","D":"• Tuân thủ kiểm toán chỉ là một phần thủ tục."}}},{"id":49,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":49,"chooseType":"Choose 1 answer","question":"Which of the following presents the most important argument for why we need to consider the impact of AI on labor in the design, development, and deployment of data-driven technology?","options":{"A":"There is still a need for human workers in human-in-the-loop mechanisms","B":"The organization would like to avoid union concerns","C":"There may be an impact on worker productivity","D":"There might be potential labor rights and human rights violations (job displacement, economic disenfranchisement)"},"answer":"D","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Lập luận quan trọng nhất giải thích tại sao chúng ta cần xem xét tác động của AI đối với lao động trong việc thiết kế, phát triển và triển khai công nghệ dựa trên dữ liệu là gì?","optionsVi":{"A":"Vẫn cần lao động con người trong cơ chế Human-in-the-loop","B":"Tổ chức muốn tránh rắc rối với công đoàn","C":"Có thể ảnh hưởng tới năng suất người lao động","D":"Có thể nảy sinh các vi phạm tiềm tàng về quyền lao động và quyền con người như mất việc làm và tước đoạt sinh kế (potential labor rights and human rights violations)"},"answerDisplay":"D. There might be potential labor rights and human rights violations.","concept":"• AI & Labor Ethics: Nguy cơ thay thế lao động quy mô lớn và tước đoạt sinh kế đe dọa trực tiếp tới Quyền con người và Quyền lao động cơ bản.","whyCorrect":"• Bảo vệ nhân quyền và quyền lao động trước nguy cơ bị tự động hóa đào thải là lý do đạo đức cao nhất.","whyWrong":{"A":"• Human-in-the-loop là giải pháp kỹ thuật.","B":"• Tránh công đoàn là lợi ích hành chính của người sử dụng lao động.","C":"• Năng suất là chỉ số hiệu quả kinh tế."}}},{"id":50,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":50,"chooseType":"Choose 1 answer","question":"Which of the following are potential training data inadequacies that you should communicate to your users in support of transparency? (Select two.)","options":{"A":"The amount of time it took to collect data","B":"Any known bias in the sample data","C":"The relatively large size of dataset","D":"Any missing values in dataset and how they were handled"},"answer":"B, D","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Những sự thiếu sót/bất cập tiềm tàng nào trong dữ liệu huấn luyện mà bạn nên truyền thông minh bạch tới người dùng? (Select two)","optionsVi":{"A":"Thời gian thu thập dữ liệu","B":"Bất kỳ thiên vị đã biết nào trong dữ liệu mẫu (Any known bias in the sample data)","C":"Kích thước lớn của tập dữ liệu","D":"Bất kỳ giá trị bị khuyết nào trong tập dữ liệu và cách chúng được xử lý (Any missing values and how handled)"},"answerDisplay":"B. Any known bias in the sample data & D. Any missing values in the dataset and how they were handled.","concept":"• Minh bạch dữ liệu (Data Transparency): Công khai hạn chế của dữ liệu mẫu (Known Bias) và phương pháp xử lý dữ liệu thiếu (Missing Value Handling).","whyCorrect":"• Công khai thiên vị và cách xử lý dữ liệu khuyết giúp người dùng hiểu rõ giới hạn và độ tin cậy của mô hình.","whyWrong":{"A":"• Thời gian thu thập không phản ánh chất lượng nội tại của dữ liệu.","C":"• Kích thước lớn không phải sự thiếu sót cần cảnh báo."}}},{"id":51,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":51,"chooseType":"Choose 1 answer","question":"Which of the following benefits can be gained from establishing baseline system behaviors? (Select two.)","options":{"A":"Tracking deviance from norms","B":"Optimizing costs of operation","C":"Restoring compromised functionality through a system rollback","D":"Holding employees more accountable"},"answer":"A, C","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Những lợi ích nào sau đây có thể đạt được từ việc thiết lập các hành vi hệ thống cơ sở (Baseline system behaviors)? (Select two)","optionsVi":{"A":"Theo dõi và phát hiện sự sai lệch so with chuẩn mực vận hành (Tracking deviance from norms)","B":"Tối ưu hóa chi phí vận hành","C":"Khôi phục lại chức năng bị xâm nhập thông qua khôi phục hệ thống về trạng thái cơ sở (Restoring functionality through system rollback)","D":"Buộc nhân viên chịu trách nhiệm nhiều hơn"},"answerDisplay":"A. Tracking deviance from norms & C. Restoring compromised functionality through a system rollback","concept":"• Baseline Behavior: Giúp phát hiện nhanh các dấu hiệu bất thường (Deviance) và cung cấp điểm mốc an toàn để khôi phục (Rollback) khi bị tấn công.","whyCorrect":"• Phát hiện sai lệch bất thường và làm điểm mốc rollback khôi phục hệ thống là 2 lợi ích an ninh cốt lõi.","whyWrong":{"B":"• Tối ưu chi phí thuộc về FinOps.","D":"• Quản lý trách nhiệm nhân viên thuộc về quy trình nhân sự."}}},{"id":52,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":52,"chooseType":"Choose 1 answer","question":"Which of the following are tools of an effective media communication plan? (Select two.)","options":{"A":"Mission statement","B":"Press release","C":"Public education campaign","D":"Video briefing"},"answer":"B, C","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Những công cụ nào sau đây thuộc về một kế hoạch truyền thông báo chí/truyền thông hiệu quả? (Select two)","optionsVi":{"A":"Tuyên bố sứ mệnh","B":"Thông cáo báo chí (Press release)","C":"Chiến dịch giáo dục công chúng (Public education campaign)","D":"Tóm tắt video nội bộ"},"answerDisplay":"B. Press release & C. Public education campaign","concept":"• Kế hoạch truyền thông báo chí sử dụng các công cụ công bố chính thức như Press Release và các chiến dịch nâng cao nhận thức cộng đồng (Public Education Campaign).","whyCorrect":"• Thông cáo báo chí và chiến dịch giáo dục là hai công cụ truyền thông đối ngoại chính yếu.","whyWrong":{"A":"• Tuyên bố sứ mệnh là định hướng chiến lược nội bộ.","D":"• Video briefing là công cụ giao tiếp nội bộ."}}},{"id":53,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":53,"chooseType":"Choose 1 answer","question":"Which of the following are useful strategies for communicating ethical risks to the individual? (Select two.)","options":{"A":"Ensure individuals understand specific details of each risk","B":"Communicate to individuals proactively rather than reactively","C":"Inform individuals of how they are obligated to mitigate risks","D":"Ensure individuals feel that they have input into the process (User empowerment)"},"answer":"B, D","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Những chiến lược nào sau đây là hữu ích để truyền thông các rủi ro đạo đức tới từng cá nhân người dùng? (Select two)","optionsVi":{"A":"Đảm bảo cá nhân hiểu từng chi tiết rủi ro","B":"Truyền thông tới cá nhân một cách chủ động thay vì bị động phản ứng (Communicate proactively rather than reactively)","C":"Yêu cầu cá nhân tự giảm thiểu rủi ro","D":"Đảm bảo cá nhân cảm thấy họ có quyền đóng góp ý kiến vào quy trình (Ensure individuals feel they have input)"},"answerDisplay":"B. Communicate to individuals proactively rather than reactively & D. Ensure individuals feel that they have input into the process","concept":"• Truyền thông rủi ro cá nhân hiệu quả: Cần thể hiện sự Chủ động (Proactive) và Trao quyền đóng góp (Empowerment) cho người dùng.","whyCorrect":"• Chủ động cảnh báo và lắng nghe đóng góp ý kiến của người dùng giúp tăng hiệu quả bảo vệ riêng tư.","whyWrong":{"A":"• Truyền thông quá chi tiết kỹ thuật gây quá tải nhận thức.","C":"• Đổ trách nhiệm giảm thiểu rủi ro lên người dùng là phi đạo đức."}}},{"id":54,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":54,"chooseType":"Choose 1 answer","question":"Which of the following communication tactics help uphold transparency and explainability from the customer perspective? (Select two.)","options":{"A":"Providing prompt responses to customer questions about AI decisions","B":"Providing information about data-driven systems in simple, easy-to-understand terms","C":"Providing in-depth white papers on algorithms","D":"Providing guidelines for password security"},"answer":"A, B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Những chiến thuật truyền thông nào sau đây giúp duy trì tính minh bạch và khả năng giải thích dưới góc nhìn của khách hàng? (Select two)","optionsVi":{"A":"Cung cấp phản hồi kịp thời cho các câu hỏi của khách hàng về các quyết định tự động của hệ thống (prompt responses to questions about decisions)","B":"Cung cấp thông tin về các hệ thống dựa trên dữ liệu bằng các thuật ngữ đơn giản, dễ hiểu (simple, easy-to-understand terms)","C":"Cung cấp tài liệu kỹ thuật hàn lâm phức tạp","D":"Cung cấp hướng dẫn bảo mật mật khẩu"},"answerDisplay":"A. Providing prompt responses to customer questions about the decisions made by data-driven systems. & B. Providing information about data-driven systems in simple, easy-to-understand terms.","concept":"• Minh bạch góc nhìn người dùng: Phản hồi nhanh chóng thắc mắc và Giải thích bằng ngôn ngữ phổ thông đơn giản.","whyCorrect":"• Phản hồi kịp thời và dùng ngôn ngữ đơn giản giúp khách hàng thực sự thấu hiểu và tin tưởng hệ thống.","whyWrong":{"C":"• Báo cáo hàn lâm quá phức tạp với người dùng đại chúng.","D":"• Hướng dẫn mật khẩu thuộc về an ninh người dùng."}}},{"id":55,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":55,"chooseType":"Choose 1 answer","question":"Which of the following are challenges that can arise if you fail to communicate about the social impact of ethical risks? (Select two.)","options":{"A":"Decreased corporate revenue","B":"Reduced brand loyalty","C":"Disenfranchisement of vulnerable groups","D":"Erosion of fundamental human rights"},"answer":"C, D","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Những thách thức xã hội nào sau đây có thể phát sinh nếu bạn không truyền thông về tác động xã hội của các rủi ro đạo đức? (Select two)","optionsVi":{"A":"Giảm doanh thu công ty","B":"Giảm lòng trung thành thương hiệu","C":"Sự tước đoạt quyền lợi của các nhóm yếu thế (Disenfranchisement)","D":"Sự xói mòn các quyền con người cơ bản (Erosion of rights)"},"answerDisplay":"C. Disenfranchisement & D. Erosion of rights","concept":"• Không truyền thông rủi ro tác động xã hội gây ra các thảm họa nhân văn nghiêm trọng như tước đoạt quyền xã hội và xói mòn nhân quyền.","whyCorrect":"• Tước đoạt quyền lợi nhóm yếu thế và xói mòn nhân quyền là hai tác động xã hội lớn nhất.","whyWrong":{"A":"• Doanh thu là chỉ số tài chính.","B":"• Lòng trung thành thương hiệu là chỉ số tiếp thị."}}},{"id":56,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":56,"chooseType":"Choose 1 answer","question":"Management asks someone to do a data-related task. Which of the following would likely be ethically problematic? (Select two.)","options":{"A":"Manipulate data or alter its interpretation to favor a specific narrative","B":"Aggregate data together","C":"Change data to another format","D":"Delete inconvenient data points to hide negative trends"},"answer":"A, D","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Ban quản lý yêu cầu một nhân viên thực hiện tác vụ liên quan đến dữ liệu. Những hành vi nào sau đây có khả năng cao vi phạm đạo đức? (Select two)","optionsVi":{"A":"Thao túng dữ liệu hoặc cố ý làm sai lệch cách diễn giải dữ liệu (Manipulate data or alter its interpretation)","B":"Gộp tổng hợp dữ liệu","C":"Chuyển đổi dữ liệu sang định dạng khác","D":"Xóa bỏ các điểm dữ liệu bất lợi để che giấu xu hướng tiêu cực (Delete inconvenient data points)"},"answerDisplay":"A. Manipulate data or alter its interpretation. & D. Delete any erroneous data / inconvenient data points","concept":"• Đạo đức Xử lý Dữ liệu: Cấm tuyệt đối hành vi Thao túng diễn giải dữ liệu (Data Manipulation) và Che giấu/Xóa bỏ dữ liệu thực tế bất lợi.","whyCorrect":"• Thao túng diễn giải và xóa dữ liệu bất lợi là hai vi phạm đạo đức dữ liệu nghiêm trọng nhất.","whyWrong":{"B":"• Tổng hợp dữ liệu là bước phân tích chuẩn.","C":"• Chuyển đổi định dạng là kỹ thuật ETL bình thường."}}},{"id":57,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":57,"chooseType":"Choose 1 answer","question":"Which of the following are ways that regulations differ from ethical frameworks? (Select two.)","options":{"A":"Regulations are often industry led","B":"Regulations are flexible in their implementation.","C":"Regulations have legal enforcement behind them.","D":"Regulations provide a clear basis for potential litigation."},"answer":"C, D","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Những điểm nào sau đây phân biệt Quy định pháp lý (Regulations) với Khung làm việc đạo đức (Ethical Frameworks)? (Select two)","optionsVi":{"A":"Quy định thường do ngành dẫn dắt","B":"Quy định linh hoạt khi triển khai","C":"Quy định có sự cưỡng chế thi hành bằng pháp luật (Regulations have legal enforcement behind them)","D":"Quy định cung cấp cơ sở rõ ràng cho các tranh tụng pháp lý (Clear basis for potential litigation)"},"answerDisplay":"C. Regulations have legal enforcement behind them. & D. Regulations provide a clear basis for potential litigation.","concept":"• Sự khác biệt chính giữa Pháp lý và Đạo đức: Pháp lý có tính cưỡng chế (Legal Enforcement) và phạt chế tài trước tòa, còn Khung đạo đức mang tính tự nguyện và tự quản.","whyCorrect":"• Tính cưỡng chế pháp luật và làm cơ sở xử lý tranh tụng tòa án là đặc trưng riêng của văn bản pháp lý.","whyWrong":{"A":"• Khung đạo đức thường do ngành dẫn dắt nhiều hơn quy định nhà nước.","B":"• Quy định pháp lý cứng nhắc hơn khung đạo đức linh hoạt."}}},{"id":58,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":58,"chooseType":"Choose 1 answer","question":"Which of the following best describes beneficence?","options":{"A":"Beneficence is a term coined by IBM for Green Horizons","B":"Beneficence is the active promotion of well-being, not just for moral agents like humans, but of animals, environment, and societies","C":"Beneficence is promotion of well-being for humans only","D":"Beneficence is promotion of efficient system performance"},"answer":"B","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng nhất khái niệm Thuyết làm điều thiện (Beneficence)?","optionsVi":{"A":"Thuật ngữ do IBM đặt ra năm 2014","B":"Beneficence là việc chủ động thúc đẩy sự thịnh vượng/tốt đẹp, không chỉ cho con người mà còn cho động vật, môi trường và toàn xã hội (promotion of well-being for humans, animals, environment, societies)","C":"Beneficence chỉ thúc đẩy lợi ích cho con người","D":"Beneficence là thúc đẩy hiệu suất hệ thống"},"answerDisplay":"B. Beneficence is the promotion of well-being, not just for moral agents like humans, but of animals, the environment, and societies _","concept":"• Beneficence (Thuyết làm điều thiện) bao quát việc chủ động tạo ra tác động tích cực rộng lớn cho con người, hệ sinh thái và toàn xã hội.","whyCorrect":"• Định nghĩa toàn diện về việc tạo dựng lợi ích cho con người, sinh giới và môi trường.","whyWrong":{"A":"• Beneficence là triết lý đạo đức cổ điển có từ thời Hy Lạp.","C":"• Định nghĩa hẹp bỏ qua tác động môi trường sinh thái.","D":"• Hiệu suất hệ thống là chỉ số phần mềm."}}},{"id":59,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":59,"chooseType":"Choose 1 answer","question":"Which of the following are advantages to adopting standards frameworks like ISO 27000? (Select two.)","options":{"A":"Technology-specific focus and precise implementation instructions","B":"Formal certification processes that provide competitive advantage","C":"Regulatory weight and legal enforcement","D":"International support, recognition, and global involvement"},"answer":"B, D","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Những lợi thế nào sau đây thu được khi áp dụng các khung tiêu chuẩn như ISO 27000? (Select two)","optionsVi":{"A":"Tập trung cụ thể công nghệ","B":"Các quy trình chứng nhận chính thức mang lại lợi thế cạnh tranh thương mại (Formal certification processes providing competitive advantage)","C":"Sức mạnh cưỡng chế pháp lý","D":"Sự hỗ trợ, công nhận và thừa nhận quốc tế (International support and recognition)"},"answerDisplay":"B. Formal certification processes that provide competitive advantage & D. International support, recognition, and involvement","concept":"• Lợi ích của Tiêu chuẩn ISO 27000: Có giá trị Chứng nhận Quốc tế (International Recognition) và chứng minh năng lực an ninh mạng giúp tạo lợi thế cạnh tranh.","whyCorrect":"• Chứng nhận ISO mang lại uy tín cạnh tranh quốc tế và được công nhận toàn cầu.","whyWrong":{"A":"• Khung ISO mang tính quản trị chung chứ không hướng dẫn mã nguồn công nghệ cụ thể.","C":"• ISO là tiêu chuẩn tự nguyện chứ không phải luật cưỡng chế."}}},{"id":60,"task":"su24_fe_re","taskLabel":"SU24 FE RE","num":60,"chooseType":"Choose 1 answer","question":"A training set structure based on feeding 60% of data for training, validating on 20% of data, and testing on the remaining 20% is referred to as:","options":{"A":"Classic training set split","B":"Optimized training set split","C":"False positive set","D":"Predictive training set"},"answer":"A","source":"ITE302c_SU24_FE_RE","explanation":{"questionVi":"Cấu trúc tập dữ liệu dựa trên việc nạp 60% dữ liệu để huấn luyện, 20% để kiểm chứng và 20% còn lại để kiểm thử được gọi là:","optionsVi":{"A":"Phân chia tập dữ liệu kinh điển / truyền thống (Classic training set split)","B":"Phân chia tập dữ liệu tối ưu","C":"Tập dữ liệu dương tính giả","D":"Tập dữ liệu dự đoán"},"answerDisplay":"A. classic training set","concept":"• Classic Train/Val/Test Split (60-20-20): Tỷ lệ phân chia kinh điển trong khoa học dữ liệu giúp huấn luyện và đánh giá mô hình khách quan.","whyCorrect":"• 60/20/20 là tên gọi tiêu chuẩn của Classic training set split.","whyWrong":{"B":"• Tối ưu tùy thuộc vào dung lượng dữ liệu tổng thể.","C":"• False positive là loại lỗi dự đoán.","D":"• Predictive training set không phải tên gọi tỷ lệ split."}}},{"id":1,"task":"su24_fe","taskLabel":"SU24 FE","num":1,"chooseType":"Choose 1 answer","question":"You're training a model to classify whether or not a bridge is likely to collapse given several factors. You have a dataset of thousands of existing bridges, where only a handful of bridges are labeled as having collapsed. Given your goal of minimizing bridge collapse, which of the following metrics would be most useful for evaluating the model?","options":{"A":"Accuracy","B":"Confusion matrix","C":"Precision","D":"Recall"},"answer":"D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Bạn đang huấn luyện mô hình phân loại xem một cây cầu có nguy cơ sụp đổ hay không dựa trên các yếu tố. Tập dữ liệu chứa hàng nghìn cây cầu nhưng chỉ có một số rất ít cầu bị sụp đổ. Với mục tiêu tối thiểu hóa nguy cơ sụp cầu gây hậu quả nghiêm trọng, chỉ số nào là hữu ích nhất để đánh giá mô hình?","optionsVi":{"A":"Độ chính xác tổng thể (Accuracy)","B":"Ma trận nhầm lẫn (Confusion matrix)","C":"Độ chính xác khẳng định (Precision)","D":"Độ gợi nhớ / Nhận diện bỏ sót (Recall)"},"answerDisplay":"D. Recall","concept":"• Trong bài toán dữ liệu mất cân bằng (Imbalanced Data) với thảm họa nghiêm trọng (sụp cầu), chỉ số Recall (Độ gợi nhớ) tối thiểu hóa lỗi bỏ sót Âm tính giả (False Negatives).","whyCorrect":"• Recall cao đảm bảo mô hình không bỏ sót bất kỳ cây cầu nào có nguy cơ sụp đổ, bảo vệ tính mạng con người.","whyWrong":{"A":"• Accuracy cao giả tạo do đa số mảng dữ liệu là cầu không sụp.","B":"• Confusion matrix là bảng thống kê tổng hợp chứ không phải một chỉ số số học.","C":"• Precision tập trung giảm dương tính giả (báo nhầm), không ưu tiên giảm bỏ sót thảm họa."}}},{"id":2,"task":"su24_fe","taskLabel":"SU24 FE","num":2,"chooseType":"Choose 1 answer","question":"The Strava dataset example illustrates that while differential privacy can protect individuals, it can still harm:","options":{"A":"Researchers","B":"Those outside the dataset","C":"Certain individuals","D":"Groups"},"answer":"D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Ví dụ tập dữ liệu Strava minh họa rằng mặc dù tính riêng tư vi sai có thể bảo vệ cá nhân, nó vẫn có thể làm lộ/gây hại cho:","optionsVi":{"A":"Các nhà nghiên cứu","B":"Những người ngoài tập dữ liệu","C":"Một số cá nhân cụ thể","D":"Các nhóm / Căn cứ quân sự bí mật (Groups)"},"answerDisplay":"D. groups","concept":"• Dữ liệu ẩn danh hóa Strava (Heatmap) bảo vệ cá nhân nhưng tiết lộ vị trí các căn cứ quân sự bí mật (Group Level Privacy Vulnerability).","whyCorrect":"• Bảo vệ cá nhân không ngăn chặn được việc dữ liệu tổng hợp làm lộ vị trí và hành vi của cả tập thể nhóm.","whyWrong":{"A":"• Các nhà nghiên cứu khai thác dữ liệu không bị tổn hại.","B":"• Người ngoài tập dữ liệu không có dữ liệu di chuyển trên ứng dụng.","C":"• Danh tính cá nhân đơn lẻ đã được bảo vệ thành công."}}},{"id":3,"task":"su24_fe","taskLabel":"SU24 FE","num":3,"chooseType":"Choose 1 answer","question":"In a dataset with significant class imbalance, which of the following accuracy metrics can be deceivingly high?","options":{"A":"Precision","B":"Recall","C":"Accuracy","D":"F1-score"},"answer":"C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Trong một tập dữ liệu có sự mất cân bằng lớp nghiêm trọng (như 99% âm tính, 1% dương tính), chỉ số đo lường nào có thể cao một cách đánh lừa?","optionsVi":{"A":"Precision","B":"Recall","C":"Độ chính xác tổng thể (Accuracy)","D":"F1-score"},"answerDisplay":"C. Accuracy","concept":"• Accuracy Paradox: Một mô hình ngây thơ luôn dự đoán lớp đa số sẽ đạt Accuracy 99% nhưng hoàn toàn vô dụng khi phát hiện lớp yếu thế.","whyCorrect":"• Accuracy tính toán trên toàn bộ tập dữ liệu nên bị che lấp hoàn toàn bởi lớp chiếm đa số tuyệt đối.","whyWrong":{"A":"• Precision đo tỷ lệ đoán đúng trong các mẫu báo positive.","B":"• Recall đo tỷ lệ tìm thấy mẫu positive.","D":"• F1-score là trung bình hài hòa giữa Precision và Recall."}}},{"id":4,"task":"su24_fe","taskLabel":"SU24 FE","num":4,"chooseType":"Choose 1 answer","question":"Which type of machine learning model uses labeled training data to predict outcomes?","options":{"A":"Unsupervised learning","B":"Supervised learning","C":"Reinforcement learning","D":"Clustering"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Loại mô hình học máy nào sử dụng dữ liệu huấn luyện đã được gán nhãn (Labeled training data) để dự đoán kết quả?","optionsVi":{"A":"Học không giám sát (Unsupervised learning)","B":"Học có giám sát (Supervised learning)","C":"Học tăng cường (Reinforcement learning)","D":"Phân cụm (Clustering)"},"answerDisplay":"B. Supervised learning","concept":"• Học có giám sát (Supervised Learning) học ánh xạ từ đầu vào (X) đến nhãn đầu ra (Y) thông qua tập dữ liệu có sẵn nhãn chuẩn.","whyCorrect":"• Định nghĩa nền tảng của Supervised Learning là huấn luyện dựa trên cặp dữ liệu - nhãn (Data-Label pairs).","whyWrong":{"A":"• Unsupervised learning tự tìm cấu trúc trong dữ liệu không có nhãn.","C":"• Reinforcement learning học qua phần thưởng/hình phạt tương tác môi trường.","D":"• Clustering là thuật toán phân nhóm dữ liệu không gán nhãn."}}},{"id":5,"task":"su24_fe","taskLabel":"SU24 FE","num":5,"chooseType":"Choose 1 answer","question":"Which of the following is an example of proxy data causing unintentional discrimination?","options":{"A":"Using race directly to reject loan applications","B":"Using zip code as a feature, which correlates with race","C":"Using credit score to evaluate financial worthiness","D":"Using income level to verify employment status"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Ví dụ nào sau đây thể hiện việc sử dụng dữ liệu thay thế (Proxy data) gây ra phân biệt đối xử vô tình?","optionsVi":{"A":"Sử dụng trực tiếp chủng tộc để từ chối cho vay","B":"Sử dụng mã bưu chính (Zip code) làm thuộc tính, vốn có tương quan mạnh với chủng tộc (Zip code correlates with race)","C":"Sử dụng điểm tín dụng để đánh giá năng lực tài chính","D":"Sử dụng mức thu nhập để xác minh việc làm"},"answerDisplay":"B. Using zip code as a feature, which correlates with race","concept":"• Proxy Attributes (Thuộc tính thay thế) là các thuộc tính tưởng như trung lập (mã zip, trường học) nhưng lại phản ánh lại thuộc tính nhạy cảm bị cấm.","whyCorrect":"• Mã bưu chính có tương quan phân bố dân cư theo chủng tộc, khiến mô hình thiên vị chủng tộc gián tiếp.","whyWrong":{"A":"• Sử dụng trực tiếp chủng tộc là Disparate treatment cố ý.","C":"• Điểm tín dụng là chỉ số tài chính hợp pháp.","D":"• Mức thu nhập là chỉ số năng lực thanh toán."}}},{"id":6,"task":"su24_fe","taskLabel":"SU24 FE","num":6,"chooseType":"Choose 1 answer","question":"The concept of 'Privacy by Design' requires organizations to integrate privacy protections during which phase?","options":{"A":"Only after a data breach occurs","B":"Only during post-deployment maintenance","C":"Throughout the entire system lifecycle from initial design","D":"Only when required by regulators"},"answer":"C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Khái niệm 'Riêng tư theo thiết kế' (Privacy by Design) yêu cầu các tổ chức tích hợp các biện pháp bảo vệ quyền riêng tư vào giai đoạn nào?","optionsVi":{"A":"Chỉ sau khi xảy ra sự cố rò rỉ dữ liệu","B":"Chỉ trong quá trình bảo trì sau triển khai","C":"Xuyên suốt toàn bộ chu kỳ sống hệ thống ngay từ khâu thiết kế ban đầu (Throughout entire lifecycle from design)","D":"Chỉ khi cơ quan quản lý bắt buộc"},"answerDisplay":"C. Throughout the entire system lifecycle from initial design","concept":"• Privacy by Design coi quyền riêng tư là thuộc tính cốt lõi được xây dựng sẵn từ kiến trúc móng ban đầu.","whyCorrect":"• Tích hợp chủ động xuyên suốt vòng đời giúp phòng ngừa rủi ro từ gốc.","whyWrong":{"A":"• Xử lý sau sự cố là biện pháp thụ động bị cấm.","B":"• Bổ sung khi bảo trì là cách làm và lỗi bị động.","D":"• Chỉ làm khi bắt buộc là tuân thủ hình thức."}}},{"id":7,"task":"su24_fe","taskLabel":"SU24 FE","num":7,"chooseType":"Choose 1 answer","question":"Which data protection regulation empowers California residents to request deletion of their personal data?","options":{"A":"GDPR","B":"CCPA","C":"PIPEDA","D":"HIPAA"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Quy định bảo vệ dữ liệu nào trao quyền cho cư dân California yêu cầu xóa dữ liệu cá nhân của họ?","optionsVi":{"A":"GDPR (Châu Âu)","B":"CCPA (Đạo luật quyền riêng tư người tiêu dùng California)","C":"PIPEDA (Canada)","D":"HIPAA (Mỹ - Y tế)"},"answerDisplay":"B. CCPA","concept":"• CCPA (California Consumer Privacy Act) quy định các quyền riêng tư cơ bản cho cư dân bang California.","whyCorrect":"• CCPA là luật chính thức của bang California trao quyền xóa dữ liệu cho người tiêu dùng.","whyWrong":{"A":"• GDPR là luật của Liên minh Châu Âu.","C":"• PIPEDA là luật của Canada.","D":"• HIPAA điều chỉnh dữ liệu y tế toàn Hoa Kỳ."}}},{"id":8,"task":"su24_fe","taskLabel":"SU24 FE","num":8,"chooseType":"Choose 1 answer","question":"What is the primary trade-off when increasing model complexity in deep learning?","options":{"A":"Higher accuracy vs Lower computational cost","B":"Higher performance vs Reduced explainability (Black box problem)","C":"Better user interface vs Lower security","D":"Faster training speed vs Higher storage"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Sự đánh đổi chính khi tăng độ phức tạp của mô hình học sâu là gì?","optionsVi":{"A":"Độ chính xác cao hơn vs Chi phí tính toán thấp hơn","B":"Hiệu suất cao hơn vs Giảm tính giải thích được (Hộp đen AI) (Higher performance vs Reduced explainability)","C":"Giao diện tốt hơn vs Bảo mật kém hơn","D":"Tốc độ huấn luyện nhanh hơn vs Lưu trữ cao hơn"},"answerDisplay":"B. Higher performance vs Reduced explainability","concept":"• Trade-off giữa Performance và Explainability: Mô hình càng phức tạp (nhiều tham số) thì dự đoán càng tốt nhưng càng khó giải thích.","whyCorrect":"• Độ phức tạp toán học tăng làm mô hình thành Hộp đen (Black box), hy sinh tính minh bạch giải thích.","whyWrong":{"A":"• Mô hình phức tạp làm tăng chi phí tính toán.","C":"• Giao diện không liên quan đến kiến trúc mô hình toán.","D":"• Mô hình phức tạp làm chậm tốc độ huấn luyện."}}},{"id":9,"task":"su24_fe","taskLabel":"SU24 FE","num":9,"chooseType":"Choose 1 answer","question":"Which ethical principle advocates that AI technologies should 'do no harm' to human beings?","options":{"A":"Beneficence","B":"Non-maleficence","C":"Justice","D":"Autonomy"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Nguyên tắc đạo đức nào ủng hộ việc các công nghệ AI 'không gây ra tổn hại' cho con người?","optionsVi":{"A":"Thuyết làm điều thiện (Beneficence)","B":"Thuyết không gây hại (Non-maleficence)","C":"Công lý / Bình đẳng (Justice)","D":"Quyền tự quyết (Autonomy)"},"answerDisplay":"B. Non-maleficence","concept":"• Non-maleficence (Do no harm) là nguyên tắc cốt lõi ngăn ngừa tác hại tiêu cực của công nghệ tới con người.","whyCorrect":"• Định nghĩa 'Do no harm' là bản chất của Non-maleficence.","whyWrong":{"A":"• Beneficence là chủ động làm điều có lợi.","C":"• Justice là đảm bảo phân phối công bằng.","D":"• Autonomy là tôn trọng quyền ra quyết định của cá nhân."}}},{"id":10,"task":"su24_fe","taskLabel":"SU24 FE","num":10,"chooseType":"Choose 1 answer","question":"In cybersecurity, which team is responsible for simulating attacks to test system defenses?","options":{"A":"Blue team","B":"Red team","C":"Purple team","D":"White team"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Trong an toàn thông tin, đội ngũ nào chịu trách nhiệm giả lập các cuộc tấn công để kiểm thử hàng rào phòng thủ hệ thống?","optionsVi":{"A":"Đội Xanh (Blue team)","B":"Đội Đỏ (Red team)","C":"Đội Tím (Purple team)","D":"Đội Trắng (White team)"},"answerDisplay":"B. Red team","concept":"• Red Team đóng vai kẻ tấn công thực tế (Adversary simulation) để phát hiện lỗ hổng hệ thống.","whyCorrect":"• Đóng vai kẻ tấn công giả lập là nhiệm vụ của Red Team.","whyWrong":{"A":"• Blue Team chịu trách nhiệm phòng thủ.","C":"• Purple Team phối hợp giữa Red và Blue.","D":"• White Team là trọng tài điều hành diễn tập."}}},{"id":11,"task":"su24_fe","taskLabel":"SU24 FE","num":11,"chooseType":"Choose 1 answer","question":"Why is it important to maintain public trust?","options":{"A":"Trust, once lost, is difficult to regain.","B":"Trust is required to avoid legal pitfalls.","C":"Trust can be used against the organization.","D":"Trust is the new trend of organization."},"answer":"A","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Tại sao việc duy trì lòng tin của công chúng lại cực kỳ quan trọng?","optionsVi":{"A":"Lòng tin một khi đã mất đi thì cực kỳ khó khôi phục lại (Trust, once lost, is difficult to regain)","B":"Lòng tin bắt buộc để tránh rắc rối pháp lý","C":"Lòng tin bị dùng chống lại công ty","D":"Lòng tin là trào lưu tạm thời"},"answerDisplay":"A. Trust, once lost, is difficult to regain.","concept":"• Lòng tin công chúng (Public Trust) là tài sản vô hình quý giá nhất; một khi bị phá hủy bởi scandal đạo đức sẽ mất nhiều năm để gầy dựng lại.","whyCorrect":"• Tính chất khó khôi phục của lòng tin khẳng định tầm quan trọng cốt lõi của việc duy trì uy tín.","whyWrong":{"B":"• Pháp lý tuân thủ bằng luật chứ không dựa vào lòng tin.","C":"• Lòng tin là tài sản bảo vệ công ty.","D":"• Lòng tin là nền tảng bền vững dài hạn."}}},{"id":12,"task":"su24_fe","taskLabel":"SU24 FE","num":12,"chooseType":"Choose 1 answer","question":"What shared principle from ethical frameworks is intellectual property often at odds with?","options":{"A":"Privacy","B":"Safety","C":"Security","D":"Transparency / Explainability"},"answer":"D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Quyền sở hữu trí tuệ (Intellectual Property - bí mật thương mại) thường mâu thuẫn trực tiếp với nguyên tắc đạo đức chung nào?","optionsVi":{"A":"Quyền riêng tư (Privacy)","B":"An toàn (Safety)","C":"An ninh (Security)","D":"Tính minh bạch và tính giải thích được (Transparency / Explainability)"},"answerDisplay":"D. Transparency/explainability","concept":"• Sự xung đột giữa Minh bạch AI và Sở hữu trí tuệ: Các công ty từ chối công khai mã nguồn/mô hình vì lý do bảo hộ bí mật kinh doanh.","whyCorrect":"• Bảo hộ bí mật thuật toán độc quyền trực tiếp ngăn cản yêu cầu công khai giải thích mô hình.","whyWrong":{"A":"• Sở hữu trí tuệ không trực tiếp xung đột với quyền riêng tư cá nhân.","B":"• An toàn là mục tiêu chung.","C":"• An ninh công nghệ được tăng cường nhờ bảo vệ bí mật."}}},{"id":13,"task":"su24_fe","taskLabel":"SU24 FE","num":13,"chooseType":"Choose 1 answer","question":"What is the benefit of hosting a virtual reality press conference over a traditional in-person press conference?","options":{"A":"It will be easier to communicate overall message","B":"The conference will be accessible to all willing participants easily","C":"The conference can be interactive without the participants needing to be co-located","D":"Participants will be impressed by technology"},"answer":"C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Lợi ích của việc tổ chức một cuộc họp báo thực tế ảo (VR Press Conference) so với họp báo trực tiếp truyền thống là gì?","optionsVi":{"A":"Dễ truyền đạt thông điệp chung hơn","B":"Tất cả mọi người đều tham gia dễ dàng","C":"Cuộc họp báo có tính tương tác mà các thành viên tham dự không cần phải tập trung cùng một địa điểm địa lý (interactive without co-located)","D":"Gây ấn tượng bằng công nghệ mới"},"answerDisplay":"C. The conference can be interactive without the participants needing to be co-located.","concept":"• VR Press Conference kết hợp khả năng Tương tác không gian 3D với sự linh hoạt không rào cản khoảng cách địa lý.","whyCorrect":"• Cho phép tương tác trải nghiệm đa chiều mà loại bỏ hạn chế vị trí địa lý thực tế.","whyWrong":{"A":"• Truyền đạt thông điệp phụ thuộc vào nội dung.","B":"• VR đòi hỏi thiết bị chuyên dụng nên hạn chế tiếp cận rộng rãi.","D":"• Gây ấn tượng chỉ là hiệu ứng phụ."}}},{"id":14,"task":"su24_fe","taskLabel":"SU24 FE","num":14,"chooseType":"Choose 1 answer","question":"How can sentiment analysis be useful in social media communication?","options":{"A":"It can shape the content and delivery of the message based on users' perceptions of the organization or technology","B":"It can classify customers as loyal or disloyal","C":"It can determine users with largest influence","D":"It can influence users to be positive"},"answer":"A","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Phân tích cảm xúc (Sentiment Analysis) có thể hữu ích như thế nào trong truyền thông mạng xã hội?","optionsVi":{"A":"Nó giúp định hình nội dung và cách thức phân phối thông điệp dựa trên nhận thức/cảm xúc hiện tại của người dùng đối với tổ chức hoặc công nghệ (shape content and delivery based on perception)","B":"Phân loại khách hàng trung thành hay không","C":"Xác định người có tầm ảnh hưởng lớn nhất","D":"Thao túng người dùng tích cực hơn"},"answerDisplay":"A. It can shape the content and delivery of the message based on users' perceptions of the organization or technology","concept":"• Sentiment Analysis phân tích thái độ dư luận (Tích cực, Tiêu cực, Trung tính) để điều chỉnh chiến lược truyền thông phù hợp.","whyCorrect":"• Hiểu thái độ công chúng giúp tổ chức tinh chỉnh thông điệp và thời điểm phát ngôn tối ưu.","whyWrong":{"B":"• Trung thành là chỉ số Customer Retention.","C":"• Người ảnh hưởng được đo bằng Influencer Metrics.","D":"• Phân tích cảm xúc đo lường thái độ chứ không thao túng tâm lý trực tiếp."}}},{"id":15,"task":"su24_fe","taskLabel":"SU24 FE","num":15,"chooseType":"Choose 1 answer","question":"What is the purpose of a holding statement in crisis and media communications?","options":{"A":"To order the business to temporarily halt operations","B":"To retain the services of specific media outlets","C":"To pre-write communications before they are needed","D":"To prevent personnel from communicating prematurely"},"answer":"D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Mục đích của một phát ngôn giữ chỗ (Holding Statement) trong truyền thông khủng hoảng là gì?","optionsVi":{"A":"Yêu cầu doanh nghiệp tạm dừng hoạt động","B":"Thuê dịch vụ của các cơ quan báo chí cụ thể","C":"Viết trước các văn bản truyền thông khi chưa cần đến","D":"Ngăn chặn nhân viên phát ngôn vội vàng/sớm khi chưa có đủ thông tin xác thực (prevent personnel from communicating prematurely)"},"answerDisplay":"D. To prevent personnel from communicating prematurely","concept":"• Holding Statement là thông cáo ban đầu giúp kiểm soát luồng thông tin, câu thời gian xác minh sự thật và ngăn phát ngôn vội vã.","whyCorrect":"• Tránh việc nhân viên tự ý đưa ra thông tin chưa kiểm chứng làm trầm trọng thêm khủng hoảng.","whyWrong":{"A":"• Holding statement là công cụ truyền thông, không phải lệnh dừng vận hành.","B":"• Không dùng để thuê hợp đồng báo chí.","C":"• Chuẩn bị kịch bản là crisis template, holding statement dùng để công bố tạm thời khi sự cố xảy ra."}}},{"id":16,"task":"su24_fe","taskLabel":"SU24 FE","num":16,"chooseType":"Choose 1 answer","question":"Which of the following is a best practice for incorporating diversity, equity, and inclusiveness in communication?","options":{"A":"Promote an organizational culture that embraces these values","B":"Ensure multiple groups of people communicate in different ways","C":"Focus on intended message rather than incorporating feedback","D":"Reassure customers that organization is diverse"},"answer":"A","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Thực hành tốt nhất nào để tích hợp tính đa dạng, bình đẳng và bao hàm (DEI) vào hoạt động truyền thông?","optionsVi":{"A":"Thúc đẩy một văn hóa tổ chức thực sự đón nhận và sống với các giá trị này (Promote an organizational culture that embraces these values)","B":"Bắt các nhóm giao tiếp khác nhau","C":"Bỏ qua phản hồi từ các bên liên quan","D":"Trấn an khách hàng bằng lời nói"},"answerDisplay":"A. Promote an organizational culture that embraces these values","concept":"• DEI trong truyền thông phải xuất phát từ Văn hóa tổ chức nội bộ (Organizational Culture) thực chất chứ không phải khẩu hiệu tiếp thị rỗng tuếch.","whyCorrect":"• Văn hóa doanh nghiệp thực sự tôn trọng DEI là nền tảng cho mọi thông điệp truyền thông chân thực.","whyWrong":{"B":"• Ép buộc kênh giao tiếp phân biệt tạo thêm rào cản.","C":"• Bỏ qua phản hồi là đi ngược lại tinh thần lắng nghe của DEI.","D":"• Trấn an suông là hành vi tiếp thị tẩy trắng (Diversity washing)."}}},{"id":17,"task":"su24_fe","taskLabel":"SU24 FE","num":17,"chooseType":"Choose 1 answer","question":"How does the low likelihood of a crisis relate to its potential impact?","options":{"A":"A crisis with low likelihood tends to have moderate impact","B":"A crisis with low likelihood tends to have high impact (Black Swan events)","C":"A crisis with low likelihood has little to no effect on impact","D":"A crisis with low likelihood tends to have low impact"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Mối quan hệ giữa xác suất xảy ra thấp của một cuộc khủng hoảng và tác động tiềm tàng của nó là gì?","optionsVi":{"A":"Khủng hoảng có xác suất thấp thường có tác động vừa phải","B":"Một cuộc khủng hoảng có xác suất xảy ra thấp thường có tác động cực kỳ nghiêm trọng khi nó thực sự xảy ra (low likelihood tends to have high impact)","C":"Xác suất không ảnh hưởng tác động","D":"Khủng hoảng xác suất thấp có tác động thấp"},"answerDisplay":"B. A crisis with low likelihood tends to have high impact","concept":"• Sự kiện Thiên nga đen (Black Swan / High-Impact Low-Probability risks): Các sự cố cực hiếm gặp nhưng một khi xảy ra sẽ gây thảm họa tàn phá khủng khiếp.","whyCorrect":"• Các rủi ro hiếm gặp thường bị chủ quan bỏ qua nên khi bùng phát sẽ tạo ra tổn hại quy mô tối đa.","whyWrong":{"A":"• Không dừng ở mức vừa phải.","C":"• Hai chỉ số này liên kết chặt chẽ trong ma trận rủi ro.","D":"• Đánh giá tác động thấp cho sự cố hiếm gặp là sai lầm quản lý rủi ro."}}},{"id":18,"task":"su24_fe","taskLabel":"SU24 FE","num":18,"chooseType":"Choose 1 answer","question":"What is one possible reason a predictive model may predict a higher crime rate based on historical datasets used?","options":{"A":"If drug arrests are historically high in that area, the model may correlate crime with areas of high drug enforcement based on datasets","B":"If crime is down in an area, a model may predict a parabolic curve","C":"The model's training curve was not provided enough data","D":"Formatting error in dataset"},"answer":"A","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Lý do khả thi nào khiến một mô hình dự đoán dự báo tỷ lệ tội phạm cao hơn tại một khu vực dựa trên dữ liệu lịch sử?","optionsVi":{"A":"Nếu số vụ bắt giữ ma túy trong lịch sử cao tại khu vực đó, mô hình sẽ đánh đồng tương quan tỷ lệ tội phạm với tần suất tuần tra bắt giữ (historically high drug arrests correlated with crime)","B":"Mô hình dự báo đường cong hình parabol","C":"Đường cong huấn luyện thiếu dữ liệu","D":"Lỗi định dạng dữ liệu"},"answerDisplay":"A. If drug arrests are historically high in that area, the model may correlate crime with areas of high drug use based on the datasets","concept":"• Feedback Loop in Predictive Policing: Mô hình nhận dữ liệu bắt giữ lịch sử (phản ánh tần suất cảnh sát tuần tra) và nhầm lẫn đó là tỷ lệ tội phạm thực tế.","whyCorrect":"• Phản ánh hiện tượng mô hình AI nhầm lẫn giữa tần suất thực thi pháp luật lịch sử với tỷ lệ tội phạm khách quan.","whyWrong":{"B":"• Mô hình không tự động tạo ra đường cong parabol phi lý.","C":"• Thiếu dữ liệu gây lỗi variance chứ không tạo định kiến khu vực cụ thể.","D":"• Lỗi định dạng gây ra crash mã nguồn."}}},{"id":19,"task":"su24_fe","taskLabel":"SU24 FE","num":19,"chooseType":"Choose 1 answer","question":"Our goals for building an ethical predictive model include making sure the results are:","options":{"A":"Precise, explainable, predictable","B":"Accurate, precise, fair","C":"Precise, methodical, ethical","D":"Accurate, fair and explainable"},"answer":"D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Mục tiêu của chúng ta khi xây dựng một mô hình dự đoán có đạo đức bao gồm đảm bảo các kết quả đầu ra đạt được tiêu chí nào?","optionsVi":{"A":"Chính xác cao, giải thích được, dự đoán được","B":"Đúng đắn, chính xác cao, công bằng","C":"Chính xác cao, có phương pháp, có đạo đức","D":"Đúng đắn, công bằng và có thể giải thích được (Accurate, fair and explainable)"},"answerDisplay":"D. accurate, fair and explainable","concept":"• Bộ ba tiêu chuẩn cho mô hình AI có trách nhiệm: Accuracy (Độ chính xác), Fairness (Tính công bằng) và Explainability (Tính giải thích được).","whyCorrect":"• Ba tiêu chí Accuracy, Fairness và Explainability hợp thành nền tảng của AI có trách nhiệm.","whyWrong":{"A":"• Thiếu tính công bằng (Fairness).","B":"• Thiếu tính giải thích được (Explainability).","C":"• Thiếu tính công bằng và chính xác thực tế."}}},{"id":20,"task":"su24_fe","taskLabel":"SU24 FE","num":20,"chooseType":"Choose 1 answer","question":"Which of the following is an example of applied ethics?","options":{"A":"Pluralism","B":"Professional ethics (or Bioethics / Business ethics)","C":"Moral relativism","D":"Virtue ethics"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Nội dung nào sau đây là một ví dụ về Đạo đức ứng dụng (Applied ethics)?","optionsVi":{"A":"Thuyết đa nguyên (Pluralism)","B":"Đạo đức nghề nghiệp / Đạo đức kinh doanh (Professional ethics)","C":"Thuyết tương đối đạo đức","D":"Thuyết đạo đức đức hạnh"},"answerDisplay":"B. Professional ethics","concept":"• Applied Ethics (Đạo đức ứng dụng) áp dụng các lý thuyết đạo đức vào các lĩnh vực thực tiễn cụ thể như Y học (Bioethics), Kinh doanh (Business ethics), Nghề nghiệp (Professional ethics).","whyCorrect":"• Đạo đức nghề nghiệp là lĩnh vực ứng dụng thực tiễn điển hình của Applied Ethics.","whyWrong":{"A":"• Pluralism là triết lý chính trị/xã hội.","C":"• Moral relativism là triết lý Siêu đạo đức (Meta-ethics).","D":"• Virtue ethics là Lý thuyết đạo đức chuẩn mực (Normative ethics)."}}},{"id":21,"task":"su24_fe","taskLabel":"SU24 FE","num":21,"chooseType":"Choose 1 answer","question":"What is a likely outcome for a weather app using a learning algorithm to figure out where to put their future weather stations?","options":{"A":"Accessing weather forecasts from local broadcasts","B":"Storing data in an AWS instance with all weather stations in the country","C":"Collecting weather data every time the app is opened","D":"Collecting location data every time the app is opened, potentially learning where a user lives, works, etc."},"answer":"D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Hệ quả tiềm tàng đối với quyền riêng tư khi một ứng dụng thời tiết sử dụng thuật toán học máy để xác định vị trí đặt trạm thời tiết tương lai là gì?","optionsVi":{"A":"Truy cập dự báo địa phương","B":"Lưu dữ liệu trên AWS","C":"Thu thập dữ liệu thời tiết mỗi khi mở app","D":"Thu thập dữ liệu vị trí mỗi khi ứng dụng được mở, có khả năng học được nơi người dùng sống và làm việc (potentially learning where a user lives, works)"},"answerDisplay":"D. Collecting location data evety time the app is opened, potentially learning where a user lives, works, etc.","concept":"• Thu thập dữ liệu vị trí GPS liên tục tạo ra rủi ro suy luận thông tin định danh cá nhân nhạy cảm (nhà riêng, cơ quan).","whyCorrect":"• Việc theo dõi vị trí mở app vô tình thu thập thông tin di chuyển cá nhân riêng tư của người dùng.","whyWrong":{"A":"• Xem dự báo là tính năng cơ bản.","B":"• Lưu trữ AWS là hạ tầng điện toán.","C":"• Thu thập thông số thời tiết là dữ liệu khí tượng chung."}}},{"id":22,"task":"su24_fe","taskLabel":"SU24 FE","num":22,"chooseType":"Choose 1 answer","question":"Which of the following describes the black box problem in AI?","options":{"A":"It is difficult to understand the nature of data being used","B":"It is difficult to understand how or why an AI system made a particular decision","C":"It is difficult to understand the results coming from an AI system","D":"It is difficult to generate reports"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả bài toán Hộp đen (Black box problem) trong AI?","optionsVi":{"A":"Khó hiểu bản chất dữ liệu huấn luyện","B":"Rất khó để hiểu cách thức hoặc lý do tại sao hệ thống AI lại đưa ra một quyết định cụ thể (difficult to understand how or why AI made a decision)","C":"Khó hiểu kết quả đầu ra","D":"Khó tạo báo cáo"},"answerDisplay":"B. It is difficult to understand how or why an Al system made a particular decision.","concept":"• Black Box Problem xảy ra khi logic tính toán toán học bên trong của mô hình AI quá phức tạp khiến con người không thể giải thích lý do dẫn đến kết quả.","whyCorrect":"• Không thể giải thích lập luận ra quyết định bên trong của AI là bản chất của vấn đề Black Box.","whyWrong":{"A":"• Bản chất dữ liệu có thể kiểm tra qua Data Profiling.","C":"• Kết quả đầu ra hiển thị rõ ràng.","D":"• Báo cáo là công cụ xuất dữ liệu."}}},{"id":23,"task":"su24_fe","taskLabel":"SU24 FE","num":23,"chooseType":"Choose 1 answer","question":"How can a visual contract be easier to understand than a written contract?","options":{"A":"The use of pictures is more accessible to all people","B":"The use of pictures explains the contract in greater detail","C":"The use of pictures with simple text makes it easier for the layperson to understand the details of a contract","D":"The use of pictures without text makes it easier"},"answer":"C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Làm thế nào một hợp đồng hình ảnh (Visual contract) có thể dễ hiểu hơn một hợp đồng văn bản truyền thống?","optionsVi":{"A":"Hình ảnh tiếp cận tốt hơn với mọi người","B":"Hình ảnh giải thích chi tiết hơn","C":"Việc sử dụng hình ảnh kết hợp với văn bản đơn giản giúp người không chuyên dễ hiểu các chi tiết của hợp đồng hơn (pictures with simple text makes it easier for layperson)","D":"Sử dụng hình ảnh không cần văn bản"},"answerDisplay":"C. The use of pictures with simple text makes it easier for the layperson to understand the details of a contract","concept":"• Legal Design & Visual Contracts: Kết hợp minh họa trực quan với ngôn ngữ phổ thông giúp giảm rào cản nhận thức pháp lý cho người tiêu dùng đại chúng.","whyCorrect":"• Hình ảnh trực quan đi kèm văn bản giản dị giúp người dùng bình thường thấu hiểu các điều khoản pháp lý phức tạp.","whyWrong":{"A":"• Chỉ hình ảnh không thay thế hoàn toàn được thuật ngữ pháp lý.","B":"• Văn bản chi tiết hơn hình ảnh nhưng hình ảnh giúp minh họa tinh gọn.","D":"• Hợp đồng hoàn toàn không văn bản gây mập mờ tính pháp lý."}}},{"id":24,"task":"su24_fe","taskLabel":"SU24 FE","num":24,"chooseType":"Choose 1 answer","question":"Your organization has developed an AI system that recommends treatments for hospital patients. What applied ethics domain do these concerns fall under?","options":{"A":"Bioethics (or Medical Ethics)","B":"Engineering ethics","C":"Business ethics","D":"Environmental ethics"},"answer":"A","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Tổ chức của bạn đã phát triển một hệ thống AI gợi ý phác đồ điều trị cho bệnh nhân nhập viện. Các lo ngại đạo đức liên quan thuộc về lĩnh vực đạo đức ứng dụng nào?","optionsVi":{"A":"Đạo đức sinh học / Đạo đức y khoa (Bioethics)","B":"Đạo đức kỹ thuật (Engineering ethics)","C":"Đạo đức kinh doanh (Business ethics)","D":"Đạo đức môi trường (Environmental ethics)"},"answerDisplay":"A. Bioethics","concept":"• Bioethics (Đạo đức sinh học/y khoa) điều chỉnh các vấn đề đạo đức phát sinh trong chăm sóc sức khỏe, y tế và ứng dụng công nghệ sinh học trên con người.","whyCorrect":"• Ứng dụng điều trị y tế cho bệnh nhân thuộc phạm vi trực tiếp của Bioethics.","whyWrong":{"B":"• Engineering ethics điều chỉnh quy chuẩn xây dựng và thiết kế phần cứng.","C":"• Business ethics điều chỉnh quan hệ thương mại và thị trường.","D":"• Environmental ethics điều chỉnh tác động môi trường tự nhiên."}}},{"id":25,"task":"su24_fe","taskLabel":"SU24 FE","num":25,"chooseType":"Choose 1 answer","question":"Which of the following is a type of technology contract that establishes the goals of both parties and describes how those goals will be achieved?","options":{"A":"Software as a Service (SaaS)","B":"Terms of Service (TOS)","C":"End-user license agreement (EULA)","D":"Service-level agreement (SLA)"},"answer":"D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Loại hợp đồng công nghệ nào xác định mục tiêu của cả hai bên và mô tả chi tiết các chỉ số đạt được các mục tiêu đó?","optionsVi":{"A":"Phần mềm dạng dịch vụ (SaaS)","B":"Điều khoản dịch vụ (TOS)","C":"Thỏa thuận giấy phép người dùng cuối (EULA)","D":"Thỏa thuận mức dịch vụ (Service-Level Agreement - SLA)"},"answerDisplay":"D. Service-level agreement (SLA)","concept":"• SLA (Service Level Agreement) cam kết rõ ràng chỉ số chất lượng dịch vụ (Uptime, thời gian phản hồi) và trách nhiệm giữa nhà cung cấp và khách hàng.","whyCorrect":"• SLA quy định cụ thể các mục tiêu chất lượng dịch vụ và cơ chế đảm bảo thực hiện.","whyWrong":{"A":"• SaaS là mô hình phân phối phần mềm đám mây.","B":"• TOS quy định quy tắc sử dụng chung.","C":"• EULA là bản quyền cấp phép phần mềm."}}},{"id":26,"task":"su24_fe","taskLabel":"SU24 FE","num":26,"chooseType":"Choose 1 answer","question":"Which of the following is a negative consequence of a predictive model used in real life?","options":{"A":"A model wrongly predicts a person will not pay credit card","B":"A model indicates a person is in danger","C":"A model used by a bank wrongly predicts a person will not be able to pay off a loan (False negative rejection)","D":"A model accurately predicts loan payoff"},"answer":"C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Hậu quả tiêu cực nào sau đây của một mô hình dự đoán được sử dụng trong đời sống thực tế?","optionsVi":{"A":"Mô hình phòng lab dự đoán sai khả năng trả thẻ tín dụng","B":"Mô hình cảnh báo một người gặp nguy hiểm","C":"Mô hình ngân hàng dự đoán sai rằng một người không thể trả nợ khoản vay, dẫn tới việc từ chối vay bất công (wrongly predicts inability to pay off loan)","D":"Mô hình dự đoán chính xác khả năng trả nợ"},"answerDisplay":"C. A model used by a bank wrongly predicts a person will not be able to pay off a loan","concept":"• Lỗi Âm tính giả trong chấm điểm tín dụng khiến khách hàng uy tín bị từ chối cấp vốn, gây ra thiệt hại tài chính và cơ hội thực tế cho người dân.","whyCorrect":"• Dự đoán sai khiến người vay đủ năng lực bị từ chối vay ngân hàng bất công là hậu quả tiêu cực đời thực.","whyWrong":{"A":"• Mô hình phòng lab không trực tiếp gây tác động đời sống ngân hàng.","B":"• Cảnh báo nguy hiểm mang lại lợi ích an toàn.","D":"• Dự đoán chính xác mang lại hiệu quả tín dụng tốt."}}},{"id":27,"task":"su24_fe","taskLabel":"SU24 FE","num":27,"chooseType":"Choose 1 answer","question":"Which of the following describes an opt-out policy in regards to the collection of private data?","options":{"A":"Data isn't collected until the user explicitly allows it","B":"Data is always collected regardless of consent","C":"Data about the user is automatically collected unless that user explicitly states that you should not do so","D":"Data is never collected"},"answer":"C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả chính sách Opt-out liên quan đến việc thu thập dữ liệu riêng tư?","optionsVi":{"A":"Dữ liệu chỉ được thu thập khi người dùng đồng ý trước (Opt-in)","B":"Dữ liệu luôn được thu thập bất kể sự đồng ý","C":"Dữ liệu người dùng tự động được thu thập ngoại trừ khi người dùng chủ động yêu cầu từ chối/dừng thu thập (automatically collected unless explicitly opted out)","D":"Dữ liệu không bao giờ được thu thập"},"answerDisplay":"C. Data about the user is automatically collected unless that user explicitly states that you should not do so.","concept":"• Opt-out Policy ngầm định thu thập dữ liệu cho đến khi người dùng chủ động thực hiện thao tác từ chối (Decline/Unsubscribe).","whyCorrect":"• Tự động thu thập trừ khi người dùng chủ động từ chối là bản chất của cơ chế Opt-out.","whyWrong":{"A":"• Đây là bản chất của chính sách Opt-in.","B":"• Thu thập không quan tâm sự đồng ý là vi phạm riêng tư.","D":"• Không bao giờ thu thập là chính sách cấm hoàn toàn."}}},{"id":28,"task":"su24_fe","taskLabel":"SU24 FE","num":28,"chooseType":"Choose 1 answer","question":"Pseudocode can best be defined as:","options":{"A":"An explainable description of code that is meant for humans, not computers","B":"A Python library for machine learning","C":"A middle ground between code and plain writing that can be fed into a computer","D":"A type of Javascript"},"answer":"A","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Mã giả (Pseudocode) được định nghĩa đúng nhất là gì?","optionsVi":{"A":"Mô tả thuật toán có thể giải thích được dành cho con người đọc hiểu, không dùng để máy tính thực thi trực tiếp (meant for humans, not computers)","B":"Một thư viện Python cho học máy","C":"Ngôn ngữ máy tính","D":"Một loại Javascript"},"answerDisplay":"A. an explainable description of code that is meant for humans, not computers","concept":"• Pseudocode (Mã giả) mô tả logic thuật toán bằng ngôn ngữ tự nhiên kết hợp cấu trúc lập trình để con người dễ hiểu và thảo luận.","whyCorrect":"• Mã giả dành cho con người thấu hiểu logic mà không bị phụ thuộc vào cú pháp máy tính cụ thể.","whyWrong":{"B":"• Mã giả không phải thư viện mã nguồn.","C":"• Máy tính không thể biên dịch trực tiếp mã giả.","D":"• Mã giả không phải ngôn ngữ lập trình Javascript."}}},{"id":29,"task":"su24_fe","taskLabel":"SU24 FE","num":29,"chooseType":"Choose 1 answer","question":"Which of the following describes dual-use or multipurpose data?","options":{"A":"Data used in multiple devices like TV and phone","B":"Data collected for one application that could also be applied to another application in a different domain","C":"Data transformed into multiple audio/video formats","D":"Data shared with family members"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả Dữ liệu sử dụng kép hoặc đa mục đích (Dual-use / Multipurpose data)?","optionsVi":{"A":"Dữ liệu dùng trên nhiều thiết bị TV/Điện thoại","B":"Dữ liệu được thu thập cho một ứng dụng ban đầu nhưng cũng có thể được áp dụng cho ứng dụng khác ở lĩnh vực khác (collected for one app, applied to another domain)","C":"Dữ liệu chuyển đổi định dạng âm thanh/video","D":"Dữ liệu chia sẻ với người thân"},"answerDisplay":"B. Data collected for one application that could also be applied to another application in a different domain.","concept":"• Dual-use / Multipurpose Data là dữ liệu được thu thập cho mục đích dân sự/lành tính nhưng có thể bị tái sử dụng cho mục đích theo dõi hoặc quân sự nhạy cảm.","whyCorrect":"• Tái sử dụng dữ liệu sang miền ứng dụng khác ngoài mục đích ban đầu là bản chất của Dual-use data.","whyWrong":{"A":"• Sử dụng trên nhiều thiết bị là Cross-device compatibility.","C":"• Chuyển đổi định dạng là Media encoding.","D":"• Chia sẻ gia đình là Personal data sharing."}}},{"id":30,"task":"su24_fe","taskLabel":"SU24 FE","num":30,"chooseType":"Choose 1 answer","question":"In artificial intelligence risk management, 'Unknown Unknowns' refers to:","options":{"A":"Being unsure about the morals of the research team","B":"Lack of explainability and what a model is actually looking at to make its prediction","C":"Facing unknown empirical data with an incomplete dataset","D":"An uncertainty of how the data is gathered"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Trong quản lý rủi ro AI, thuật ngữ 'Điều không biết về những điều không biết' (Unknown Unknowns) đề cập đến điều gì?","optionsVi":{"A":"Không chắc chắn về đạo đức của đội ngũ","B":"Sự thiếu tính giải thích được và việc không thể biết mô hình thực sự dựa vào yếu tố nào để đưa ra dự đoán (Lack of explainability and what a model is actually looking at)","C":"Dữ liệu thực nghiệm chưa biết","D":"Không chắc chắn về quy trình thu thập dữ liệu"},"answerDisplay":"B. lack of explainability and what a model is actually looking at to make it's prediction","concept":"• Unknown Unknowns trong AI Hộp đen là các rủi ro mà chúng ta thậm chí không biết là chúng tồn tại do không thể giải thích cơ chế ra quyết định của mô hình.","whyCorrect":"• Việc không thể biết mô hình đang dựa vào quy luật nào bên trong là rủi ro Unknown Unknowns nguy hại nhất.","whyWrong":{"A":"• Đạo đức nhóm nghiên cứu là rủi ro quản trị con người.","C":"• Thiếu dữ liệu thực nghiệm là Known Unknowns.","D":"• Không chắc quy trình thu thập là rủi ro Data Provenance."}}},{"id":31,"task":"su24_fe","taskLabel":"SU24 FE","num":31,"chooseType":"Choose 1 answer","question":"An unfair model will by nature:","options":{"A":"Optimize for making the fewest decisions","B":"Try to balance groups automatically","C":"Optimize for overall accuracy while concentrating errors on a specific subgroup","D":"Optimize for making the fewest mistakes"},"answer":"C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Một mô hình không công bằng (Unfair model) về mặt bản chất sẽ thực hiện thao tác tối ưu hóa nào?","optionsVi":{"A":"Tối ưu hóa để ra ít quyết định nhất","B":"Tự động cân bằng các nhóm","C":"Tối ưu hóa độ chính xác chung trong khi dồn sai số/lỗi sai lên một nhóm yếu thế cụ thể (concentrating errors on a specific subgroup)","D":"Tối ưu hóa để mắc ít lỗi nhất"},"answerDisplay":"C. optimize for overall accuracy while concentrating errors on a specific subgroup","concept":"• Bản chất của Unfair Model: Đạt chỉ số Accuracy tổng thể cao bằng cách hy sinh nhóm yếu thế (dồn tỷ lệ lỗi False Positive / False Negative lên nhóm đó).","whyCorrect":"• Mô hình thiên vị giữ độ chính xác tổng thể bằng cách dồn sai sót thiệt hại lên phân nhóm thiểu số.","whyWrong":{"A":"• Số lượng quyết định không phản ánh tính công bằng.","B":"• Mô hình thiên vị không tự động cân bằng nhóm.","D":"• Mắc ít lỗi nhất không đảm bảo lỗi được phân bố đều."}}},{"id":32,"task":"su24_fe","taskLabel":"SU24 FE","num":32,"chooseType":"Choose 1 answer","question":"If we know one group's worthiness score has been artificially inflated, one solution for fairness is to:","options":{"A":"Create separate decision thresholds for each group to equalize opportunity","B":"Remove that group from dataset","C":"Balance error rate by prioritizing other group","D":"Add inflation to other data"},"answer":"A","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Nếu biết điểm số giá trị của một nhóm đã bị thổi vồng nhân tạo trong lịch sử, một giải pháp để đảm bảo tính công bằng là gì?","optionsVi":{"A":"Tạo các ngưỡng quyết định riêng biệt cho từng nhóm để cân bằng cơ hội (create separate decision thresholds for each group)","B":"Xóa nhóm đó khỏi tập dữ liệu","C":"Cân bằng tỷ lệ lỗi","D":"Thổi vồng dữ liệu của nhóm còn lại"},"answerDisplay":"A. creating separate decision thresholds for each group","concept":"• Group-specific Decision Thresholds: Điều chỉnh ngưỡng quyết định riêng cho từng nhóm để bù đắp sự lệch điểm lịch sử và đạt được Equal Opportunity.","whyCorrect":"• Hạ hoặc nâng ngưỡng quyết định linh hoạt cho từng nhóm giúp triệt tiêu sự thổi vồng điểm số lịch sử bất công.","whyWrong":{"B":"• Xóa nhóm khỏi tập dữ liệu là tước bỏ quyền truy cập của họ.","C":"• Cân bằng tỷ lệ lỗi chung không sửa được sự thiên vị điểm số gốc.","D":"• Thổi vồng dữ liệu tạo thêm nhiễu sai lệch."}}},{"id":33,"task":"su24_fe","taskLabel":"SU24 FE","num":33,"chooseType":"Choose 1 answer","question":"Which type of entity are the OECD Principles on Artificial Intelligence mostly geared towards?","options":{"A":"Individuals","B":"Municipal governments","C":"National governments","D":"Private corporations"},"answer":"C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Các nguyên tắc AI của OECD chủ yếu hướng tới đối tượng nào?","optionsVi":{"A":"Cá nhân người dùng","B":"Chính quyền thành phố / địa phương","C":"Chính phủ các quốc gia (National governments)","D":"Các tập đoàn tư nhân"},"answerDisplay":"C. National governments","concept":"• Khung khuyến nghị OECD AI Principles được thiết kế chủ yếu làm kim chỉ nam chính sách cho Chính phủ các nước thành viên xây dựng luật pháp.","whyCorrect":"• OECD là tổ chức hợp tác kinh tế liên chính phủ, các khuyến nghị hướng tới cấp độ hoạch định chính sách quốc gia.","whyWrong":{"A":"• Cá nhân là đối tượng được bảo vệ.","B":"• Chính quyền địa phương thực thi chính sách từ quốc gia.","D":"• Các tập đoàn áp dụng tuân thủ luật do chính phủ ban hành."}}},{"id":34,"task":"su24_fe","taskLabel":"SU24 FE","num":34,"chooseType":"Choose 1 answer","question":"Dating algorithms become biased mostly through offering users:","options":{"A":"Collaborative filtering that reinforces existing attraction stereotypes","B":"Access to separate data models","C":"Different ways to match with users","D":"Unlimited matches per day"},"answer":"A","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Các thuật toán hẹn hò trở nên bị thiên vị chủ yếu thông qua việc cung cấp cho người dùng tính năng gì?","optionsVi":{"A":"Lọc cộng tác (Collaborative filtering) củng cố các định kiến hấp dẫn sẵn có","B":"Truy cập các mô hình dữ liệu riêng","C":"Các cách ghép đôi khác nhau","D":"Không giới hạn lượt ghép đôi"},"answerDisplay":"A. collaborative filtering","concept":"• Lọc cộng tác (Collaborative Filtering) trong app hẹn hò gợi ý người dùng dựa trên hành vi của người dùng tương tự, vô tình tạo ra vòng lặp củng cố định kiến chủng tộc/ngoại hình.","whyCorrect":"• Lọc cộng tác nhân rộng và củng cố các định kiến xã hội vốn có trong dữ liệu quẹt thẻ.","whyWrong":{"B":"• Truy cập mô hình riêng là kiến trúc hệ thống.","C":"• Cách thức match là giao diện người dùng.","D":"• Lượt match không gây ra định kiến thiên vị nhóm."}}},{"id":35,"task":"su24_fe","taskLabel":"SU24 FE","num":35,"chooseType":"Choose 1 answer","question":"Your business handles the personal data of California residents. Which of the following regulations would enable a resident to request that their data be deleted from your company's files?","options":{"A":"PCI DSS","B":"OECD Privacy Guidelines","C":"COPPA","D":"CCPA"},"answer":"D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Doanh nghiệp của bạn xử lý dữ liệu cá nhân của cư dân California. Quy định nào sau đây cho phép cư dân yêu cầu xóa dữ liệu của họ khỏi tệp của công ty?","optionsVi":{"A":"PCI DSS","B":"Hướng dẫn quyền riêng tư OECD","C":"COPPA","D":"CCPA (Đạo luật quyền riêng tư người tiêu dùng California)"},"answerDisplay":"D. CCPA","concept":"• CCPA (California Consumer Privacy Act) trao cho cư dân California quyền yêu cầu doanh nghiệp xóa dữ liệu cá nhân (Right to Delete).","whyCorrect":"• CCPA là đạo luật riêng tư của bang California quy định rõ quyền xóa dữ liệu cá nhân của người tiêu dùng.","whyWrong":{"A":"• PCI DSS là tiêu chuẩn an toàn dữ liệu thẻ thanh toán ngân hàng.","B":"• OECD Privacy Guidelines là khuyến nghị quốc tế, không phải luật bắt buộc thi hành tại California.","C":"• COPPA là luật bảo vệ quyền riêng tư trẻ em trên mạng của Mỹ."}}},{"id":36,"task":"su24_fe","taskLabel":"SU24 FE","num":36,"chooseType":"Choose 1 answer","question":"How does the 'virtuous cycle' that benefits Big Tech operate?","options":{"A":"Organizations write algorithms with fewer biases, which leads to fairer outcomes.","B":"By acting virtuous, the public respects Big Tech more and more.","C":"Better classes of customers lead to richer and more refined data for algorithmic systems.","D":"Data-driven algorithms improve solutions, leading to new customers, and better data."},"answer":"D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Chu trình tăng trưởng độc quyền ('Virtuous Cycle') mang lại lợi ích cho các tập đoàn Big Tech vận hành như thế nào?","optionsVi":{"A":"Tổ chức viết thuật toán ít thiên vị dẫn tới kết quả công bằng hơn","B":"Hành động đạo đức giúp công chúng tôn trọng Big Tech hơn","C":"Khách hàng tốt mang lại dữ liệu phong phú hơn","D":"Thuật toán dựa trên dữ liệu cải thiện giải pháp -> Thu hút khách hàng mới -> Thu thập thêm dữ liệu tốt hơn (Data -> Product -> Users -> More Data)"},"answerDisplay":"D. Data-driven algorithms improve solutions, leading to new customers, and better data.","concept":"• Vòng lặp phản hồi dữ liệu (Data Flywheel Effect): Càng nhiều dữ liệu -> Thuật toán càng thông minh -> Sản phẩm càng tốt -> Thu hút thêm người dùng -> Lại có thêm dữ liệu độc quyền.","whyCorrect":"• Chu trình tự củng cố giữa dữ liệu, chất lượng sản phẩm và lượng người dùng tạo nên lợi thế độc quyền cho Big Tech.","whyWrong":{"A":"• Viết thuật toán ít thiên vị là mục tiêu đạo đức.","B":"• Công chúng tôn trọng là hiệu ứng thương hiệu.","C":"• Khách hàng giàu không phải nguyên nhân cốt lõi của chu trình."}}},{"id":37,"task":"su24_fe","taskLabel":"SU24 FE","num":37,"chooseType":"Choose 1 answer","question":"A model that makes more mistakes by moving its decision threshold down 40% of its worthiness metric will be potentially:","options":{"A":"More accurate and fairer","B":"Less accurate and less fair","C":"Fairer but less accurate","D":"Less fair but more accurate"},"answer":"C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Một mô hình mắc nhiều lỗi hơn bằng cách hạ ngưỡng quyết định (decision threshold) xuống 40% chỉ số giá trị sẽ có khả năng trở thành:","optionsVi":{"A":"Chính xác hơn và công bằng hơn","B":"Kém chính xác hơn và kém công bằng hơn","C":"Công bằng hơn nhưng kém chính xác hơn (Fairer but less accurate)","D":"Kém công bằng hơn nhưng chính xác hơn"},"answerDisplay":"C. Fairer but less accurate","concept":"• Sự đánh đổi trong ML (Trade-off between Accuracy and Fairness): Hạ ngưỡng quyết định có thể làm giảm sai lệch bất công giữa các nhóm (tăng Fairness) nhưng làm tăng tỷ lệ báo động giả (giảm Accuracy).","whyCorrect":"• Hạ ngưỡng mở rộng cơ hội cho nhóm bị phân biệt đối xử (tăng tính công bằng) nhưng chấp nhận nhiều sai sót dự đoán hơn (giảm độ chính xác).","whyWrong":{"A":"• Hạ ngưỡng làm tăng lỗi nên không thể vừa tăng chính xác vừa tăng công bằng.","B":"• Hạ ngưỡng mở rộng cơ hội tiếp cận cho nhóm yếu thế nên giúp tăng Fairness.","D":"• Ngược lại với bản chất của trade-off hạ ngưỡng."}}},{"id":38,"task":"su24_fe","taskLabel":"SU24 FE","num":38,"chooseType":"Choose 1 answer","question":"Which type of fairness fails to address merit while maintaining accuracy?","options":{"A":"Error rate parity","B":"Statistical parity (Demographic parity)","C":"Equality of false positives","D":"Equality of prediction rate"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Loại tiêu chuẩn công bằng nào thất bại trong việc đánh giá năng lực/xứng đáng cá nhân (merit) trong khi cố duy trì tỷ lệ ngang bằng giữa các nhóm?","optionsVi":{"A":"Cân bằng tỷ lệ lỗi (Error rate parity)","B":"Cân bằng thống kê / nhân khẩu học (Statistical parity)","C":"Bình đẳng dương tính giả","D":"Bình đẳng tỷ lệ dự đoán"},"answerDisplay":"B. statistical parity","concept":"• Statistical Parity (Demographic Parity) ép buộc tỷ lệ lựa chọn bằng nhau giữa các nhóm mà không xét đến độ xứng đáng (merit) thực tế của từng cá nhân trong nhóm.","whyCorrect":"• Cân bằng chỉ số nhóm cố định có thể bỏ qua sự chênh lệch năng lực cá nhân thực tế giữa các nhóm.","whyWrong":{"A":"• Error rate parity xét tỷ lệ lỗi sai dự đoán.","C":"• False positive parity xét tỷ lệ báo động giả.","D":"• Prediction rate parity là chỉ số đầu ra."}}},{"id":39,"task":"su24_fe","taskLabel":"SU24 FE","num":39,"chooseType":"Choose 1 answer","question":"Which of the following is an important reason for continually refreshing an organization's internal and external ethics policies?","options":{"A":"It helps internal stakeholders justify the release of new product features.","B":"It helps maintain alignment with emergent risks and changing ethical posture of products and services.","C":"It helps maintain alignment with cultural values of employees.","D":"It helps demonstrate to senior management that work is being done."},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Lý do quan trọng cho việc liên tục cập nhật làm mới các chính sách đạo đức nội bộ và bên ngoài của tổ chức là gì?","optionsVi":{"A":"Biện minh cho việc phát hành tính năng mới","B":"Giúp duy trì sự đồng bộ với các rủi ro mới nổi và vị thế đạo đức thay đổi của các sản phẩm/dịch vụ (maintain alignment with emergent risks)","C":"Duy trì sự đồng bộ với giá trị văn hóa","D":"Báo cáo tiến độ làm việc cho lãnh đạo"},"answerDisplay":"B. It helps maintain alignment with the emergent risks and changing ethical posture of the products and services of the organization.","concept":"• Công nghệ và rủi ro mới (Emergent Risks) xuất hiện liên tục, đòi hỏi chính sách đạo đức phải được cập nhật thường xuyên để tương thích.","whyCorrect":"• Đảm bảo chính sách luôn bắt kịp với các rủi ro công nghệ mới xuất hiện là lý do quan trọng nhất.","whyWrong":{"A":"• Biện minh tính năng không phải mục tiêu đạo đức.","C":"• Đồng bộ văn hóa là một phần nhỏ.","D":"• Báo cáo hình thức không mang giá trị quản trị rủi ro."}}},{"id":40,"task":"su24_fe","taskLabel":"SU24 FE","num":40,"chooseType":"Choose 1 answer","question":"Which of the following constitute internal stakeholders in the context of a code of ethics?","options":{"A":"Regulators","B":"Designers and Developers","C":"Data subjects","D":"Policymakers"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Nhóm đối tượng nào sau đây cấu thành các bên liên quan nội bộ (Internal Stakeholders) trong bối cảnh bộ quy tắc đạo đức?","optionsVi":{"A":"Cơ quan quản lý nhà nước (Regulators)","B":"Các nhà thiết kế và lập trình viên (Designers and Developers)","C":"Chủ thể dữ liệu (Data subjects)","D":"Các nhà hoạch định chính sách"},"answerDisplay":"B. Designers","concept":"• Internal Stakeholders bao gồm nhân viên, nhà thiết kế, lập trình viên, ban quản lý làm việc trực tiếp bên trong tổ chức.","whyCorrect":"• Lập trình viên và nhà thiết kế là nhân sự nội bộ trực tiếp tham gia xây dựng sản phẩm.","whyWrong":{"A":"• Regulators là bên liên quan bên ngoài.","C":"• Data subjects là bên ngoài bị tác động.","D":"• Policymakers là cơ quan chính phủ bên ngoài."}}},{"id":41,"task":"su24_fe","taskLabel":"SU24 FE","num":41,"chooseType":"Choose 1 answer","question":"How could a board of ethics be an example of ethics washing?","options":{"A":"If it has a wide variety of stakeholders","B":"If it has a narrow list of values to guide decisions","C":"If it has no power to institute change or enforce compliance","D":"If it has a large number of stakeholders"},"answer":"C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Làm thế nào một Hội đồng Đạo đức có thể trở thành một ví dụ về 'Ethics Washing' (Tẩy trắng đạo đức)?","optionsVi":{"A":"Nếu hội đồng có nhiều bên liên quan","B":"Nếu hội đồng có danh sách giá trị hẹp","C":"Nếu hội đồng không có thực quyền để thực thi thay đổi hoặc cưỡng chế tuân thủ (has no power to institute change)","D":"Nếu hội đồng có đông thành viên"},"answerDisplay":"C. If it has no power to institute change.","concept":"• Ethics Washing là việc lập ra các hội đồng hình thức để quảng bá hình ảnh nhưng tước bỏ quyền hạn thực thi quyết định của hội đồng đó.","whyCorrect":"• Thành lập hội đồng bề nổi nhưng không cho thực quyền thay đổi là hình thức Ethics Washing điển hình.","whyWrong":{"A":"• Đa dạng bên liên quan là tính chất tích cực.","B":"• Danh sách giá trị hẹp là vấn đề phạm vi.","D":"• Đông thành viên không quyết định việc tẩy trắng."}}},{"id":42,"task":"su24_fe","taskLabel":"SU24 FE","num":42,"chooseType":"Choose 1 answer","question":"Which of the following is a benefit of using focus groups over surveys?","options":{"A":"They can provide structured data","B":"They are more scalable for large populations","C":"They are easier to collect from target audience","D":"They allow for deeper engagement and qualitative insights with the target demographic community"},"answer":"D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Lợi ích của việc sử dụng nhóm thảo luận tập trung (Focus groups) so với khảo sát đại chúng (Surveys) là gì?","optionsVi":{"A":"Cung cấp dữ liệu cấu trúc tốt hơn","B":"Mở rộng quy mô dễ hơn","C":"Dễ thu thập thông tin hơn","D":"Cho phép tương tác sâu sắc hơn và thu thập góc nhìn định tính từ cộng đồng dân cư mục tiêu (deeper engagement with target demographic)"},"answerDisplay":"D. They allow for deeper engagement with the target demographic community.","concept":"• Focus Groups tạo môi trường đối thoại mở định tính, giúp tìm hiểu sâu sắc động cơ và góc nhìn tâm lý của người tham gia.","whyCorrect":"• Thảo luận trực tiếp cho phép tương tác chiều sâu và làm rõ các chi tiết định tính mà khảo sát tích chọn bỏ sót.","whyWrong":{"A":"• Survey mới là công cụ cung cấp dữ liệu cấu trúc định lượng.","B":"• Survey mở rộng quy mô (scalable) tốt hơn focus group.","C":"• Survey dễ gửi hơn focus group."}}},{"id":43,"task":"su24_fe","taskLabel":"SU24 FE","num":43,"chooseType":"Choose 1 answer","question":"What is the purpose of what-if scenario planning sessions?","options":{"A":"To think critically about the tradeoffs between company values and business needs so you can decide how to proceed","B":"To think critically about mistakes so you can identify what should do after a violation","C":"To think critically about potential worst-case scenarios so you can decide whether or not to proceed with a project","D":"To think critically about best-case scenarios"},"answer":"C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Mục đích của các buổi diễn tập lập kế hoạch kịch bản giả định 'What-if' là gì?","optionsVi":{"A":"Suy nghĩ về sự đánh đổi giá trị","B":"Suy nghĩ về các sai lầm sau khi sự cố xảy ra","C":"Tư duy phản biện về các kịch bản tồi tệ nhất có thể xảy ra (worst-case scenarios) để quyết định có nên tiếp tục dự án hay không","D":"Suy nghĩ về kịch bản tốt nhất"},"answerDisplay":"C. The purpose of what-if scenario planning sessions is to think critically about potential worst-case scenarios so you can decide whether or not to proceed with a project","concept":"• Diễn tập kịch bản 'What-if' đóng vai trò quản lý rủi ro dự phòng, giúp nhận diện các thảm họa tồi tệ nhất (Worst-case) để phòng ngừa hoặc dừng dự án kịp thời.","whyCorrect":"• Đánh giá kịch bản xấu nhất giúp tổ chức quyết định tính khả thi và an toàn đạo đức của dự án trước khi triển khai.","whyWrong":{"A":"• Đánh đổi giá trị là phân tích đạo đức chung.","B":"• Xử lý sự cố là Post-mortem report.","D":"• Kịch bản tốt nhất (Best-case) không phản ánh tư duy quản lý rủi ro."}}},{"id":44,"task":"su24_fe","taskLabel":"SU24 FE","num":44,"chooseType":"Choose 1 answer","question":"How is employee voice different than open door policy?","options":{"A":"Open door policy follows up with people to show how changes were implemented","B":"Employee voice follows up with people to show how changes were implemented based on their communication","C":"They are identical in implementation","D":"Open door policy is strictly formal"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Tiếng nói của nhân viên (Employee voice) khác biệt với Chính sách mở cửa (Open door policy) như thế nào?","optionsVi":{"A":"Chính sách mở cửa theo dõi và minh chứng sự thay đổi","B":"Employee voice chủ động phản hồi và chứng minh các thay đổi thực tế đã được thực thi dựa trên ý kiến đóng góp của nhân viên (follows up to show how changes were implemented)","C":"Cả hai giống hệt nhau","D":"Chính sách mở cửa là hình thức cứng nhắc"},"answerDisplay":"B. Employee voice follows up with the people to show how changes were implemented based on their communication.","concept":"• Employee Voice thực chất bao gồm hai chiều: Lắng nghe đóng góp và Thực thi hành động phản hồi (Follow-up & Implementation) để nhân viên thấy ý kiến của họ có giá trị.","whyCorrect":"• Phản hồi kết quả hành động thực tế là điểm khác biệt cốt lõi của Employee Voice so với sự mở cửa lắng nghe thụ động.","whyWrong":{"A":"• Open door policy chỉ dừng ở mở cửa lắng nghe thụ động.","C":"• Hai khái niệm có sự khác biệt lớn về tính hiệu quả hành động.","D":"• Mở cửa mang tính hình thức lỏng lẻo."}}},{"id":45,"task":"su24_fe","taskLabel":"SU24 FE","num":45,"chooseType":"Choose 1 answer","question":"Which approach to corporate governance is more likely to create an ethical organizational culture?","options":{"A":"A systemic approach with incentive systems align with values","B":"An oversight committee focus solely on rules","C":"A board focused only on legal compliance","D":"An oversight committee focus on static frameworks"},"answer":"A","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Cách tiếp cận quản trị doanh nghiệp nào có khả năng cao hơn trong việc tạo ra một văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Cách tiếp cận hệ thống kết hợp với hệ thống khuyến khích / đãi ngộ gắn liền với giá trị đạo đức (systemic approach with incentive systems)","B":"Ủy ban chỉ tập trung vào quy tắc cứng","C":"Hội đồng chỉ tập trung vào tuân thủ pháp lý","D":"Ủy ban tập trung vào khung lý thuyết tĩnh"},"answerDisplay":"A. A systemic approach with incentive systems.","concept":"• Quản trị hệ thống (Systemic Governance) thưởng/phạt và khuyến khích nhân viên theo chuẩn mực giá trị giúp củng cố văn hóa đạo đức tự giác.","whyCorrect":"• Gắn cơ chế đãi ngộ khuyến khích với các giá trị đạo đức giúp thúc đẩy hành vi tích cực toàn tổ chức.","whyWrong":{"B":"• Chỉ tập trung quy tắc tạo ra tâm lý đối phó cứng nhắc.","C":"• Tuân thủ pháp lý chỉ là điều kiện sàn tối thiểu.","D":"• Khung lý thuyết tĩnh thiếu tính thực tiễn hành động."}}},{"id":46,"task":"su24_fe","taskLabel":"SU24 FE","num":46,"chooseType":"Choose 1 answer","question":"Which of the following constitute external stakeholders in the context of a code of ethics?","options":{"A":"Business managers","B":"Regulators and Customers","C":"Developers","D":"Designers"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Những đối tượng nào sau đây cấu thành các bên liên quan bên ngoài (External Stakeholders) trong bối cảnh bộ quy tắc đạo đức?","optionsVi":{"A":"Các nhà quản lý kinh doanh","B":"Cơ quan quản lý nhà nước và Khách hàng (Regulators and Customers)","C":"Các nhà phát triển phần mềm","D":"Các nhà thiết kế"},"answerDisplay":"B. Regulators and Customers","concept":"• External Stakeholders bao gồm các cá nhân/tổ chức nằm ngoài doanh nghiệp như Khách hàng, Cơ quan quản lý (Regulators), Cộng đồng và Đối tác.","whyCorrect":"• Cơ quan quản lý và Khách hàng là hai nhóm bên ngoài chịu ảnh hưởng và điều chỉnh chính sách của doanh nghiệp.","whyWrong":{"A":"• Quản lý kinh doanh là Internal Stakeholders.","C":"• Lập trình viên là Internal Stakeholders.","D":"• Nhà thiết kế là Internal Stakeholders."}}},{"id":47,"task":"su24_fe","taskLabel":"SU24 FE","num":47,"chooseType":"Choose 1 answer","question":"Which organizational resource is most commonly used in terms of fostering an ethical organizational culture?","options":{"A":"Human resources","B":"Informational resources","C":"Financial resources","D":"Physical resources"},"answer":"A","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Nguồn lực tổ chức nào được sử dụng phổ biến nhất để thúc đẩy văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Nguồn nhân lực (Human resources)","B":"Nguồn lực thông tin","C":"Nguồn lực tài chính","D":"Nguồn lực cơ sở vật chất"},"answerDisplay":"A. Human resources","concept":"• Văn hóa đạo đức được xây dựng bởi con người qua đào tạo, nêu gương lãnh đạo và tuyển dụng (Human Resources).","whyCorrect":"• Nguồn nhân lực là yếu tố cốt lõi trực tiếp thực hành và lan tỏa các giá trị đạo đức trong công ty.","whyWrong":{"B":"• Thông tin là công cụ hỗ trợ.","C":"• Tài chính tài trợ các chương trình nhưng con người mới là đối tượng thực thi.","D":"• Cơ sở vật chất là hạ tầng làm việc."}}},{"id":48,"task":"su24_fe","taskLabel":"SU24 FE","num":48,"chooseType":"Choose 1 answer","question":"Which of the following are important steps to document during an auditing process? (Select two.)","options":{"A":"Specify and document what precisely is being audited","B":"Document the audit procedures to be followed","C":"Provide significant advance notice before an audit","D":"Specify a purpose for the audit or an agenda to be covered"},"answer":"A, B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Những bước nào sau đây là quan trọng cần lập hồ sơ tài liệu trong quá trình kiểm toán? (Select two)","optionsVi":{"A":"Xác định và ghi chép rõ ràng chính xác đối tượng được kiểm toán (Specify and document what precisely is being audited)","B":"Ghi chép quy trình kiểm toán cần tuân thủ (Document the audit procedures to be followed)","C":"Gửi thông báo trước quá lâu","D":"Tạo chương trình họp chung"},"answerDisplay":"A. Specify and document what precisely is being audited & B. Document the audit procedures to be followed","concept":"• Hồ sơ kiểm toán đòi hỏi tính chính xác về phạm vi kiểm toán (Audit Scope) và quy trình thực hiện (Audit Procedures).","whyCorrect":"• Xác định rõ đối tượng và quy trình giúp đảm bảo tính minh bạch và khả năng tái lập kiểm toán.","whyWrong":{"C":"• Thông báo trước là thủ tục hành chính.","D":"• Lên lịch họp là quản lý thời gian."}}},{"id":49,"task":"su24_fe","taskLabel":"SU24 FE","num":49,"chooseType":"Choose 1 answer","question":"Which of the following are fundamental risk management tasks? (Select two.)","options":{"A":"Mitigation","B":"Authentication","C":"Compliance","D":"Identification"},"answer":"A, D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Những nhiệm vụ nào sau đây là các nhiệm vụ quản lý rủi ro cơ bản? (Select two)","optionsVi":{"A":"Giảm thiểu rủi ro (Mitigation)","B":"Xác thực người dùng","C":"Tuân thủ pháp lý","D":"Nhận diện rủi ro (Identification)"},"answerDisplay":"A. Mitigation & D. Identification","concept":"• Chu trình quản lý rủi ro bao gồm các bước cốt lõi: Nhận diện (Identification), Đánh giá (Assessment), Giảm thiểu (Mitigation) và Giám sát (Monitoring).","whyCorrect":"• Nhận diện rủi ro là bước đầu tiên và Giảm thiểu rủi ro là bước xử lý cốt lõi.","whyWrong":{"B":"• Xác thực (Authentication) là tính năng an ninh mạng.","C":"• Tuân thủ (Compliance) là mục tiêu quản trị."}}},{"id":50,"task":"su24_fe","taskLabel":"SU24 FE","num":50,"chooseType":"Choose 1 answer","question":"Which of the following are objectives of a forensic analysis? (Select two.)","options":{"A":"To inform stakeholders that an incident has occurred","B":"To determine what occurred in an incident","C":"To identify who or what is responsible for an incident","D":"To mitigate the effects of an incident"},"answer":"B, C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Những mục tiêu nào sau đây thuộc về Phân tích điều tra số (Forensic analysis)? (Select two)","optionsVi":{"A":"Thông báo cho các bên liên quan","B":"Xác định những gì đã xảy ra trong sự cố (To determine what occurred in an incident)","C":"Xác định ai hoặc yếu tố nào chịu trách nhiệm cho sự cố (To identify who or what is responsible)","D":"Giảm thiểu tác hại sự cố"},"answerDisplay":"B. To determine what occurred in an incident & C. To identify who or what is responsible for an incident","concept":"• Forensic Analysis (Điều tra pháp y kỹ thuật số) tập trung vào khôi phục bằng chứng để trả lời 2 câu hỏi: Chuyện gì đã xảy ra (What) và Ai chịu trách nhiệm (Who/Cause).","whyCorrect":"• Khôi phục diễn biến sự cố và tìm ra nguyên nhân/thủ phạm là mục đích chính của Forensic analysis.","whyWrong":{"A":"• Thông báo sự cố là công việc của Incident Response PR.","D":"• Giảm thiểu tác hại là công việc của Containment & Remediation team."}}},{"id":51,"task":"su24_fe","taskLabel":"SU24 FE","num":51,"chooseType":"Choose 1 answer","question":"Which of the following are best practices for incorporating inclusive design in AI projects? (Select two.)","options":{"A":"Solve for one, extend to many","B":"Consider bias a spectrum","C":"Keep machines and humans separate","D":"Leverage customer input to reduce bias"},"answer":"B, D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Những thực hành tốt nhất nào sau đây giúp tích hợp Thiết kế bao hàm (Inclusive Design) vào các dự án AI? (Select two)","optionsVi":{"A":"Giải quyết cho một người, mở rộng cho nhiều người","B":"Coi thiên vị như một dải phổ liên tục (Consider bias a spectrum)","C":"Tách biệt máy tính và con người","D":"Tận dụng phản hồi đóng góp của khách hàng để giảm thiên vị (Leverage customer input to reduce bias)"},"answerDisplay":"B. Consider bias a spectrum. & D. Leverage customer input to reduce bias.","concept":"• Inclusive Design xem xét đa dạng các góc nhìn nhu cầu và coi thiên vị là một dải phổ cần liên tục lắng nghe phản hồi từ cộng đồng người dùng.","whyCorrect":"• Nhận thức thiên vị dưới dạng dải phổ và thu thập phản hồi người dùng đa dạng giúp tối ưu hóa tính bao hàm.","whyWrong":{"A":"• Khẩu hiệu chuẩn của Inclusive Design là 'Solve for one, extend to many' (câu A bị ghi ngược 'Solve for many, extend to one' trong đề gốc).","C":"• Tách biệt máy và người làm giảm khả năng tương tác Human-in-the-loop."}}},{"id":52,"task":"su24_fe","taskLabel":"SU24 FE","num":52,"chooseType":"Choose 1 answer","question":"Which of the following are useful strategies for communicating ethical risks to the organization? (Select two.)","options":{"A":"Communicate information through a single voice","B":"Disseminate information in multiple formats","C":"Communicate information in real time","D":"Provide information only when solicited"},"answer":"B, C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Những chiến lược nào sau đây là hữu ích để truyền thông các rủi ro đạo đức tới toàn tổ chức? (Select two)","optionsVi":{"A":"Truyền đạt thông tin qua một giọng nói duy nhất","B":"Phổ biến thông tin dưới nhiều định dạng đa dạng (Disseminate information in multiple formats)","C":"Truyền đạt thông tin theo thời gian thực (Communicate information in real time)","D":"Chỉ cung cấp thông tin khi được yêu cầu"},"answerDisplay":"B. Disseminate information in multiple formats & C. Communicate information in real time","concept":"• Truyền thông rủi ro hiệu quả cần sử dụng đa dạng định dạng (văn bản, video, tập huấn) và cập nhật kịp thời gian thực.","whyCorrect":"• Đa dạng định dạng giúp tăng khả năng tiếp thu và truyền thông thời gian thực giúp ngăn ngừa sự cố kịp thời.","whyWrong":{"A":"• Giọng nói duy nhất tạo ra sự đơn điệu và thiếu phủ sóng.","D":"• Chỉ cung cấp khi hỏi là thái độ thụ động nguy hiểm trong quản lý rủi ro."}}},{"id":53,"task":"su24_fe","taskLabel":"SU24 FE","num":53,"chooseType":"Choose 1 answer","question":"Which of the following are important to provide to a crisis communication team? (Select two.)","options":{"A":"Clear direction on the roles and responsibilities of team members","B":"Permission to tell public what they want to hear","C":"Ability to work independently","D":"Access to adequate resources and verified information"},"answer":"A, D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Những yếu tố nào sau đây là quan trọng cần cung cấp cho đội ngũ truyền thông khủng hoảng? (Select two)","optionsVi":{"A":"Hướng dẫn rõ ràng về vai trò và trách nhiệm của từng thành viên (Clear direction on roles and responsibilities)","B":"Cho phép nói những gì công chúng muốn nghe","C":"Khả năng làm việc độc lập","D":"Quyền truy cập vào nguồn lực đầy đủ và thông tin xác thực (Access to adequate resources)"},"answerDisplay":"A. Clear direction on the roles and responsibilities of team members & D. Access to adequate resources","concept":"• Đội truyền thông khủng hoảng cần sự rõ ràng về phân công nhiệm vụ (Roles & Responsibilities) và được cung cấp đầy đủ hạ tầng/thông tin (Resources).","whyCorrect":"• Phân công vai trò chuẩn xác và cấp đủ tài nguyên giúp đội phản ứng nhanh chóng và nhất quán.","whyWrong":{"B":"• Nói những gì công chúng thích nghe mà thiếu sự thật là dối trá truyền thông.","C":"• Đội truyền thông phải phối hợp chặt chẽ với ban chỉ đạo khủng hoảng chứ không làm việc cô lập."}}},{"id":54,"task":"su24_fe","taskLabel":"SU24 FE","num":54,"chooseType":"Choose 1 answer","question":"Which of the following are effective strategies when making statements on social media? (Select two.)","options":{"A":"Being honest and up front","B":"Communicating only as needed","C":"Presenting a human face of the organization","D":"Focusing on positive feedback only"},"answer":"A, C","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Những chiến lược nào sau đây là hiệu quả khi đưa ra các phát biểu trên mạng xã hội? (Select two)","optionsVi":{"A":"Trung thực và thẳng thắn ngay từ đầu (Being honest and up front)","B":"Chỉ truyền thông khi thật cần thiết","C":"Thể hiện diện mạo nhân văn/gần gũi của tổ chức (Presenting a face of the organization)","D":"Chỉ tập trung vào phản hồi tích cực"},"answerDisplay":"A. Being honest and up front & C. Presenting a face of the organization","concept":"• Truyền thông mạng xã hội thành công yêu cầu tính Trung thực (Authenticity) và sự Cầu thị nhân văn (Human Face) thay vì ngôn từ doanh nghiệp cứng nhắc.","whyCorrect":"• Bày tỏ thái độ trung thực và giao tiếp với diện mạo nhân văn xây dựng niềm tin với cộng đồng mạng.","whyWrong":{"B":"• Chỉ truyền thông khi cần khiến tổ chức bị coi là thiếu minh bạch.","D":"• Lờ đi phản hồi tiêu cực gây ra làn sóng tẩy chay dư luận."}}},{"id":55,"task":"su24_fe","taskLabel":"SU24 FE","num":55,"chooseType":"Choose 1 answer","question":"Which of the following are important ethical elements to safeguard within ethical AI systems? (Select two.)","options":{"A":"Accountability and management of bias","B":"The number of layers, tensors, or parameters used","C":"Performance and optimization speed","D":"Transparency and explainability, balanced with privacy"},"answer":"A, D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Những yếu tố đạo đức quan trọng nào sau đây cần được bảo vệ trong các hệ thống AI có đạo đức? (Select two)","optionsVi":{"A":"Trách nhiệm giải trình và quản lý thiên vị (Accountability and management of bias)","B":"Số lượng lớp nơ-ron và tham số","C":"Hiệu suất và tốc độ tối ưu hóa","D":"Tính minh bạch và tính giải thích được, cân bằng với quyền riêng tư (Transparency and explainability, balanced with privacy)"},"answerDisplay":"A. Accountability and management of bias. & D. Transparency and explainability, balanced with privacy.","concept":"• Các trụ cột của AI có trách nhiệm (Trustworthy AI): 1. Accountability & Bias control, 2. Transparency & Explainability & Privacy protection.","whyCorrect":"• Hai nhóm trụ cột này là cốt lõi của mọi khung làm việc đạo đức AI chuẩn mực.","whyWrong":{"B":"• Số lớp nơ-ron là thông số kỹ thuật.","C":"• Hiệu suất và tốc độ là chỉ số tối ưu hóa phần mềm."}}},{"id":56,"task":"su24_fe","taskLabel":"SU24 FE","num":56,"chooseType":"Choose 1 answer","question":"Which of the following are important elements of the data minimization principle? (Select two.)","options":{"A":"Only collect data that is strictly necessary","B":"Only keep data for as long as it is needed","C":"Only delete data that can be easily replaced","D":"Only compress data that needs to be kept small"},"answer":"A, B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Những yếu tố nào sau đây là thành phần quan trọng của nguyên tắc giảm thiểu dữ liệu (Data Minimization)? (Select two)","optionsVi":{"A":"Chỉ thu thập dữ liệu thực sự cần thiết (Only collect data that is strictly necessary)","B":"Chỉ giữ dữ liệu trong khoảng thời gian còn cần đến (Only keep data for as long as it is needed)","C":"Chỉ xóa dữ liệu có thể thay thế","D":"Chỉ nén dữ liệu cần lưu trữ nhỏ"},"answerDisplay":"A. Only collect data that is strictly necessary & B. Only keep data for as long as it is needed","concept":"• Data Minimization bao gồm hai khía cạnh: Giới hạn phạm vi thu thập (Need-to-know) và Giới hạn thời gian lưu trữ (Data Retention).","whyCorrect":"• Chỉ thu thập dữ liệu thiết yếu và xóa dữ liệu khi hết thời hạn sử dụng giúp phòng ngừa tối đa rủi ro lộ rò.","whyWrong":{"C":"• Xóa dữ liệu phụ thuộc vào quy định lưu trữ chứ không phải tính dễ thay thế.","D":"• Nén dữ liệu là giải pháp tối ưu lưu trữ phần mềm."}}},{"id":57,"task":"su24_fe","taskLabel":"SU24 FE","num":57,"chooseType":"Choose 1 answer","question":"Which of the following are likely to be found within a penetration test rules of engagement (ROE)? (Select two.)","options":{"A":"What systems may be targeted","B":"How long CCTV camera recordings should be maintained","C":"The appropriate length and complexity of employee passwords","D":"What methods of attack are legitimate"},"answer":"A, D","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Những thành tố nào sau đây thường được quy định trong Quy tắc tham chiến (Rules of Engagement - ROE) của bài kiểm thử xâm nhập? (Select two)","optionsVi":{"A":"Hệ thống nào được phép tấn công mục tiêu (What systems may be targeted)","B":"Thời gian lưu trữ camera CCTV","C":"Độ dài mật khẩu nhân viên","D":"Những phương thức tấn công nào là hợp lệ (What methods of attack are legitimate)"},"answerDisplay":"A. What systems may be targeted & D. What methods of attack are legitimate","concept":"• ROE trong Penetration Testing giới hạn rõ ràng Phạm vi mục tiêu (Scope) và Kỹ thuật tấn công được phép/bị cấm sử dụng.","whyCorrect":"• Xác định phạm vi mục tiêu được phép và phương thức tấn công hợp lệ bảo vệ an toàn cho hệ thống vận hành thực tế.","whyWrong":{"B":"• Thời gian lưu camera thuộc về chính sách an ninh vật lý.","C":"• Độ dài mật khẩu thuộc về chính sách đặt mật khẩu công ty."}}},{"id":58,"task":"su24_fe","taskLabel":"SU24 FE","num":58,"chooseType":"Choose 1 answer","question":"When building a predictive model, what is the goal of the development/training phase?","options":{"A":"To plug in 40% of dataset for testing","B":"To get the model's error function below an acceptable percentage threshold","C":"To specify algorithm and clean data","D":"To accept new inputs and train until finding better curve"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Khi xây dựng một mô hình dự đoán, mục tiêu của giai đoạn phát triển / huấn luyện (Development/Training phase) là gì?","optionsVi":{"A":"Nạp 40% dữ liệu để thử nghiệm","B":"Đưa hàm sai số (Error function / Loss) của mô hình xuống dưới mức ngưỡng chấp nhận được (get error function below acceptable percentage)","C":"Xác định thuật toán và làm sạch dữ liệu","D":"Nạp dữ liệu mới và huấn luyện liên tục"},"answerDisplay":"B. To get the model's error function below an acceptable percentage","concept":"• Giai đoạn Huấn luyện (Training): Tối ưu hóa các trọng số toán học để giảm tối đa giá trị của hàm mất mát (Loss/Error Function).","whyCorrect":"• Giảm thiểu hàm sai số tổn thất xuống mức tối ưu chấp nhận được là mục tiêu cốt lõi của giai đoạn huấn luyện.","whyWrong":{"A":"• Thử nghiệm thuộc về Testing set.","C":"• Chọn thuật toán thuộc về giai đoạn thiết kế ban đầu.","D":"• Huấn luyện lặp lại liên tục không có điểm dừng là Overfitting."}}},{"id":59,"task":"su24_fe","taskLabel":"SU24 FE","num":59,"chooseType":"Choose 1 answer","question":"Which of the following ethical domains does the IEEE 7000 series explore? (Select two.)","options":{"A":"Emulated empathy","B":"Machine-readable privacy terms","C":"Fair competition","D":"Personnel safety"},"answer":"A, B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Lĩnh vực đạo đức nào sau đây được chuỗi tiêu chuẩn IEEE 7000 nghiên cứu? (Select two)","optionsVi":{"A":"Thấu cảm giả lập (Emulated empathy)","B":"Điều khoản quyền riêng tư máy có thể đọc được (Machine-readable privacy terms)","C":"Cạnh tranh công bằng","D":"An toàn nhân sự"},"answerDisplay":"A. Emulated empathy & B. Machine-readable privacy terms","concept":"• Chuỗi tiêu chuẩn IEEE 7000 tập trung vào thiết kế đạo đức cho hệ thống tự động, bao gồm thấu cảm mô phỏng và điều khoản máy đọc.","whyCorrect":"• Hai khía cạnh này nằm trong phạm vi kỹ thuật hóa đạo đức của chuẩn IEEE 7000.","whyWrong":{"C":"• Cạnh tranh công bằng thuộc về luật chống độc quyền thương mại.","D":"• An toàn nhân sự thuộc về an toàn lao động OSHA."}}},{"id":60,"task":"su24_fe","taskLabel":"SU24 FE","num":60,"chooseType":"Choose 1 answer","question":"What makes ethics training effective in an organization?","options":{"A":"Keep sessions short and focused","B":"Keep sessions interactive and engaging","C":"Keep the content simple, direct and actionable","D":"All of the above (Short, interactive, simple and actionable)"},"answer":"B","source":"ITE302c_SU24_FE","explanation":{"questionVi":"Điều gì giúp cho các chương trình tập huấn đạo đức trong tổ chức đạt hiệu quả cao?","optionsVi":{"A":"Giữ các buổi ngắn gọn và tập trung","B":"Tạo tính tương tác cao và cuốn hút người tham gia (Keep sessions interactive)","C":"Nội dung đơn giản trực tiếp","D":"Tất cả các yếu tố trên"},"answerDisplay":"B. Keep sessions interactive.","concept":"• Đào tạo đạo đức hiệu quả đòi hỏi phương pháp Tương tác (Interactive Case Studies) giúp nhân viên tự nhập vai giải quyết tình huống thay vì nghe giảng thụ động.","whyCorrect":"• Tính tương tác giúp nhân viên chủ động rèn luyện tư duy phản biện đạo đức trong thực tế.","whyWrong":{"A":"• Thời lượng ngắn không quyết định được chất lượng tiếp thu nếu thiếu tương tác.","C":"• Nội dung đơn giản chỉ là điều kiện cần.","D":"• Đáp án B thể hiện phương pháp giảng dạy tích cực hàng đầu."}}},{"id":1,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":1,"chooseType":"Choose 1 answer","question":"k-Anonymity in a dataset is achieved when each individual cannot be:","options":{"A":"Distinguished from at least k-1 other individuals who are also in the dataset based on quasi-identifiers","B":"Reidentified in k datasets","C":"Hidden from quasi-identifier column as long as k individuals belong","D":"Harmed from datasets with k individuals"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Tính ẩn danh k-anonymity trong một tập dữ liệu đạt được khi mỗi cá nhân không thể bị:","optionsVi":{"A":"Phân biệt với ít nhất k-1 cá nhân khác trong cùng tập dữ liệu dựa trên các thuộc tính bán định danh (Distinguished from at least K individuals)","B":"Tái định danh trong k tập dữ liệu","C":"Che giấu khỏi cột bán định danh","D":"Tổn hại từ các tập dữ liệu chứa k cá nhân"},"answerDisplay":"A. distinguished from at least K individuals who are also in the dataset","concept":"• k-Anonymity Requirement: Mỗi nhóm thuộc tính bán định danh (Quasi-identifiers) phải xuất hiện ít nhất k lần trong tập dữ liệu.","whyCorrect":"• Ẩn mình trong nhóm ít nhất k cá nhân có cùng thuộc tính bán định danh là định nghĩa của k-anonymity.","whyWrong":{"B":"• k không đại diện cho số lượng tập dữ liệu.","C":"• Thuộc tính bán định danh bị làm mờ tổng quát hóa.","D":"• Tổn hại không nằm trong định nghĩa k-anonymity."}}},{"id":2,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":2,"chooseType":"Choose 1 answer","question":"What is the primary purpose of obtaining feedback about an ethical crisis?","options":{"A":"To demonstrate compliance","B":"To make operational improvements and prevent future incidents","C":"To appease concerned stakeholders","D":"To motivate internal personnel"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Mục đích chính của việc thu thập phản hồi về một cuộc khủng hoảng đạo đức là gì?","optionsVi":{"A":"Chứng minh tuân thủ hình thức","B":"Thực hiện các cải tiến vận hành nhằm ngăn chặn sự cố tái diễn trong tương lai (To make operational improvements)","C":"Xoa dịu các bên liên quan","D":"Động viên nhân viên nội bộ"},"answerDisplay":"B. To make operational improvements","concept":"• Feedback Loop sau sự cố: Rút ra bài học kinh nghiệm (Lessons Learned) để cải tiến vận hành thực chất.","whyCorrect":"• Cải tiến quy trình vận hành phòng ngừa lặp lại rủi ro là giá trị thực chất nhất.","whyWrong":{"A":"• Tuân thủ hình thức không khắc phục nguyên nhân gốc.","C":"• Xoa dịu suông là giải pháp ngắn hạn.","D":"• Động viên nhân viên thuộc về công tác nhân sự."}}},{"id":3,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":3,"chooseType":"Choose 1 answer","question":"Which of the following would be an appropriate scenario to issue a press release?","options":{"A":"The organization's AI product has a critical flaw/incident or major values alignment update","B":"The organization's service receives a routine minor update","C":"The organization's change management strategy has been modified","D":"The organization plans internal team restructuring"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Kịch bản nào sau đây là phù hợp nhất để doanh nghiệp phát hành một thông cáo báo chí (Press Release)?","optionsVi":{"A":"Sản phẩm AI của tổ chức gặp sự cố/lỗi nghiêm trọng hoặc công bố cập nhật lớn về tiêu chuẩn đạo đức (product defect/recall or major policy announcement)","B":"Dịch vụ nhận cập nhật nhỏ định kỳ","C":"Chiến lược quản lý thay đổi nội bộ sửa đổi","D":"Tái cấu trúc nhóm nội bộ"},"answerDisplay":"A. The organization's Al product has a defect and needs to be recalled","concept":"• Tính chất Tin tức của Thông cáo Báo chí (Press Release Newsworthiness): Chỉ phát hành khi có sự kiện quan trọng tác động lớn tới công chúng/khách hàng.","whyCorrect":"• Sự cố sản phẩm nghiêm trọng ảnh hưởng cộng đồng là sự kiện báo chí bắt buộc thông cáo.","whyWrong":{"B":"• Cập nhật nhỏ định kỳ dùng tin tức blog/newsletter.","C":"• Quản lý thay đổi là quy trình nội bộ.","D":"• Tái cấu trúc nhóm là tin tức nhân sự nội bộ."}}},{"id":4,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":4,"chooseType":"Choose 1 answer","question":"Which of the following describes why explainability is important in AI decision systems?","options":{"A":"It is necessary so internal stakeholders can understand system works","B":"It provides interpretations of system actions","C":"It provides accountability, transparency, and trust for users and regulators","D":"It enables you to explain for shareholder purposes"},"answer":"C","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả lý do tại sao tính giải thích được (Explainability) lại quan trọng trong các hệ thống ra quyết định AI?","optionsVi":{"A":"Cần thiết cho bên nội bộ thấu hiểu","B":"Cung cấp diễn giải hành động","C":"Nó tạo ra trách nhiệm giải trình, tính minh bạch và lòng tin cho người dùng và cơ quan quản lý (provides accountability and trust)","D":"Giải thích vì mục đích cổ đông"},"answerDisplay":"C. It provides accountability and trust.","concept":"• Giá trị của XAI: Khả năng giải thích củng cố Trách nhiệm giải trình (Accountability) và Lòng tin (Trust) từ xã hội.","whyCorrect":"• Xây dựng lòng tin và cơ chế giải trình là vai trò cốt lõi của tính giải thích được.","whyWrong":{"A":"• Giải thích hướng tới cả các thực thể bên ngoài.","B":"• Diễn giải hành động chỉ là phương tiện kỹ thuật.","D":"• Cổ đông chỉ là một bên liên quan tài chính."}}},{"id":5,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":5,"chooseType":"Choose 1 answer","question":"Which of the following Information Security pillars confirms the claimed identity of a user or system?","options":{"A":"Authorization","B":"Authentication","C":"Kindness","D":"Reputation"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Trụ cột an toàn thông tin nào sau đây giúp xác minh tính đúng đắn của danh tính được khai báo của người dùng hoặc hệ thống?","optionsVi":{"A":"Ủy quyền (Authorization)","B":"Xác thực danh tính (Authentication)","C":"Lòng tốt","D":"Uy tín"},"answerDisplay":"B. Authentication","concept":"• Authentication vs Authorization: Authentication (Xác thực - Bạn là ai?), Authorization (Phân quyền - Bạn được làm gì?).","whyCorrect":"• Authentication là quy trình kiểm tra xác minh danh tính khai báo của thực thể.","whyWrong":{"A":"• Authorization là quy trình cấp quyền truy cập sau khi đã xác thực.","C":"• Kindness không phải thuật ngữ an ninh thông tin.","D":"• Reputation là chỉ số uy tín hệ thống."}}},{"id":6,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":6,"chooseType":"Choose 1 answer","question":"What is the primary benefit of hosting a virtual conference for ethics communication?","options":{"A":"Easier to communicate overall message","B":"Accessible to all willing participants globally","C":"The conference can be interactive without participants needing to be co-located","D":"Participants will be impressed by technology"},"answer":"C","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Lợi ích chính của việc tổ chức một hội thảo trực tuyến (Virtual conference) để truyền thông đạo đức là gì?","optionsVi":{"A":"Dễ truyền đạt thông điệp chung","B":"Tiếp cận dễ dàng","C":"Hội thảo có thể mang tính tương tác cao mà không yêu cầu các đại biểu phải tập trung cùng một địa điểm vật lý (interactive without being co-located)","D":"Gây ấn tượng bằng công nghệ"},"answerDisplay":"C. The conference can be interactive without the participants needing to be co-located.","concept":"• Lợi thế của Virtual Conference: Duy trì khả năng tương tác đa chiều (Interactive) mà xóa bỏ rào cản địa lý (Co-location).","whyCorrect":"• Tạo tương tác phản hồi linh hoạt mà không tốn chi phí di chuyển địa lý.","whyWrong":{"A":"• Truyền đạt thông điệp chung có thể qua video thu sẵn.","B":"• Tiếp cận dễ dàng là đặc tính chung của web.","D":"• Gây ấn tượng công nghệ là giá trị bề nổi."}}},{"id":7,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":7,"chooseType":"Choose 1 answer","question":"Which of the following topics would be most appropriate to cover in a physical security policy?","options":{"A":"What systems may be targeted","B":"How long CCTV camera recordings and physical access logs should be maintained","C":"Length and complexity of passwords","D":"Legitimate attack methods"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Chủ đề nào sau đây là phù hợp nhất để quy định trong một Chính sách an ninh vật lý (Physical security policy)?","optionsVi":{"A":"Hệ thống nào bị nhắm mục tiêu","B":"Thời gian lưu trữ bản ghi camera giám sát CCTV và nhật ký truy cập vật lý (How long CCTV recordings maintained)","C":"Độ dài và độ phức tạp mật khẩu","D":"Phương thức tấn công hợp lệ"},"answerDisplay":"B. How long CCTV camera recordings should be maintained","concept":"• Physical Security Policy: Quản lý thiết bị giám sát camera CCTV, thẻ từ ra vào, khóa cửa phòng máy chủ và bảo vệ hạ tầng phần cứng.","whyCorrect":"• Bản ghi camera CCTV là thành tố kiểm soát an ninh vật lý tiêu chuẩn.","whyWrong":{"A":"• Mục tiêu tấn công thuộc Threat Modeling.","C":"• Mật khẩu thuộc về Password / Digital Security Policy.","D":"• Phương thức tấn công thuộc Penetration Testing."}}},{"id":8,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":8,"chooseType":"Choose 1 answer","question":"What shared principle from ethical frameworks in intellectual property often at odds with AI transparency?","options":{"A":"Privacy","B":"Safety","C":"Security","D":"Transparency / Explainability (Trade secret protection)"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Bảo hộ sở hữu trí tuệ (Bí mật thương mại) thường mâu thuẫn trực tiếp với nguyên tắc đạo đức nào?","optionsVi":{"A":"Quyền riêng tư","B":"An toàn","C":"An ninh","D":"Tính minh bạch và tính giải thích được (Transparency / Explainability)"},"answerDisplay":"D. Transparency/explainability","concept":"• Conflict of IP & Transparency: Bảo mật thuật toán độc quyền (IP/Trade Secrets) ngăn cản việc công khai mã nguồn giải thích AI.","whyCorrect":"• Bảo hộ bí mật thương mại xung đột trực diện với yêu cầu công khai minh bạch mô hình.","whyWrong":{"A":"• Quyền riêng tư là bảo vệ dữ liệu cá nhân.","B":"• An toàn là mục tiêu bảo vệ.","C":"• An ninh là bảo vệ hệ thống."}}},{"id":9,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":9,"chooseType":"Choose 1 answer","question":"Which of the following is a benefit of incorporating stakeholder feedback during ethics policy reviews?","options":{"A":"Replaces need for policy refresh","B":"Dissuades users from scrutinizing policies","C":"Provides rich qualitative information used to continuously refine and improve policies","D":"Provides transparency around efforts"},"answer":"C","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Lợi ích của việc kết hợp phản hồi từ các bên liên quan trong quá trình xem xét chính sách đạo đức là gì?","optionsVi":{"A":"Thay thế nhu cầu cập nhật","B":"Ngăn người dùng soi xét chính sách","C":"Cung cấp thông tin định tính phong phú giúp liên tục tinh chỉnh và hoàn thiện các chính sách (qualitative information to improve policies)","D":"Cung cấp tính minh bạch bề nổi"},"answerDisplay":"C. It can help provide qualitative information that can be used to improve the policies","concept":"• Policy Iteration & Qualitative Feedback: Phản hồi từ các bên liên quan mang lại dữ liệu thực tế để cập nhật chính sách khả thi hơn.","whyCorrect":"• Phản hồi định tính giúp nhận diện lỗ hổng thực tế để hoàn thiện chính sách.","whyWrong":{"A":"• Phản hồi thúc đẩy cập nhật chứ không thay thế cập nhật.","B":"• Khuyến khích người dùng hiểu rõ chính sách.","D":"• Minh bạch nỗ lực chỉ là lợi ích phụ."}}},{"id":10,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":10,"chooseType":"Choose 1 answer","question":"Which ethical theory primarily judges the morality of an action based on its consequences and total utility produced?","options":{"A":"Virtue ethics","B":"Categorical imperative","C":"Deontology","D":"Utilitarianism"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Lý thuyết đạo đức nào chủ yếu đánh giá tính đạo đức của một hành động dựa trên kết quả/hậu quả và tổng giá trị hữu dụng (utility) mang lại?","optionsVi":{"A":"Thuyết đạo đức đức hạnh","B":"Mệnh lệnh tuyệt đối","C":"Thuyết nghĩa vụ luận","D":"Thuyết vị lợi (Utilitarianism)"},"answerDisplay":"D. Utilitarianism","concept":"• Utilitarianism (Thuyết vị lợi của Jeremy Bentham & John Stuart Mill): Quyết định đạo đức là quyết định mang lại 'Lợi ích lớn nhất cho số đông lớn nhất' (Greatest good for greatest number).","whyCorrect":"• Đánh giá đạo đức dựa trên hậu quả và tổng giá trị hữu ích là cốt lõi của Thuyết vị lợi.","whyWrong":{"A":"• Virtue ethics tập trung phẩm chất cá nhân.","B":"• Categorical imperative là nguyên tắc nghĩa vụ của Kant.","C":"• Deontology đánh giá dựa trên sự tuân thủ quy tắc nghĩa vụ."}}},{"id":11,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":11,"chooseType":"Choose 1 answer","question":"Which of the following are advantages to adopting standards frameworks like ISO 27000? (Select two.)","options":{"A":"Technology-specific focus and precise implementation instructions","B":"Formal certification processes that provide competitive advantage","C":"Regulatory weight and legal enforcement","D":"International support, recognition, and involvement"},"answer":"B, D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Những lợi thế nào sau đây thu được khi áp dụng các khung tiêu chuẩn như ISO 27000? (Select two)","optionsVi":{"A":"Tập trung công nghệ cụ thể","B":"Quy trình chứng nhận chính thức mang lại lợi thế cạnh tranh thương mại (Formal certification processes providing competitive advantage)","C":"Sức mạnh pháp lý cưỡng chế","D":"Sự hỗ trợ, công nhận và thừa nhận trên quy mô quốc tế (International support, recognition)","E":"Tất cả đáp án"},"answerDisplay":"B. Formal certification processes that provide competitive advantage & D. International support, recognition, and involvement","concept":"• Lợi ích ISO 27000: Có giá trị Chứng nhận Quốc tế và chứng minh năng lực an toàn thông tin tạo lợi thế cạnh tranh.","whyCorrect":"• Chứng nhận ISO mang lại uy tín cạnh tranh thương mại và được công nhận quốc tế.","whyWrong":{"A":"• ISO mang tính quản trị chung chứ không hướng dẫn dòng mã cụ thể.","C":"• ISO là tiêu chuẩn tự nguyện."}}},{"id":12,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":12,"chooseType":"Choose 1 answer","question":"Why are simple anonymization techniques like removing names often inadequate for protecting privacy?","options":{"A":"They are too expensive","B":"They destroy data usefulness completely","C":"They don't integrate into workflows","D":"They can be broken by combining this anonymized data with other publicly available datasets (Linkage attack)"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Tại sao các kỹ thuật ẩn danh hóa đơn giản như xóa tên thường không đủ để bảo vệ quyền riêng tư?","optionsVi":{"A":"Quá tốn kém","B":"Phá hủy hoàn toàn giá trị dữ liệu","C":"Không tích hợp được quy trình","D":"Chúng có thể bị vô hiệu hóa bằng cách kết hợp dữ liệu ẩn danh đó với các tập dữ liệu công khai khác (broken by combining with other publicly available data)"},"answerDisplay":"D. They can be broken by combining this data with other publicly available data","concept":"• Linkage Attack in Simple Anonymization: Kết hợp dữ liệu xóa tên với dữ liệu cử tri/mạng xã hội công khai để tái định danh cá nhân.","whyCorrect":"• Tái định danh qua kết hợp tập dữ liệu công khai ngoài là điểm yếu chí mạng của ẩn danh hóa đơn giản.","whyWrong":{"A":"• Xóa tên là kỹ thuật rất rẻ.","B":"• Xóa tên vẫn giữ nguyên các cột giá trị khác.","C":"• Dễ dàng tích hợp vào quy trình xử lý dữ liệu."}}},{"id":13,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":13,"chooseType":"Choose 1 answer","question":"To uphold transparency in ethics policy communications, messaging should be:","options":{"A":"Clear, concise, and coherent","B":"Complex, convincing, and contained","C":"Caring, consistent, and creative","D":"Long, complex, and iterative"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Để duy trì tính minh bạch trong truyền thông chính sách đạo đức, thông điệp cần phải đạt được các tiêu chuẩn nào?","optionsVi":{"A":"Rõ ràng, ngắn gọn súc tích và mạch lạc (Clear, concise, and coherent)","B":"Phức tạp, thuyết phục và khép kín","C":"Quan tâm, nhất quán và sáng tạo","D":"Dài dòng, phức tạp và lặp đi lặp lại"},"answerDisplay":"A. Clear, concise, and coherent.","concept":"• Tiêu chuẩn Truyền thông Minh bạch (3Cs): Clear (Rõ ràng), Concise (Súc tích), Coherent (Mạch lạc).","whyCorrect":"• Rõ ràng, súc tích và mạch lạc giúp mọi đối tượng dễ dàng tiếp thu và thấu hiểu.","whyWrong":{"B":"• Phức tạp cản trở sự thấu hiểu.","C":"• Sáng tạo không thay thế được tính rõ ràng.","D":"• Dài dòng phức tạp gây mơ hồ."}}},{"id":14,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":14,"chooseType":"Choose 1 answer","question":"Which of the following are useful strategies for communicating ethical risks to the individual? (Select two.)","options":{"A":"Ensure individuals understand specific details of risks","B":"Communicate to individuals proactively rather than reactively","C":"Inform individuals of how they are obligated to mitigate risks","D":"Ensure individuals feel that they have input into the process"},"answer":"B, D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Những chiến lược nào sau đây là hữu ích để truyền thông các rủi ro đạo đức tới từng cá nhân? (Select two)","optionsVi":{"A":"Đảm bảo cá nhân hiểu từng chi tiết","B":"Truyền thông tới cá nhân một cách chủ động thay vì bị động phản ứng (Communicate proactively rather than reactively)","C":"Yêu cầu cá nhân tự giảm thiểu rủi ro","D":"Đảm bảo cá nhân cảm thấy họ có quyền đóng góp ý kiến vào quy trình (Ensure individuals feel they have input)"},"answerDisplay":"B. Communicate to individuals proactively rather than reactively & D. Ensure individuals feel that they have input into the process","concept":"• Truyền thông Rủi ro Cá nhân: Chủ động (Proactive) và Trao quyền đóng góp (Input & Agency).","whyCorrect":"• Chủ động cảnh báo và tạo cơ hội đóng góp ý kiến nâng cao niềm tin cá nhân.","whyWrong":{"A":"• Truyền thông quá chi tiết gây quá tải nhận thức.","C":"• Đổ trách nhiệm giảm rủi ro cho người dùng là phi đạo đức."}}},{"id":15,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":15,"chooseType":"Choose 1 answer","question":"Model inputs of address with 'City + State' as separate inputs from a dataset would violate which accuracy guideline?","options":{"A":"Domain expertise","B":"No correlation guideline / Feature independence (redundant correlating features)","C":"First principles","D":"Objective summarization"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Đưa các đầu vào địa chỉ như 'Thành phố + Bang' thành các biến đầu vào riêng biệt trong cùng một tập dữ liệu sẽ vi phạm hướng dẫn độ chính xác nào?","optionsVi":{"A":"Chuyên môn miền","B":"Hướng dẫn không trùng lặp tương quan / Độc lập thuộc tính (No correlating data / Redundant correlated features)","C":"Nguyên lý đầu tiên","D":"Tóm tắt khách quan"},"answerDisplay":"B. No correlating data","concept":"• Multicollinearity / Correlated Features: Thành phố và Bang có sự tương quan phụ thuộc trực tiếp (City suy ra State), việc đưa cả hai vào làm tăng đa cộng tuyến và méo lệch mô hình.","whyCorrect":"• Đưa các thuộc tính có tương quan trực tiếp phụ thuộc lẫn nhau vào mô hình vi phạm nguyên tắc 'No correlating data'.","whyWrong":{"A":"• Chuyên môn miền hiểu rõ mối quan hệ này để loại bỏ biến trùng.","C":"• Nguyên lý đầu tiên là lập luận logic từ móng.","D":"• Tóm tắt khách quan là việc tổng hợp dữ liệu."}}},{"id":16,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":16,"chooseType":"Choose 1 answer","question":"One effective way to avoid feedback loops in machine learning is to:","options":{"A":"Destroy previous training data","B":"Scrub datasets after each decision","C":"Investigate exclusion bias and label outputs to prevent re-training on model outputs directly","D":"Label outputs to prevent re-training bias"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Một cách hiệu quả để tránh các vòng lặp phản hồi (Feedback loops) trong học máy là gì?","optionsVi":{"A":"Hủy dữ liệu huấn luyện cũ","B":"Xóa dữ liệu sau mỗi quyết định","C":"Điều tra thiên vị loại trừ","D":"Gán nhãn các đầu ra để ngăn chặn việc đưa trực tiếp đầu ra dự đoán làm dữ liệu huấn luyện lại (label outputs to prevent re-training bias)"},"answerDisplay":"D. label outputs to prevent re-training bias","concept":"• Mitigating Feedback Loops: Đánh dấu/gán nhãn cẩn thận dữ liệu sinh ra từ thuật toán để tránh nạp mù quáng đầu ra vào tập huấn luyện lại.","whyCorrect":"• Gán nhãn phân biệt đầu ra dự đoán giúp ngăn chặn việc tự củng cố thiên vị trong các vòng tái huấn luyện.","whyWrong":{"A":"• Hủy dữ liệu cũ làm mất lịch sử huấn luyện.","B":"• Xóa dữ liệu làm cản trở việc kiểm toán.","C":"• Thiên vị loại trừ là một khía cạnh riêng."}}},{"id":17,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":17,"chooseType":"Choose 1 answer","question":"Which of the following elements should be documented regarding dataset quality before model training?","options":{"A":"Time it took to collect data","B":"Any known bias in sample data and missing values handling","C":"Large size of dataset","D":"Missing values only"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Yếu tố nào sau đây nên được ghi chép tài liệu về chất lượng tập dữ liệu trước khi huấn luyện mô hình?","optionsVi":{"A":"Thời gian thu thập dữ liệu","B":"Bất kỳ thiên vị nào được phát hiện trong dữ liệu mẫu và quy trình xử lý giá trị khuyết thiếu (Any known bias in sample data and missing values handling)","C":"Kích thước tập dữ liệu","D":"Chỉ các giá trị khuyết"},"answerDisplay":"B. Any known bias in the sample data","concept":"• Dataset Documentation & Datasheets for Datasets: Ghi nhận công khai các thiên vị mẫu (Sample bias) và phương pháp xử lý dữ liệu thiếu để phục vụ kiểm toán.","whyCorrect":"• Ghi nhận các thiên vị mẫu giúp kỹ sư chủ động áp dụng thuật toán giảm nhẹ.","whyWrong":{"A":"• Thời gian thu thập không phản ánh chất lượng dữ liệu.","C":"• Kích thước lớn không đảm bảo dữ liệu không bị lệch.","D":"• Bỏ qua việc ghi nhận thiên vị mẫu."}}},{"id":18,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":18,"chooseType":"Choose 1 answer","question":"What is the primary purpose of the Turing test in artificial intelligence?","options":{"A":"To test whether an AI system is trustworthy","B":"To test whether an AI system can exhibit intelligent behavior indistinguishable from a human","C":"To test availability","D":"To test model accuracy"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Mục đích ban đầu của Phép thử Turing (Turing test) trong trí tuệ nhân tạo là gì?","optionsVi":{"A":"Kiểm tra xem AI có đáng tin không","B":"Kiểm tra xem một hệ thống AI có thể thể hiện hành vi trí tuệ không thể phân biệt được với con người hay không (exhibit behavior indistinguishable from human)","C":"Kiểm tra tính sẵn sàng","D":"Kiểm tra độ chính xác mô hình"},"answerDisplay":"B. To test whether an AI system can exhibit human intelligence","concept":"• Turing Test (Alan Turing 1950): Đánh giá khả năng giao tiếp của máy tính đến mức người đối thoại không thể phân biệt được đó là máy hay con người.","whyCorrect":"• Đo lường khả năng giả lập hành vi trí tuệ giống hệt con người.","whyWrong":{"A":"• Thử nghiệm Turing không đo lường đạo đức hay độ tin cậy.","C":"• Tính sẵn sàng là chỉ số Uptime.","D":"• Độ chính xác là chỉ số Accuracy."}}},{"id":19,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":19,"chooseType":"Choose 1 answer","question":"Which of the following describes the purpose of having an Ethics Board for a data-driven organization?","options":{"A":"An Ethics Board can help maintain values-based intentions and increase transparency into data-driven technology use","B":"An Ethics Board helps maintain profit margins","C":"An Ethics Board decreases inherent dangers","D":"An Ethics Board increases transparency into profit"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả mục đích của việc thành lập Hội đồng Đạo đức (Ethics Board) cho một tổ chức dựa trên dữ liệu?","optionsVi":{"A":"Hội đồng Đạo đức giúp duy trì các định hướng dựa trên giá trị của tổ chức và tăng cường tính minh bạch trong việc sử dụng công nghệ dựa trên dữ liệu (maintain values-based intentions and increase transparency)","B":"Duy trì biên lợi nhuận","C":"Giảm hiểm họa tự động","D":"Tăng minh bạch lợi nhuận"},"answerDisplay":"A. An Ethics Board can help maintain an organization's values-based intentions and increase transparency into how they use data-driven technologies","concept":"• Chức năng Ethics Board: Giám sát việc tuân thủ các giá trị đạo đức và tăng cường tính minh bạch công nghệ.","whyCorrect":"• Định hướng giá trị cốt lõi và đảm bảo minh bạch ứng dụng AI.","whyWrong":{"B":"• Biên lợi nhuận do ban kinh doanh quản lý.","C":"• Giảm hiểm họa kỹ thuật do bộ phận An ninh mạng đảm nhiệm.","D":"• Minh bạch lợi nhuận thuộc về báo cáo tài chính."}}},{"id":20,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":20,"chooseType":"Choose 1 answer","question":"A training set modified to remove biased historical attributes and ensure equal representation is known as a:","options":{"A":"Classic training set","B":"Optimized / Balanced training set","C":"False positive set","D":"Predictive training set"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Tập dữ liệu huấn luyện được can thiệp sửa đổi để loại bỏ các thuộc tính thiên vị lịch sử và đảm bảo đại diện bình đẳng được gọi là gì?","optionsVi":{"A":"Tập huấn luyện cổ điển","B":"Tập huấn luyện tối ưu hóa / cân bằng (Optimized / Balanced training set)","C":"Tập dương tính giả","D":"Tập huấn luyện dự đoán"},"answerDisplay":"B. optimized training set","concept":"• Data Pre-processing for Fairness: Kỹ thuật Resampling/Re-weighting để tạo ra Tập huấn luyện cân bằng (Balanced/Optimized Training Set).","whyCorrect":"• Tập dữ liệu đã được xử lý để cân bằng đại diện và triệt tiêu thiên vị.","whyWrong":{"A":"• Tập cổ điển thường chứa nguyên vẹn thiên vị lịch sử.","C":"• Tập dương tính giả là chỉ số đo lường lỗi.","D":"• Tập dự đoán là tên gọi chung."}}},{"id":21,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":21,"chooseType":"Choose 1 answer","question":"The endorsement of which role is most vital for securing company-wide adoption of an ethics policy?","options":{"A":"Department heads","B":"C-suite executives and senior leadership","C":"Employees","D":"Customers"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Sự bảo chứng/ủng hộ của vai trò nào là quan trọng nhất để đảm bảo sự áp dụng chính sách đạo đức trên toàn bộ công ty?","optionsVi":{"A":"Trưởng các bộ phận","B":"Ban lãnh đạo cấp cao C-suite (C-suite executives)","C":"Nhân viên","D":"Khách hàng"},"answerDisplay":"B. C-suite executives","concept":"• Tone at the Top: Cam kết ủng hộ mạnh mẽ từ Ban lãnh đạo C-suite là điều kiện quyết định để văn hóa đạo đức được thực thi nghiêm túc.","whyCorrect":"• Cam kết từ cấp C-suite tạo ra nguồn lực và quyền lực cưỡng chế thực thi toàn doanh nghiệp.","whyWrong":{"A":"• Trưởng bộ phận thực thi theo chỉ đạo cấp cao.","C":"• Nhân viên là đối tượng tuân thủ.","D":"• Khách hàng là thực thể bên ngoài."}}},{"id":22,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":22,"chooseType":"Choose 1 answer","question":"Which of the following is a limitation of regional data protection laws like GDPR or CCPA when applied to global AI platforms?","options":{"A":"Its exclusive focus on a single domain rather than a breadth of domains","B":"The early date of its inauguration","C":"Its specific national/regional jurisdiction scope versus global cross-border data flows","D":"A stipulation to continue providing service even if data usage is denied"},"answer":"C","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Hạn chế của các đạo luật bảo vệ dữ liệu mang tính khu vực (như GDPR hay CCPA) khi áp dụng cho các nền tảng AI toàn cầu là gì?","optionsVi":{"A":"Tập trung hẹp một lĩnh vực","B":"Ngày ban hành sớm","C":"Phạm vi thẩm quyền theo khu vực/quốc gia cụ thể mâu thuẫn với luồng dữ liệu xuyên biên giới toàn cầu (specific national focus vs global flows)","D":"Bắt buộc cung cấp dịch vụ khi bị từ chối dữ liệu"},"answerDisplay":"C. Its nationwide scope and specific national focus","concept":"• Cross-Border Data Flow & Jurisdiction: Luật pháp mang tính địa phương trong khi dữ liệu internet và AI vận hành toàn cầu xuyên biên giới.","whyCorrect":"• Giới hạn thẩm quyền địa lý mâu thuẫn với bản chất lưu chuyển dữ liệu toàn cầu của internet.","whyWrong":{"A":"• GDPR bao phủ đa lĩnh vực.","B":"• Ngày ban hành không phải hạn chế cơ bản.","D":"• GDPR cho phép từ chối cung cấp dịch vụ nếu dữ liệu là cốt lõi."}}},{"id":23,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":23,"chooseType":"Choose 1 answer","question":"How does a smart contract differ from a traditional contract?","options":{"A":"Smart contracts serve a completely different purpose","B":"Smart contracts eliminate the need for a central trusted authority by executing via code","C":"Smart contracts are more effective","D":"Smart contracts guarantee anonymity"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Hợp đồng thông minh (Smart contract) khác biệt như thế nào so với hợp đồng truyền thống?","optionsVi":{"A":"Phục vụ mục đích khác","B":"Loại bỏ nhu cầu về một cơ quan thẩm quyền trung gian nhờ tự động thực thi bằng mã code (eliminate the need for a central authority)","C":"Hiệu quả hơn","D":"Đảm bảo ẩn danh"},"answerDisplay":"B. Smart contracts eliminate the need for a central authority","concept":"• Smart Contracts: Tự động thực thi trên Blockchain không cần trung gian.","whyCorrect":"• Loại bỏ vai trò của bên trung gian phân xử là bản chất kỹ thuật.","whyWrong":{"A":"• Cả hai đều nhằm giao kết thỏa thuận.","C":"• Hiệu quả phụ thuộc vào mã nguồn.","D":"• Tính ẩn danh không bắt buộc."}}},{"id":24,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":24,"chooseType":"Choose 1 answer","question":"What is the fundamental attribution error in cognitive psychology?","options":{"A":"Assuming cause-effect for correlated variables","B":"Believing negative risks are lower for yourself","C":"Believing your ideas are normal","D":"Attributing one's own bad behavior to situational factors, but attributing others' bad behavior to internal personality traits"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Lỗi quy kết cơ bản (Fundamental attribution error) là gì?","optionsVi":{"A":"Giả định nhân quả cho biến tương quan","B":"Tin rủi ro của mình thấp hơn","C":"Tin ý kiến mình là số đông","D":"Quy kết hành vi xấu của bản thân là do hoàn cảnh khách quan, nhưng quy kết hành vi xấu của người khác là do tính cách tiêu cực nội tại (own bad behavior to situation, others to personality)"},"answerDisplay":"D. When you say your bad behavior is caused by the situation, but when other people display the same bad behavior, it is caused by a personality trait.","concept":"• Fundamental Attribution Error: Quy kết hoàn cảnh cho mình, quy kết tính cách cho người khác.","whyCorrect":"• Định nghĩa chính xác về lỗi quy kết tâm lý.","whyWrong":{"A":"• Correlation vs Causation.","B":"• Optimism bias.","C":"• False consensus effect."}}},{"id":25,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":25,"chooseType":"Choose 1 answer","question":"What is the purpose of a holding statement in crisis communications?","options":{"A":"To order business operation halt","B":"To retain media services","C":"To pre-write communications","D":"To prevent personnel from communicating prematurely before facts are verified"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Mục đích của phát ngôn giữ chỗ (Holding Statement) trong truyền thông khủng hoảng là gì?","optionsVi":{"A":"Yêu cầu dừng vận hành","B":"Thuê dịch vụ báo chí","C":"Viết trước văn bản","D":"Ngăn chặn nhân viên phát ngôn vội vàng/sớm khi chưa xác minh đầy đủ sự thật (prevent personnel from communicating prematurely)"},"answerDisplay":"D. To prevent personnel from communicating prematurely","concept":"• Holding Statement: Kiểm soát luồng tin, câu thời gian xác minh và ngăn phát ngôn vội vã.","whyCorrect":"• Tránh nhân viên phát ngôn sai lệch khi chưa đủ thông tin.","whyWrong":{"A":"• Không phải lệnh dừng vận hành.","B":"• Không dùng để thuê hợp đồng báo chí.","C":"• Holding statement phát ra ngay khi sự cố bùng phát."}}},{"id":26,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":26,"chooseType":"Choose 1 answer","question":"Why are demographic attributes like race, gender, and religion classified as sensitive attributes?","options":{"A":"People use these groups as identities","B":"These groups can be used to re-identify someone","C":"Organizations forbidden from collecting them","D":"These groups have historically been used as the basis for systemic discrimination and bias"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Tại sao các thuộc tính nhân khẩu học như chủng tộc, giới tính và tôn giáo lại được xếp vào nhóm thuộc tính nhạy cảm (Sensitive attributes)?","optionsVi":{"A":"Mọi người dùng làm bản dạng","B":"Dùng để định danh lại","C":"Cấm thu thập hoàn toàn","D":"Các thuộc tính này trong lịch sử từng bị sử dụng làm căn cứ cho sự phân biệt đối xử và thiên vị hệ thống (used as basis for wholesale discrimination)"},"answerDisplay":"D. These groups have been used as the basis for wholesale discriminatiom","concept":"• Sensitive Attributes in AI Ethics: Thuộc tính nhạy cảm có lịch sử bị kỳ thị/bất công nên cần kiểm toán bảo vệ đặc biệt.","whyCorrect":"• Lịch sử bị sử dụng để phân biệt đối xử bất công là lý do chúng được gắn nhãn nhạy cảm.","whyWrong":{"A":"• Bản dạng cá nhân không quyết định rủi ro pháp lý.","B":"• Định danh lại do thuộc tính Quasi-identifier.","C":"• Pháp luật cho phép thu thập nếu có sự đồng ý rõ ràng."}}},{"id":27,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":27,"chooseType":"Choose 1 answer","question":"Which of the following is a primary benefit of adopting an organizational Code of Ethics?","options":{"A":"Compels employees to operate ethically","B":"Prevents regulatory scrutiny","C":"Lets external stakeholders know you are ethical","D":"It creates consistency in ethical practices across the organization, rather than patchy implementation"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Lợi ích chính của việc áp dụng một Bộ quy tắc đạo đức doanh nghiệp là gì?","optionsVi":{"A":"Bắt buộc nhân viên hoạt động đạo đức","B":"Ngăn chặn thanh tra pháp lý","C":"Cho bên ngoài biết công ty có đạo đức","D":"Nó tạo ra sự nhất quán trong các thực hành đạo đức trên toàn bộ tổ chức, thay vì việc triển khai manh mún chắp vá (creates consistency across organization)"},"answerDisplay":"D. It creates consistency in the ethical practices across the organization, rather than patchy implementation of the practices _","concept":"• Consistency in Ethics Implementation: Xóa bỏ sự áp dụng tùy tiện manh mún (patchy implementation) để tạo ra chuẩn mực thống nhất.","whyCorrect":"• Đảm bảo sự nhất quán trong áp dụng đạo đức trên toàn bộ quy mô công ty.","whyWrong":{"A":"• Quy tắc cung cấp hướng dẫn chứ không tự cưỡng chế hành vi.","B":"• Không giúp né tránh sự kiểm tra của cơ quan quản lý.","C":"• Quảng bá hình ảnh chỉ là tác động phụ."}}},{"id":28,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":28,"chooseType":"Choose 1 answer","question":"Which of the following network protocols encrypts data sent over the web?","options":{"A":"HTTPS (Hypertext Transfer Protocol Secure)","B":"FTP","C":"SMTP","D":"HTTP"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Giao thức mạng nào sau đây thực hiện mã hóa dữ liệu truyền tải trên trang web?","optionsVi":{"A":"HTTPS (Giao thức truyền tải siêu văn bản bảo mật)","B":"FTP","C":"SMTP","D":"HTTP (Không mã hóa)"},"answerDisplay":"A. HTTPS","concept":"• Web Encryption Protocol: HTTPS sử dụng SSL/TLS để mã hóa đường truyền giữ tính bảo mật cho dữ liệu web.","whyCorrect":"• HTTPS là giao thức mã hóa dữ liệu web tiêu chuẩn.","whyWrong":{"B":"• FTP truyền tệp không mã hóa.","C":"• SMTP là giao thức truyền thư email.","D":"• HTTP truyền văn bản thô (Plaintext) không mã hóa."}}},{"id":29,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":29,"chooseType":"Choose 1 answer","question":"Why are deepfakes considered an ethical threat to personal rights?","options":{"A":"Take away monetization opportunities","B":"They usurp a person's likeness, identity, and voice, which can then be weaponized against them without consent","C":"Violate data agreements","D":"Built on third party tech"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Tại sao công nghệ Deepfake lại bị coi là một đe dọa đạo đức đối với quyền cá nhân?","optionsVi":{"A":"Tước đoạt cơ hội kiếm tiền","B":"Chúng chiếm đoạt hình ảnh, danh tính và giọng nói của một người, từ đó có thể bị biến thành vũ khí chống lại họ mà không có sự đồng ý (usurp person's likeness weaponized without consent)","C":"Vi phạm thỏa thuận chia sẻ","D":"Xây dựng trên công nghệ bên thứ ba"},"answerDisplay":"B. They usurp a person's likeness and can then be weaponized against them.","concept":"• Deepfake Risks: Xâm phạm nghiêm trọng danh tính và hình ảnh cá nhân (Likeness & Voice theft) để mạo danh thao túng.","whyCorrect":"• Tước đoạt hình ảnh/giọng nói để giả mạo gây tổn hại cá nhân mà không được phép.","whyWrong":{"A":"• Cơ hội kiếm tiền không phải nguy cơ đạo đức cốt lõi.","C":"• Vi phạm thỏa thuận là vấn đề hợp đồng.","D":"• Công nghệ bên thứ ba là chi tiết hạ tầng."}}},{"id":30,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":30,"chooseType":"Choose 1 answer","question":"How can engaging with external community focus groups benefit an organization's ethics policy review?","options":{"A":"Demonstrate standpoints","B":"Reinforce employee values","C":"It can unearth new qualitative insights into how products/services might impact the target demographic community","D":"Acts as shielding mechanism"},"answer":"C","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Làm thế nào việc tham vấn các nhóm thảo luận cộng đồng bên ngoài có thể mang lại lợi ích cho quá trình xem xét chính sách đạo đức của tổ chức?","optionsVi":{"A":"Chứng minh quan điểm","B":"Củng cố giá trị nhân viên","C":"Nó có thể phát hiện các góc nhìn định tính mới về cách sản phẩm/dịch vụ tác động tới cộng đồng dân cư mục tiêu (unearth new insights for target demographic)","D":"Làm lá chắn trách nhiệm"},"answerDisplay":"C. It can unearth new insights for how the products and services might be used In the target demographic community.","concept":"• Community Focus Groups: Mang lại các góc nhìn định tính thực tế (Qualitative Insights) từ người chịu tác động trực tiếp.","whyCorrect":"• Khai quật góc nhìn định tính mới từ cộng đồng chịu tác động.","whyWrong":{"A":"• Không phải kênh quảng diễn quan điểm.","B":"• Giá trị nhân viên được củng cố nội bộ.","D":"• Dùng làm lá chắn trách nhiệm là Ethics Washing."}}},{"id":31,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":31,"chooseType":"Choose 1 answer","question":"You want to solicit detailed, qualitative user feedback on ethical concerns. Which UI element is best suited for this?","options":{"A":"Drop-down menu of categories","B":"Series of short open questions","C":"Yes/No radio buttons","D":"Provide a large, unrestricted open text box where users can enter their thoughts at length"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Bạn muốn thu thập phản hồi định tính chi tiết từ người dùng về các mối quan ngại đạo đức. Thành phần giao diện nào phù hợp nhất cho mục đích này?","optionsVi":{"A":"Menu thả xuống các danh mục","B":"Các câu hỏi mở ngắn","C":"Nút chọn Đúng/Sai","D":"Cung cấp một hộp văn bản mở tự do cỡ lớn (Unrestricted open text box) để người dùng thoải mái nhập suy nghĩ chi tiết của họ (large unrestricted textbox)"},"answerDisplay":"D. Provide a large, unrestricted textbox where users can enter their thoughts at length","concept":"• Qualitative Feedback Collection UI: Hộp văn bản tự do (Open Textbox) cho phép người dùng bộc lộ suy nghĩ góc nhìn không bị giới hạn bởi đáp án đóng.","whyCorrect":"• Ô nhập văn bản tự do cho phép người dùng bày tỏ phản hồi định tính sâu sắc.","whyWrong":{"A":"• Menu thả xuống giới hạn trong các danh mục có sẵn.","B":"• Ô câu hỏi ngắn hạn chế độ dài diễn đạt.","C":"• Nút bấm Có/Không chỉ thu thập dữ liệu định lượng nhị phân."}}},{"id":32,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":32,"chooseType":"Choose 1 answer","question":"Which of the following describes the fallacy of confusing correlation with causation?","options":{"A":"When you incorrectly assume a cause-and-effect relationship simply because two variables are correlated","B":"When you assume correlation due to confounding variable","C":"When you correlate variables that don't exist","D":"When you correlate a variable with confounding variable"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả sự ngụy biện nhầm lẫn giữa Tương quan và Nhân quả (Correlation vs Causation)?","optionsVi":{"A":"Khi bạn giả định sai lầm rằng có mối quan hệ nguyên nhân - kết quả chỉ vì hai biến số có sự tương quan thống kê với nhau (incorrectly assume cause and effect because variables correlated)","B":"Giả định tương quan do biến nhiễu","C":"Tương quan biến không tồn tại","D":"Tương quan biến với biến nhiễu"},"answerDisplay":"A. When you incorrectly assume a cause and effect relationship because variables are correlated.","concept":"• Correlation vs Causation: Hai biến biến thiên cùng chiều (Tương quan) không có nghĩa là biến này gây ra biến kia (Nhân quả).","whyCorrect":"• Ngụy biện coi tương quan thống kê đồng nghĩa với mối quan hệ nhân quả.","whyWrong":{"B":"• Biến nhiễu gây ra tương quan ảo (Spurious correlation).","C":"• Biến không tồn tại là lỗi dữ liệu.","D":"• Tương quan biến nhiễu là kỹ thuật thống kê."}}},{"id":33,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":33,"chooseType":"Choose 1 answer","question":"Which of the following is an example of selection bias in data collection?","options":{"A":"Using biased survey data","B":"Using parsed Twitter data over parsed Facebook data","C":"Using new data over existing data","D":"Relying strictly on scraped Twitter data over representative survey data for general population sentiment"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Ví dụ nào sau đây thể hiện Thiên vị lựa chọn mẫu (Selection bias) trong thu thập dữ liệu?","optionsVi":{"A":"Dùng dữ liệu khảo sát thiên vị","B":"Dùng dữ liệu Twitter hơn Facebook","C":"Dùng dữ liệu mới hơn dữ liệu cũ","D":"Chỉ dựa vào dữ liệu cào từ Twitter thay vì dữ liệu khảo sát đại diện để đánh giá dư luận của toàn bộ dân số (scraped twitter data over survey data)"},"answerDisplay":"D. using scraped twitter data over survey data","concept":"• Selection Bias: Chọn nguồn dữ liệu mẫu (như Twitter) vốn lệch về giới trẻ/đô thị làm đại diện cho toàn bộ dân số đa dạng.","whyCorrect":"• Dữ liệu Twitter không đại diện cho toàn bộ mẫu dân số chung sinh ra Selection bias.","whyWrong":{"A":"• Khảo sát thiên vị là tên gọi chung.","B":"• So sánh Twitter và Facebook là chọn lọc nguồn.","C":"• Dữ liệu mới là Temporal bias."}}},{"id":34,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":34,"chooseType":"Choose 1 answer","question":"Which of the following statements accurately describes Determinism?","options":{"A":"All future events determined by preceding events, but humans interfere","B":"All events, past, present, and future, are determined in advance by preceding causes","C":"Human beings make choices whose outcomes are not determined","D":"All events predestined by supernatural force"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Phát biểu nào mô tả chính xác Thuyết quyết định luận (Determinism)?","optionsVi":{"A":"Tương lai bị quyết định nhưng con người can thiệp được","B":"Mọi sự kiện quá khứ, hiện tại và tương lai đều được quyết định trước bởi các quy luật nguyên nhân - kết quả tiền đề (All events determined in advance by preceding causes)","C":"Con người đưa ra lựa chọn tự do","D":"Được an bài bởi lực lượng siêu nhiên"},"answerDisplay":"B. All events, past, present, and future, are determined in advance","concept":"• Determinism: Mọi sự kiện bị quy định bởi chuỗi nguyên nhân nhân quả tiền đề.","whyCorrect":"• Định nghĩa chuẩn triết học của Thuyết quyết định luận.","whyWrong":{"A":"• Quyết định luận không cho phép can thiệp ngẫu nhiên ngoài quy luật.","C":"• Lựa chọn tự do là Free Will.","D":"• An bài siêu nhiên là Fatalism."}}},{"id":35,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":35,"chooseType":"Choose 1 answer","question":"Why is it important to categorize ethical risks into specific domains?","options":{"A":"It makes it easier for us to identify, analyze, and manage different types of risks effectively","B":"Ensures customers know we take risks seriously","C":"Helps understand complexities","D":"Helps consider universal tactics"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Tại sao việc phân loại các rủi ro đạo đức thành các danh mục miền cụ thể lại quan trọng?","optionsVi":{"A":"Nó giúp chúng ta dễ dàng hơn trong việc nhận diện, phân tích và quản lý hiệu quả từng loại rủi ro (makes it easier to identify and manage different risks)","B":"Đảm bảo khách hàng biết công ty nghiêm túc","C":"Giúp hiểu sự phức tạp","D":"Giúp tìm giải pháp toàn năng"},"answerDisplay":"A. It makes it easier for us to identify' and manage different types of risks","concept":"• Categorization in Risk Management: Phân loại rủi ro giúp áp dụng đúng công cụ và quy trình giảm thiểu cho từng miền.","whyCorrect":"• Giúp việc nhận diện và quản lý rủi ro trở nên có hệ thống và hiệu quả hơn.","whyWrong":{"B":"• Khách hàng là đối tượng đối ngoại.","C":"• Thấu hiểu phức tạp là kết quả phụ.","D":"• Không có giải pháp toàn năng (universal tactic) cho mọi rủi ro."}}},{"id":36,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":36,"chooseType":"Choose 1 answer","question":"What are the core duties of an Ethics Board for data-driven technology organizations?","options":{"A":"Respond to rapid changes in field and investigate implications","B":"Develop resources for ethical decision making","C":"Build repository of institutional knowledge","D":"All of the above"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Nhiệm vụ cốt lõi của một Hội đồng Đạo đức đối với các tổ chức công nghệ là gì?","optionsVi":{"A":"Phản ứng với các thay đổi công nghệ và điều tra hệ lụy đạo đức","B":"Phát triển tài nguyên cho quy trình ra quyết định đạo đức","C":"Xây dựng kho tri thức tổ chức","D":"Tất cả các đáp án trên (All of the others)"},"answerDisplay":"D. All of the others","concept":"• Chức năng toàn diện của Ethics Board.","whyCorrect":"• Cả 3 nhiệm vụ A, B, C hợp thành chức năng toàn diện.","whyWrong":{"A":"• Chỉ là một phần nhiệm vụ giám sát.","B":"• Chỉ là một phần nhiệm vụ hỗ trợ.","C":"• Chỉ là một phần nhiệm vụ quản trị tri thức."}}},{"id":37,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":37,"chooseType":"Choose 1 answer","question":"What is a culture of accountability in an organization?","options":{"A":"An incentive structure that encourages all employees to feel responsible and identify positive ethical behavior","B":"An incentive structure encouraging external stakeholders","C":"An incentive structure encouraging managers only","D":"An incentive structure encouraging directors only"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Một văn hóa trách nhiệm giải trình (Culture of accountability) trong tổ chức là gì?","optionsVi":{"A":"Cơ cấu khuyến khích thúc đẩy toàn thể nhân viên cảm nhận trách nhiệm và tự giác thực hiện hành vi đạo đức (incentive structure encouraging all employees)","B":"Khuyến khích bên ngoài","C":"Khuyến khích riêng quản lý","D":"Khuyến khích riêng giám đốc"},"answerDisplay":"A. An incentive structure that encourages all employees to identify people who deserve a reward for behaving ethically _","concept":"• Culture of Accountability: Lan tỏa tinh thần trách nhiệm tới toàn thể nhân viên trong tổ chức.","whyCorrect":"• Áp dụng cơ chế khuyến khích tinh thần trách nhiệm cho toàn bộ nhân sự.","whyWrong":{"B":"• Bên ngoài không thuộc văn hóa nội bộ.","C":"• Chỉ quản lý tạo ra phân biệt cấp bậc.","D":"• Chỉ giám đốc không bao quát tổ chức."}}},{"id":38,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":38,"chooseType":"Choose 1 answer","question":"Our primary goals for building ethical AI models are ensuring they are:","options":{"A":"Precise, explainable, predictable","B":"Accurate, precise, fair","C":"Precise, methodical, ethical","D":"Accurate, fair, and explainable"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Mục tiêu chính khi xây dựng các mô hình AI có đạo đức là đảm bảo chúng đạt được 3 tiêu chuẩn nào?","optionsVi":{"A":"Chính xác, giải thích được, dự đoán được","B":"Chính xác, chuẩn xác, công bằng","C":"Chuẩn xác, bài bản, đạo đức","D":"Chính xác (Accurate), Công bằng (Fair) và Giải thích được (Explainable)"},"answerDisplay":"D. accurate, fair and explainable","concept":"• Trụ cột AI Đạo đức: Accuracy (Chính xác), Fairness (Công bằng) và Explainability (Giải thích được).","whyCorrect":"• Bộ ba chỉ số vàng của một mô hình AI có trách nhiệm.","whyWrong":{"A":"• Thiếu chỉ số Công bằng (Fairness).","B":"• Thiếu chỉ số Giải thích được (Explainability).","C":"• Thiếu chỉ số Công bằng."}}},{"id":39,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":39,"chooseType":"Choose 1 answer","question":"Which of the following is a key metric evaluated when measuring differential privacy noise?","options":{"A":"Epsilon (Privacy budget parameter)","B":"Dataset filter","C":"Biased dataset","D":"Model fairness score"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Đại lượng đo lường chính nào được sử dụng khi đánh giá mức độ riêng tư trong Differential Privacy?","optionsVi":{"A":"Epsilon (Tham số ngân sách riêng tư - Privacy budget parameter)","B":"Bộ lọc tập dữ liệu","C":"Tập dữ liệu thiên vị","D":"Điểm công bằng mô hình"},"answerDisplay":"A. Epsilon","concept":"• Differential Privacy Epsilon (ε): Tham số kiểm soát mức độ rò rỉ thông tin riêng tư (Epsilon càng nhỏ, tính riêng tư càng cao).","whyCorrect":"• Epsilon là tham số toán học cốt lõi đo lường ngân sách riêng tư trong Differential Privacy.","whyWrong":{"B":"• Bộ lọc là bước tiền xử lý.","C":"• Dữ liệu thiên vị thuộc kiểm toán công bằng.","D":"• Điểm công bằng thuộc đo lường Fairness."}}},{"id":40,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":40,"chooseType":"Choose 1 answer","question":"Why are environmental concerns important to consider in the development of data-driven technologies?","options":{"A":"Data-driven technologies can cause secondary, indirect, or cumulative effects on the environment that impact people in long term","B":"Direct impact through mining","C":"Direct impact through pollution","D":"Direct impact through displacement"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Tại sao các mối quan ngại môi trường lại quan trọng cần xem xét trong việc phát triển công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Công nghệ dữ liệu gây ra tác động thứ cấp, gián tiếp hoặc tích tụ lên môi trường ảnh hưởng dài hạn tới con người (secondary, indirect, cumulative effects)","B":"Tác động trực tiếp qua khai thác","C":"Tác động trực tiếp qua ô nhiễm","D":"Tác động trực tiếp di dời"},"answerDisplay":"A. Data-driven technologies can cause secondary, indirect, or cumulative effects on the environment that might impact people in the long term.","concept":"• Cumulative Carbon Footprint of AI Datacenters.","whyCorrect":"• Tác động tích tụ dài hạn lên hệ sinh thái môi trường.","whyWrong":{"B":"• Khai thác là chuỗi phần cứng.","C":"• Ô nhiễm trực tiếp là rác điện tử.","D":"• Di dời sinh vật là tác động mặt bằng."}}},{"id":41,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":41,"chooseType":"Choose 1 answer","question":"Which approach to corporate governance is more likely to create an ethical organizational culture?","options":{"A":"A systemic approach with incentive systems aligned with ethical values","B":"An oversight committee focus on rules","C":"A board focused on legal compliance","D":"An oversight committee focus on static frameworks"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Cách tiếp cận quản trị doanh nghiệp nào có khả năng tạo ra một văn hóa tổ chức có đạo đức?","optionsVi":{"A":"Cách tiếp cận hệ thống kết hợp với hệ thống đãi ngộ/khuyến khích gắn liền với giá trị đạo đức (systemic approach with incentive systems)","B":"Ủy ban tập trung quy tắc cứng","C":"Hội đồng tập trung tuân thủ pháp lý","D":"Ủy ban tập trung khung lý thuyết"},"answerDisplay":"A. A systemic approach with incentive systems","concept":"• Systemic Governance: Thưởng/phạt gắn liền với giá trị thúc đẩy hành vi tự giác.","whyCorrect":"• Cơ chế đãi ngộ khuyến khích tạo động lực thực thi văn hóa.","whyWrong":{"B":"• Tập trung quy tắc tạo tâm lý đối phó.","C":"• Tuân thủ pháp lý là mức sàn tối thiểu.","D":"• Khung tĩnh thiếu tính hành động."}}},{"id":42,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":42,"chooseType":"Choose 1 answer","question":"The explainable AI movement states that cooperation between algorithms and humans depends on:","options":{"A":"Trust","B":"Human rights","C":"Competition","D":"Privacy"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Phong trào AI giải thích được khẳng định sự hợp tác giữa thuật toán và con người phụ thuộc vào:","optionsVi":{"A":"Lòng tin (Trust)","B":"Nhân quyền","C":"Cạnh tranh","D":"Quyền riêng tư"},"answerDisplay":"A. trust","concept":"• Human-AI Trust.","whyCorrect":"• Lòng tin là yếu tố quyết định sự hợp tác.","whyWrong":{"B":"• Nhân quyền là giá trị bảo vệ.","C":"• Cạnh tranh là yếu tố thị trường.","D":"• Quyền riêng tư là khía cạnh bảo mật."}}},{"id":43,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":43,"chooseType":"Choose 1 answer","question":"A dataset attribute that is not directly identifiable by itself but can re-identify an individual when combined with other attributes is known as a:","options":{"A":"Explicitly private column","B":"Quasi-identifier","C":"Non-sensitive column","D":"Sensitive column"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Một thuộc tính dữ liệu không tự định danh trực tiếp cá nhân nhưng có thể tái định danh khi kết hợp với các thuộc tính khác được gọi là:","optionsVi":{"A":"Cột riêng tư rõ ràng","B":"Thuộc tính bán định danh (Quasi-identifier)","C":"Cột không nhạy cảm","D":"Cột nhạy cảm"},"answerDisplay":"B. quasi-identifier","concept":"• Quasi-identifiers (Quasi-ID): Mã bưu điện, Ngày sinh, Giới tính - khi đứng riêng không định danh được nhưng khi kết hợp lại xác định được 87% dân số Mỹ.","whyCorrect":"• Thuộc tính bán định danh là định nghĩa chuẩn cho các biến kết hợp tái định danh.","whyWrong":{"A":"• Không có thuật ngữ 'explicitly private column'.","C":"• Cột không nhạy cảm không có nguy cơ tái định danh.","D":"• Cột nhạy cảm chứa thông tin y tế/tài chính."}}},{"id":44,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":44,"chooseType":"Choose 1 answer","question":"Which of the following describes an ethical framework?","options":{"A":"Ethical frameworks raise timeless ethical questions","B":"Ethical frameworks apply meta-ethical theories","C":"Ethical frameworks consolidate regulatory requirements","D":"Ethical frameworks seek to mitigate ethical concerns by creating actionable steps and principles for decision-making"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả một Khung làm việc đạo đức (Ethical framework)?","optionsVi":{"A":"Đặt ra câu hỏi vượt thời gian","B":"Áp dụng lý thuyết siêu đạo đức","C":"Gộp các yêu cầu pháp lý","D":"Khung đạo đức nhằm giảm thiểu các lo ngại đạo đức bằng cách tạo ra các bước hành động cụ thể và các nguyên tắc ra quyết định (mitigate concerns by creating actionable steps)"},"answerDisplay":"D. Ethical frameworks seek to mitigate ethical concerns by creating actionable steps.","concept":"• Ethical Framework Definition: Bộ nguyên tắc và bước hành động thực tiễn (Actionable Steps) để định hướng quyết định đạo đức.","whyCorrect":"• Cung cấp các bước hành động thực tiễn để giải quyết và giảm thiểu nguy cơ đạo đức.","whyWrong":{"A":"• Triết học thuần túy mới dừng ở câu hỏi.","B":"• Meta-ethics là nghiên cứu bản chất đạo đức.","C":"• Quy định pháp lý thuộc về Compliance framework."}}},{"id":45,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":45,"chooseType":"Choose 1 answer","question":"Which of the following communication tactics help uphold transparency and explainability from the customer perspective? (Select two.)","options":{"A":"Providing prompt responses to customer questions about decisions made by AI","B":"Providing information about data-driven systems in simple, easy-to-understand terms","C":"Providing in-depth white papers on algorithms","D":"Providing guidelines for password security"},"answer":"A, B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Những chiến thuật truyền thông nào giúp duy trì tính minh bạch và khả năng giải thích dưới góc nhìn khách hàng? (Select two)","optionsVi":{"A":"Cung cấp phản hồi kịp thời cho các câu hỏi của khách hàng về các quyết định tự động (prompt responses to questions)","B":"Cung cấp thông tin bằng các thuật ngữ đơn giản, dễ hiểu (simple, easy-to-understand terms)","C":"Cung cấp báo cáo kỹ thuật hàn lâm","D":"Cung cấp hướng dẫn bảo mật mật khẩu"},"answerDisplay":"A. Providing prompt responses to customer questions about the decisions made by data-driven systems. & B. Providing information about data-driven systems in simple, easy-to-understand terms.","concept":"• Minh bạch góc nhìn người dùng: Phản hồi nhanh và Ngôn ngữ đơn giản.","whyCorrect":"• Phản hồi kịp thời và dùng từ ngữ đơn giản giúp khách hàng thấu hiểu hệ thống.","whyWrong":{"C":"• Báo cáo hàn lâm quá phức tạp với công chúng.","D":"• Hướng dẫn mật khẩu thuộc an ninh người dùng."}}},{"id":46,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":46,"chooseType":"Choose 1 answer","question":"Once a dataset has been cleaned, which accuracy guideline ensures your model is looking at the problem correctly using core logical domain principles?","options":{"A":"Objective summarization","B":"Domain expertise","C":"Dataset verification","D":"First principles (Tư duy nguyên lý đầu tiên)"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Sau khi tập dữ liệu đã được làm sạch, hướng dẫn độ chính xác nào đảm bảo mô hình đang nhìn nhận vấn đề một cách đúng đắn dựa trên logic cốt lõi?","optionsVi":{"A":"Tóm tắt khách quan","B":"Chuyên môn miền","C":"Xác minh tập dữ liệu","D":"Nguyên lý đầu tiên (First principles)"},"answerDisplay":"D. First principles","concept":"• First Principles Thinking: Phân tích bài toán về các sự thật cơ bản cốt lõi nhất để đảm bảo mô hình xây dựng trên lập luận logic đúng đắn.","whyCorrect":"• Áp dụng nguyên lý đầu tiên giúp mô hình nhìn nhận bài toán từ nền tảng sự thật logic chuẩn xác.","whyWrong":{"A":"• Tóm tắt khách quan là việc tổng quát dữ liệu.","B":"• Chuyên môn miền bổ trợ tri thức ngành.","C":"• Xác minh tập dữ liệu thuộc khâu tiền xử lý."}}},{"id":47,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":47,"chooseType":"Choose 1 answer","question":"Management asks an employee to do a data-related task. Which of the following would likely be ethically problematic? (Select two.)","options":{"A":"Manipulate data or alter its interpretation to fit a desired outcome","B":"Aggregate data together","C":"Change data to another format","D":"Delete inconvenient raw data while claiming it was erroneous"},"answer":"A, D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Quản lý yêu cầu nhân viên thực hiện một tác vụ dữ liệu. Những tác vụ nào sau đây có khả năng cao vi phạm đạo đức? (Select two)","optionsVi":{"A":"Thao túng dữ liệu hoặc làm sai lệch cách diễn giải để phù hợp với kết quả mong muốn (Manipulate data or alter interpretation)","B":"Gom tổng hợp dữ liệu","C":"Chuyển đổi định dạng dữ liệu","D":"Xóa dữ liệu thô không thuận lợi và gán nhãn giả là dữ liệu lỗi (Delete inconvenient data claimed as erroneous)"},"answerDisplay":"A. Manipulate data or alter its interpretatiom & D. Delete any erroneous data (hoặc xóa dữ liệu cố ý)","concept":"• Data Manipulation & Fraud: Thao túng dữ liệu và cố ý xóa bớt dữ liệu thực tế là vi phạm đạo đức nghiêm trọng.","whyCorrect":"• Xuyên tạc diễn giải dữ liệu và xóa dữ liệu thực tế là hành vi gian lận dữ liệu.","whyWrong":{"B":"• Gom dữ liệu là tác vụ phân tích bình thường.","C":"• Chuyển đổi định dạng là kỹ thuật dữ liệu chuẩn."}}},{"id":48,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":48,"chooseType":"Choose 1 answer","question":"Ethical AI models are defined as systems that are:","options":{"A":"Precise, explainable, and private","B":"Accurate, methodical, and fair","C":"Precise, explainable, and fair","D":"Accurate, fair, and explainable (or Accurate, Explainable, and Fair)"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Các mô hình AI có đạo đức (Ethical models) được định nghĩa là các hệ thống:","optionsVi":{"A":"Chuẩn xác, giải thích được và riêng tư","B":"Chính xác, bài bản và công bằng","C":"Chuẩn xác, giải thích được và công bằng","D":"Chính xác (Accurate), Công bằng (Fair) và Giải thích được (Explainable)"},"answerDisplay":"D. accurate, explainable, and fair","concept":"• Ethical Model Pillars: Accurate + Fair + Explainable.","whyCorrect":"• Bộ 3 tiêu chuẩn định nghĩa một mô hình AI có đạo đức.","whyWrong":{"A":"• Thiếu tiêu chuẩn công bằng.","B":"• Thiếu tiêu chuẩn giải thích được.","C":"• Precision là chỉ số kỹ thuật hẹp hơn Accuracy."}}},{"id":49,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":49,"chooseType":"Choose 1 answer","question":"What does it mean to say that human rights are inalienable? (Select two.)","options":{"A":"Inalienable rights are conditional","B":"Inalienable rights are inherent in all human beings by virtue of being human","C":"Inalienable rights cannot be taken away or transferred","D":"Inalienable rights derived from tradition"},"answer":"B, C","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Nói rằng Quyền con người là Không thể tước đoạt (Inalienable) có nghĩa là gì? (Select two)","optionsVi":{"A":"Quyền có điều kiện","B":"Quyền vốn sẵn có ở mọi con người (inherent in all human beings)","C":"Quyền không thể bị lấy mất hay chuyển nhượng (cannot be taken away)","D":"Quyền đến từ truyền thống"},"answerDisplay":"B. Inalienable rights are inherent in all human beings & C. Inalienable rights cannot be taken away except in extreme circumstances.","concept":"• Inalienable Rights: Sẵn có tự nhiên và Không thể bị tước đoạt.","whyCorrect":"• Quyền vốn có và không thể bị tước đoạt là bản chất của Inalienable.","whyWrong":{"A":"• Không phải quyền có điều kiện.","D":"• Quyền mang tính phổ quát không phụ thuộc truyền thống."}}},{"id":50,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":50,"chooseType":"Choose 1 answer","question":"Which of the following is a recommended data governance security practice for machine learning datasets?","options":{"A":"Ensure team is full of perspectives","B":"Enact a sound data governance structure with access controls and audit logs","C":"Perform threat modeling","D":"Create chain of command"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Thực hành an ninh quản trị dữ liệu nào sau đây được khuyến nghị cho các tập dữ liệu học máy?","optionsVi":{"A":"Đảm bảo nhóm nhiều góc nhìn","B":"Ban hành một cấu trúc quản trị dữ liệu vững chắc với phân quyền truy cập và nhật ký kiểm toán (Enact a sound data governance structure)","C":"Thực hiện mô hình hóa đe dọa","D":"Tạo chuỗi chỉ huy"},"answerDisplay":"B. Enact a sound data governance structure","concept":"• Data Governance Structure: Quản lý quyền truy cập (Access Control), phân loại dữ liệu và ghi log kiểm toán.","whyCorrect":"• Thiết lập cấu trúc quản trị dữ liệu bài bản là giải pháp bảo mật dữ liệu hàng đầu.","whyWrong":{"A":"• Nhóm nhiều góc nhìn là quy trình nhân sự.","C":"• Mô hình đe dọa là bước đánh giá rủi ro.","D":"• Chuỗi chỉ huy thuộc về quản lý tổ chức."}}},{"id":51,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":51,"chooseType":"Choose 1 answer","question":"GDPR states that 'Personal data shall be adequate, relevant and limited to what is necessary in relation to the purposes for which they are processed.' This is known as the principle of data being:","options":{"A":"Thoroughly vetted","B":"Not excessive (Data minimization)","C":"Highly specified","D":"Broadly applicable"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"GDPR quy định rằng 'Dữ liệu cá nhân phải đầy đủ, liên quan và giới hạn trong những gì cần thiết cho mục đích xử lý.' Điều này gọi là nguyên tắc dữ liệu phải:","optionsVi":{"A":"Được kiểm tra kỹ lưỡng","B":"Không dư thừa / Giảm thiểu (Not excessive - Data Minimization)","C":"Được chỉ định cao","D":"Áp dụng rộng rãi"},"answerDisplay":"B. not excessive","concept":"• GDPR Article 5(1)(c) Data Minimization: Dữ liệu thu thập không được dư thừa (Not excessive).","whyCorrect":"• Giới hạn thu thập không dư thừa là định nghĩa của nguyên tắc Data Minimization trong GDPR.","whyWrong":{"A":"• Vetted thuộc về tính chính xác.","C":"• Specified thuộc về Purpose Limitation.","D":"• Áp dụng rộng đi ngược lại nguyên tắc giảm thiểu."}}},{"id":52,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":52,"chooseType":"Choose 1 answer","question":"Which of the following presents the most important argument for considering the impact of AI on labor in technology deployment?","options":{"A":"Need for human workers in loop","B":"Avoid union concerns","C":"Impact on worker productivity","D":"There might be potential labor rights and human rights violations if workers are displaced without support"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Lập luận quan trọng nhất giải thích tại sao cần xem xét tác động của AI đối với lao động khi triển khai công nghệ là gì?","optionsVi":{"A":"Cần con người trong vòng lặp","B":"Tránh vấn đề công đoàn","C":"Tác động đến năng suất","D":"Có thể xảy ra vi phạm quyền lao động và nhân quyền nghiêm trọng nếu người lao động bị mất việc mà không được hỗ trợ (potential labor rights and human rights violations)"},"answerDisplay":"D. There might be potential labor rights and human rights violations.","concept":"• Labor & Human Rights in AI Automation: Việc sa thải/thay thế lao động diện rộng do AI đe dọa sinh kế và quyền lao động cơ bản.","whyCorrect":"• Bảo vệ quyền lao động và nhân quyền cơ bản trước nguy cơ bị đào thải bởi tự động hóa.","whyWrong":{"A":"• Nhu cầu con người là vấn đề kỹ thuật.","B":"• Tránh công đoàn là góc nhìn quản lý ngắn hạn.","C":"• Năng suất là chỉ số hiệu quả kinh doanh."}}},{"id":53,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":53,"chooseType":"Choose 1 answer","question":"What is the AI black box problem?","options":{"A":"When a model is deployed, but researchers are unable to figure out why it's making specific decisions","B":"Problem when attributes are inaccurate","C":"Issue of not having enough data","D":"Model cannot judge shape or color"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Bài toán Hộp đen (Black box problem) trong AI được phát biểu chính xác là gì?","optionsVi":{"A":"Khi mô hình đã triển khai nhưng các nhà nghiên cứu không thể tìm ra lý do tại sao nó đưa ra các quyết định đó (unable to figure out why making decisions)","B":"Vấn đề thuộc tính sai","C":"Thiếu dữ liệu huấn luyện","D":"Không đoán được hình dạng màu sắc"},"answerDisplay":"A. When a model is deployed, but researchers are unable to figure out why its making decisions","concept":"• Black Box Problem: Thiếu tính giải thích được về cơ chế lập luận bên trong.","whyCorrect":"• Không thể giải thích cách mô hình xử lý biến số ra kết quả.","whyWrong":{"B":"• Thuộc tính sai gây thiên vị.","C":"• Thiếu dữ liệu gây underfitting.","D":"• Lỗi thị giác máy tính."}}},{"id":54,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":54,"chooseType":"Choose 1 answer","question":"Your business handles the personal data of California residents. Which regulation enables a resident to request data deletion?","options":{"A":"PCI DSS","B":"OECD Privacy Guidelines","C":"COPPA","D":"CCPA"},"answer":"D","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Doanh nghiệp xử lý dữ liệu cư dân California. Quy định nào cho phép cư dân yêu cầu xóa dữ liệu cá nhân?","optionsVi":{"A":"PCI DSS","B":"Hướng dẫn OECD","C":"COPPA","D":"CCPA (California Consumer Privacy Act)"},"answerDisplay":"D. CCPA","concept":"• CCPA Right to Delete.","whyCorrect":"• CCPA quy định quyền xóa dữ liệu cá nhân của cư dân California.","whyWrong":{"A":"• PCI DSS là an toàn thẻ ngân hàng.","B":"• OECD là hướng dẫn quốc tế.","C":"• COPPA là luật riêng tư trẻ em."}}},{"id":55,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":55,"chooseType":"Choose 1 answer","question":"What primary strategy do researchers use to evaluate the fairness of an existing black box model?","options":{"A":"Systematically change input data perturbations and evaluate the resulting output decisions (Audit by testing inputs/outputs)","B":"Change training data and evaluate outputs","C":"Change inputs and evaluate training data","D":"Evaluate inputs and data"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Chiến lược chính nào được các nhà nghiên cứu sử dụng để đánh giá tính công bằng của một mô hình Hộp đen đã triển khai?","optionsVi":{"A":"Thay đổi có hệ thống các đầu vào thử nghiệm và đánh giá các quyết định đầu ra thu được (Change inputs, evaluate outputs)","B":"Thay đổi dữ liệu huấn luyện","C":"Thay đổi đầu vào và đánh giá dữ liệu huấn luyện","D":"Đánh giá đầu vào và dữ liệu"},"answerDisplay":"A_ Change inputs, evaluate outputs","concept":"• Black-box Audit Technique: Kiểm thử tạo nhiễu biến số đầu vào (Input Perturbation) và quan sát sự thay đổi đầu ra (Output Observation) mà không cần truy cập mã nguồn.","whyCorrect":"• Đổi đầu vào và đánh giá đầu ra là phương pháp duy nhất để kiểm toán Hộp đen đóng.","whyWrong":{"B":"• Mô hình Hộp đen đã triển khai không cho phép sửa dữ liệu huấn luyện.","C":"• Đánh giá dữ liệu huấn luyện không đo được đầu ra mô hình.","D":"• Đánh giá đầu vào đơn thuần không đo được thiên vị đầu ra."}}},{"id":56,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":56,"chooseType":"Choose 1 answer","question":"Which school of philosophical thought primarily advocates for a global moral code based on categorical duty?","options":{"A":"Utilitarianism","B":"Deontology","C":"Virtue ethics","D":"Virtual ethics"},"answer":"B","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Trường phái tư tưởng triết học nào chủ yếu cổ vũ cho một bộ quy tắc đạo đức toàn cầu dựa trên nghĩa vụ tuyệt đối?","optionsVi":{"A":"Thuyết vị lợi","B":"Thuyết nghĩa vụ luận (Deontology)","C":"Thuyết đạo đức đức hạnh","D":"Đạo đức ảo"},"answerDisplay":"B. Deontology","concept":"• Deontology (Kantian ethics): Quy tắc đạo đức là nghĩa vụ tuyệt đối phổ quát.","whyCorrect":"• Nghĩa vụ luận đòi hỏi tuân thủ các quy tắc tuyệt đối.","whyWrong":{"A":"• Utilitarianism đánh giá theo hậu quả.","C":"• Virtue ethics tập trung vào đức hạnh cá nhân.","D":"• Virtual ethics không phải trường phái triết học."}}},{"id":57,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":57,"chooseType":"Choose 1 answer","question":"How do AI and data-driven technologies utilize probability in decision making?","options":{"A":"By determining objective likelihood","B":"By estimating likelihood without input data","C":"By providing a mathematical model of belief about the likelihood of an outcome given available evidence","D":"By guaranteeing 100% certainty"},"answer":"C","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"AI và các công nghệ dựa trên dữ liệu sử dụng xác suất như thế nào trong việc ra quyết định?","optionsVi":{"A":"Xác định khả năng khách quan","B":"Ước tính không cần dữ liệu","C":"Cung cấp một mô hình toán học phản ánh mức độ tin tưởng về khả năng xảy ra của một sự kiện dựa trên dữ liệu hiện có (model of belief about likelihood)","D":"Đảm bảo chắc chắn 100%"},"answerDisplay":"C. By providing a model of belief about the likelihood of some event happening","concept":"• Probabilistic Inference in AI (Bayesian Logic): Mô hình hóa mức độ tin tưởng (Degree of belief / Likelihood) dựa trên bằng chứng dữ liệu thu thập được.","whyCorrect":"• Tạo dựng mô hình toán học lượng hóa mức độ tin tưởng về khả năng xảy ra sự kiện.","whyWrong":{"A":"• Xác suất trong AI mang tính suy luận toán học từ dữ liệu mẫu.","B":"• Phải bắt buộc có dữ liệu đầu vào.","D":"• AI không bao giờ cam kết chắc chắn 100% trong môi trường bất định."}}},{"id":58,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":58,"chooseType":"Choose 1 answer","question":"Which of the following is a transparency risk of closed source software?","options":{"A":"Closed source software may not be accessible to independent auditors for security and ethics review","B":"Closed source software cannot be shared with partners","C":"Closed source software includes obfuscated code","D":"Closed source software cannot be reviewed by developing organization"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Nội dung nào sau đây mô tả rủi ro về tính minh bạch của phần mềm mã nguồn đóng?","optionsVi":{"A":"Phần mềm mã nguồn đóng có thể không cho phép các kiểm toán viên độc lập bên ngoài truy cập xem xét (may not be accessible to independent auditors)","B":"Không thể chia sẻ với đối tác","C":"Chứa mã xáo trộn","D":"Không thể được xem xét bởi chính tổ chức phát triển"},"answerDisplay":"A. Closed source software may not be accessible to independent auditors.","concept":"• Closed Source Transparency Risk: Ngăn cản sự kiểm toán của bên thứ ba độc lập.","whyCorrect":"• Ngăn cấm kiểm toán viên độc lập kiểm tra mã nguồn.","whyWrong":{"B":"• Vẫn chia sẻ qua hợp đồng.","C":"• Mã nguồn đóng lưu mã nhị phân.","D":"• Tổ chức phát triển nắm toàn bộ mã."}}},{"id":59,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":59,"chooseType":"Choose 1 answer","question":"An adversarial model attack or test relies primarily on using:","options":{"A":"Perturbed inputs (Adversarial perturbation inputs)","B":"Sensitive columns","C":"Algorithm detection","D":"Pressure inputs"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Một cuộc tấn công hoặc kiểm thử mô hình đối kháng (Adversarial model) chủ yếu dựa vào việc sử dụng:","optionsVi":{"A":"Các đầu vào bị xáo trộn / tạo nhiễu đối kháng (Perturbed inputs)","B":"Các cột nhạy cảm","C":"Phát hiện thuật toán","D":"Đầu vào áp lực"},"answerDisplay":"A. perturbed inputs","concept":"• Adversarial Attacks (Nhiễu đối kháng): Thêm các nhiễu siêu nhỏ không thể nhận biết bởi con người (Perturbed inputs) để lừa mô hình AI dự đoán sai hoàn toàn.","whyCorrect":"• Sử dụng các đầu vào bị tạo nhiễu đối kháng (Perturbed inputs) để đánh lừa mô hình.","whyWrong":{"B":"• Cột nhạy cảm thuộc về bài toán công bằng.","C":"• Phát hiện thuật toán không phải cơ chế tấn công.","D":"• Pressure inputs không phải thuật ngữ AI."}}},{"id":60,"task":"sp24_fe_re","taskLabel":"SP24 FE RE","num":60,"chooseType":"Choose 1 answer","question":"Which of the following is a primary reason to periodically update an organization's Code of Ethics document?","options":{"A":"It captures the evolving nature of new technological developments and ethical risks of the product","B":"Signals care to stakeholders","C":"Reinforces code in minds of employees","D":"Fiduciary responsibility"},"answer":"A","source":"ITE302c_SP24_FE_RE","explanation":{"questionVi":"Lý do chính của việc cần cập nhật định kỳ tài liệu Quy tắc đạo đức của tổ chức là gì?","optionsVi":{"A":"Nó bắt kịp bản chất liên tục tiến hóa của các phát triển công nghệ mới và các rủi ro đạo đức của sản phẩm (captures evolving nature of ethical risks)","B":"Phát tín hiệu quan tâm tới các bên","C":"Củng cố quy tắc trong tâm trí nhân viên","D":"Trách nhiệm pháp lý hình thức"},"answerDisplay":"A. It allows you to capture the evolving nature of the ethical risks of the product or service that you are developing.","concept":"• Iterative Ethics Policy: Công nghệ và rủi ro AI liên tục tiến hóa (Evolving risks) đòi hỏi bộ quy tắc phải cập nhật định kỳ.","whyCorrect":"• Bắt kịp với sự xuất hiện của các rủi ro đạo đức mới phát sinh từ sự phát triển công nghệ.","whyWrong":{"B":"• Phát tín hiệu là mục tiêu PR.","C":"• Củng cố thói quen qua đào tạo hàng ngày.","D":"• Trách nhiệm pháp lý chỉ là điều kiện bắt buộc."}}},{"id":1,"task":"sp24_fe","taskLabel":"SP24 FE","num":1,"chooseType":"Choose 1 answer","question":"A good example of feedback loop in machine learning occurs when:","options":{"A":"An image recognition model selects one face over another based on sample data","B":"A model selects for one demographic less often because of their historical representation, which then reinforces lower representation in future data","C":"A model fails to recognize cultural differences due to incorrect attributes","D":"A predictive model incorporates training data from a variety of sources"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Một ví dụ điển hình về Vòng lặp phản hồi (Feedback loop) trong học máy xảy ra khi nào?","optionsVi":{"A":"Mô hình nhận diện khuôn mặt chọn mặt này thay vì mặt khác dựa trên dữ liệu mẫu","B":"Mô hình lựa chọn một nhóm nhân khẩu học ít hơn do sự hiện diện lịch sử thấp của họ, điều này tiếp tục củng cố sự hiện diện thấp hơn trong dữ liệu tương lai (selects one demographic less often reinforcing lower representation)","C":"Mô hình không nhận diện được sự khác biệt văn hóa do thuộc tính sai","D":"Mô hình dự đoán kết hợp dữ liệu huấn luyện từ nhiều nguồn"},"answerDisplay":"B. a model selects for one demographic less often because of their historical representation","concept":"• Vòng lặp phản hồi củng cố (Reinforcing Feedback Loop): Dữ liệu thiên vị lịch sử tạo ra quyết định đầu ra lệch lạc, đầu ra đó tiếp tục trở thành dữ liệu đầu vào làm sâu sắc thêm thiên vị trong tương lai.","whyCorrect":"• Sự lặp lại củng cố thiên vị đại diện lịch sử qua các vòng huấn luyện là bản chất của feedback loop.","whyWrong":{"A":"• Nhận diện khuôn mặt mẫu là dự đoán đơn lẻ.","C":"• Lỗi thuộc tính sai là lỗi Feature engineering.","D":"• Thu thập đa nguồn giúp giảm thiên vị."}}},{"id":2,"task":"sp24_fe","taskLabel":"SP24 FE","num":2,"chooseType":"Choose 1 answer","question":"Which of the following are requirements set forth by the Biometric Information Privacy Act (BIPA)? (Select two.)","options":{"A":"Organizations must not transmit biometric data across an unsecured network","B":"Organizations must obtain written consent from individuals regarding the collection and use of biometric data","C":"Organizations must destroy biometric data in a timely fashion according to a schedule","D":"Organizations must store biometric data in local, on-premises databases"},"answer":"B, C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Những yêu cầu nào sau đây do Đạo luật bảo vệ quyền riêng tư thông tin sinh trắc học (BIPA) quy định? (Select two)","optionsVi":{"A":"Tổ chức không được truyền dữ liệu sinh trắc học qua mạng không an toàn","B":"Tổ chức phải nhận được sự đồng ý bằng văn bản từ cá nhân trước khi thu thập và sử dụng dữ liệu sinh trắc học (obtain consent regarding collection)","C":"Tổ chức phải hủy bỏ dữ liệu sinh trắc học một cách kịp thời đúng hạn (destroy biometric data in a timely fashion)","D":"Tổ chức phải lưu dữ liệu trong cơ sở dữ liệu nội bộ tại chỗ"},"answerDisplay":"B. Organizations must obtain consent from individuals regarding the collection and use of biometric data. & C. Organizations must destroy biometric data in a timely fashion.","concept":"• Quy định BIPA (Biometric Information Privacy Act): Đòi hỏi Sự đồng ý trước (Informed Written Consent) và Lịch trình hủy bỏ dữ liệu (Timely Destruction Schedule).","whyCorrect":"• Xin phép đồng ý trước và hủy bỏ dữ liệu đúng hạn là 2 yêu cầu tiêu chuẩn của BIPA.","whyWrong":{"A":"• Mạng truyền tải được cho phép nếu mã hóa TLS an toàn.","D":"• BIPA không cấm lưu trữ trên đám mây."}}},{"id":3,"task":"sp24_fe","taskLabel":"SP24 FE","num":3,"chooseType":"Choose 1 answer","question":"Which of the following elements might be considered moderately affected in an Impact Level 2 Algorithmic Impact Assessment?","options":{"A":"Loss of life resulting from specific circumstances","B":"A brief delay in the conveyance of a commercial transaction","C":"The fundamental rights of individuals or communities","D":"The long-term health and well-being of individuals"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Yếu tố nào sau đây có thể được coi là chịu tác động ở mức độ Vừa phải (Impact Level 2 / Moderately affected) trong Đánh giá tác động thuật toán?","optionsVi":{"A":"Thiệt hại sinh mạng con người (Level 4 - High/Critical)","B":"Một sự trì hoãn ngắn trong việc thực hiện giao dịch thương mại (brief delay in commercial transaction)","C":"Quyền cơ bản của cá nhân hoặc cộng đồng (Level 3/4)","D":"Sức khỏe dài hạn của cá nhân (Level 4)"},"answerDisplay":"B. A brief delay in the conveyance of a commercial transaction.","concept":"• Cấp độ Tác động Thuật toán Level 2 (Moderate Impact): Gây ra các bất tiện tạm thời hoặc trì hoãn ngắn trong giao dịch commercial transaction.","whyCorrect":"• Sự trì hoãn ngắn giao dịch thuộc phân cấp tác động vừa phải Moderate Level 2.","whyWrong":{"A":"• Thiệt hại sinh mạng thuộc Level 4 (Critical/High).","C":"• Nhân quyền thuộc Level 3 hoặc Level 4.","D":"• Sức khỏe dài hạn thuộc Level 4."}}},{"id":4,"task":"sp24_fe","taskLabel":"SP24 FE","num":4,"chooseType":"Choose 1 answer","question":"Which of the following is a critical element when designing a public awareness campaign about ethical risks?","options":{"A":"The environment in which campaign will be launched","B":"The effect the campaign has on bottom line","C":"The time-sensitive nature of communication in campaign","D":"The specific ethical risks that will be communicated clearly to the audience"},"answer":"D","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Yếu tố quan trọng hàng đầu khi thiết kế một chiến dịch nâng cao nhận thức cộng đồng về các rủi ro đạo đức là gì?","optionsVi":{"A":"Môi trường nơi chiến dịch ra mắt","B":"Tác động đến lợi nhuận công ty","C":"Tính chất nhạy cảm thời gian","D":"Các rủi ro đạo đức cụ thể sẽ được truyền thông rõ ràng tới công chúng (risks that will be talked about in campaign)"},"answerDisplay":"D. The risks that will be talked about in the campaign","concept":"• Trọng tâm Truyền thông Nhận thức: Xác định và truyền tải minh bạch các nguy cơ rủi ro đạo đức cụ thể để công hướng tới sự chuẩn bị.","whyCorrect":"• Nội dung rủi ro đạo đức cụ thể cần truyền thông là hạt nhân quyết định sự thành bại của chiến dịch nhận thức.","whyWrong":{"A":"• Môi trường chỉ là kênh truyền tải.","B":"• Lợi nhuận là mục tiêu thương mại.","C":"• Thời gian là yếu tố lập kế hoạch."}}},{"id":5,"task":"sp24_fe","taskLabel":"SP24 FE","num":5,"chooseType":"Choose 1 answer","question":"A model can still exhibit bias even if a protected attribute is removed from dataset. This phenomenon occurs when:","options":{"A":"Biased training","B":"Proxy attributes (blind attributes) correlate with protected characteristics","C":"Single attribute","D":"False-negative optimized"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Một mô hình vẫn có thể thể hiện sự thiên vị ngay cả khi thuộc tính được bảo vệ (giới tính, chủng tộc) đã bị loại bỏ khỏi tập dữ liệu. Hiện tượng này xảy ra do:","optionsVi":{"A":"Huấn luyện thiên vị","B":"Các thuộc tính ẩn / thuộc tính thay thế (Proxy / Blind attributes) có sự tương quan mạnh với các đặc trưng được bảo vệ (proxy attributes correlate with protected traits)","C":"Thuộc tính đơn","D":"Tối ưu hóa âm tính giả"},"answerDisplay":"B. blind attribute","concept":"• Thuộc tính Thay thế (Proxy Attributes / Redlining): Ngay cả khi xóa cột chủng tộc, mã bưu điện (Zip code) vẫn đóng vai trò biến thay thế phản ánh sự phân bố chủng tộc.","whyCorrect":"• Thuộc tính ẩn/thay thế có tương quan ngầm với đặc trưng bảo vệ sinh ra thiên vị gián tiếp.","whyWrong":{"A":"• Huấn luyện thiên vị là kết quả chung.","C":"• Thuộc tính đơn không giải thích nguyên nhân ẩn.","D":"• Tối ưu hóa âm tính giả là chỉ số công bằng."}}},{"id":6,"task":"sp24_fe","taskLabel":"SP24 FE","num":6,"chooseType":"Choose 1 answer","question":"Why is it important to include a diverse set of stakeholders when gathering perspectives for risk assessment?","options":{"A":"It is a legal requirement in many jurisdictions","B":"It includes more perspectives, which leads to better risk identification and reduced blind spots","C":"It gives an opportunity to identify people as risk","D":"It gives an opportunity to identify technology as risk"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Tại sao việc thu hút đa dạng các bên liên quan (Diverse stakeholders) khi thu thập góc nhìn cho đánh giá rủi ro lại quan trọng?","optionsVi":{"A":"Yêu cầu pháp lý ở nhiều nơi","B":"Nó bao gồm nhiều góc nhìn hơn, dẫn tới việc nhận diện rủi ro tốt hơn và phát hiện các điểm mù (includes more perspectives, better risk identification)","C":"Cơ hội nhận diện con người là rủi ro","D":"Cơ hội nhận diện công nghệ là rủi ro"},"answerDisplay":"B. It includes more perspectives, which can lead to better risk identification","concept":"• Đa dạng hóa Góc nhìn Quản trị Rủi ro (Diverse Stakeholder Engagement): Giúp phát hiện các góc khuất và rủi ro ẩn mà một nhóm chuyên gia đồng nhất dễ bỏ qua.","whyCorrect":"• Thu thập nhiều góc nhìn phong phú giúp nhận diện toàn diện các rủi ro hệ thống.","whyWrong":{"A":"• Tuân thủ luật pháp không phải giá trị duy nhất.","C":"• Con người không phải đối tượng bị coi là rủi ro.","D":"• Nhận diện công nghệ là việc đánh giá kỹ thuật."}}},{"id":7,"task":"sp24_fe","taskLabel":"SP24 FE","num":7,"chooseType":"Choose 1 answer","question":"Which of the following describes why freedom of expression is considered an important right on digital platforms?","options":{"A":"It helps uphold freedom of expression for everyone and doesn't give anyone special rights","B":"It prevents the spread of disinformation that causes harm to vulnerable populations","C":"It prevents monopolies","D":"It creates adequate incentives"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả lý do tại sao tự do ngôn luận cần đi kèm các giới hạn có trách nhiệm trên nền tảng số?","optionsVi":{"A":"Ủng hộ tự do phát biểu cho mọi người không đặc quyền","B":"Giúp ngăn chặn sự phát tán của tin giả / thông tin sai lệch gây tổn hại cho các nhóm dễ bị tổn thương (prevents spread of disinformation causing harm)","C":"Ngăn chặn độc quyền sáng tạo","D":"Tạo động lực chia sẻ ý kiến"},"answerDisplay":"B. It prevents the spread of disinformation that can cause harm to vulnerable populations.","concept":"• Tự do Ngôn luận có Trách nhiệm (Responsible Freedom of Expression): Cần cân bằng giữa quyền tự do phát biểu và nghĩa vụ ngăn chặn tin giả (Disinformation) gây tổn hại xã hội.","whyCorrect":"• Ngăn chặn thông tin sai lệch bảo vệ cộng đồng dễ bị tổn thương khỏi các hiểm họa mạng.","whyWrong":{"A":"• Tự do tuyệt đối không kiểm soát gây ra tin giả.","C":"• Độc quyền sáng tạo thuộc luật bản quyền IP.","D":"• Động lực chia sẻ thuộc trải nghiệm người dùng."}}},{"id":8,"task":"sp24_fe","taskLabel":"SP24 FE","num":8,"chooseType":"Choose 1 answer","question":"Your Vice President asks for processed facts with contextual meaning to make a strategic business decision. What are they asking for?","options":{"A":"Information","B":"Knowledge","C":"Wisdom","D":"Data"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Phó Chủ tịch công ty yêu cầu bạn cung cấp các sự thật đã qua xử lý kèm theo bối cảnh ý nghĩa để đưa ra quyết định chiến lược. Họ đang yêu cầu điều gì?","optionsVi":{"A":"Thông tin (Information)","B":"Tri thức (Knowledge)","C":"Sự khôn ngoan (Wisdom)","D":"Dữ liệu thô (Data)"},"answerDisplay":"A. Information","concept":"• Tháp DIKW (Data - Information - Knowledge - Wisdom): Data (Dữ liệu thô) + Context/Processing = Information (Thông tin có bối cảnh).","whyCorrect":"• Dữ liệu thô được gán bối cảnh và xử lý chính là định nghĩa của Thông tin (Information).","whyWrong":{"B":"• Knowledge là thông tin được tổng hợp và thấu hiểu qua kinh nghiệm.","C":"• Wisdom là khả năng vận dụng tri thức để ra quyết định đúng đắn.","D":"• Data là các con số/kí tự thô chưa qua xử lý."}}},{"id":9,"task":"sp24_fe","taskLabel":"SP24 FE","num":9,"chooseType":"Choose 1 answer","question":"Which of the following are primary pillars of ethical AI frameworks?","options":{"A":"Transparency and explainability","B":"Happiness and spiritual contentment","C":"Human control and autonomy","D":"Fairness and non-discrimination"},"answer":"A, D","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Những nội dung nào sau đây là các trụ cột chính trong các khung đạo đức AI? (Select primary pillars)","optionsVi":{"A":"Tính minh bạch và tính giải thích được (Transparency and explainability)","B":"Hạnh phúc và sự thỏa mãn tâm linh","C":"Sự kiểm soát của con người","D":"Tính công bằng và không đĩa đối xử (Fairness and non-discrimination)"},"answerDisplay":"A. Transparency and explainability & D. Fairness and non-discrimination","concept":"• Trụ cột Đạo đức AI chuẩn quốc tế: Transparency (Minh bạch), Explainability (Giải thích được) và Fairness (Công bằng).","whyCorrect":"• Minh bạch, giải thích được và công bằng là các trụ cột nền tảng của AI có trách nhiệm.","whyWrong":{"B":"• Hạnh phúc tâm linh không thuộc tiêu chuẩn kỹ thuật AI.","C":"• Kiểm soát con người thuộc trụ cột Human Agency."}}},{"id":10,"task":"sp24_fe","taskLabel":"SP24 FE","num":10,"chooseType":"Choose 1 answer","question":"To measure a predictive model's accuracy, you:","options":{"A":"Divide number of predictions by total dataset","B":"Measure ratio of error curve","C":"Multiply predictions by percentage","D":"Divide the number of correct predictions by the total number of predictions"},"answer":"D","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Để đo lường độ chính xác (Accuracy) của một mô hình dự đoán, bạn thực hiện phép tính nào?","optionsVi":{"A":"Chia số dự đoán cho tổng tập dữ liệu","B":"Đo tỷ lệ đường cong lỗi","C":"Nhân tổng dự đoán với phần trăm đúng","D":"Chia số lượng dự đoán đúng cho tổng số lượng dự đoán (Divide correct predictions by total predictions)"},"answerDisplay":"D. divide the number of correct predictions by the total number of predictions","concept":"• Accuracy Formula: (Correct Predictions) / (Total Predictions).","whyCorrect":"• Phép chia số dự đoán đúng cho tổng số lần dự đoán ra chỉ số độ chính xác.","whyWrong":{"A":"• Phép chia không tính đến dự đoán đúng.","B":"• Đường cong lỗi đo Loss curve.","C":"• Phép nhân không ra công thức Accuracy."}}},{"id":11,"task":"sp24_fe","taskLabel":"SP24 FE","num":11,"chooseType":"Choose 1 answer","question":"Which of the following describes change management in organizational ethics?","options":{"A":"A collective term describing how employees voice concerns","B":"A collective term for all approaches to prepare, support, and help individuals, teams, and organizations in fostering an ethical organizational culture","C":"A collective term for product modifications after negative feedback","D":"A process to replace executive board"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả Quản lý sự thay đổi (Change management) trong bối cảnh đạo đức tổ chức?","optionsVi":{"A":"Thuật ngữ mô tả cách nhân viên lên tiếng","B":"Thuật ngữ chung cho tất cả các phương pháp nhằm chuẩn bị, hỗ trợ và giúp đỡ cá nhân, đội ngũ và tổ chức thực hiện sự chuyển đổi sang văn hóa đạo đức (approaches to prepare, support, help in fostering ethical culture)","C":"Sửa đổi sản phẩm sau phản hồi","D":"Quy trình thay thế ban điều hành"},"answerDisplay":"B. A collective term for all approaches to prepare, support, and help individuals, teams, and organizations in fostering an ethical organizational culture.","concept":"• Change Management: Quy trình chuẩn bị và hỗ trợ tổ chức thích nghi thành công với văn hóa đạo đức mới.","whyCorrect":"• Chuẩn bị và hỗ trợ toàn diện các cấp trong tổ chức thực hiện chuyển đổi văn hóa.","whyWrong":{"A":"• Lên tiếng là Employee Voice.","C":"• Sửa sản phẩm là Product Iteration.","D":"• Thay ban điều hành là Succession planning."}}},{"id":12,"task":"sp24_fe","taskLabel":"SP24 FE","num":12,"chooseType":"Choose 1 answer","question":"Which of the following entities have the primary responsibility to enforce regulations and protect public interest regarding data privacy?","options":{"A":"Individuals","B":"Municipal governments","C":"National regulatory agencies and governments","D":"Private corporations"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Thực thể nào sau đây có trách nhiệm chính trong việc thực thi các quy định pháp lý và bảo vệ lợi ích công cộng liên quan đến quyền riêng tư dữ liệu?","optionsVi":{"A":"Cá nhân người dùng","B":"Chính quyền thành phố","C":"Các cơ quan quản lý và chính phủ quốc gia (National regulatory agencies and governments)","D":"Các tập đoàn tư nhân"},"answerDisplay":"C. National governments","concept":"• Vai trò Quản lý Nhà nước (Government Regulations): Chính phủ quốc gia có thẩm quyền ban hành và thực thi pháp luật (như GDPR, CCPA) để bảo vệ quyền lợi công chúng.","whyCorrect":"• Các cơ quan quản lý nhà nước có thẩm quyền thi hành pháp luật trên phạm vi toàn quốc.","whyWrong":{"A":"• Cá nhân là chủ thể được bảo vệ.","B":"• Chính quyền địa phương bị giới hạn thẩm quyền.","D":"• Tập đoàn tư nhân là đối tượng chịu sự điều chỉnh của luật."}}},{"id":13,"task":"sp24_fe","taskLabel":"SP24 FE","num":13,"chooseType":"Choose 1 answer","question":"Which of the following is a post-hoc local explainability technique for machine learning models?","options":{"A":"LIME (Local Interpretable Model-agnostic Explanations)","B":"Shapley value (SHAP)","C":"Anchor Explanations","D":"Perturbation"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Kỹ thuật giải thích cục bộ sau huấn luyện (Post-hoc local explainability) phổ biến nào được dùng cho các mô hình học máy?","optionsVi":{"A":"LIME (Giải thích độc lập với mô hình có thể diễn giải cục bộ)","B":"Giá trị Shapley (SHAP)","C":"Giải thích mỏ neo (Anchor)","D":"Nhiễu loạn dữ liệu"},"answerDisplay":"A. Local Interpretable Model-Agnostic Explanations","concept":"• LIME (Local Interpretable Model-agnostic Explanations): Xấp xỉ mô hình phức tạp xung quanh một điểm dự đoán cụ thể bằng một mô hình đơn giản có thể giải thích được.","whyCorrect":"• LIME là kỹ thuật giải thích cục bộ độc lập với thuật toán kinh điển.","whyWrong":{"B":"• SHAP tính toán đóng góp dựa trên lý thuyết trò chơi.","C":"• Anchor tìm quy tắc quyết định đủ.","D":"• Perturbation là kỹ thuật tạo nhiễu."}}},{"id":14,"task":"sp24_fe","taskLabel":"SP24 FE","num":14,"chooseType":"Choose 1 answer","question":"Which of the following are possible causes of limited adoption of a code of ethics within an organization?","options":{"A":"Comprehensive coverage of concerns","B":"Lack of clarity in the code of ethics","C":"Prescriptive language used","D":"Lack of awareness of the code of ethics and where it is meant to be applied"},"answer":"B, D","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Những nguyên nhân nào sau đây dẫn đến việc áp dụng hạn chế bộ quy tắc đạo đức trong một tổ chức? (Select two)","optionsVi":{"A":"Bao phủ toàn diện các mối quan ngại","B":"Sự thiếu rõ ràng trong bộ quy tắc đạo đức (Lack of clarity in the code of ethics)","C":"Ngôn ngữ chỉ định","D":"Thiếu nhận thức về bộ quy tắc đạo đức và nơi áp dụng (Lack of awareness of the code of ethics)"},"answerDisplay":"B. Lack of clarity in the code of ethics & D. Lack of awareness of the code of ethics and where it is meant to be applied","concept":"• Nguyên nhân thất bại của Code of Ethics: Sự thiếu rõ ràng (Ambiguity) và Thiếu truyền thông tập huấn nâng cao nhận thức (Lack of awareness).","whyCorrect":"• Ngôn từ mập mờ và thiếu đào tạo khiến nhân viên không hiểu và không biết cách áp dụng.","whyWrong":{"A":"• Bao phủ toàn diện giúp áp dụng tốt hơn.","C":"• Ngôn ngữ chỉ định rõ ràng giúp tuân thủ dễ hơn."}}},{"id":15,"task":"sp24_fe","taskLabel":"SP24 FE","num":15,"chooseType":"Choose 1 answer","question":"Which of the following describes ethics washing in corporate practices?","options":{"A":"No attempt is made towards genuine ethical action","B":"Superficial promises are replaced by genuine action","C":"Genuine ethical action is used to wash over previous mistakes","D":"Genuine ethical action gets replaced by superficial promises and PR statements"},"answer":"D","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả Tẩy trắng đạo đức (Ethics washing) trong thực tiễn doanh nghiệp?","optionsVi":{"A":"Không nỗ lực hành động","B":"Lời hứa bề nổi được thay bằng hành động thật","C":"Hành động thật dùng để che lỗi cũ","D":"Các hành động đạo đức thực chất bị thay thế bởi các lời hứa bề nổi và tuyên bố PR hình thức (Genuine ethical action gets replaced by superficial promises)"},"answerDisplay":"D. Genuine ethical action gets replaced by superficial promises","concept":"• Ethics Washing: Việc doanh nghiệp dùng khẩu hiệu PR và các tuyên bố bóng bẩy hình thức để thay thế cho các cam kết hành động đạo đức thực chất.","whyCorrect":"• Thay thế hành động thực chất bằng quảng cáo hình thức bề nổi là bản chất của Ethics Washing.","whyWrong":{"A":"• Không nỗ lực là sự thờ ơ đơn thuần.","B":"• Đây là sự chuyển biến tích cực.","C":"• Khắc phục lỗi cũ là hành động bù đắp."}}},{"id":16,"task":"sp24_fe","taskLabel":"SP24 FE","num":16,"chooseType":"Choose 1 answer","question":"Pseudocode can best be defined as:","options":{"A":"An explainable description of code that is meant for humans, not computers","B":"A Python library for machine learning","C":"A middle ground between code and plain writing fed into computers","D":"A type of Javascript"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Mã giả (Pseudocode) được định nghĩa đúng nhất là gì?","optionsVi":{"A":"Mô tả thuật toán có thể giải thích được dành cho con người đọc hiểu, không dùng cho máy tính (meant for humans, not computers)","B":"Một thư viện Python","C":"Ngôn ngữ trung gian nạp vào máy tính","D":"Loại Javascript"},"answerDisplay":"A. an explainable description of code that is meant for humans, not computers","concept":"• Pseudocode: Mã giả dùng để diễn đạt logic thuật toán cho con người trao đổi.","whyCorrect":"• Dành cho con người đọc hiểu chứ không thực thi trực tiếp trên máy tính.","whyWrong":{"B":"• Không phải thư viện lập trình.","C":"• Máy tính không thực thi trực tiếp mã giả.","D":"• Không phải ngôn ngữ Javascript."}}},{"id":17,"task":"sp24_fe","taskLabel":"SP24 FE","num":17,"chooseType":"Choose 1 answer","question":"Which of the following is an important action needed for the finalization of internal and external ethics policies before approval?","options":{"A":"Discarding open issues to provide a clean slate","B":"Documenting the assumptions and choices made in the drafting of policies","C":"Testing policy in deployed project","D":"Ensuring policies are same as peers"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Hành động quan trọng nào cần thiết cho việc hoàn thiện các chính sách đạo đức trước khi phê duyệt chính thức?","optionsVi":{"A":"Bỏ qua các vấn đề mở","B":"Ghi chép tài liệu về các giả định và lựa chọn được đưa ra trong quá trình dự thảo (Documenting assumptions and choices made)","C":"Thử nghiệm trên dự án thực tế","D":"Đảm bảo chính sách giống hệt đối thủ"},"answerDisplay":"B. Documenting the assumptions and choices made in the drafting of the policies","concept":"• Ghi chép tài liệu giả định và căn cứ dự thảo chính sách tạo cơ sở giải trình và kiểm toán.","whyCorrect":"• Ghi chép các giả định giúp minh bạch hóa lý do đưa ra chính sách.","whyWrong":{"A":"• Bỏ qua vấn đề là giấu rủi ro.","C":"• Thử nghiệm nên làm ở pha pilot.","D":"• Sao chép bỏ qua tính đặc thù."}}},{"id":18,"task":"sp24_fe","taskLabel":"SP24 FE","num":18,"chooseType":"Choose 1 answer","question":"An unfair model will by nature:","options":{"A":"Optimize for making fewest decisions","B":"Try to balance groups automatically","C":"Optimize for making errors on specific subgroups while keeping high overall accuracy","D":"Optimize for making fewest mistakes"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Một mô hình không công bằng (Unfair model) về mặt bản chất sẽ:","optionsVi":{"A":"Tối ưu hóa ra ít quyết định","B":"Tự động cân bằng nhóm","C":"Tối ưu hóa bằng cách dồn sai số/lỗi lên một phân nhóm cụ thể để duy trì độ chính xác chung (concentrating errors on specific subgroup)","D":"Tối ưu hóa mắc ít lỗi nhất"},"answerDisplay":"C. optimize for making the most errors on specific subgroup","concept":"• Unfair Model behavior: Đạt chỉ số chung tốt bằng cách dồn thiệt hại sai số lên nhóm yếu thế.","whyCorrect":"• Dồn sai số tổn hại lên nhóm thiểu số để giữ độ chính xác tổng thể.","whyWrong":{"A":"• Số quyết định không phản ánh thiên vị.","B":"• Mô hình thiên vị không tự cân bằng.","D":"• Mắc ít lỗi nhất không đảm bảo phân bố lỗi đều."}}},{"id":19,"task":"sp24_fe","taskLabel":"SP24 FE","num":19,"chooseType":"Choose 1 answer","question":"Which of the following, by itself, qualifies as personally identifiable information (PII)?","options":{"A":"Cookies and session tokens","B":"Passport numbers and social security numbers","C":"Device IDs","D":"Telephone numbers"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Nội dung nào sau đây, bản thân nó đủ điều kiện cấu thành Thông tin định danh cá nhân (PII) trực tiếp?","optionsVi":{"A":"Cookies và session tokens","B":"Số hộ chiếu (Passport numbers) và số an sinh xã hội","C":"ID thiết bị","D":"Số điện thoại (cần kết hợp)"},"answerDisplay":"B. Passport numbers","concept":"• Direct PII: Số hộ chiếu (Passport Number), Số CCCD là các thuộc tính định danh duy nhất của cá nhân do nhà nước cấp.","whyCorrect":"• Số hộ chiếu là thông tin định danh trực tiếp duy nhất xác định danh tính cá nhân.","whyWrong":{"A":"• Cookies là dữ liệu phiên gián tiếp.","C":"• Device ID là mã định danh phần cứng.","D":"• Số điện thoại là PII gián tiếp cần đối chiếu danh bạ."}}},{"id":20,"task":"sp24_fe","taskLabel":"SP24 FE","num":20,"chooseType":"Choose 1 answer","question":"Which of the following, by itself, qualifies as personally identifiable information (PII)?","options":{"A":"System events added to a log","B":"A user's home address","C":"Temperature readings for an office building","D":"A user's customer ID in an online ordering system"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Nội dung nào sau đây, bản thân nó đủ điều kiện cấu thành Thông tin định danh cá nhân (PII)?","optionsVi":{"A":"Nhật ký sự kiện hệ thống","B":"Địa chỉ nhà riêng của người dùng (User's home address)","C":"Nhiệt độ tòa nhà","D":"Mã ID khách hàng"},"answerDisplay":"B. A user's home address","concept":"• Direct PII: Địa chỉ nhà riêng trực tiếp xác định nơi cư trú cá nhân.","whyCorrect":"• Địa chỉ nhà riêng là thông tin định danh vị trí trực tiếp.","whyWrong":{"A":"• Log là dữ liệu an ninh.","C":"• Nhiệt độ là dữ liệu môi trường.","D":"• Customer ID cần bảng ánh xạ nội bộ."}}},{"id":21,"task":"sp24_fe","taskLabel":"SP24 FE","num":21,"chooseType":"Choose 1 answer","question":"What is the primary advantage of radioactive data tracing over past techniques?","options":{"A":"Radioactive data tracing can modify labels","B":"Radioactive data tracing doesn't impact a model's performance","C":"Radioactive data tracing targets language input","D":"Radioactive data tracing makes modifications perceptible"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Ưu điểm chính của kỹ thuật truy vết dữ liệu phóng xạ (Radioactive data tracing) so với các kỹ thuật trước đây là gì?","optionsVi":{"A":"Sửa đổi nhãn dữ liệu","B":"Không làm ảnh hưởng hay suy giảm hiệu suất tổng thể của mô hình (doesn't impact model's performance)","C":"Nhắm vào đầu vào ngôn ngữ","D":"Làm sửa đổi hiển thị rõ với con người"},"answerDisplay":"B. Radioactive data tracing doesnt impact a model's performance.","concept":"• Radioactive Data Tracing: Đánh dấu bản quyền dữ liệu huấn luyện mà không làm giảm độ chính xác mô hình.","whyCorrect":"• Duy trì nguyên vẹn hiệu suất mô hình là ưu thế kỹ thuật cốt lõi.","whyWrong":{"A":"• Mục tiêu không phải sửa nhãn.","C":"• Áp dụng cho nhiều dạng dữ liệu.","D":"• Vết nước phóng xạ tinh vi không nhận biết bằng mắt thường."}}},{"id":22,"task":"sp24_fe","taskLabel":"SP24 FE","num":22,"chooseType":"Choose 1 answer","question":"The nature of a machine learning model's output is primarily determined by:","options":{"A":"The researchers behind it","B":"The algorithm's architecture","C":"The quality and distribution of data it is trained on","D":"The ethics of individual inputs"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Bản chất đầu ra dự đoán của một mô hình học máy chủ yếu bị quyết định bởi yếu tố nào?","optionsVi":{"A":"Các nhà nghiên cứu đằng sau","B":"Kiến trúc thuật toán","C":"Chất lượng và sự phân bố của tập dữ liệu mà nó được huấn luyện (data it is trained on - Garbage In, Garbage Out)","D":"Đạo đức của các đầu vào cá nhân"},"answerDisplay":"C. the data it is trained on","concept":"• Nguyên lý GIGO (Garbage In, Garbage Out): Kết quả của mô hình phụ thuộc trực tiếp vào dữ liệu huấn luyện đầu vào.","whyCorrect":"• Dữ liệu huấn luyện quy định toàn bộ tri thức và xu hướng dự đoán của mô hình.","whyWrong":{"A":"• Nhà nghiên cứu chọn mô hình chứ không tự quyết định các trọng số.","B":"• Thuật toán chỉ là khung tính toán.","D":"• Đạo đức đầu vào đơn lẻ không quyết định phân bố tổng thể."}}},{"id":23,"task":"sp24_fe","taskLabel":"SP24 FE","num":23,"chooseType":"Choose 1 answer","question":"Why is it important to consider ethical implications beyond just legal compliance?","options":{"A":"The law often lags behind technological innovation (Pacing Problem)","B":"The law is not always applied consistently","C":"The law is not clear","D":"The law is difficult to understand"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Tại sao việc xem xét các hệ lụy đạo đức vượt ra ngoài việc chỉ tuân thủ pháp luật đơn thuần lại quan trọng?","optionsVi":{"A":"Luật pháp thường đi sau và tụt hậu so với sự phát triển nhanh chóng của công nghệ (law lags behind innovation - Pacing Problem)","B":"Luật không áp dụng nhất quán","C":"Luật không rõ ràng","D":"Luật khó hiểu"},"answerDisplay":"A. The law often lags behind innovation.","concept":"• Vấn đề Tốc độ (The Pacing Problem): Công nghệ phát triển theo cấp số nhân trong khi quy trình lập pháp diễn ra chậm chạp, tạo ra các khoảng trống pháp lý.","whyCorrect":"• Tốc độ đổi mới công nghệ nhanh hơn tốc độ ban hành luật đòi hỏi tổ chức phải tự chủ động về đạo đức.","whyWrong":{"B":"• Sự áp dụng luật là khâu tư pháp.","C":"• Độ rõ ràng tùy thuộc từng bộ luật.","D":"• Tính phức tạp không phải nguyên nhân chính của khoảng trống pháp lý."}}},{"id":24,"task":"sp24_fe","taskLabel":"SP24 FE","num":24,"chooseType":"Choose 1 answer","question":"Which of the following describe a process of cross-correlation of data? (Select two.)","options":{"A":"Discovering new information via inference","B":"Analysing emotional stimulus","C":"Comparing multiple data points or datasets to identify patterns","D":"Comparing people of different demographic groups"},"answer":"A, C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Những nội dung nào sau đây mô tả quy trình tương quan chéo dữ liệu (Cross-correlation of data)? (Select two)","optionsVi":{"A":"Khám phá thông tin mới thông qua suy luận (Discovering new information via inference)","B":"Phân tích phản ứng cảm xúc","C":"So sánh nhiều điểm dữ liệu hoặc tập dữ liệu với nhau (Comparing multiple data points or sets)","D":"So sánh các nhóm nhân khẩu học"},"answerDisplay":"A. Discovering new information via inference & C. Comparing multiple data points or sets","concept":"• Cross-correlation: So sánh đối chiếu chéo nhiều nguồn dữ liệu để phát hiện ra các quy luật suy luận mới.","whyCorrect":"• Suy luận thông tin mới và so sánh chéo các điểm dữ liệu là 2 đặc trưng của Cross-correlation.","whyWrong":{"B":"• Phân tích cảm xúc là Sentiment analysis.","D":"• So sánh nhân khẩu học là Demographic analysis."}}},{"id":25,"task":"sp24_fe","taskLabel":"SP24 FE","num":25,"chooseType":"Choose 1 answer","question":"What is the purpose of change management in adopting ethical frameworks?","options":{"A":"To create a fast transition through training","B":"To create a management transition","C":"To create a smooth, supported transition for individuals and organizations fostering an ethical culture","D":"To create a slow transition"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Mục đích của Quản lý sự thay đổi (Change management) trong việc áp dụng các khung đạo đức là gì?","optionsVi":{"A":"Tạo ra sự chuyển đổi nhanh","B":"Tạo ra sự chuyển đổi quản lý","C":"Tạo ra sự chuyển đổi mượt mà và được hỗ trợ cho cá nhân và tổ chức trong việc nuôi dưỡng văn hóa đạo đức (smooth transition in fostering ethical culture)","D":"Tạo ra sự chuyển đổi chậm"},"answerDisplay":"C. To create a smooth transition.","concept":"• Change Management Purpose: Đảm bảo quá trình chuyển đổi văn hóa tổ chức diễn ra thuận lợi, giảm bớt kháng cự nội bộ.","whyCorrect":"• Hỗ trợ sự chuyển đổi văn hóa mượt mà và giảm thiểu rủi ro xung đột.","whyWrong":{"A":"• Tốc độ nhanh không phải mục tiêu tối thượng.","B":"• Quản lý chuyển đổi bao gồm toàn bộ nhân viên.","D":"• Chuyển đổi chậm là hệ quả chứ không phải mục đích."}}},{"id":26,"task":"sp24_fe","taskLabel":"SP24 FE","num":26,"chooseType":"Choose 1 answer","question":"How could an Ethics Board be an example of ethics washing?","options":{"A":"If it has a wide variety of stakeholders","B":"If it has a narrow list of values to guide decisions","C":"If it has no power to institute change or enforce decisions","D":"If it has a large number of stakeholders"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Làm thế nào một Hội đồng Đạo đức có thể trở thành ví dụ về 'Ethics washing'?","optionsVi":{"A":"Nếu có nhiều bên liên quan","B":"Nếu có danh sách giá trị hẹp","C":"Nếu hội đồng không có thực quyền để thực thi thay đổi hoặc cưỡng chế quyết định (has no power to institute change)","D":"Nếu có quá đông thành viên"},"answerDisplay":"C. If it has no power to institute change","concept":"• Ethics Washing via Ethics Board: Thành lập hội đồng bề nổi quảng bá nhưng không trao thực quyền thay đổi.","whyCorrect":"• Tước bỏ thực quyền thay đổi là hình thức Ethics Washing điển hình.","whyWrong":{"A":"• Đa dạng bên liên quan là tính chất tích cực.","B":"• Danh sách giá trị hẹp là vấn đề phạm vi.","D":"• Đông thành viên không quyết định việc tẩy trắng."}}},{"id":27,"task":"sp24_fe","taskLabel":"SP24 FE","num":27,"chooseType":"Choose 1 answer","question":"One way to counter automation bias in decision-making systems is by:","options":{"A":"Changing the datasets","B":"Improving model transparency, explainability, and training humans to critically question automated recommendations","C":"Banning model updates","D":"Limiting precise outputs"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Một cách để chống lại Định kiến tự động hóa (Automation bias) trong các hệ thống ra quyết định là gì?","optionsVi":{"A":"Thay đổi tập dữ liệu","B":"Cải thiện tính minh bạch, tính giải thích được của mô hình và đào tạo con người biết nghi ngờ/đánh giá phản biện các gợi ý tự động (improving model transparency)","C":"Cấm cập nhật mô hình","D":"Giới hạn đầu ra chính xác"},"answerDisplay":"B. improving model transparency","concept":"• Chống Automation Bias: Nâng cao tính giải thích được của mô hình và rèn luyện tư duy phản biện cho con người giám sát (Human-in-the-loop).","whyCorrect":"• Tính minh bạch giúp con người hiểu lý do và không nhắm mắt tin theo máy tính.","whyWrong":{"A":"• Thay dữ liệu không sửa được thói quen tin tưởng mù quáng của con người.","C":"• Cấm cập nhật làm mô hình bị lỗi thời.","D":"• Giới hạn độ chính xác làm giảm chất lượng sản phẩm."}}},{"id":28,"task":"sp24_fe","taskLabel":"SP24 FE","num":28,"chooseType":"Choose 1 answer","question":"A type of artificial intelligence that outperforms humans in specific defined tasks is known as:","options":{"A":"General AI","B":"Narrow AI","C":"AEI","D":"Special AI"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Loại trí tuệ nhân tạo vượt trội hơn con người trong một số nhiệm vụ cụ thể được gọi là gì?","optionsVi":{"A":"AI tổng quát (General AI)","B":"AI hẹp / AI chuyên biệt (Narrow AI)","C":"AEI","D":"AI đặc biệt"},"answerDisplay":"B. Narrow Al","concept":"• Narrow AI: Trí tuệ nhân tạo chuyên biệt một tác vụ duy nhất.","whyCorrect":"• Định nghĩa chuẩn mực của Narrow AI.","whyWrong":{"A":"• General AI có năng lực đa nhiệm như con người.","C":"• AEI không phải thuật ngữ AI tiêu chuẩn.","D":"• Special AI không phải thuật ngữ học thuật."}}},{"id":29,"task":"sp24_fe","taskLabel":"SP24 FE","num":29,"chooseType":"Choose 1 answer","question":"Which of the following is a key difference between LIME and SHAP explainability techniques?","options":{"A":"LIME supports fewer types of models than SHAP","B":"LIME supports more programming languages","C":"LIME outputs results faster than SHAP due to local linear approximations","D":"LIME is less accurate than SHAP"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Sự khác biệt chính giữa hai kỹ thuật giải thích LIME và SHAP là gì?","optionsVi":{"A":"LIME hỗ trợ ít mô hình hơn SHAP","B":"LIME hỗ trợ nhiều ngôn ngữ lập trình hơn","C":"LIME xuất kết quả nhanh hơn SHAP nhờ sử dụng xấp xỉ tuyến tính cục bộ (LIME outputs results faster than SHAP)","D":"LIME kém chính xác hơn SHAP"},"answerDisplay":"C. LIME outputs results faster than SHAP","concept":"• LIME vs SHAP: LIME nhanh hơn về tốc độ tính toán (Faster computation) nhờ mô hình xấp xỉ cục bộ, trong khi SHAP tính toán lâu hơn do phải xét mọi tổ hợp Shapley values.","whyCorrect":"• Tốc độ tính toán nhanh hơn là ưu thế chính của LIME so với SHAP.","whyWrong":{"A":"• Cả hai đều là Model-Agnostic hỗ trợ mọi mô hình.","B":"• Cả hai đều phổ biến trên Python/R.","D":"• Độ chính xác giải thích thuộc về phạm vi đánh giá khác nhau."}}},{"id":30,"task":"sp24_fe","taskLabel":"SP24 FE","num":30,"chooseType":"Choose 1 answer","question":"Which cognitive bias describes the tendency to search for, interpret, favor, and recall information in a way that confirms one's prior beliefs?","options":{"A":"Confirmation bias","B":"Implicit bias","C":"Temporal bias","D":"Reinforcement bias"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Định kiến nhận thức nào mô tả xu hướng tìm kiếm, giải thích, ưu ái và ghi nhớ thông tin theo cách củng cố các niềm tin sẵn có của một người?","optionsVi":{"A":"Định kiến xác nhận (Confirmation bias)","B":"Định kiến ẩn tàng (Implicit bias)","C":"Định kiến thời gian (Temporal bias)","D":"Định kiến củng cố"},"answerDisplay":"A. Confirmation bias","concept":"• Confirmation Bias (Định kiến xác nhận): Xu hướng tâm lý chỉ thích tiếp nhận các thông tin phù hợp với quan điểm có sẵn của bản thân.","whyCorrect":"• Định nghĩa kinh điển của Định kiến xác nhận (Confirmation bias).","whyWrong":{"B":"• Implicit bias là định kiến vô thức về nhóm xã hội.","C":"• Temporal bias là thiên vị do tính thời điểm dữ liệu.","D":"• Reinforcement bias là hiệu ứng tăng cường."}}},{"id":31,"task":"sp24_fe","taskLabel":"SP24 FE","num":31,"chooseType":"Choose 1 answer","question":"What is ambient intelligence?","options":{"A":"Linked IoT technology collecting home data","B":"Linked IoT conducting government surveillance","C":"Linked IoT technology that is always on and acting to personalize the experience for people within its environment","D":"Linked IoT technology collecting campus data"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Trí tuệ môi trường (Ambient Intelligence) được định nghĩa là gì?","optionsVi":{"A":"Công nghệ IoT thu thập dữ liệu nhà ở","B":"Công nghệ IoT giám sát lén lút","C":"Mạng lưới công nghệ IoT kết nối luôn bật và chủ động tương tác để cá nhân hóa trải nghiệm cho con người trong môi trường sống (always on and acting to personalize experience)","D":"Công nghệ IoT thu thập dữ liệu khuôn viên"},"answerDisplay":"C. Linked IOT technology that always on and acting to personalize the experience for the people within its environment","concept":"• Ambient Intelligence (AmI): Môi trường thông minh tích hợp cảm biến IoT luôn hiện diện nhạy bén.","whyCorrect":"• Tính chất luôn bật và tự động cá nhân hóa môi trường sống cho con người.","whyWrong":{"A":"• Thu thập dữ liệu nhà ở chỉ là Smart Home cơ bản.","B":"• Giám sát lén lút là Mass Surveillance.","D":"• Dữ liệu khuôn viên là Campus IoT."}}},{"id":32,"task":"sp24_fe","taskLabel":"SP24 FE","num":32,"chooseType":"Choose 1 answer","question":"Why is an internal Code of Ethics important for an organization?","options":{"A":"It provides an accountability framework for stakeholders of organization to prevent ethical violations","B":"It helps showcase ethical guidelines to customers","C":"It binds employees in a moral code limiting actions","D":"It helps point towards a document in case of violations"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Tại sao một Bộ quy tắc đạo đức nội bộ (Code of Ethics) lại quan trọng đối với một tổ chức?","optionsVi":{"A":"Nó cung cấp một khung giải trình trách nhiệm cho các bên liên quan nhằm ngăn ngừa các vi phạm đạo đức (provides an accountability framework to prevent ethical violations)","B":"Giúp khoe hướng dẫn đạo đức với khách hàng","C":"Ràng buộc nhân viên hạn chế hành động","D":"Dùng để đổ lỗi khi có sự cố"},"answerDisplay":"A. It provides an accountability framework for stakeholders of the organization to prevent ethical violations.","concept":"• Tầm quan trọng của Code of Ethics: Cung cấp khung trách nhiệm giải trình và chuẩn mực hành vi để chủ động ngăn ngừa vi phạm.","whyCorrect":"• Tạo dựng khung giải trình định hướng hành vi chuẩn mực phòng ngừa rủi ro.","whyWrong":{"B":"• Khoe khoang với khách hàng là mục tiêu tiếp thị PR.","C":"• Ràng buộc hạn chế là góc nhìn tiêu cực.","D":"• Dùng trỏ tay chối bỏ trách nhiệm là hình thức Ethics Washing."}}},{"id":33,"task":"sp24_fe","taskLabel":"SP24 FE","num":33,"chooseType":"Choose 1 answer","question":"Which of the following is a primary internal benefit of establishing a clear Code of Ethics?","options":{"A":"It supports profitable research innovations","B":"It supports accountability and makes expectations explicit","C":"It supports consistency of behavior and unification of organizational culture","D":"It supports sales and marketing results"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Lợi ích nội bộ chính yếu của việc thiết lập một Bộ quy tắc đạo đức rõ ràng là gì?","optionsVi":{"A":"Hỗ trợ phát minh có lợi nhuận","B":"Hỗ trợ tính giải trình","C":"Hỗ trợ tính nhất quán trong hành vi của nhân viên và thống nhất văn hóa tổ chức (supports consistency of behavior and unification of culture)","D":"Hỗ trợ kết quả bán hàng"},"answerDisplay":"C. It supports consistency of behavior and unification of culture_","concept":"• Internal Value of Code of Ethics: Định hình tính nhất quán trong hành vi ứng xử của mọi nhân viên và xây dựng bản sắc văn hóa tổ chức thống nhất.","whyCorrect":"• Đảm bảo sự đồng nhất trong hành vi và gắn kết văn hóa doanh nghiệp.","whyWrong":{"A":"• Lợi nhuận không phải mục tiêu đạo đức.","B":"• Giải trình là một khía cạnh cơ chế.","D":"• Bán hàng thuộc về hoạt động thương mại."}}},{"id":34,"task":"sp24_fe","taskLabel":"SP24 FE","num":34,"chooseType":"Choose 1 answer","question":"How do anonymized datasets fall short of their goal of being anonymous?","options":{"A":"Anonymized datasets can be re-identified by hash key","B":"Anonymized datasets aren't anonymous because fields identify users","C":"Anonymized datasets can be traced back by browsing history","D":"Anonymized datasets can be combined with auxiliary datasets to re-identify individuals (Linkage attack)"},"answer":"D","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Tại sao các tập dữ liệu ẩn danh vẫn thất bại trong việc đạt mục tiêu riêng tư của chúng?","optionsVi":{"A":"Re-identify bằng hash key","B":"Các trường định danh người dùng","C":"Truy ngược qua lịch sử duyệt web","D":"Dữ liệu ẩn danh có thể bị liên kết kết hợp với các tập dữ liệu phụ trợ bên ngoài để tái định danh cá nhân (combined with other datasets to re-identify)"},"answerDisplay":"D. Anonymized datasets can be combined with other datasets, which can re-identify individuals","concept":"• Linkage Attack: Kết hợp tập dữ liệu ẩn danh với tập dữ liệu công khai ngoài làm vô hiệu hóa giải pháp ẩn danh sơ sài.","whyCorrect":"• Tái định danh danh tính qua liên kết tập dữ liệu bên ngoài là hạn chế cốt lõi.","whyWrong":{"A":"• Mã hóa băm hash không thể giải mã nếu không có khóa bí mật.","B":"• Ẩn danh hóa đã xóa các trường định danh trực tiếp.","C":"• Lịch sử duyệt web là một tập dữ liệu riêng biệt."}}},{"id":35,"task":"sp24_fe","taskLabel":"SP24 FE","num":35,"chooseType":"Choose 1 answer","question":"Which of the following roles is primarily responsible for establishing ethical guidelines and governance policy within a tech company?","options":{"A":"Business managers and executive leadership","B":"Developers","C":"Regulators","D":"Designers"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Vai trò nào chịu trách nhiệm chính trong việc thiết lập các hướng dẫn đạo đức và chính sách quản trị trong một công ty công nghệ?","optionsVi":{"A":"Các nhà quản lý kinh doanh và ban lãnh đạo điều hành (Business managers and executive leadership)","B":"Các lập trình viên (Developers)","C":"Các cơ quan quản lý (Regulators)","D":"Các nhà thiết kế (Designers)"},"answerDisplay":"A. Business managers","concept":"• Leadership Responsibility: Ban quản lý doanh nghiệp và Lãnh đạo cấp cao chịu trách nhiệm ban hành khung quản trị và hướng dẫn đạo đức cho công ty.","whyCorrect":"• Ban quản lý chịu trách nhiệm thiết lập các chính sách quản trị cấp tổ chức.","whyWrong":{"B":"• Developers thực thi mã nguồn.","C":"• Regulators ban hành luật pháp nhà nước.","D":"• Designers thiết kế giao diện sản phẩm."}}},{"id":36,"task":"sp24_fe","taskLabel":"SP24 FE","num":36,"chooseType":"Choose 1 answer","question":"SSL, TLS, and SSH are all forms of:","options":{"A":"Computer forensics tools","B":"Media codecs","C":"Encryption protocols","D":"Version control systems"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"SSL, TLS và SSH đều là các hình thức của:","optionsVi":{"A":"Công cụ điều tra số","B":"Bộ mã hóa đa phương tiện","C":"Các giao thức mã hóa an toàn (Encryption protocols)","D":"Hệ thống quản lý phiên bản"},"answerDisplay":"C. Encryption protocols","concept":"• Giao thức mã hóa an ninh mạng tiêu chuẩn SSL, TLS và SSH.","whyCorrect":"• SSL, TLS và SSH là các giao thức mã hóa mạng.","whyWrong":{"A":"• Công cụ điều tra số là EnCase.","B":"• Media codecs là H.264.","D":"• Version control là Git."}}},{"id":37,"task":"sp24_fe","taskLabel":"SP24 FE","num":37,"chooseType":"Choose 1 answer","question":"Which of the following is an adequate definition of a stakeholder?","options":{"A":"All internal employees only","B":"All internal employees and external customers","C":"All people who have an impact on or are impacted by the organization","D":"All people in the company"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Nội dung nào sau đây là định nghĩa đầy đủ về Bên liên quan (Stakeholder)?","optionsVi":{"A":"Toàn bộ nhân viên nội bộ","B":"Nhân viên và khách hàng","C":"Tất cả những người có tác động hoặc chịu tác động bởi tổ chức (impact on or impacted by the organization)","D":"Toàn bộ người trong công ty"},"answerDisplay":"C. All people who have an impact or are impacted by the organization","concept":"• Stakeholder bao gồm bất kỳ cá nhân hay nhóm nào có thể gây ảnh hưởng hoặc chịu ảnh hưởng bởi tổ chức.","whyCorrect":"• Bao quát cả chiều tác động hai hướng.","whyWrong":{"A":"• Chỉ nhân viên là định nghĩa hẹp.","B":"• Bỏ qua cơ quan quản lý và cộng đồng.","D":"• Chỉ người trong công ty bỏ qua thực thể bên ngoài."}}},{"id":38,"task":"sp24_fe","taskLabel":"SP24 FE","num":38,"chooseType":"Choose 1 answer","question":"How can AI be designed to uphold justice in legal applications?","options":{"A":"The more AI products used, the more justice is upheld","B":"AI systems can be designed from the start to help promote fairness and minimize bias","C":"AI systems can replace human judges completely","D":"AI can automate clerical tasks"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Làm thế nào AI có thể được thiết kế để duy trì công lý trong các ứng dụng pháp lý?","optionsVi":{"A":"Dùng càng nhiều AI càng tốt","B":"Các hệ thống AI có thể được thiết kế ngay từ đầu để thúc đẩy sự công bằng và giảm thiểu thiên vị (designed from the start to promote fairness and minimize bias)","C":"AI có thể thay thế hoàn toàn thẩm phán con người","D":"AI tự động hóa công việc văn phòng"},"answerDisplay":"B. Al systems can be designed from the start to help promote fairness and minimize bias.","concept":"• Responsible AI by Design: Chủ động tích hợp tiêu chuẩn công bằng và giảm thiên vị ngay từ giai đoạn thiết kế hệ thống.","whyCorrect":"• Thiết kế chủ động hướng tới công bằng và giảm thiên vị ngay từ đầu là giải pháp bền vững.","whyWrong":{"A":"• Số lượng sản phẩm không đảm bảo chất lượng đạo đức.","C":"• AI không được phép thay thế hoàn toàn thẩm phán con người.","D":"• Tự động hóa văn phòng không tự sinh ra tính công lý."}}},{"id":39,"task":"sp24_fe","taskLabel":"SP24 FE","num":39,"chooseType":"Choose 1 answer","question":"Which of the following is an effective approach to promoting corporate ethical values in media communications?","options":{"A":"Promote an organizational culture that embraces these values throughout the company","B":"Ensure multiple groups communicate differently based on race","C":"Focus on intended message without incorporating feedback","D":"Reassure customers with superficial PR statements"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Cách tiếp cận hiệu quả nào để quảng bá các giá trị đạo đức doanh nghiệp trong truyền thông là gì?","optionsVi":{"A":"Thúc đẩy một văn hóa tổ chức thực sự đón nhận và sống theo các giá trị đó (Promote an organizational culture that embraces these values)","B":"Đảm bảo phân nhóm truyền thông theo chủng tộc","C":"Bỏ qua phản hồi từ bên ngoài","D":"Trấn an khách hàng bằng tuyên bố PR bề nổi"},"answerDisplay":"A. Promote an organizational culture that embraces these values","concept":"• Authentic Ethical Communication: Truyền thông uy tín bắt nguồn từ văn hóa tổ chức thực chất được toàn bộ doanh nghiệp đón nhận.","whyCorrect":"• Thúc đẩy văn hóa tổ chức thực chất là nền tảng cho mọi truyền thông đạo đức chân thực.","whyWrong":{"B":"• Phân biệt truyền thông theo chủng tộc là phi đạo đức.","C":"• Bỏ qua phản hồi gây ra sự ngạo mạn truyền thông.","D":"• Trấn an bề nổi là Ethics Washing."}}},{"id":40,"task":"sp24_fe","taskLabel":"SP24 FE","num":40,"chooseType":"Choose 1 answer","question":"Why are deep learning models often referred to as black boxes compared to decision trees?","options":{"A":"Narrow AI can only perform specific tasks","B":"Deep learning models have millions of parameters making internal reasoning difficult to interpret","C":"Narrow AI is dependent on hand-coding","D":"Decision trees use more data"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Tại sao các mô hình học sâu (Deep learning) thường được gọi là các Hộp đen (Black boxes) so với Cây quyết định (Decision trees)?","optionsVi":{"A":"AI hẹp chỉ thực hiện nhiệm vụ cụ thể","B":"Mô hình học sâu chứa hàng triệu trọng số tham số phức tạp khiến lập luận nội tại rất khó để diễn giải (millions of parameters making internal reasoning difficult to interpret)","C":"AI hẹp phụ thuộc vào lập trình thủ công","D":"Cây quyết định dùng nhiều dữ liệu hơn"},"answerDisplay":"B. Deep learning models have complex internal architectures that are difficult to interpret.","concept":"• Deep Learning Complexity: Mạng nơ-ron sâu với nhiều tầng ẩn (Hidden layers) và hàng triệu tham số tạo nên bài toán Hộp đen.","whyCorrect":"• Độ phức tạp kiến trúc và số lượng tham số khổng lồ ngăn cản khả năng diễn giải logic.","whyWrong":{"A":"• Phạm vi tác vụ không giải thích lý do hộp đen.","C":"• Học sâu tự động trích xuất đặc trưng chứ không lập trình thủ công.","D":"• Cây quyết định dễ giải thích nhờ các quy tắc If-Then trực quan."}}},{"id":41,"task":"sp24_fe","taskLabel":"SP24 FE","num":41,"chooseType":"Choose 1 answer","question":"When building a predictive model, what is the goal of the development phase?","options":{"A":"To plug in 40% dataset","B":"To get the model's error function below an acceptable percentage threshold","C":"To specify algorithm and clean data","D":"To train continuously without stopping"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Khi xây dựng một mô hình dự đoán, mục tiêu của giai đoạn phát triển (Development phase) là gì?","optionsVi":{"A":"Nạp 40% dữ liệu","B":"Đưa hàm sai số (Error function) của mô hình xuống dưới mức ngưỡng chấp nhận được (get error function below acceptable percentage)","C":"Chỉ định thuật toán và làm sạch dữ liệu","D":"Huấn luyện liên tục không dừng"},"answerDisplay":"B. To get the model's error function belowr an acceptable percentage","concept":"• Tối ưu hóa trong phát triển ML: Giảm tổn thất (Loss) xuống ngưỡng chấp nhận được.","whyCorrect":"• Hạ hàm sai số xuống mức tối ưu chấp nhận được là tiêu chuẩn hoàn thành pha phát triển.","whyWrong":{"A":"• 40% là chỉ số chia dữ liệu.","C":"• Làm sạch là khâu tiền xử lý.","D":"• Huấn luyện không dừng gây overfitting."}}},{"id":42,"task":"sp24_fe","taskLabel":"SP24 FE","num":42,"chooseType":"Choose 1 answer","question":"How can you leverage emerging technologies like AI in disaster recovery plans (DRP)?","options":{"A":"By using data-driven techniques to inform and optimize strategies behind DRP","B":"By using NLP to ensure DRP document is free of typos","C":"By using deep learning to bolster defense against disasters","D":"By using AI to decide if DRP is necessary"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Làm thế nào bạn có thể tận dụng các công nghệ mới nổi như AI trong các kế hoạch khôi phục sau thảm họa (DRP)?","optionsVi":{"A":"Bằng cách sử dụng các kỹ thuật dựa trên dữ liệu để cung cấp thông tin và tối ưu hóa các chiến lược đằng sau DRP (using data-driven techniques to inform DRP strategies)","B":"Dùng NLP sửa lỗi chính tả","C":"Dùng học sâu ngăn thảm họa","D":"Dùng AI quyết định có cần DRP không"},"answerDisplay":"A. By using data-driven techniques to inform the strategies behind the DRP.","concept":"• AI-augmented DRP: Sử dụng phân tích dự báo dữ liệu để mô phỏng kịch bản thảm họa và tối ưu hóa chiến lược khôi phục.","whyCorrect":"• Phân tích dữ liệu giúp hoạch định chiến lược khôi phục hạ tầng thông minh hơn.","whyWrong":{"B":"• Sửa lỗi chính tả không có giá trị khôi phục thảm họa.","C":"• Học sâu không ngăn được thảm họa tự nhiên.","D":"• DRP là bắt buộc tối thiểu đối với doanh nghiệp."}}},{"id":43,"task":"sp24_fe","taskLabel":"SP24 FE","num":43,"chooseType":"Choose 1 answer","question":"The Data minimization principle requires that you limit data collection to only what is:","options":{"A":"Necessary for differential privacy","B":"Optional for a chain of command","C":"Needed to have k-anonymity","D":"Directly required to fulfill a specific, stated purpose"},"answer":"D","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Nguyên tắc Giảm thiểu dữ liệu (Data minimization) yêu cầu bạn giới hạn việc thu thập dữ liệu chỉ trong phạm vi những gì:","optionsVi":{"A":"Cần thiết cho riêng tư vi sai","B":"Tùy chọn cho chuỗi chỉ huy","C":"Cần thiết để có k-anonymity","D":"Trực tiếp cần thiết để thực hiện một mục đích cụ thể đã xác định (required to fulfill a specific purpose)"},"answerDisplay":"D. required to fulfill a specific purpose","concept":"• Data Minimization Principle: Chỉ thu thập đúng và đủ lượng dữ liệu cần thiết cho mục đích chính đáng đã công bố.","whyCorrect":"• Giới hạn thu thập đúng mục đích sử dụng là định nghĩa cốt lõi của Data Minimization.","whyWrong":{"A":"• Differential privacy là kỹ thuật toán học.","B":"• Chuỗi chỉ huy thuộc về cấu trúc tổ chức.","C":"• k-anonymity là mô hình ẩn danh dữ liệu."}}},{"id":44,"task":"sp24_fe","taskLabel":"SP24 FE","num":44,"chooseType":"Choose 1 answer","question":"In Game Theory applied to ethics, outcomes that are best for the group can be obscured by outcomes best for:","options":{"A":"The dataset, the model","B":"The group, the dataset","C":"The individual (Nash Equilibrium vs Pareto Efficiency)","D":"The model, the individual"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Trong Lý thuyết Trò chơi (Game Theory) áp dụng cho đạo đức, các kết quả tốt nhất cho tập thể (Group) có thể bị che lấp bởi các kết quả tốt nhất cho:","optionsVi":{"A":"Tập dữ liệu, mô hình","B":"Nhóm, tập dữ liệu","C":"Tự lợi cá nhân đơn lẻ (The individual - Nghịch lý tù nhân / Cân bằng Nash)","D":"Mô hình, cá nhân"},"answerDisplay":"C. the group, the individual","concept":"• Game Theory & Prisoner's Dilemma: Khi từng cá nhân theo đuổi lợi ích tối đa cho bản thân (Individual), họ tạo ra kết quả tệ hơn cho toàn thể cộng đồng (Group).","whyCorrect":"• Sự xung đột giữa lợi ích tự lợi cá nhân ngắn hạn và lợi ích tập thể dài hạn.","whyWrong":{"A":"• Tập dữ liệu không phải tác thể trò chơi.","B":"• Tập dữ liệu là thông tin.","D":"• Mô hình không có động cơ cá nhân."}}},{"id":45,"task":"sp24_fe","taskLabel":"SP24 FE","num":45,"chooseType":"Choose 1 answer","question":"The Children's Online Privacy Protection Act (COPPA) safeguards the privacy of personal information for which age group?","options":{"A":"Anyone under 18 years old","B":"Anyone under 13 years old","C":"Anyone between 5 and 13 years old","D":"Anyone between 13 and 18 years old"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Đạo luật bảo vệ quyền riêng tư của trẻ em trên mạng (COPPA) bảo vệ thông tin cá nhân của nhóm tuổi nào?","optionsVi":{"A":"Bất kỳ ai dưới 18 tuổi","B":"Trẻ em dưới 13 tuổi (Anyone under 13 years old)","C":"Từ 5 đến 13 tuổi","D":"Từ 13 đến 18 tuổi"},"answerDisplay":"B. Anyone under 13 years old","concept":"• COPPA (Children's Online Privacy Protection Act): Phạm vi áp dụng nghiêm ngặt bảo vệ dữ liệu cá nhân của trẻ em dưới 13 tuổi.","whyCorrect":"• Dưới 13 tuổi là ngưỡng tuổi định nghĩa trẻ em thuộc phạm vi bảo vệ của luật COPPA.","whyWrong":{"A":"• Dưới 18 tuổi là phạm vi vị thành niên chung (Minors).","C":"• Trẻ em dưới 5 tuổi vẫn được COPPA bảo vệ.","D":"• Từ 13 đến 18 tuổi thuộc phạm vi bảo vệ thiếu niên (Teens)."}}},{"id":46,"task":"sp24_fe","taskLabel":"SP24 FE","num":46,"chooseType":"Choose 1 answer","question":"Which of the following negative consequences is the direct result of failing to be truthful in communicating about a crisis?","options":{"A":"Discrimination","B":"Security risk","C":"Severe reputational damage and catastrophic loss of public trust","D":"Financial loss"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Hậu quả tiêu cực nào sau đây là kết quả trực tiếp của việc thiếu trung thực khi truyền thông về một cuộc khủng hoảng?","optionsVi":{"A":"Phân biệt đối xử","B":"Rủi ro an ninh","C":"Tổn hại nghiêm trọng về uy tín thương hiệu và mất đi niềm tin của công chúng (Reputational damage)","D":"Tổn thất tài chính gián tiếp"},"answerDisplay":"C. Reputational damage","concept":"• Consequences of Dishonesty in Crisis PR: Dối trá về khủng hoảng sẽ hủy hoại hoàn toàn uy tín thương hiệu và lòng tin của khách hàng.","whyCorrect":"• Tổn hại uy tín nghiêm trọng là hậu quả trực tiếp khi bị phát hiện dối trá.","whyWrong":{"A":"• Phân biệt đối xử là vấn đề công bằng.","B":"• Rủi ro an ninh thuộc kỹ thuật hạ tầng.","D":"• Thất thoát tài chính là hậu quả thứ cấp."}}},{"id":47,"task":"sp24_fe","taskLabel":"SP24 FE","num":47,"chooseType":"Choose 1 answer","question":"When building a predictive model, what is the primary goal of the training phase?","options":{"A":"To specify algorithm and clean data","B":"To adjust the model based on a subset of data, optimizing for a lower error rate","C":"To use the model in real-world scenarios","D":"To adjust training methods from backpropagation to supervised learning"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Khi xây dựng một mô hình dự đoán, mục tiêu chính của giai đoạn huấn luyện (Training phase) là gì?","optionsVi":{"A":"Chỉ định thuật toán và làm sạch dữ liệu","B":"Điều chỉnh các trọng số mô hình dựa trên tập dữ liệu huấn luyện, tối ưu hóa để đạt tỷ lệ lỗi sai thấp hơn (adjust model, optimizing for lower error rate)","C":"Sử dụng mô hình trong kịch bản thực tế","D":"Chuyển đổi phương pháp huấn luyện"},"answerDisplay":"B. To adjust the model based on a subset of data, optimizing for a lower error rate","concept":"• Mục tiêu Huấn luyện: Điều chỉnh tham số để hạ thấp hàm sai số.","whyCorrect":"• Tối ưu hóa trọng số mô hình để giảm sai số là bản chất của giai đoạn huấn luyện.","whyWrong":{"A":"• Chọn thuật toán là bước chuẩn bị.","C":"• Sử dụng thực tế là pha triển khai.","D":"• Backpropagation thuộc Supervised Learning."}}},{"id":48,"task":"sp24_fe","taskLabel":"SP24 FE","num":48,"chooseType":"Choose 1 answer","question":"Which expression best characterizes what an organizational or corporate culture is?","options":{"A":"\"This is how we want this done.\"","B":"\"This is how things are done around here.\"","C":"\"It is what it is.\"","D":"\"This is what we're told to do.\""},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Câu nói nào sau đây thể hiện một cách tốt nhất bản chất của Văn hóa doanh nghiệp / Văn hóa tổ chức (Corporate culture)?","optionsVi":{"A":"\"Đây là cách chúng tôi muốn công việc được làm.\"","B":"\"Đây là cách mọi việc được thực hiện ở đây.\" (\"This is how things are done around here.\")","C":"\"Nó là như vậy thôi.\"","D":"\"Đây là những gì chúng tôi được bảo phải làm.\""},"answerDisplay":"B. \"This is how things are done around here.\"","concept":"• Định nghĩa Văn hóa Doanh nghiệp (Corporate Culture): Tập hợp các hành vi, niềm tin và thói quen ứng xử ngầm định hình nên cách thức làm việc thực tế hàng ngày.","whyCorrect":"• Câu châm ngôn kinh điển thể hiện tập quán và thói quen hành vi thực tế của tổ chức.","whyWrong":{"A":"• 'Muốn được làm' thể hiện mong muốn lý thuyết.","C":"• 'Nó là như vậy' thể hiện sự buông xuôi.","D":"• 'Được bảo làm' thể hiện sự tuân thủ quy tắc cưỡng chế."}}},{"id":49,"task":"sp24_fe","taskLabel":"SP24 FE","num":49,"chooseType":"Choose 1 answer","question":"Which of the following are desired qualities when choosing a spokesperson for your organization during a crisis? (Select two.)","options":{"A":"Articulate when communicating important details","B":"Patient when addressing tough questions or concerns","C":"Lighthearted when dealing with serious topics","D":"Defensive when challenged"},"answer":"A, B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Những phẩm chất mong muốn nào sau đây khi lựa chọn một người phát ngôn (Spokesperson) cho tổ chức trong khủng hoảng? (Select two)","optionsVi":{"A":"Ăn nói rõ ràng mạch lạc khi truyền thông các chi tiết quan trọng (Articulate when communicating important details)","B":"Kiên nhẫn khi giải quyết các câu hỏi hóc húa hoặc lo ngại (Patient when addressing tough questions)","C":"Cợt nhả khi bàn về chủ đề nghiêm trọng","D":"Phòng thủ khi bị thách thức"},"answerDisplay":"A. Articulate when communicating important details & B. Patient when addressing tough questions or concerns","concept":"• Phẩm chất Người phát ngôn: Diễn đạt mạch lạc (Articulate) và Kiên nhẫn điềm tĩnh (Patient).","whyCorrect":"• Diễn đạt mạch lạc và kiên nhẫn lắng nghe giúp xây dựng uy tín truyền thông.","whyWrong":{"C":"• Cợt nhả gây phẫn nộ dư luận.","D":"• Phản ứng phòng thủ phá hủy lòng tin."}}},{"id":50,"task":"sp24_fe","taskLabel":"SP24 FE","num":50,"chooseType":"Choose 1 answer","question":"Which type of model is often preferred by businesses because it offers clear, human-understandable reasoning?","options":{"A":"Black box model","B":"Precise model","C":"Fair and explainable model (White box / Explainable model)","D":"Ethical model"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Loại mô hình nào thường được các doanh nghiệp ưu tiên lựa chọn vì nó cung cấp lập luận rõ ràng, dễ hiểu cho con người?","optionsVi":{"A":"Mô hình hộp đen (Black box)","B":"Mô hình chính xác tuyệt đối","C":"Mô hình công bằng và giải thích được (Explainable / White box model)","D":"Mô hình đạo đức"},"answerDisplay":"C. Explainable model","concept":"• Explainable Model vs Black Box: Doanh nghiệp ưu tiên mô hình giải thích được (White Box) để dễ kiểm toán, tuân thủ pháp lý và xây dựng lòng tin.","whyCorrect":"• Khả năng cung cấp lập luận minh bạch dễ hiểu cho con người là lý do mô hình giải thích được được ưu chuộng.","whyWrong":{"A":"• Mô hình hộp đen khó giải thích gây rủi ro kiểm toán.","B":"• Mô hình chính xác nhưng nếu là Hộp đen vẫn bị e ngại.","D":"• Mô hình đạo đức là định hướng chung."}}},{"id":51,"task":"sp24_fe","taskLabel":"SP24 FE","num":51,"chooseType":"Choose 1 answer","question":"When you deliver periodic statements about a crisis to the media, what should the first statement do?","options":{"A":"Provide in-depth details about the situation","B":"Survey public opinion","C":"Set the tone of what is to follow, acknowledge the event, and outline initial actions being taken","D":"Accept full responsibility immediately without verification"},"answer":"C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Khi bạn đưa ra các phát biểu định kỳ về một cuộc khủng hoảng cho báo chí, phát biểu đầu tiên (Holding statement) cần phải làm gì?","optionsVi":{"A":"Cung cấp chi tiết chuyên sâu về tình hình","B":"Khảo sát ý kiến công chúng","C":"Thiết lập tông giọng truyền thông, xác nhận sự cố và phác thảo các hành động ban đầu đang được thực hiện (Set the tone of what is to follow)","D":"Nhận trách nhiệm hoàn toàn ngay lập tức khi chưa kiểm chứng"},"answerDisplay":"C. Set the tone of what is to follow","concept":"• First Crisis Statement (Holding Statement): Nhằm định hình tông giọng truyền thông (Set the tone), thể hiện thái độ nghiêm túc và trấn an dư luận.","whyCorrect":"• Thiết lập định hướng truyền thông và xác nhận thái độ tiếp nhận sự cố nghiêm túc của doanh nghiệp.","whyWrong":{"A":"• Phát biểu đầu tiên chưa có đủ chi tiết chuyên sâu.","B":"• Chưa thể khảo sát dư luận ngay lập tức.","D":"• Nhận trách nhiệm vội vàng khi chưa rõ nguyên nhân gây thiệt hại pháp lý."}}},{"id":52,"task":"sp24_fe","taskLabel":"SP24 FE","num":52,"chooseType":"Choose 1 answer","question":"You plan on streamlining your company's product experience while upholding the agency and autonomy of users. Which actions uphold these principles? (Select two.)","options":{"A":"Applying machine intelligence to simulate customer behavior","B":"Respecting the right of the user to choose and customize their experiences","C":"Refraining from dark patterns that guide users into choices they didn't wish for or intend","D":"Enabling government agencies to customize interface"},"answer":"B, C","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Bạn dự định tối ưu hóa trải nghiệm sản phẩm nhưng vẫn tôn trọng quyền tự quyết (Agency) và sự tự chủ (Autonomy) của người dùng. Những hành động nào tôn trọng các nguyên tắc này? (Select two)","optionsVi":{"A":"Mô phỏng hành vi người dùng","B":"Tôn trọng quyền của người dùng trong việc lựa chọn và tùy chỉnh trải nghiệm của họ (Respecting right of user to choose and customize)","C":"Tránh các mẫu thiết kế thao túng (Dark patterns) dẫn dắt người dùng vào những lựa chọn ngoài ý muốn (Refraining from guiding users into unintended choices)","D":"Cho phép cơ quan chính phủ tùy biến giao diện"},"answerDisplay":"B. Respecting the right of the user to choose and customize their experiences & C. Reframing from guiding users into something they didn't wish for or intend","concept":"• User Autonomy & Agency: Tránh các mẫu thiết kế thao túng tâm lý (Dark Patterns) và trao quyền tự chọn cài đặt cá nhân cho người dùng.","whyCorrect":"• Tôn trọng quyền tự chọn tùy chỉnh và loại bỏ Dark Patterns giúp bảo vệ quyền tự quyết của người dùng.","whyWrong":{"A":"• Mô phỏng hành vi không trao quyền kiểm soát cho người dùng.","D":"• Cơ quan chính phủ không liên quan đến quyền tự chủ người dùng."}}},{"id":53,"task":"sp24_fe","taskLabel":"SP24 FE","num":53,"chooseType":"Choose 1 answer","question":"Which of the following can help mitigate unwillingness to accept feedback?","options":{"A":"Engage in cultural awareness","B":"Create and participate in a risk culture of open feedback","C":"Communicate the importance of feedback in refining a product","D":"Communicate regularly about culture values"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Nội dung nào sau đây có thể giúp giảm thiểu thái độ e ngại/miễn cưỡng khi tiếp nhận phản hồi?","optionsVi":{"A":"Tham gia nhận thức văn hóa","B":"Xây dựng và tham gia vào một văn hóa rủi ro mở lắng nghe phản hồi (Create and participate in a risk culture)","C":"Truyền thông tầm quan trọng của phản hồi","D":"Truyền thông định kỳ về giá trị"},"answerDisplay":"B. Create and participate in a risk culture.","concept":"• Risk Culture: Tạo môi trường an toàn về mặt tâm lý để nhân viên tự do đóng góp và nhận phản hồi.","whyCorrect":"• Xây dựng văn hóa rủi ro mở thúc đẩy việc tự giác lắng nghe và sửa đổi.","whyWrong":{"A":"• Nhận thức văn hóa là phạm vi rộng.","C":"• Nói lý thuyết suông không xóa được tâm lý e ngại.","D":"• Truyền thông giá trị không tự đổi mới thói quen."}}},{"id":54,"task":"sp24_fe","taskLabel":"SP24 FE","num":54,"chooseType":"Choose 1 answer","question":"Which of the following describes the primary purpose of a Business Impact Assessment (BIA)?","options":{"A":"It helps you predict business interruptions and develop recovery strategies","B":"It helps you identify what risks you can accept or transfer to third party","C":"It helps you evaluate how a product could fail to apply ethical values","D":"It helps you identify risks you can transfer to customers"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả đúng mục đích chính của Đánh giá Tác động Kinh doanh (Business Impact Assessment - BIA)?","optionsVi":{"A":"Giúp bạn dự đoán các gián đoạn kinh doanh và phát triển các chiến lược khôi phục tương ứng (predict business interruptions and develop recovery strategies)","B":"Xác định rủi ro chuyển giao cho bên thứ ba","C":"Đánh giá thất bại áp dụng đạo đức","D":"Xác định rủi ro chuyển cho khách hàng"},"answerDisplay":"A. It helps you predict business interruptions and develop recovery strategies.","concept":"• BIA Purpose: Phân tích các hậu quả khi hoạt động kinh doanh bị gián đoạn và lập kế hoạch chiến lược khôi phục (DRP/BCP).","whyCorrect":"• Dự đoán gián đoạn vận hành và xây dựng chiến lược khôi phục là bản chất của BIA.","whyWrong":{"B":"• Chuyển giao rủi ro thuộc về Risk Treatment.","C":"• Đánh giá đạo đức là Ethical Impact Assessment.","D":"• Chuyển rủi ro cho khách hàng là phi đạo đức."}}},{"id":55,"task":"sp24_fe","taskLabel":"SP24 FE","num":55,"chooseType":"Choose 1 answer","question":"Dating algorithms become biased mostly through offering users:","options":{"A":"Collaborative filtering that reinforces existing stereotypes","B":"Access to separate data models","C":"Different ways to match","D":"Unlimited matches per day"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Các thuật toán hẹn hò trở nên bị thiên vị chủ yếu thông qua việc cung cấp cho người dùng tính năng gì?","optionsVi":{"A":"Lọc cộng tác (Collaborative filtering) củng cố định kiến sẵn có","B":"Truy cập mô hình dữ liệu riêng","C":"Các cách ghép đôi khác nhau","D":"Không giới hạn lượt ghép đôi"},"answerDisplay":"A. collaborative filtering","concept":"• Collaborative Filtering Bias: Tự động nhân rộng các thiên vị dựa trên hành vi quẹt thẻ của số đông.","whyCorrect":"• Lọc cộng tác củng cố các định kiến xã hội vốn có.","whyWrong":{"B":"• Mô hình riêng là kiến trúc hệ thống.","C":"• Cách match là giao diện người dùng.","D":"• Lượt match không sinh thiên vị nhóm."}}},{"id":56,"task":"sp24_fe","taskLabel":"SP24 FE","num":56,"chooseType":"Choose 1 answer","question":"Which of the following accurately describes the measures of central tendency in a perfectly normal distribution?","options":{"A":"The mean is higher than both median and mode","B":"The median is equal to mode, and higher than mean","C":"The mode is higher than mean","D":"The mean, mode, and median are all equal and located at the center of distribution"},"answer":"D","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Nội dung nào sau đây mô tả chính xác các đại lượng đo lường xu hướng trung tâm trong một phân bố chuẩn hoàn hảo (Normal Distribution)?","optionsVi":{"A":"Giá trị trung bình cao hơn trung vị và mốt","B":"Trung vị bằng mốt và cao hơn trung bình","C":"Mốt cao hơn trung bình","D":"Giá trị trung bình (Mean), Mốt (Mode) và Trung vị (Median) đều bằng nhau và nằm tại chính tâm phân bố (Mean, mode and median are the same)"},"answerDisplay":"D. The mean, mode and median are the same.","concept":"• Symmetry of Normal Distribution: Trong Phân bố Chuẩn (Gaussian Curve), Mean = Median = Mode.","whyCorrect":"• Ba chỉ số trung tâm hoàn toàn trùng nhau tại đỉnh đối xứng của phân bố chuẩn.","whyWrong":{"A":"• Mean > Median > Mode là Phân bố lệch phải (Positively Skewed).","B":"• Không phản ánh phân bố chuẩn.","C":"• Phản ánh phân bố lệch."}}},{"id":57,"task":"sp24_fe","taskLabel":"SP24 FE","num":57,"chooseType":"Choose 1 answer","question":"You have collected social media posts with a specific hashtag for an analysis of the words used in the post. What kind of data is that?","options":{"A":"Unstructured data","B":"Structured data","C":"Semi-Structured data","D":"Data Structured"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Bạn đã thu thập các bài đăng trên mạng xã hội theo một hashtag cụ thể để phân tích các từ ngữ sử dụng. Đó là loại dữ liệu nào?","optionsVi":{"A":"Dữ liệu phi cấu trúc (Unstructured data)","B":"Dữ liệu có cấu trúc (Structured data)","C":"Dữ liệu bán cấu trúc","D":"Dữ liệu cấu trúc"},"answerDisplay":"A. Unstructured","concept":"• Unstructured Data (Dữ liệu Phi cấu trúc): Văn bản tự do (Free text), hình ảnh, video không nằm trong các bảng cột hàng định sẵn.","whyCorrect":"• Bài đăng văn bản tự do trên mạng xã hội là hình thức điển hình của Dữ liệu phi cấu trúc.","whyWrong":{"B":"• Structured data nằm trong bảng cơ sở dữ liệu SQL.","C":"• Semi-structured là tệp JSON/XML.","D":"• Data Structured không phải thuật ngữ phân loại."}}},{"id":58,"task":"sp24_fe","taskLabel":"SP24 FE","num":58,"chooseType":"Choose 1 answer","question":"Which of the following are important ethical elements to safeguard within ethical AI systems? (Select two.)","options":{"A":"Accountability and active management of bias","B":"The number of layers, tensors, or parameters","C":"Performance and optimization speed","D":"Transparency and explainability, balanced with privacy protection"},"answer":"A, D","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Những yếu tố đạo đức quan trọng nào cần bảo vệ và duy trì trong các hệ thống AI có trách nhiệm? (Select two)","optionsVi":{"A":"Trách nhiệm giải trình và quản lý chủ động sự thiên vị (Accountability and management of bias)","B":"Số lượng tầng, tensors hoặc tham số","C":"Hiệu suất và tốc độ","D":"Tính minh bạch và giải thích được, cân bằng với bảo vệ quyền riêng tư (Transparency and explainability, balanced with privacy)"},"answerDisplay":"A. Accountability and management of bias & D. Transparency and expiainabiilty, balanced with privacy","concept":"• Trụ cột Đạo đức AI: Accountability, Bias Management, Transparency, Explainability & Privacy.","whyCorrect":"• Trách nhiệm giải trình, kiểm soát thiên vị và minh bạch cân bằng với riêng tư là các nguyên tắc cốt lõi.","whyWrong":{"B":"• Số lượng tham số là chi tiết kỹ thuật kiến trúc.","C":"• Tốc độ hiệu suất là chỉ số tối ưu hóa toán."}}},{"id":59,"task":"sp24_fe","taskLabel":"SP24 FE","num":59,"chooseType":"Choose 1 answer","question":"Why is fair competition an important ethical consideration for data-driven technology businesses?","options":{"A":"Fair competition prevents predatory pricing","B":"Fair competition builds user trust in technology as a whole and prevents market monopolies","C":"Fair competition provides products choice to users","D":"Fair competition provides service choice"},"answer":"B","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Tại sao cạnh tranh công bằng lại là một xem xét đạo đức quan trọng đối với các doanh nghiệp công nghệ dựa trên dữ liệu?","optionsVi":{"A":"Ngăn chặn định giá phá giá","B":"Cạnh tranh công bằng xây dựng niềm tin của người dùng vào toàn bộ nền công nghệ và ngăn chặn độc quyền lũng đoạn (builds user trust in technology as a whole)","C":"Cung cấp sự lựa chọn sản phẩm","D":"Cung cấp sự lựa chọn dịch vụ"},"answerDisplay":"B. Fair competition builds user trust in technology as a whole-","concept":"• Fair Competition & Public Trust: Cạnh tranh lành mạnh ngăn Big Tech thâu tóm độc quyền và củng cố lòng tin của xã hội đối với toàn ngành công nghệ.","whyCorrect":"• Xây dựng niềm tin bền vững của cộng đồng đối với hệ sinh thái công nghệ.","whyWrong":{"A":"• Định giá phá giá chỉ là một kỹ thuật cạnh tranh không lành mạnh.","C":"• Sự lựa chọn là hệ quả thị trường.","D":"• Lựa chọn dịch vụ là khía cạnh người dùng."}}},{"id":60,"task":"sp24_fe","taskLabel":"SP24 FE","num":60,"chooseType":"Choose 1 answer","question":"What's the difference between a basic and a complex learning algorithm?","options":{"A":"A basic algorithm has a set amount of choices to optimize for, while a complex algorithm is given the freedom to discover its own features and model representations","B":"A basic algorithm cannot use computer vision","C":"A basic algorithm cannot process more than 5 steps","D":"A basic algorithm handles numbers, complex handles pictures"},"answer":"A","source":"ITE302c_SP24_FE","explanation":{"questionVi":"Sự khác biệt giữa một thuật toán học máy cơ bản và một thuật toán học máy phức tạp là gì?","optionsVi":{"A":"Thuật toán cơ bản có một số lượng lựa chọn cố định để tối ưu hóa, trong khi thuật toán phức tạp được tự do tự phát hiện các thuộc tính và mô hình đại diện (basic has set choices vs complex given freedom to find own model)","B":"Cơ bản không dùng được thị giác máy tính","C":"Cơ bản không xử lý quá 5 bước","D":"Cơ bản chỉ xử lý số, phức tạp xử lý ảnh"},"answerDisplay":"A. A basic algorithm has a set amount of choices to optimize for, while a complex algorithm is given the freedom to find its own model","concept":"• Basic vs Complex ML (Representation Learning): Thuật toán cơ bản phụ thuộc thuộc tính cố định gán sẵn; Thuật toán phức tạp (Deep Learning) tự học biểu diễn đặc trưng từ dữ liệu thô.","whyCorrect":"• Tự do học và khám phá các biểu diễn đặc trưng là ưu thế của thuật toán phức tạp.","whyWrong":{"B":"• Thuật toán cơ bản như Haar Cascade vẫn dùng trong máy tính thị giác.","C":"• Số bước hàm không quy định mức độ phức tạp thuật toán.","D":"• Thuật toán cơ bản vẫn xử lý mảng điểm ảnh hình ảnh."}}}];
